# ================= LANGUAGE SYSTEM =================
DEFAULT_BOT_LANGUAGE = "my"
LANGUAGE_NAMES = {
    "my": "မြန်မာ",
    "en": "English",
    "th": "ไทย",
    "zh-CN": "中文",
    "hi": "हिन्दी",
}
LANGUAGE_BUTTONS = [
    ("my", "🇲🇲 မြန်မာ"),
    ("en", "🇬🇧 English"),
    ("th", "🇹🇭 ไทย"),
    ("zh-CN", "🇨🇳 中文"),
    ("hi", "🇮🇳 हिन्दी"),
]
TRANSLATION_CACHE: dict[tuple[str, str], str] = {}

def _normalize_lang_code(lang_code: str | None) -> str:
    if not lang_code:
        return DEFAULT_BOT_LANGUAGE
    lang_code = str(lang_code).strip()
    if lang_code in LANGUAGE_NAMES:
        return lang_code
    lowered = lang_code.lower()
    alias_map = {
        "mm": "my", "burmese": "my", "myanmar": "my",
        "english": "en", "eng": "en",
        "thai": "th",
        "chinese": "zh-CN", "zh": "zh-CN", "cn": "zh-CN",
        "india": "hi", "indian": "hi", "hindi": "hi",
    }
    return alias_map.get(lowered, DEFAULT_BOT_LANGUAGE)

def _language_display_name(lang_code: str | None) -> str:
    return LANGUAGE_NAMES.get(_normalize_lang_code(lang_code), LANGUAGE_NAMES[DEFAULT_BOT_LANGUAGE])

def _safe_chat_language(chat_id=None) -> str:
    try:
        if chat_id is not None:
            langs = bot.settings.get('chat_languages', {})
            return _normalize_lang_code(langs.get(str(chat_id), DEFAULT_BOT_LANGUAGE))
    except Exception:
        pass
    return DEFAULT_BOT_LANGUAGE

def _set_chat_language(chat_id, user_id, lang_code: str) -> str:
    chosen = _normalize_lang_code(lang_code)
    bot.settings.setdefault('chat_languages', {})
    if chat_id is not None:
        bot.settings['chat_languages'][str(chat_id)] = chosen
    bot.data.setdefault('user_profiles', {})
    if user_id is not None:
        bot.data['user_profiles'].setdefault(str(user_id), {})['language'] = chosen
    try:
        bot.save_settings()
        bot.save_data()
    except Exception as e:
        logger.warning(f"language save warning: {e}")
    return chosen

def _split_translate_chunks(text: str, chunk_size: int = 2200) -> list[str]:
    if len(text) <= chunk_size:
        return [text]

    chunks: list[str] = []
    current = ""
    for line in text.splitlines(keepends=True):
        if len(current) + len(line) > chunk_size and current:
            chunks.append(current)
            current = line
        else:
            current += line

    if current:
        chunks.append(current)

    if not chunks:
        return [text[i:i+chunk_size] for i in range(0, len(text), chunk_size)]
    return chunks

def _translate_text_sync(text: str, target_lang: str) -> str:
    if not isinstance(text, str):
        return text

    target_lang = _normalize_lang_code(target_lang)
    if not text.strip() or target_lang == DEFAULT_BOT_LANGUAGE:
        return text

    if not re.search(r"[A-Za-zက-႟฀-๿一-鿿ऀ-ॿ]", text):
        return text

    cache_key = (target_lang, text)
    cached = TRANSLATION_CACHE.get(cache_key)
    if cached:
        return cached

    translated_parts = []
    for chunk in _split_translate_chunks(text):
        payload = urlencode({
            'client': 'gtx',
            'sl': 'auto',
            'tl': target_lang,
            'dt': 't',
            'q': chunk,
        }).encode('utf-8')
        req = Request(
            'https://translate.googleapis.com/translate_a/single',
            data=payload,
            headers={
                'User-Agent': 'Mozilla/5.0',
                'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            },
        )
        with urlopen(req, timeout=12) as response:
            raw = response.read().decode('utf-8')
        data = json.loads(raw)
        translated_chunk = ''.join(part[0] for part in data[0] if part and part[0])
        translated_parts.append(translated_chunk or chunk)

    translated = ''.join(translated_parts).strip() or text
    TRANSLATION_CACHE[cache_key] = translated
    return translated

async def _translate_text_for_chat(text: str, chat_id) -> str:
    lang_code = _safe_chat_language(chat_id)
    if lang_code == DEFAULT_BOT_LANGUAGE or not isinstance(text, str) or not text.strip():
        return text
    try:
        return await asyncio.to_thread(_translate_text_sync, text, lang_code)
    except Exception as e:
        logger.warning(f"translation warning: {e}")
        return text

def _set_positional_arg(args_list: list, index: int, value):
    while len(args_list) <= index:
        args_list.append(None)
    args_list[index] = value

def install_language_runtime():
    if getattr(ExtBot, '_ziceko_language_patch_installed', False):
        return

    original_send_message = ExtBot.send_message
    original_send_photo = ExtBot.send_photo
    original_send_video = ExtBot.send_video
