    original_edit_message_caption = ExtBot.edit_message_caption

    async def send_message_patched(self, *args, **kwargs):
        args_list = list(args)
        chat_id = kwargs.get('chat_id', args_list[0] if len(args_list) > 0 else None)
        has_kw = 'text' in kwargs
        original_text = kwargs.get('text') if has_kw else (args_list[1] if len(args_list) > 1 else None)
        translated_text = await _translate_text_for_chat(original_text, chat_id)
        if translated_text != original_text:
            if has_kw:
                kwargs['text'] = translated_text
            else:
                _set_positional_arg(args_list, 1, translated_text)
            try:
                return await original_send_message(self, *args_list, **kwargs)
            except TelegramError as e:
                logger.warning(f"send_message translation fallback: {e}")
                if has_kw:
                    kwargs['text'] = original_text
                else:
                    _set_positional_arg(args_list, 1, original_text)
        return await original_send_message(self, *args_list, **kwargs)

