# ================= ONE-OF-A-KIND PRESTIGE TITLES =================
# Cards marked as singular (one_of_a_kind=True) gain a prestige title
# drawn from this pool. These are EXCLUSIVE — only one card can hold a given
# title at any time, and the title rotates as singular cards are created.
# "One-of-a-Kind" wording is intentionally avoided per design spec;
# instead we surface prestige titles ("Singularity", "Origin", "Monarch",...)
# that carry the same collector weight without sounding like marketing copy.
SINGULARITY_PRESTIGE_TITLES = (
    "🜲 SINGULARITY",
    "✦ ORIGIN",
    "♛ MONARCH",
    "☉ CROWN JEWEL",
    "☾ CELESTIAL RELIC",
    "✺ PRIMORDIAL",
    "⚚ ETERNAL SOVEREIGN",
)

# Maps singular-card id -> reserved prestige title (assigned on creation).
# Persisted in bot.data['singularity_assignments'] = { "1774 A": "🜲 SINGULARITY", ... }
def _singularity_assignments():
    """Return (and lazily create) the prestige-title assignment map."""
    if not hasattr(bot, "data") or not isinstance(getattr(bot, "data", None), dict):
        return {}
    return bot.data.setdefault('singularity_assignments', {})


def is_singular_card(card: dict) -> bool:
    """Return True if the card is marked as a Singularity-tier card.

    A card becomes singular when EITHER:
      - Admin/Sudo flags it via /setsingular <id>
      - It is uploaded with the `singular` keyword in /upload or /uploadvd
    """
    if not isinstance(card, dict):
        return False
    if card.get('one_of_a_kind') is True:
        return True
    if str(card.get('singular', '')).lower() in ('1', 'true', 'yes', 'on'):
        return True
    return False


def get_prestige_title_for(card: dict) -> str:
    """Return a stable prestige title for a singular card.
    Once a title is assigned to a card id, it stays for that card.
    """
    if not is_singular_card(card):
        return ""
    raw_id = str(card.get('id') or card.get('key') or '')
    if not raw_id:
        return SINGULARITY_PRESTIGE_TITLES[0]
    assigns = _singularity_assignments()
    if raw_id in assigns:
        return assigns[raw_id]
    # Pick a title not currently held by another card
    used = set(assigns.values())
    for t in SINGULARITY_PRESTIGE_TITLES:
        if t not in used:
            assigns[raw_id] = t
            return t
    # All titles in use — fall back to SINGULARITY (deterministic)
    assigns[raw_id] = SINGULARITY_PRESTIGE_TITLES[0]
    return SINGULARITY_PRESTIGE_TITLES[0]  # Fixed deterministic fallback

