def get_card_role(card: dict) -> str:
    """Return the canonical role key for a card.
    Auto-defaults to 'normal' when the card has no role field or an unknown role.
    Existing cards in the database are therefore safe — they show up as Normal.
    """
    if not isinstance(card, dict):
        return 'normal'
    raw = card.get('role')
    if not raw:
        return 'normal'
    key = str(raw).strip().lower().replace(' ', '').replace('-', '').replace('_', '')
    if key in ROLES:
        return key
    return ROLE_ALIASES.get(key, 'normal')


def get_role_info(card_or_role) -> dict:
    """Accepts either a card dict or a role key/string and returns the ROLES entry."""
    if isinstance(card_or_role, dict):
        key = get_card_role(card_or_role)
    else:
        key = str(card_or_role or '').strip().lower().replace(' ', '').replace('-', '').replace('_', '')
        key = ROLE_ALIASES.get(key, key if key in ROLES else 'normal')
    return ROLES.get(key, ROLES['normal'])


def role_display(card: dict) -> str:
    """Convenience wrapper: '🏖 Summer' style string for a card."""
    return get_role_info(card)['display']


def resolve_role_arg(arg) -> str | None:
    """Resolve a user-supplied role argument (name/alias/emoji) to a canonical role key.
    Returns None if not resolvable.
    """
    if arg is None:
        return None
    s = str(arg).strip().lower()
    if not s:
        return None
    s_clean = s.replace(' ', '').replace('-', '').replace('_', '')
    if s_clean in ROLES:
        return s_clean
    if s_clean in ROLE_ALIASES:
        return ROLE_ALIASES[s_clean]
    # Try emoji match
    for key, info in ROLES.items():
        if info['emoji'] == arg or info['emoji'] == s:
            return key
    return None


def _role_keyboard(prefix: str = 'role_'):
    """Inline keyboard with all roles (2 columns)."""
    from telegram import InlineKeyboardButton, InlineKeyboardMarkup
    keys = list(ROLES.keys())
    rows = []
    row = []
    for i, k in enumerate(keys):
        row.append(InlineKeyboardButton(ROLES[k]['display'], callback_data=f"{prefix}{k}"))
        if len(row) == 2:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    return InlineKeyboardMarkup(rows)


