def _md_escape(text: str) -> str:
    """Escape text for legacy Markdown parse_mode."""
    if text is None:
        return ""
    text = str(text)
    return (
        text.replace('\\', '\\\\')
            .replace('[', '\\[')
            .replace(']', '\\]')
            .replace('(', '\\(')
            .replace(')', '\\)')
            .replace('*', '\\*')
            .replace('_', '\\_')
            .replace('`', '\\`')
    )


def _mention_md(user_id, name) -> str:
    name = name or "User"
    if user_id:
        try:
            uid = int(user_id)
        except Exception:
            uid = None
        if uid:
            return f"[{_md_escape(name)}](tg://user?id={uid})"
    return _md_escape(name)


def _card_media_line(card: dict) -> str:
    if card.get('type') == 'video' or card.get('video'):
        return "🎥 Video updated"
    return "🖼 Photo updated"


def build_db_updated_caption(card_id: str, action_line: str) -> str:
    card = bot.data.get('cards', {}).get(str(card_id), {})
    rarity_key = str(card.get('rarity', '1'))
    rarity_info = RARITIES.get(rarity_key, RARITIES['1'])
    role_info = get_role_info(card)

    uploader_name = card.get('uploaded_by') or "Unknown"
    uploader_id = card.get('uploaded_by_id')
    uploader = _mention_md(uploader_id, uploader_name)

    return (
        f"{STYLE_3D['border_top']}\n"
        f"✅ Updated\n"
        f"{STYLE_3D['sep']}\n"
        f"🆔 ID: {card.get('id', card_id)}\n"
        f"📛 {_md_escape(card.get('name', ''))}\n"
        f"🎬 {_md_escape(card.get('movie', ''))}\n"
        f"⭐ {rarity_info['display']}\n"
        f"🎭 {role_info['display']}\n"
        f"{_card_media_line(card)}\n"
        f"{action_line}\n"
        f"📤 Uploader: {uploader}\n"
        f"{STYLE_3D['border_bot']}"
    )


async def notify_db_channel_card_update(bot_api, card_id: str, action_line: str):
    """Auto-send updated card media to /setdbchannel target."""
    db_chat = bot.settings.get('database_channel')
    if not db_chat:
        return

    card = bot.data.get('cards', {}).get(str(card_id))
    if not card:
        return

    caption = build_db_updated_caption(str(card_id), action_line=action_line)

    try:
        if card.get('type') == 'video' or card.get('video'):
            if card.get('video_type') == 'video':
                await bot_api.send_video(chat_id=db_chat, video=card.get('video'), caption=caption, parse_mode='Markdown')
            else:
                await bot_api.send_document(chat_id=db_chat, document=card.get('video'), caption=caption, parse_mode='Markdown')
        else:
            if card.get('image'):
                await bot_api.send_photo(chat_id=db_chat, photo=card.get('image'), caption=caption, parse_mode='Markdown')
            else:
                await bot_api.send_message(chat_id=db_chat, text=caption, parse_mode='Markdown')
    except Exception as e:
        logger.error(f"DB channel notify failed: {e}")

DATECT_SESSIONS: dict[str, dict] = {}
DATECT_SESSION_TTL = 3600


def _cleanup_datect_sessions():
    now_ts = time.time()
    expired = [
        token for token, info in DATECT_SESSIONS.items()
        if now_ts - float(info.get('created_at', now_ts)) > DATECT_SESSION_TTL
    ]
    for token in expired:
        DATECT_SESSIONS.pop(token, None)


def _datect_card_sort_key(item):
    cid, card = item
    try:
        return int(card.get('id', cid))
    except Exception:
        try:
            return int(cid)
        except Exception:
            return 10 ** 9


def _datect_get_media(card: dict):
    if not isinstance(card, dict):
        return None, None

    video = card.get('video_url') or card.get('video')
    if video:
        return 'video', video

    photo = card.get('photo_url') or card.get('image') or card.get('photo')
    if photo:
        return 'photo', photo

    return None, None


def _datect_build_caption(card: dict, result_index: int, total_results: int) -> str:
    rarity_key = str(card.get('rarity', '1'))
    rarity_info = RARITIES.get(rarity_key, {})
    role_info = get_role_info(card)

    card_id = card.get('id', '-')
    card_name = card.get('name') or '-'
    anime_name = card.get('movie') or card.get('anime') or card.get('anime/movie') or '-'
    role_name = role_info.get('name') or role_info.get('display') or 'Normal'
    rarity_name = rarity_info.get('name') or str(card.get('rarity', '-'))

    return (
        "💘 Card Search\n\n"
        f"🆔 ID : {card_id}\n"
        f"📛 Name : {card_name}\n"
        f"🎬 Anime : {anime_name}\n"
        f"🎭 Role : {role_name}\n"
        f"⭐ Rarity : {rarity_name}\n\n"
        f"📄 Result {result_index + 1}/{total_results}\n\n"
        "━━━━━━━━━━━━━━"
    )


def _datect_build_keyboard(token: str, index: int, total: int) -> InlineKeyboardMarkup:
    if total <= 0:
        total = 1
    prev_index = (index - 1) % total
    next_index = (index + 1) % total
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("⬅️ Back", callback_data=f"datect|nav|{token}|{prev_index}"),
            InlineKeyboardButton("➡️ Next", callback_data=f"datect|nav|{token}|{next_index}"),
        ],
        [InlineKeyboardButton("❌ Close", callback_data=f"datect|close|{token}")],
    ])


async def _datect_send_initial_result(message, card: dict, index: int, total: int, token: str):
    caption = _datect_build_caption(card, index, total)
    reply_markup = _datect_build_keyboard(token, index, total)
    media_kind, media_value = _datect_get_media(card)

    try:
        if media_kind == 'video' and media_value:
            await message.reply_video(video=media_value, caption=caption, reply_markup=reply_markup)
            return
        if media_kind == 'photo' and media_value:
            await message.reply_photo(photo=media_value, caption=caption, reply_markup=reply_markup)
            return
    except Exception as e:
        logger.warning(f"datect initial media fallback: {e}")

    await message.reply_text(caption, reply_markup=reply_markup)


async def _datect_edit_result(query, card: dict, index: int, total: int, token: str):
    caption = _datect_build_caption(card, index, total)
    reply_markup = _datect_build_keyboard(token, index, total)
    media_kind, media_value = _datect_get_media(card)

    try:
        if media_kind == 'video' and media_value:
            await query.edit_message_media(
                media=InputMediaVideo(media=media_value, caption=caption),
                reply_markup=reply_markup,
            )
            return
        if media_kind == 'photo' and media_value:
            await query.edit_message_media(
                media=InputMediaPhoto(media=media_value, caption=caption),
                reply_markup=reply_markup,
            )
            return
        await query.edit_message_text(text=caption, reply_markup=reply_markup)
        return
    except Exception as e:
        logger.warning(f"datect edit media fallback: {e}")

    try:
        await query.edit_message_caption(caption=caption, reply_markup=reply_markup)
        return
    except Exception as e:
        logger.warning(f"datect edit caption fallback: {e}")

    await query.edit_message_text(text=caption, reply_markup=reply_markup)


