def resolve_rarity_arg(arg: str):
    """Resolve rarity ID (1-16) or name to rarity key. Returns key or None."""
    arg = (arg or "").strip()
    if arg in RARITIES:
        return arg
    arg_lower = arg.lower()
    for key, val in RARITIES.items():
        if val['name'].lower() == arg_lower:
            return key
    return None


def parse_name_movie_from_caption(caption: str):
    """Extract (name, movie) from common caption formats.

    Supports formats like:
    - "📛 Name" and "🎬 Movie"
    - "🎴 Name" and "🎬 Movie"
    - "🌟 Name   : xxx" and "🎬 Anime  : yyy"
    - Fallback: first 2 non-empty lines => (name, movie)
    """
    if not caption:
        return None, None

    name = None
    movie = None
    non_empty: list[str] = []

    for raw in str(caption).splitlines():
        line = raw.strip()
        if not line:
            continue
        non_empty.append(line)

        # NAME
        if line.startswith('📛') or line.startswith('🎴') or re.search(r"\bName\b", line, flags=re.I):
            tmp = line.replace('📛', '').replace('🎴', '').strip()
            tmp = re.sub(r"^🌟\s*Name\s*[:：]?\s*", "", tmp, flags=re.I)
            tmp = re.sub(r"^Name\s*[:：]?\s*", "", tmp, flags=re.I)
            if ':' in tmp:
                parts = tmp.split(':', 1)
                if len(parts[0].strip()) <= 10:
                    tmp = parts[1].strip()
            if tmp:
                name = name or tmp
                continue

        # MOVIE / ANIME
        if line.startswith('🎬') or re.search(r"\b(Anime|Movie)\b", line, flags=re.I):
            tmp = line.replace('🎬', '').strip()
            tmp = re.sub(r"^(Anime|Movie)\s*[:：]?\s*", "", tmp, flags=re.I)
            m = re.search(r"[:：]\s*(.+)$", tmp)
            if m and len(tmp.split(':', 1)[0].strip()) <= 12:
                tmp = m.group(1).strip()
            if tmp:
                movie = movie or tmp
                continue

    # fallback: first 2 meaningful lines (ignore borders/separators)
    if (not name or not movie) and len(non_empty) >= 2:
        cleaned = []
        for ln in non_empty:
            if any(ch in ln for ch in ['══', '━━', '╔', '╚', '╭', '╰', '┄', '┈']):
                continue
            if ln.startswith('#'):
                continue
            cleaned.append(ln)
        if len(cleaned) >= 2:
            name = name or cleaned[0]
            movie = movie or cleaned[1]

    return name, movie


async def li_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/li <rarity_no> [role] (reply) => auto upload from forwarded/replied media.

    Usage:
      - Forward card/photo/video message
      - Reply to that message: /li 3
      - Optional role: /li 3 summer  (defaults to Normal)
    """
    user_id = update.effective_user.id if update.effective_user else None
    if not user_id or not bot.is_admin(user_id):
        await update.message.reply_text("❌ Admin only")
        return

    if not update.message.reply_to_message:
        await update.message.reply_text("📝 Forward လုပ်ထားတဲ့ photo/video message ကို reply ထားပြီး\n/li <rarity 1-16> [role] လို့ရိုက်ပါ")
        return

    if not context.args:
        await update.message.reply_text("📝 /li <rarity 1-16> [role]  (ဥပမာ /li 3 summer)")
        return

    rarity_key = resolve_rarity_arg(str(context.args[0]))
    if not rarity_key:
        await update.message.reply_text("❌ Rarity မမှန်ပါ (1-16)\nဥပမာ /li 3")
        return

    # Optional role argument (defaults to 'normal' when omitted/invalid)
    role_key = 'normal'
    if len(context.args) >= 2:
        resolved = resolve_role_arg(' '.join(context.args[1:]))
        if resolved:
            role_key = resolved

    src = update.message.reply_to_message

    # media
    media_type = None
    image_file_id = None
    video_file_id = None
    video_type = None

    if src.photo:
        image_file_id = src.photo[-1].file_id
        media_type = 'photo'
    elif src.video:
        video_file_id = src.video.file_id
        media_type = 'video'
        video_type = 'video'
    elif src.document:
        # accept any document as video-like if admin wants
        video_file_id = src.document.file_id
        media_type = 'video'
        video_type = 'document'
    else:
        await update.message.reply_text("❌ Reply ထားတဲ့ message ထဲမှာ photo/video/document မရှိပါ")
        return

    caption_text = src.caption or src.text or ""
    name, movie = parse_name_movie_from_caption(caption_text)

    if not name or not movie:
        await update.message.reply_text(
            "❌ Name/Movie မတွေ့ပါ\n"
            "Caption ထဲမှာ 📛 Name / 🎬 Movie (သို့) 🎴 Name / 🎬 Movie ပုံစံရှိရပါမယ်"
        )
        return

    # create card
    try:
        card_id = bot.data['next_id']
        user = update.effective_user

        card_data = {
            'id': card_id,
            'name': name.strip(),
            'movie': movie.strip(),
            'owner': None,
            'owner_name': 'Available',
            'uploaded_by': user.first_name if user else 'Admin',
            'uploaded_by_id': user.id if user else user_id,
            'date': datetime.now().isoformat(),
            'rarity': str(rarity_key),
            'role': role_key,
        }

        if media_type == 'photo':
            card_data['image'] = image_file_id
        else:
            card_data['video'] = video_file_id
            card_data['video_type'] = video_type
            card_data['type'] = 'video'

        bot.data['cards'][str(card_id)] = card_data
        bot.data['next_id'] += 1
        bot.save_data()

        rarity_info = RARITIES.get(str(rarity_key), RARITIES['1'])
        role_info = get_role_info(card_data)

        # ── Premium Channel UI (Bold Unicode + Gacha-style layout) ──
        caption = build_li_channel_caption(
            card=card_data,
            uploader_id=(user.id if user else user_id),
            uploader_name=(user.first_name if user else 'Admin'),
        )
        _parse_mode = 'HTML'

        # send in current chat
        if media_type == 'photo':
            await update.message.reply_photo(photo=image_file_id, caption=caption, parse_mode=_parse_mode)
        else:
            if video_type == 'video':
                await update.message.reply_video(video=video_file_id, caption=caption, parse_mode=_parse_mode)
            else:
                await update.message.reply_document(document=video_file_id, caption=caption, parse_mode=_parse_mode)

        # send to db channel (if set)
        if bot.settings.get('database_channel'):
            try:
                db_chat = bot.settings['database_channel']
                if media_type == 'photo':
                    await context.bot.send_photo(chat_id=db_chat, photo=image_file_id, caption=caption, parse_mode=_parse_mode)
                else:
                    if video_type == 'video':
                        await context.bot.send_video(chat_id=db_chat, video=video_file_id, caption=caption, parse_mode=_parse_mode)
                    else:
                        await context.bot.send_document(chat_id=db_chat, document=video_file_id, caption=caption, parse_mode=_parse_mode)
            except Exception as e:
                logger.error(f"/li DB channel send failed: {e}")

    except Exception as e:
        logger.error(f"/li failed: {e}")
        await update.message.reply_text(f"❌ /li error: {e}")


