def _now():
    return datetime.now()


def _parse_iso(dt_str: str):
    try:
        return datetime.fromisoformat(dt_str)
    except Exception:
        return None


def _get_active_rarity_boost():
    """Return active boost dict or None."""
    boost = bot.settings.get('rarity_boost') if hasattr(bot, 'settings') else None
    if not boost or not isinstance(boost, dict):
        return None
    ends_at = _parse_iso(str(boost.get('ends_at') or ''))
    if not ends_at:
        return None
    if _now() >= ends_at:
        try:
            bot.settings['rarity_boost'] = None
            bot.save_settings()
        except Exception:
            pass
        return None
    return boost


def _normalize_weights(items):
    cleaned = [(k, float(w)) for k, w in items if w is not None and float(w) > 0]
    s = sum(w for _, w in cleaned)
    if s <= 0:
        return []
    return [(k, (w / s) * 100.0) for k, w in cleaned]


def _weighted_choice(pairs):
    r = random.random() * sum(w for _, w in pairs)
    upto = 0.0
    for k, w in pairs:
        upto += w
        if upto >= r:
            return k
    return pairs[-1][0]


def _get_effective_rarity_rates(locked_rarities: list[str]):
    base = dict(bot.settings.get('rarity_rates') or {})
    if not base:
        base = dict(DEFAULT_RARITY_RATES)

    available = []
    for rk in base.keys():
        if rk == '15':
            continue
        if str(rk) in locked_rarities:
            continue
        available.append(str(rk))

    # remove rarities with no droppable cards
    droppable_rarities = set()
    for _, c in bot.data.get('cards', {}).items():
        if not c:
            continue
        if not c.get('drop_enabled', True):
            continue
        rr = str(c.get('rarity', '1'))
        if rr != '15' and rr not in locked_rarities:
            droppable_rarities.add(rr)

    available = [rk for rk in available if rk in droppable_rarities]

    rates = [(rk, float(base.get(rk, 0.0))) for rk in available]
    rates = _normalize_weights(rates)

    boost = _get_active_rarity_boost()
    if not boost:
        return rates

    br = str(boost.get('rarity'))
    try:
        bp = float(boost.get('percent'))
    except Exception:
        bp = 0.0

    if br not in [k for k, _ in rates] or bp <= 0:
        return rates

    bp = max(0.0, min(bp, 100.0))
    others = [(k, w) for k, w in rates if k != br]
    others_sum = sum(w for _, w in others)

    if others_sum <= 0:
        return [(br, 100.0)]

    remaining = max(0.0, 100.0 - bp)
    scaled_others = [(k, (w / others_sum) * remaining) for k, w in others]

    effective = [(br, bp)] + scaled_others
    effective = [(k, w) for k, w in effective if w > 0]
    return effective


def _choose_card_id_by_rates(locked_rarities: list[str]):
    rates = _get_effective_rarity_rates(locked_rarities)
    if not rates:
        return None

    chosen_rarity = _weighted_choice(rates)

    pool = [cid for cid, c in bot.data.get('cards', {}).items()
            if c and c.get('drop_enabled', True)
            and str(c.get('rarity', '1')) == str(chosen_rarity)
            and str(c.get('rarity', '1')) not in locked_rarities
            and str(c.get('rarity', '1')) != '15']

    if not pool:
        pool = [cid for cid, c in bot.data.get('cards', {}).items()
                if c and c.get('drop_enabled', True)
                and str(c.get('rarity', '1')) != '15'
                and str(c.get('rarity', '1')) not in locked_rarities]

    return __import__('random').choice(pool) if pool else None




class CardBot:
    def __init__(self):
        self.data = self.load_data()
        self.settings = self.load_settings()

    def load_data(self):
        """Load card data from file"""
        if os.path.exists(DATA_FILE):
            with open(DATA_FILE, 'r', encoding='utf-8') as f:
                data = json.load(f)
            # Patch missing keys safely (backward compatible)
            if isinstance(data, dict):
                data.setdefault('cards', {})
                data.setdefault('users', {})
                data.setdefault('next_id', 1)
                data.setdefault('group_counters', {})
                data.setdefault('dropped_cards', {})
                data.setdefault('card_message_ids', {})
                data.setdefault('active_groups', [])
                data.setdefault('last_claims', {})
                data.setdefault('group_drop_counters', {})
                data.setdefault('user_profiles', {})
                data.setdefault('marriages', {})
                data.setdefault('proposals', {})
                data.setdefault('redeem_codes', {})
                data.setdefault('group_drop_enabled', {})
                data.setdefault('group_last_drop_time', {})
                data.setdefault('favorites', {})
            return data

        return {
            'cards': {},
            'users': {},
            'next_id': 1,
            'group_counters': {},
            'dropped_cards': {},
            'card_message_ids': {},
            'active_groups': [],
            'last_claims': {},
            'group_drop_counters': {},
            'user_profiles': {},
            'marriages': {},
            'proposals': {},
            'favorites': {},
            'redeem_codes': {},
            'group_drop_enabled': {},
            'group_last_drop_time': {}
        }

    def save_data(self):
        """Save card data to file"""
        os.makedirs(os.path.dirname(DATA_FILE) if os.path.dirname(DATA_FILE) else ".", exist_ok=True)
        with open(DATA_FILE, 'w', encoding='utf-8') as f:
            json.dump(self.data, f, ensure_ascii=False, indent=2)

    def load_settings(self):
        """Load bot settings"""
        if os.path.exists(SETTINGS_FILE):
            with open(SETTINGS_FILE, 'r', encoding='utf-8') as f:
                s = json.load(f)
            # Patch missing keys safely (backward compatible)
            s.setdefault('admins', OWNERS.copy())
            s.setdefault('database_channel', None)
            s.setdefault('drop_channel', None)
            s.setdefault('drop_threshold', 50)
            s.setdefault('sudo_users', [])
            s.setdefault('dev_users', [])
            s.setdefault('gbanned_users', {})
            s.setdefault('gmuted_users', {})
            s.setdefault('last_backup_message_id', None)
            s.setdefault('last_backup_file_id', None)
            s.setdefault('card_backup_message_ids', [])
            s.setdefault('drop_chance_percent', 100)
            s.setdefault('animated_rate', 11)
            s.setdefault('forced_next_rarity', None)
            s.setdefault('locked_rarities', [])
            s.setdefault('harem_channel', None)
            s.setdefault('harem_group', None)
            s.setdefault('log_group_id', None)  # Admin/Sudo command log group
            s.setdefault('chat_languages', {})

            # NEW (Owner Drop Control)
            s.setdefault('drop_system_enabled', True)
            s.setdefault('drop_cooldown_seconds', 0)
            s.setdefault('rarity_rates', dict(DEFAULT_RARITY_RATES))
            s.setdefault('rarity_boost', None)

            # NEW (Security / Locks)
            s.setdefault('bot_locked', False)
            s.setdefault('trade_locked', False)
            s.setdefault('suspended_users', {})

            # NEW (Slot Win Rate Control)
            s.setdefault('slot_win_rate', 40)  # default 40%

            # NEW (Rob Lock)
            s.setdefault('rob_locked', False)
            s.setdefault('drop_sticker', None)  # Sticker before card drop

            return s
        return {
            'admins': OWNERS.copy(),
            'database_channel': None,
            'drop_channel': None,
            'drop_threshold': 50,
            'sudo_users': [],
            'dev_users': [],
            'gbanned_users': {},
            'gmuted_users': {},
            'last_backup_message_id': None,
            'last_backup_file_id': None,
            'card_backup_message_ids': [],
            'drop_chance_percent': 100,
            'animated_rate': 11,
            'forced_next_rarity': None,
            'locked_rarities': [],
            # ── Harem Join Protection ──
            'harem_channel': None,   # Required channel username (e.g. @mychannel)
            'harem_group': None,     # Required group username (e.g. @mygroup)
            'log_group_id': None,    # Admin/Sudo command log group
            'chat_languages': {},
            # NEW (Owner Drop Control)
            'drop_system_enabled': True,
            'drop_cooldown_seconds': 0,
            'rarity_rates': dict(DEFAULT_RARITY_RATES),
            'rarity_boost': None,
            # NEW (Security / Locks)
            'bot_locked': False,
            'trade_locked': False,
            'suspended_users': {},
            # NEW (Slot Win Rate Control)
            'slot_win_rate': 40,  # default 40%
            # NEW (Rob Lock)
            'rob_locked': False,
            'drop_sticker': None  # Sticker before card drop
        }

    def save_settings(self):
        """Save bot settings"""
        os.makedirs(os.path.dirname(SETTINGS_FILE) if os.path.dirname(SETTINGS_FILE) else ".", exist_ok=True)
        with open(SETTINGS_FILE, 'w', encoding='utf-8') as f:
            json.dump(self.settings, f, ensure_ascii=False, indent=2)

    def is_admin(self, user_id):
        return user_id in self.settings['admins'] or self.is_sudo(user_id) or self.is_dev(user_id)

    def is_real_owner(self, user_id):
        return user_id in OWNERS

    def is_owner(self, user_id):
        if self.is_real_owner(user_id):
            return True
        try:
            permitted = self.settings.get('owner_permitted_users', []) or []
            return int(user_id) in [int(x) for x in permitted]
        except Exception:
            return False
    
    def is_sudo(self, user_id):
        return user_id in self.settings.get('sudo_users', []) or self.is_owner(user_id)
    
    def is_dev(self, user_id):
        return user_id in self.settings.get('dev_users', []) or self.is_owner(user_id)
    
    def is_gbanned(self, user_id):
        return str(user_id) in self.settings.get('gbanned_users', {})
    
    def is_gmuted(self, user_id):
        return str(user_id) in self.settings.get('gmuted_users', {})


