def _build_language_keyboard(selected_lang: str | None = None) -> InlineKeyboardMarkup:
    selected_lang = _normalize_lang_code(selected_lang)
    rows = []
    current_row = []
    for code, label in LANGUAGE_BUTTONS:
        text = f"✅ {label}" if code == selected_lang else label
        current_row.append(InlineKeyboardButton(text, callback_data=f"lang_set_{code}"))
        if len(current_row) == 2:
            rows.append(current_row)
            current_row = []
    if current_row:
        rows.append(current_row)
    return InlineKeyboardMarkup(rows)

