def _autosave_worker():
    while True:
        try:
            time.sleep(60)
            try:
                bot.save_data()
            except Exception as e:
                logger.error(f"Autosave data error: {e}")
            try:
                bot.save_settings()
            except Exception as e:
                logger.error(f"Autosave settings error: {e}")
            try:
                save_events()
            except Exception as e:
                logger.error(f"Autosave events error: {e}")
        except Exception as e:
            logger.error(f"Autosave worker error: {e}")

