def init_user_if_not_exists(user_id: str):
    """Initialize user data with XP profile"""
    if user_id not in bot.data['users']:
        bot.data['users'][user_id] = []
    
    if 'user_profiles' not in bot.data:
        bot.data['user_profiles'] = {}
    
    if user_id not in bot.data['user_profiles']:
        bot.data['user_profiles'][user_id] = {
            "xp": 0,
            "level": 1,
            "coins": 0,
            "last_xp_time": None,
            "last_daily": None,
            "bank": 0,
            "last_interest": None,
            "event_coins": 0,
            "luck": 0.0,
            "reputation": 0,
            "title": None,
            "wishlist": [],
            "profile_media": None,
            "pvp_wins": 0,
            "pvp_battles": 0,
            "pvp_streak": 0,
            "pvp_max_streak": 0,
            "card_claimed": 0,
            "drop_total": 0,
            "drop_rare_plus": 0,
            "daily_claimed_days": 0,
            "market_trades": 0,
            "total_earned": 0,
            "muted_notices": False,
            "spam_streak_count": 0,
            "spam_streak_updated_at": None,
            "command_mute_until": None
        }
    else:
        # Patch old profiles - add bank fields if missing
        if "last_daily" not in bot.data['user_profiles'][user_id]:
            bot.data['user_profiles'][user_id]["last_daily"] = None
        if "bank" not in bot.data['user_profiles'][user_id]:
            bot.data['user_profiles'][user_id]["bank"] = 0
        if "last_interest" not in bot.data['user_profiles'][user_id]:
            bot.data['user_profiles'][user_id]["last_interest"] = None
        if "event_coins" not in bot.data['user_profiles'][user_id]:
            bot.data['user_profiles'][user_id]["event_coins"] = 0
        if "luck" not in bot.data['user_profiles'][user_id]:
            bot.data['user_profiles'][user_id]["luck"] = 0.0
        if "reputation" not in bot.data['user_profiles'][user_id]:
            bot.data['user_profiles'][user_id]["reputation"] = 0
        if "title" not in bot.data['user_profiles'][user_id]:
            bot.data['user_profiles'][user_id]["title"] = None
        if "wishlist" not in bot.data['user_profiles'][user_id]:
            bot.data['user_profiles'][user_id]["wishlist"] = []
        if "profile_media" not in bot.data['user_profiles'][user_id]:
            bot.data['user_profiles'][user_id]["profile_media"] = None
        # ── stats fields patch ──
        for _sf, _sv in [
            ("pvp_wins", 0), ("pvp_battles", 0), ("pvp_streak", 0),
            ("pvp_max_streak", 0), ("card_claimed", 0),
            ("drop_total", 0), ("drop_rare_plus", 0),
            ("daily_claimed_days", 0), ("market_trades", 0),
            ("total_earned", 0), ("muted_notices", False),
            ("spam_streak_count", 0), ("spam_streak_updated_at", None),
            ("command_mute_until", None),
        ]:
            if _sf not in bot.data['user_profiles'][user_id]:
                bot.data['user_profiles'][user_id][_sf] = _sv
    # Ensure marriage/proposal dicts always exist
    if 'marriages' not in bot.data:
        bot.data['marriages'] = {}
    if 'proposals' not in bot.data:
        bot.data['proposals'] = {}

    # Ensure group drop enable map exists
    if 'group_drop_enabled' not in bot.data:
        bot.data['group_drop_enabled'] = {}


def xp_required_for_level(level: int):
    """Calculate XP required for next level"""
    return 100 + (level - 1) * 50


def check_level_up(user_id: str):
    """Check if user leveled up"""
    profile = bot.data['user_profiles'][user_id]
    
    leveled_up = False
    while profile["xp"] >= xp_required_for_level(profile["level"]):
        profile["xp"] -= xp_required_for_level(profile["level"])
        profile["level"] += 1
        profile["coins"] += 100  # reward per level
        leveled_up = True
    
    return leveled_up




def _get_command_mute_until_dt(user_id: str):
    init_user_if_not_exists(user_id)
    profile = bot.data['user_profiles'][user_id]
    raw_until = profile.get('command_mute_until')
    if not raw_until:
        return None

    until_dt = _parse_iso(str(raw_until))
    if not until_dt or _now() >= until_dt:
        profile['command_mute_until'] = None
        try:
            bot.save_data()
        except Exception:
            pass
        return None

    return until_dt


def _reset_spam_streak(user_id: str, save: bool = False):
    init_user_if_not_exists(user_id)
    profile = bot.data['user_profiles'][user_id]
    profile['spam_streak_count'] = 0
    profile['spam_streak_updated_at'] = None
    if save:
        try:
            bot.save_data()
        except Exception:
            pass


async def anti_spam_text_tracker(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """If a user sends 40 consecutive non-command text messages,
    only restricted commands (/drop /claim /slot /blue /harem) are blocked for 10 minutes.
    Owner / Sudo / Dev / owner-permitted users are exempt.
    """
    if not update.effective_user or not update.message or update.effective_user.is_bot:
        return

    text_msg = (update.message.text or '').strip()
    if not text_msg or text_msg.startswith('/'):
        return

    user_id_int = update.effective_user.id
    # Permission bypass: owner / sudo / dev / owner-permitted users never get spam-muted
    try:
        if bot.is_owner(user_id_int) or bot.is_sudo(user_id_int) or bot.is_dev(user_id_int) or _is_owner_permitted(user_id_int):
            return
    except Exception:
        pass

    user_id = str(update.effective_user.id)
    init_user_if_not_exists(user_id)
    profile = bot.data['user_profiles'][user_id]
    now = _now()

    last_dt = _parse_iso(str(profile.get('spam_streak_updated_at') or ''))
    if not last_dt or (now - last_dt).total_seconds() > SPAM_STREAK_RESET_SECONDS:
        profile['spam_streak_count'] = 0

    profile['spam_streak_count'] = int(profile.get('spam_streak_count', 0) or 0) + 1
    profile['spam_streak_updated_at'] = now.isoformat()

    active_until = _get_command_mute_until_dt(user_id)
    if active_until:
        try:
            bot.save_data()
        except Exception:
            pass
        return

    if profile['spam_streak_count'] >= SPAM_STREAK_LIMIT:
        mute_until = now + timedelta(minutes=COMMAND_SPAM_MUTE_MINUTES)
        profile['command_mute_until'] = mute_until.isoformat()
        profile['spam_streak_count'] = 0
        profile['spam_streak_updated_at'] = now.isoformat()

        try:
            bot.save_data()
        except Exception as e:
            logger.error(f'anti_spam_text_tracker save error: {e}')

        try:
            await update.message.reply_text(
                '⚠️ Spam Notice\n'
                'ဆက်တိုက် စာ 40 ကြောင်းပို့ထားသောကြောင့်\n'
                '/drop, /claim, /slot, /blue, /harem command များကို 10 မိနစ်ပိတ်ထားပါသည်။\n'
                '⏳ 10 မိနစ်ပြည့်ပြီးမှ ပြန်သုံးနိုင်ပါမည်။\n'
                '💡 /restm  →  ချက်ချင်း ဖြေနိုင်သည်'
            )
        except Exception:
            pass


def _extract_command_word(text: str) -> str:
    """Return the bare command word (without /, without @botname). Empty if not a command."""
    if not text:
        return ''
    t = text.strip()
    if not t.startswith('/'):
        return ''
    head = t.split()[0]
    word = head.lstrip('/').split('@', 1)[0].lower()
    return word


def _is_owner_permitted(user_id) -> bool:
    """Check whether a user has been granted /ownp owner-permit (full command access)."""
    try:
        permitted = bot.settings.get('owner_permitted_users', []) or []
        return int(user_id) in [int(x) for x in permitted]
    except Exception:
        return False


async def command_mute_blocker(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Block ONLY restricted slash commands (/drop /claim /slot /blue /harem)
    while a user is under anti-spam command mute.

    Other commands (and /restm) are still allowed.
    Owner / Sudo / Dev / owner-permitted users are exempt.
    """
    if not update.effective_user or not update.message or update.effective_user.is_bot:
        return

    user_id = str(update.effective_user.id)
    user_id_int = update.effective_user.id

    # Permission bypass
    try:
        if bot.is_owner(user_id_int) or bot.is_sudo(user_id_int) or bot.is_dev(user_id_int) or _is_owner_permitted(user_id_int):
            return
    except Exception:
        pass

    cmd_word = _extract_command_word(update.message.text or '')

    # /restm must always be allowed so user can self-release
    if cmd_word == 'restm':
        return

    # Only block restricted commands when muted
    if cmd_word not in SPAM_RESTRICTED_COMMANDS:
        # Non-restricted commands: also reset streak so they don't accidentally mute
        profile = bot.data.get('user_profiles', {}).get(user_id)
        if profile and (profile.get('spam_streak_count') or profile.get('spam_streak_updated_at')):
            _reset_spam_streak(user_id, save=True)
        return

    mute_until = _get_command_mute_until_dt(user_id)
    if mute_until:
        remaining_seconds = max(1, int((mute_until - _now()).total_seconds()))
        remaining_minutes = max(1, (remaining_seconds + 59) // 60)
        try:
            await update.message.reply_text(
                f'🚫 ႀ𝖆𝖓𝖕𝖓ႀ  ႅႀ  ႀ𝖆𝖗𝖊  ႀ𝖝𝖆𝖙𝖊𝖉ႀ  /{cmd_word} ကို ယာယီပိတ်ထားပါသည်။\n'
                f'⏳ ကျန်ရှိချိန်: {remaining_minutes} မိနစ်\n'
                f'📌 Spam 40 ကြောင်းဆက်တိုက်ပို့ထားသောကြောင့် 10 မိနစ် mute ဝင်ထားပါသည်။\n'
                f'💡 /restm  →  ချက်ချင်း ဖြေနိုင်သည်\n'
                f'🔓 ခွင့်ပြုတော့မည့် command: drop, claim, slot, blue, harem'
            )
        except Exception:
            pass
        raise ApplicationHandlerStop

    profile = bot.data.get('user_profiles', {}).get(user_id)
    if profile and (profile.get('spam_streak_count') or profile.get('spam_streak_updated_at')):
        _reset_spam_streak(user_id, save=True)


# ==================== /restm  &  /ownp ====================

async def restm_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/restm  —  စပန်းမှု mute ထိထားရင် ကိုယ့်ကိုယ့် self-unmute ပြုလုပ်နိုင်သည်"""
    if not update.effective_user or not update.message:
        return

    user = update.effective_user
    user_id = str(user.id)
    init_user_if_not_exists(user_id)

    profile = bot.data['user_profiles'][user_id]
    was_muted = bool(profile.get('command_mute_until'))

    profile['command_mute_until'] = None
    profile['spam_streak_count'] = 0
    profile['spam_streak_updated_at'] = None
    try:
        bot.save_data()
    except Exception as e:
        logger.error(f'restm_cmd save error: {e}')

    if was_muted:
        await update.message.reply_text(
            "✅ Spam-mute ဖြေရှင်းပြီးပါပြီ!\n"
            "🎯 /drop, /claim, /slot, /blue, /harem command များကို ပြန်သုံးနိုင်ပါပြီ။"
        )
    else:
        await update.message.reply_text(
            "ℹ️ မင်း mute မရှိပါ။ spam streak ကို reset ပြီးပါပြီ။"
        )


async def ownp_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/ownp <username|reply>  —  Owner Permit

    Owner-only. Grants the target user UNRESTRICTED access to all commands
    (bypasses spam-mute, gmute, locks etc.).
    Toggle behaviour: running it again on the same user removes the permit.
    """
    if not update.effective_user or not update.message:
        return
    if not bot.is_real_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only command")
        return

    target_id = None
    target_name = None

    # 1) Reply
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        ru = update.message.reply_to_message.from_user
        if ru and not ru.is_bot:
            target_id = ru.id
            target_name = ru.first_name or ru.username or str(ru.id)

    # 2) Username / numeric id argument
    if target_id is None and context.args:
        arg = context.args[0].strip().lstrip('@')
        if arg.isdigit():
            target_id = int(arg)
            target_name = USER_CACHE.get(str(target_id)) or f"User {target_id}"
        else:
            # Lookup numeric id by username (best-effort via USER_CACHE / Telegram API)
            try:
                chat = await context.bot.get_chat('@' + arg)
                target_id = chat.id
                target_name = chat.first_name or arg
            except Exception:
                await update.message.reply_text(
                    "❌ ဤ username င့် user မတွေ့ပါ။ Reply တိုကျတော့မှ numeric ID နှင့် တိုကျသုံးပါ။"
                )
                return

    if target_id is None:
        await update.message.reply_text(
            "📝 /ownp <username သို့မဟုတ် reply>\n\n"
            "ၵ𝖕𝖆𝖒𝖕𝖕𝖆: /ownp @someone\n"
            "ၵ𝖕𝖆𝖒𝖕𝖕𝖆 2: (reply to user) /ownp"
        )
        return

    if bot.is_real_owner(target_id):
        await update.message.reply_text("ℹ️ Owner တယ်သည့် command အားလုံးပြည့်စုံသုံးနိုင်ပြီးသားပြစ်။")
        return

    permitted = bot.settings.setdefault('owner_permitted_users', [])
    # Normalise to ints
    try:
        permitted_norm = [int(x) for x in permitted]
    except Exception:
        permitted_norm = []
    bot.settings['owner_permitted_users'] = permitted_norm

    label = target_name or f"User {target_id}"
    if int(target_id) in permitted_norm:
        permitted_norm.remove(int(target_id))
        bot.settings['owner_permitted_users'] = permitted_norm
        # Also clear any active spam mute as a courtesy
        tid_str = str(target_id)
        if tid_str in bot.data.get('user_profiles', {}):
            bot.data['user_profiles'][tid_str]['command_mute_until'] = None
            bot.data['user_profiles'][tid_str]['spam_streak_count'] = 0
        bot.save_settings()
        try:
            bot.save_data()
        except Exception:
            pass
        await update.message.reply_text(
            f"🔓 Owner-permit ဖျေထုတ်ပြီးပါပြီ\n"
            f"👤 {label}\n"
            f"🆔 `{target_id}`",
            parse_mode='Markdown'
        )
    else:
        permitted_norm.append(int(target_id))
        bot.settings['owner_permitted_users'] = permitted_norm
        # Clear any active spam mute for them immediately
        tid_str = str(target_id)
        init_user_if_not_exists(tid_str)
        bot.data['user_profiles'][tid_str]['command_mute_until'] = None
        bot.data['user_profiles'][tid_str]['spam_streak_count'] = 0
        bot.save_settings()
        try:
            bot.save_data()
        except Exception:
            pass
        await update.message.reply_text(
            f"✅ Owner-permit ပေးပြီးပါပြီ\n"
            f"👤 {label}\n"
            f"🆔 `{target_id}`\n"
            f"🎟️ command အားလုံးတို ကန့်သတ်မှုမရှိဘဲ သုံးနိုင်ပါပြီ!\n\n"
            f"💡 ပြန်ဖျက်ချင်ပါက /ownp ထပ်ရိုက်ပါ။",
            parse_mode='Markdown'
        )


async def xp_message_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle XP gain from messages"""
    if update.effective_user.is_bot:
        return
    
    # Check if user is gbanned or gmuted
    user_id_int = update.effective_user.id
    if bot.is_gbanned(user_id_int) or bot.is_gmuted(user_id_int):
        return

    user_id = str(update.effective_user.id)
    init_user_if_not_exists(user_id)

    profile = bot.data['user_profiles'][user_id]
    now = datetime.now()

    # Check cooldown
    if profile["last_xp_time"]:
        last_time = datetime.fromisoformat(profile["last_xp_time"])
        if (now - last_time).total_seconds() < XP_COOLDOWN:
            return

    # Grant XP
    # Grant XP (with event multiplier if active)
    xp_gain = XP_PER_MESSAGE
    if is_event_active():
        event = events["active_event"]
        multiplier = event.get("xp_multiplier", 1)
        xp_gain = int(XP_PER_MESSAGE * multiplier)
    profile["xp"] += xp_gain
    profile["last_xp_time"] = now.isoformat()

    # Check level up
    leveled_up = check_level_up(user_id)

    bot.save_data()

    # Notify on level up
    if leveled_up:
        try:
            await update.message.reply_text(
                f"🎉 **Level Up!**\n"
                f"👤 {update.effective_user.first_name}\n"
                f"⭐ New Level: **{profile['level']}**\n"
                f"💰 +100 Coins Reward!",
                parse_mode='Markdown'
            )
        except Exception as e:
            logger.warning(f"Level up notification failed: {e}")

# ==================== BACKUP HELPERS ====================
def _make_backup_zip_bytes() -> bytes:
    """Create a full backup. Frame metadata/file_ids live inside bot.data,
    so Telegram-hosted frames are backed up automatically with the combined JSON.
    """
    mem = io.BytesIO()
    with zipfile.ZipFile(mem, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
        # Add all individual JSON files
        for path in BACKUP_FILES:
            if os.path.exists(path):
                zf.write(path, arcname=os.path.basename(path))
        # Also embed a combined snapshot for maximum recovery safety
        try:
            combined = {
                "bot_data": bot.data,
                "bot_settings": bot.settings,
                "events": events,
                "gold_data": gold_data,
                "backup_time": datetime.now().isoformat(),
                "frame_backup": {
                    "frames": bot.data.get(_ZF_DATA_KEY, {}) if '_ZF_DATA_KEY' in globals() else {},
                    "user_frames": bot.data.get(_ZF_USER_KEY, {}) if '_ZF_USER_KEY' in globals() else {},
                    "equipped_frames": bot.data.get(_ZF_EQUIPPED_KEY, {}) if '_ZF_EQUIPPED_KEY' in globals() else {},
                    "storage": "telegram_file_id"
                },
                "version": "v14-telegram-frames"
            }
            combined_bytes = json.dumps(combined, ensure_ascii=False, indent=2).encode('utf-8')
            zf.writestr("full_backup_combined.json", combined_bytes)
        except Exception as _e:
            logger.warning(f"Combined snapshot failed: {_e}")
    mem.seek(0)
    return mem.read()


def _restore_from_zip_bytes(zip_bytes: bytes) -> list:
    """Restore all JSON files from zip to current directory.
    Returns list of extracted file names."""
    mem = io.BytesIO(zip_bytes)
    extracted = []
    with zipfile.ZipFile(mem, mode="r") as zf:
        out_dir = os.path.dirname(DATA_FILE) if os.path.dirname(DATA_FILE) else "."
        os.makedirs(out_dir, exist_ok=True)
        for name in zf.namelist():
            # Only extract known JSON files (skip combined snapshot - handled separately)
            if name.endswith('.json') and name != 'full_backup_combined.json':
                zf.extract(name, out_dir)
                extracted.append(name)
    return extracted


def _restore_from_combined_json(zip_bytes: bytes) -> bool:
    """Fallback: restore directly from full_backup_combined.json inside zip.
    Returns True if successfully restored."""
    try:
        mem = io.BytesIO(zip_bytes)
        with zipfile.ZipFile(mem, mode="r") as zf:
            if 'full_backup_combined.json' not in zf.namelist():
                return False
            raw = zf.read('full_backup_combined.json')
            combined = json.loads(raw.decode('utf-8'))
        # Write individual JSON files from combined snapshot
        if 'bot_data' in combined:
            with open(DATA_FILE, 'w', encoding='utf-8') as f:
                json.dump(combined['bot_data'], f, ensure_ascii=False, indent=2)
        if 'bot_settings' in combined:
            with open(SETTINGS_FILE, 'w', encoding='utf-8') as f:
                json.dump(combined['bot_settings'], f, ensure_ascii=False, indent=2)
        if 'events' in combined:
            with open(EVENTS_FILE, 'w', encoding='utf-8') as f:
                json.dump(combined['events'], f, ensure_ascii=False, indent=2)
        if 'gold_data' in combined:
            with open(GOLD_FILE, 'w', encoding='utf-8') as f:
                json.dump(combined['gold_data'], f, ensure_ascii=False, indent=2)
            # Reload gold_data in memory
            global gold_data
            gold_data.clear()
            gold_data.update(combined['gold_data'])
        # Older backups may store frame data only in the dedicated frame_backup
        # section. Merge it back into bot_data before the normal reload.
        fb = combined.get("frame_backup") or {}
        if isinstance(combined.get("bot_data"), dict) and isinstance(fb, dict):
            bd = combined["bot_data"]
            if "frames" in fb and "character_frames" not in bd:
                bd["character_frames"] = fb.get("frames") or {}
            if "user_frames" in fb and "user_frames" not in bd:
                bd["user_frames"] = fb.get("user_frames") or {}
            if "equipped_frames" in fb and "equipped_frame" not in bd:
                bd["equipped_frame"] = fb.get("equipped_frames") or {}
            with open(DATA_FILE, 'w', encoding='utf-8') as f:
                json.dump(bd, f, ensure_ascii=False, indent=2)
        return True
    except Exception as _e:
        logger.error(f"Combined JSON restore failed: {_e}")
        return False


def _get_restore_zip_document(message) -> tuple | tuple[None, None]:
    """Return (document, source_label) for restore commands.
    Supports direct zip upload or replying to a zip message.
    """
    if not message:
        return None, None

    direct_doc = getattr(message, 'document', None)
    if direct_doc:
        file_name = str(getattr(direct_doc, 'file_name', '') or '').lower()
        if file_name.endswith('.zip'):
            return direct_doc, '📤 User uploaded zip'

    reply_msg = getattr(message, 'reply_to_message', None)
    reply_doc = getattr(reply_msg, 'document', None) if reply_msg else None
    if reply_doc:
        file_name = str(getattr(reply_doc, 'file_name', '') or '').lower()
        if file_name.endswith('.zip'):
            return reply_doc, '↩️ Replied backup zip'

    return None, None


async def _delete_old_backup_messages(context: ContextTypes.DEFAULT_TYPE):
    """Delete old backups"""
    deleted_count = 0
    
    old_msg_id = bot.settings.get("last_backup_message_id")
    if old_msg_id:
        try:
            await context.bot.delete_message(chat_id=BACKUP_CHANNEL, message_id=int(old_msg_id))
            deleted_count += 1
        except Exception as e:
            logger.warning(f"Failed deleting backup: {e}")
    
    old_card_msg_ids = bot.settings.get("card_backup_message_ids", [])
    for msg_id in old_card_msg_ids:
        try:
            await context.bot.delete_message(chat_id=BACKUP_CHANNEL, message_id=int(msg_id))
            deleted_count += 1
        except Exception as e:
            logger.warning(f"Failed deleting card backup: {e}")
    
    return deleted_count


async def restorefull_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """FULL AUTO RESTORE FROM ZIP — reply to a zip file with /restorefull"""

    global events


    if not bot.is_dev(update.effective_user.id):
        await update.message.reply_text("❌ Dev/Owner only")
        return

    if not update.message.reply_to_message:
        await update.message.reply_text("\U0001f4e6 Backup zip \u1000\u102d\u102f reply \u101c\u102f\u1015\u103e\u102c\u1038")
        return

    doc = update.message.reply_to_message.document

    if not doc or not doc.file_name.endswith(".zip"):
        await update.message.reply_text("\u274c Zip file reply \u101c\u102f\u1015\u103e\u102c\u1038")
        return

    try:
        await update.message.reply_text("\U0001f504 Full Auto Restore \u1005\u1010\u1004\u103a\u1014\u1031\u101e\u100a\u103a...")

        file = await context.bot.get_file(doc.file_id)
        zip_bytes = bytes(await file.download_as_bytearray())

        # Validate zip
        try:
            test_mem = io.BytesIO(zip_bytes)
            with zipfile.ZipFile(test_mem, 'r') as ztest:
                names = ztest.namelist()
        except Exception as e:
            await update.message.reply_text(f"\u274c Invalid zip file:\n{e}")
            return

        await update.message.reply_text(
            f"\U0001f4e6 Zip loaded\u2014Contains: {', '.join(names)}\n"
            f"\U0001f9e0 Injecting data..."
        )

        # Safety snapshot
        try:
            bot.save_data()
            bot.save_settings()
            save_events()
            for fpath in [DATA_FILE, SETTINGS_FILE, ECONOMY_FILE, MISSIONS_FILE, EVENTS_FILE]:
                if os.path.exists(fpath):
                    shutil.copy(fpath, fpath + ".pre_restorefull_bak")
        except Exception as e:
            logger.warning(f"Pre-restorefull safety snapshot failed (non-critical): {e}")

        # ================= FULL RESTORE FIRST =================
        success = _restore_from_combined_json(zip_bytes)

        if success:
            bot.data = bot.load_data()
            bot.settings = bot.load_settings()

            try:
                new_events = load_events()
                events.clear()
                events.update(new_events)
            except Exception as e:
                logger.error(f"Reload events after restorefull failed: {e}")

            # Patch missing keys
            _defaults_data = {
                'users': {}, 'cards': {}, 'user_profiles': {},
                'character_frames': {}, 'user_frames': {}, 'equipped_frame': {},
                'next_id': 1, 'group_counters': {}, 'active_groups': [],
                'last_claims': {}, 'group_drop_counters': {},
                'dropped_cards': {}, 'card_message_ids': {}
            }
            for k, v in _defaults_data.items():
                if k not in bot.data:
                    bot.data[k] = v

            _defaults_settings = {
                'admins': OWNERS.copy(), 'database_channel': None,
                'drop_channel': None, 'drop_threshold': 50,
                'sudo_users': [], 'dev_users': [],
                'gbanned_users': {}, 'gmuted_users': {},
                'last_backup_message_id': None,
                'last_backup_file_id': None,
                'card_backup_message_ids': []
            }
            for k, v in _defaults_settings.items():
                if k not in bot.settings:
                    bot.settings[k] = v

            _profile_defaults = {
                "bank": 0, "last_daily": None, "last_interest": None,
                "event_coins": 0, "xp": 0, "level": 1, "coins": 0,
                "last_xp_time": None
            }
            for uid, profile in bot.data.get('user_profiles', {}).items():
                for fk, fv in _profile_defaults.items():
                    if fk not in profile:
                        profile[fk] = fv

            try:
                bot.save_data()
                bot.save_settings()
                save_events()
            except Exception as e:
                logger.warning(f"Save after restorefull failed: {e}")

            total_cards = len(bot.data.get('cards', {}))
            cards_with_media = sum(
                1 for c in bot.data.get('cards', {}).values()
                if c.get('image') or c.get('video')
            )

            # 🔧 Restore custom roles (setrole) from bot.settings -> in-memory ROLES dict
            try:
                if '_ms_restore_custom_roles' in globals():
                    _ms_restore_custom_roles()
            except Exception as _rr_e:
                logger.warning(f"Custom-role restore failed (non-critical): {_rr_e}")

            # Re-register any role-search command handler for restored custom roles
            try:
                _app_ref = context.application
                if _app_ref is not None and 'role_search_cmd' in globals():
                    _custom_now = (bot.settings.get("custom_roles") or {})
                    for _rk in list(_custom_now.keys()):
                        try:
                            _app_ref.add_handler(CommandHandler(_rk, role_search_cmd))
                        except Exception:
                            pass
            except Exception:
                pass

            await update.message.reply_text(
                f"\U0001f525 FULL AUTO RESTORE SUCCESS!\n\n"
                f"\U0001f465 Users: {len(bot.data.get('users', {}))} \u2714\n"
                f"\U0001f3b4 Cards: {total_cards} (\U0001f4f8 media: {cards_with_media}) \u2714\n"
                f"\U0001f4b0 Coins \u2714\n"
                f"\U0001f3e6 Bank \u2714\n"
                f"\u2b50 XP \u2714\n"
                f"\U0001f3c6 Levels \u2714\n"
                f"\U0001f383 Events \u2714\n"
                f"\U0001f3ad Custom Roles \u2714\n\n"
                f"\U0001f680 No Bot Restart needed!"
            )
            return

        # ================= FALLBACK: Normal zip extract =================
        try:
            extracted = _restore_from_zip_bytes(zip_bytes)
        except Exception as e:
            await update.message.reply_text(f"\u274c Restore Failed:\n{e}")
            return

        bot.data = bot.load_data()
        bot.settings = bot.load_settings()

        try:
            new_events = load_events()
            events.clear()
            events.update(new_events)
        except Exception as e:
            logger.error(f"Reload events after restorefull fallback failed: {e}")

        total_cards = len(bot.data.get('cards', {}))
        cards_with_media = sum(
            1 for c in bot.data.get('cards', {}).values()
            if c.get('image') or c.get('video')
        )

        # 🔧 Restore custom roles (setrole) — fallback path
        try:
            if '_ms_restore_custom_roles' in globals():
                _ms_restore_custom_roles()
        except Exception as _rr_e:
            logger.warning(f"Custom-role restore (fallback) failed: {_rr_e}")
        try:
            _app_ref = context.application
            if _app_ref is not None and 'role_search_cmd' in globals():
                _custom_now = (bot.settings.get("custom_roles") or {})
                for _rk in list(_custom_now.keys()):
                    try:
                        _app_ref.add_handler(CommandHandler(_rk, role_search_cmd))
                    except Exception:
                        pass
        except Exception:
            pass

        await update.message.reply_text(
            f"\u26a0\ufe0f Combined backup မတွေ့ပါ — Normal Restore Done:\n"
            f"\U0001f4c2 Extracted: {', '.join(extracted) if extracted else 'none'}\n\n"
            f"\U0001f465 Users: {len(bot.data.get('users', {}))} \u2714\n"
            f"\U0001f3b4 Cards: {total_cards} (\U0001f4f8 media: {cards_with_media}) \u2714\n"
            f"\U0001f3c6 Levels & XP \u2714\n"
            f"\U0001f383 Events \u2714\n"
            f"\U0001f3ad Custom Roles \u2714"
        )

    except Exception as e:
        logger.error(f"restorefull_cmd error: {e}")
        await update.message.reply_text(f"\u274c Restore Failed:\n{e}")


