# (Referral helpers removed)

def _give_card_by_rarity(rarity_key: str, user_id_str: str) -> str | None:
    """Give a random card of given rarity to user. Returns card_id or None."""
    pool = [cid for cid, c in bot.data.get("cards", {}).items()
            if c and str(c.get("rarity", "1")) == rarity_key
            and c.get("drop_enabled", True)]
    if not pool:
        return None
    card_id = random.choice(pool)
    bot.data["users"].setdefault(user_id_str, [])
    bot.data["users"][user_id_str].append(card_id)
    return card_id


async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Premium /start — Welcome Video/Photo + Caption + Inline Buttons.

    Owner can change the welcome media via /setwcl (reply photo/video)
    and the Help link via /sethelp <url>. Both persist across restarts
    via bot.settings (bot_settings.json) and a mirror in settings.json.
    """
    user = update.effective_user
    if not user or not update.message:
        return
    try:
        update_name_cache(user)
    except Exception:
        pass

    # Resolve bot username for the Add-Group deep link
    try:
        me = await context.bot.get_me()
        bot_username = me.username or "this_bot"
    except Exception:
        bot_username = "this_bot"

    # ----- Welcome caption (exact format requested) -----
    caption = (
        "╔════════════════════╗\n"
        "     ✦ SYSTEM ONLINE ✦\n"
        "╚════════════════════╝\n\n"
        f"Welcome Back, {user.first_name}\n\n"
        "▰ Account Status  : Active\n"
        "▰ Collection Mode : Ready\n"
        "▰ Missions Status : Available\n"
        "▰ Event Status    : Live\n\n"
        "━━━━━━━━━━━━━━━━\n"
        "「 Choose Your Path 」\n"
        "━━━━━━━━━━━━━━━━"
    )

    # ----- Settings (welcome media + help link) -----
    try:
        media_id   = bot.settings.get("welcome_media", "") or ""
        media_type = (bot.settings.get("welcome_type", "") or "").lower()
        help_link  = bot.settings.get("help_link", "") or ""
    except Exception:
        media_id, media_type, help_link = "", "", ""

    add_group_link = f"https://t.me/{bot_username}?startgroup=true"

    # ----- Inline buttons -----
    rows = [
        [
            InlineKeyboardButton("🎯 Start",    callback_data="psui|main"),
            InlineKeyboardButton("📋 Missions", callback_data="psui|missions"),
        ],
        [InlineKeyboardButton("➕ Add Your Group", url=add_group_link)],
    ]
    if isinstance(help_link, str) and help_link.strip().lower().startswith(
        ("http://", "https://", "tg://", "t.me/")
    ):
        rows.append([InlineKeyboardButton("❓ Help", url=help_link.strip())])
    else:
        rows.append([InlineKeyboardButton("❓ Help", callback_data="psui|help_unset")])
    kb = InlineKeyboardMarkup(rows)

    # ----- Send: try media first, fallback to text -----
    sent_ok = False
    if media_id and media_type in ("video", "photo"):
        try:
            if media_type == "video":
                await update.message.reply_video(
                    video=media_id, caption=caption, reply_markup=kb
                )
            else:
                await update.message.reply_photo(
                    photo=media_id, caption=caption, reply_markup=kb
                )
            sent_ok = True
        except Exception as e:
            try:
                logger.error(f"[premium-start] media send failed: {e}")
            except Exception:
                pass

    if not sent_ok:
        try:
            await update.message.reply_text(caption, reply_markup=kb)
        except Exception:
            pass


