# ══════════════════════════════════════════════════════════════
#  FAVORITES (FAV) — Helper
# ══════════════════════════════════════════════════════════════

def _get_user_fav_entry(user_id_str: str):
    """Return normalized favorite entry.
    Backward compatible with old favorites format that stored only card id."""
    raw = bot.data.get('favorites', {}).get(str(user_id_str))
    if raw is None:
        return None

    if isinstance(raw, dict):
        card_id = raw.get('card_id') or raw.get('id') or raw.get('card')
        if not card_id:
            return None
        return {
            'card_id': str(card_id),
            'image': raw.get('image'),
            'video': raw.get('video'),
            'video_type': raw.get('video_type'),
            'type': raw.get('type'),
        }

    return {'card_id': str(raw)}


def _get_user_fav_id(user_id_str: str):
    entry = _get_user_fav_entry(user_id_str)
    return entry.get('card_id') if entry else None


def _build_favorite_snapshot(card_id_str: str):
    card = bot.data.get('cards', {}).get(str(card_id_str))
    if not card:
        return None
    return {
        'card_id': str(card_id_str),
        'image': card.get('image'),
        'video': card.get('video'),
        'video_type': card.get('video_type'),
        'type': card.get('type'),
    }


def _set_user_fav_id(user_id_str: str, card_id_str: str | None, fav_snapshot: dict | None = None):
    bot.data.setdefault('favorites', {})
    if card_id_str is None:
        bot.data['favorites'].pop(str(user_id_str), None)
    else:
        snapshot = fav_snapshot or _build_favorite_snapshot(str(card_id_str)) or {}
        snapshot['card_id'] = str(card_id_str)
        bot.data['favorites'][str(user_id_str)] = snapshot


async def send_favorite_in_harem(message, user, card_id_str: str, fav_entry: dict | None = None):
    """Send saved favorite media (photo/video) before /harem list.
    Uses stored favorite media snapshot first so /harem can still show the same
    favorite photo/video without crashing even if card media changes later."""
    card = bot.data.get('cards', {}).get(str(card_id_str), {})
    fav_entry = fav_entry or {}

    image = fav_entry.get('image') or card.get('image')
    video = fav_entry.get('video') or card.get('video')
    media_type = fav_entry.get('type') or card.get('type')
    video_type = fav_entry.get('video_type') or card.get('video_type')

    if not card and not image and not video:
        return

    rarity = str(card.get('rarity', '1'))
    rarity_info = RARITIES.get(rarity, RARITIES['1'])
    role_info = get_role_info(card)

    mention = _mention_md(user.id, user.first_name)
    caption = (
        f"╭━━━〔 💖 FAVORITE CARD 〕━━━╮\n"
        f"👤 Player : {mention}\n"
        f"🎬 Anime  : {_md_escape(card.get('movie',''))}\n"
        f"🆔 ID     : {card.get('id', card_id_str)}\n"
        f"🌟 Name   : {_md_escape(card.get('name',''))}\n"
        f"⚜ Rarity : {rarity_info['display']}\n"
        f"🎭 Role   : {role_info['display']}\n"
        f"╰━━━━━━━━━━━━━━━━━━━━╯"
    )

    try:
        if media_type == 'video' and video:
            if video_type == 'video':
                await message.reply_video(video=video, caption=caption, parse_mode='Markdown')
            else:
                await message.reply_document(document=video, caption=caption, parse_mode='Markdown')
        elif image:
            _framed = await _zf_get_card_image(image, user.id, message.get_bot())
            await message.reply_photo(photo=_framed or image, caption=caption, parse_mode='Markdown')
        elif video:
            if video_type == 'video':
                await message.reply_video(video=video, caption=caption, parse_mode='Markdown')
            else:
                await message.reply_document(document=video, caption=caption, parse_mode='Markdown')
        else:
            await message.reply_text(caption, parse_mode='Markdown')
    except Exception as e:
        logger.error(f"Send favorite in harem failed: {e}")
        try:
            await message.reply_text(caption, parse_mode='Markdown')
        except Exception:
            pass


# ═════════════════════════════════════════════════════════════
#  HAREM — build text + media for combined favorite-in-harem view
# ═════════════════════════════════════════════════════════════
def _build_harem_anime_text(user, page: int):
    """Build harem list text in anime-grouped format and return (text, reply_markup, max_page).
    Format example:
        💖 Favorite : Keisuke Baji

        🎴 USER HAREM
        📖 Page 1/N

        📚 Tokyo Revengers [1/12]
        🎗 1619 🔮 Keisuke Baji ×1
        ...
    """
    from collections import Counter, OrderedDict
    user_id_str = str(user.id)
    user_cards = bot.data.get('users', {}).get(user_id_str, [])
    total = len(user_cards)

    if total == 0:
        return None, None, 0

    card_counts = Counter(user_cards)

    # Group unique cards by anime/movie
    anime_groups: "OrderedDict[str, list]" = OrderedDict()
    rarity_summary: dict = {}
    power = 0
    animated_count = 0
    video_count = 0

    # First pass: rarity stats + power
    for cid, count in card_counts.items():
        card = bot.data['cards'].get(str(cid))
        if not card:
            continue
        rarity = card.get('rarity', '1')
        rarity_info = RARITIES.get(rarity, RARITIES['1'])
        power += rarity_info['value'] * count
        rarity_summary[rarity] = rarity_summary.get(rarity, 0) + count
        if rarity == '15':
            animated_count += count
        if card.get('type') == 'video':
            video_count += count

    # Build sorted unique list (by rarity desc) so groups still show best first
    def _rv(cid):
        c = bot.data['cards'].get(str(cid))
        if not c:
            return 0
        return RARITIES.get(c.get('rarity', '1'), RARITIES['1'])['value']

    unique_sorted = sorted(card_counts.keys(), key=_rv, reverse=True)

    for cid in unique_sorted:
        card = bot.data['cards'].get(str(cid))
        if not card:
            continue
        anime = (card.get('movie') or card.get('anime') or 'Unknown').strip() or 'Unknown'
        anime_groups.setdefault(anime, []).append(cid)

    anime_list = list(anime_groups.keys())
    total_animes = len(anime_list)

    # Paginate by anime groups: 3 anime groups per page (premium feel)
    GROUPS_PER_PAGE = 3
    max_page = max(0, (total_animes - 1) // GROUPS_PER_PAGE)
    page = max(0, min(page, max_page))

    start_idx = page * GROUPS_PER_PAGE
    end_idx = min(start_idx + GROUPS_PER_PAGE, total_animes)
    page_anime_names = anime_list[start_idx:end_idx]

    # Profile / level
    profile = bot.data.get('user_profiles', {}).get(user_id_str, {})
    level = profile.get("level", 1)

    # Favorite (if any)
    fav_id = _get_user_fav_id(user_id_str)
    fav_name = None
    if fav_id:
        owned = bot.data.get('users', {}).get(user_id_str, [])
        if str(fav_id) in owned:
            fcard = bot.data['cards'].get(str(fav_id), {})
            fav_name = fcard.get('name') or None

    # ━━━━━ BUILD TEXT ━━━━━
    lines = []
    if fav_name:
        lines.append(f"💖 Favorite : {fav_name}")
        lines.append("")

    lines.append("🎴 USER HAREM")
    lines.append(f"📖 Page {page+1}/{max_page+1}")
    lines.append("")

    lines.append(f"👤 Player: {user.first_name}")
    lines.append(f"🏆 Level: {level}")
    lines.append(f"💪 Power: {power:,}")
    lines.append(f"🎴 Total: {total}  •  🎯 Unique: {len(card_counts)}  •  🎬 Animes: {total_animes}")
    if animated_count > 0:
        lines.append(f"⚡ Animated: {animated_count}")
    if video_count > 0:
        lines.append(f"🎥 Video Cards: {video_count}")
    lines.append("")

    # Anime grouped listing
    for anime in page_anime_names:
        cids = anime_groups[anime]
        # owned unique count for this anime
        owned_unique_in_anime = len(cids)
        # total unique cards of this anime in DB (for [x/y] label)
        total_in_db = sum(
            1 for _cid, _c in bot.data.get('cards', {}).items()
            if ((_c.get('movie') or _c.get('anime') or 'Unknown').strip() or 'Unknown') == anime
        )
        if total_in_db <= 0:
            total_in_db = owned_unique_in_anime

        lines.append(f"📚 {anime} [{owned_unique_in_anime}/{total_in_db}]")
        for cid in cids:
            card = bot.data['cards'].get(str(cid))
            if not card:
                continue
            count = card_counts[cid]
            rarity = card.get('rarity', '1')
            rarity_info = RARITIES.get(rarity, RARITIES['1'])
            type_tag = " 🎥" if card.get('type') == 'video' else ""
            lines.append(
                f"🎗 {card.get('id', cid)} {rarity_info['emoji']}{type_tag} {card.get('name','')} ×{count}"
            )
        lines.append("")

    text = "\n".join(lines).rstrip()

    # ━━━━━ NAVIGATION ━━━━━
    keyboard = []
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton("⬅️ Back", callback_data=f"harem_list_{page-1}"))
    nav.append(InlineKeyboardButton(f"📄 {page+1}/{max_page+1}", callback_data="harem_info"))
    if page < max_page:
        nav.append(InlineKeyboardButton("Next ➡️", callback_data=f"harem_list_{page+1}"))
    if nav:
        keyboard.append(nav)

    action_row = [
        InlineKeyboardButton("🔝 Top Rare", callback_data="harem_list_0"),
        InlineKeyboardButton("💎 Stats", callback_data="harem_stats"),
    ]
    keyboard.append(action_row)

    inline_row = [
        InlineKeyboardButton(
            "🔍 Inline View Cards",
            switch_inline_query_current_chat=str(user.id),
        )
    ]
    keyboard.append(inline_row)

    reply_markup = InlineKeyboardMarkup(keyboard) if keyboard else None
    return text, reply_markup, max_page


async def send_favorite_with_harem(message, user, card_id_str: str, fav_entry: dict | None,
                                   page: int = 0):
    """Send ONE combined message: favorite media (photo/video) whose CAPTION carries
    the anime-grouped harem list + Next/Back + Stats inline keyboard.
    Falls back to plain text if there is no usable media or caption is too long.
    """
    card = bot.data.get('cards', {}).get(str(card_id_str), {})
    fav_entry = fav_entry or {}

    image = fav_entry.get('image') or card.get('image')
    video = fav_entry.get('video') or card.get('video')
    media_type = fav_entry.get('type') or card.get('type')
    video_type = fav_entry.get('video_type') or card.get('video_type')

    # Build the combined harem text (acts as caption)
    text, reply_markup, _max_page = _build_harem_anime_text(user, page)
    if text is None:
        await message.reply_text("😢 ကဒ်မရှိပါ")
        return

    # Telegram caption hard limit is 1024 chars. If too long, send media + short caption
    # and follow up with full text as a separate message (still with the keyboard).
    CAPTION_LIMIT = 1024
    use_caption = text if len(text) <= CAPTION_LIMIT else None

    sent_media = False
    try:
        if media_type == 'video' and video:
            if video_type == 'video':
                await message.reply_video(
                    video=video,
                    caption=use_caption or "🎴 USER HAREM",
                    reply_markup=reply_markup if use_caption else None,
                )
            else:
                await message.reply_document(
                    document=video,
                    caption=use_caption or "🎴 USER HAREM",
                    reply_markup=reply_markup if use_caption else None,
                )
            sent_media = True
        elif image:
            # Equipped frame is composited onto the character art here too.
            _framed = await _zf_get_card_image(image, user.id, message.get_bot())
            await message.reply_photo(
                photo=_framed or image,
                caption=use_caption or "🎴 USER HAREM",
                reply_markup=reply_markup if use_caption else None,
            )
            sent_media = True
        elif video:
            if video_type == 'video':
                await message.reply_video(
                    video=video,
                    caption=use_caption or "🎴 USER HAREM",
                    reply_markup=reply_markup if use_caption else None,
                )
            else:
                await message.reply_document(
                    document=video,
                    caption=use_caption or "🎴 USER HAREM",
                    reply_markup=reply_markup if use_caption else None,
                )
            sent_media = True
    except Exception as e:
        logger.error(f"send_favorite_with_harem media failed: {e}")
        sent_media = False

    # If caption too long OR media send failed → send full text separately so keyboard works
    if not sent_media or use_caption is None:
        try:
            await message.reply_text(text, reply_markup=reply_markup)
        except Exception as e:
            logger.error(f"send_favorite_with_harem text fallback failed: {e}")


# ══════════════════════════════════════════════════════════════
#  HAREM JOIN PROTECTION — Helper
# ══════════════════════════════════════════════════════════════
async def check_user_joined(context, user_id: int, chat_username: str) -> bool:
    """
    Verify whether *user_id* is a member of *chat_username*.
    Returns True if joined (or if the check cannot be performed).
    """
    try:
        member = await context.bot.get_chat_member(chat_username, user_id)
        # left / kicked → not a member
        return member.status not in ("left", "kicked")
    except Exception:
        # If we can't check (bot not in chat, etc.) we allow the user through
        return True


async def harem(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show collection — requires user to join the configured channel/group first"""
    user = update.effective_user
    user_id_str = str(user.id)

    # ── Harem Join Protection Check ──
    harem_channel = bot.settings.get('harem_channel')   # e.g.  "@mychannel"
    harem_group   = bot.settings.get('harem_group')     # e.g.  "@mygroup"

    not_joined = []

    if harem_channel:
        if not await check_user_joined(context, user.id, harem_channel):
            not_joined.append(f"📢 Channel: {harem_channel}")

    if harem_group:
        if not await check_user_joined(context, user.id, harem_group):
            not_joined.append(f"👥 Group: {harem_group}")

    if not_joined:
        # Build "join first" message with inline buttons
        buttons = []
        if harem_channel and not await check_user_joined(context, user.id, harem_channel):
            buttons.append([InlineKeyboardButton(
                "📢 Channel Join", url=f"https://t.me/{harem_channel.lstrip('@')}"
            )])
        if harem_group and not await check_user_joined(context, user.id, harem_group):
            buttons.append([InlineKeyboardButton(
                "👥 Group Join", url=f"https://t.me/{harem_group.lstrip('@')}"
            )])

        join_list = "\n".join(not_joined)
        await update.message.reply_text(
            f"🔒 **Harem Access Denied!**\n\n"
            f"Harem command သုံးရန် အောက်ပါ channel/group တွင် Join ဖြစ်ရပါမည်:\n\n"
            f"{join_list}\n\n"
            f"Join ပြီးမှ /harem ထပ်ကြိုးစားပါ။",
            parse_mode='Markdown',
            reply_markup=InlineKeyboardMarkup(buttons) if buttons else None
        )
        return
    # ── End Join Check ──

    if user_id_str not in bot.data['users'] or not bot.data['users'][user_id_str]:
        await update.message.reply_text("😢 မင်းမှာကဒ်မရှိသေးဘူး")
        return

    # 💖 Favorite + harem list → COMBINED into ONE message (media caption carries the list)
    fav_entry = _get_user_fav_entry(user_id_str)
    fav_id = _get_user_fav_id(user_id_str)
    fav_has_media = False
    if fav_id:
        owned = bot.data.get('users', {}).get(user_id_str, [])
        if str(fav_id) in owned:
            # Migrate old favorite data (id only) to saved media snapshot automatically
            if fav_entry and not fav_entry.get('image') and not fav_entry.get('video'):
                _set_user_fav_id(user_id_str, str(fav_id), _build_favorite_snapshot(str(fav_id)))
                fav_entry = _get_user_fav_entry(user_id_str)
                try:
                    bot.save_data()
                except Exception:
                    pass
            _card_for_fav = bot.data.get('cards', {}).get(str(fav_id), {})
            _img = (fav_entry or {}).get('image') or _card_for_fav.get('image')
            _vid = (fav_entry or {}).get('video') or _card_for_fav.get('video')
            fav_has_media = bool(_img or _vid)
        else:
            # auto-remove if not owned anymore
            _set_user_fav_id(user_id_str, None)
            fav_id = None
            fav_entry = None
            try:
                bot.save_data()
            except Exception:
                pass

    if fav_id and fav_has_media:
        # ✨ Combined: favorite photo/video with harem list as caption + inline keyboard
        await send_favorite_with_harem(update.message, user, str(fav_id), fav_entry, page=0)
    else:
        # No favorite media → plain anime-grouped harem list
        await show_harem_list(update.message, user, page=0)


async def show_harem_list(message, user, page: int):
    """Show paginated harem in ANIME-GROUPED format.
    Uses _build_harem_anime_text() so the layout matches the combined favorite-in-harem view.
    """
    text, reply_markup, _max_page = _build_harem_anime_text(user, page)
    if text is None:
        await message.reply_text("😢 ကဒ်မရှိပါ")
        return

    # If the previous message was a media message (photo/video with caption),
    # edit_text() will fail — fall back to sending a fresh text message.
    try:
        await message.edit_text(text, reply_markup=reply_markup)
    except Exception:
        try:
            await message.edit_caption(caption=text, reply_markup=reply_markup)
        except Exception:
            await message.reply_text(text, reply_markup=reply_markup)


async def harem_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Harem pagination callback with enhanced features"""
    query = update.callback_query
    
    data = query.data
    
    # Handle pagination
    if data.startswith("harem_list_"):
        await query.answer()
        page = int(data.split("_")[2])
        await show_harem_list(query.message, query.from_user, page)
    
    # Handle info button
    elif data == "harem_info":
        await query.answer("📊 Navigate using ⬅️ ➡️ buttons!", show_alert=False)
    
    # Handle stats button
    elif data == "harem_stats":
        await query.answer()
        await show_harem_stats(query.message, query.from_user)


async def show_harem_stats(message, user):
    """Show detailed harem statistics"""
    user_id_str = str(user.id)
    user_cards = bot.data.get('users', {}).get(user_id_str, [])
    
    if not user_cards:
        await message.edit_text("😢 ကဒ်မရှိပါ")
        return
    
    from collections import Counter
    card_counts = Counter(user_cards)
    
    # Calculate detailed stats
    total_power = 0
    rarity_breakdown = {}
    video_count = 0
    
    for cid, count in card_counts.items():
        card = bot.data['cards'].get(str(cid))
        if not card:
            continue
        
        rarity = card.get('rarity', '1')
        rarity_info = RARITIES.get(rarity, RARITIES['1'])
        
        total_power += rarity_info['value'] * count
        
        if rarity not in rarity_breakdown:
            rarity_breakdown[rarity] = {'count': 0, 'power': 0}
        
        rarity_breakdown[rarity]['count'] += count
        rarity_breakdown[rarity]['power'] += rarity_info['value'] * count
        
        if card.get('type') == 'video':
            video_count += count
    
    # Get user profile
    profile = bot.data.get('user_profiles', {}).get(user_id_str, {})
    level = profile.get("level", 1)
    
    # Build stats message
    text = "━━━━━━━━━━━━━━━━━━\n"
    text += "📈 HAREM STATISTICS\n"
    text += "━━━━━━━━━━━━━━━━━━\n\n"
    
    text += f"👤 Player: {user.first_name}\n"
    text += f"🏆 Level: {level}\n"
    text += f"💪 Total Power: {total_power:,}\n"
    text += f"🎴 Total Cards: {len(user_cards)}\n"
    text += f"🎯 Unique Cards: {len(card_counts)}\n"
    text += f"🎥 Video Cards: {video_count}\n\n"
    
    text += "━━━━━━━━━━━━━━━━━━\n"
    text += "💎 RARITY BREAKDOWN\n"
    text += "━━━━━━━━━━━━━━━━━━\n\n"
    
    # Sort by rarity value
    sorted_rarities = sorted(
        rarity_breakdown.items(),
        key=lambda x: RARITIES.get(x[0], RARITIES['1'])['value'],
        reverse=True
    )
    
    for rarity, stats in sorted_rarities:
        rarity_info = RARITIES.get(rarity, RARITIES['1'])
        percentage = (stats['count'] / len(user_cards)) * 100
        text += f"{rarity_info['emoji']} {rarity_info['name']}\n"
        text += f"   ├ Cards: {stats['count']} ({percentage:.1f}%)\n"
        text += f"   └ Power: {stats['power']:,}\n\n"
    
    text += "━━━━━━━━━━━━━━━━━━"
    
    # Back button
    keyboard = [[InlineKeyboardButton("⬅️ Back to Harem", callback_data="harem_list_0")]]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    try:
        await message.edit_text(text, reply_markup=reply_markup)
    except:
        await message.reply_text(text, reply_markup=reply_markup)

# ==================== GIFT ====================

# In-memory pending gift transfers awaiting Yes/No confirmation.
# Key: confirmation message_id -> dict(sender, receiver, card_id, chat_id)
PENDING_GIFTS = {}
# In-memory pending favorite changes awaiting Yes/No confirmation.
PENDING_FAVS = {}


async def gift(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/gift <card_id> (reply) — Yes/No ခလုပ်ပါသည်။
    ချက်ထေသော ထပ်ဆောင်း message မရောက်ဘဲ inline button ႃတယ်။"""
    if not update.message.reply_to_message:
        await update.message.reply_text("❌ User message ကို reply လုပ်ပါ")
        return
    
    if not context.args:
        await update.message.reply_text("📝 /gift <card_id> (reply)")
        return
    
    card_id = context.args[0]
    sender = update.effective_user
    sender_id_str = str(sender.id)
    receiver = update.message.reply_to_message.from_user
    receiver_id_str = str(receiver.id)

    if receiver.is_bot:
        await update.message.reply_text("❌ Bot ကို gift မပေးနိုင်ပါ")
        return

    if sender.id == receiver.id:
        await update.message.reply_text("❌ ကိုယ်ကိုသုံ gift မပေးနိုင်ပါ")
        return
    
    if card_id not in bot.data['cards']:
        await update.message.reply_text("❌ Card မရှိပါ")
        return
    
    if sender_id_str not in bot.data['users'] or card_id not in bot.data['users'][sender_id_str]:
        await update.message.reply_text("❌ မင်းမှာ ဒီ card မရှိပါ")
        return

    card = bot.data['cards'][card_id]
    rarity = str(card.get('rarity', '1'))
    rarity_info = RARITIES.get(rarity, RARITIES['1'])

    sender_mention = _html_mention(sender.id, sender.first_name)
    receiver_mention = _html_mention(receiver.id, receiver.first_name)

    confirm_text = (
        f"🎁 <b>Gift Confirm</b>\n\n"
        f"📤 From: {sender_mention}\n"
        f"📥 To: {receiver_mention}\n\n"
        f"🆔 Card ID: <code>{card.get('id', card_id)}</code>\n"
        f"🎴 Name: {_html_escape(card.get('name',''))}\n"
        f"🎬 Movie: {_html_escape(card.get('movie',''))}\n"
        f"⭐ Rarity: {_html_escape(rarity_info['display'])}\n\n"
        f"❔ {sender_mention} — ဒီကဒ်ကို ပေးမလား？"
    )

    kb = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ Yes", callback_data="gift_confirm|yes"),
        InlineKeyboardButton("❌ No",  callback_data="gift_confirm|no"),
    ]])

    sent = await update.message.reply_text(
        confirm_text, parse_mode='HTML',
        reply_markup=kb, disable_web_page_preview=True
    )

    PENDING_GIFTS[sent.message_id] = {
        'sender_id': sender.id,
        'sender_name': sender.first_name,
        'receiver_id': receiver.id,
        'receiver_name': receiver.first_name,
        'card_id': card_id,
        'chat_id': sent.chat_id,
        'created_at': time.time(),
    }


async def gift_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Yes/No inline button for /gift."""
    query = update.callback_query
    try:
        _prefix, choice = query.data.split('|', 1)
    except Exception:
        await query.answer()
        return

    pending = PENDING_GIFTS.get(query.message.message_id)
    if not pending:
        await query.answer("⏳ Expired or unknown gift.", show_alert=True)
        return

    # Only the original sender can press Yes/No
    if query.from_user.id != pending['sender_id']:
        await query.answer("⛔ ဒီခလုပ်ကို ထိုသူတင် နှိပ်နိုင်ပါသည်။", show_alert=True)
        return

    if choice == 'no':
        PENDING_GIFTS.pop(query.message.message_id, None)
        await query.answer("❌ Cancelled")
        try:
            await query.edit_message_text("❌ <b>Gift Cancelled</b>", parse_mode='HTML')
        except Exception:
            pass
        return

    # choice == yes
    sender_id_str = str(pending['sender_id'])
    receiver_id_str = str(pending['receiver_id'])
    card_id = pending['card_id']

    # Re-validate (state may have changed)
    if card_id not in bot.data['cards']:
        PENDING_GIFTS.pop(query.message.message_id, None)
        await query.answer("❌ Card no longer exists.", show_alert=True)
        return
    if card_id not in bot.data['users'].get(sender_id_str, []):
        PENDING_GIFTS.pop(query.message.message_id, None)
        await query.answer("❌ ဒီ card မရှိတော့ပါ။", show_alert=True)
        return

    # Transfer
    bot.data['users'][sender_id_str].remove(card_id)
    if receiver_id_str not in bot.data['users']:
        bot.data['users'][receiver_id_str] = []
    bot.data['users'][receiver_id_str].append(card_id)

    bot.data['cards'][card_id]['owner'] = pending['receiver_id']
    bot.data['cards'][card_id]['owner_name'] = pending['receiver_name']

    # Auto-clear favorite if sender no longer owns it
    fav_id = _get_user_fav_id(sender_id_str)
    if fav_id == str(card_id) and card_id not in bot.data['users'][sender_id_str]:
        _set_user_fav_id(sender_id_str, None)

    try:
        bot.save_data()
    except Exception:
        pass

    PENDING_GIFTS.pop(query.message.message_id, None)

    card = bot.data['cards'][card_id]
    rarity = str(card.get('rarity', '1'))
    rarity_info = RARITIES.get(rarity, RARITIES['1'])

    sender_mention = _html_mention(pending['sender_id'], pending['sender_name'])
    receiver_mention = _html_mention(pending['receiver_id'], pending['receiver_name'])

    caption = (
        f"🎁 <b>Gift Success!</b>\n\n"
        f"📤 From: {sender_mention}\n"
        f"📥 To: {receiver_mention}\n\n"
        f"🎴 {_html_escape(card.get('name',''))}\n"
        f"🎬 {_html_escape(card.get('movie',''))}\n"
        f"🆔 ID: <code>{card.get('id', card_id)}</code>\n"
        f"⭐ {_html_escape(rarity_info['display'])}"
    )

    await query.answer("✅ Gifted!")
    try:
        await query.edit_message_text(caption, parse_mode='HTML', disable_web_page_preview=True)
    except Exception:
        try:
            await query.message.reply_text(caption, parse_mode='HTML')
        except Exception:
            pass


async def _pick_fuse_reward_card(source_rarity: str):
    """Pick a random reward card with higher rarity.
    Prefer the immediate next rarity if available; otherwise any unlocked higher rarity."""
    locked_rarities = {str(r) for r in bot.settings.get('locked_rarities', [])}
    try:
        source_value = int(str(source_rarity))
    except Exception:
        return None

    next_rarity = str(source_value + 1)
    exact_pool = [
        cid for cid, card in bot.data.get('cards', {}).items()
        if str(card.get('rarity', '1')) == next_rarity and str(card.get('rarity', '1')) not in locked_rarities
    ]
    if exact_pool:
        return random.choice(exact_pool)

    higher_pool = []
    for cid, card in bot.data.get('cards', {}).items():
        rarity_key = str(card.get('rarity', '1'))
        if rarity_key in locked_rarities:
            continue
        try:
            rarity_value = int(rarity_key)
        except Exception:
            continue
        if rarity_value > source_value:
            higher_pool.append(cid)

    if not higher_pool:
        return None
    return random.choice(higher_pool)


async def fuse_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Fuse 3 same-rarity cards into 1 higher-rarity random card."""
    user = update.effective_user
    user_id_str = str(user.id)
    args = [str(a).strip() for a in (context.args or []) if str(a).strip()]

    if len(args) != 3:
        await update.message.reply_text(
            "📝 /fuse <id1> <id2> <id3>\n"
            "ဥပမာ: /fuse 1 2 3"
        )
        return

    user_cards = list(bot.data.get('users', {}).get(user_id_str, []))
    if len(user_cards) < 3:
        await update.message.reply_text("❌ Fuse လုပ်ဖို့ card 3 ခု မလောက်ပါ")
        return

    from collections import Counter
    requested = Counter(args)
    owned = Counter(user_cards)

    missing_cards = [cid for cid, need in requested.items() if owned.get(cid, 0) < need]
    if missing_cards:
        await update.message.reply_text(
            "❌ မင်း inventory ထဲမှာ မရှိသော card ID ပါဝင်နေသည်\n"
            f"Missing: {', '.join(missing_cards)}"
        )
        return

    if any(cid not in bot.data.get('cards', {}) for cid in args):
        bad = [cid for cid in args if cid not in bot.data.get('cards', {})]
        await update.message.reply_text(
            "❌ Card data မရှိသော ID ပါဝင်နေသည်\n"
            f"Invalid: {', '.join(bad)}"
        )
        return

    rarities = [str(bot.data['cards'][cid].get('rarity', '1')) for cid in args]
    if len(set(rarities)) != 1:
        await update.message.reply_text("❌ Fuse လုပ်မယ့် card 3 ခုရဲ့ rarity တူရမည်")
        return

    source_rarity = rarities[0]
    try:
        source_rarity_value = int(source_rarity)
    except Exception:
        await update.message.reply_text("❌ ဒီ card rarity ကို fuse မလုပ်နိုင်ပါ")
        return

    max_rarity = max(int(k) for k in RARITIES.keys())
    if source_rarity_value >= max_rarity:
        await update.message.reply_text("❌ Highest rarity ကို fuse မလုပ်နိုင်ပါ")
        return

    reward_card_id = await _pick_fuse_reward_card(source_rarity)
    if not reward_card_id:
        await update.message.reply_text("❌ ဒီ rarity အထက် reward card မရှိသေးပါ")
        return

    updated_cards = list(user_cards)
    try:
        for cid in args:
            updated_cards.remove(cid)
    except ValueError:
        await update.message.reply_text("❌ Fuse လုပ်ရာတွင် inventory remove error ဖြစ်နေပါသည်")
        return

    updated_cards.append(reward_card_id)
    bot.data['users'][user_id_str] = updated_cards

    reward_card = bot.data['cards'][reward_card_id]
    reward_card['owner'] = user.id
    reward_card['owner_name'] = user.first_name

    fav_id = _get_user_fav_id(user_id_str)
    if fav_id and requested.get(str(fav_id), 0) > 0 and str(fav_id) not in updated_cards:
        _set_user_fav_id(user_id_str, None)

    bot.save_data()

    source_rarity_info = RARITIES.get(source_rarity, RARITIES['1'])
    reward_rarity_key = str(reward_card.get('rarity', '1'))
    reward_rarity_info = RARITIES.get(reward_rarity_key, RARITIES['1'])
    removed_lines = '\n'.join(
        f"• {cid} - {bot.data['cards'][cid].get('name', '?')}" for cid in args
    )

    caption = (
        "✨ Fuse Success!\n\n"
        f"🗑️ Removed 3 Cards:\n{removed_lines}\n\n"
        f"⭐ Base Rarity: {source_rarity_info['display']}\n"
        f"🎁 Reward Card: {reward_card.get('name', '?')}\n"
        f"🎬 Movie: {reward_card.get('movie', '-') }\n"
        f"🆔 ID: {reward_card_id}\n"
        f"⭐ Reward Rarity: {reward_rarity_info['display']}"
    )

    if reward_card.get('type') == 'video' and reward_card.get('video'):
        if reward_card.get('video_type') == 'video':
            await update.message.reply_video(video=reward_card['video'], caption=caption)
        else:
            await update.message.reply_document(document=reward_card['video'], caption=caption)
    elif reward_card.get('image'):
        await update.message.reply_photo(photo=reward_card['image'], caption=caption)
    else:
        await update.message.reply_text(caption)


# ==================== CLAIM ====================

async def claim_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Weekly Animated card claim"""
    user = update.effective_user
    user_id_str = str(user.id)
    
    # Check bio
    try:
        chat_member = await context.bot.get_chat(user.id)
        bio = getattr(chat_member, 'bio', '')
        bot_username = (await context.bot.get_me()).username
        
        if not bio or bot_username.lower() not in bio.lower():
            await update.message.reply_text(
                f"❌ Bio မှာ @{bot_username} ထားရမယ်"
            )
            return
    except:
        await update.message.reply_text("❌ Bio check မလုပ်နိုင်ပါ")
        return
    
    # Check cooldown (7 days)
    last_claim = bot.data.get('last_claims', {}).get(user_id_str)
    if last_claim:
        last_claim_time = datetime.fromisoformat(last_claim)
        cooldown = timedelta(days=7)
        if datetime.now() - last_claim_time < cooldown:
            remaining = cooldown - (datetime.now() - last_claim_time)
            days = remaining.days
            hours = remaining.seconds // 3600
            await update.message.reply_text(
                f"⏳ နောက် {days}d {hours}h ကျမှ claim ထပ်လုပ်လို့ရမယ်"
            )
            return
    
    # Get random Animated card
    animated_cards = [cid for cid, card in bot.data['cards'].items() 
                     if card.get('rarity') == '15']
    
    if not animated_cards:
        await update.message.reply_text("❌ Animated cards မရှိသေးပါ")
        return
    
    card_id = random.choice(animated_cards)
    card = bot.data['cards'][card_id]
    
    # Give card
    if user_id_str not in bot.data['users']:
        bot.data['users'][user_id_str] = []
    bot.data['users'][user_id_str].append(card_id)
    
    # Update last claim
    if 'last_claims' not in bot.data:
        bot.data['last_claims'] = {}
    bot.data['last_claims'][user_id_str] = datetime.now().isoformat()

    # Track claim count in profile
    init_user_if_not_exists(user_id_str)
    prof = bot.data['user_profiles'][user_id_str]
    prof['card_claimed'] = prof.get('card_claimed', 0) + 1

    bot.save_data()
    
    rarity_info = RARITIES['15']
    
    caption = f"""
🎉 Claim Success!

🎴 {card['name']}
🎬 {card['movie']}
🆔 ID: {card['id']}
⭐ {rarity_info['display']}

⏳ Next claim: 7 days
"""
    
    if card.get('type') == 'video':
        if card.get('video_type') == 'video':
            await update.message.reply_video(video=card['video'], caption=caption)
        else:
            await update.message.reply_document(document=card['video'], caption=caption)
    else:
        await update.message.reply_photo(photo=card.get('image', card.get('video')), caption=caption)


# ==================== TOP (PAGINATED UP TO 99) ====================

def _build_top_page(user_counts: list, page: int) -> tuple:
    """
    Build top-users text for a given page (0-indexed).
    Each page shows 10 entries. Max 99 users (pages 0..9 = 100 entries but capped).
    Returns (text, has_next, has_prev)
    """
    PAGE_SIZE = 10
    MAX_USERS = 99
    capped = user_counts[:MAX_USERS]
    start = page * PAGE_SIZE
    end = min(start + PAGE_SIZE, len(capped))
    slice_ = capped[start:end]

    medals = {1: "🥇", 2: "🥈", 3: "🥉"}
    total_pages = (len(capped) + PAGE_SIZE - 1) // PAGE_SIZE

    header = (
        "╔══════════════════════╗\n"
        "  🏆  TOP  PLAYERS  🏆  \n"
        "╚══════════════════════╝\n\n"
    )
    body = ""
    for rank_i, (uid, count) in enumerate(slice_, start=start + 1):
        user_name = get_name(uid)
        if user_name == "Unknown":
            for card in bot.data['cards'].values():
                if str(card.get('owner')) == uid:
                    user_name = card.get('owner_name', 'Unknown')
                    USER_CACHE[uid] = user_name
                    break
        medal = medals.get(rank_i, f"{rank_i}\u2024")
        mention = f"[{user_name}](tg://user?id={uid})"
        body += f"{medal} {mention}\n"
        body += f"   🎴 {count} cards\n\n"

    footer = f"━━━━━━━━━━━━━━━━━━━━━━━\nPage {page+1}/{total_pages}  •  Total {len(capped)} players"
    text = header + body + footer
    has_next = end < len(capped)
    has_prev = page > 0
    return text, has_next, has_prev


async def top_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Top players – first 10, paginate up to #99 with Next button"""
    user_counts = [(uid, len(cards)) for uid, cards in bot.data['users'].items()]
    user_counts.sort(key=lambda x: x[1], reverse=True)

    page = 0
    text, has_next, has_prev = _build_top_page(user_counts, page)

    buttons = []
    if has_next:
        buttons.append(InlineKeyboardButton("Next ▶️", callback_data=f"top_page_1"))
    keyboard = InlineKeyboardMarkup([buttons]) if buttons else None

    await update.message.reply_text(text, parse_mode='Markdown', reply_markup=keyboard)


async def top_page_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Callback for top pagination"""
    query = update.callback_query
    await query.answer()

    try:
        page = int(query.data.split("_")[2])
    except (IndexError, ValueError):
        page = 0

    user_counts = [(uid, len(cards)) for uid, cards in bot.data['users'].items()]
    user_counts.sort(key=lambda x: x[1], reverse=True)

    text, has_next, has_prev = _build_top_page(user_counts, page)

    buttons = []
    if has_prev:
        buttons.append(InlineKeyboardButton("◀️ Prev", callback_data=f"top_page_{page-1}"))
    if has_next:
        buttons.append(InlineKeyboardButton("Next ▶️", callback_data=f"top_page_{page+1}"))
    keyboard = InlineKeyboardMarkup([buttons]) if buttons else None

    try:
        await query.edit_message_text(text, parse_mode='Markdown', reply_markup=keyboard)
    except Exception:
        pass


# ==================== RANK COMMAND (POWER RANKING) ====================

async def rank_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Power-based global rank for the calling user"""
    user = update.effective_user
    user_id = str(user.id)

    if user_id not in bot.data['users'] or not bot.data['users'][user_id]:
        await update.message.reply_text(
            "❌ No cards yet. Collect some cards first!"
        )
        return

    # Calculate power for every user
    power_list = []
    for uid, card_ids in bot.data['users'].items():
        total_power = 0
        for cid in card_ids:
            card = bot.data['cards'].get(str(cid))
            if card:
                rarity = card.get('rarity', '1')
                rarity_info = RARITIES.get(str(rarity), RARITIES['1'])
                total_power += rarity_info.get('value', 10)
        power_list.append((uid, total_power))

    power_list.sort(key=lambda x: x[1], reverse=True)

    # Find calling user
    user_power = 0
    user_rank = 0
    for index, (uid, power) in enumerate(power_list, start=1):
        if uid == user_id:
            user_rank = index
            user_power = power
            break

    # Tier thresholds
    if user_power < 1000:
        tier = "🥉 Bronze"
        next_tier = "Silver"
        needed = 1000 - user_power
    elif user_power < 5000:
        tier = "🥈 Silver"
        next_tier = "Gold"
        needed = 5000 - user_power
    elif user_power < 15000:
        tier = "🥇 Gold"
        next_tier = "Diamond"
        needed = 15000 - user_power
    elif user_power < 30000:
        tier = "💎 Diamond"
        next_tier = "Mythic"
        needed = 30000 - user_power
    else:
        tier = "👑 Mythic"
        next_tier = None
        needed = 0

    total_players = len(power_list)
    top_pct = round((user_rank / total_players) * 100, 1) if total_players else 0

    progress_line = ""
    if next_tier and needed > 0:
        progress_line = f"\n⬆️ Next Tier: {needed:,} power to {next_tier}"

    text = (
        "╔══════════════════════╗\n"
        "  🌌  GLOBAL  RANK  🌌  \n"
        "╚══════════════════════╝\n\n"
        f"👤 Player: {user.first_name}\n"
        f"🏆 Rank: #{user_rank} / {total_players}\n"
        f"💪 Power: {user_power:,}\n"
        f"🎖 Tier: {tier}\n"
        f"📊 Top {top_pct}% of players"
        f"{progress_line}\n\n"
        "━━━━━━━━━━━━━━━━━━━━━━━\n"
        "💡 Power = Sum of all card rarity values"
    )

    await update.message.reply_text(text)


