async def upload_role_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Role chosen → finalize photo upload."""
    query = update.callback_query
    await query.answer()

    role_key = (query.data or "").split('_', 1)[1] if '_' in (query.data or "") else 'normal'
    if role_key not in ROLES:
        role_key = 'normal'

    user = query.from_user
    rarity = context.user_data.get('card_rarity', '1')

    card_id = bot.data['next_id']
    card_data = {
        'id': card_id,
        'image': context.user_data['card_image'],
        'name': context.user_data['card_name'],
        'movie': context.user_data['card_movie'],
        'owner': None,
        'owner_name': 'Available',
        'uploaded_by': user.first_name,
        'uploaded_by_id': user.id,
        'date': datetime.now().isoformat(),
        'rarity': rarity,
        'role': role_key,
    }

    bot.data['cards'][str(card_id)] = card_data
    bot.data['next_id'] += 1
    bot.save_data()

    rarity_info = RARITIES.get(rarity, RARITIES['1'])
    role_info = ROLES[role_key]

    caption = (
        f"{STYLE_3D['border_top']}\n"
        f"✅ Uploaded\n"
        f"{STYLE_3D['sep']}\n"
        f"🆔 ID: {card_id}\n"
        f"📛 {_md_escape(card_data['name'])}\n"
        f"🎬 {_md_escape(card_data['movie'])}\n"
        f"⭐ {rarity_info['display']}\n"
        f"🎭 {role_info['display']}\n"
        f"🖼 Photo\n"
        f"📤 Uploader: {_mention_md(user.id, user.first_name)}\n"
        f"{STYLE_3D['border_bot']}"
    )
    try:
        await query.edit_message_text(f"✅ Role selected: {role_info['display']}")
    except Exception:
        pass
    await query.message.reply_photo(
        photo=card_data['image'],
        caption=caption,
        parse_mode='Markdown'
    )

    # ─── Send to DB channel (/setdbchannel) ───
    if bot.settings.get('database_channel'):
        try:
            await query.bot.send_photo(
                chat_id=bot.settings['database_channel'],
                photo=card_data['image'],
                caption=caption,
                parse_mode='Markdown'
            )
        except Exception as e:
            logger.error(f"DB channel (photo upload) failed: {e}")

    return ConversationHandler.END


