async def role_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/role <card_id> [role]
    • /role <id>          → show inline keyboard with all roles
    • /role <id> summer   → set directly (admin shortcut)
    Admin only.
    """
    if not bot.is_admin(update.effective_user.id):
        await update.message.reply_text("❌ Admin only")
        return

    if not context.args:
        await update.message.reply_text(
            "📝 /role <card_id> [role]\n"
            "ဥပမာ: /role 1001\n"
            "သို့မဟုတ် /role 1001 summer"
        )
        return

    card_id = str(context.args[0]).strip()
    cards = bot.data.get('cards', {})
    if card_id not in cards:
        await update.message.reply_text("❌ Card not found")
        return

    card = cards[card_id]

    # Direct set form: /role <id> <role>
    if len(context.args) >= 2:
        resolved = resolve_role_arg(' '.join(context.args[1:]))
        if not resolved:
            await update.message.reply_text(
                "❌ Role နာမေမှန်ပါ\n"
                f"📋 Roles: {', '.join(ROLES[k]['name'] for k in ROLES)}"
            )
            return
        cards[card_id]['role'] = resolved
        bot.save_data()
        rarity_info = RARITIES.get(str(card.get('rarity', '1')), RARITIES['1'])
        role_info = ROLES[resolved]
        await update.message.reply_text(
            f"✅ Role updated!\n"
            f"🆔 {card.get('id', card_id)}\n"
            f"📛 {_md_escape(card.get('name', ''))}\n"
            f"⭐ {rarity_info['display']}\n"
            f"🎭 {role_info['display']}",
            parse_mode='Markdown'
        )
        try:
            await notify_db_channel_card_update(context.bot, card_id, PREMIUM_STATUS['role'])
        except Exception as e:
            logger.error(f"role notify failed: {e}")
        return

    # Show role picker keyboard
    keys = list(ROLES.keys())
    rows = []
    row = []
    for k in keys:
        row.append(InlineKeyboardButton(ROLES[k]['display'], callback_data=f"setrole_{card_id}_{k}"))
        if len(row) == 2:
            rows.append(row)
            row = []
    if row:
        rows.append(row)

    current_role = get_role_info(card)
    rarity_info = RARITIES.get(str(card.get('rarity', '1')), RARITIES['1'])

    await update.message.reply_text(
        f"🎭 **Set Role**\n"
        f"🆔 {card.get('id', card_id)} • 📛 {_md_escape(card.get('name', ''))}\n"
        f"⭐ {rarity_info['display']}\n"
        f"🎭 Current: {current_role['display']}\n\n"
        f"ေအာက်တွင် Role တစ်ခုကို နှိပ်ပါ:",
        parse_mode='Markdown',
        reply_markup=InlineKeyboardMarkup(rows)
    )


async def role_setrole_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Callback for /role inline buttons → sets role on existing card."""
    query = update.callback_query
    if not query:
        return
    if not bot.is_admin(query.from_user.id):
        try:
            await query.answer("Admin only", show_alert=True)
        except Exception:
            pass
        return
    try:
        await query.answer()
    except Exception:
        pass

    data = query.data or ""
    # Pattern: setrole_<card_id>_<role_key>
    m = re.match(r"^setrole_(.+)_([a-z]+)$", data)
    if not m:
        try:
            await query.edit_message_text("❌ Invalid role data")
        except Exception:
            pass
        return

    card_id, role_key = m.group(1), m.group(2)
    if role_key not in ROLES:
        try:
            await query.edit_message_text("❌ Unknown role")
        except Exception:
            pass
        return

    cards = bot.data.get('cards', {})
    if card_id not in cards:
        try:
            await query.edit_message_text("❌ Card not found")
        except Exception:
            pass
        return

    cards[card_id]['role'] = role_key
    bot.save_data()

    role_info = ROLES[role_key]
    rarity_info = RARITIES.get(str(cards[card_id].get('rarity', '1')), RARITIES['1'])
    try:
        await query.edit_message_text(
            f"✅ Role updated!\n"
            f"🆔 {card_id}\n"
            f"📛 {_md_escape(cards[card_id].get('name', ''))}\n"
            f"⭐ {rarity_info['display']}\n"
            f"🎭 {role_info['display']}",
            parse_mode='Markdown'
        )
    except Exception:
        pass

    try:
        await notify_db_channel_card_update(context.bot, card_id, PREMIUM_STATUS['role'])
    except Exception as e:
        logger.error(f"role notify failed: {e}")


async def role_list_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/roles — List all available roles."""
    lines = ["🎭 **Available Roles:**\n"]
    for key, info in ROLES.items():
        lines.append(f"{info['display']}  —  `/{key}`")
    lines.append("\n💡 Use `/<role>` to search cards by that role.")
    lines.append("💡 Admin: `/role <id>` → change a card's role.")
    await update.message.reply_text("\n".join(lines), parse_mode='Markdown')


async def role_search_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/summer, /valentine, /christmas, /halloween, ... — Search cards by role.

    ⚠️ NEW: တယ် Text List မသုံးတော့ပါ။ Telegram **Inline Query Result System** ကို
    အသုံးပြုပြီး Card Thumbnail / Name / Rarity / Role ပြသည်။
    Result တစ်ခုနှိပ်လိုက်ပါက ဆိုင်ရာ card photo / video ကို မိမိတင်မှ
    Caption နှင့်တွဲ ပို့ပေးမည်။
    """
    msg = update.message
    if not msg or not msg.text:
        return

    # Extract the bare command word (strip leading /, drop @botname)
    raw = msg.text.strip().split()[0]
    cmd_word = raw.lstrip('/').split('@', 1)[0].lower()

    role_key = resolve_role_arg(cmd_word)
    if not role_key:
        return  # unknown — silently ignore (shouldn't trigger if registered correctly)

    role_info = ROLES[role_key]

    # Count cards with this role just to give a hint to the user
    total = 0
    for _cid, card in bot.data.get('cards', {}).items():
        if not card:
            continue
        if get_card_role(card) == role_key:
            total += 1

    if total == 0:
        await msg.reply_text(
            f"😢 {role_info['display']} role နှင့် card မတွေ့ပါ"
        )
        return

    # Build a single message + Inline-Query button. နှိပ်လိုက်လျှင်
    # Telegram ရဲ့ Inline Query Gallery ပွင့်ပြီး thumbnail/name/rarity/role ပြပေးမည်။
    inline_payload = f"role:{role_key}"
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton(
            f"🎴 Open {role_info['display']} Gallery",
            switch_inline_query_current_chat=inline_payload
        )]
    ])

    await msg.reply_text(
        f"🎭 **{role_info['display']} Cards**\n"
        f"📊 Total: **{total}** cards\n"
        f"────────────────────\n"
        f"👇 အောက်မှထော့ button ကိုနှိပ်ပြီး Card Gallery မှာ ကြည့်ရှုနိုင်ပါ။\n"
        f"👀 တစ်ခုချင်းထော့တဲ့ result မှာ ထို card ရဲ့ photo သို့မဟုတ် video နှင့် caption ပို့ပေးပါမည်။",
        parse_mode='Markdown',
        reply_markup=kb
    )


async def myrole_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/myrole <role>  —  Show the user's collection filtered by role.
    Example: /myrole summer   /myrole valentine   /myrole christmas
    If no arg → list available roles + counts in user's collection.
    """
    user = update.effective_user
    if not user:
        return
    uid_str = str(user.id)
    owned = bot.data.get('users', {}).get(uid_str, []) or []
    if not owned:
        await update.message.reply_text("😢 မင်းမှာ ကဒ်မရှိသေးပါ")
        return

    from collections import Counter
    # Always pre-compute per-role counts
    role_counts = {k: 0 for k in ROLES}
    counts = Counter(owned)
    for cid, n in counts.items():
        c = bot.data.get('cards', {}).get(str(cid))
        if not c:
            continue
        rk = get_card_role(c)
        role_counts[rk] = role_counts.get(rk, 0) + n

    if not context.args:
        lines = ["🎭 **My Role Collection**\n"]
        for k, info in ROLES.items():
            n = role_counts.get(k, 0)
            if n > 0:
                lines.append(f"{info['display']}  —  **{n}**")
        lines.append("\n💡 Use `/myrole <role>` to view list. ဥပမာ `/myrole summer`")
        await update.message.reply_text("\n".join(lines), parse_mode='Markdown')
        return

    role_key = resolve_role_arg(' '.join(context.args))
    if not role_key:
        await update.message.reply_text(
            "❌ Role နာမေမှန်ပါ\n"
            f"📋 Roles: {', '.join(ROLES[k]['name'] for k in ROLES)}"
        )
        return

    role_info = ROLES[role_key]

    # Filter owned cards by role
    filtered = []
    for cid, n in counts.items():
        c = bot.data.get('cards', {}).get(str(cid))
        if not c:
            continue
        if get_card_role(c) == role_key:
            filtered.append((str(cid), c, n))

    if not filtered:
        await update.message.reply_text(
            f"😢 {role_info['display']} ကဒ် မတွေ့ပါ"
        )
        return

    # Sort by rarity desc
    def _sort_key(item):
        c = item[1]
        rk = str(c.get('rarity', '1'))
        return (-RARITIES.get(rk, RARITIES['1'])['value'], int(c.get('id', 0) or 0))
    filtered.sort(key=_sort_key)

    lines = [
        f"🎭 **My {role_info['display']} Cards**",
        f"📊 Total unique: {len(filtered)}  •  Total copies: {sum(n for _, _, n in filtered)}",
        "─" * 20,
    ]
    show_limit = 50
    for cid, c, n in filtered[:show_limit]:
        rk = str(c.get('rarity', '1'))
        ri = RARITIES.get(rk, RARITIES['1'])
        lines.append(
            f"🆔 {c.get('id', cid)} • {ri['emoji']} 📛 {_md_escape(c.get('name', '?'))} ×{n}"
        )
    if len(filtered) > show_limit:
        lines.append(f"\n… +{len(filtered) - show_limit} more")

    await update.message.reply_text("\n".join(lines), parse_mode='Markdown')


# ==================== EDIT/DELETE ====================

async def edit_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Edit card using /edit <id> / <name> / <movie name>.
    Also supports old - separated and space-separated formats as fallback."""
    if not bot.is_admin(update.effective_user.id):
        await update.message.reply_text("❌ Admin only")
        return

    raw_text = (update.message.text or '').strip()
    card_id = None
    new_name = None
    new_movie = None

    slash_match = re.match(r'^/edit(?:@\w+)?\s+(\S+)\s*/\s*(.*?)\s*/\s*(.+)$', raw_text, flags=re.S)
    if slash_match:
        card_id = slash_match.group(1).strip()
        new_name = slash_match.group(2).strip()
        new_movie = slash_match.group(3).strip()
    else:
        split_parts = re.split(r'\s*-\s*', raw_text, maxsplit=2)
        if len(split_parts) == 3:
            head_tokens = split_parts[0].split(maxsplit=1)
            if len(head_tokens) >= 2:
                card_id = head_tokens[1].strip()
                new_name = split_parts[1].strip()
                new_movie = split_parts[2].strip()

    # Fallback for old format: /edit <id> <name> <movie>
    if not card_id:
        if len(context.args) < 3:
            await update.message.reply_text("📝 /edit <id> / <name> / <movie name>")
            return
        card_id = context.args[0]
        remaining = context.args[1:]
        if len(remaining) < 2:
            await update.message.reply_text("❌ Name နဲ့ Movie ပေးပါ")
            return
        new_name = remaining[0].strip()
        new_movie = ' '.join(remaining[1:]).strip()

    if not card_id or not new_name or not new_movie:
        await update.message.reply_text("📝 /edit <id> / <name> / <movie name>")
        return

    if card_id not in bot.data['cards']:
        await update.message.reply_text("❌ Card မရှိပါ")
        return

    bot.data['cards'][card_id]['name'] = new_name
    bot.data['cards'][card_id]['movie'] = new_movie
    bot.save_data()

    await update.message.reply_text(
        f"✅ Edited!\n"
        f"🆔 {card_id}\n"
        f"📛 {new_name}\n"
        f"🎬 {new_movie}"
    )

    # Notify db_channel (Updated + card media) — premium status
    await notify_db_channel_card_update(context.bot, card_id, action_line=PREMIUM_STATUS['edit'])


async def editr_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Edit rarity"""
    if not bot.is_admin(update.effective_user.id):
        await update.message.reply_text("❌ Admin only")
