    card_id = context.args[0]
    
    if card_id not in bot.data['cards']:
        await update.message.reply_text("❌ Card မရှိပါ")
        return
    
    card = bot.data['cards'][card_id]
    current = RARITIES.get(card.get('rarity', '1'), RARITIES['1'])
    
    keyboard = []
    for i in range(1, 17):
        rarity = RARITIES[str(i)]
        keyboard.append([InlineKeyboardButton(rarity['display'], callback_data=f"editr_{card_id}_{i}")])
    
