async def add_admin(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Add admin"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return
    
    if not context.args:
        await update.message.reply_text("📝 /addadmin <user_id>")
        return
    
    try:
        user_id = int(context.args[0])
        if user_id not in bot.settings['admins']:
            bot.settings['admins'].append(user_id)
            bot.save_settings()
            await update.message.reply_text(f"✅ Added admin: {user_id}")
        else:
            await update.message.reply_text("⚠️ Already admin")
    except ValueError:
        await update.message.reply_text("❌ Invalid ID")


