async def commend_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Commend a user — admin/sudo/dev/owner only"""

    if not bot.is_admin(update.effective_user.id):
        await update.message.reply_text("❌ Admin only")
        return

    target_id = None
    target_name = "Unknown"

    if update.message and update.message.reply_to_message and update.message.reply_to_message.from_user:
        target_user = update.message.reply_to_message.from_user
        target_id = target_user.id
        target_name = target_user.full_name or target_user.first_name or "Unknown"
    elif context.args:
        try:
            target_id = int(context.args[0])
            target_name = f"User {target_id}"
        except ValueError:
            await update.message.reply_text("❌ /commend <user_id> သို့မဟုတ် user ကို reply ထားပြီး /commend")
            return
    else:
        await update.message.reply_text("❌ /commend <user_id> သို့မဟုတ် user ကို reply ထားပြီး /commend")
        return

    # Don't allow commending owners
    if bot.is_owner(target_id):
        await update.message.reply_text("❌ Owner ကို commend မပေးနိုင်")
        return

    uid_str = str(target_id)

    # Store commends in user_profiles
    bot.data.setdefault('user_profiles', {})
    bot.data['user_profiles'].setdefault(uid_str, {})

    current = int(bot.data['user_profiles'][uid_str].get('commends', 0) or 0)
    bot.data['user_profiles'][uid_str]['commends'] = current + 1

    try:
        bot.save_data()
    except Exception as e:
        logger.error(f"commend save error: {e}")

    commend_by = (
        update.effective_user.full_name
        or update.effective_user.first_name
        or "User"
    )

    msg = (
        "╔══════════════════════════╗\n"
        "🏅✨  𝗖𝗢𝗠𝗠𝗘𝗡𝗗𝗔𝗧𝗜𝗢𝗡  ✨🏅\n"
        "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"👤 User: {target_name}\n"
        f"🌟 Commends: {current + 1}\n"
        f"✅ By: {commend_by}\n"
        "╚══════════════════════════╝"
    )

    await update.message.reply_text(msg)


