async def gban_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Global ban"""
    if not bot.is_dev(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return
    
    target_id = None
    target_user = None
    reason = "No reason"
    
    if update.message.reply_to_message:
        target_user = update.message.reply_to_message.from_user
        target_id = target_user.id
        if context.args:
            reason = ' '.join(context.args)
    elif context.args:
        try:
            target_id = int(context.args[0])
            reason = ' '.join(context.args[1:]) if len(context.args) > 1 else reason
        except ValueError:
            await update.message.reply_text("❌ /gban <id> [reason]")
            return
    else:
        await update.message.reply_text("❌ /gban <id> [reason]")
        return
    
    if bot.is_owner(target_id):
        await update.message.reply_text("❌ Can't ban owner")
        return
    
    bot.settings['gbanned_users'][str(target_id)] = {
        'reason': reason,
        'banned_by': update.effective_user.id,
        'banned_at': datetime.now().isoformat(),
        'username': target_user.first_name if target_user else 'Unknown'
    }
    bot.save_settings()
    
    username = target_user.first_name if target_user else f"User {target_id}"
    
    await update.message.reply_text(
        f"✅ Gbanned {username} ({target_id})\n"
        f"📝 Reason: {reason}"
    )
    
    # Try to kick from groups
    kicked = 0
    for gid in bot.data.get('group_counters', {}).keys():
        try:
            await context.bot.ban_chat_member(int(gid), target_id)
            kicked += 1
        except:
            pass
    
    await update.message.reply_text(f"🚫 Kicked from {kicked} groups")

    # ── 3D EFFECT: Send gban notice sticker to all active groups ──
    drop_sticker_id = bot.settings.get('drop_sticker')
    gban_3d_text = (
        f"╔══════════════════════════╗\n"
        f"🚨✨  𝗚𝗟𝗢𝗕𝗔𝗟  𝗕𝗔𝗡  ✨🚨\n"
        f"┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"👤 User: {metion} ({target_id})\n"
        f"📝 Reason: {reason}\n"
        f"⚡ Status: GLOBALLY BANNED\n"
        f"┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"🔥 This user has been removed from all groups!\n"
        f"╚══════════════════════════╝"
    )
    for gid in list(bot.data.get('active_groups', [])):
        try:
            if drop_sticker_id:
                await context.bot.send_sticker(chat_id=int(gid), sticker=drop_sticker_id)
            await context.bot.send_message(chat_id=int(gid), text=gban_3d_text)
        except Exception:
            pass


