# ==================== BROADCAST ====================

async def broadcast_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Broadcast to all groups and users"""
    if not bot.is_owner(update.effective_user.id) and not bot.is_sudo(update.effective_user.id) and not bot.is_dev(update.effective_user.id):
        await update.message.reply_text("❌ Owner/Sudo/Dev only")
        return
    
    groups = list(bot.data.get('group_counters', {}).keys())
    users = list(bot.data.get('users', {}).keys())
    
    if not groups and not users:
        await update.message.reply_text("❌ No groups/users")
        return
    
    g_ok = 0
    g_fail = 0
    u_ok = 0
    u_fail = 0
    
    if update.message.reply_to_message:
        await update.message.reply_text(f"🔄 Broadcasting to {len(groups)} groups and {len(users)} users...")
        
        for gid in groups:
            try:
                await context.bot.forward_message(
                    chat_id=int(gid),
                    from_chat_id=update.effective_chat.id,
                    message_id=update.message.reply_to_message.message_id
                )
                g_ok += 1
            except Exception as e:
                logger.error(f"Broadcast to group failed: {e}")
                g_fail += 1
        
        for uid in users:
            try:
                await context.bot.forward_message(
                    chat_id=int(uid),
                    from_chat_id=update.effective_chat.id,
                    message_id=update.message.reply_to_message.message_id
                )
                u_ok += 1
            except Exception as e:
                logger.error(f"Broadcast to user failed: {e}")
                u_fail += 1
    
    elif context.args:
        msg_text = ' '.join(context.args)
        await update.message.reply_text(f"🔄 Broadcasting to {len(groups)} groups and {len(users)} users...")
        
        for gid in groups:
            try:
                await context.bot.send_message(
                    chat_id=int(gid),
                    text=f"📢 Broadcast:\n\n{msg_text}"
                )
                g_ok += 1
            except Exception as e:
                logger.error(f"Broadcast to group failed: {e}")
                g_fail += 1
        
        for uid in users:
            try:
                await context.bot.send_message(
                    chat_id=int(uid),
                    text=f"📢 Broadcast:\n\n{msg_text}"
                )
                u_ok += 1
            except Exception as e:
                logger.error(f"Broadcast to user failed: {e}")
                u_fail += 1
    
    else:
        await update.message.reply_text("📝 /broadcast <msg> or reply to message")
        return
    
    await update.message.reply_text(
        f"✅ Broadcast done!\n\n"
        f"📊 Groups:\n"
        f"   ✅ Success: {g_ok}\n"
        f"   ❌ Failed: {g_fail}\n\n"
        f"👥 Users:\n"
        f"   ✅ Success: {u_ok}\n"
        f"   ❌ Failed: {u_fail}"
    )


# ==================== BACKUP/RESTORE ====================

async def backup_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Backup all data - includes settings, users, economy, events, and card media.
    The zip contains ALL JSON files + a combined snapshot for maximum safety.
    Restoring any backup zip will fully recover all data."""
    if not bot.is_dev(update.effective_user.id):
        await update.message.reply_text("❌ Dev/Owner only")
        return

    try:
        await update.message.reply_text("🔄 Backing up all data...")

        # Step 1: Delete old backup messages from channel
        deleted = await _delete_old_backup_messages(context)

        # Step 2: Flush all in-memory data to JSON files on disk
        try:
            bot.save_data()
        except Exception as e:
            logger.error(f"Save data error: {e}")
        try:
            bot.save_settings()
        except Exception as e:
            logger.error(f"Save settings error: {e}")
        try:
            save_events()
        except Exception as e:
            logger.error(f"Save events error: {e}")

        # Step 3: Create zip backup (all JSON files + combined snapshot)
        zip_bytes = _make_backup_zip_bytes()
        if not zip_bytes:
            await update.message.reply_text("❌ Backup failed - could not create zip")
            return

        # Step 4: Send zip to backup channel
        now_str = datetime.now().isoformat()
        caption = (
            f"💾 Full Data Backup\n"
            f"📅 {now_str}\n"
            f"👥 Users: {len(bot.data.get('users', {}))}\n"
            f"🎴 Cards: {len(bot.data.get('cards', {}))}\n"
            f"💰 Profiles: {len(bot.data.get('user_profiles', {}))}\n"
            f"🎪 Events: {'Active' if events.get('active_event') else 'None'}\n"
            f"#{BACKUP_TAG}"
        )

        bio = io.BytesIO(zip_bytes)
        bio.name = "full_backup.zip"

        sent = await context.bot.send_document(
            chat_id=BACKUP_CHANNEL,
            document=bio,
            caption=caption
        )

        bot.settings["last_backup_message_id"] = sent.message_id
        if sent.document:
            bot.settings["last_backup_file_id"] = sent.document.file_id
        try:
            bot.save_settings()
        except Exception as e:
            logger.error(f"Save settings error: {e}")
        # Step 5 removed: ZIP-only backup (faster + safer)

        await update.message.reply_text(
            (
                f"✅ Backup complete!\n"
                f"🗑️ Deleted old: {deleted}\n"
                f"💾 Zip backup: ✅ (JSON Files + Combined snapshot)\n"
                f"👥 Users: {len(bot.data.get('users', {}))}\n"
                f"💰 Profiles: {len(bot.data.get('user_profiles', {}))}\n"
                f"🎴 Cards: {len(bot.data.get('cards', {}))}\n"
                f"🎪 Events: ✅\n"
                f"📍 {BACKUP_CHANNEL}\n\n"
                f"💡 ဒီ zip file ကို /restore နဲ့ တိုက်ရိုက် restore လုပ်နိုင်သလို\nreply + /rc (သို့) /restorefull နဲ့လည်း data အကုန်ပြန်ရမည်"
            ),
        )

    except Exception as e:
        logger.error(f"Backup error: {e}")
        await update.message.reply_text(f"❌ Backup error: {e}")

async def restore_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Safe restore from backup - restores ALL data from zip file + card media.
    Methods (in priority order):
      1. Zip file sent directly with /restore command
      2. Last cloud backup file_id stored in settings
    After restoring JSON data, card file_ids are already inside card_bot_data.json.
    Channel card media fetch is attempted as a bonus refresh (non-blocking).
    Bot crash recovery: just send the old zip to /restore and everything comes back.
    """
    if not bot.is_dev(update.effective_user.id):
        await update.message.reply_text("❌ Dev/Owner only")
        return

    try:
        await update.message.reply_text("🔄 Restore စတင်နေသည်...")

        zip_bytes = None
        source_label = ""

        # Method 1: direct zip upload or reply-to zip
        restore_doc, restore_doc_label = _get_restore_zip_document(update.message)
        if restore_doc:
            await update.message.reply_text("📂 Backup zip ဖတ်နေသည်...")
            try:
                tg_file = await restore_doc.get_file()
                zip_bytes = bytes(await tg_file.download_as_bytearray())
                source_label = restore_doc_label or "📤 User uploaded zip"
            except Exception as e:
                logger.error(f"Could not read restore zip: {e}")
                await update.message.reply_text(f"❌ Zip ဖတ်၍မရပါ: {e}")
                return

        # Method 2: Use the last saved backup file_id from settings
        if not zip_bytes:
            file_id = bot.settings.get("last_backup_file_id")
            if file_id:
                await update.message.reply_text("☁️ Channel မှ နောက်ဆုံး cloud backup ဒေါင်းလုဒ်နေသည်...")
                try:
                    tg_file = await context.bot.get_file(file_id)
                    zip_bytes = bytes(await tg_file.download_as_bytearray())
                    source_label = "☁️ Cloud backup (channel)"
                except Exception as e:
                    logger.error(f"Could not download cloud backup: {e}")
                    await update.message.reply_text(
                        f"⚠️ Cloud backup ဒေါင်းလုဒ်မရပါ: {e}\n"
                        f"💡 Backup zip ကို တိုက်ရိုက်ပို့ပြီး /restore ပြန်ရိုက်ပါ"
                    )

        if not zip_bytes:
            await update.message.reply_text(
                "❌ Backup မတွေ့ပါ!\n\n"
                "နည်းလမ်း:\n"
                "• Backup zip file ကို ဒီ chat မှာ ပေးပို့ပြီး /restore ရိုက်ပါ\n"
                "• သို့မဟုတ် backup zip ကို reply လုပ်ပြီး /restore (သို့) /rc ရိုက်ပါ\n"
                "• သို့မဟုတ် /backup ကို ဦးစွာ run ပါ"
            )
            return

        # Validate zip integrity
        try:
            test_mem = io.BytesIO(zip_bytes)
            with zipfile.ZipFile(test_mem, 'r') as ztest:
                names = ztest.namelist()
        except Exception as e:
            await update.message.reply_text(f"❌ Invalid backup zip: {e}")
            return

        await update.message.reply_text(
            f"📦 Backup source: {source_label}\n"
            f"📋 Contains: {', '.join(names)}"
        )

        # ── Safety snapshot of current data before overwriting ──
        try:
            bot.save_data()
            bot.save_settings()
            save_events()
            shutil.copy(DATA_FILE, DATA_FILE + ".pre_restore_bak") if os.path.exists(DATA_FILE) else None
            shutil.copy(SETTINGS_FILE, SETTINGS_FILE + ".pre_restore_bak") if os.path.exists(SETTINGS_FILE) else None
            shutil.copy(ECONOMY_FILE, ECONOMY_FILE + ".pre_restore_bak") if os.path.exists(ECONOMY_FILE) else None
            shutil.copy(MISSIONS_FILE, MISSIONS_FILE + ".pre_restore_bak") if os.path.exists(MISSIONS_FILE) else None
            shutil.copy(EVENTS_FILE, EVENTS_FILE + ".pre_restore_bak") if os.path.exists(EVENTS_FILE) else None
        except Exception as e:
            logger.warning(f"Pre-restore safety snapshot failed (non-critical): {e}")

        # ── Step 1: Extract individual JSON files from zip ──
        extracted = []
        try:
            extracted = _restore_from_zip_bytes(zip_bytes)
        except Exception as e:
            logger.error(f"Primary zip extraction failed: {e}")
            # Fallback: try combined snapshot inside zip
            await update.message.reply_text(f"⚠️ Primary extraction error: {e}\n🔄 Combined snapshot restore ကြိုးစားနေသည်...")
            ok = _restore_from_combined_json(zip_bytes)
            if not ok:
                await update.message.reply_text("❌ Restore လုံးဝမရပါ - zip file ပျက်နေနိုင်သည်")
                return
            await update.message.reply_text("✅ Combined snapshot မှ restore ရအောင်မြင်ပါသည်")

        # ── Step 2: Reload all in-memory data from restored files ──
        bot.data = bot.load_data()
        bot.settings = bot.load_settings()
        try:
            new_events = load_events()
            events.clear()
            events.update(new_events)
        except Exception as e:
            logger.error(f"Reload events failed: {e}")

        # ── Step 3: Patch missing keys to prevent KeyError crashes ──
        _defaults_data = {
            'users': {}, 'cards': {}, 'user_profiles': {},
            'next_id': 1, 'group_counters': {}, 'active_groups': [],
            'last_claims': {}, 'group_drop_counters': {},
            'dropped_cards': {}, 'card_message_ids': {}
        }
        for k, v in _defaults_data.items():
            if k not in bot.data:
                bot.data[k] = v

        _defaults_settings = {
            'admins': OWNERS.copy(), 'database_channel': None,
            'drop_channel': None, 'drop_threshold': 50,
            'sudo_users': [], 'dev_users': [],
            'gbanned_users': {}, 'gmuted_users': {},
            'last_backup_message_id': None,
            'last_backup_file_id': None,
            'card_backup_message_ids': [],
            'locked_rarities': []
        }
        for k, v in _defaults_settings.items():
            if k not in bot.settings:
                bot.settings[k] = v

        # Patch user profile fields
        _profile_defaults = {
            "bank": 0, "last_daily": None, "last_interest": None,
            "event_coins": 0, "xp": 0, "level": 1, "coins": 0,
            "last_xp_time": None
        }
        for uid, profile in bot.data.get('user_profiles', {}).items():
            for fk, fv in _profile_defaults.items():
                if fk not in profile:
                    profile[fk] = fv

        # ── Step 4: Save patched data back to disk ──
        try:
            bot.save_data()
        except Exception as e:
            logger.error(f"Save data after restore failed: {e}")
        try:
            bot.save_settings()
        except Exception as e:
            logger.error(f"Save settings after restore failed: {e}")
        try:
            save_events()
        except Exception as e:
            logger.error(f"Save events after restore failed: {e}")

        # Count cards that already have valid file_ids from the JSON data
        cards_with_media = sum(
            1 for c in bot.data.get('cards', {}).values()
            if c.get('image') or c.get('video')
        )
        total_cards = len(bot.data.get('cards', {}))

        await update.message.reply_text(
            f"✅ JSON Data restore ပြီးပါပြီ!\n\n"
            f"💾 Files extracted: {', '.join(extracted) if extracted else 'combined snapshot'}\n"
            f"👥 Users: {len(bot.data.get('users', {}))}\n"
            f"🎴 Total Cards: {total_cards}\n"
            f"📸 Cards with media (from JSON): {cards_with_media}/{total_cards}\n"
            f"💰 Profiles: {len(bot.data.get('user_profiles', {}))}\n"
            f"🎪 Events: ✅\n\n"
            f"🔄 Card media file_id refresh ကြိုးစားနေသည် ({BACKUP_CHANNEL})..."
        )

        # ── Step 5: Optional - refresh card file_ids from channel backup messages ──
        # This is NOT required for restore to work (file_ids already in JSON).
        # It only refreshes them in case old file_ids expired.
        card_msg_ids = bot.settings.get("card_backup_message_ids", [])
        refreshed_count = 0
        skipped_count = 0
        error_count = 0

        if card_msg_ids:
            for msg_id in card_msg_ids:
                try:
                    msg = await context.bot.forward_message(
                        chat_id=update.effective_chat.id,
                        from_chat_id=BACKUP_CHANNEL,
                        message_id=msg_id
                    )
                    # Delete the forwarded message immediately to keep chat clean
                    try:
                        await msg.delete()
                    except Exception:
                        pass

                    if not msg.caption or CARD_BACKUP_TAG not in msg.caption:
                        skipped_count += 1
                        continue

                    # Parse card ID from caption
                    card_id = None
                    for line in msg.caption.split('\n'):
                        if line.startswith('🆔 ID:'):
                            try:
                                card_id = str(int(line.replace('🆔 ID:', '').strip()))
                            except Exception:
                                pass

                    if not card_id or card_id not in bot.data.get('cards', {}):
                        skipped_count += 1
                        continue

                    # Refresh file_id
                    if msg.photo:
                        bot.data['cards'][card_id]['image'] = msg.photo[-1].file_id
                        refreshed_count += 1
                    elif msg.video:
                        bot.data['cards'][card_id]['video'] = msg.video.file_id
                        bot.data['cards'][card_id]['video_type'] = 'video'
                        bot.data['cards'][card_id]['type'] = 'video'
                        refreshed_count += 1
                    elif msg.document:
                        bot.data['cards'][card_id]['video'] = msg.document.file_id
                        bot.data['cards'][card_id]['video_type'] = 'document'
                        bot.data['cards'][card_id]['type'] = 'video'
                        refreshed_count += 1
                    else:
                        skipped_count += 1

                except Exception as e:
                    logger.error(f"Refresh card media msg_id={msg_id} failed: {e}")
                    error_count += 1
        else:
            await update.message.reply_text(
                "ℹ️ Channel media message IDs မရှိပါ\n"
                "✅ Card file_ids များသည် JSON data မှ တိုက်ရိုက်ထည့်သွင်းပြီးပါပြီ"
            )

        # Final save after media refresh
        try:
            bot.save_data()
        except Exception as e:
            logger.error(f"Final save after media refresh failed: {e}")

        await update.message.reply_text(
            f"🎉 Restore လုံးဝပြီးပါပြီ!\n\n"
            f"💾 JSON Data: ✅\n"
            f"👥 Users: {len(bot.data.get('users', {}))}\n"
            f"🎴 Total Cards: {total_cards}\n"
            f"📸 Cards with media: {cards_with_media}/{total_cards}\n"
            f"🔄 Media file_ids refreshed: {refreshed_count}\n"
            f"⚠️ Skipped: {skipped_count}\n"
            f"❌ Refresh errors: {error_count}\n\n"
            f"✨ Data အားလုံး ပြန်ရပါပြီ!"
        )

    except Exception as e:
        logger.error(f"Restore error: {e}")
        await update.message.reply_text(f"❌ Restore error: {e}")

async def importcards_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Start import mode"""
    if not bot.is_admin(update.effective_user.id):
        await update.message.reply_text("❌ Admin only")
        return
    
    text = f"""
📥 Card Import Instructions:

1️⃣ Go to {BACKUP_CHANNEL}
2️⃣ Find messages with #{CARD_BACKUP_TAG}
3️⃣ Forward them to bot
4️⃣ Bot will auto-import

⚠️ Existing cards will be skipped

✅ Ready! Start forwarding...
"""
    
    await update.message.reply_text(text)


async def manualimport_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle forwarded card imports - supports both photos and videos"""
    user_id = update.effective_user.id

    # Suspension (Owner command /suspend)
    sus = bot.settings.get('suspended_users', {})
    srec = sus.get(str(user_id))
    if srec:
        ends = _parse_iso(str(srec.get('ends_at') or ''))
        if ends and _now() < ends:
            try:
                await update.message.reply_text(f"⛔ Suspended until: {srec.get('ends_at')}")
            except Exception:
                pass
            try:
                await update.message.delete()
            except Exception:
                pass
            return
        else:
            # expired
            try:
                sus.pop(str(user_id), None)
                bot.save_settings()
            except Exception:
                pass
    
    if not bot.is_admin(user_id):
        return
    
    message = update.message
    
    # Check if message has media (photo or video) and caption
    has_media = message.photo or message.video or message.document
    if not has_media or not message.caption:
        return
    
    if CARD_BACKUP_TAG not in message.caption:
        return
    
    try:
        lines = message.caption.split('\n')
        card_name = None
        card_movie = None
        card_id = None
        owner_id = None
        owner_name = None
        date = None
        rarity = '1'
        
        for line in lines:
            line = line.strip()
            if line.startswith('🎴'):
                card_name = line.replace('🎴', '').strip()
            elif line.startswith('🎬'):
                card_movie = line.replace('🎬', '').strip()
            elif line.startswith('🆔 ID:'):
                try:
                    card_id = int(line.replace('🆔 ID:', '').strip())
                except ValueError:
                    pass
            elif line.startswith('👤 Owner:'):
                owner_info = line.replace('👤 Owner:', '').strip()
                if '(ID:' in owner_info:
                    owner_name = owner_info.split('(ID:')[0].strip()
                    try:
                        owner_id = int(owner_info.split('(ID:')[1].replace(')', '').strip())
                    except:
                        pass
                else:
                    owner_name = owner_info
            elif line.startswith('📅'):
                date = line.replace('📅', '').strip()
            elif line.startswith('⭐'):
                for r_key, r_data in RARITIES.items():
                    if r_data['name'] in line or r_data['emoji'] in line:
                        rarity = r_key
                        break
        
        if not all([card_name, card_movie, card_id]):
            await message.reply_text("❌ Incomplete card data")
            return
        
        card_id_str = str(card_id)
        if card_id_str in bot.data['cards']:
            await message.reply_text(f"⚠️ Card {card_id} exists, skipped")
            return
        
        # Determine media type and get file_id
        card_data = {
            'id': card_id,
            'name': card_name,
            'movie': card_movie,
            'owner': owner_id or user_id,
            'owner_name': owner_name or 'Imported',
            'uploaded_by': 'Imported',
            'uploaded_by_id': user_id,
            'date': date or datetime.now().isoformat(),
            'rarity': rarity
        }
        
        # Handle different media types
        if message.photo:
            card_data['image'] = message.photo[-1].file_id
        elif message.video:
            card_data['video'] = message.video.file_id
            card_data['video_type'] = 'video'
            card_data['type'] = 'video'
        elif message.document:
            card_data['video'] = message.document.file_id
            card_data['video_type'] = 'document'
            card_data['type'] = 'video'
        
        bot.data['cards'][card_id_str] = card_data
        
        if owner_id:
            uid_str = str(owner_id)
            if uid_str not in bot.data['users']:
                bot.data['users'][uid_str] = []
            bot.data['users'][uid_str].append(card_id_str)
        
        if card_id >= bot.data['next_id']:
            bot.data['next_id'] = card_id + 1
        
        bot.save_data()
        
        rarity_info = RARITIES.get(rarity, RARITIES['1'])
        
        await message.reply_text(
            f"✅ Imported!\n"
            f"🎴 {card_name}\n"
            f"🎬 {card_movie}\n"
            f"🆔 {card_id}\n"
            f"⭐ {rarity_info['display']}\n"
            f"👤 {owner_name}"
        )
        
    except Exception as e:
        logger.error(f"Import failed: {e}")
        await message.reply_text(f"❌ Import error: {e}")


