async def datect_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/datect <keyword> — search cards by name with media pagination UI."""
    if not update.message:
        return

    keyword = ' '.join(context.args).strip()
    if not keyword:
        await update.message.reply_text("📝 အသုံးပြုပုံ\n/datect gojo")
        return

    cards_db = bot.data.get('cards', {}) or {}
    search_key = keyword.casefold()
    matches = []

    for cid, card in cards_db.items():
        if not isinstance(card, dict):
            continue
        card_name = str(card.get('name', '') or '').strip()
        if not card_name:
            continue
        if search_key in card_name.casefold():
            matches.append((str(cid), card))

    matches.sort(key=_datect_card_sort_key)

    if not matches:
        await update.message.reply_text(f"❌ No cards found for: {keyword}")
        return

    _cleanup_datect_sessions()
    token = f"d{random.randint(1000, 9999)}{int(time.time()) % 100000}"
    DATECT_SESSIONS[token] = {
        'user_id': update.effective_user.id if update.effective_user else 0,
        'keyword': keyword,
        'card_ids': [str(cid) for cid, _ in matches],
        'created_at': time.time(),
    }

    await _datect_send_initial_result(update.message, matches[0][1], 0, len(matches), token)


async def datect_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query or not query.data:
        return

    parts = query.data.split('|')
    if len(parts) < 3:
        await query.answer()
        return

    action = parts[1]
    token = parts[2]
    session = DATECT_SESSIONS.get(token)

    if not session:
        await query.answer("Search session expired", show_alert=True)
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass
        return

    user_id = update.effective_user.id if update.effective_user else 0
    if session.get('user_id') and session.get('user_id') != user_id:
        await query.answer("ဒီ search ကို စတင်ထားသူပဲ သုံးနိုင်ပါသည်", show_alert=True)
        return

    if action == 'close':
        DATECT_SESSIONS.pop(token, None)
        await query.answer("Closed")
        try:
            await query.edit_message_caption(caption="❌ Closed", reply_markup=None)
            return
        except Exception:
            pass
        try:
            await query.edit_message_text(text="❌ Closed", reply_markup=None)
        except Exception:
            try:
                await query.edit_message_reply_markup(reply_markup=None)
            except Exception:
                pass
        return

    if action != 'nav' or len(parts) < 4:
        await query.answer()
        return

    card_ids = session.get('card_ids', []) or []
    if not card_ids:
        DATECT_SESSIONS.pop(token, None)
        await query.answer("Search session expired", show_alert=True)
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass
        return

    try:
        target_index = int(parts[3])
    except Exception:
        target_index = 0

    total = len(card_ids)
    target_index = max(0, min(target_index, total - 1))
    card = bot.data.get('cards', {}).get(str(card_ids[target_index]))

    if not card:
        await query.answer("Card data missing", show_alert=True)
        return

    session['created_at'] = time.time()
    await query.answer()
    await _datect_edit_result(query, card, target_index, total, token)


async def inline_query(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle inline queries.

    ✅ How to use (examples):
      • @botusername spiderman          -> search by card name/movie
      • @botusername userid 123456789   -> show that user's cards
      • @botusername id 123456789       -> show that user's cards
      • @botusername .harem.123456789   -> (legacy) show that user's cards

    Notes:
    - This bot stores Telegram *file_id* for photo/video.
    - Inline mode must use *Cached* inline results (file_id), NOT photo_url/video_url.
    """

    import re

    iq = update.inline_query
    query = (iq.query or "").strip()
    if not query:
        return

    # The /harem Inline View Cards flow is handled by _ufp_inline_query,
    # which implements Telegram's offset/next_offset pagination.  Do NOT let
    # this original handler answer the same query again, otherwise its old
    # 50-result response can overwrite the paginated response.
    try:
        _self = update.effective_user
        if (
            _self
            and query.isdigit()
            and len(query) >= 4
            and query == str(_self.id)
        ):
            return
    except Exception:
        pass

    async def _answer(results):
        return await iq.answer(results, cache_time=1, is_personal=True)

    def _caption(card: dict, mention: str) -> str:
        rarity = str(card.get('rarity', '1'))
        rarity_info = RARITIES.get(rarity, RARITIES['1'])
        role_info = get_role_info(card)
        return (
            f"OwO! Check out this character!\n"
            f"👤 Player : {mention}\n"
            f"🎬 Anime  : {_md_escape(card.get('movie',''))}\n"
            f"🆔 ID     : {card.get('id','')}\n"
            f"🌟 Name   : {_md_escape(card.get('name',''))}\n"
            f"⚜ Rarity : {rarity_info['display']}\n"
            f"🎭 Role   : {role_info['display']}\n"
            f"╰━━━━━━━━━━━━━━━━━━━━╯"
        )

    def _build_result(card: dict, cap: str):
        # Return InlineQueryResultCachedPhoto/Video
        try:
            if card.get('type') == 'video' and card.get('video'):
                return InlineQueryResultCachedVideo(
                    id=f"v_{card.get('id','0')}_{random.randint(1000,9999)}",
                    video_file_id=card['video'],
                    title=str(card.get('name', 'Video Card')),
                    caption=cap,
                    parse_mode='Markdown',
                )
            if card.get('image'):
                return InlineQueryResultCachedPhoto(
                    id=f"p_{card.get('id','0')}_{random.randint(1000,9999)}",
                    photo_file_id=card['image'],
                    title=str(card.get('name', 'Card')),
                    caption=cap,
                    parse_mode='Markdown',
                )
        except Exception:
            return None
        return None

    def _results_for_user(target_user_id_str: str):
        user_cards = bot.data.get('users', {}).get(str(target_user_id_str))
        if not user_cards:
            return []

        # caption player should be that target user (not the requester)
        target_name = get_name(target_user_id_str)
        if target_name == 'Unknown':
            target_name = 'User'
        mention = _mention_md(int(target_user_id_str), target_name)

        out = []
        for cid in user_cards[:50]:
            card = bot.data.get('cards', {}).get(str(cid))
            if not card:
                continue
            cap = _caption(card, mention)
            res = _build_result(card, cap)
            if res:
                out.append(res)
            if len(out) >= 50:
                break
        return out

    qlow = query.lower()

    # ============================================================
    # ROLE GALLERY: 'role:<role_key>' or 'role:<role_key> <free text>'
    # Triggered by /summer, /valentine, etc. through switch_inline_query_current_chat.
    # Returns InlineQueryResult* with title=Name, description=Rarity · Role,
    # and the photo/video itself as the result media (Telegram uses it as thumbnail).
    # Tapping a result sends the card photo/video + caption to the chat.
    # ============================================================
    role_m = re.match(r'^role:([a-z0-9_\-]+)(?:\s+(.*))?$', qlow)
    if role_m:
        role_key_raw = role_m.group(1)
        extra_q = (role_m.group(2) or '').strip().lower()
        role_key = resolve_role_arg(role_key_raw)
        if not role_key:
            await _answer([])
            return

        role_info_g = ROLES.get(role_key, ROLES['normal'])
        requester2 = update.effective_user
        req_mention2 = _mention_md(
            requester2.id if requester2 else 0,
            requester2.first_name if requester2 else 'User'
        )

        # Collect matching cards
        matched = []
        for cid, card in bot.data.get('cards', {}).items():
            if not card:
                continue
            if get_card_role(card) != role_key:
                continue
            # Optional free-text filter within the role gallery
            if extra_q:
                name = str(card.get('name', '')).lower()
                movie = str(card.get('movie', '')).lower()
                cid_s = str(card.get('id', cid)).lower()
                if extra_q not in name and extra_q not in movie and extra_q != cid_s:
                    continue
            matched.append((cid, card))

        # Sort by rarity desc then id
        def _r_sort(item):
            c = item[1]
            rk = str(c.get('rarity', '1'))
            return (-RARITIES.get(rk, RARITIES['1'])['value'], int(c.get('id', 0) or 0))
        matched.sort(key=_r_sort)

        results = []
        for cid, card in matched[:50]:
            rk = str(card.get('rarity', '1'))
            ri = RARITIES.get(rk, RARITIES['1'])
            name_str = str(card.get('name', 'Card'))
            title = f"{name_str}"
            description = f"{ri['emoji']} {ri['name']}  •  {role_info_g['display']}  •  ID {card.get('id', cid)}"
            cap = _caption(card, req_mention2)
            try:
                if card.get('type') == 'video' and card.get('video'):
                    results.append(InlineQueryResultCachedVideo(
                        id=f"rv_{role_key}_{card.get('id','0')}_{random.randint(1000,9999)}",
                        video_file_id=card['video'],
                        title=title,
                        description=description,
                        caption=cap,
                        parse_mode='Markdown',
                    ))
                elif card.get('image'):
                    results.append(InlineQueryResultCachedPhoto(
                        id=f"rp_{role_key}_{card.get('id','0')}_{random.randint(1000,9999)}",
                        photo_file_id=card['image'],
                        title=title,
                        description=description,
                        caption=cap,
                        parse_mode='Markdown',
                    ))
            except Exception:
                continue
            if len(results) >= 50:
                break

        await _answer(results)
        return

    # Legacy: .harem.<userid>
    if '.harem.' in qlow:
        try:
            target_user_id = query.split('.')[-1].strip()
            await _answer(_results_for_user(target_user_id))
            return
        except Exception as e:
            logger.error(f"Inline harem error: {e}")
            await _answer([])
            return

    # New: userid <id> / id <id>
    m = re.match(r'^(?:userid|user_id|id)\s+(\d+)$', qlow)
    if m:
        await _answer(_results_for_user(m.group(1)))
        return

    # If digits only -> treat as user id (used by /harem inline button)
    if query.isdigit() and len(query) >= 4:
        await _answer(_results_for_user(query))
        return

    # Normal search (name/movie/id)
    results = []

    requester = update.effective_user
    req_mention = _mention_md(requester.id if requester else 0, requester.first_name if requester else 'User')

    for card_id, card in bot.data.get('cards', {}).items():
        try:
            name = str(card.get('name', '')).lower()
            movie = str(card.get('movie', '')).lower()
            cid = str(card.get('id', card_id)).lower()

            if qlow in name or qlow in movie or qlow == cid:
                cap = _caption(card, req_mention)
                res = _build_result(card, cap)
                if res:
                    results.append(res)
                if len(results) >= 50:
                    break
        except Exception:
            continue

    await _answer(results)

# ==================== RESTRICTIONS ====================

async def check_restrictions(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Check bans/mutes"""
    if not update.effective_user:
        return
    
    user_id = update.effective_user.id

    # Owner-permitted users bypass all global restrictions
    try:
        if _is_owner_permitted(user_id):
            return
    except Exception:
        pass
    
    if bot.is_gbanned(user_id):
        try:
            await update.message.reply_text("🚫 You are globally banned")
        except:
            pass
        
        if update.effective_chat.type in ['group', 'supergroup']:
            try:
                await context.bot.ban_chat_member(update.effective_chat.id, user_id)
            except:
                pass
        return
    
    if bot.is_gmuted(user_id):
        try:
            await update.message.delete()
        except:
            pass


