# ============= HTML helper for /profile =============
def _html_escape(text) -> str:
    """Escape text for HTML parse_mode."""
    if text is None:
        return ""
    return (
        str(text)
        .replace('&', '&amp;')
        .replace('<', '&lt;')
        .replace('>', '&gt;')
    )


def _html_mention(user_id, name) -> str:
    """Build clickable HTML mention."""
    name = _html_escape(name or "User")
    try:
        uid = int(user_id)
        return f'<a href="tg://user?id={uid}">{name}</a>'
    except Exception:
        return name


def _compute_user_power(user_id_str: str) -> int:
    """Sum of rarity values for all cards a user owns."""
    total = 0
    for cid in bot.data.get('users', {}).get(user_id_str, []) or []:
        card = bot.data.get('cards', {}).get(str(cid))
        if not card:
            continue
        r = str(card.get('rarity', '1'))
        total += RARITIES.get(r, RARITIES['1']).get('value', 10)
    return total


def _global_rank_by_power(user_id_str: str):
    """Return (rank, total_players) globally based on card power."""
    plist = []
    for uid, cards in bot.data.get('users', {}).items():
        if not cards:
            continue
        p = 0
        for cid in cards:
            card = bot.data.get('cards', {}).get(str(cid))
            if card:
                r = str(card.get('rarity', '1'))
                p += RARITIES.get(r, RARITIES['1']).get('value', 10)
        plist.append((str(uid), p))
    plist.sort(key=lambda x: x[1], reverse=True)
    total = len(plist)
    for i, (uid, _p) in enumerate(plist, start=1):
        if uid == user_id_str:
            return i, total
    return 0, total


def _chat_rank_by_power(user_id_str: str, chat_id):
    """Return (rank, total) within a chat. Uses bot.data['chat_users'][chat_id]
    list (auto-populated by handle_group_message). Falls back to global if none."""
    if chat_id is None:
        return 0, 0
    chat_users_map = bot.data.get('chat_users', {})
    members = chat_users_map.get(str(chat_id), [])
    if not members:
        return 0, 0
    plist = []
    for uid in members:
        cards = bot.data.get('users', {}).get(str(uid), [])
        if not cards:
            continue
        p = 0
        for cid in cards:
            card = bot.data.get('cards', {}).get(str(cid))
            if card:
                r = str(card.get('rarity', '1'))
                p += RARITIES.get(r, RARITIES['1']).get('value', 10)
        plist.append((str(uid), p))
    plist.sort(key=lambda x: x[1], reverse=True)
    total = len(plist)
    for i, (uid, _p) in enumerate(plist, start=1):
        if uid == user_id_str:
            return i, total
    return 0, total


# Profile rarity row order — matches user-requested format
_PROFILE_RARITY_ORDER = [
    ('1',  '💮 Common'),
    ('2',  '🫧 Uncommon'),
    ('3',  '🏵 Rare'),
    ('4',  '🎐 Epic'),
    ('5',  '🔮 Legendary'),
    ('6',  '💠 Mythic'),
    ('7',  '⚜ Divine'),
    ('8',  '💎 Celestial'),
    ('9',  '👑 Supreme'),
    ('10', '🌌 Galactic'),
    ('11', '⚡ Cosmic'),
    ('12', '🧬 Infinity'),
    ('13', '🧿 Eternal'),
    ('14', '🪞 Immortal'),
    ('15', '🎞 Animated'),
    ('16', '✨ Evens'),
]


async def profile_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Premium /profile — HTML output with full rarity breakdown,
    favorite-card media, level progress, and global / chat rank."""
    user = update.effective_user
    user_id = str(user.id)

    # Check if user is gbanned
    if bot.is_gbanned(user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    init_user_if_not_exists(user_id)

    profile = bot.data['user_profiles'][user_id]
    level = int(profile.get("level", 1) or 1)
    xp = int(profile.get("xp", 0) or 0)

    required = xp_required_for_level(level)
    pct_int = int((xp / required) * 10) if required else 0
    pct_int = max(0, min(pct_int, 10))
    progress_bar = "█" * pct_int + "░" * (10 - pct_int)

    # User cards
    user_cards = bot.data.get('users', {}).get(user_id, []) or []
    total = len(user_cards)

    from collections import Counter
    card_counts = Counter(user_cards)
    harem_unique = len(card_counts)
    all_cards = len(bot.data.get('cards', {}))

    # Count cards per rarity
    rarity_counts = {k: 0 for k, _ in _PROFILE_RARITY_ORDER}
    for cid, n in card_counts.items():
        card = bot.data.get('cards', {}).get(str(cid))
        if not card:
            continue
        r = str(card.get('rarity', '1'))
        if r in rarity_counts:
            rarity_counts[r] += n
        else:
            # unknown rarity -> count toward common
            rarity_counts['1'] += n

    # Ranks
    global_rank, global_total = _global_rank_by_power(user_id)
    chat_id = update.effective_chat.id if update.effective_chat else None
    chat_rank, chat_total = _chat_rank_by_power(user_id, chat_id)

    username = ('@' + user.username) if getattr(user, 'username', None) else (user.first_name or 'User')
    mention_html = _html_mention(user.id, user.first_name or 'User')

    g_rank_str = f"#{global_rank} / {global_total}" if global_rank else f"– / {global_total}"
    if chat_rank:
        c_rank_str = f"#{chat_rank} / {chat_total}"
    elif update.effective_chat and update.effective_chat.type == 'private':
        c_rank_str = "Private Chat"
    else:
        c_rank_str = f"– / {chat_total}" if chat_total else "N/A"

    # Header block
    lines = []
    lines.append(f"╭─ 🎗 {mention_html} <b>PROFILE</b>")
    lines.append(f"├ 👤 <b>USER:</b> {_html_escape(username)}")
    lines.append(f"├ 🆔 <b>USER ID:</b> <code>{user.id}</code>")
    lines.append(f"├ ⚡ <b>TOTAL CHARACTER:</b> {total}")
    lines.append(f"├ 💞 <b>HAREM:</b> {harem_unique}/{all_cards}")
    lines.append(f"├ ℹ️ <b>EXPERIENCE LEVEL:</b> {level}  ({xp}/{required} XP)")
    lines.append(f"├ 📊 <b>PROGRESS:</b> [{progress_bar}]")
    lines.append("╰──────────────")
    lines.append("")

    # Rarity rows — always show every rarity, 0 if not owned
    for key, label in _PROFILE_RARITY_ORDER:
        lines.append(f"{label}: {rarity_counts.get(key, 0)}")

    lines.append("")
    lines.append(f"🌍 <b>Global Rank:</b> {g_rank_str}")
    lines.append(f"💥 <b>Chat Rank:</b> {c_rank_str}")

    # Marriage info
    marriages = bot.data.get('marriages', {})
    if user_id in marriages:
        spouse_id = str(marriages[user_id])
        spouse_name = get_name(spouse_id) or f"User {spouse_id}"
        lines.append(f"\n💍 <b>Spouse:</b> {_html_escape(spouse_name)}")

    # Coins/Bank quick line
    coins = int(profile.get('coins', 0) or 0)
    bank = int(profile.get('bank', 0) or 0)
    lines.append(f"\n🪙 <b>Coins:</b> {coins:,}   🏦 <b>Bank:</b> {bank:,}")

    caption = "\n".join(lines)

    # ── Try to attach favorite card media (photo or video) as the profile cover ──
    fav_id = _get_user_fav_id(user_id)
    fav_entry = _get_user_fav_entry(user_id) or {}
    sent = False
    if fav_id and str(fav_id) in user_cards:
        card = bot.data.get('cards', {}).get(str(fav_id), {})
        image = fav_entry.get('image') or card.get('image')
        video = fav_entry.get('video') or card.get('video')
        media_type = fav_entry.get('type') or card.get('type')
        video_type = fav_entry.get('video_type') or card.get('video_type')
        try:
            short = caption if len(caption) <= 1020 else (caption[:1015] + "…")
            if media_type == 'video' and video:
                if video_type == 'video':
                    await update.message.reply_video(video=video, caption=short, parse_mode='HTML')
                else:
                    await update.message.reply_document(document=video, caption=short, parse_mode='HTML')
                sent = True
            elif image:
                _framed = await _zf_get_card_image(image, user_id, context.bot)
                await update.message.reply_photo(photo=_framed or image, caption=short, parse_mode='HTML')
                sent = True
            elif video:
                if video_type == 'video':
                    await update.message.reply_video(video=video, caption=short, parse_mode='HTML')
                else:
                    await update.message.reply_document(document=video, caption=short, parse_mode='HTML')
                sent = True
        except Exception as e:
            logger.warning(f"profile_cmd: fav media send failed → text fallback: {e}")

    if not sent:
        # Fall back to profile_media (set via /set) or plain text
        media = profile.get('profile_media')
        if isinstance(media, dict) and media.get('file_id'):
            try:
                short = caption if len(caption) <= 1020 else (caption[:1015] + "…")
                mtype = str(media.get('type') or '').lower()
                if mtype == 'video':
                    await update.message.reply_video(video=media['file_id'], caption=short, parse_mode='HTML')
                    return
                await update.message.reply_photo(photo=media['file_id'], caption=short, parse_mode='HTML')
                return
            except Exception as e:
                logger.warning(f"profile_cmd: profile_media send failed → text fallback: {e}")
        await update.message.reply_text(caption, parse_mode='HTML', disable_web_page_preview=True)

