async def balance_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show balance.

    • Normal: /balance → show own balance
    • Reply:  reply to a user's message + /balance → show that user's balance
    """
    user = update.effective_user

    if bot.is_gbanned(user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    # Target selection (reply user if provided)
    target_user = user
    if update.message and update.message.reply_to_message and update.message.reply_to_message.from_user:
        ru = update.message.reply_to_message.from_user
        if ru and (not getattr(ru, 'is_bot', False)):
            target_user = ru

    target_id = str(target_user.id)
    init_user_if_not_exists(target_id)

    profile = bot.data['user_profiles'][target_id]
    card_count = len(bot.data['users'].get(target_id, []))

    required = xp_required_for_level(int(profile.get('level', 1) or 1))
    xp = int(profile.get('xp', 0) or 0)
    percent = int((xp / required) * 10) if required else 0
    percent = max(0, min(percent, 10))
    bar = "█" * percent + "░" * (10 - percent)

    coins = int(profile.get('coins', 0) or 0)
    bank  = int(profile.get('bank', 0) or 0)

    caption = (
        f"💰 **Balance**\n\n"
        f"👤 {target_user.first_name}\n"
        f"🆔 `{target_id}`\n"
        f"🪙 Coins: **{coins:,}**\n"
        f"🏦 Bank: **{bank:,}**\n"
        f"💵 Total: **{coins + bank:,}**\n\n"
        f"🏆 Level: **{int(profile.get('level', 1) or 1)}**\n"
        f"⭐ XP: **{xp}/{required}**\n"
        f"[{bar}]\n\n"
        f"🎴 Cards: **{card_count}**"
    )

    # Only show profile media when checking SELF (avoid leaking other's profile media)
    if target_user.id == user.id:
        media = profile.get('profile_media')
        if isinstance(media, dict) and media.get('file_id'):
            mtype = str(media.get('type') or '').lower()
            fid = media.get('file_id')
            try:
                cap = caption if len(caption) <= 1000 else (caption[:1000] + "…")
                if mtype == 'video':
                    await update.message.reply_video(video=fid, caption=cap, parse_mode='Markdown')
                    return
                await update.message.reply_photo(photo=fid, caption=cap, parse_mode='Markdown')
                return
            except Exception as e:
                logger.warning(f"Balance media send failed, fallback to text: {e}")

    await update.message.reply_text(caption, parse_mode='Markdown')


