async def buy_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Buy card from shop"""
    user = update.effective_user
    user_id = str(user.id)

    if bot.is_gbanned(user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    if not context.args:
        await update.message.reply_text(
            "📝 /buy <rarity_number>\n"
            "📋 Check: /shop"
        )
        return

    rarity = context.args[0].strip()

    if rarity not in SHOP_PRICES:
        await update.message.reply_text(
            "❌ Invalid rarity number\n"
            "📋 Check: /shop"
        )
        return

    # Block buy-only-close + drop-lock rarities so admins can shut down
    # the shop without affecting drops. /closeshop writes to
    # 'buy_blocked_rarities' (drops still work). The legacy
    # 'locked_rarities' list (set by /lockrd) blocks drops as well — it
    # is still respected by /buy because a drop-locked rarity shouldn't
    # be purchasable either.
    _buy_locked = set(str(r) for r in bot.settings.get('buy_blocked_rarities', []) or [])
    _drop_locked = set(str(r) for r in bot.settings.get('locked_rarities', []) or [])
    if rarity in _buy_locked or rarity in _drop_locked:
        _lr_info = RARITIES.get(rarity, RARITIES['1'])
        if rarity in _buy_locked and rarity not in _drop_locked:
            reason = "🔒 Shop closed for this rarity (drops still work)"
        else:
            reason = "🔒 This rarity is currently locked"
        await update.message.reply_text(
            f"{reason}\n"
            f"❌ {_lr_info['display']} cannot be purchased\n"
            f"💡 Try dropping it via /hunt or /catch instead."
        )
        return

    init_user_if_not_exists(user_id)
    profile = bot.data['user_profiles'][user_id]
    price = SHOP_PRICES[rarity]['price']
    rarity_info = RARITIES[rarity]

    if profile['coins'] < price:
        shortage = price - profile['coins']
        await update.message.reply_text(
            f"❌ Not enough coins\n\n"
            f"🪙 Have: {profile['coins']:,} coins\n"
            f"💵 Need: {price:,} coins\n"
            f"📉 Short: {shortage:,} coins\n\n"
            f"💡 Use /daily and chat more (Level up = +100 coins)"
        )
        return

    # Get random card of that rarity
    cards = [cid for cid, card in bot.data['cards'].items()
             if str(card.get('rarity')) == rarity]

    if not cards:
        await update.message.reply_text(
            f"❌ {rarity_info['display']} card not available\n"
            "🔄 Contact admin to add cards"
        )
        return

    card_id = random.choice(cards)
    card = bot.data['cards'][card_id]

    # Deduct coins
    profile['coins'] -= price

    # Give card
    if user_id not in bot.data['users']:
        bot.data['users'][user_id] = []
    bot.data['users'][user_id].append(card_id)

    # Update card owner
    bot.data['cards'][card_id]['owner'] = user.id
    bot.data['cards'][card_id]['owner_name'] = user.first_name

    bot.save_data()

    remaining = profile['coins']
    caption = (
        f"🎉 Purchase Successful!\n\n"
        f"🎴 {card['name']}\n"
        f"🎬 {card['movie']}\n"
        f"🆔 ID: {card['id']}\n"
        f"⭐ {rarity_info['display']}\n\n"
        f"🪙 -{price:,} coins\n"
        f"💰 Remaining: {remaining:,} coins"
    )

    try:
        if card.get('type') == 'video':
            if card.get('video_type') == 'video':
                await update.message.reply_video(video=card['video'], caption=caption)
            else:
                await update.message.reply_document(document=card['video'], caption=caption)
        else:
            await update.message.reply_photo(photo=card['image'], caption=caption)
    except Exception as e:
        logger.warning(f"Buy card send media failed: {e}")
        await update.message.reply_text(caption)


async def daily_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Daily coin reward (24h cooldown)"""
    user = update.effective_user
    user_id = str(user.id)

    if bot.is_gbanned(user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    init_user_if_not_exists(user_id)
    profile = bot.data['user_profiles'][user_id]
    now = datetime.now()

    last_daily = profile.get('last_daily')
    if last_daily:
        last_dt = datetime.fromisoformat(last_daily)
        elapsed = now - last_dt
        cooldown = timedelta(hours=24)
        if elapsed < cooldown:
            remaining = cooldown - elapsed
            total_secs = int(remaining.total_seconds())
            hours = total_secs // 3600
            minutes = (total_secs % 3600) // 60
            await update.message.reply_text(
                f"⏳ **Daily not ready yet!**\n\n"
                f"💤 Wait **{hours}h {minutes}m**\n"
                f"🪙 Coins: {profile['coins']:,}",
                parse_mode='Markdown'
            )
            return

    # Grant daily reward — track count
    profile['daily_claimed_days'] = profile.get('daily_claimed_days', 0) + 1
    profile['total_earned'] = profile.get('total_earned', 0) + DAILY_REWARD
    profile['coins'] += DAILY_REWARD
    profile['last_daily'] = now.isoformat()
    bot.save_data()

    await update.message.reply_text(
        f"🎁 **Daily Reward!**\n\n"
        f"👤 {user.first_name}\n"
        f"🪙 +**{DAILY_REWARD:,}** Coins\n\n"
        f"💰 Balance: **{profile['coins']:,}** coins\n\n"
        f"⏰ Come back in 24 hours",
        parse_mode='Markdown'
    )


async def addcoin_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: add coins to user"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if len(context.args) < 2:
        await update.message.reply_text("📝 /addcoin <user_id> <amount>")
        return

    try:
        target_id = str(context.args[0])
        amount = int(context.args[1])
        if amount <= 0:
            raise ValueError
    except (ValueError, IndexError):
        await update.message.reply_text("❌ Invalid arguments. /addcoin <user_id> <amount>")
        return

    init_user_if_not_exists(target_id)
    bot.data['user_profiles'][target_id]['coins'] += amount
    bot.save_data()

    current = bot.data['user_profiles'][target_id]['coins']
    await update.message.reply_text(
        f"✅ Added **{amount:,}** coins to `{target_id}`\n"
        f"🪙 New balance: **{current:,}** coins",
        parse_mode='Markdown'
    )


async def rmcoin_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: remove coins from user"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if len(context.args) < 2:
        await update.message.reply_text("📝 /rmcoin <user_id> <amount>")
        return

    try:
        target_id = str(context.args[0])
        amount = int(context.args[1])
        if amount <= 0:
            raise ValueError
    except (ValueError, IndexError):
        await update.message.reply_text("❌ Invalid arguments. /rmcoin <user_id> <amount>")
        return

    init_user_if_not_exists(target_id)
    profile = bot.data['user_profiles'][target_id]
    removed = min(amount, profile['coins'])
    profile['coins'] = max(0, profile['coins'] - amount)
    bot.save_data()

    await update.message.reply_text(
        f"✅ Removed **{removed:,}** coins from `{target_id}`\n"
        f"🪙 New balance: **{profile['coins']:,}** coins",
        parse_mode='Markdown'
    )




async def delcoin_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: delete % of everyone coins (wallet+bank + legacy economy balances). Usage: /delcoin 10"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if not context.args:
        await update.message.reply_text("📝 /delcoin <percent>\nဥပမာ: /delcoin 10")
        return

    try:
        percent = int(context.args[0])
        if percent <= 0 or percent > 100:
            raise ValueError
    except Exception:
        await update.message.reply_text("❌ Percent must be 1-100. Example: /delcoin 10")
        return

    total_wallet_cut = 0
    total_bank_cut = 0
    total_legacy_cut = 0
    profile_affected = 0
    legacy_affected = 0

    profiles = bot.data.setdefault('user_profiles', {})
    for _uid, prof in profiles.items():
        if not isinstance(prof, dict):
            continue

        wallet = int(prof.get('coins', 0) or 0)
        bank = int(prof.get('bank', 0) or 0)

        wallet_cut = int(wallet * percent / 100)
        bank_cut = int(bank * percent / 100)

        if wallet_cut == 0 and bank_cut == 0:
            continue

        prof['coins'] = max(0, wallet - wallet_cut)
        prof['bank'] = max(0, bank - bank_cut)

        total_wallet_cut += wallet_cut
        total_bank_cut += bank_cut
        profile_affected += 1

    balances = economy_data.setdefault('balances', {})
    for _uid, bal in list(balances.items()):
        try:
            bal_int = int(bal or 0)
        except Exception:
            continue

        legacy_cut = int(bal_int * percent / 100)
        if legacy_cut <= 0:
            continue

        balances[_uid] = max(0, bal_int - legacy_cut)
        total_legacy_cut += legacy_cut
        legacy_affected += 1

    bot.save_data()
    save_economy()

    total_removed = total_wallet_cut + total_bank_cut + total_legacy_cut
    await update.message.reply_text(
        "✅ /delcoin completed\n\n"
        f"📉 Percent: {percent}%\n"
        f"👥 Profiles affected: {profile_affected}\n"
        f"🗃 Legacy balances affected: {legacy_affected}\n\n"
        f"🪙 Wallet removed: {total_wallet_cut:,}\n"
        f"🏦 Bank removed: {total_bank_cut:,}\n"
        f"💼 Legacy balance removed: {total_legacy_cut:,}\n"
        f"💰 Total removed: {total_removed:,}"
    )


async def rob_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/rob (reply): steal random 10%-100% from victim wallet (NOT bank)."""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    # Check if rob is locked
    if bot.settings.get('rob_locked', False):
        await update.message.reply_text("🔒 Rob command is currently locked by admin.")
        return

    msg = update.message
    if not msg or not msg.reply_to_message or not msg.reply_to_message.from_user:
        await update.message.reply_text("📝 Usage: Reply to someone and type /rob")
        return

    robber = update.effective_user
    victim = msg.reply_to_message.from_user

    if victim.is_bot:
        await update.message.reply_text("❌ You can't rob a bot.")
        return

    robber_id = str(robber.id)
    victim_id = str(victim.id)

    if robber_id == victim_id:
        await update.message.reply_text("❌ You can't rob yourself.")
        return

    init_user_if_not_exists(robber_id)
    init_user_if_not_exists(victim_id)

    rprof = bot.data['user_profiles'][robber_id]
    vprof = bot.data['user_profiles'][victim_id]

    victim_wallet = int(vprof.get('coins', 0) or 0)
    if victim_wallet <= 0:
        await update.message.reply_text(f"❌ {victim.first_name} ရဲ့ Wallet ထဲမှာ coins မရှိပါ။")
        return

    steal_percent = random.randint(10, 100)
    stolen = int(victim_wallet * steal_percent / 100)
    stolen = max(1, stolen)
    stolen = min(stolen, victim_wallet)

    vprof['coins'] = victim_wallet - stolen
    rprof['coins'] = int(rprof.get('coins', 0) or 0) + stolen

    bot.save_data()

    await update.message.reply_text(
        "🦹‍♂️ Rob Success!\n\n"
        f"🎯 Victim: {victim.first_name}\n"
        f"📉 Steal rate: {steal_percent}%\n"
        f"🪙 Stolen: {stolen:,} coins (wallet only)\n\n"
        f"💰 Your wallet: {rprof.get('coins', 0):,}\n"
        f"💸 Victim wallet left: {vprof.get('coins', 0):,}",
        parse_mode='Markdown'
    )


