async def massaddcoin_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: Add coins to ALL users\n/massaddcoin <amount>"""
    user_id = update.effective_user.id
    if not bot.is_owner(user_id):
        await update.message.reply_text("❌ Owner only.")
        return
    if not context.args:
        await update.message.reply_text("📝 Usage: /massaddcoin <amount>")
        return
    try:
        amount = int(context.args[0])
        if amount <= 0:
            raise ValueError
    except:
        await update.message.reply_text("❌ Invalid amount. Please enter a positive integer.")
        return

    profiles = bot.data.get('user_profiles', {})
    count = 0
    for uid, profile in profiles.items():
        profile['coins'] = int(profile.get('coins', 0) or 0) + amount
        count += 1
    bot.save_data()
    await update.message.reply_text(
        f"✅ *Mass Add Coins Done!*\n\n"
        f"🪙 Added: `{amount:,}` coins\n"
        f"👥 Users affected: `{count}`",
        parse_mode='Markdown'
    )


async def massrmcoin_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: Remove coins from ALL users\n/massrmcoin <amount>"""
    user_id = update.effective_user.id
    if not bot.is_owner(user_id):
        await update.message.reply_text("❌ Owner only.")
        return
    if not context.args:
        await update.message.reply_text("📝 Usage: /massrmcoin <amount>")
        return
    try:
        amount = int(context.args[0])
        if amount <= 0:
            raise ValueError
    except:
        await update.message.reply_text("❌ Invalid amount. Please enter a positive integer.")
        return

    profiles = bot.data.get('user_profiles', {})
    count = 0
    for uid, profile in profiles.items():
        current = int(profile.get('coins', 0) or 0)
        profile['coins'] = max(0, current - amount)
        count += 1
    bot.save_data()
    await update.message.reply_text(
        f"✅ *Mass Remove Coins Done!*\n\n"
        f"🪙 Removed: `{amount:,}` coins\n"
        f"👥 Users affected: `{count}`",
        parse_mode='Markdown'
    )


