# 🎰 ZICEKO REAL 3D SLOT – PRO VERSION
async def slot_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ZICEKO REAL 3D Slot Machine – native Telegram dice emoji"""
    global JACKPOT_POOL

    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    user = update.effective_user
    user_id = str(user.id)
    init_user_if_not_exists(user_id)

    # ── Channel / Group Join Check ──
    if not await _check_harem_join(update, context, "Slot"):
        return

    # ── 40-second Cooldown Check ──
    import time as _time
    now = _time.time()
    last_used = GAMBLE_LAST.get(user_id, 0)
    elapsed = now - last_used
    if elapsed < GAMBLE_COOLDOWN:
        remaining = int(GAMBLE_COOLDOWN - elapsed)
        await update.message.reply_text(
            f"{pe('hourglass','⏳')} ကျေးဇူးပြု၍ <b>{remaining}</b> စက္ကန့် စောင့်ပါ\n"
            f"{pe('slot_machine','🎰')} မကြာမီ ထပ်မံကစားနိုင်မည်!",
            parse_mode="HTML"
        )
        return

    # ── Load profile ──
    profile = bot.data['user_profiles'].get(user_id)
    current_balance = profile["coins"] if profile else 0

    if not context.args:
        await update.message.reply_text(
            f"{pe('slot_machine', '🎰')} <b>Usage:</b> /slot &lt;amount&gt;\n"
            f"ဥပမာ: <code>/slot 1</code>\n\n"
            f"{pe('money_bag', '💰')} Balance: <b>{current_balance:,}</b> {pe('coin', '🪙')}\n"
            f"📉 Min Bet: <b>1 coin</b> (limit မရှိ — balance ရှိသလောက် ဆော့နိုင်)\n"
            f"📈 Max Bet: <b>{current_balance:,}</b> coins",
            parse_mode="HTML"
        )
        return

    try:
        bet = int(context.args[0])
    except Exception:
        await update.message.reply_text("❌ ပမာဏ မှားနေသည် (number ထည့်ပါ)")
        return

    if bet <= 0:
        await update.message.reply_text("❌ Bet သည် 1 နှင့်အထက် ဖြစ်ရမည်")
        return

    # ── No minimum limit — play as much as you want from your balance ──
    if not profile or profile["coins"] < bet:
        await update.message.reply_text(
            f"{pe('cross_miss','❌')} <b>Coins မလုံလောက်ပါ!</b>\n\n"
            f"{pe('money_bag','💰')} Balance: <b>{current_balance:,}</b> coins\n"
            f"🎲 Bet: <b>{bet:,}</b> coins\n"
            f"📈 အများဆုံး: <b>{current_balance:,}</b> coins (balance ရှိသလောက်)",
            parse_mode='HTML'
        )
        return

    # Record cooldown timestamp
    GAMBLE_LAST[user_id] = now

    # Deduct bet first
    profile["coins"] -= bet

    # Add 5% to jackpot pool
    jackpot_add = int(bet * 0.05)
    JACKPOT_POOL += jackpot_add

    # ── REAL Telegram 3D Slot Animation ──
    msg = await context.bot.send_dice(
        chat_id=update.effective_chat.id,
        emoji="🎰"
    )
    value = msg.dice.value

    reward = 0
    result_text = ""

    # ── Win Rate Control by Owner ──
    win_rate = bot.settings.get('slot_win_rate', 40)  # default 40%
    win_roll = random.random() * 100  # 0.0 ~ 100.0

    if win_roll < win_rate:
        # ── WIN branch: determine win tier by dice value ──
        if value == 64:
            reward = bet * 10 + JACKPOT_POOL
            result_text = f"{pe('jackpot','💎')}{pe('diamond','💎')}{pe('jackpot','💎')} <b>JACKPOT</b> {pe('jackpot','💎')}{pe('diamond','💎')}{pe('jackpot','💎')}"
            JACKPOT_POOL = 0
            try:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=(
                        f"{pe('fire_win','🔥')} <b>GLOBAL JACKPOT WON!</b>\n"
                        f"{pe('crown','👑')} {user.first_name}\n"
                        f"{pe('money_bag','💰')} <b>{reward:,}</b> Coins!"
                    ),
                    parse_mode="HTML"
                )
            except Exception:
                pass
        elif value >= 40:
            reward = bet * 3
            result_text = f"{pe('fire_win','🔥')} <b>BIG WIN!</b>"
        else:
            # Ensure at least Small Win when win_roll passes
            reward = int(bet * 1.5)
            result_text = f"{pe('sparkle_win','✨')} <b>Small Win</b>"
    else:
        # ── LOSE branch ──
        result_text = f"{pe('skull_lose','💀')} <b>You Lost</b>"

    profile["coins"] += reward
    bot.save_data()

    await update.message.reply_text(
        f"╔══════════════╗\n"
        f"{pe('slot_machine','🎰')} <b>ZICEKO SLOT</b>\n"
        f"╠══════════════╣\n"
        f"👤 {user.first_name}\n"
        f"{pe('money_bag','💰')} Bet: <b>{bet:,}</b>\n"
        f"🎲 Roll: <b>{value}</b>\n"
        f"╠══════════════╣\n"
        f"{result_text}\n"
        f"{pe('diamond','💎')} Reward: <b>{reward:,}</b>\n"
        f"{pe('bank','🏦')} Jackpot Pool: <b>{JACKPOT_POOL:,}</b>\n"
        f"╚══════════════╝",
        parse_mode="HTML"
    )

# 💰 COIN LEADERBOARD
def _fmt_coins(n: int) -> str:
    """Format coin number: if >= 50 digits use scientific-style (1+eN), else normal comma-separated."""
    n = int(n)
    s = str(abs(n))
    digits = len(s)
    if digits > 50:
        # Scientific-like display e.g. 1+e52
        exp = digits - 1
        lead = s[0]
        frac = s[1:3]  # 2 decimal places
        if frac and int(frac) > 0:
            return f"{'-' if n < 0 else ''}{lead}.{frac}e+{exp}"
        return f"{'-' if n < 0 else ''}{lead}+e{exp}"
    return f"{n:,}"


