# /basket — Basketball coin-gambling using Telegram native dice
# ============================================================
async def basket_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/basket <amount>  — Telegram ရဲ့ native 🏀 dice emoji နဲ့ basketball game။

    • user တယ်သော amount သည် coin balance ထက် ကျော်ရမည်။
    • dice value ∈ {1,2}  → miss (lose bet)
    • dice value ∈ {3}    → hit rim (push — refund)
    • dice value ∈ {4,5}  → swish! (2× payout = win 1× bet)
    """
    user = update.effective_user
    if bot.is_gbanned(user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    user_id = str(user.id)
    init_user_if_not_exists(user_id)
    profile = bot.data['user_profiles'][user_id]
    coins = int(profile.get('coins', 0) or 0)

    if not context.args:
        await update.message.reply_text(
            f"{'🏀'} <b>Basket</b>\n\n"
            f"Usage: <code>/basket &lt;amount&gt;</code>\n"
            f"{'🪙'} မိမိ့ coin: <b>{coins:,}</b>\n\n"
            f"📜 Rules:\n"
            f"• {'🎯'} Swish (4–5) → Win 1× bet\n"
            f"• {'🏀'} Rim (3)      → Push (refund)\n"
            f"• {'❌'} Miss (1–2) → Lose bet\n\n"
            f"{'⏳'} Cooldown: <b>{BASKET_COOLDOWN}s</b> between games",
            parse_mode='HTML'
        )
        return

    # ── 40-second Cooldown Check (one game then wait) ──
    import time as _time
    _now_ts = _time.time()
    _last_used = BASKET_LAST.get(user_id, 0)
    _elapsed = _now_ts - _last_used
    if _elapsed < BASKET_COOLDOWN:
        _remaining = int(BASKET_COOLDOWN - _elapsed)
        await update.message.reply_text(
            f"{'⏳'} ကျေးဇူးပြု၍ <b>{_remaining}</b> စက္ကန့် စောင့်ပါ\n"
            f"{'🏀'} မကြာမီ ထပ်မံကစားနိုင်မည်!",
            parse_mode='HTML'
        )
        return

    raw = context.args[0].strip().lower()
    # Allow shortcuts: all / max
    if raw in ('all', 'max'):
        amount = coins
    else:
        try:
            amount = int(raw.replace(',', ''))
        except Exception:
            await update.message.reply_text("❌ Amount မှန်ကန်မဟုတ်ပါ။ Usage: <code>/basket 100</code>", parse_mode='HTML')
            return

    if amount <= 0:
        await update.message.reply_text("❌ Amount ငွေောင်မရ။")
        return

    if amount > coins:
        await update.message.reply_text(
            f"❌ ကွန်မလုံလောက်ပါ။\nမိမိ့: <b>{coins:,}</b>  • ပန်းထား: <b>{amount:,}</b>",
            parse_mode='HTML'
        )
        return

    # Deduct bet immediately
    profile['coins'] = coins - amount
    bot.save_data()

    # Record cooldown timestamp (one game then 40s wait)
    BASKET_LAST[user_id] = _now_ts

    mention = _html_mention(user.id, user.first_name)

    # Throw the native basketball dice
    try:
        msg = await context.bot.send_dice(
            chat_id=update.effective_chat.id,
            emoji='🏀',
            reply_to_message_id=update.message.message_id,
        )
    except Exception as e:
        # Refund on failure
        profile['coins'] = coins
        # Also clear cooldown so user can retry immediately on send error
        BASKET_LAST.pop(user_id, None)
        bot.save_data()
        await update.message.reply_text(f"❌ Dice send error: {e}\n(ပင်ဆောင်လိုက်ပြီးပါပြီ)")
        return

    value = int(getattr(msg.dice, 'value', 0) or 0)

    # Wait for animation
    await asyncio.sleep(3.5)

    if value in (4, 5):
        # Win 1x bet (2x payout total)
        payout = amount * 2
        profile['coins'] = int(profile.get('coins', 0)) + payout
        bot.save_data()
        result = (
            f"{'🏀'} <b>SWISH!</b> {'🎯'}\n\n"
            f"👤 {mention}\n"
            f"🎲 Roll: <b>{value}</b>\n"
            f"{'💰'} Bet: <b>{amount:,}</b>\n"
            f"{'🏆'} Won: <b>+{amount:,}</b>\n"
            f"{'🪙'} Balance: <b>{int(profile['coins']):,}</b>"
        )
    elif value == 3:
        # Push — refund
        profile['coins'] = int(profile.get('coins', 0)) + amount
        bot.save_data()
        result = (
            f"{'🏀'} <b>Rim Roll — Push</b>\n\n"
            f"👤 {mention}\n"
            f"🎲 Roll: <b>{value}</b>\n"
            f"{'💰'} Bet refunded: <b>{amount:,}</b>\n"
            f"{'🪙'} Balance: <b>{int(profile['coins']):,}</b>"
        )
    else:
        # Loss — already deducted
        result = (
            f"{'❌'} <b>Missed!</b>\n\n"
            f"👤 {mention}\n"
            f"🎲 Roll: <b>{value}</b>\n"
            f"{'💸'} Lost: <b>{amount:,}</b>\n"
            f"{'🪙'} Balance: <b>{int(profile['coins']):,}</b>"
        )

    try:
        await update.message.reply_text(result, parse_mode='HTML')
    except Exception:
        await update.message.reply_text(result.replace('<b>', '').replace('</b>', '').replace('<code>', '').replace('</code>', ''))


async def delg_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/delg <percent> — OWNER only: user အားလုံး၏ gold ကို percent အတိုင်း ဖျက်ရန်။
    ဥပမာ /delg 100 → gold 100% (အလုံးစုံ 0) ဖြစ်သွားမည်။"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only command.")
        return

    if not context.args:
        await update.message.reply_text(
            "📝 Usage: <code>/delg &lt;percent&gt;</code>\n"
            "ဥပမာ: <code>/delg 100</code> → gold အကုန် 0 ဖြစ်သွားမည်",
            parse_mode='HTML'
        )
        return

    try:
        pct = float(context.args[0].replace('%', '').strip())
    except Exception:
        await update.message.reply_text("❌ Percent မှန်ကန်မဟုတ်ပါ။ Usage: /delg 100")
        return

    if pct < 0 or pct > 100:
        await update.message.reply_text("❌ Percent သည် 0 မှ 100 ကြားဖြစ်ရမည်။")
        return

    total_removed = 0
    affected = 0
    for _uid in list(gold_data.keys()):
        before = int(gold_data.get(_uid, 0) or 0)
        if before <= 0:
            continue
        removed = int(before * pct / 100)
        if removed > 0:
            gold_data[_uid] = before - removed
            total_removed += removed
            affected += 1
    save_gold()

    await update.message.reply_text(
        f"✅ Gold ဖျက်သိမ်းပြီးပါပြီ\n\n"
        f"📊 Percent: <b>{pct:g}%</b>\n"
        f"👥 Affected users: <b>{affected:,}</b>\n"
        f"🥇 Total gold removed: <b>{total_removed:,}</b>",
        parse_mode='HTML'
    )


async def coinstop_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Top richest players by coins"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
