def _casino_cleanup_message(chat_id: int, message_id: int):
    CASINO_RUNTIME['sessions'].pop(_casino_message_key(chat_id, message_id), None)
    for uid, waiter in list(CASINO_RUNTIME['bet_waiters'].items()):
        if waiter.get('chat_id') == chat_id and waiter.get('message_id') == message_id:
            CASINO_RUNTIME['bet_waiters'].pop(uid, None)



def _casino_resolve_blackjack(session: dict) -> tuple[str, int, int]:
    while _casino_blackjack_total(session['dealer']) < 17:
        session['dealer'].append(_casino_draw(session['deck']))

    player_total = _casino_blackjack_total(session['player'])
    dealer_total = _casino_blackjack_total(session['dealer'])
    payout = 0

    if player_total > 21:
        result = f"💔 LOSE -{session['bet']:,}"
    elif dealer_total > 21 or player_total > dealer_total:
        payout = session['bet'] * 2
        result = f"🎉 WIN +{session['bet']:,}"
    elif player_total == dealer_total:
        payout = session['bet']
        result = '🤝 PUSH'
    else:
        result = f"💔 LOSE -{session['bet']:,}"

    if payout:
        _casino_change_balance(session['user_id'], payout, reason='casino:blackjack:resolve')
    else:
        _casino_commit()
    session['finished'] = True
    return result, player_total, dealer_total


async def _casino_finish_blackjack(context: ContextTypes.DEFAULT_TYPE, session: dict, footer: str = ''):
    result, player_total, dealer_total = _casino_resolve_blackjack(session)
    msg = footer or f"{result}\nDealer : {dealer_total} • You : {player_total}"
    await _casino_safe_edit(
        context,
        session['chat_id'],
        session['message_id'],
        _casino_blackjack_text(session, reveal_dealer=True, footer=msg),
        _casino_result_keyboard('blackjack', session['base_bet'])
    )



def _casino_try_blackjack_natural(session: dict) -> tuple[bool, str | None]:
    player_bj = _casino_is_blackjack(session['player'])
    dealer_bj = _casino_is_blackjack(session['dealer'])
    if not player_bj and not dealer_bj:
        return False, None

    if player_bj and dealer_bj:
        _casino_change_balance(session['user_id'], session['bet'], reason='casino:blackjack:push')
        footer = '🤝 PUSH • Double Blackjack'
    elif player_bj:
        payout = int(session['bet'] * 2.5)
        _casino_change_balance(session['user_id'], payout, reason='casino:blackjack:natural')
        footer = f"🏆 BLACKJACK +{int(session['bet'] * 1.5):,}"
    else:
        footer = f"💔 Dealer Blackjack -{session['bet']:,}"
        _casino_commit()
    session['finished'] = True
    return True, footer


async def _casino_start_game(context: ContextTypes.DEFAULT_TYPE, chat_id: int, message_id: int, user_id_str: str, game: str, bet: int):
    if bet <= 0:
        raise ValueError('bet must be positive')
    balance = _casino_get_balance(user_id_str)
    if balance < bet:
        raise ValueError('insufficient balance')

    remain = _casino_check_cooldown(user_id_str, game)
    if remain > 0:
        raise RuntimeError(f'cooldown:{remain}')

    _casino_start_cooldown(user_id_str, game, CASINO_GAME_COOLDOWNS.get(game, 3))
    _casino_change_balance(user_id_str, -bet, reason=f'casino:{game}:bet')

    session = {
        'owner_id': int(user_id_str),
        'user_id': user_id_str,
        'chat_id': chat_id,
        'message_id': message_id,
        'game': game,
        'bet': bet,
        'base_bet': bet,
        'started_at': time.time(),
        'finished': False,
    }

    key = _casino_message_key(chat_id, message_id)

    if game == 'blackjack':
        deck = _casino_new_deck()
        session.update({
            'deck': deck,
            'player': [_casino_draw(deck), _casino_draw(deck)],
            'dealer': [_casino_draw(deck), _casino_draw(deck)],
        })
        CASINO_RUNTIME['sessions'][key] = session
        is_done, footer = _casino_try_blackjack_natural(session)
        if is_done:
            await _casino_safe_edit(
                context,
                chat_id,
                message_id,
                _casino_blackjack_text(session, reveal_dealer=True, footer=footer),
                _casino_result_keyboard('blackjack', session['base_bet'])
            )
        else:
            await _casino_safe_edit(context, chat_id, message_id, _casino_blackjack_text(session), _casino_blackjack_keyboard())
        return

    if game == 'shan':
        deck = _casino_new_deck()
        session.update({
            'deck': deck,
            'player': [_casino_draw(deck), _casino_draw(deck)],
            'dealer': [_casino_draw(deck), _casino_draw(deck)],
            'drew': False,
        })
        CASINO_RUNTIME['sessions'][key] = session
        await _casino_safe_edit(context, chat_id, message_id, _casino_shan_text(session), _casino_shan_keyboard(can_draw=True))
        return

    if game == 'headtail':
        CASINO_RUNTIME['sessions'][key] = session
        await _casino_safe_edit(context, chat_id, message_id, _casino_headtail_text(_casino_get_balance(user_id_str), bet), _casino_headtail_keyboard())
        return

    if game == 'dice':
        CASINO_RUNTIME['sessions'][key] = session
        await _casino_safe_edit(context, chat_id, message_id, _casino_dice_text(_casino_get_balance(user_id_str), bet), _casino_dice_keyboard())
        return


