def _casino_pick_jackpot_winner() -> dict | None:
    casino = _casino_bootstrap()
    tickets = {uid: int(cnt or 0) for uid, cnt in casino.get('jackpot_tickets', {}).items() if int(cnt or 0) > 0}
    total_tickets = sum(tickets.values())
    if total_tickets < 5:
        return None
    draw_chance = min(0.35, 0.10 + total_tickets * 0.02)
    if random.random() > draw_chance:
        _casino_commit()
        return None

    winning_index = random.randint(1, total_tickets)
    cursor = 0
    winner_uid = None
    for uid, count in tickets.items():
        cursor += count
        if winning_index <= cursor:
            winner_uid = uid
            break
    if not winner_uid:
        return None

    prize = int(casino.get('jackpot_pool', 0) or 0)
    _casino_change_balance(winner_uid, prize, reason='casino:jackpot:win', autosave=False)
    winner_name = _casino_get_display_name(winner_uid)
    casino['jackpot_last_winner'] = {
        'user_id': winner_uid,
        'name': winner_name,
        'prize': prize,
        'time': datetime.now().isoformat(),
    }
    casino['jackpot_pool'] = 0
    casino['jackpot_tickets'] = {}
    _casino_commit()
    return casino['jackpot_last_winner']


async def casino_custom_bet_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user or not update.message or update.effective_user.is_bot:
        return

    uid = str(update.effective_user.id)
    waiter = CASINO_RUNTIME['bet_waiters'].get(uid)
    if not waiter:
        return

    if waiter.get('chat_id') != update.effective_chat.id:
        return

    try:
        await update.message.delete()
    except Exception:
        pass

    if time.time() - float(waiter.get('created_at', 0) or 0) > CASINO_CUSTOM_BET_TIMEOUT:
        CASINO_RUNTIME['bet_waiters'].pop(uid, None)
        await _casino_safe_edit(
            context,
            waiter['chat_id'],
            waiter['message_id'],
            '⌛ Custom bet expired\n\nပြန်ရွေးချယ်ပေးပါ။',
            _casino_bet_keyboard(waiter['game'])
        )
        raise ApplicationHandlerStop

    amount = _casino_parse_amount(update.message.text or '')
    balance = _casino_get_balance(uid)
    if amount is None or amount <= 0:
        await _casino_safe_edit(
            context,
            waiter['chat_id'],
            waiter['message_id'],
            (
                f"{_casino_title(waiter['game'])}\n\n"
                '✏️ Custom Bet\n\n'
                'Coin ပမာဏကို number / 10k / 1m ပုံစံနဲ့ ပို့ပါ။\n\n'
                f"💎 Balance : {balance:,}"
            ),
            _casino_bet_keyboard(waiter['game'])
        )
        raise ApplicationHandlerStop

    if amount > balance:
        await _casino_safe_edit(
            context,
            waiter['chat_id'],
            waiter['message_id'],
            (
                f"{_casino_title(waiter['game'])}\n\n"
                '❌ Balance ထက်ပိုမလောင်းနိုင်ပါ\n\n'
                f"💰 Requested : {amount:,}\n"
                f"💎 Balance : {balance:,}"
            ),
            _casino_bet_keyboard(waiter['game'])
        )
        raise ApplicationHandlerStop

    CASINO_RUNTIME['bet_waiters'].pop(uid, None)
    try:
        await _casino_start_game(context, waiter['chat_id'], waiter['message_id'], uid, waiter['game'], amount)
    except RuntimeError as e:
        if str(e).startswith('cooldown:'):
            remain = str(e).split(':', 1)[1]
            await _casino_safe_edit(
                context,
                waiter['chat_id'],
                waiter['message_id'],
                f"⏳ {CASINO_GAME_NAMES.get(waiter['game'], waiter['game'])}\n\nCooldown : {remain}s",
                _casino_bet_keyboard(waiter['game'])
            )
        else:
            raise
    except ValueError:
        await _casino_safe_edit(
            context,
            waiter['chat_id'],
            waiter['message_id'],
            '❌ Not enough balance',
            _casino_bet_keyboard(waiter['game'])
        )
    raise ApplicationHandlerStop


async def casino_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    if not query or not query.message or not query.from_user:
        return

    uid = str(query.from_user.id)
    allowed, remaining = _casino_action_allowed(uid)
    if not allowed:
        try:
            await query.answer(f'Please wait {remaining:.1f}s', show_alert=False)
        except Exception:
            pass
        return

    key = _casino_message_key(query.message.chat_id, query.message.message_id)
    session = CASINO_RUNTIME['sessions'].get(key)
    if session and int(session.get('owner_id', 0) or 0) not in {0, query.from_user.id}:
        await query.answer('ဒီ Casino Table က အခြား user အတွက် ဖြစ်ပါတယ်။', show_alert=True)
        return

    parts = (query.data or '').split('|')
    if len(parts) < 2:
        return

    _casino_bootstrap()
    init_user_if_not_exists(uid)

    action = parts[1]

    if action == 'close':
        _casino_cleanup_message(query.message.chat_id, query.message.message_id)
        try:
            await query.message.delete()
        except Exception:
            await _casino_safe_edit(context, query.message.chat_id, query.message.message_id, '❌ Casino closed')
        return

    if action == 'menu':
        CASINO_RUNTIME['bet_waiters'].pop(uid, None)
        await _casino_render_menu(context, query.message.chat_id, query.message.message_id, uid)
        return

    if action == 'open' and len(parts) >= 3:
        game = CASINO_GAME_ALIASES.get(parts[2], 'blackjack')
        CASINO_RUNTIME['bet_waiters'].pop(uid, None)
        if game == 'jackpot':
            await _casino_render_jackpot(context, query.message.chat_id, query.message.message_id, uid)
        else:
            await _casino_open_bet_menu(context, query.message.chat_id, query.message.message_id, uid, game)
        return

    if action == 'again' and len(parts) >= 4:
        game = CASINO_GAME_ALIASES.get(parts[2], 'blackjack')
        bet = int(parts[3])
        try:
            await _casino_start_game(context, query.message.chat_id, query.message.message_id, uid, game, bet)
        except RuntimeError as e:
            remain = str(e).split(':', 1)[1] if ':' in str(e) else '0'
            await query.answer(f'Cooldown {remain}s', show_alert=True)
        except ValueError:
            await query.answer('Not enough balance', show_alert=True)
        return

    if action == 'bet' and len(parts) >= 4:
        game = CASINO_GAME_ALIASES.get(parts[2], 'blackjack')
        balance = _casino_get_balance(uid)
        bet = balance if parts[3] == 'all' else int(parts[3])
        if bet <= 0 or balance < bet:
            await query.answer('Balance မလုံလောက်ပါ', show_alert=True)
            return
        try:
            await _casino_start_game(context, query.message.chat_id, query.message.message_id, uid, game, bet)
        except RuntimeError as e:
            remain = str(e).split(':', 1)[1] if ':' in str(e) else '0'
            await query.answer(f'Cooldown {remain}s', show_alert=True)
        except ValueError:
            await query.answer('Not enough balance', show_alert=True)
        return

    if action == 'betcustom' and len(parts) >= 3:
        game = CASINO_GAME_ALIASES.get(parts[2], 'blackjack')
        CASINO_RUNTIME['bet_waiters'][uid] = {
            'game': game,
            'chat_id': query.message.chat_id,
            'message_id': query.message.message_id,
            'created_at': time.time(),
        }
        await _casino_safe_edit(
            context,
            query.message.chat_id,
            query.message.message_id,
            (
                f"{_casino_title(game)}\n\n"
                '✏️ Custom Bet\n\n'
                'Coin ပမာဏကို normal message အဖြစ် ပို့ပါ\n'
                'ဥပမာ : 250000 / 500k / 2m\n\n'
                f"💎 Balance : {_casino_get_balance(uid):,}"
            ),
            _casino_bet_keyboard(game)
        )
        return

    live = CASINO_RUNTIME['sessions'].get(key)
    if not live:
        await _casino_render_menu(context, query.message.chat_id, query.message.message_id, uid)
        return

    if live.get('finished') and action not in {'menu', 'again'}:
        await query.answer('Round finished', show_alert=False)
        return

    if action == 'bj' and len(parts) >= 3:
        move = parts[2]
        if live.get('game') != 'blackjack':
            return
        if move == 'hit':
            live['player'].append(_casino_draw(live['deck']))
            if _casino_blackjack_total(live['player']) > 21:
                await _casino_finish_blackjack(context, live, footer='💥 BUST')
            else:
                await _casino_safe_edit(context, live['chat_id'], live['message_id'], _casino_blackjack_text(live), _casino_blackjack_keyboard())
            return
        if move == 'stand':
            await _casino_finish_blackjack(context, live)
            return
        if move == 'double':
            balance = _casino_get_balance(uid)
            extra = live['bet']
            if balance < extra:
                await query.answer('Double လုပ်ဖို့ coin မလုံလောက်ပါ', show_alert=True)
                return
            _casino_change_balance(uid, -extra, reason='casino:blackjack:double')
            live['bet'] += extra
            live['player'].append(_casino_draw(live['deck']))
            await _casino_finish_blackjack(context, live, footer='💸 Double Down')
            return
        if move == 'allin':
            balance = _casino_get_balance(uid)
            if balance <= 0:
                await query.answer('All In လုပ်ဖို့ coin မကျန်ပါ', show_alert=True)
                return
            _casino_change_balance(uid, -balance, reason='casino:blackjack:allin')
            live['bet'] += balance
            live['player'].append(_casino_draw(live['deck']))
            await _casino_finish_blackjack(context, live, footer='🔥 All In')
            return

    if action == 'shan' and len(parts) >= 3:
        move = parts[2]
        if live.get('game') != 'shan':
            return
        if move == 'draw':
            if live.get('drew') or len(live['player']) >= 3:
                await query.answer('Draw already used', show_alert=True)
                return
            live['player'].append(_casino_draw(live['deck']))
            live['drew'] = True
            await _casino_safe_edit(
                context,
                live['chat_id'],
                live['message_id'],
                _casino_shan_text(live, footer='🎴 One more card drawn'),
                _casino_shan_keyboard(can_draw=False)
            )
            return
        if move == 'fold':
            refund = live['bet'] // 2
            if refund > 0:
                _casino_change_balance(uid, refund, reason='casino:shan:fold')
            live['finished'] = True
            await _casino_safe_edit(
                context,
                live['chat_id'],
                live['message_id'],
                _casino_shan_text(live, reveal=False, footer=f'❌ Fold • Refund {refund:,}'),
                _casino_result_keyboard('shan', live['base_bet'])
            )
            return
        if move == 'reveal':
            while len(live['dealer']) < 3 and _casino_shan_total(live['dealer']) <= 5:
                live['dealer'].append(_casino_draw(live['deck']))
            player_total = _casino_shan_total(live['player'])
            dealer_total = _casino_shan_total(live['dealer'])
            if player_total > dealer_total:
                _casino_change_balance(uid, live['bet'] * 2, reason='casino:shan:win')
                result = f'🎉 WIN +{live["bet"]:,}'
            elif player_total == dealer_total:
                _casino_change_balance(uid, live['bet'], reason='casino:shan:push')
                result = '🤝 PUSH'
            else:
                _casino_commit()
                result = f'💔 LOSE -{live["bet"]:,}'
            live['finished'] = True
            await _casino_safe_edit(
                context,
                live['chat_id'],
                live['message_id'],
                _casino_shan_text(live, reveal=True, footer=result),
                _casino_result_keyboard('shan', live['base_bet'])
            )
            return

    if action == 'ht' and len(parts) >= 3:
        side = parts[2]
        if live.get('game') != 'headtail':
            return
        balance = _casino_get_balance(uid)
        frames = [
            '🪙 Head & Tail\n\n🪙 Flipping...\n\n🪙',
            '🪙 Head & Tail\n\n🪙 Flipping...\n\n🪙\n🪙',
            '🪙 Head & Tail\n\n🪙 Flipping...\n\n🪙\n🪙\n🪙',
        ]
        for frame in frames:
            await _casino_safe_edit(context, live['chat_id'], live['message_id'], frame)
            await asyncio.sleep(0.35)
        result = random.choice(['head', 'tail'])
        won = result == side
        if won:
            _casino_change_balance(uid, live['bet'] * 2, reason='casino:headtail:win')
            result_text = f"{'👑 HEAD' if result == 'head' else '🐉 TAIL'}\n\n🎉 WIN +{live['bet']:,}"
        else:
            _casino_commit()
            result_text = f"{'👑 HEAD' if result == 'head' else '🐉 TAIL'}\n\n💔 LOSE -{live['bet']:,}"
        live['finished'] = True
        await _casino_safe_edit(
            context,
            live['chat_id'],
            live['message_id'],
            _casino_headtail_text(_casino_get_balance(uid), live['bet'], result_text),
            _casino_result_keyboard('headtail', live['base_bet'])
        )
        return

    if action == 'dice' and len(parts) >= 3:
        pick = parts[2]
        if live.get('game') != 'dice':
            return
        frames = ['🎲 Rolling.  ', '🎲 Rolling.. ', '🎲 Rolling...']
        for frame in frames:
            await _casino_safe_edit(
                context,
                live['chat_id'],
                live['message_id'],
                _casino_dice_text(_casino_get_balance(uid), live['bet'], frame)
            )
            await asyncio.sleep(0.35)
        rolled = random.randint(1, 6)
        won = (pick == 'low' and rolled <= 3) or (pick == 'high' and rolled >= 4)
        if won:
            _casino_change_balance(uid, live['bet'] * 2, reason='casino:dice:win')
            result = f'🎯 Rolled : {rolled}\n🎉 WIN +{live["bet"]:,}'
        else:
            _casino_commit()
            result = f'🎯 Rolled : {rolled}\n💔 LOSE -{live["bet"]:,}'
        live['finished'] = True
        await _casino_safe_edit(
            context,
            live['chat_id'],
            live['message_id'],
            _casino_dice_text(_casino_get_balance(uid), live['bet'], result),
            _casino_result_keyboard('dice', live['base_bet'])
        )
        return

    if action == 'jp' and len(parts) >= 3:
        move = parts[2]
        if move == 'buy':
            remain = _casino_check_cooldown(uid, 'jackpot')
            if remain > 0:
                await query.answer(f'Cooldown {remain}s', show_alert=True)
                return
            balance = _casino_get_balance(uid)
            if balance < CASINO_TICKET_PRICE:
                await query.answer('Ticket ဝယ်ဖို့ coin မလုံလောက်ပါ', show_alert=True)
                return
            _casino_start_cooldown(uid, 'jackpot', CASINO_GAME_COOLDOWNS['jackpot'])
            _casino_change_balance(uid, -CASINO_TICKET_PRICE, reason='casino:jackpot:ticket', autosave=False)
            casino = _casino_bootstrap()
            casino['jackpot_pool'] = int(casino.get('jackpot_pool', 0) or 0) + CASINO_TICKET_PRICE
            tickets = casino.setdefault('jackpot_tickets', {})
            tickets[uid] = int(tickets.get(uid, 0) or 0) + 1
            winner = _casino_pick_jackpot_winner()
            if winner:
                text = _casino_jackpot_text() + f"\n\n🎉 Winner : {winner['name']}\nPrize Paid : {int(winner['prize']):,}"
            else:
                _casino_commit()
                text = _casino_jackpot_text() + f"\n\nYour Tickets : {tickets.get(uid, 0):,}"
            await _casino_safe_edit(context, query.message.chat_id, query.message.message_id, text, _casino_jackpot_keyboard())
            return


