async def eventshop_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show event shop"""
    if not is_event_active():
        await update.message.reply_text("❌ No active event")
        return
    
    event = events["active_event"]
    currency = event.get("currency_emoji", "🎃")
    
    text = f"🛍 **EVENT SHOP**\n\n"
    
    for key, item in EVENT_SHOP.items():
        rarity_info = RARITIES.get(item["rarity"], RARITIES['1'])
        text += f"**{key}.** {item['name']}\n"
        text += f"   {rarity_info['display']}\n"
        text += f"   💰 Price: {item['price']} {currency}\n\n"
    
    text += f"📌 Use: /eventbuy <number>"
    
    await update.message.reply_text(text, parse_mode='Markdown')

async def eventbuy_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Buy item from event shop"""
    if not is_event_active():
        await update.message.reply_text("❌ No active event")
        return
    
    if not context.args:
        await update.message.reply_text("📝 Usage: /eventbuy <item_number>")
        return
    
    item_id = context.args[0]
    user_id = str(update.effective_user.id)
    init_user_if_not_exists(user_id)
    profile = bot.data['user_profiles'][user_id]
    
    if item_id not in EVENT_SHOP:
        await update.message.reply_text("❌ Invalid item number")
        return
    
    item = EVENT_SHOP[item_id]
    event = events["active_event"]
    currency = event.get("currency_emoji", "🎪")
    
    event_coins = profile.get("event_coins", 0)
    
    if event_coins < item["price"]:
        await update.message.reply_text(
            f"❌ Not enough {currency}!\n"
            f"Required: {item['price']} {currency}\n"
            f"You have: {event_coins} {currency}"
        )
        return
    
    # Get random card of specified rarity
    rarity_cards = [cid for cid, card in bot.data['cards'].items() 
                   if card.get('rarity') == item["rarity"]]
    
    if not rarity_cards:
        await update.message.reply_text("❌ No cards available in this rarity")
        return
    
    card_id = random.choice(rarity_cards)
    card = bot.data['cards'][card_id]
    
    # Deduct coins
    profile["event_coins"] = event_coins - item["price"]
    
    # Give card
    if user_id not in bot.data['users']:
        bot.data['users'][user_id] = []
    bot.data['users'][user_id].append(card_id)
    
    bot.save_data()
    
    rarity_info = RARITIES.get(item["rarity"], RARITIES['1'])
    
    caption = f"""
🎉 **Purchase Successful!**

{item['name']}

🎴 {card['name']}
🎬 {card['movie']}
🆔 ID: {card['id']}
⭐ {rarity_info['display']}

💰 Remaining {currency}: {profile['event_coins']}
"""
    
    if card.get('type') == 'video':
        if card.get('video_type') == 'video':
            await update.message.reply_video(video=card['video'], caption=caption, parse_mode='Markdown')
        else:
            await update.message.reply_document(document=card['video'], caption=caption, parse_mode='Markdown')
    else:
        await update.message.reply_photo(photo=card['image'], caption=caption, parse_mode='Markdown')

async def eventlb_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show event leaderboard"""
    if not is_event_active():
        await update.message.reply_text("❌ No active event")
        return
    
    event = events["active_event"]
    currency = event.get("currency_emoji", "🎪")
    
    # Sort users by event_coins
    user_scores = []
    for uid, profile in bot.data['user_profiles'].items():
        event_coins = profile.get("event_coins", 0)
        if event_coins > 0:
            # Get username
            user_name = "Unknown"
            for card in bot.data['cards'].values():
                if str(card.get('owner')) == uid:
                    user_name = card.get('owner_name', 'Unknown')
                    break
            user_scores.append((uid, user_name, event_coins))
    
    user_scores.sort(key=lambda x: x[2], reverse=True)
    top_10 = user_scores[:10]
    
    text = f"🏆 **EVENT LEADERBOARD**\n"
    text += f"🎪 {event['name']}\n\n"
    
    medals = {1: "🥇", 2: "🥈", 3: "🥉"}
    
    for idx, (uid, name, coins) in enumerate(top_10, 1):
        medal = medals.get(idx, f"{idx}.")
        try:
            user_mention = f"[{name}](tg://user?id={uid})"
        except:
            user_mention = name
        text += f"{medal} {user_mention}\n"
        text += f"   💰 {coins} {currency}\n\n"
    
    await update.message.reply_text(text, parse_mode='Markdown')

async def registerevent_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Register a card as event card (Admin only)"""
    if not bot.is_admin(update.effective_user.id):
        await update.message.reply_text("❌ Admin only")
        return
    
    if not context.args:
        await update.message.reply_text("📝 /registerevent <card_id>")
        return
    
    card_id = context.args[0]
    
    if card_id not in bot.data['cards']:
        await update.message.reply_text("❌ Card not found")
        return
    
    events["event_cards"][card_id] = True
    save_events()
    
    card = bot.data['cards'][card_id]
    await update.message.reply_text(
        f"✅ Card registered as event card!\n\n"
        f"🆔 {card_id}\n"
        f"📛 {card['name']}\n"
        f"🎬 {card['movie']}"
    )

async def unregisterevent_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Unregister event card (Admin only)"""
    if not bot.is_admin(update.effective_user.id):
        await update.message.reply_text("❌ Admin only")
        return
    
    if not context.args:
        await update.message.reply_text("📝 /unregisterevent <card_id>")
        return
    
    card_id = context.args[0]
    
    if card_id in events["event_cards"]:
        del events["event_cards"][card_id]
        save_events()
        await update.message.reply_text(f"✅ Card {card_id} removed from event cards")
    else:
        await update.message.reply_text(f"❌ Card {card_id} is not an event card")

