# ==================== AFK SYSTEM ====================

async def afk_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Set AFK status"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    user_id = update.effective_user.id
    reason = " ".join(context.args) if context.args else "AFK"
    AFK_USERS[user_id] = reason
    await update.message.reply_text(f"😴 You are now AFK: {reason}")


async def unafk_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Remove AFK status manually"""
    user_id = update.effective_user.id
    if user_id in AFK_USERS:
        del AFK_USERS[user_id]
        await update.message.reply_text("✅ AFK removed! You are back.")
    else:
        await update.message.reply_text("ℹ️ You are not AFK.")


async def afklist_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """List all AFK users"""
    if not AFK_USERS:
        await update.message.reply_text("✅ No one is AFK right now.")
        return
    text = "😴 **AFK Users**\n\n"
    for uid, reason in AFK_USERS.items():
        name = get_name(uid) or str(uid)
        text += f"👤 [{name}](tg://user?id={uid}): {reason}\n"
    await update.message.reply_text(text, parse_mode='Markdown')


# ==================== CARD TRADE SYSTEM ====================

# Pending trades: {initiator_id: {"card_id": str, "target_id": int, "target_card_id": str}}
PENDING_TRADES = {}

async def trade_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Initiate a card trade: /trade @user your_card_id their_card_id"""
    # Trade lock (Owner command /locktrade)
    if bot.settings.get('trade_locked') and not bot.is_owner(update.effective_user.id):
        await update.message.reply_text('🔒 Trade system is locked')
        return

    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    user = update.effective_user
    user_id = str(user.id)

    if len(context.args) < 2:
        await update.message.reply_text(
            "📝 Usage: /trade <your_card_id> <their_card_id>\n"
            "Reply to the target user's message, OR mention them first.\n"
            "Example: /trade 12 45"
        )
        return

    # Get target user from reply
    if not update.message.reply_to_message:
        await update.message.reply_text("↩️ Reply to the user you want to trade with.")
        return

    target_user = update.message.reply_to_message.from_user
    if not target_user or target_user.is_bot:
        await update.message.reply_text("❌ Invalid target user.")
        return

    target_id = str(target_user.id)

    if target_id == user_id:
        await update.message.reply_text("❌ Cannot trade with yourself.")
        return

    my_card_id = context.args[0]
    their_card_id = context.args[1]

    # Validate cards
    my_cards = bot.data.get('users', {}).get(user_id, [])
    their_cards = bot.data.get('users', {}).get(target_id, [])

    if my_card_id not in my_cards:
        await update.message.reply_text(f"❌ You don't own card ID {my_card_id}")
        return

    if their_card_id not in their_cards:
        await update.message.reply_text(f"❌ {target_user.first_name} doesn't own card ID {their_card_id}")
        return

    if my_card_id not in bot.data.get('cards', {}):
        await update.message.reply_text(f"❌ Card {my_card_id} not found in database.")
        return

    if their_card_id not in bot.data.get('cards', {}):
        await update.message.reply_text(f"❌ Card {their_card_id} not found in database.")
        return

    my_card = bot.data['cards'][my_card_id]
    their_card = bot.data['cards'][their_card_id]

    # Store pending trade
    PENDING_TRADES[user.id] = {
        "card_id": my_card_id,
        "target_id": target_user.id,
        "target_card_id": their_card_id
    }

    keyboard = InlineKeyboardMarkup([
        [
            InlineKeyboardButton("✅ Accept", callback_data=f"trade_accept_{user.id}"),
            InlineKeyboardButton("❌ Decline", callback_data=f"trade_decline_{user.id}")
        ]
    ])

    await update.message.reply_text(
        f"🔄 **Trade Request**\n\n"
        f"👤 {user.first_name} offers:\n"
        f"🎴 {my_card.get('name', '?')} (ID: {my_card_id})\n"
        f"⭐ {RARITIES.get(my_card.get('rarity','1'), RARITIES['1'])['display']}\n\n"
        f"🎯 For {target_user.first_name}'s:\n"
        f"🎴 {their_card.get('name', '?')} (ID: {their_card_id})\n"
        f"⭐ {RARITIES.get(their_card.get('rarity','1'), RARITIES['1'])['display']}\n\n"
        f"⏳ {target_user.first_name}, accept or decline?",
        parse_mode='Markdown',
        reply_markup=keyboard
    )


async def trade_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle trade accept/decline callbacks"""
    query = update.callback_query
    await query.answer()

    data = query.data
    responder = query.from_user

    if data.startswith("trade_accept_"):
        initiator_id = int(data.split("_")[2])
        trade = PENDING_TRADES.get(initiator_id)

        if not trade:
            await query.edit_message_text("❌ Trade expired or not found.")
            return

        # Verify responder is the target
        if responder.id != trade["target_id"]:
            await query.answer("❌ This trade is not for you!", show_alert=True)
            return

        initiator_id_str = str(initiator_id)
        target_id_str = str(trade["target_id"])
        my_card_id = trade["card_id"]
        their_card_id = trade["target_card_id"]

        # Verify ownership again
        my_cards = bot.data.get('users', {}).get(initiator_id_str, [])
        their_cards = bot.data.get('users', {}).get(target_id_str, [])

        if my_card_id not in my_cards:
            await query.edit_message_text("❌ Trade failed: Initiator no longer owns that card.")
            PENDING_TRADES.pop(initiator_id, None)
            return

        if their_card_id not in their_cards:
            await query.edit_message_text("❌ Trade failed: You no longer own that card.")
            PENDING_TRADES.pop(initiator_id, None)
            return

        # Execute trade
        my_cards.remove(my_card_id)
        my_cards.append(their_card_id)
        their_cards.remove(their_card_id)
        their_cards.append(my_card_id)

        # Update card owner info
        if my_card_id in bot.data.get('cards', {}):
            bot.data['cards'][my_card_id]['owner'] = trade["target_id"]
            bot.data['cards'][my_card_id]['owner_name'] = responder.first_name
        if their_card_id in bot.data.get('cards', {}):
            bot.data['cards'][their_card_id]['owner'] = initiator_id
            bot.data['cards'][their_card_id]['owner_name'] = get_name(initiator_id_str) or str(initiator_id)

        try:
            bot.save_data()
        except Exception as e:
            logger.error(f"Trade save error: {e}")

        PENDING_TRADES.pop(initiator_id, None)

        my_card_info = bot.data['cards'].get(their_card_id, {})
        their_card_info = bot.data['cards'].get(my_card_id, {})

        await query.edit_message_text(
            f"✅ **Trade Complete!**\n\n"
            f"🎴 {responder.first_name} received: {my_card_info.get('name','?')} (ID: {their_card_id})\n"
            f"🎴 Partner received: {their_card_info.get('name','?')} (ID: {my_card_id})\n\n"
            f"🤝 Trade successful!",
            parse_mode='Markdown'
        )

    elif data.startswith("trade_decline_"):
        initiator_id = int(data.split("_")[2])
        trade = PENDING_TRADES.get(initiator_id)

        if trade and responder.id != trade["target_id"]:
            await query.answer("❌ This trade is not for you!", show_alert=True)
            return

        PENDING_TRADES.pop(initiator_id, None)
        await query.edit_message_text("❌ Trade declined.")




# ==================== MARRIAGE SYSTEM ====================

# Cooldown for mystery box (in-memory): {user_id: last_used_timestamp}
MYSTERYBOX_COOLDOWN = {}
MYSTERYBOX_COST     = 1000
MYSTERYBOX_COOLDOWN_SECONDS = 3600  # 1 hour between opens

RING_COST = 500  # Cost in coins to propose (ring fee)


async def marry_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Propose marriage: reply to target user with /marry"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    proposer = update.effective_user
    proposer_id = str(proposer.id)

    if not update.message.reply_to_message:
        await update.message.reply_text(
            "💍 **Marriage**\n\n"
            "Reply to the person you want to propose to, then type /marry\n\n"
            f"💰 Ring fee: **{RING_COST:,} coins**",
            parse_mode='Markdown'
        )
        return

    target = update.message.reply_to_message.from_user
    if not target or target.is_bot:
        await update.message.reply_text("❌ Cannot propose to a bot.")
        return

    target_id = str(target.id)

    if proposer_id == target_id:
        await update.message.reply_text("❌ Cannot propose to yourself 😅")
        return

    init_user_if_not_exists(proposer_id)
    init_user_if_not_exists(target_id)

    marriages  = bot.data.setdefault('marriages',  {})
    proposals  = bot.data.setdefault('proposals',  {})
    profile    = bot.data['user_profiles'][proposer_id]

    # Check if already married
    if proposer_id in marriages:
        partner_id   = str(marriages[proposer_id])
        partner_name = get_name(partner_id) or f"User {partner_id}"
        await update.message.reply_text(
            f"❌ You are already married to **{partner_name}**!\n"
            f"Use /divorce first.",
            parse_mode='Markdown'
        )
        return

    if target_id in marriages:
        await update.message.reply_text(
            f"❌ **{target.first_name}** is already married to someone else!",
            parse_mode='Markdown'
        )
        return

    # Check coins
    if profile.get('coins', 0) < RING_COST:
        await update.message.reply_text(
            f"❌ You need **{RING_COST:,} coins** to buy a ring!\n"
            f"You have: **{profile.get('coins',0):,} coins**",
            parse_mode='Markdown'
        )
        return

    # Deduct ring fee
    profile['coins'] -= RING_COST

    # Store proposal
    proposals[target_id] = {
        "from_id":   proposer.id,
        "from_name": proposer.first_name
    }

    bot.save_data()

    keyboard = InlineKeyboardMarkup([
        [
            InlineKeyboardButton("💖 Accept", callback_data=f"marry_accept_{proposer.id}"),
            InlineKeyboardButton("💔 Decline", callback_data=f"marry_decline_{proposer.id}")
        ]
    ])

    await update.message.reply_text(
        f"💍 **Marriage Proposal!**\n\n"
        f"💕 **{proposer.first_name}** proposes to **{target.first_name}**!\n\n"
        f"**{target.first_name}**, do you accept? 🌸",
        parse_mode='Markdown',
        reply_markup=keyboard
    )


async def marry_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle marriage accept/decline inline buttons"""
    query    = update.callback_query
    await query.answer()

    responder    = query.from_user
    responder_id = str(responder.id)
    data         = query.data

    proposals = bot.data.setdefault('proposals', {})
    marriages  = bot.data.setdefault('marriages', {})

    if data.startswith("marry_accept_"):
        proposer_int_id = int(data.split("_")[2])
        prop = proposals.get(responder_id)

        if not prop:
            await query.edit_message_text("❌ No active proposal found.")
            return

        if prop["from_id"] != proposer_int_id:
            await query.answer("❌ This proposal is not for you!", show_alert=True)
            return

        proposer_id   = str(proposer_int_id)
        proposer_name = prop["from_name"]

        # Check if either is already married now
        if proposer_id in marriages:
            await query.edit_message_text(
                f"❌ {proposer_name} has already married someone else."
            )
            proposals.pop(responder_id, None)
            bot.save_data()
            return

        if responder_id in marriages:
            await query.edit_message_text(
                f"❌ {responder.first_name} is already married."
            )
            proposals.pop(responder_id, None)
            bot.save_data()
            return

        # Record marriage (bi-directional)
        marriages[proposer_id]  = proposer_int_id   # store as int same style
        marriages[responder_id] = int(responder_id)
        # Actually store each partner's ID as the other
        marriages[proposer_id]  = responder.id
        marriages[responder_id] = proposer_int_id

        proposals.pop(responder_id, None)
        bot.save_data()

        await query.edit_message_text(
            f"💖 **{proposer_name}** & **{responder.first_name}** are now married!\n\n"
            f"🎉 Congratulations! 🎊\n"
            f"💍 Marriage Bonuses:\n"
            f"  • Drop Chance +5% 🎴\n"
            f"  • XP Bonus +10% ⭐\n"
            f"  • Coins Bonus +5% on daily 💰",
            parse_mode='Markdown'
        )

        # 🎞 Marriage GIF/MP4
        try:
            await context.bot.send_animation(
                chat_id=query.message.chat_id,
                animation='https://files.catbox.moe/drtbl9.mp4',
                caption='💍 Congratulations! 💖',
            )
        except Exception as e:
            logger.error(f"Marriage animation send failed: {e}")

    elif data.startswith("marry_decline_"):
        proposer_int_id = int(data.split("_")[2])
        prop = proposals.get(responder_id)

        if prop and prop["from_id"] != proposer_int_id:
            await query.answer("❌ This proposal is not for you!", show_alert=True)
            return

        # Refund ring fee
        proposer_id = str(proposer_int_id)
        if proposer_id in bot.data.get('user_profiles', {}):
            bot.data['user_profiles'][proposer_id]['coins'] =                 bot.data['user_profiles'][proposer_id].get('coins', 0) + RING_COST

        proposals.pop(responder_id, None)
        bot.save_data()

        await query.edit_message_text(
            f"💔 **{responder.first_name}** declined the proposal.\n"
            f"💰 Ring fee refunded.",
            parse_mode='Markdown'
        )


async def divorce_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Divorce your current spouse"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    user_id   = str(update.effective_user.id)
    marriages = bot.data.setdefault('marriages', {})

    if user_id not in marriages:
        await update.message.reply_text("❌ You are not married.")
        return

    partner_id   = str(marriages[user_id])
    partner_name = get_name(partner_id) or f"User {partner_id}"

    # Remove both sides
    marriages.pop(user_id,   None)
    marriages.pop(partner_id, None)
    bot.save_data()

    await update.message.reply_text(
        f"💔 You have divorced **{partner_name}**.\n"
        f"Marriage bonuses removed.",
        parse_mode='Markdown'
    )


async def myspouse_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Check who you are married to"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    user_id   = str(update.effective_user.id)
    marriages = bot.data.setdefault('marriages', {})
    init_user_if_not_exists(user_id)

    if user_id not in marriages:
        await update.message.reply_text(
            "💔 You are not married yet.\n"
            "Reply to someone and use /marry to propose! 💍"
        )
        return

    partner_id   = str(marriages[user_id])
    partner_name = get_name(partner_id) or f"User {partner_id}"
    p_profile    = bot.data.get('user_profiles', {}).get(partner_id, {})
    p_cards      = len(bot.data.get('users', {}).get(partner_id, []))

    await update.message.reply_text(
        f"💍 **Your Spouse**\n\n"
        f"👤 Name: **{partner_name}**\n"
        f"🏆 Level: **{p_profile.get('level', 1)}**\n"
        f"🎴 Cards: **{p_cards}**\n"
        f"💰 Coins: **{p_profile.get('coins', 0):,}**\n\n"
        f"❤️ You two are happily married!",
        parse_mode='Markdown'
    )


# ==================== MYSTERY BOX SYSTEM ====================


MYSTERYBOX_REWARDS = [
    # (weight, type, label, value)
    (35, "coins",    "💰 Coin Bag",        None),   # random 300-1500
    (25, "card",     "🎴 Random Card",      None),   # random card from db
    (20, "coins",    "💎 Big Coin Bag",     None),   # random 1500-4000
    (12, "jackpot",  "🎊 JACKPOT!",         5000),
    (5,  "rare_card","⭐ Rare Card",         None),   # rarity >= 3
    (3,  "super",    "🌌 SUPER JACKPOT!",   10000),
]


def _mysterybox_weighted_choice(rewards):
    """Choose a reward based on weights (for mystery box)"""
    total   = sum(r[0] for r in rewards)
    roll    = random.randint(1, total)
    current = 0
    for r in rewards:
        current += r[0]
        if roll <= current:
            return r
    return rewards[0]


async def mysterybox_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Open a Mystery Box for 1000 coins — 1 hour cooldown"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    user    = update.effective_user
    user_id = str(user.id)
    init_user_if_not_exists(user_id)

    profile = bot.data['user_profiles'][user_id]

    # Cooldown check
    now      = time.time()
    last_use = MYSTERYBOX_COOLDOWN.get(user_id, 0)
    elapsed  = now - last_use
    if elapsed < MYSTERYBOX_COOLDOWN_SECONDS:
        remaining = int(MYSTERYBOX_COOLDOWN_SECONDS - elapsed)
        mins  = remaining // 60
        secs  = remaining % 60
        await update.message.reply_text(
            f"⏳ Mystery Box cooldown!\n"
            f"Come back in **{mins}m {secs}s** 🕐",
            parse_mode='Markdown'
        )
        return

    # Coin check
    if profile.get('coins', 0) < MYSTERYBOX_COST:
        await update.message.reply_text(
            f"❌ You need **{MYSTERYBOX_COST:,} coins** to open a Mystery Box!\n"
            f"You have: **{profile.get('coins',0):,} coins** 💰",
            parse_mode='Markdown'
        )
        return

    # Deduct cost
    profile['coins'] -= MYSTERYBOX_COST
    MYSTERYBOX_COOLDOWN[user_id] = now

    # Pick reward
    reward = _mysterybox_weighted_choice(MYSTERYBOX_REWARDS)
    w, rtype, label, fixed_val = reward

    result_msg = f"🎁 **Mystery Box**\n\n💰 Cost: {MYSTERYBOX_COST:,} coins\n\n"

    if rtype == "coins":
        amount = random.randint(300, 1500)
        profile['coins'] += amount
        result_msg += (
            f"🎉 You got: {label}\n"
            f"💰 +**{amount:,} coins**\n\n"
        )
        net = amount - MYSTERYBOX_COST
        result_msg += f"📊 Net: {'+'if net>=0 else ''}{net:,} coins"

    elif rtype == "coins" or (rtype == "coins" and fixed_val):
        amount = random.randint(1500, 4000)
        profile['coins'] += amount
        result_msg += (
            f"🎉 You got: {label}\n"
            f"💰 +**{amount:,} coins**\n\n"
        )
        net = amount - MYSTERYBOX_COST
        result_msg += f"📊 Net: {'+'if net>=0 else ''}{net:,} coins"

    elif rtype == "card":
        cards_db = bot.data.get('cards', {})
        if cards_db:
            card_id   = random.choice(list(cards_db.keys()))
            card_info = cards_db[card_id]
            bot.data['users'][user_id].append(card_id)
            rarity_key  = card_info.get('rarity', '1')
            rarity_disp = RARITIES.get(rarity_key, RARITIES['1'])['display']
            result_msg += (
                f"🎉 You got: {label}\n"
                f"🎴 **{card_info.get('name','Unknown')}**\n"
                f"⭐ {rarity_disp}\n"
                f"🆔 ID: {card_id}"
            )
        else:
            # No cards in DB → refund
            profile['coins'] += MYSTERYBOX_COST
            result_msg += "😅 No cards in database yet! Refunded."

    elif rtype == "rare_card":
        cards_db  = bot.data.get('cards', {})
        rare_pool = [cid for cid, cd in cards_db.items()
                     if int(cd.get('rarity','1')) >= 3]
        if rare_pool:
            card_id   = random.choice(rare_pool)
            card_info = cards_db[card_id]
            bot.data['users'][user_id].append(card_id)
            rarity_key  = card_info.get('rarity', '1')
            rarity_disp = RARITIES.get(rarity_key, RARITIES['1'])['display']
            result_msg += (
                f"✨ You got: {label}\n"
                f"🎴 **{card_info.get('name','Unknown')}**\n"
                f"⭐ {rarity_disp}\n"
                f"🆔 ID: {card_id}"
            )
        else:
            amount = random.randint(1000, 2500)
            profile['coins'] += amount
            result_msg += (
                f"💰 No rare cards available – consolation prize!\n"
                f"+**{amount:,} coins**"
            )

    elif rtype in ("jackpot", "super"):
        amount = fixed_val
        profile['coins'] += amount
        result_msg += (
            f"🎊🎊 **{label}** 🎊🎊\n"
            f"💰 +**{amount:,} coins**!!!\n\n"
            f"🎉 Lucky!!!"
        )

    try:
        bot.save_data()
    except Exception as e:
        logger.error(f"mysterybox save error: {e}")

    await update.message.reply_text(result_msg, parse_mode='Markdown')


# ==================== RARITY STATS (Owner/Sudo/Admin only) ====================
async def rarity_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show how many cards are uploaded per rarity (owner/sudo/admin only)"""
    user_id = update.effective_user.id
    if not (bot.is_owner(user_id) or bot.is_sudo(user_id) or bot.is_admin(user_id)):
        await update.message.reply_text("❌ ဤ command ကို Owner, Sudo, Admin များသာ အသုံးပြုနိုင်သည်။")
        return

    cards = bot.data.get('cards', {})
    total = len(cards)

    # Count cards per rarity
    rarity_counts = {}
    for card in cards.values():
        r = str(card.get('rarity', '1'))
        rarity_counts[r] = rarity_counts.get(r, 0) + 1

    lines = []
    for key in sorted(RARITIES.keys(), key=lambda x: int(x)):
        info = RARITIES[key]
        count = rarity_counts.get(key, 0)
        lines.append(f"{info['display']} ─ `{count}` cards")

    text = (
        f"🗂 *Rarity Upload Statistics*\n"
        f"━━━━━━━━━━━━━━━━━━━━\n"
        + "\n".join(lines)
        + f"\n━━━━━━━━━━━━━━━━━━━━\n"
        f"🎴 *Total Cards:* `{total}`"
    )
    await update.message.reply_text(text, parse_mode='Markdown')


# ==================== CPAY - Coin Pay / Transfer ====================
async def cpay_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/cpay <amount> — Reply to a user to transfer coins from your balance"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    sender = update.effective_user
    msg = update.message

    # Must reply to someone
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        await msg.reply_text(
            "⚠️ အသုံးပြုနည်း: `/cpay <amount>` — ငွေပေးလိုသူ၏ message ကို reply လုပ်ပြီး ရိုက်ပါ။\n"
            "ဥပမာ: `/cpay 500`",
            parse_mode='Markdown'
        )
        return

    recipient = msg.reply_to_message.from_user

    # Cannot pay yourself
    if recipient.id == sender.id:
        await msg.reply_text("❌ မိမိကိုယ်မိမိ ငွေပေး၍ မရပါ။")
        return

    # Cannot pay bots
    if recipient.is_bot:
        await msg.reply_text("❌ Bot ကို ငွေပေး၍ မရပါ။")
        return

    # Parse amount
    if not context.args or len(context.args) < 1:
        await msg.reply_text(
            "⚠️ Amount ထည့်ပေးပါ။\nဥပမာ: `/cpay 500`",
            parse_mode='Markdown'
        )
        return

    try:
        amount = int(context.args[0])
    except ValueError:
        await msg.reply_text("❌ Amount သည် ကိန်းဂဏာန်းဖြစ်ရမည်။")
        return

    if amount <= 0:
        await msg.reply_text("❌ Amount သည် 0 ထက်ကြီးရမည်။")
        return

    sender_id = str(sender.id)
    recipient_id = str(recipient.id)

    # Get/init profiles
    init_user_if_not_exists(sender_id)
    init_user_if_not_exists(recipient_id)

    sender_profile = bot.data['user_profiles'][sender_id]
    recipient_profile = bot.data['user_profiles'][recipient_id]

    if sender_profile['coins'] < amount:
        await msg.reply_text(
            f"❌ Coin မလုံလောက်ပါ။\n"
            f"💰 သင့် Balance: `{sender_profile['coins']:,}` coins\n"
            f"💸 လိုအပ်သည်: `{amount:,}` coins",
            parse_mode='Markdown'
        )
        return

    # Transfer
    sender_profile['coins'] -= amount
    recipient_profile['coins'] += amount
    recipient_profile['total_earned'] = recipient_profile.get('total_earned', 0) + amount
    bot.save_data()

    sender_name = sender.first_name or "User"
    recipient_name = recipient.first_name or "User"

    await msg.reply_text(
        f"✅ *Coin Transfer အောင်မြင်သည်!*\n"
        f"━━━━━━━━━━━━━━━━━━━━\n"
        f"💸 ပေးသူ: [{sender_name}](tg://user?id={sender.id})\n"
        f"🎁 လက်ခံသူ: [{recipient_name}](tg://user?id={recipient.id})\n"
        f"🪙 ပမာဏ: `{amount:,}` coins\n"
        f"━━━━━━━━━━━━━━━━━━━━\n"
        f"💰 သင့် Balance ကျန်: `{sender_profile['coins']:,}` coins",
        parse_mode='Markdown'
    )



