def generate_redeem_code(length=8):
    """Generate a random uppercase alphanumeric redeem code"""
    chars = string.ascii_uppercase + string.digits
    return ''.join(random.choice(chars) for _ in range(length))


async def genredeem_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/genredeem — Owner only: generate a redeem code"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if len(context.args) < 3:
        await update.message.reply_text(
            "📝 Usage:\n/genredeem card <card_id> <limit>\n"
            "/genredeem coin <amount> <limit>"
        )
        return

    reward_type = context.args[0].lower()

    if reward_type not in ("card", "coin"):
        await update.message.reply_text("❌ Type must be *card* or *coin*", parse_mode="Markdown")
        return

    try:
        value = int(context.args[1])
        limit = int(context.args[2])
    except (ValueError, IndexError):
        await update.message.reply_text("❌ Wrong format\nExample: /genredeem coin 500 5")
        return

    if value <= 0 or limit <= 0:
        await update.message.reply_text("❌ Value and limit must be greater than 0")
        return

    # Ensure redeem_codes key exists
    if 'redeem_codes' not in bot.data:
        bot.data['redeem_codes'] = {}

    code = generate_redeem_code()
    # Ensure uniqueness
    while code in bot.data['redeem_codes']:
        code = generate_redeem_code()

    bot.data['redeem_codes'][code] = {
        "type": reward_type,
        "value": value,
        "limit": limit,
        "used": 0
    }
    bot.save_data()

    await update.message.reply_text(
        f"✨ *Redeem Code Generated!*\n\n"
        f"🎁 Type: `{reward_type}`\n"
        f"📦 Value: `{value}`\n"
        f"🔢 Limit: `{limit}`\n\n"
        f"🔑 Code: `{code}`\n"
        f"📝 Usage: /redeem {code}",
        parse_mode="Markdown"
    )


async def redeem_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/redeem CODE — Redeem a code for card or coins"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    if not context.args:
        await update.message.reply_text("📝 Usage: /redeem CODE")
        return

    code = context.args[0].upper()

    # Ensure redeem_codes key exists
    if 'redeem_codes' not in bot.data:
        bot.data['redeem_codes'] = {}

    if code not in bot.data['redeem_codes']:
        await update.message.reply_text("❌ Invalid Code")
        return

    rdata = bot.data['redeem_codes'][code]

    if rdata['used'] >= rdata['limit']:
        await update.message.reply_text("❌ Code Expired / Limit Reached")
        return

    user_id = str(update.effective_user.id)
    init_user_if_not_exists(user_id)

    if rdata['type'] == "card":
        card_id = str(rdata['value'])

        if card_id not in bot.data['cards']:
            await update.message.reply_text("❌ Card not found in database")
            return

        if card_id not in bot.data['users'].get(user_id, []):
            if user_id not in bot.data['users']:
                bot.data['users'][user_id] = []
            bot.data['users'][user_id].append(card_id)

        rdata['used'] += 1
        bot.save_data()

        await update.message.reply_text(
            f"🎉 *Successfully Redeemed!*\n"
            f"🎴 Card ID: `{card_id}`",
            parse_mode="Markdown"
        )

    elif rdata['type'] == "coin":
        bot.data['user_profiles'][user_id]['coins'] += rdata['value']

        rdata['used'] += 1
        bot.save_data()

        await update.message.reply_text(
            f"🎉 *Successfully Redeemed!*\n"
            f"💰 +{rdata['value']:,} Coins",
            parse_mode="Markdown"
        )
    else:
        await update.message.reply_text("❌ Unknown reward type in code")


# ==================== GIVEAWAY SYSTEM ====================

async def broadcast_to_groups(context, message_text: str):
    """Broadcast a message to all active groups"""
    for gid in bot.data.get("active_groups", []):
        try:
            await context.bot.send_message(
                chat_id=int(gid),
                text=message_text,
                parse_mode="Markdown"
            )
        except Exception:
            continue


async def giveaway_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏆 Owner-only Giveaway System — coin or card"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only command!")
        return

    if len(context.args) < 2:
        await update.message.reply_text(
            "🎰 **Giveaway Usage:**\n\n"
            "`/giveaway coin <amount>` \u2014 Random winner gets coins\n"
            "`/giveaway card <card_id>` \u2014 Random winner gets a card\n\n"
            "📌 XP > 0 သောသူးလီာပဲသာ ပိုင် Active users များ Eligible ဖြစ်သည်",
            parse_mode="Markdown"
        )
        return

    gtype = context.args[0].lower()

    # Get eligible users (XP > 0 only)
    eligible_users = [
        uid for uid, profile in bot.data.get("user_profiles", {}).items()
        if profile.get("xp", 0) > 0
    ]

    if not eligible_users:
        await update.message.reply_text("❌ No eligible users (need XP > 0)")
        return

    import random as _random
    winner_id = _random.choice(eligible_users)
    winner_profile = bot.data["user_profiles"][winner_id]
    winner_name = USER_CACHE.get(winner_id, "User")

    # ===== COIN GIVEAWAY =====
    if gtype == "coin":
        try:
            amount = int(context.args[1])
            if amount <= 0:
                raise ValueError
        except:
            await update.message.reply_text("❌ Invalid amount")
            return

        winner_profile["coins"] = winner_profile.get("coins", 0) + amount
        bot.save_data()

        text = (
            "🎉 ─── GIVEAWAY WINNER! ───\n\n"
            f"🏆 Winner: [{winner_name}](tg://user?id={winner_id})\n"
            f"💰 Reward: **{amount:,} Coins**\n\n"
            "🔥 Stay active for more rewards!"
        )
        await update.message.reply_text(text, parse_mode="Markdown")
        await broadcast_to_groups(context, text)
        return

    # ===== CARD GIVEAWAY =====
    elif gtype == "card":
        card_id = context.args[1]

        if card_id not in bot.data.get("cards", {}):
            await update.message.reply_text("❌ Card not found")
            return

        if winner_id not in bot.data["users"]:
            bot.data["users"][winner_id] = []

        bot.data["users"][winner_id].append(card_id)

        card = bot.data["cards"][card_id]
        card["owner"] = int(winner_id)
        card["owner_name"] = winner_name

        bot.save_data()

        rarity = card.get("rarity", "1")
        rarity_info = RARITIES.get(rarity, RARITIES["1"])

        caption = (
            "🎉 ─── CARD GIVEAWAY WINNER! ───\n\n"
            f"🏆 Winner: [{winner_name}](tg://user?id={winner_id})\n\n"
            f"🎴 **{card.get('name', 'Unknown')}**\n"
            f"🎥 {card.get('movie', 'Unknown')}\n"
            f"⭐ {rarity_info['display']}\n"
        )

        if card.get("type") == "video":
            if card.get("video_type") == "video":
                await update.message.reply_video(
                    video=card["video"],
                    caption=caption,
                    parse_mode="Markdown"
                )
            else:
                await update.message.reply_document(
                    document=card["video"],
                    caption=caption,
                    parse_mode="Markdown"
                )
        else:
            await update.message.reply_photo(
                photo=card["image"],
                caption=caption,
                parse_mode="Markdown"
            )

        # Broadcast text-only to groups
        bc_text = (
            "🎉 CARD GIVEAWAY WINNER!\n\n"
            f"🏆 Winner: [{winner_name}](tg://user?id={winner_id})\n"
            f"🎴 Card: {card.get('name', '?')} | {rarity_info['display']}"
        )
        await broadcast_to_groups(context, bc_text)
        return

    else:
        await update.message.reply_text("❌ Type must be `coin` or `card`", parse_mode="Markdown")



    # ==================== OWNER EXTRA COMMANDS (NEW) ====================

async def give_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """\
    /give — Admin/Sudo/Owner give cards (reply recommended)\
\
    ✅ Random give (requested):\
      • Reply to user + /give <amount>\
        Eg: reply + /give 5  -> target user gets 5 random cards\
\
    ✅ Give specific card id (when you *need*):\
      • Reply to user + /give card <card_id>\
      • Or /give <card_id> <user_id>\
\
    Note: This bot's card DB uses numeric ids, so reply-mode digits are treated as *amount* by default.\
          Use `/give card <card_id>` to force specific-id giving in reply mode.\
    """

    uid = update.effective_user.id
    if not bot.is_owner(uid):
        await update.message.reply_text("❌ Owner only")
        return

    if not update.message or not update.message.text:
        return

    if not context.args:
        await update.message.reply_text(
            "📝 Usage:\n"
            "• Reply + `/give <amount>`  (random cards)\n"
            "• Reply + `/give card <card_id>` (specific card)\n"
            "• `/give <card_id> <user_id>` (specific card)",
            parse_mode='Markdown'
        )
        return

    args = [a.strip() for a in context.args if a.strip()]

    # ── Determine target user ──
    target_user = None
    target_id_str = None
    target_name = None

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        target_user = update.message.reply_to_message.from_user
        target_id_str = str(target_user.id)
        target_name = target_user.first_name
    elif len(args) >= 2 and args[-1].lstrip('-').isdigit():
        # direct mode (no reply) expects last arg is user_id
        target_id_str = args[-1]
        target_name = target_id_str
        args = args[:-1]
    else:
        await update.message.reply_text(
            "❌ Target user မသိ!\n\n"
            "✅ Reply to user + `/give <amount>`\n"
            "or `/give card <card_id>`\n"
            "သို့မဟုတ် `/give <card_id> <user_id>`",
            parse_mode='Markdown'
        )
        return

    # Ensure user exists in DB
    init_user_if_not_exists(target_id_str)
    bot.data['users'].setdefault(target_id_str, [])

    # ── Decide mode: random amount vs specific card ──
    mode = None
    amount = 0
    card_id = None

    # Explicit keyword mode
    if len(args) >= 2 and args[0].lower() in ("card", "id"):
        mode = 'specific'
        card_id = args[1]
    elif len(args) >= 2 and args[0].lower() in ("random", "rnd", "cards"):
        mode = 'random'
        try:
            amount = int(args[1])
        except Exception:
            amount = 0
    else:
        # Reply mode default: /give <amount>
        if target_user is not None and len(args) == 1 and args[0].isdigit():
            mode = 'random'
            amount = int(args[0])
        else:
            mode = 'specific'
            card_id = args[0]

    if mode == 'random':
        if amount <= 0:
            await update.message.reply_text("❌ Amount မှန်အောင်ရေးပါ။ ဥပမာ: reply + /give 5")
            return
        if amount > 50:
            await update.message.reply_text("❌ Maximum 50 cards per command.")
            return

        # Build random pool (all existing cards)
        pool = [cid for cid, c in bot.data.get('cards', {}).items() if c]
        if not pool:
            await update.message.reply_text("❌ Card database ထဲမှာ card မရှိသေးပါ")
            return

        given = []
        for _ in range(amount):
            cid = random.choice(pool)
            bot.data['users'][target_id_str].append(cid)
            # Update owner field to help /fav and other displays
            try:
                bot.data['cards'][cid]['owner'] = int(target_id_str) if str(target_id_str).lstrip('-').isdigit() else 0
                bot.data['cards'][cid]['owner_name'] = target_name
            except Exception:
                pass
            given.append(cid)

        bot.save_data()

        await update.message.reply_text(
            f"✅ **Random Cards Give လုပ်ပြီးပါပြီ!**\n\n"
            f"👤 To: **{target_name}** (`{target_id_str}`)\n"
            f"🎁 Amount: **{len(given)}**\n"
            f"💡 Harem ကြည့်ရန်: /harem\n"
            f"💡 Inline ကြည့်ရန်: Harem ထဲက ‘Inline View Cards’ ကိုနှိပ်ပါ။",
            parse_mode='Markdown'
        )
        return

    # mode == specific
    if not card_id:
        await update.message.reply_text("❌ Card ID မရှိပါ။ /give card <card_id> (reply) သို့မဟုတ် /give <card_id> <user_id>")
        return

    if card_id not in bot.data.get('cards', {}):
        await update.message.reply_text(f"❌ Card ID `{card_id}` မတွေ့ပါ", parse_mode='Markdown')
        return

    card = bot.data['cards'][card_id]

    bot.data['users'][target_id_str].append(card_id)
    bot.data['cards'][card_id]['owner'] = int(target_id_str) if str(target_id_str).lstrip('-').isdigit() else 0
    bot.data['cards'][card_id]['owner_name'] = target_name
    bot.save_data()

    rarity = card.get('rarity', '1')
    rarity_info = RARITIES.get(rarity, RARITIES['1'])

    await update.message.reply_text(
        f"✅ **Card Give လုပ်ပြီးပါပြီ!**\n\n"
        f"🎴 **{card.get('name', '?')}**\n"
        f"🎬 {card.get('movie', '?')}\n"
        f"🆔 ID: `{card.get('id', card_id)}`\n"
        f"⭐ {rarity_info['display']}\n"
        f"📥 Received: **{target_name}** (`{target_id_str}`)",
        parse_mode='Markdown'
    )


