async def setharemchannel_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /setharemchannel @channelusername
    Owner only. Harem command သုံးနိုင်ရန် user ၀င်ရမည့် channel သတ်မှတ်သည်။
    Channel မ set ထားလျှင် join check မလုပ်ပါ။
    """
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if not context.args:
        current = bot.settings.get('harem_channel') or 'Not set'
        await update.message.reply_text(
            f"📢 **Harem Channel Setting**\n"
            f"Current: `{current}`\n\n"
            f"Usage: `/setharemchannel @channelusername`\n"
            f"Remove: `/setharemchannel off`",
            parse_mode='Markdown'
        )
        return

    value = context.args[0].strip()

    # Allow clearing the setting
    if value.lower() in ('off', 'none', 'remove', '0'):
        bot.settings['harem_channel'] = None
        bot.save_settings()
        await update.message.reply_text("✅ Harem channel protection **disabled** (removed).")
        return

    # Ensure @-prefix
    if not value.startswith('@'):
        value = '@' + value

    bot.settings['harem_channel'] = value
    bot.save_settings()

    await update.message.reply_text(
        f"✅ **Harem Channel Set!**\n"
        f"📢 Channel: `{value}`\n"
        f"User တွေ harem မသုံးမီ ဒီ channel join ထားရမည်။",
        parse_mode='Markdown'
    )


