async def checkjoin_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /checkjoin — User မိမိ join status စစ်ဆေးနိုင်သည်။
    Owner/Admin တွေ reply ဖြင့် အခြား user စစ်နိုင်သည်။
    """
    # Determine which user to check
    if update.message.reply_to_message and bot.is_admin(update.effective_user.id):
        target = update.message.reply_to_message.from_user
    else:
        target = update.effective_user

    harem_channel = bot.settings.get('harem_channel')
    harem_group   = bot.settings.get('harem_group')

    if not harem_channel and not harem_group:
        await update.message.reply_text(
            "ℹ️ Harem join protection မ configure ရသေးပါ။\n"
            "Owner: `/setharemchannel` / `/setharemgroup` use ပါ။",
            parse_mode='Markdown'
        )
        return

    lines = [f"🔍 **Join Status Check**\n👤 {target.first_name} (`{target.id}`)\n"]

    # Check channel
    if harem_channel:
        ch_joined = await check_user_joined(context, target.id, harem_channel)
        status_ch = "✅ Joined" if ch_joined else "❌ Not joined"
        lines.append(f"📢 Channel {harem_channel}\n   {status_ch}")
    else:
        lines.append("📢 Channel: _Not configured_")

    # Check group
    if harem_group:
        gr_joined = await check_user_joined(context, target.id, harem_group)
        status_gr = "✅ Joined" if gr_joined else "❌ Not joined"
        lines.append(f"👥 Group {harem_group}\n   {status_gr}")
    else:
        lines.append("👥 Group: _Not configured_")

    # Overall result
    can_use = (
        (not harem_channel or await check_user_joined(context, target.id, harem_channel)) and
        (not harem_group   or await check_user_joined(context, target.id, harem_group))
    )
    lines.append(f"\n{'🟢 Harem command သုံးနိုင်သည်' if can_use else '🔴 Harem command သုံး၍မရသေး (Join ပြုလုပ်ပါ)'}")

    await update.message.reply_text("\n".join(lines), parse_mode='Markdown')


async def massgive_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/massgive <rarity> - Give all cards of a rarity to replied user or self"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if not context.args:
        await update.message.reply_text("📝 /massgive <rarity>")
        return

    rarity = str(context.args[0]).strip()
    if rarity not in RARITIES:
        await update.message.reply_text("❌ Invalid rarity. Use 1-16")
        return

    # Target: reply user else owner
    target_user = update.message.reply_to_message.from_user if update.message.reply_to_message else update.effective_user
    target_id = str(target_user.id)

    init_user_if_not_exists(target_id)

    pool = [cid for cid, c in bot.data.get('cards', {}).items() if str(c.get('rarity', '1')) == rarity]
    if not pool:
        await update.message.reply_text(f"❌ No cards found for rarity {RARITIES[rarity]['display']}")
        return

    # Give 1 copy of each card id (avoid duplicates explosion)
    owned = bot.data['users'].setdefault(target_id, [])
    added = 0
    for cid in pool:
        if cid not in owned:
            owned.append(cid)
            added += 1
            try:
                bot.data['cards'][cid]['owner'] = int(target_id)
                bot.data['cards'][cid]['owner_name'] = target_user.first_name
            except Exception:
                pass

    bot.save_data()

    await update.message.reply_text(
        f"✅ Mass give done!\n"
        f"👤 Target: {target_user.first_name} (`{target_id}`)\n"
        f"⭐ Rarity: {RARITIES[rarity]['display']}\n"
        f"🎴 Added: {added} / {len(pool)} cards",
        parse_mode='Markdown'
    )



async def massdc_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/massdc <percent> — Owner only. Deduct coin percent from ALL users."""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if not context.args:
        await update.message.reply_text("📝 /massdc <percent>\nဥပမာ: /massdc 20  (20% coin လျှော့)")
        return

    try:
        percent = int(context.args[0])
    except Exception:
        await update.message.reply_text("❌ Percent ကို ဂဏန်းနဲ့ရေးပါ။ ဥပမာ: /massdc 20")
        return

    if percent <= 0 or percent > 100:
        await update.message.reply_text("❌ Percent range 1 - 100")
        return

    balances = economy_data.get('balances', {})
    if not isinstance(balances, dict) or not balances:
        await update.message.reply_text("⚠️ Economy balances မရှိသေးပါ")
        return

    affected = 0
    total_deducted = 0

    for uid, bal in list(balances.items()):
        try:
            bal_int = int(bal)
        except Exception:
            continue
        if bal_int <= 0:
            continue

        new_bal = int(bal_int * (100 - percent) / 100)
        deduct = bal_int - new_bal
        if deduct <= 0:
            continue

        balances[uid] = new_bal
        affected += 1
        total_deducted += deduct

    economy_data['balances'] = balances
    save_economy()

    await update.message.reply_text(
        f"✅ MASS DEDUCT DONE\n\n"
        f"📉 Percent: {percent}%\n"
        f"👥 Affected Users: {affected}\n"
        f"🪙 Total Deducted: {total_deducted}"
    )

    # Optional log to DB channel
    db_chat = bot.settings.get('database_channel')
    if db_chat:
        try:
            await context.bot.send_message(
                chat_id=db_chat,
                text=(
                    f"{STYLE_3D['border_top']}\n"
                    f"📢 Economy Update\n"
                    f"{STYLE_3D['sep']}\n"
                    f"/massdc executed\n"
                    f"📉 Percent: {percent}%\n"
                    f"👥 Affected: {affected}\n"
                    f"🪙 Total Deducted: {total_deducted}\n"
                    f"{STYLE_3D['border_bot']}"
                )
            )
        except Exception as e:
            logger.error(f"massdc db log failed: {e}")

async def resetcardowner_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/resetcardowner <card_id> - Remove card from all users and clear owner"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if not context.args:
        await update.message.reply_text("📝 /resetcardowner <card_id>")
        return

    card_id = str(context.args[0]).strip()
    if card_id not in bot.data.get('cards', {}):
        await update.message.reply_text("❌ Card not found")
        return

    removed_total = 0
    for uid, cards in bot.data.get('users', {}).items():
        if card_id in cards:
            before = len(cards)
            bot.data['users'][uid] = [c for c in cards if c != card_id]
            removed_total += (before - len(bot.data['users'][uid]))

    bot.data['cards'][card_id]['owner'] = None
    bot.data['cards'][card_id]['owner_name'] = 'Available'
    bot.save_data()

    await update.message.reply_text(
        f"✅ Owner reset done for card `{card_id}`\n"
        f"🗑 Removed copies from users: `{removed_total}`",
        parse_mode='Markdown'
    )


