async def duplicate_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/duplicate <id> - Clone a card into new ID"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if not context.args:
        await update.message.reply_text("📝 /duplicate <id>")
        return

    src_id = str(context.args[0]).strip()
    cards = bot.data.get('cards', {})
    if src_id not in cards:
        await update.message.reply_text("❌ Card not found")
        return

    src = dict(cards[src_id])
    new_id = int(bot.data.get('next_id', 1))

    src['id'] = new_id
    src['owner'] = None
    src['owner_name'] = 'Available'

    cards[str(new_id)] = src
    bot.data['next_id'] = new_id + 1
    bot.save_data()

    await update.message.reply_text(f"✅ Duplicated `{src_id}` ➜ New card ID: `{new_id}`", parse_mode='Markdown')


