async def givecard_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/givecard <card_id> (reply) — Give a card to a user. Owner only."""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if not update.message.reply_to_message:
        await update.message.reply_text("❌ Reply to the target user\n📝 /givecard <card_id> (reply)")
        return

    if not context.args:
        await update.message.reply_text("📝 /givecard <card_id> (reply to user)")
        return

    card_id = context.args[0].strip()
    target = update.message.reply_to_message.from_user
    target_id_str = str(target.id)

    if card_id not in bot.data.get('cards', {}):
        await update.message.reply_text("❌ Card not found")
        return

    card = bot.data['cards'][card_id]
    init_user_if_not_exists(target_id_str)

    if target_id_str not in bot.data['users']:
        bot.data['users'][target_id_str] = []
    bot.data['users'][target_id_str].append(card_id)
    bot.data['cards'][card_id]['owner'] = target.id
    bot.data['cards'][card_id]['owner_name'] = target.first_name
    bot.save_data()

    rarity = card.get('rarity', '1')
    rarity_info = RARITIES.get(rarity, RARITIES['1'])

    await update.message.reply_text(
        f"✅ Card Given!\n\n"
        f"🎴 {card.get('name', '?')}\n"
        f"🎬 {card.get('movie', '?')}\n"
        f"🆔 ID: {card.get('id', card_id)}\n"
        f"⭐ {rarity_info['display']}\n"
        f"📥 To: {target.first_name} (`{target_id_str}`)",
        parse_mode='Markdown'
    )


async def removecard_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/removecard <card_id> [user_id] (reply) — Remove a card from user. Owner only."""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if not context.args:
        await update.message.reply_text(
            "📝 /removecard <card_id> (reply to user)\n"
            "or /removecard <card_id> <user_id>"
        )
        return

    card_id = context.args[0].strip()

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        target_user = update.message.reply_to_message.from_user
        target_id_str = str(target_user.id)
        target_name = target_user.first_name
    elif len(context.args) >= 2:
        target_id_str = context.args[1].strip()
        target_name = f"User {target_id_str}"
    else:
        await update.message.reply_text(
            "❌ Reply to a user or provide user_id:\n"
            "/removecard <card_id> <user_id>"
        )
        return

    if card_id not in bot.data.get('cards', {}):
        await update.message.reply_text("❌ Card not found")
        return

    user_cards = bot.data.get('users', {}).get(target_id_str, [])
    if card_id not in user_cards:
        await update.message.reply_text(
            f"❌ {target_name} doesn't own card `{card_id}`",
            parse_mode='Markdown'
        )
        return

    bot.data['users'][target_id_str].remove(card_id)
    bot.save_data()

    card = bot.data['cards'][card_id]
    rarity = card.get('rarity', '1')
    rarity_info = RARITIES.get(rarity, RARITIES['1'])

    await update.message.reply_text(
        f"✅ Card Removed!\n\n"
        f"🎴 {card.get('name', '?')}\n"
        f"🎬 {card.get('movie', '?')}\n"
        f"🆔 ID: {card.get('id', card_id)}\n"
        f"⭐ {rarity_info['display']}\n"
        f"📤 From: {target_name} (`{target_id_str}`)",
        parse_mode='Markdown'
    )


