async def transferinv_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/transferinv <from_id> <to_id> — Transfer all cards. Owner only."""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if len(context.args) < 2:
        await update.message.reply_text(
            "📝 /transferinv <from_user_id> <to_user_id>\n\n"
            "Transfers ALL cards from one user to another.\n"
            "Source user inventory will be emptied."
        )
        return

    from_id = context.args[0].strip()
    to_id = context.args[1].strip()

    if from_id == to_id:
        await update.message.reply_text("❌ From and To cannot be the same user")
        return

    if from_id not in bot.data.get('users', {}):
        await update.message.reply_text(
            f"❌ From user `{from_id}` not found",
            parse_mode='Markdown'
        )
        return

    from_cards = list(bot.data['users'].get(from_id, []))
    card_count = len(from_cards)

    if card_count == 0:
        await update.message.reply_text(f"❌ User `{from_id}` has no cards", parse_mode='Markdown')
        return

    init_user_if_not_exists(to_id)
    if to_id not in bot.data['users']:
        bot.data['users'][to_id] = []

    bot.data['users'][to_id].extend(from_cards)
    bot.data['users'][from_id] = []
    bot.save_data()

    await update.message.reply_text(
        f"✅ Inventory Transferred!\n\n"
        f"📤 From: `{from_id}`\n"
        f"📥 To: `{to_id}`\n"
        f"🎴 Cards: {card_count}",
        parse_mode='Markdown'
    )



# ==================== USER: /set (profile media) ====================

async def set_media_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/set (reply to photo/video) — Save user profile media and show it on /balance"""
    user = update.effective_user
    user_id = str(user.id)

    if bot.is_gbanned(user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    init_user_if_not_exists(user_id)

    if not update.message.reply_to_message:
        await update.message.reply_text(
            "📝 အသုံးပြုနည်း:\n"
            "1) Photo / Video ကို Reply လုပ်ပါ\n"
            "2) /set လို့ပို့ပါ\n\n"
            "❌ Reply မလုပ်ထားပါ\n"
            "(ဖျက်ချင်ရင်: /set off)"
        )
        return

    # Clear
    if context.args and context.args[0].lower() in {'off', 'clear', 'remove'}:
        bot.data['user_profiles'][user_id]['profile_media'] = None
        bot.save_data()
        await update.message.reply_text("✅ /set media ဖျက်ပြီးပါပြီ")
        return

    r = update.message.reply_to_message

    file_id = None
    mtype = None

    if r.photo:
        file_id = r.photo[-1].file_id
        mtype = 'photo'
    elif r.video:
        file_id = r.video.file_id
        mtype = 'video'
    elif r.document and (r.document.mime_type or '').startswith('video/'):
        file_id = r.document.file_id
        mtype = 'video'

    if not file_id:
        await update.message.reply_text("❌ Photo/Video ကို reply လုပ်ပြီး /set သုံးပါ")
        return

    bot.data['user_profiles'][user_id]['profile_media'] = {
        'type': mtype,
        'file_id': file_id,
        'set_at': datetime.now().isoformat()
    }
    bot.save_data()

    await update.message.reply_text(
        f"✅ Set အောင်မြင်ပါပြီ!\n"
        f"📌 Type: {mtype}\n"
        f"💡 /balance မှာ တွဲပြပေးမယ်"
    )


