async def viewrates_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    base = bot.settings.get('rarity_rates') or dict(DEFAULT_RARITY_RATES)
    locked = bot.settings.get('locked_rarities', [])
    eff = _get_effective_rarity_rates(locked)

    lines = ["📊 **Drop Rates (Non-Animated)**\n"]
    lines.append("**Base (raw):**")
    for k in sorted([x for x in base.keys() if x != '15'], key=lambda x: int(x)):
        ri = RARITIES.get(str(k), {'display': k})
        lines.append(f"• {ri['display']}: `{float(base.get(str(k), 0.0))}%`")

    lines.append("\n**Effective (after lock/boost, normalized):**")
    if eff:
        for k, w in eff:
            ri = RARITIES.get(str(k), {'display': k})
            lines.append(f"• {ri['display']}: **{w:.2f}%**")
    else:
        lines.append("• (No droppable rarities found)")

    boost = _get_active_rarity_boost()
    if boost:
        br = str(boost.get('rarity'))
        ends = str(boost.get('ends_at'))
        lines.append("\n⚡ **Active Boost:**")
        lines.append(f"• {RARITIES.get(br, RARITIES['1'])['display']} = {boost.get('percent')}% until `{ends}`")

    await update.message.reply_text("\n".join(lines), parse_mode='Markdown')


