# ==================== OWNER: USER DIRECT CONTROL ====================

def _user_card_power(uid: str) -> int:
    cards = bot.data.get('users', {}).get(str(uid), [])
    power = 0
    for cid in cards:
        c = bot.data.get('cards', {}).get(cid)
        if not c:
            continue
        rp = int(c.get('power') or 0)
        if rp <= 0:
            rarity = str(c.get('rarity', '1'))
            rp = int(RARITIES.get(rarity, RARITIES['1'])['value'])
        power += rp
    return power


def _safe_int(v, default=0) -> int:
    try:
        return int(v)
    except Exception:
        return int(default)


def _apply_coin_cut(uid: str, percent: int) -> dict:
    """Cut user's wallet+bank coins by percent (0-100). Also cut legacy economy balance."""
    percent = max(0, min(100, int(percent)))
    init_user_if_not_exists(uid)

    prof = bot.data['user_profiles'].setdefault(uid, {})
    before_wallet = _safe_int(prof.get('coins', 0))
    before_bank   = _safe_int(prof.get('bank', 0))

    cut_wallet = (before_wallet * percent) // 100
    cut_bank   = (before_bank * percent) // 100

    prof['coins'] = max(0, before_wallet - cut_wallet)
    prof['bank']  = max(0, before_bank   - cut_bank)

    # legacy economy balances
    try:
        balances = economy_data.setdefault('balances', {})
        before_legacy = _safe_int(balances.get(uid, 0))
        cut_legacy = (before_legacy * percent) // 100
        balances[uid] = max(0, before_legacy - cut_legacy)
        save_economy()
    except Exception as e:
        logger.warning(f"apply_coin_cut legacy balance failed: {e}")

    try:
        bot.save_data()
    except Exception as e:
        logger.warning(f"apply_coin_cut save failed: {e}")

    return {
        'before_wallet': before_wallet,
        'before_bank': before_bank,
        'after_wallet': _safe_int(prof.get('coins', 0)),
        'after_bank': _safe_int(prof.get('bank', 0)),
        'percent': percent,
    }


def _wipe_user_everything(uid: str) -> dict:
    """Remove user's main data: profile, inventory, cooldowns, gold, legacy balances, marriage.
    Also reset ownership of cards in their inventory back to 0."""
    uid = str(uid)

    # Ensure exists so we can safely read inventory
    init_user_if_not_exists(uid)

    removed_cards = 0
    inv = list(bot.data.get('users', {}).get(uid, []) or [])
    for cid in inv:
        c = bot.data.get('cards', {}).get(cid)
        if isinstance(c, dict):
            # reset owner fields
            c['owner'] = 0
            c['owner_name'] = 'Unknown'
            removed_cards += 1

    # Remove main keys
    bot.data.get('users', {}).pop(uid, None)
    bot.data.get('user_profiles', {}).pop(uid, None)
    bot.data.get('last_claims', {}).pop(uid, None)

    # Clean some optional structures safely
    for key in ['dropped_cards', 'card_message_ids']:
        try:
            bot.data.get(key, {}).pop(uid, None)
        except Exception:
            pass

    # Marriage cleanup
    try:
        marriages = bot.data.setdefault('marriages', {})
        partner = marriages.pop(uid, None)
        if partner is not None:
            marriages.pop(str(partner), None)
    except Exception:
        pass

    # Gold wipe
    try:
        if uid in gold_data:
            gold_data[uid] = 0
            save_gold()
    except Exception as e:
        logger.warning(f"wipe user gold failed: {e}")

    # Legacy economy wipe
    try:
        economy_data.setdefault('balances', {}).pop(uid, None)
        save_economy()
    except Exception:
        pass

    try:
        bot.save_data()
    except Exception as e:
        logger.warning(f"wipe user save failed: {e}")

    return {
        'inventory_cards_reset': removed_cards,
    }


async def inspect_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only. Inspect target user by reply or user_id.

    Usage:
      • reply to user message + /inspect
      • /inspect <user_id>
    """
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    uid = None
    if update.message and update.message.reply_to_message and update.message.reply_to_message.from_user:
        uid = str(update.message.reply_to_message.from_user.id)
    elif context.args:
        uid = str(context.args[0]).strip()

    if not uid:
        await update.message.reply_text("📝 user ကို reply လုပ်ပြီး /inspect\n(သို့) /inspect <user_id>")
        return

    init_user_if_not_exists(uid)

    prof = bot.data['user_profiles'].get(uid, {})
    cards = bot.data.get('users', {}).get(uid, [])

    breakdown = {}
    for cid in cards:
        c = bot.data.get('cards', {}).get(cid)
        if not c:
            continue
        r = str(c.get('rarity', '1'))
        breakdown[r] = breakdown.get(r, 0) + 1

    lines = ["🔍 **Inspect User**\n"]
    lines.append(f"🆔 `{uid}`")
    lines.append(f"👤 Name(cache): **{get_name(uid)}**")
    lines.append(f"🪙 Coins: **{int(prof.get('coins', 0)):,}**")
    lines.append(f"🏦 Bank: **{int(prof.get('bank', 0)):,}**")
    lines.append(f"🪙 Legacy balance: **{int(economy_data.get('balances', {}).get(uid, 0)):,}**")
    lines.append(f"🥇 Gold: **{int(gold_data.get(uid, 0)):,}**")
    lines.append(f"🏆 Level: **{int(prof.get('level', 1))}**")
    lines.append(f"⭐ XP: **{int(prof.get('xp', 0))}**")
    lines.append(f"🍀 Luck: **{float(prof.get('luck', 0.0))}%**")
    lines.append(f"🧾 Reputation: **{int(prof.get('reputation', 0))}**")
    lines.append(f"🏷 Title: **{prof.get('title') or '-'}**")
    lines.append(f"🎴 Cards: **{len(cards)}**")
    lines.append(f"💪 Power: **{_user_card_power(uid):,}**")

    if breakdown:
        lines.append("\n**Rarity Breakdown:**")
        for rk in sorted(breakdown.keys(), key=lambda x: int(x)):
            lines.append(f"• {RARITIES.get(rk, RARITIES['1'])['display']}: {breakdown[rk]}")

    keyboard = [
        [
            InlineKeyboardButton("Dc50 (Coins -50%)", callback_data=f"ins_dc50_{uid}"),
            InlineKeyboardButton("DCA (Coins=0)",    callback_data=f"ins_dca_{uid}"),
        ],
        [
            InlineKeyboardButton("Gp (Gold=0)",      callback_data=f"ins_gp_{uid}"),
            InlineKeyboardButton("Daa (Wipe Data)",  callback_data=f"ins_daa_{uid}"),
        ]
    ]

    await update.message.reply_text(
        "\n".join(lines),
        parse_mode='Markdown',
        reply_markup=InlineKeyboardMarkup(keyboard)
    )


async def inspect_action_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return

    if not update.effective_user or not bot.is_owner(update.effective_user.id):
        try:
            await query.answer("Owner only", show_alert=True)
        except Exception:
            pass
        return

    data = query.data or ""
    m = re.match(r"^ins_(dc50|dca|gp|daa)_(\d+)$", data)
    if not m:
        await query.answer("Invalid", show_alert=True)
        return

    action, uid = m.group(1), m.group(2)

    try:
        await query.answer()
    except Exception:
        pass

    try:
        if action == 'dc50':
            res = _apply_coin_cut(uid, 50)
            msg = (
                f"✅ Dc50 done for `{uid}`\n"
                f"🪙 Wallet: {res['before_wallet']:,} → {res['after_wallet']:,}\n"
                f"🏦 Bank  : {res['before_bank']:,} → {res['after_bank']:,}"
            )
        elif action == 'dca':
            res = _apply_coin_cut(uid, 100)
            msg = (
                f"✅ DCA done for `{uid}`\n"
                f"🪙 Wallet: {res['before_wallet']:,} → {res['after_wallet']:,}\n"
                f"🏦 Bank  : {res['before_bank']:,} → {res['after_bank']:,}"
            )
        elif action == 'gp':
            _ensure_gold(uid)
            before = int(gold_data.get(uid, 0) or 0)
            gold_data[uid] = 0
            save_gold()
            msg = f"✅ Gp done for `{uid}` (Gold: {before:,} → 0)"
        else:
            res = _wipe_user_everything(uid)
            msg = (
                f"✅ Daa done for `{uid}`\n"
                f"🎴 Reset cards: {res.get('inventory_cards_reset', 0)}\n"
                f"🗑 Profile/coins/gold/legacy/marriage removed"
            )

        await query.message.reply_text(msg, parse_mode='Markdown')

    except Exception as e:
        logger.error(f"inspect_action_callback error: {e}")
        try:
            await query.message.reply_text(f"❌ Error: {e}")
        except Exception:
            pass


