async def transfercoins_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return
    if len(context.args) < 3:
        await update.message.reply_text("📝 /transfercoins <from_id> <to_id> <amount>")
        return

    from_id = str(context.args[0]).strip()
    to_id = str(context.args[1]).strip()
    try:
        amount = int(context.args[2])
    except ValueError:
        await update.message.reply_text("❌ amount ကို ဂဏန်းနဲ့ရေးပါ")
        return

    if amount <= 0:
        await update.message.reply_text("❌ amount must be > 0")
        return

    init_user_if_not_exists(from_id)
    init_user_if_not_exists(to_id)

    pf = bot.data['user_profiles'][from_id]
    pt = bot.data['user_profiles'][to_id]

    if pf.get('coins', 0) < amount:
        await update.message.reply_text("❌ From user coins not enough")
        return

    pf['coins'] -= amount
    pt['coins'] += amount
    bot.save_data()

    await update.message.reply_text(
        f"✅ Transfer done\n📤 `{from_id}` ➜ 📥 `{to_id}`\n🪙 Amount: **{amount:,}**",
        parse_mode='Markdown'
    )


