async def suspend_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return
    if len(context.args) < 2:
        await update.message.reply_text("📝 /suspend <user_id> <hours>")
        return
    uid = str(context.args[0]).strip()
    try:
        hours = float(context.args[1])
    except ValueError:
        await update.message.reply_text("❌ hours must be number")
        return
    hours = max(0.1, min(hours, 24 * 365))
    ends = (datetime.now() + timedelta(hours=hours)).isoformat()
    bot.settings.setdefault('suspended_users', {})
    bot.settings['suspended_users'][uid] = {'ends_at': ends}
    bot.save_settings()
    await update.message.reply_text(f"⛔ Suspended `{uid}` until `{ends}`", parse_mode='Markdown')


