async def forceclaim_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if update.effective_chat.type not in ['group', 'supergroup']:
        await update.message.reply_text("❌ Group မှာပဲ သုံးပါ")
        return

    if not context.args:
        await update.message.reply_text("📝 /forceclaim <user_id>")
        return

    gid = str(update.effective_chat.id)
    if gid not in bot.data.get('dropped_cards', {}):
        await update.message.reply_text("❌ Drop မရှိပါ")
        return

    uid = str(context.args[0]).strip()
    init_user_if_not_exists(uid)

    dropped = bot.data['dropped_cards'][gid]
    card_id = dropped['card_id']

    bot.data.setdefault('users', {})
    bot.data['users'].setdefault(uid, [])
    bot.data['users'][uid].append(card_id)

    try:
        bot.data['cards'][card_id]['owner'] = int(uid)
        bot.data['cards'][card_id]['owner_name'] = get_name(uid)
    except Exception:
        pass

    del bot.data['dropped_cards'][gid]
    bot.save_data()

    card = bot.data['cards'].get(card_id, {})
    r = str(card.get('rarity', '1'))
    await update.message.reply_text(
        f"✅ Force claim done!\n"
        f"👤 User: `{uid}`\n"
        f"🎴 Card: `{card_id}` ({card.get('name', '-')})\n"
        f"⭐ {RARITIES.get(r, RARITIES['1'])['display']}",
        parse_mode='Markdown'
    )


async def forcebattle_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return
    if len(context.args) < 2:
        await update.message.reply_text("📝 /forcebattle <user1_id> <user2_id>")
        return

    u1 = str(context.args[0]).strip()
    u2 = str(context.args[1]).strip()

    p1 = _user_card_power(u1)
    p2 = _user_card_power(u2)

    if p1 == p2:
        result = "🤝 Draw"
    elif p1 > p2:
        result = f"🏆 Winner: `{u1}`"
    else:
        result = f"🏆 Winner: `{u2}`"

    await update.message.reply_text(
        f"⚔️ **Forced Battle**\n\n"
        f"👤 `{u1}` Power: **{p1:,}**\n"
        f"👤 `{u2}` Power: **{p2:,}**\n\n"
        f"{result}",
        parse_mode='Markdown'
    )


