# ====================  🌋 TRAITOR EVENT – Mini Mafia Mode ====================
# Data structure stored in bot.data['traitor_event']
# {
#   'active': bool,
#   'chat_id': int,
#   'players': {str(user_id): {'name': str}},
#   'traitor_id': str,
#   'votes': {str(voter_id): str(target_id)},
#   'phase': 'join'|'vote'|'ended',
#   'join_message_id': int,
#   'started_by': int
# }

def _traitor_data() -> dict:
    """Return traitor event data, initialise if missing."""
    if 'traitor_event' not in bot.data:
        bot.data['traitor_event'] = {
            'active': False, 'chat_id': None,
            'players': {}, 'traitor_id': None,
            'votes': {}, 'phase': None,
            'join_message_id': None, 'started_by': None
        }
    return bot.data['traitor_event']


async def traitor_event_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/traitor start  ─  Owner/Admin only: open a new Traitor Event."""
    user = update.effective_user
    if not (bot.is_owner(user.id) or bot.is_admin(str(user.id))):
        await update.message.reply_text("❌ Owner / Admin သာသာသာ အသုံးပြုနိုင်အမည်။")
        return

    te = _traitor_data()
    if te['active']:
        await update.message.reply_text(
            "⚠️ Traitor Event ရှိပြုနေသည်။ ပြီးရှိပြုရီး /traitor end ပြီးနှိုးပါ။"
        )
        return

    # Reset
    bot.data['traitor_event'] = {
        'active': True,
        'chat_id': update.effective_chat.id,
        'players': {},
        'traitor_id': None,
        'votes': {},
        'phase': 'join',
        'join_message_id': None,
        'started_by': user.id
    }
    bot.save_data()

    join_btn = InlineKeyboardMarkup([
        [InlineKeyboardButton("🌋 Join Game", callback_data="traitor_join")]
    ])
    msg = await update.message.reply_text(
        "🌋 *TRAITOR EVENT — Mini Mafia Mode*\n\n"
        "👥 Players သည်ဖြစ် 5–10 သို Join ပြုနိုင်သည်။\n"
        "🟢 Join လိုသည်: Button နှပ်ပါ။\n\n"
        "⏳ Owner/Admin မှ ဆောင်ချနိုင် `/traitor begin` နှိုးပါ။"
        "\n\n👥 *Joined (0):*",
        parse_mode='Markdown',
        reply_markup=join_btn
    )
    bot.data['traitor_event']['join_message_id'] = msg.message_id
    bot.save_data()


async def traitor_join_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Inline button: join traitor event."""
    query = update.callback_query
    await query.answer()
    user = query.from_user
    user_id = str(user.id)

    te = _traitor_data()
    if not te['active'] or te['phase'] != 'join':
        await query.answer("❌ Event မရှိပါ။", show_alert=True)
        return

    if user_id in te['players']:
        await query.answer("✅ သင် Join ပြုပြီးဆွေ၊", show_alert=True)
        return

    if len(te['players']) >= 10:
        await query.answer("❌ Player ပြည်လွန်းသည် (Max 10)", show_alert=True)
        return

    te['players'][user_id] = {'name': user.first_name}
    bot.save_data()

    player_list = "\n".join(
        f"👤 {v['name']}" for v in te['players'].values()
    )
    try:
        await query.edit_message_text(
            "🌋 *TRAITOR EVENT — Mini Mafia Mode*\n\n"
            "👥 Players သည်ဖြစ် 5–10 သို Join ပြုနိုင်သည်။\n"
            "🟢 Join လိုသည်: Button နှပ်ပါ။\n\n"
            "⏳ Owner/Admin မှ ဆောင်ချနိုင် `/traitor begin` နှိုးပါ။"
            f"\n\n👥 *Joined ({len(te['players'])}):*\n{player_list}",
            parse_mode='Markdown',
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🌋 Join Game", callback_data="traitor_join")]
            ])
        )
    except Exception:
        pass


async def traitor_begin(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/traitor begin  ─  Owner/Admin only: assign traitor and open voting phase."""
    user = update.effective_user
    if not (bot.is_owner(user.id) or bot.is_admin(str(user.id))):
        await update.message.reply_text("❌ Owner / Admin သာသာသာ အသုံးပြုနိုင်အမည်။")
        return

    te = _traitor_data()
    if not te['active'] or te['phase'] != 'join':
        await update.message.reply_text("❌ Join phase မရှိပါ။")
        return

    players = te['players']
    if len(players) < 5:
        await update.message.reply_text(
            f"❌ Players မလုံလောက်ပါ။ ရှိပြုမည်: {len(players)}/5"
        )
        return

    # Assign one hidden traitor
    traitor_id = random.choice(list(players.keys()))
    te['traitor_id'] = traitor_id
    te['phase'] = 'vote'
    te['votes'] = {}
    bot.save_data()

    # DM the traitor secretly
    try:
        await context.bot.send_message(
            chat_id=int(traitor_id),
            text=(
                "🔊 **သင် Traitor ဖြစ်ပြုသည်!**\n\n"
                "🌋 အချိုး Traitor Game ဖြစ်ပြုသည်။\n"
                "⚠️ အချိုးကို Vote မချ သတ်ဆိုးကို Vote လွှတ်ပြုမလုံသေချာ။\n"
                "🏆 Traitor ကို မသိသည်ဆိုသော Owner မှ ဘွဲ့သေချာ reward ရရပါမည်။"
            ),
            parse_mode='Markdown'
        )
    except Exception:
        pass  # User might not have started the bot

    player_list = "\n".join(
        f"• {v['name']}" for v in players.values()
    )

    await update.message.reply_text(
        "🌋 **TRAITOR EVENT — Voting Phase Started!**\n\n"
        "🔎 အသမ်းသော Traitor လူး အပြာကိုကို ရှိပြုသည်။\n\n"
        f"👥 **Players ({len(players)}):**\n{player_list}\n\n"
        "📢 Vote ထတ်မည်: `/vote @username`\n"
        "⏰ **လုည်ဖုန် Vote ချိန်ပြီး: `/traitor result`**",
        parse_mode='Markdown'
    )


async def traitor_vote_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/vote @username ─ Cast a vote for who you think is the Traitor."""
    te = _traitor_data()
    if not te['active'] or te['phase'] != 'vote':
        await update.message.reply_text("❌ Vote phase မရှိပါ။")
        return

    user = update.effective_user
    voter_id = str(user.id)

    if voter_id not in te['players']:
        await update.message.reply_text("❌ သင် Game ထဲ Join ပြုပြီးမဆွေ၊")
        return

    if voter_id in te['votes']:
        await update.message.reply_text("❌ သင် ဖြစ်ပြု Vote လွှတ်ပြုပြီးဆွေ (1 ကြိမ်ချည် 1 vote သာသာ)")
        return

    if not context.args:
        await update.message.reply_text("📝 Usage: /vote @username")
        return

    # Find target by username mention
    target_username = context.args[0].lstrip('@').lower()
    target_id = None
    for pid, pdata in te['players'].items():
        pname = pdata.get('name', '').lower()
        if pname == target_username or pid == target_username:
            target_id = pid
            break
    # Also check message entities for user mention
    if not target_id and update.message.entities:
        for entity in update.message.entities:
            if entity.type == 'text_mention' and entity.user:
                tid = str(entity.user.id)
                if tid in te['players']:
                    target_id = tid
                    break

    if not target_id:
        await update.message.reply_text(
            "❌ ရှာချင်သော User မတွေ့ပါ။\n"
            "💡 Player name မှတိကျ Game ထဲ Join ပြုသော နာမကို vote ပါ။"
        )
        return

    if target_id == voter_id:
        await update.message.reply_text("❌ မိမိကိုယ်မိမိကို Vote လွှတ်ပြုမရနိုင်။")
        return

    te['votes'][voter_id] = target_id
    bot.save_data()

    target_name = te['players'][target_id]['name']
    votes_cast = len(te['votes'])
    total_players = len(te['players'])

    await update.message.reply_text(
        f"✅ Vote လွှတ်ပြုသည်။ သင် **{target_name}** ကို vote လွှတ်ပြုသည်။\n"
        f"📊 Votes: {votes_cast}/{total_players}",
        parse_mode='Markdown'
    )


async def traitor_result_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/traitor result ─ Owner/Admin: tally votes and reveal the Traitor."""
    user = update.effective_user
    if not (bot.is_owner(user.id) or bot.is_admin(str(user.id))):
        await update.message.reply_text("❌ Owner / Admin သာသာသာ အသုံးပြုနိုင်အမည်။")
        return

    te = _traitor_data()
    if not te['active'] or te['phase'] != 'vote':
        await update.message.reply_text("❌ Vote phase မရှိပါ။")
        return

    players = te['players']
    votes = te['votes']
    traitor_id = te['traitor_id']

    # Tally votes
    tally = {}
    for target in votes.values():
        tally[target] = tally.get(target, 0) + 1

    # Most voted
    if tally:
        most_voted_id = max(tally, key=lambda x: tally[x])
        most_voted_name = players.get(most_voted_id, {}).get('name', 'Unknown')
        most_votes = tally[most_voted_id]
    else:
        most_voted_id = None
        most_voted_name = 'Nobody'
        most_votes = 0

    traitor_name = players.get(traitor_id, {}).get('name', 'Unknown')

    # Build vote summary
    summary_lines = []
    for pid, pdata in players.items():
        v_count = tally.get(pid, 0)
        marker = " 🔴 ← TRAITOR" if pid == traitor_id else ""
        summary_lines.append(f"• {pdata['name']}: {v_count} vote(s){marker}")
    summary = "\n".join(summary_lines)

    if most_voted_id == traitor_id:
        outcome_header = "🎉 အလဲ Players Traitor ကိုမသိသည်ဆိုသော Players အားလုံး WIN!"
        outcome_footer = (
            "🎁 Winner Reward: Owner မှလက်ချိတ်တိုင်းကို ပေးသေချာ Reward ပါမည်။"
        )
    else:
        outcome_header = (
            f"🔴 အလဲ Traitor ({traitor_name}) လွတ်ပြောင်းသည်! Traitor WIN!"
        )
        outcome_footer = (
            f"🎁 Traitor Reward: Owner မှ {traitor_name} ကို Reward ပါမည်။"
        )

    result_text = (
        f"🌋 **TRAITOR EVENT RESULT**\n\n"
        f"👥 *Most Voted:* {most_voted_name} ({most_votes} votes)\n"
        f"🔍 *Hidden Traitor was:* **{traitor_name}** 🔴\n\n"
        f"📊 **Vote Tally:**\n{summary}\n\n"
        f"{outcome_header}\n"
        f"{outcome_footer}"
    )

    te['phase'] = 'ended'
    te['active'] = False
    bot.save_data()

    await update.message.reply_text(result_text, parse_mode='Markdown')


