async def traitor_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /traitor <subcommand>
      start   – Open join phase
      begin   – Assign traitor & open vote phase
      result  – Reveal result
      status  – Show current state
      end     – Force end/reset
    """
    if not context.args:
        await update.message.reply_text(
            "🌋 **TRAITOR EVENT** — Mini Mafia Mode\n\n"
            "Commands:\n"
            "`/traitor start` – Join phase သိုးသည်\n"
            "`/traitor begin` – Traitor ချတ်ပြန် Vote phase သိုး\n"
            "`/traitor result` – Vote သင်အသုတ်သော Traitor ထုတ်သည်\n"
            "`/traitor status` – သနေအချိုးအချိုးသည်ကို ဖော်ပြသည်\n"
            "`/vote @name` – သည်သည် Vote ထက်မည်\n"
            "`/traitor end` – Event reset ချသည် (Admin/Owner)",
            parse_mode='Markdown'
        )
        return

    sub = context.args[0].lower()
    context.args = context.args[1:]

    if sub == 'start':
        await traitor_event_start(update, context)
    elif sub == 'begin':
        await traitor_begin(update, context)
    elif sub == 'result':
        await traitor_result_cmd(update, context)
    elif sub == 'status':
        await traitor_status_cmd(update, context)
    elif sub == 'end':
        await traitor_end_cmd(update, context)
    else:
        await update.message.reply_text(
            "❌ Unknown sub-command.\n"
            "Use: start / begin / result / status / end"
        )



