async def fullrd_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    "/fullrd — Show all 15 rarities as inline buttons (Owner/Sudo only)"
    user_id = update.effective_user.id
    if not (bot.is_owner(user_id) or bot.is_sudo(user_id)):
        await update.message.reply_text("❌ ဤ command ကို Owner/Sudo များသာ အသုံးပြုနိုင်သည်။")
        return

    buttons = []
    row = []
    for key in sorted(RARITIES.keys(), key=lambda x: int(x)):
        info = RARITIES[key]
        cards_in_rd = [c for c in bot.data.get('cards', {}).values()
                       if str(c.get('rarity', '1')) == key]
        btn_text = f"{info['emoji']} {info['name']} ({len(cards_in_rd)})"
        row.append(InlineKeyboardButton(btn_text, callback_data=f"fullrd_{key}"))
        if len(row) == 3:
            buttons.append(row)
            row = []
    if row:
        buttons.append(row)

    reply_markup = InlineKeyboardMarkup(buttons)
    await update.message.reply_text(
        "📂 *Full Rarity Directory*\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        "Rarity တစ်ခုကို နှိပ်ပါ → ထို Rarity ထဲမှ Cards များကို ကြည့်ရှုနိုင်ပါသည်။",
        parse_mode="Markdown",
        reply_markup=reply_markup
    )


async def fullrd_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    "Inline button callback for /fullrd"
    query = update.callback_query
    await query.answer()

    user_id = query.from_user.id
    if not (bot.is_owner(user_id) or bot.is_sudo(user_id)):
        await query.answer("❌ Permission denied.", show_alert=True)
        return

    rarity_key = query.data.replace("fullrd_", "")
    if rarity_key not in RARITIES:
        await query.edit_message_text("❌ Unknown rarity.")
        return

    info = RARITIES[rarity_key]
    cards = {cid: c for cid, c in bot.data.get('cards', {}).items()
             if str(c.get('rarity', '1')) == rarity_key}

    if not cards:
        await query.edit_message_text(
            f"{info['emoji']} *{info['name']}* Rarity ထဲတွင် Cards မရှိသေးပါ။",
            parse_mode="Markdown"
        )
        return

    MAX_PER_MSG = 50
    card_list = sorted(cards.items(), key=lambda x: int(x[0]) if x[0].isdigit() else 0)

    lines_out = []
    for cid, card in card_list[:MAX_PER_MSG]:
        name = card.get('name', 'Unknown')
        lines_out.append(f"🆔 `{cid}` — {name}")

    total = len(card_list)
    shown = min(MAX_PER_MSG, total)
    suffix = f" (showing first {shown})" if total > MAX_PER_MSG else ""

    text = (
        f"{info['emoji']} *{info['name']}* Rarity Cards\n"
        f"━━━━━━━━━━━━━━━━━━━━\n"
        f"📊 Total: `{total}` cards{suffix}\n"
        f"━━━━━━━━━━━━━━━━━━━━\n"
        + "\n".join(lines_out)
    )

    back_btn = InlineKeyboardMarkup([
        [InlineKeyboardButton("⬅️ Back to Rarities", callback_data="fullrd_back")]
    ])

    try:
        await query.edit_message_text(text, parse_mode="Markdown", reply_markup=back_btn)
    except Exception:
        await query.edit_message_text(
            f"{info['emoji']} *{info['name']}* — `{total}` cards found. Sending list...",
            parse_mode="Markdown"
        )
        chunk_size = 30
        for i in range(0, min(total, MAX_PER_MSG), chunk_size):
            chunk = lines_out[i:i+chunk_size]
            await context.bot.send_message(
                chat_id=query.message.chat_id,
                text="\n".join(chunk),
                parse_mode="Markdown"
            )


