#  SETLOG — Set admin/sudo command log group
# ═══════════════════════════════════════════════════════════════

async def setlog_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /setlog — Set this group as the admin/sudo command log group. Owner only.
    Use inside the target group: /setlog
    OR pass chat id: /setlog -100xxxxxxxxxx
    """
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    if context.args:
        # Manual chat id provided
        try:
            group_id = int(context.args[0])
        except ValueError:
            await update.message.reply_text("❌ Invalid chat id. Use /setlog inside the group or /setlog <chat_id>")
            return
    else:
        # Use the current chat
        group_id = update.effective_chat.id

    bot.settings['log_group_id'] = group_id
    bot.save_settings()
    await update.message.reply_text(
        f"✅ **Log group set!**\n\n"
        f"📍 Group ID: `{group_id}`\n"
        f"Admin/Sudo ကော command တိုင်းကို အခုပီအဆည်ယော group ထဲပိ့ပိ့သကိုလိမည်သှာ။",
        parse_mode='Markdown'
    )


# ═══════════════════════════════════════════════════════════════
#  ADMIN / SUDO COMMAND LOGGER MIDDLEWARE
#  Runs at group=-1 (before all other handlers).
#  Intercepts every command sent by an Admin or Sudo user and
#  forwards a compact log entry to the configured log group.
# ═══════════════════════════════════════════════════════════════


async def admin_sudo_command_logger(
    update: Update, context: ContextTypes.DEFAULT_TYPE
):
    """Middleware: log privileged commands used by Owner/Admin/Sudo/Dev to the configured log group.

    ✅ Only logs *privileged* commands (owner/admin/sudo/dev tools), not normal user commands.
    ✅ Never blocks execution (always returns and lets other handlers run).
    ✅ Uses HTML parse mode to avoid Markdown parsing errors.
    """
    log_group_id = bot.settings.get('log_group_id')
    if not log_group_id:
        return  # Nothing configured — skip silently

    if not update.message or not update.message.text:
        return
    if not update.message.text.startswith('/'):
        return

    user = update.effective_user
    if not user:
        return

    uid = user.id

    # Determine role (Dev should not be mis-labeled as Admin)
    role = None
    if bot.is_owner(uid):
        role = "🔱 Owner"
    elif bot.is_sudo(uid):
        role = "👑 Sudo"
    elif bot.is_dev(uid):
        role = "🧪 Dev"
    elif bot.settings and uid in bot.settings.get('admins', []):
        role = "🔑 Admin"
    else:
        return  # Regular users — skip

    # Extract command name (/cmd@bot -> cmd)
    raw = update.message.text.strip()
    cmd_part = raw.split()[0]
    cmd_name = cmd_part[1:].split('@')[0].lower() if cmd_part.startswith('/') else ""

    # Privileged commands list
    # (From /owncm & /admcm in this bot + /setlog)
    PRIV_CMDS = {
        # logger setup
        'setlog',

        # owner/admin management
        'settings','addadmin','removeadmin','setdbchannel','setdropchannel',
        'addsudo','rmsudo','sudolist','adddev','rmdev','devlist','devs',
        'broadcast','take','stats','backup','restore','rc','restorefull','importcards','backupnow','restorebackup',

        # card management
        'upload','uploadvd','edit','editr','delete','setdrop','clonecard','deletecard','createcard',
        'hidecard','unhidecard','setcarddrop','setcooldown','setrarityrate','viewrates','resetrates','boostrarity','guaranteed',
        'inspect','forceclaim','forcebattle','forcebattle2','forcebattle3','forcebattle4','forcelevelup',
        'clearwishlist','setluck','transfercoins','wipeinv','transferinv','give','givecard','removecard',

        # moderation
        'gban','ungban','gmute','ungmute','suspend','unsuspend',

        # locks / controls
        'lockbot','unlockbot','locktrade','unlocktrade',
        'lockrd','unlockrd',

        # events
        'startevent','endevent','eventinfo','eventshop','eventbuy','eventlb','registerevent','unregisterevent','listeventcards','stopevent',
        'traitor',

        # economy owner
        'addcoin','rmcoin',

        # other destructive tools
        'rmmassc','deleteh',

        # drop controls
        'set','startdrop','stopdrop','stopdrop2','setdropchannel2'
    }

    if cmd_name not in PRIV_CMDS:
        return  # Not a privileged command; skip

    import html

    user_display = html.escape(user.full_name or user.first_name or 'User')
    user_mention = f"<a href=\"tg://user?id={uid}\">{user_display}</a>"

    chat = update.effective_chat
    chat_title = html.escape((chat.title or 'Private') if chat else 'Unknown')
    chat_id = chat.id if chat else 'Unknown'

    # Truncate to keep logs clean
    cmd_text = raw[:500]
    cmd_text_esc = html.escape(cmd_text)

    log_text = (
        "<b>📝 Command Log</b>\n\n"
        f"👤 User: {user_mention} (<code>{uid}</code>)\n"
        f"🏷 Role: <b>{html.escape(role)}</b>\n"
        f"💬 Chat: {chat_title} (<code>{chat_id}</code>)\n"
        f"🕒 Time: <code>{datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')} UTC</code>\n"
        f"📌 Command:\n<code>{cmd_text_esc}</code>"
    )

    try:
        await context.bot.send_message(
            chat_id=log_group_id,
            text=log_text,
            parse_mode='HTML',
            disable_web_page_preview=True,
        )
    except Exception as e:
        logger.warning(f"admin_sudo_command_logger: could not send log → {e}")

    return


