# Rarity power bonuses
RARITY_POWER_BONUS = {
    '1': 0, '2': 10, '3': 25, '4': 50, '5': 80,
    '6': 120, '7': 170, '8': 230, '9': 300, '10': 380,
    '11': 470, '12': 580, '13': 710, '14': 870, '15': 1000, '16': 1300,
}

PVP_ANIMATION_FRAMES = [
    "⚔️  𝗕𝗔𝗧𝗧𝗟𝗘  𝗦𝗧𝗔𝗥𝗧𝗦 …",
    "💥  𝗖𝗟𝗔𝗦𝗛𝗜𝗡𝗚  𝗙𝗢𝗥𝗖𝗘𝗦 …",
    "🔥  𝗜𝗡𝗧𝗘𝗡𝗦𝗘  𝗕𝗔𝗧𝗧𝗟𝗘 …",
    "⚡  𝗙𝗜𝗡𝗔𝗟  𝗕𝗟𝗢𝗪 !",
]


def _get_user_power(user_id_str: str) -> tuple[int, str | None]:
    """Return (total_power, best_card_id_or_None) for a user."""
    cards_owned = bot.data.get("users", {}).get(user_id_str, [])
    if not cards_owned:
        return random.randint(100, 300), None

    # Pick the highest-rarity card the user owns
    best_cid = None
    best_rarity = 0
    for cid in cards_owned:
        card = bot.data.get("cards", {}).get(cid)
        if not card:
            continue
        r = int(card.get("rarity", "1"))
        if r > best_rarity:
            best_rarity = r
            best_cid = cid

    base_power = random.randint(300, 700)
    bonus      = RARITY_POWER_BONUS.get(str(best_rarity), 0)
    return base_power + bonus, best_cid


def _reward_pvp_winner(winner_id_str: str) -> str | None:
    """Give winner a random Rare (rarity 3) card. Returns card_id or None."""
    return _give_card_by_rarity("3", winner_id_str)


async def pvp_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """⚔️ PvP Battle  /pvp @username  or reply to user"""
    if update.effective_chat.type not in ("group", "supergroup"):
        await update.message.reply_text("❌ Group မှာပဲ PvP ကစားနိုင်သည်")
        return

    challenger = update.effective_user
    ch_id_str  = str(challenger.id)
    now_ts     = time.time()

    # Cooldown check
    last_pvp = PVP_COOLDOWN.get(challenger.id, 0)
    remaining = PVP_COOLDOWN_SECONDS - (now_ts - last_pvp)
    if remaining > 0:
        await update.message.reply_text(
            f"⏳ ⚡ PvP cooldown: **{remaining:.0f}s** ကျန်တယ်\n"
            f"🕹 ၁ပွဲပြီးနောက် {PVP_COOLDOWN_SECONDS}s ခဏစောင့်ပါ",
            parse_mode="Markdown"
        )
        return

    # Resolve opponent
    opponent      = None
    op_id_str     = None

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        opponent = update.message.reply_to_message.from_user
    elif context.args:
        username_arg = context.args[0].lstrip("@")
        # Try to find in name cache
        for uid_s, name in USER_CACHE.items():
            if name.lower() == username_arg.lower():
                op_id_str = uid_s
                break
        if not op_id_str:
            await update.message.reply_text(
                "❌ User မတွေ့ပါ။ Reply လုပ်ပြီး /pvp သုံးပါ"
            )
            return
    else:
        await update.message.reply_text("📝 /pvp @username  သို့မဟုတ် Message ကို Reply လုပ်ပြီး /pvp")
        return

    if opponent:
        if opponent.is_bot:
            await update.message.reply_text("❌ Bot နှင့် PvP မကစားနိုင်ပါ")
            return
        if opponent.id == challenger.id:
            await update.message.reply_text("❌ မိမိကိုယ်နှင့် ကစားမရပါ")
            return
        op_id_str = str(opponent.id)
        update_name_cache(opponent)
        op_name = opponent.first_name
    else:
        op_name = get_name(int(op_id_str)) if op_id_str else "Opponent"
        if op_id_str and int(op_id_str) == challenger.id:
            await update.message.reply_text("❌ မိမိကိုယ်နှင့် ကစားမရပါ")
            return

    update_name_cache(challenger)

    ch_name = challenger.first_name
    ch_mention = f"[{ch_name}](tg://user?id={challenger.id})"
    op_mention = (f"[{op_name}](tg://user?id={op_id_str})"
                  if op_id_str else op_name)

    # Animate battle
    anim_msg = await update.message.reply_text(
        f"╔══════════════════════════╗\n"
        f"⚔️💥  𝗣𝘃𝗣  𝗕𝗔𝗧𝗧𝗟𝗘  𝗦𝗧𝗔𝗥𝗧𝗘𝗗 💥⚔️\n"
        f"┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"🧑 {ch_mention}  VS  {op_mention} 🧑\n"
        f"╚══════════════════════════╝",
        parse_mode="Markdown"
    )

    for frame in PVP_ANIMATION_FRAMES:
        await asyncio.sleep(1)
        try:
            await anim_msg.edit_text(
                f"╔══════════════════════════╗\n"
                f"⚔️  𝗣𝘃𝗣  𝗕𝗔𝗧𝗧𝗟𝗘 ⚔️\n"
                f"┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
                f"{frame}\n"
                f"╚══════════════════════════╝"
            )
        except Exception:
            pass

    # Calculate power
    ch_power, ch_best = _get_user_power(ch_id_str)
    op_power, op_best = _get_user_power(op_id_str) if op_id_str else (random.randint(100, 300), None)

    ch_rarity = "1"
    if ch_best:
        ch_rarity = str(bot.data.get("cards", {}).get(ch_best, {}).get("rarity", "1"))
    op_rarity = "1"
    if op_best:
        op_rarity = str(bot.data.get("cards", {}).get(op_best, {}).get("rarity", "1"))

    ch_rarity_info = RARITIES.get(ch_rarity, RARITIES["1"])
    op_rarity_info = RARITIES.get(op_rarity, RARITIES["1"])

    # Determine winner
    if ch_power >= op_power:
        winner_mention = ch_mention
        loser_mention  = op_mention
        winner_id_str  = ch_id_str
        result_emoji   = "🏆🌟"
    else:
        winner_mention = op_mention
        loser_mention  = ch_mention
        winner_id_str  = op_id_str
        result_emoji   = "🏆🌟"

    # Reward: random Rare card to winner
    reward_cid = _reward_pvp_winner(winner_id_str)
    if reward_cid:
        reward_card = bot.data["cards"].get(reward_cid)
        reward_text = (f"🎁 𝗥𝗲𝘄𝗮𝗿𝗱  : 🌋 Rare Card [{reward_card['name']}]" if reward_card
                       else "🎁 𝗥𝗲𝘄𝗮𝗿𝗱  : 🌋 Rare Card")
    else:
        reward_text = "🎁 𝗥𝗲𝘄𝗮𝗿𝗱  : 🪙 +500 Coins"
        # fallback: give coins
        if winner_id_str:
            _ensure_economy(winner_id_str)
            economy_data["balances"][winner_id_str] =                 economy_data["balances"].get(winner_id_str, 0) + 500
            save_economy()

    # ── Track PvP stats ──
    init_user_if_not_exists(ch_id_str)
    if op_id_str:
        init_user_if_not_exists(op_id_str)

    ch_prof = bot.data["user_profiles"][ch_id_str]
    ch_prof["pvp_battles"] = ch_prof.get("pvp_battles", 0) + 1
    if op_id_str:
        op_prof = bot.data["user_profiles"][op_id_str]
        op_prof["pvp_battles"] = op_prof.get("pvp_battles", 0) + 1

    if winner_id_str == ch_id_str:
        ch_prof["pvp_wins"] = ch_prof.get("pvp_wins", 0) + 1
        ch_prof["pvp_streak"] = ch_prof.get("pvp_streak", 0) + 1
        if ch_prof["pvp_streak"] > ch_prof.get("pvp_max_streak", 0):
            ch_prof["pvp_max_streak"] = ch_prof["pvp_streak"]
        if op_id_str:
            op_prof["pvp_streak"] = 0
    elif winner_id_str == op_id_str:
        if op_id_str:
            op_prof["pvp_wins"] = op_prof.get("pvp_wins", 0) + 1
            op_prof["pvp_streak"] = op_prof.get("pvp_streak", 0) + 1
            if op_prof["pvp_streak"] > op_prof.get("pvp_max_streak", 0):
                op_prof["pvp_max_streak"] = op_prof["pvp_streak"]
        ch_prof["pvp_streak"] = 0

    bot.save_data()

    # Set cooldown for challenger
    PVP_COOLDOWN[challenger.id] = now_ts

    result_msg = (
        f"╔══════════════════════════╗\n"
        f"⚔️💥  𝗣𝘃𝗣  𝗥𝗘𝗦𝗨𝗟𝗧  💥⚔️\n"
        f"┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"🧑 {ch_mention}\n"
        f"   ⚡ Power  : {ch_power}\n"
        f"   {ch_rarity_info['emoji']} Rarity : {ch_rarity_info['name']}\n"
        f"┄\n"
        f"🧑 {op_mention}\n"
        f"   ⚡ Power  : {op_power}\n"
        f"   {op_rarity_info['emoji']} Rarity : {op_rarity_info['name']}\n"
        f"┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"{result_emoji}  𝗪𝗜𝗡𝗡𝗘𝗥  :  {winner_mention}\n"
        f"{reward_text}\n"
        f"💔 𝗟𝗼𝘀𝗲𝗿   :  {loser_mention}\n"
        f"┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"⏳ Next PvP in {PVP_COOLDOWN_SECONDS}s\n"
        f"╚══════════════════════════╝"
    )

    try:
        await anim_msg.edit_text(result_msg, parse_mode="Markdown")
    except Exception:
        await update.message.reply_text(result_msg, parse_mode="Markdown")



