def _get_rarest_card_name(user_id_str: str) -> str:
    """Return rarest card name + emoji owned by user."""
    cards_owned = bot.data.get("users", {}).get(user_id_str, [])
    best_rarity = 0
    best_name   = "—"
    for cid in cards_owned:
        card = bot.data.get("cards", {}).get(cid)
        if not card:
            continue
        r = int(card.get("rarity", "1"))
        if r > best_rarity:
            best_rarity = r
            best_name = card.get("name", "—")
    if best_rarity > 0:
        rarity_info = RARITIES.get(str(best_rarity), RARITIES["1"])
        return f"{rarity_info['emoji']} {rarity_info['name']} ({best_name})"
    return "—"


def _build_mystats_text(user_id_str: str, display_name: str) -> str:
    """Build the /mystats display text."""
    init_user_if_not_exists(user_id_str)
    prof = bot.data["user_profiles"].get(user_id_str, {})

    pvp_wins    = prof.get("pvp_wins", 0)
    pvp_battles = prof.get("pvp_battles", 0)
    pvp_streak  = prof.get("pvp_streak", 0)
    card_claimed   = prof.get("card_claimed", 0)
    drop_total     = prof.get("drop_total", 0)
    drop_rare_plus = prof.get("drop_rare_plus", 0)
    daily_days     = prof.get("daily_claimed_days", 0)
    market_trades  = prof.get("market_trades", 0)
    total_earned   = prof.get("total_earned", 0)
    coins          = prof.get("coins", 0)
    bank           = prof.get("bank", 0)

    # Derived
    win_rate = round((pvp_wins / pvp_battles) * 100, 1) if pvp_battles > 0 else 0.0
    drop_luck = round((drop_rare_plus / drop_total) * 100, 1) if drop_total > 0 else 0.0
    rarest   = _get_rarest_card_name(user_id_str)
    total_cards = len(bot.data.get("users", {}).get(user_id_str, []))

    text = (
        f"╔═══════════════════════╗\n"
        f"      📊  YOUR  STATS\n"
        f"╚═══════════════════════╝\n"
        f"\n"
        f"👤  {display_name}\n"
        f"─────────────────────────\n"
        f"⚔️  PvP Win Rate   : **{win_rate}%**\n"
        f"   └ {pvp_wins}W / {pvp_battles - pvp_wins}L / {pvp_battles} Total\n"
        f"🔥  Current Streak : **{pvp_streak} Wins**\n"
        f"🎴  Total Claimed  : **{card_claimed}** cards\n"
        f"📦  Collection     : **{total_cards}** cards\n"
        f"🍀  Drop Luck      : **{drop_luck}%**\n"
        f"   └ {drop_rare_plus} Rare+ / {drop_total} Total Drops\n"
        f"💎  Rarest Card    : {rarest}\n"
        f"🎁  Daily Claimed  : **{daily_days} Days**\n"
        f"🛒  Market Trades  : **{market_trades}**\n"
        f"💰  Total Earned   : **{total_earned:,} Coins**\n"
        f"   └ Wallet: {coins:,} | Bank: {bank:,}\n"
        f"─────────────────────────\n"
        f"📈 Use buttons below for more details"
    )
    return text


def _mystats_keyboard(user_id_str: str) -> InlineKeyboardMarkup:
    """Build inline keyboard for /mystats."""
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("📈 Detailed Breakdown", callback_data=f"mstat_detail_{user_id_str}"),
        ],
        [
            InlineKeyboardButton("🏆 View Rank",       callback_data="top_0"),
            InlineKeyboardButton("📦 Collection",      callback_data=f"harem_0_{user_id_str}"),
        ],
        [
            InlineKeyboardButton("🔄 Refresh",         callback_data=f"mstat_refresh_{user_id_str}"),
        ],
    ])


async def mystats_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/mystats — Show detailed user performance statistics."""
    user       = update.effective_user
    uid_str    = str(user.id)
    init_user_if_not_exists(uid_str)
    text       = _build_mystats_text(uid_str, user.first_name)
    markup     = _mystats_keyboard(uid_str)
    await update.message.reply_text(text, parse_mode="Markdown", reply_markup=markup)


async def mystats_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle mystats inline button callbacks."""
    query   = update.callback_query
    data    = query.data          # e.g. mstat_refresh_123456  or  mstat_detail_123456
    user    = query.from_user
    uid_str = str(user.id)

    await query.answer()

    if data.startswith("mstat_refresh_"):
        target_id = data.split("_", 2)[2]
        if uid_str != target_id:
            await query.answer("❌ ကိုယ်ပိုင် stats သာ refresh လုပ်နိုင်သည်", show_alert=True)
            return
        init_user_if_not_exists(uid_str)
        text   = _build_mystats_text(uid_str, user.first_name)
        markup = _mystats_keyboard(uid_str)
        try:
            await query.edit_message_text(text, parse_mode="Markdown", reply_markup=markup)
        except Exception:
            pass

    elif data.startswith("mstat_detail_"):
        target_id = data.split("_", 2)[2]
        if uid_str != target_id:
            await query.answer("❌ ကိုယ်ပိုင် stats သာ ကြည့်နိုင်သည်", show_alert=True)
            return
        init_user_if_not_exists(uid_str)
        prof = bot.data["user_profiles"].get(uid_str, {})

        pvp_wins     = prof.get("pvp_wins", 0)
        pvp_battles  = prof.get("pvp_battles", 0)
        pvp_streak   = prof.get("pvp_streak", 0)
        pvp_max      = prof.get("pvp_max_streak", 0)
        win_rate     = round((pvp_wins / pvp_battles) * 100, 1) if pvp_battles > 0 else 0.0
        drop_total   = prof.get("drop_total", 0)
        drop_rare    = prof.get("drop_rare_plus", 0)
        drop_luck    = round((drop_rare / drop_total) * 100, 1) if drop_total > 0 else 0.0
        xp           = prof.get("xp", 0)
        level        = prof.get("level", 1)
        luck         = prof.get("luck", 0.0)
        rep          = prof.get("reputation", 0)

        detail = (
            f"╔═══════════════════════╗\n"
            f"  📊  STAT  BREAKDOWN\n"
            f"╚═══════════════════════╝\n"
            f"\n"
            f"⚔️  **PvP Win Rate**\n"
            f"  Formula : (wins / battles) × 100\n"
            f"  Wins={pvp_wins}  Battles={pvp_battles}  → **{win_rate}%**\n"
            f"  🔥 Current Streak  : {pvp_streak}\n"
            f"  🏅 Best Streak     : {pvp_max}\n"
            f"\n"
            f"🍀  **Drop Luck**\n"
            f"  Formula : (rare+ drops / total) × 100\n"
            f"  Rare+={drop_rare}  Total={drop_total}  → **{drop_luck}%**\n"
            f"\n"
            f"🎮  **Other Stats**\n"
            f"  ⭐ Level       : {level} (XP: {xp:,})\n"
            f"  🍀 Luck        : {luck}\n"
            f"  🌟 Reputation  : {rep}\n"
        )
        back_kb = InlineKeyboardMarkup([[
            InlineKeyboardButton("◀️ Back", callback_data=f"mstat_refresh_{uid_str}")
        ]])
        try:
            await query.edit_message_text(detail, parse_mode="Markdown", reply_markup=back_kb)
        except Exception:
            pass


