NOTICE_EFFECTS = {
    "fire":    ("🔥", ["🔥💫", "🔥🌟", "💥🔥", "🔥⚡", "🌋🔥"], "flame"),
    "neon":    ("🌈", ["🌈✨", "💡🌟", "⚡🌈", "🔮✨", "🌟💎"], "glowing"),
    "galaxy":  ("🌌", ["🌌✨", "⭐🌌", "💫🌠", "🌟🌌", "✨🪐"], "cosmic"),
    "shock":   ("⚡", ["⚡💥", "🌩⚡", "💥⚡", "⚡🔥", "🌩💥"], "lightning"),
    "freeze":  ("❄️", ["❄️💠", "🧊❄️", "❄️⛄", "💎❄️", "❄️🌨"], "ice"),
}

NOTICE_BORDERS = {
    "fire":   ["╔🔥═══🔥═══🔥╗", "╚🔥═══🔥═══🔥╝"],
    "neon":   ["╔✨═══✨═══✨╗", "╚✨═══✨═══✨╝"],
    "galaxy": ["╔🌌═══🌌═══🌌╗", "╚🌌═══🌌═══🌌╝"],
    "shock":  ["╔⚡═══⚡═══⚡╗", "╚⚡═══⚡═══⚡╝"],
    "freeze": ["╔❄️═══❄️═══❄️╗", "╚❄️═══❄️═══❄️╝"],
    "default":["╔══════════════════╗", "╚══════════════════╝"],
}


def _build_notice_frame(effect: str, message: str, frame_idx: int) -> str:
    """Build a single animation frame for global notice."""
    ef = NOTICE_EFFECTS.get(effect)
    borders = NOTICE_BORDERS.get(effect, NOTICE_BORDERS["default"])
    top, bot_b = borders

    if ef:
        icon = ef[0]
        frames_list = ef[1]
        spark = frames_list[frame_idx % len(frames_list)]
        style = ef[2]
    else:
        icon  = "🌍"
        spark = "✨"
        style = "3D pulse"

    pulse = "▓▒░" if frame_idx % 2 == 0 else "░▒▓"
    text = (
        f"{top}\n"
        f"  {icon}  𝗚𝗟𝗢𝗕𝗔𝗟  𝗡𝗢𝗧𝗜𝗖𝗘  {icon}\n"
        f"{spark}  {pulse}  {spark}\n"
        f"──────────────────\n"
        f"{message}\n"
        f"──────────────────\n"
        f"🎆 {style.upper()} Effect Active\n"
        f"{bot_b}"
    )
    return text


def _notice_keyboard(chat_id: int, message_id: int, effect: str) -> InlineKeyboardMarkup:
    data_prefix = f"notice_{chat_id}_{message_id}_{effect}"
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("🔁 Replay",     callback_data=f"{data_prefix}_replay"),
            InlineKeyboardButton("🔕 Mute",       callback_data=f"{data_prefix}_mute"),
        ],
        [
            InlineKeyboardButton("📌 Pin Message", callback_data=f"{data_prefix}_pin"),
            InlineKeyboardButton("❤️ React",       callback_data=f"{data_prefix}_react"),
        ],
    ])


async def global3dnotice_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/global3dnotice [effect] <message>  — Owner only 3D animated broadcast."""
    user = update.effective_user
    if user.id not in OWNERS:
        await update.message.reply_text("❌ Owner only command")
        return

    args = context.args or []
    effect  = "default"
    msg_text = ""

    EFFECT_KEYS = list(NOTICE_EFFECTS.keys())
    if args and args[0].lower() in EFFECT_KEYS:
        effect   = args[0].lower()
        msg_text = " ".join(args[1:]) if len(args) > 1 else "📢 Global Announcement!"
    else:
        msg_text = " ".join(args) if args else "📢 Global Announcement!"

    if not msg_text:
        msg_text = "📢 Global Announcement!"

    # Send 3D animated notice to current chat as preview
    sent_msg = await update.message.reply_text(
        _build_notice_frame(effect, msg_text, 0),
        parse_mode="Markdown"
    )

    # Animate 4 frames in current chat
    for i in range(1, 5):
        await asyncio.sleep(0.8)
        try:
            await sent_msg.edit_text(
                _build_notice_frame(effect, msg_text, i),
                parse_mode="Markdown"
            )
        except Exception:
            pass

    # Final frame with buttons
    final_text = _build_notice_frame(effect, msg_text, 0)
    markup = _notice_keyboard(sent_msg.chat_id, sent_msg.message_id, effect)
    try:
        await sent_msg.edit_text(final_text, parse_mode="Markdown", reply_markup=markup)
    except Exception:
        pass

    # Broadcast to all known users
    all_users = list(bot.data.get("users", {}).keys())
    success, failed = 0, 0
    broadcast_text = _build_notice_frame(effect, msg_text, 0)

    for uid_s in all_users:
        try:
            uid_int = int(uid_s)
            if uid_int == user.id:
                continue
            await context.bot.send_message(
                chat_id=uid_int,
                text=broadcast_text,
                parse_mode="Markdown",
                reply_markup=_notice_keyboard(uid_int, 0, effect)
            )
            success += 1
            await asyncio.sleep(0.05)   # rate-limit safe
        except Exception:
            failed += 1

    await update.message.reply_text(
        f"✅ Global Notice Sent!\n"
        f"📨 Success: {success} | ❌ Failed: {failed}"
    )


async def global3dnotice_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle inline button callbacks for global notice."""
    query    = update.callback_query
    data     = query.data
    user     = query.from_user

    # data format: notice_{chat_id}_{msg_id}_{effect}_{action}
    parts = data.split("_", 5)   # notice, chat_id, msg_id, effect, action
    if len(parts) < 5:
        await query.answer()
        return

    _, chat_id_s, msg_id_s, effect, action = parts[0], parts[1], parts[2], parts[3], parts[4]

    if action == "mute":
        uid_str = str(user.id)
        init_user_if_not_exists(uid_str)
        bot.data["user_profiles"][uid_str]["muted_notices"] = True
        bot.save_data()
        await query.answer("🔕 Notices muted.", show_alert=True)

    elif action == "react":
        await query.answer("❤️ Reacted!", show_alert=True)

    elif action == "pin":
        if user.id not in OWNERS:
            await query.answer("❌ Owner only.", show_alert=True)
            return
        try:
            await context.bot.pin_chat_message(
                chat_id=query.message.chat_id,
                message_id=query.message.message_id,
                disable_notification=True
            )
            await query.answer("📌 Message pinned!", show_alert=True)
        except Exception as e:
            await query.answer(f"❌ Pin failed: {e}", show_alert=True)

    elif action == "replay":
        # Re-animate the message
        msg_text_lines = query.message.text.split("\n")
        # Extract original content between dashes
        try:
            inner_lines = []
            dashes_found = 0
            for line in msg_text_lines:
                if "──────" in line:
                    dashes_found += 1
                    continue
                if dashes_found == 1:
                    inner_lines.append(line)
                elif dashes_found >= 2:
                    break
            msg_content = "\n".join(inner_lines).strip() or "📢 Global Announcement!"
        except Exception:
            msg_content = "📢 Global Announcement!"

        await query.answer("🔁 Replaying...")
        for i in range(4):
            await asyncio.sleep(0.8)
            try:
                await query.edit_message_text(
                    _build_notice_frame(effect, msg_content, i),
                    parse_mode="Markdown"
                )
            except Exception:
                pass
        markup = _notice_keyboard(query.message.chat_id, query.message.message_id, effect)
        try:
            await query.edit_message_text(
                _build_notice_frame(effect, msg_content, 0),
                parse_mode="Markdown",
                reply_markup=markup
            )
        except Exception:
            pass
    else:
        await query.answer()



async def _check_harem_join(update, context, cmd_name: str) -> bool:
    """Return True if user has joined both harem channel and group (if set).
    If not, send a message with join buttons and return False."""
    user = update.effective_user
    harem_channel = bot.settings.get('harem_channel')
    harem_group   = bot.settings.get('harem_group')
    not_joined = []
    if harem_channel:
        if not await check_user_joined(context, user.id, harem_channel):
            not_joined.append((f"📢 Channel: {harem_channel}", harem_channel))
    if harem_group:
        if not await check_user_joined(context, user.id, harem_group):
            not_joined.append((f"👥 Group: {harem_group}", harem_group))
    if not_joined:
        buttons = []
        for label_url, handle in not_joined:
            is_ch = "Channel" in label_url
            btn_label = "📢 Channel Join" if is_ch else "👥 Group Join"
            buttons.append([InlineKeyboardButton(btn_label, url=f"https://t.me/{handle.lstrip('@')}")])
        join_text = "\n".join(l for l, _ in not_joined)
        await update.message.reply_text(
            f"🔒 **{cmd_name} ကစားရန် မရနိုင်ပါ!**\n\n"
            f"ကစားရန် အောက်ပါ channel/group နှစ်ခုလုံးတွင် Join ဖြစ်ရပါမည်:\n\n"
            f"{join_text}\n\n"
            f"Join ပြီးမှ /{cmd_name.lower().replace(' ','')} ထပ်ကြိုးစားပါ။",
            parse_mode='Markdown',
            reply_markup=InlineKeyboardMarkup(buttons) if buttons else None
        )
        return False
    return True


