# 💸  SELL CARD  —  /sell <card_id>
# ═══════════════════════════════════════════════════════════════

# Sell price map: 70% of SHOP_PRICES
SELL_PRICE_TABLE = {k: int(v["price"] * 0.70) for k, v in SHOP_PRICES.items()}

# For rarities 1–2 (Common/Uncommon) not in shop, use rarity value * 70
def _get_sell_price(rarity_key: str) -> int:
    if rarity_key in SELL_PRICE_TABLE:
        return SELL_PRICE_TABLE[rarity_key]
    r_val = RARITIES.get(rarity_key, RARITIES["1"])["value"]
    return int(r_val * 70)


async def sell_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/sell <card_id> — မိမိပိုင် photo/video card ကိုရောင်းပြီး 70% ပြန်ရမည်"""
    user = update.effective_user
    user_id = str(user.id)

    if bot.is_gbanned(user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    if not context.args:
        await update.message.reply_text(
            "📝 **Usage:** `/sell <card_id>`\n\n"
            "ဥပမာ: `/sell 100`\n"
            "💡 မိမိပိုင် card ID ကိုသာ ရောင်းနိုင်သည်\n"
            "💰 ရောင်းငွေ = Shop Price ၏ **70%** သာ ရမည်",
            parse_mode="Markdown"
        )
        return

    card_id = context.args[0].strip()

    init_user_if_not_exists(user_id)
    user_cards = bot.data["users"].get(user_id, [])

    # Check ownership
    if card_id not in user_cards:
        await update.message.reply_text(
            f"❌ Card ID `{card_id}` သည် သင့်ပိုင်မဟုတ်ပါ သို့မဟုတ် မတည်ရှိပါ။",
            parse_mode="Markdown"
        )
        return

    cards_db = bot.data.get("cards", {})
    if card_id not in cards_db:
        await update.message.reply_text(
            f"❌ Card ID `{card_id}` database ထဲမတွေ့ပါ။",
            parse_mode="Markdown"
        )
        return

    card = cards_db[card_id]
    rarity_key = str(card.get("rarity", "1"))
    rarity_info = RARITIES.get(rarity_key, RARITIES["1"])
    sell_price = _get_sell_price(rarity_key)

    # Remove card from user inventory (first occurrence only)
    new_cards = list(user_cards)
    new_cards.remove(card_id)
    bot.data["users"][user_id] = new_cards

    # Add coins
    profile = bot.data["user_profiles"][user_id]
    profile["coins"] = int(profile.get("coins", 0)) + sell_price
    profile["total_earned"] = int(profile.get("total_earned", 0)) + sell_price

    # Reset card owner (back to no owner)
    try:
        bot.data["cards"][card_id]["owner"] = 0
        bot.data["cards"][card_id]["owner_name"] = "Unknown"
    except Exception:
        pass

    try:
        bot.save_data()
    except Exception as e:
        logger.error(f"sell_cmd save error: {e}")

    shop_price_display = SELL_PRICE_TABLE.get(rarity_key, None)
    base_display = (int(shop_price_display / 0.70) if shop_price_display
                    else _get_sell_price(rarity_key))

    await update.message.reply_text(
        f"💸 **Card ရောင်းချပြီးပါပြီ!**\n\n"
        f"🎴 **{card.get('name', 'Unknown')}**\n"
        f"🎬 {card.get('movie', 'Unknown')}\n"
        f"🆔 ID: `{card.get('id', card_id)}`\n"
        f"⭐ {rarity_info['display']}\n\n"
        f"💰 ရရှိသောငွေ: **{sell_price:,} coins** (70%)\n"
        f"📊 ဘဏ်ကျန်: **{profile['coins']:,} coins**",
        parse_mode="Markdown"
    )


