# 🏆  GOLD LEADERBOARD  —  /gstop
# ═══════════════════════════════════════════════════════════════

async def gstop_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/gstop — Gold Top 10 leaderboard with name mentions (max 10 users)"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    if not gold_data:
        await update.message.reply_text("🪙 မည်သောသူမျှ Gold မရှိသေးပါ။")
        return

    # Sort by gold descending, take top 10
    sorted_gold = sorted(gold_data.items(), key=lambda x: int(x[1]), reverse=True)[:10]

    rank_emojis = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]

    lines = []
    for i, (uid_str, gold_val) in enumerate(sorted_gold):
        gold_val = int(gold_val)
        if gold_val <= 0:
            continue
        # Get name from cache → fallback to "User"
        name = USER_CACHE.get(uid_str, None)
        if not name:
            # Try to get owner_name from card data
            for card in bot.data.get('cards', {}).values():
                if str(card.get('owner_id', '')) == uid_str:
                    name = card.get('owner_name', None)
                    if name:
                        break
        if not name:
            name = f"User{uid_str[-4:]}"

        mention = f"[{name}](tg://user?id={uid_str})"
        rank_emoji = rank_emojis[i] if i < len(rank_emojis) else f"{i+1}."
        lines.append(f"{rank_emoji} {mention} — 🪙 {gold_val:,}")

    if not lines:
        await update.message.reply_text("🪙 မည်သောသူမျှ Gold မရှိသေးပါ။")
        return

    text = (
        "🔷═══════ 𝗚𝗢𝗟𝗗 𝗟𝗘𝗔𝗗𝗘𝗥𝗕𝗢𝗔𝗥𝗗 ═══════🔷\n"
        "🏆 𝗧𝗢𝗣 𝟭𝟬 𝗚𝗢𝗟𝗗 𝗛𝗢𝗟𝗗𝗘𝗥𝗦 🏆\n"
        "═══════════════════════════════\n"
        + "\n".join(lines) +
        "\n═══════════════════════════════\n"
        "🔷════════════════════════════🔷"
    )
    await update.message.reply_text(text, parse_mode="Markdown", disable_web_page_preview=True)


