# 🔵  BLUE ARENA  +  🪙 GOLD SYSTEM
# ═══════════════════════════════════════════════════════════════

def _get_blue_gold(user_id_str: str) -> int:
    """Get user gold balance"""
    _ensure_gold(user_id_str)
    return int(gold_data.get(user_id_str, 0))

def _add_blue_gold(user_id_str: str, amount: int):
    """Add gold to user (can be negative to subtract)"""
    _ensure_gold(user_id_str)
    gold_data[user_id_str] = max(0, int(gold_data.get(user_id_str, 0)) + amount)
    save_gold()


def _blue_neon_caption(result: str, gold_change: int, balance: int) -> str:
    """Build the Blue Neon Frame caption"""
    if result == 'win':
        status_line = "🏆 𝗬𝗢𝗨 𝗪𝗜𝗡"
        gold_line   = f"🪙 +{gold_change:,} 𝗚𝗢𝗟𝗗"
    else:
        status_line = "💔 𝗬𝗢𝗨 𝗟𝗢𝗦𝗧"
        gold_line   = f"💔 -{gold_change:,} 𝗚𝗢𝗟𝗗"

    caption = (
        "🔷═══════ 𝗕𝗟𝗨𝗘 𝗔𝗥𝗘𝗡𝗔 ═══════🔷\n"
        "⚡ 𝗡𝗘𝗢𝗡 𝗠𝗢𝗗𝗘 ⚡\n"
        "═══════════════════════\n"
        f"{status_line}\n"
        f"{gold_line}\n"
        f"💰 𝗕𝗔𝗟𝗔𝗡𝗖𝗘: {balance:,}\n"
        "🔷════════════════════🔷"
    )
    return caption


async def blue_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/blue [amount]  —  Blue Arena spin.  Min bet: 200 Gold.  Win → +amount, Lose → -amount."""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    user   = update.effective_user
    uid    = str(user.id)
    init_user_if_not_exists(uid)

    # ── Channel / Group Join Check ──
    if not await _check_harem_join(update, context, "Blue"):
        return

    # ── Parse bet amount ──
    BLUE_MIN_BET = 200
    bet_amount = BLUE_MIN_BET  # default
    if context.args:
        try:
            bet_amount = int(context.args[0])
        except (ValueError, TypeError):
            await update.message.reply_text(
                "❌ ပမာဏ မှားနေသည်!\n"                f"📝 သုံးနည်း: `/blue {BLUE_MIN_BET}` (Gold ပမာဏ ထည့်ပါ)",
                parse_mode="Markdown"
            )
            return

    if bet_amount < BLUE_MIN_BET:
        await update.message.reply_text(
            f"❌ အနည်းဆုံး **{BLUE_MIN_BET:,} Gold** ထည့်မှ ကစားနိုင်သည်!\n"            f"📝 သုံးနည်း: `/blue {BLUE_MIN_BET}`",
            parse_mode="Markdown"
        )
        return

    # ── Check balance before cooldown ──
    gold_balance = _get_blue_gold(uid)
    if gold_balance < bet_amount:
        await update.message.reply_text(
            f"❌ Gold မလုံလောက်ပါ!\n"            f"🪙 လက်ရှိ Gold: **{gold_balance:,}**\n"            f"🎯 လိုအပ်သော Gold: **{bet_amount:,}**",
            parse_mode="Markdown"
        )
        return

    # Cooldown
    import time as _time
    now     = _time.time()
    elapsed = now - BLUE_LAST.get(uid, 0)
    if elapsed < BLUE_COOLDOWN:
        remaining = int(BLUE_COOLDOWN - elapsed)
        await update.message.reply_text(
            f"🔵 ⏳ **{remaining}** စက္ကန့် စောင့်ပါ — Blue Arena cooldown!",
            parse_mode="Markdown"
        )
        return
    BLUE_LAST[uid] = now

    # ── Spin animation text  ──
    spin_frames = [
        "🔵 🎰  |  🟦  🟦  🟦  |",
        "⚡ 🎲  |  🔷  ❓  🔷  |",
        "💠 ✨  |  🎯  💫  🎯  |",
    ]
    spin_msg = await update.message.reply_text(
        "🔷═══════ 𝗕𝗟𝗨𝗘 𝗔𝗥𝗘𝗡𝗔 ═══════🔷\n"
        "⚡ 𝗡𝗘𝗢𝗡 𝗠𝗢𝗗𝗘 ⚡\n"
        "═══════════════════════\n"
        f"🪙 𝗚𝗢𝗟𝗗 𝗕𝗔𝗟𝗔𝗡𝗖𝗘: {gold_balance:,}\n"
        "═══════════════════════\n"
        f"{spin_frames[0]}\n"
        "🔷════════════════════🔷",
        parse_mode="Markdown"
    )
    await asyncio.sleep(0.7)
    try:
        await spin_msg.edit_text(
            "🔷═══════ 𝗕𝗟𝗨𝗘 𝗔𝗥𝗘𝗡𝗔 ═══════🔷\n"
            "⚡ 𝗡𝗘𝗢𝗡 𝗠𝗢𝗗𝗘 ⚡\n"
            "═══════════════════════\n"
            f"🪙 𝗚𝗢𝗟𝗗 𝗕𝗔𝗟𝗔𝗡𝗖𝗘: {gold_balance:,}\n"
            "═══════════════════════\n"
            f"{spin_frames[1]}\n"
            "🔷════════════════════🔷",
            parse_mode="Markdown"
        )
    except Exception:
        pass
    await asyncio.sleep(0.7)
    try:
        await spin_msg.edit_text(
            "🔷═══════ 𝗕𝗟𝗨𝗘 𝗔𝗥𝗘𝗡𝗔 ═══════🔷\n"
            "⚡ 𝗡𝗘𝗢𝗡 𝗠𝗢𝗗𝗘 ⚡\n"
            "═══════════════════════\n"
            f"🪙 𝗚𝗢𝗟𝗗 𝗕𝗔𝗟𝗔𝗡𝗖𝗘: {gold_balance:,}\n"
            "═══════════════════════\n"
            f"{spin_frames[2]}\n"
            "🔷════════════════════🔷",
            parse_mode="Markdown"
        )
    except Exception:
        pass
    await asyncio.sleep(0.8)
    try:
        await spin_msg.delete()
    except Exception:
        pass

    # ── Determine Win / Lose ──
    win_rate = float(bot.settings.get('blue_win_rate', 50))
    won      = random.random() * 100 < win_rate

    # Gold change: based on bet_amount
    gold_change = bet_amount
    if won:
        _add_blue_gold(uid, gold_change)
    else:
        _add_blue_gold(uid, -gold_change)

    new_balance = _get_blue_gold(uid)
    result_key  = 'win' if won else 'lose'
    caption     = _blue_neon_caption(result_key, gold_change, new_balance)

    # ── Send video or fallback caption ──
    video_id = bot.settings.get(f'blue_{result_key}_video')
    if video_id:
        try:
            await context.bot.send_video(
                chat_id=update.effective_chat.id,
                video=video_id,
                caption=caption
            )
            return
        except TelegramError:
            pass  # fallback to text

    # Fallback: text only
    await update.message.reply_text(caption)


async def setwin_blue_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/setwin_blue <file_id>  —  Set Blue Arena WIN video (Owner only)"""
    if not bot.is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only")
        return

    # Accept reply-to video OR direct file_id argument
    file_id = None
    if update.message.reply_to_message:
        replied = update.message.reply_to_message
        if replied.video:
            file_id = replied.video.file_id
        elif replied.animation:
            file_id = replied.animation.file_id

    if not file_id and context.args:
        file_id = context.args[0]

    if not file_id:
        await update.message.reply_text(
            "📝 Usage:\n"
            "`/setwin_blue` — Video တစ်ခုကို Reply လုပ်ပြီး ပေးပို့ပါ\n"
            "သို့မဟုတ် `/setwin_blue <file_id>`",
            parse_mode="Markdown"
        )
        return

    bot.settings['blue_win_video'] = file_id
    bot.save_settings()
    await update.message.reply_text("✅ Blue Arena **WIN** video သတ်မှတ်ပြီးပါပြီ!", parse_mode="Markdown")


