async def cvngold_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/cvngold <amount>  —  Coin ၏ 10% ကို Gold အဖြစ် ပြောင်းမည်"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    uid = str(update.effective_user.id)
    init_user_if_not_exists(uid)

    if not context.args:
        await update.message.reply_text(
            "📝 Usage: `/cvngold <coin_amount>`\n\n"
            "ဥပမာ: `/cvngold 1000`\n"
            "→ 1000 coin ၏ 10% = **100 gold** ရမည်\n\n"
            "⚠️ Coin ကနေ Gold ပြောင်းလဲမှုသည် 10% rate ဖြင့်သာ ရမည်",
            parse_mode="Markdown"
        )
        return

    try:
        coin_amount = int(context.args[0])
        if coin_amount <= 0:
            raise ValueError
    except (ValueError, IndexError):
        await update.message.reply_text("❌ ပမာဏ မှန်ကန်ရပါမည် (1 နှင့်အထက်)")
        return

    profile = bot.data['user_profiles'].get(uid)
    if not profile or profile.get('coins', 0) < coin_amount:
        current = profile.get('coins', 0) if profile else 0
        await update.message.reply_text(
            f"❌ Coins မလုံလောက်ပါ!\n"
            f"💰 လက်ရှိ Coins: {current:,}\n"
            f"🎯 လိုအပ်သော Coins: {coin_amount:,}"
        )
        return

    # 10% conversion
    gold_gain = max(1, int(coin_amount * 0.10))

    profile['coins'] -= coin_amount
    bot.save_data()
    _add_blue_gold(uid, gold_gain)

    new_gold    = _get_blue_gold(uid)
    new_coins   = profile['coins']

    await update.message.reply_text(
        "🔷═══════ 𝗖𝗢𝗡𝗩𝗘𝗥𝗧 ═══════🔷\n"
        "🔄 Coin → Gold Conversion\n"
        "═══════════════════════\n"
        f"💰 Coin သုံး:  -{coin_amount:,}\n"
        f"🪙 Gold ရ:    +{gold_gain:,}\n"
        "═══════════════════════\n"
        f"💰 Coin Balance:  {new_coins:,}\n"
        f"🪙 Gold Balance:  {new_gold:,}\n"
        "🔷════════════════════🔷"
    )


async def mygold_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/mygold  —  Gold balance ကြည့်မည်

    အသုံးပြုသူဧ /set နှင့်သိမ်းဆည်ထားသော photo/video ရှိလှျင်
    /balance ကဲ့သို့ မီထေရှိ caption နှင့်တွဲပြရမည်။
    """
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    user = update.effective_user
    uid  = str(user.id)
    init_user_if_not_exists(uid)
    _ensure_gold(uid)

    gold = _get_blue_gold(uid)

    caption = (
        "🔷═══════ 𝗚𝗢𝗟𝗗 𝗪𝗔𝗟𝗟𝗘𝗧 ═══════🔷\n"
        f"👤 {user.first_name}\n"
        "═══════════════════════\n"
        f"🪙 Gold Balance: **{gold:,}**\n"
        "═══════════════════════\n"
        "💡 /cvngold <amount>  Coin→Gold ပြောင်းမည်\n"
        "🎮 /blue  Blue Arena ကစားမည်\n"
        "💸 /gpay @user <amount>  Gold ပို့မည်\n"
        "🔷════════════════════🔷"
    )

    # /set မှသိမ်းဆည်ထားသော profile media ရှိလှျင် /balance ကဲ့သို့ ထည့်ပြရမည်
    profile = bot.data['user_profiles'].get(uid, {})
    media = profile.get('profile_media') if isinstance(profile, dict) else None
    if isinstance(media, dict) and media.get('file_id'):
        mtype = str(media.get('type') or '').lower()
        fid = media.get('file_id')
        try:
            cap = caption if len(caption) <= 1000 else (caption[:1000] + "…")
            if mtype == 'video':
                await update.message.reply_video(video=fid, caption=cap, parse_mode='Markdown')
                return
            await update.message.reply_photo(photo=fid, caption=cap, parse_mode='Markdown')
            return
        except Exception as e:
            logger.warning(f"/mygold media send failed, fallback to text: {e}")

    await update.message.reply_text(caption, parse_mode="Markdown")


async def gpay_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/gpay {reply} <amount>  —  Reply လုပ်ထားသော user ကို Gold ပို့မည်"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    sender     = update.effective_user
    sender_uid = str(sender.id)
    init_user_if_not_exists(sender_uid)

    # Determine receiver: reply-to message
    receiver        = None
    receiver_uid    = None

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        receiver     = update.message.reply_to_message.from_user
        receiver_uid = str(receiver.id)
    else:
        await update.message.reply_text(
            "📝 Usage: `/gpay` <amount> — User ၏ message ကို Reply လုပ်ပြီး ပမာဏ ထည့်ပါ\n"
            "ဥပမာ: Reply မှ → `/gpay 100`",
            parse_mode="Markdown"
        )
        return

    if receiver_uid == sender_uid:
        await update.message.reply_text("❌ ကိုယ့်ကိုယ်ကိုယ် Gold မပို့နိုင်ပါ")
        return

    if not context.args:
        await update.message.reply_text("📝 ပမာဏ ထည့်ပါ — `/gpay 100`", parse_mode="Markdown")
        return

    try:
        amount = int(context.args[0])
        if amount <= 0:
            raise ValueError
    except (ValueError, IndexError):
        await update.message.reply_text("❌ ပမာဏ မှန်ကန်ရပါမည် (1 နှင့်အထက်)")
        return

    sender_gold = _get_blue_gold(sender_uid)
    if sender_gold < amount:
        await update.message.reply_text(
            f"❌ Gold မလုံလောက်ပါ!\n"
            f"🪙 လက်ရှိ Gold: {sender_gold:,}\n"
            f"🎯 ပို့ရန် Gold: {amount:,}"
        )
        return

    init_user_if_not_exists(receiver_uid)
    _add_blue_gold(sender_uid, -amount)
    _add_blue_gold(receiver_uid,  amount)

    sender_new   = _get_blue_gold(sender_uid)
    receiver_new = _get_blue_gold(receiver_uid)
    recv_name    = receiver.first_name if receiver else "User"

    await update.message.reply_text(
        "🔷═══════ 𝗚𝗢𝗟𝗗 𝗣𝗔𝗬 ═══════🔷\n"
        "💸 Gold Transfer\n"
        "═══════════════════════\n"
        f"👤 From: {sender.first_name}\n"
        f"👤 To:   {recv_name}\n"
        f"🪙 Amount: {amount:,} Gold\n"
        "═══════════════════════\n"
        f"💰 သင်၏ Gold: {sender_new:,}\n"
        f"💰 {recv_name}၏ Gold: {receiver_new:,}\n"
        "🔷════════════════════🔷"
    )




