async def cvncoin_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/cvncoin <gold_amount>  —  Gold ၏ 95× ကို Coin အဖြစ် ပြောင်းမည်"""
    if bot.is_gbanned(update.effective_user.id):
        await update.message.reply_text("❌ You are globally banned.")
        return

    uid = str(update.effective_user.id)
    init_user_if_not_exists(uid)

    if not context.args:
        await update.message.reply_text(
            "📝 Usage: `/cvncoin <gold_amount>`\n\n"
            "ဥပမာ: `/cvncoin 100`\n"
            "→ 100 gold × 95 = **9,500 coin** ရမည်\n\n"
            "⚠️ Gold ကနေ Coin ပြောင်းလဲမှုသည် **95×** rate ဖြင့် ရမည်",
            parse_mode="Markdown"
        )
        return

    try:
        gold_amount = int(context.args[0])
        if gold_amount <= 0:
            raise ValueError
    except (ValueError, IndexError):
        await update.message.reply_text("❌ ပမာဏ မှန်ကန်ရပါမည် (1 နှင့်အထက်)")
