# 🗑 /deleteh <percent> — Remove % of a specific user's cards (Owner/Admin/Sudo)
# ═══════════════════════════════════════════════════════════════

async def deleteh_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/deleteh <percent> (reply to user) — Remove a percentage of a user's cards. Owner/Admin/Sudo only."""
    uid = update.effective_user.id
    if not (bot.is_owner(uid) or bot.is_admin(uid) or bot.is_sudo(uid)):
        await update.message.reply_text("❌ Permission denied. Owner/Admin/Sudo only.")
        return

    if not context.args or len(context.args) < 1:
        await update.message.reply_text(
            "📝 Usage: `/deleteh <percent>` (reply ထားသောသူ)\n\n"
            "ဥပမာ: `/deleteh 10` — reply ထားသောသူရဲ့ card တွေကို 10% ဖျက်မည်",
            parse_mode="Markdown"
        )
        return

    if not update.message.reply_to_message or not update.message.reply_to_message.from_user:
        await update.message.reply_text(
            "❌ ဖျက်လိုသော user ကို reply ထားပါ\n"
            "📝 /deleteh <percent> (reply to user)"
        )
        return

    try:
        percent = float(context.args[0])
        if not (1 <= percent <= 100):
            raise ValueError
    except (ValueError, IndexError):
        await update.message.reply_text("❌ Percent သည် 1–100 ကြားဖြစ်ရမည်")
        return

    target_user = update.message.reply_to_message.from_user
    target_id_str = str(target_user.id)
    target_name = target_user.first_name
    target_mention = f"[{target_name}](tg://user?id={target_user.id})"

    card_list = bot.data.get('users', {}).get(target_id_str, [])
    if not card_list:
        await update.message.reply_text(
            f"❌ {target_mention} \u1019\u101b\u1039\u101b \u1014\u100a\u1039\u1004\u1010\u103a \u1019\u103e\u1031 inventory \u1011\u1032\u1075\u1010\u103d\u1004\u1039 card \u1019\u101b\u103e\u102d\u1015\u102b",
            parse_mode="Markdown"
        )
        return

    total_before = len(card_list)
    remove_count = max(1, int(total_before * percent / 100))
    to_remove = random.sample(card_list, min(remove_count, len(card_list)))
    for card_id in to_remove:
        card_list.remove(card_id)

    bot.save_data()

    user = update.effective_user
    user_mention = f"[{user.first_name}](tg://user?id={uid})"

    await update.message.reply_text(
        "✅ **User Card Removal Done!**\n\n"
        f"👤 By: {user_mention}\n"
        f"🎯 Target: {target_mention} (`{target_id_str}`)\n"
        f"📊 Percent: **{percent}%**\n"
        f"🃏 Before: **{total_before}** cards\n"
        f"🗑 Removed: **{len(to_remove)}** cards\n"
        f"📦 Remaining: **{len(card_list)}** cards",
        parse_mode="Markdown"
    )


# ═══════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════
#  ⚔️  MISSION CENTER  +  /setrole  +  /ownplist     (additive module)
# ═══════════════════════════════════════════════════════════════════════
#  All-new additive module appended to the original bot.
#  • Does NOT modify any existing function.
#  • Adds:
#       /missions    — Mission Center (Daily / Weekly / Monthly)
#       /setrole     — Owner-only:  create a brand-new role (e.g. /setrole sex🔞)
#       /ownplist    — List owner-permitted users with @mentions
#  • Mission progress is auto-tracked by observing existing handlers
#    (claim / daily / slot / pvp etc.) via a group=-5 passive observer
#    — no existing call-site needs to change.
# ═══════════════════════════════════════════════════════════════════════

import os as _ms_os
import json as _ms_json
import time as _ms_time
import random as _ms_random
import re as _ms_re
from datetime import datetime as _ms_dt, timedelta as _ms_td

from telegram import (
    Update as _MsUpdate,
    InlineKeyboardButton as _MsBtn,
    InlineKeyboardMarkup as _MsKb,
)
from telegram.ext import (
    CommandHandler as _MsCmd,
    CallbackQueryHandler as _MsCbq,
    MessageHandler as _MsMsg,
    ContextTypes as _MsCtx,
    filters as _ms_filters,
)

# ── persistence ─────────────────────────────────────────────────────────
MISSIONS_FILE = "missions_data.json"

# Mission definitions — keep stable keys for DB compatibility
DAILY_MISSIONS = [
    ("multi_battle",  "❌ Multi Battle",    3),
    ("tictactoe",     "❌ Tic Tac Toe",     2),
    ("support_task",  "❌ Support Task",    1),
    ("alone_fight",   "❌ Alone Fight",     3),
    ("diamond_hunt",  "❌ Diamond Hunt",    3),
]
DAILY_POWER = 50

WEEKLY_MISSIONS = [
    ("pvp_win",          "❌ Win PvP",                20),
    ("collect_cards",    "❌ Collect Cards",          50),
    ("trade_cards",      "❌ Trade Cards",            10),
    ("complete_daily",   "❌ Complete Daily Missions", 7),
    ("boss_hunt",        "❌ Boss Hunt",               5),
]
WEEKLY_POWER = 100

MONTHLY_MISSIONS = [
    ("complete_weekly",      "❌ Complete Weekly Missions", 4),
    ("pvp_win_month",        "❌ Win PvP",                100),
    ("collect_legendary",    "❌ Collect Legendary Cards", 10),
    ("collect_mythic",       "❌ Collect Mythic Cards",     3),
    ("world_boss",           "❌ World Boss Kill",         10),
]
MONTHLY_POWER = 500

# Reward pools  (rarity-key ints as strings — see RARITIES dict)
REWARD_POOLS = {
    "daily":   ["3", "4", "5", "6"],            # Rare / Epic / Legendary / Mythic
    "weekly":  ["5", "6", "7"],                 # Legendary / Mythic / Divine
    "monthly": ["6", "7", "15", "16"],          # Mythic / Divine / Animated / Evens-Secret
}

REWARD_CARDS_PER_CLAIM = 10  # spec: "Random Card 10ခု ရွေးပေးရမည်"

# Reset windows
RESET_SECONDS = {
    "daily":   24 * 3600,
    "weekly":  7  * 24 * 3600,
    "monthly": 30 * 24 * 3600,
}

# ── data layer ──────────────────────────────────────────────────────────
def _ms_load():
    if _ms_os.path.exists(MISSIONS_FILE):
        try:
            with open(MISSIONS_FILE, 'r', encoding='utf-8') as f:
                return _ms_json.load(f)
        except Exception:
            pass
    return {"users": {}}

def _ms_save():
    try:
        with open(MISSIONS_FILE, 'w', encoding='utf-8') as f:
            _ms_json.dump(MISSION_DATA, f, ensure_ascii=False, indent=2)
    except Exception as e:
        try:
            logger.error(f"[missions] save failed: {e}")
        except Exception:
            pass

MISSION_DATA = _ms_load()

def _ms_now() -> float:
    return _ms_time.time()

def _ms_default_user():
    return {
        "daily":   {"progress": {}, "claimed": False, "reset_at": 0,
                    "completed_count": 0},
        "weekly":  {"progress": {}, "claimed": False, "reset_at": 0,
                    "completed_count": 0},
        "monthly": {"progress": {}, "claimed": False, "reset_at": 0},
        "started_daily":   False,
        "started_weekly":  False,
        "started_monthly": False,
    }

def _ms_user(uid: str) -> dict:
    MISSION_DATA.setdefault("users", {})
    u = MISSION_DATA["users"].get(uid)
    if not u:
        u = _ms_default_user()
        MISSION_DATA["users"][uid] = u
    # backward-compat patch
    for tier in ("daily", "weekly", "monthly"):
        u.setdefault(tier, {"progress": {}, "claimed": False, "reset_at": 0})
        u[tier].setdefault("progress", {})
        u[tier].setdefault("claimed", False)
        u[tier].setdefault("reset_at", 0)
        if tier in ("daily", "weekly"):
            u[tier].setdefault("completed_count", 0)
    for f in ("started_daily", "started_weekly", "started_monthly"):
        u.setdefault(f, False)
    return u

def _ms_missions_for(tier: str):
    return {"daily":   DAILY_MISSIONS,
            "weekly":  WEEKLY_MISSIONS,
            "monthly": MONTHLY_MISSIONS}[tier]

def _ms_power_for(tier: str) -> int:
    return {"daily": DAILY_POWER, "weekly": WEEKLY_POWER, "monthly": MONTHLY_POWER}[tier]

def _ms_check_reset(uid: str):
    """Auto-reset stale tiers."""
    u = _ms_user(uid)
    now = _ms_now()
    changed = False
    for tier, secs in RESET_SECONDS.items():
        if u[tier].get("reset_at", 0) and now >= u[tier]["reset_at"]:
            # carry "completed" counters into higher tiers BEFORE wiping
            if tier == "daily" and u[tier].get("_was_complete"):
                u["weekly"]["progress"]["complete_daily"] = \
                    int(u["weekly"]["progress"].get("complete_daily", 0)) + 1
            if tier == "weekly" and u[tier].get("_was_complete"):
                u["monthly"]["progress"]["complete_weekly"] = \
                    int(u["monthly"]["progress"].get("complete_weekly", 0)) + 1
            u[tier] = {"progress": {}, "claimed": False, "reset_at": 0}
            if tier != "monthly":
                u[tier]["completed_count"] = 0
            u[f"started_{tier}"] = False
            changed = True
    if changed:
        _ms_save()

def _ms_start_tier(uid: str, tier: str):
    u = _ms_user(uid)
    if not u.get(f"started_{tier}"):
        u[f"started_{tier}"] = True
        u[tier]["reset_at"] = _ms_now() + RESET_SECONDS[tier]
        u[tier]["claimed"] = False
        _ms_save()

def _ms_is_tier_complete(uid: str, tier: str) -> bool:
    u = _ms_user(uid)
    prog = u[tier]["progress"]
    for key, _label, target in _ms_missions_for(tier):
        if int(prog.get(key, 0)) < int(target):
            return False
    return True

def _ms_mark_completion_state(uid: str):
    """Set _was_complete flag if tier is currently fully done."""
    u = _ms_user(uid)
    for tier in ("daily", "weekly", "monthly"):
        u[tier]["_was_complete"] = _ms_is_tier_complete(uid, tier)

# ── Public progress API (used by observer hooks) ────────────────────────
def mission_progress_add(user_id, key: str, amount: int = 1):
    """Add progress to whichever tier(s) have this key."""
    if not user_id:
        return
    uid = str(user_id)
    _ms_check_reset(uid)
    u = _ms_user(uid)
    bumped = False
    for tier in ("daily", "weekly", "monthly"):
        for k, _l, target in _ms_missions_for(tier):
            if k == key and u.get(f"started_{tier}"):
                cur = int(u[tier]["progress"].get(k, 0))
                new = min(cur + int(amount), int(target))
                if new != cur:
                    u[tier]["progress"][k] = new
                    bumped = True
    if bumped:
        _ms_mark_completion_state(uid)
        _ms_save()

# ── UI helpers ──────────────────────────────────────────────────────────
def _ms_format_remaining(seconds: float) -> str:
    if seconds <= 0:
        return "Ready"
    h = int(seconds // 3600)
    m = int((seconds % 3600) // 60)
    if h >= 24:
        d = h // 24
        return f"{d}d {h % 24}h"
    return f"{h}h {m}m"

def _ms_center_text(uid: str) -> str:
    _ms_check_reset(uid)
    u = _ms_user(uid)
    now = _ms_now()

    def _tier_status(tier: str) -> str:
        if not u.get(f"started_{tier}"):
            return "⏳ Not Started"
        if _ms_is_tier_complete(uid, tier):
            if u[tier].get("claimed"):
                return "✅ Claimed"
            return "🎁 Ready to Claim"
        # count progress
        done = 0
        total = 0
        for _k, _l, target in _ms_missions_for(tier):
            cur = int(u[tier]["progress"].get(_k, 0))
            if cur >= target:
                done += 1
            total += 1
        return f"📊 {done}/{total} done"

    def _tier_reset(tier: str) -> str:
        if not u.get(f"started_{tier}"):
            return "—"
        left = float(u[tier].get("reset_at", 0)) - now
        return _ms_format_remaining(left)

    # power = sum of completed tiers
    power = 0
    for tier in ("daily", "weekly", "monthly"):
        if _ms_is_tier_complete(uid, tier):
            power += _ms_power_for(tier)

    txt = (
        "╔════════════════════╗\n"
        "  ⚔️  MISSION CENTER  ⚔️\n"
        "╚════════════════════╝\n\n"
        f"📋 Daily Missions   →  { _tier_status('daily') }   ⏰ { _tier_reset('daily') }\n"
        f"🏆 Weekly Missions  →  { _tier_status('weekly') }   ⏰ { _tier_reset('weekly') }\n"
        f"👑 Monthly Missions →  { _tier_status('monthly') }   ⏰ { _tier_reset('monthly') }\n\n"
        "━━━━━━━━━━━━━━\n"
        "🎁 Available Rewards : Random Cards x10\n"
        "📊 Mission Progress  : See tier menus\n"
        f"⚡ Player Power     : {power}\n"
        "━━━━━━━━━━━━━━\n"
        "🔥  Choose your mission below  🔥"
    )
    return txt

def _ms_center_kb() -> _MsKb:
    rows = [
        [_MsBtn("📋 Daily",   callback_data="mc|tier|daily"),
         _MsBtn("🏆 Weekly",  callback_data="mc|tier|weekly")],
        [_MsBtn("👑 Monthly", callback_data="mc|tier|monthly"),
         _MsBtn("🎁 Claim Reward", callback_data="mc|claim_menu")],
        [_MsBtn("?? Refresh", callback_data="mc|home")],
    ]
    return _MsKb(rows)

def _ms_tier_text(uid: str, tier: str) -> str:
    _ms_check_reset(uid)
    u = _ms_user(uid)
    header_map = {
        "daily":   ("📋 DAILY MISSION",    "🔥 KEEP GOING HERO! 🔥",      "🎴 Random Card",            "Rare / Epic / Legendary / Mythic"),
        "weekly":  ("🏆 WEEKLY MISSION",   "🔥 LEGENDS NEVER STOP 🔥",    "🎴 Random Premium Card",    "Legendary / Mythic / Divine"),
        "monthly": ("👑 MONTHLY MISSION",  "🌟 YOU ARE A TRUE HERO 🌟",  "🎴 Exclusive Random Card",  "Mythic / Divine / Animated / Secret Event Card"),
    }
    title, motto, reward_label, pool_label = header_map[tier]
    started = u.get(f"started_{tier}", False)
    start_line = "✅ Mission Start" if started else "▶️ Tap '✅ Mission Start' to begin"

    lines = []
    lines.append("╔════════════════════╗")
    lines.append(f"      {title}")
    lines.append("╚════════════════════╝\n")
    lines.append(start_line + "\n")

    missions = _ms_missions_for(tier)
    power_inserted = False
    for idx, (key, label, target) in enumerate(missions):
        cur = int(u[tier]["progress"].get(key, 0))
        done = cur >= target
        mark = "✅" if done else "❌"
        clean_label = label.lstrip("❌ ").lstrip("✅ ")
        lines.append(f"{mark} {clean_label} ({cur}/{target})")
        # spec puts ⚡ POWER between missions[3] and missions[4]
        if idx == len(missions) - 2 and not power_inserted:
            lines.append(f"\n⚡ POWER : {_ms_power_for(tier)}\n")
            power_inserted = True
    lines.append("\n🎁 REWARD")
    lines.append(reward_label)
    lines.append("\n━━━━━━━━━━━━━━")
    lines.append(motto)
    lines.append("\nReward Pool:")
    for r in pool_label.split(" / "):
        lines.append(f"• {r}")
    if started:
        left = float(u[tier].get("reset_at", 0)) - _ms_now()
        lines.append(f"\n⏰ Reset in: { _ms_format_remaining(left) }")
    return "\n".join(lines)

def _ms_tier_kb(uid: str, tier: str) -> _MsKb:
    u = _ms_user(uid)
    rows = []
    if not u.get(f"started_{tier}"):
        rows.append([_MsBtn("✅ Mission Start", callback_data=f"mc|start|{tier}")])
    else:
        if _ms_is_tier_complete(uid, tier) and not u[tier].get("claimed"):
            rows.append([_MsBtn("🎁 Claim Reward", callback_data=f"mc|claim|{tier}")])
        # demo / dev progress buttons removed for prod safety
    rows.append([_MsBtn("🏠 Mission Center", callback_data="mc|home")])
    return _MsKb(rows)

# ── reward delivery ─────────────────────────────────────────────────────
def _ms_random_card_id(pool_rarities: list) -> str | None:
    cards = bot.data.get("cards", {})
    candidates = [cid for cid, c in cards.items()
                  if c and str(c.get("rarity", "1")) in pool_rarities
                  and c.get("drop_enabled", True)]
    if not candidates:
        # fallback: any drop-enabled card
        candidates = [cid for cid, c in cards.items()
                      if c and c.get("drop_enabled", True)]
    if not candidates:
        return None
    return _ms_random.choice(candidates)

async def _ms_deliver_reward_cards(update_or_query, context, uid: str, tier: str):
    """Pick 10 random cards, add to inventory, send each."""
    pool = REWARD_POOLS.get(tier, ["3", "4", "5"])
    chat_id = update_or_query.message.chat_id if hasattr(update_or_query, "message") and update_or_query.message else None
    if chat_id is None and hasattr(update_or_query, "effective_chat"):
        chat_id = update_or_query.effective_chat.id

    # Inventory init
    bot.data.setdefault("users", {})
    bot.data["users"].setdefault(uid, [])

    intro = (
        "🎉 𝗠𝗜𝗦𝗦𝗜𝗢𝗡 𝗖𝗢𝗠𝗣𝗟𝗘𝗧𝗘𝗗\n\n"
        f"🎴  10 Reward Cards Obtained!\n"
        "━━━━━━━━━━━━━━"
    )
    try:
        await context.bot.send_message(chat_id=chat_id, text=intro)
    except Exception:
        pass

    delivered = 0
    for i in range(REWARD_CARDS_PER_CLAIM):
        cid = _ms_random_card_id(pool)
        if not cid:
            continue
        card = bot.data["cards"].get(cid)
        if not card:
            continue
        bot.data["users"][uid].append(cid)
        delivered += 1
        # build reward caption
        rarity_key = str(card.get("rarity", "1"))
        rarity_info = RARITIES.get(rarity_key, RARITIES.get("1", {"display": "💮 Common"}))
        cname = card.get("name", "Unknown")
        caption = (
            "🎉 𝗠𝗜𝗦𝗦𝗜𝗢𝗡 𝗥𝗘𝗪𝗔𝗥𝗗\n\n"
            "🎴 Reward Obtained!\n\n"
            f"📛 {cname}\n"
            f"⭐ {rarity_info.get('display', rarity_key)}\n"
            f"🆔 `{cid}`\n\n"
            "━━━━━━━━━━━━━━\n"
            f"🔥 KEEP COLLECTING!  ({i+1}/{REWARD_CARDS_PER_CLAIM})\n"
            "━━━━━━━━━━━━━━"
        )
        # send media
        try:
            if card.get('type') == 'video' or card.get('video'):
                vid = card.get('video') or card.get('video_url')
                if card.get('video_type') == 'video':
                    await context.bot.send_video(chat_id=chat_id, video=vid,
                                                 caption=caption, parse_mode='Markdown')
                else:
                    await context.bot.send_document(chat_id=chat_id, document=vid,
                                                    caption=caption, parse_mode='Markdown')
            else:
                img = card.get('image') or card.get('photo') or card.get('photo_url')
                if img:
                    await context.bot.send_photo(chat_id=chat_id, photo=img,
                                                 caption=caption, parse_mode='Markdown')
                else:
                    await context.bot.send_message(chat_id=chat_id, text=caption,
                                                   parse_mode='Markdown')
        except Exception as e:
            try:
                logger.warning(f"[missions] reward send failed: {e}")
            except Exception:
                pass
            try:
                await context.bot.send_message(chat_id=chat_id, text=caption,
                                               parse_mode='Markdown')
            except Exception:
                pass

    try:
        bot.save_data()
    except Exception:
        pass

    # Track collect_cards / collect_legendary / collect_mythic for higher tiers
    try:
        mission_progress_add(uid, "collect_cards", delivered)
    except Exception:
        pass

    return delivered

# ── command + callbacks ────────────────────────────────────────────────
async def missions_cmd(update: _MsUpdate, context: _MsCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user:
        return
    try:
        if bot.is_gbanned(user.id):
            await update.message.reply_text("❌ You are globally banned.")
            return
    except Exception:
        pass
    try:
        update_name_cache(user)
    except Exception:
        pass
    uid = str(user.id)
    _ms_check_reset(uid)
    _ms_user(uid)  # ensure init
    text = _ms_center_text(uid)
    await update.message.reply_text(text, reply_markup=_ms_center_kb())

async def missions_callback(update: _MsUpdate, context: _MsCtx.DEFAULT_TYPE):
    q = update.callback_query
    if not q:
        return
    user = q.from_user
    uid = str(user.id)
    data = q.data or ""
    parts = data.split("|")
    if len(parts) < 2:
        try:
            await q.answer()
        except Exception:
            pass
        return
    action = parts[1]
    _ms_check_reset(uid)

    try:
        await q.answer()
    except Exception:
        pass

    try:
        if action == "home":
            text = _ms_center_text(uid)
            await q.edit_message_text(text, reply_markup=_ms_center_kb())
            return

        if action == "tier" and len(parts) >= 3:
            tier = parts[2]
            if tier not in ("daily", "weekly", "monthly"):
                return
            text = _ms_tier_text(uid, tier)
            await q.edit_message_text(text, reply_markup=_ms_tier_kb(uid, tier))
            return

        if action == "start" and len(parts) >= 3:
            tier = parts[2]
            if tier not in ("daily", "weekly", "monthly"):
                return
            _ms_start_tier(uid, tier)
            try:
                await q.answer(f"✅ {tier.title()} Mission Started!", show_alert=False)
            except Exception:
                pass
            text = _ms_tier_text(uid, tier)
            await q.edit_message_text(text, reply_markup=_ms_tier_kb(uid, tier))
            return

        if action == "claim_menu":
            u = _ms_user(uid)
            rows = []
            available = False
            for tier in ("daily", "weekly", "monthly"):
                if _ms_is_tier_complete(uid, tier) and not u[tier].get("claimed"):
                    rows.append([_MsBtn(f"🎁 Claim {tier.title()} Reward",
                                        callback_data=f"mc|claim|{tier}")])
                    available = True
            rows.append([_MsBtn("🏠 Mission Center", callback_data="mc|home")])
            if not available:
                msg = ("🎁 Available Rewards\n\n"
                       "ℹ️ ယခုလက်ရှိ Claim လုပ်နိုင်သော Reward မရှိသေးပါ။\n"
                       "Mission များ Complete ဖြစ်အောင် ဆက်လုပ်ပါ!")
            else:
                msg = ("🎁 Available Rewards\n\n"
                       "အောက်ပါ Reward များကို Claim လုပ်နိုင်ပါပြီ —")
            await q.edit_message_text(msg, reply_markup=_MsKb(rows))
            return

        if action == "claim" and len(parts) >= 3:
            tier = parts[2]
            if tier not in ("daily", "weekly", "monthly"):
                return
            u = _ms_user(uid)
            if not _ms_is_tier_complete(uid, tier):
                try:
                    await q.answer("⛔ Mission မပြီးသေးပါ", show_alert=True)
                except Exception:
                    pass
                return
            if u[tier].get("claimed"):
                try:
                    await q.answer("ℹ️ Reward ကို Claim ပြီးပါပြီ", show_alert=True)
                except Exception:
                    pass
                return
            u[tier]["claimed"] = True
            # bump completion counters for higher tiers right away
            if tier == "daily":
                u["weekly"]["progress"]["complete_daily"] = \
                    int(u["weekly"]["progress"].get("complete_daily", 0)) + 1
            elif tier == "weekly":
                u["monthly"]["progress"]["complete_weekly"] = \
                    int(u["monthly"]["progress"].get("complete_weekly", 0)) + 1
            _ms_save()
            await _ms_deliver_reward_cards(q, context, uid, tier)
            # refresh tier view
            try:
                text = _ms_tier_text(uid, tier)
                await context.bot.send_message(chat_id=q.message.chat_id,
                                               text=text,
                                               reply_markup=_ms_tier_kb(uid, tier))
            except Exception:
                pass
            return
    except Exception as e:
        try:
            logger.error(f"[missions] callback error: {e}")
        except Exception:
            pass


# ═══════════════════════════════════════════════════════════════════════
# 🪄  PASSIVE PROGRESS OBSERVER  (group=-5, never blocks)
# ═══════════════════════════════════════════════════════════════════════
# Maps slash-commands → mission keys to bump by 1 on each invocation.
_MS_COMMAND_HOOKS = {
    "claim":    ["diamond_hunt"],         # claiming a card
    "daily":    ["support_task"],         # daily check-in
    "slot":     ["multi_battle"],         # gambling round
    "basket":   ["multi_battle"],
    "blue":     ["alone_fight"],          # blue dice game
    "casino":   ["multi_battle"],
    "sell":     ["trade_cards"],
    "give":     ["trade_cards"],
    "gpay":     ["trade_cards"],
    "cpay":     ["trade_cards"],
    "marry":    ["support_task"],
    "mysterybox": ["diamond_hunt"],
    "rob":      ["alone_fight"],
}

# pvp callbacks (tictactoe etc.) — bump tictactoe when callbacks like 'ttt_' or 'pvp_' fire
_MS_CALLBACK_HOOKS = [
    (_ms_re.compile(r"^ttt[_|]"),  ["tictactoe"]),
    (_ms_re.compile(r"^tictac"),    ["tictactoe"]),
    (_ms_re.compile(r"^pvp[_|]"),  ["pvp_win", "pvp_win_month", "boss_hunt", "world_boss"]),
    (_ms_re.compile(r"^boss[_|]"), ["boss_hunt", "world_boss"]),
]

async def _ms_observer_msg(update: _MsUpdate, context: _MsCtx.DEFAULT_TYPE):
    """Passive observer — runs in group=-5 BEFORE other handlers; never blocks."""
    try:
        msg = update.message
        if not msg or not msg.text or not update.effective_user:
            return
        if update.effective_user.is_bot:
            return
        text = msg.text.strip()
        if not text.startswith("/"):
            return
        # extract command word
        first = text.split()[0][1:]
        if "@" in first:
            first = first.split("@", 1)[0]
        first = first.lower()
        keys = _MS_COMMAND_HOOKS.get(first)
        if not keys:
            return
        uid = str(update.effective_user.id)
        for k in keys:
            try:
                mission_progress_add(uid, k, 1)
            except Exception:
                pass
    except Exception:
        # NEVER raise inside a passive observer
        pass

async def _ms_observer_cbq(update: _MsUpdate, context: _MsCtx.DEFAULT_TYPE):
    try:
        q = update.callback_query
        if not q or not q.data or not q.from_user:
            return
        if q.from_user.is_bot:
            return
        data = q.data
        uid = str(q.from_user.id)
        for pat, keys in _MS_CALLBACK_HOOKS:
            if pat.search(data):
                for k in keys:
                    try:
                        mission_progress_add(uid, k, 1)
                    except Exception:
                        pass
                break
    except Exception:
        pass


# ═══════════════════════════════════════════════════════════════════════
# 🎭  /setrole  —  Owner-only role creator
# ═══════════════════════════════════════════════════════════════════════
def _ms_split_emoji(arg: str):
    """Split a string like 'sex🔞' or '🔞sex' into (name, emoji)."""
    if not arg:
        return "", ""
    # Find all emoji-like chars (basic heuristic — any non-letter / non-digit / non-ascii-symbol)
    name_chars = []
    emoji_chars = []
    for ch in arg:
        code = ord(ch)
        if (("a" <= ch.lower() <= "z") or ch.isdigit() or ch in "_-"):
            name_chars.append(ch)
        elif code > 127:
            emoji_chars.append(ch)
    name = "".join(name_chars).strip().lower()
    emoji = "".join(emoji_chars).strip()
    return name, emoji

async def setrole_cmd(update: _MsUpdate, context: _MsCtx.DEFAULT_TYPE):
    """/setrole <name>[emoji]  — Owner-only: create a new card-role at runtime."""
    if not update.effective_user or not update.message:
        return
    try:
        if not bot.is_real_owner(update.effective_user.id):
            await update.message.reply_text("❌ Owner only command")
            return
    except Exception:
        await update.message.reply_text("❌ Owner only command")
        return

    if not context.args:
        await update.message.reply_text(
            "📝 𝗨𝘀𝗮𝗴𝗲:\n"
            "/setrole <name><emoji>\n\n"
            "ဥပမာ:\n"
            "• /setrole sex🔞\n"
            "• /setrole vampire🧛\n"
            "• /setrole pirate🏴‍☠️\n\n"
            "ℹ️ Emoji မပါသော အမည်ပေးပါက default 🎭 ကို သုံးမည်။"
        )
        return

    raw = " ".join(context.args).strip()
    name, emoji = _ms_split_emoji(raw)
    if not name:
        await update.message.reply_text("⚠️ Role အမည် (a-z, 0-9, _, -) ပါမသပါ။ ဥပမာ: /setrole sex🔞")
        return
    if not emoji:
        emoji = "🎭"

    key = name
    if key in ROLES:
        # update emoji
        ROLES[key]["emoji"]   = emoji
        ROLES[key]["display"] = f"{emoji} {ROLES[key]['name']}"
        try:
            bot.settings.setdefault("custom_roles", {})[key] = {
                "name": ROLES[key]["name"], "emoji": emoji
            }
            bot.save_settings()
        except Exception:
            pass
        await update.message.reply_text(
            f"♻️ Role ပြန်ပြင်ပြီးပါပြီ\n\n"
            f"🔑 key: `{key}`\n"
            f"📛 name: {ROLES[key]['name']}\n"
            f"😀 emoji: {emoji}\n"
            f"🎯 display: {ROLES[key]['display']}",
            parse_mode='Markdown'
        )
        return

    display_name = name.capitalize()
    ROLES[key] = {"name": display_name, "emoji": emoji, "display": f"{emoji} {display_name}"}
    # Register aliases
    ROLE_ALIASES[key] = key
    ROLE_ALIASES[key.lower()] = key

    # Register a /<key> search command at runtime (best-effort)
    try:
        app = context.application
        if app is not None and 'role_search_cmd' in globals():
            app.add_handler(_MsCmd(key, role_search_cmd))
    except Exception:
        pass

    # Persist into settings so it survives restart
    try:
        bot.settings.setdefault("custom_roles", {})[key] = {"name": display_name, "emoji": emoji}
        bot.save_settings()
    except Exception:
        pass

    await update.message.reply_text(
        "✅ 𝗡𝗲𝘄 𝗥𝗼𝗹𝗲 𝗖𝗿𝗲𝗮𝘁𝗲𝗱\n\n"
        f"🔑 key: `{key}`\n"
        f"📛 name: {display_name}\n"
        f"😀 emoji: {emoji}\n"
        f"🎯 display: {ROLES[key]['display']}\n\n"
        f"💡 အသုံးပြုပုံ —\n"
        f"• `/role <card_id>` → Card တွင် ဤ role ကို သတ်မှတ်နိုင်ပါပြီ\n"
        f"• `/{key}` → ဤ role ရှိ card များကို ရှာရန်",
        parse_mode='Markdown'
    )

def _ms_restore_custom_roles():
    """At startup: restore any custom roles owner had created previously."""
    try:
        custom = bot.settings.get("custom_roles", {}) or {}
        for key, info in custom.items():
            if not key or not isinstance(info, dict):
                continue
            name = info.get("name") or key.capitalize()
            emoji = info.get("emoji") or "🎭"
            if key not in ROLES:
                ROLES[key] = {"name": name, "emoji": emoji,
                              "display": f"{emoji} {name}"}
                ROLE_ALIASES[key] = key
                ROLE_ALIASES[key.lower()] = key
    except Exception:
        pass


# ═══════════════════════════════════════════════════════════════════════
# 👥  /ownplist  —  list owner-permitted users with @mentions
# ═══════════════════════════════════════════════════════════════════════
async def ownplist_cmd(update: _MsUpdate, context: _MsCtx.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    try:
        if not bot.is_real_owner(update.effective_user.id):
            await update.message.reply_text("❌ Owner only command")
            return
    except Exception:
        await update.message.reply_text("❌ Owner only command")
        return

    try:
        permitted = bot.settings.get("owner_permitted_users", []) or []
    except Exception:
        permitted = []

    if not permitted:
        await update.message.reply_text(
            "📋 𝗢𝘄𝗻𝗲𝗿-𝗣𝗲𝗿𝗺𝗶𝘁 𝗟𝗶𝘀𝘁\n\n"
            "ℹ️ မည်သူ့ကိုမှ owner-permit မပေးထားသေးပါ။\n\n"
            "💡 `/ownp @username` သို့မဟုတ် reply ဖြင့် permit ပေးနိုင်ပါသည်။",
            parse_mode='Markdown'
        )
        return

    lines = ["📋 𝗢𝘄𝗻𝗲𝗿-𝗣𝗲𝗿𝗺𝗶𝘁𝘁𝗲𝗱 𝗨𝘀𝗲𝗿𝘀\n",
             "━━━━━━━━━━━━━━"]
    rank_icons = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]

    for i, raw_uid in enumerate(permitted):
        try:
            uid_int = int(raw_uid)
        except Exception:
            continue
        # Try cache first
        name = USER_CACHE.get(str(uid_int))
        if not name:
            try:
                chat = await context.bot.get_chat(uid_int)
                name = chat.first_name or chat.username or f"User {uid_int}"
                try:
                    USER_CACHE[str(uid_int)] = name
                except Exception:
                    pass
            except Exception:
                name = f"User {uid_int}"

        icon = rank_icons[i] if i < len(rank_icons) else f"{i+1}."
        # Use MarkdownV1 [name](tg://user?id=) mention
        try:
            mention = _mention_md(uid_int, name)
        except Exception:
            mention = f"[{name}](tg://user?id={uid_int})"
        lines.append(f"{icon}  {mention}  —  `{uid_int}`")

    lines.append("━━━━━━━━━━━━━━")
    lines.append(f"👥 Total: **{len(permitted)}** user(s)")

    try:
        await update.message.reply_text(
            "\n".join(lines),
            parse_mode='Markdown',
            disable_web_page_preview=True,
        )
    except Exception:
        # Fallback w/o markdown if any user-name breaks formatting
        plain = []
        for line in lines:
            plain.append(_ms_re.sub(r"[`*_\[\]\(\)]", "", line))
        await update.message.reply_text("\n".join(plain))


# ═══════════════════════════════════════════════════════════════════════
# 🧩  REGISTRATION  — called automatically from a wrapper around main()
# ═══════════════════════════════════════════════════════════════════════
def register_mission_handlers(application):
    """Attach all new handlers. Safe to call multiple times (idempotent-ish)."""
    # Passive observers — group=-5 so they run BEFORE existing -4/-3 blockers
    # but never call ApplicationHandlerStop, so they don't block anything.
    try:
        application.add_handler(
            _MsMsg(_ms_filters.COMMAND, _ms_observer_msg), group=-5
        )
    except Exception:
        pass
    try:
        application.add_handler(
            _MsCbq(_ms_observer_cbq), group=-5
        )
    except Exception:
        pass

    # Main /missions
    application.add_handler(_MsCmd("missions", missions_cmd))
    application.add_handler(_MsCbq(missions_callback, pattern=r"^mc\|"))

    # /setrole + /ownplist
    application.add_handler(_MsCmd("setrole",  setrole_cmd))
    application.add_handler(_MsCmd("ownplist", ownplist_cmd))

    # Restore custom roles from settings
    _ms_restore_custom_roles()

    try:
        logger.info("[missions] ⚔️  Mission Center + /setrole + /ownplist registered")
    except Exception:
        pass


# ═══════════════════════════════════════════════════════════════════════
# 🪝  AUTO-WIRE INTO main()  — monkey-patch main once, on import
# ═══════════════════════════════════════════════════════════════════════
def _ms_install_main_wrapper():
    """Replace main() with a wrapper that builds Application, registers
    everything original main() registers, AND our new handlers."""
    g = globals()
    orig_main = g.get("main")
    if not callable(orig_main) or getattr(orig_main, "_ms_wrapped", False):
        return

    def wrapped_main():
        # We can't easily intercept the local 'application' inside the original
        # main(), so we instead patch Application.builder().build() to register
        # our handlers right after construction.
        from telegram.ext import Application as _MS_App
        orig_build = _MS_App.builder().__class__.build

        def patched_build(self, *a, **kw):
            app_obj = orig_build(self, *a, **kw)
            try:
                register_mission_handlers(app_obj)
            except Exception as e:
                try:
                    logger.error(f"[missions] register failed: {e}")
                except Exception:
                    pass
            # restore so only first call is patched
            _MS_App.builder().__class__.build = orig_build
            return app_obj

        _MS_App.builder().__class__.build = patched_build
        return orig_main()

    wrapped_main._ms_wrapped = True
    g["main"] = wrapped_main

_ms_install_main_wrapper()
# ═══════════════════════════════════════════════════════════════════════
