# ── per-user anti-spam cooldowns for game commands ──────────────────────
_ADDON_COOLDOWNS: dict[str, float] = {}
_ADDON_COOLDOWN_SECONDS = 2.0          # tap-spam guard
_ADDON_TTT_SESSIONS: dict[int, dict] = {}   # chat_id -> ttt session
_ADDON_DIAMOND_SESSIONS: dict[int, dict] = {}  # chat_id -> diamond session
_ADDON_MTASK_SESSIONS: dict[int, dict] = {}  # chat_id -> support task session


def _ad_check_spam(uid: str) -> bool:
    """Return True if user is allowed to act, False if rate-limited."""
    now = _addon_time.time()
    last = _ADDON_COOLDOWNS.get(uid, 0.0)
    if now - last < _ADDON_COOLDOWN_SECONDS:
        return False
    _ADDON_COOLDOWNS[uid] = now
    return True


