# 🎯  PREMIUM /start  —  Video/Photo + Caption + Inline Buttons
# ═══════════════════════════════════════════════════════════════════════
async def _ad_premium_start(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user:
        return
    try:
        update_name_cache(user)
    except Exception:
        pass

    try:
        me = await context.bot.get_me()
        bot_username = me.username or "this_bot"
    except Exception:
        bot_username = "this_bot"

    caption = (
        "╔════════════════════╗\n"
        "       ✦ SYSTEM ONLINE ✦\n"
        "╚════════════════════╝\n\n"
        f"Welcome Back, {user.first_name}\n\n"
        "▰ Account Status   : Active\n"
        "▰ Collection Mode  : Ready\n"
        "▰ Missions Status  : Available\n"
        "▰ Event Status     : Live\n\n"
        "━━━━━━━━━━━━━━━━\n"
        "「 Choose Your Path 」\n"
        "━━━━━━━━━━━━━━━━"
    )

    help_link = _ad_settings_get('help_link', '') or ''
    add_group_link = f"https://t.me/{bot_username}?startgroup=true"

    rows = [
        [
            _AdBtn("🎯 Start",    callback_data="psui|main"),
            _AdBtn("📋 Missions", callback_data="psui|missions"),
        ],
        [_AdBtn("➕ Add Your Group", url=add_group_link)],
    ]
    if help_link.strip().lower().startswith(("http://", "https://", "tg://", "t.me/")):
        rows.append([_AdBtn("❓ Help", url=help_link.strip())])
    else:
        rows.append([_AdBtn("❓ Help", callback_data="psui|help_unset")])
    kb = _AdKb(rows)

    media_id = _ad_settings_get('welcome_media', '') or ''
    media_type = (_ad_settings_get('welcome_type', '') or '').lower()

    sent_ok = False
    if media_id and media_type in ('video', 'photo'):
        try:
            if media_type == 'video':
                await update.message.reply_video(
                    video=media_id, caption=caption, reply_markup=kb
                )
            else:
                await update.message.reply_photo(
                    photo=media_id, caption=caption, reply_markup=kb
                )
            sent_ok = True
        except Exception as e:
            try:
                logger.error(f"[premium-start] media send failed: {e}")
            except Exception:
                pass

    if not sent_ok:
        # Fallback to plain text if no media has been set or send failed
        try:
            await update.message.reply_text(caption, reply_markup=kb)
        except Exception:
            pass


async def _ad_psui_callback(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    q = update.callback_query
    if not q:
        return
    try:
        await q.answer()
    except Exception:
        pass
    data = (q.data or "").split("|")
    if len(data) < 2:
        return
    action = data[1]
    user = q.from_user

    if action == "main":
        try:
            await context.bot.send_message(
                chat_id=q.message.chat_id,
                text="🎮  Main Menu\n\nUse /usercm to view user commands,\n"
                     "/admcm for admin commands or /owncm for owner tools."
            )
        except Exception:
            pass
        return

    if action == "missions":
        # Re-use existing mission system entry point
        try:
            uid = str(user.id)
            _ms_check_reset(uid)
            _ms_user(uid)
            text = _ms_daily_premium_text(uid)
            await context.bot.send_message(
                chat_id=q.message.chat_id,
                text=text,
                reply_markup=_ms_daily_premium_kb(uid),
            )
        except Exception:
            try:
                await context.bot.send_message(
                    chat_id=q.message.chat_id,
                    text="📋 Use /missions to open the Mission Center."
                )
            except Exception:
                pass
        return

    if action == "help_unset":
        try:
            await context.bot.send_message(
                chat_id=q.message.chat_id,
                text="ℹ️ Help link is not configured yet.\n"
                     "Owner can set it using:\n"
                     "/sethelp <https://your-help-link>",
            )
        except Exception:
            pass
        return


# ═══════════════════════════════════════════════════════════════════════
# 👑  /setwcl  —  Owner: set welcome media (video / photo)
# ═══════════════════════════════════════════════════════════════════════
async def setwcl_cmd(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not bot.is_owner(user.id):
        try:
            await update.message.reply_text("⛔ Owner only command.")
        except Exception:
            pass
        return

    msg = update.message
    if not msg or not msg.reply_to_message:
        await msg.reply_text(
            "ℹ️ Usage:\n"
            "1. Reply to a *video* or *photo* message\n"
            "2. Then send: /setwcl\n\n"
            "→ Saves the media as the /start welcome.",
            parse_mode="Markdown",
        )
        return

    target = msg.reply_to_message
    file_id = None
    mtype = None

    if target.video:
        file_id = target.video.file_id
        mtype = "video"
    elif target.photo:
        # pick largest size
        file_id = target.photo[-1].file_id
        mtype = "photo"
    elif target.document and target.document.mime_type:
        mime = target.document.mime_type.lower()
        if mime.startswith("video"):
            file_id = target.document.file_id
            mtype = "video"
        elif mime.startswith("image"):
            file_id = target.document.file_id
            mtype = "photo"

    if not file_id or not mtype:
        await msg.reply_text("❌ Reply must be a video or photo message.")
        return

    _ad_settings_set("welcome_media", file_id)
    _ad_settings_set("welcome_type", mtype)

    await msg.reply_text(
        f"✅ Welcome {mtype} saved.\n"
        "Use /start to preview the new premium UI."
    )


# ═══════════════════════════════════════════════════════════════════════
# 👑  /sethelp <url>  —  Owner: set the help-button URL
# ═══════════════════════════════════════════════════════════════════════
async def sethelp_cmd(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not bot.is_owner(user.id):
        try:
            await update.message.reply_text("⛔ Owner only command.")
        except Exception:
            pass
        return

    args = context.args or []
    if not args:
        cur = _ad_settings_get('help_link', '') or '—'
        await update.message.reply_text(
            "ℹ️ Usage: /sethelp <url>\n\n"
            f"Current help link:\n{cur}"
        )
        return

    link = args[0].strip()
    if not link.lower().startswith(("http://", "https://", "tg://", "t.me/")):
        await update.message.reply_text("❌ Provide a valid http(s) or t.me link.")
        return

    _ad_settings_set('help_link', link)
    await update.message.reply_text(f"✅ Help link saved:\n{link}")


# ═══════════════════════════════════════════════════════════════════════
# 📋  Daily Mission UI (matches user's exact spec — overrides default tier view)
# ═══════════════════════════════════════════════════════════════════════
_AD_DAILY_LABELS = {
    "multi_battle": "⚔️ Multi Battle",
    "alone_fight":  "🥊 Alone Fight",
    "tictactoe":    "❌ Tic Tac Toe",
    "support_task": "🤝 Support Task",
    "diamond_hunt": "💎 Diamond Hunt",
}

# Targets must mirror DAILY_MISSIONS in original file
_AD_DAILY_TARGETS = {
    "multi_battle": 3,
    "alone_fight":  3,
    "tictactoe":    2,
    "support_task": 1,
    "diamond_hunt": 3,
}


def _ms_daily_premium_text(uid: str) -> str:
    """Re-rendered Daily-Mission text in the exact format requested."""
    _ms_check_reset(uid)
    u = _ms_user(uid)
    prog = u["daily"]["progress"]

    lines = []
    lines.append("╔════════════════════╗")
    lines.append("        📋 Daily Missions")
    lines.append("╚════════════════════╝\n")

    completed = 0
    total = 0
    ordered_keys = ["multi_battle", "alone_fight", "tictactoe",
                    "support_task", "diamond_hunt"]
    for key in ordered_keys:
        tgt = _AD_DAILY_TARGETS[key]
        cur = min(int(prog.get(key, 0)), tgt)
        total += tgt
        completed += cur
        label = _AD_DAILY_LABELS[key]
        bar = _ad_progress_bar(cur, tgt)
        lines.append(f"{label}  ({cur}/{tgt})")
        lines.append(f"   {bar}")

    pct = int((completed / total) * 100) if total else 0

    all_done = _ms_is_tier_complete(uid, "daily")
    claimed = bool(u["daily"].get("claimed"))

    status_line = "🎁 Ready to Claim" if (all_done and not claimed) else (
        "✅ All Claimed" if claimed else "⏳ In Progress"
    )

    lines.append("")
    lines.append(f"📊 Progress : {pct}%")
    lines.append("🎁 Reward    : Random Card")
    lines.append(f"💠 Status    : {status_line}")
    lines.append("\n━━━━━━━━━━━━━━━━━━")
    lines.append("Commands:")
    lines.append("/mbattle  /afight  /tictoe")
    lines.append("/mtask    /diamond")

    if u.get("started_daily"):
        try:
            left = float(u["daily"].get("reset_at", 0)) - _addon_time.time()
            lines.append(f"\n⏰ Reset in: { _ms_format_remaining(left) }")
        except Exception:
            pass
    return "\n".join(lines)


def _ms_daily_premium_kb(uid: str) -> _AdKb:
    u = _ms_user(uid)
    rows = []
    if not u.get("started_daily"):
        rows.append([_AdBtn("✅ Start Missions", callback_data="mc|start|daily")])

    rows.append([
        _AdBtn("🎮 Play",  callback_data="psui|main"),
        _AdBtn("🎁 Claim", callback_data="adm|claim_daily"),
    ])
    rows.append([
        _AdBtn("🏆 Weekly",  callback_data="mc|tier|weekly"),
        _AdBtn("👑 Monthly", callback_data="mc|tier|monthly"),
    ])
    rows.append([_AdBtn("🔄 Refresh", callback_data="adm|refresh_daily")])
    return _AdKb(rows)


def _ad_progress_bar(cur: int, total: int, width: int = 10) -> str:
    if total <= 0:
        return "▱" * width
    filled = int(round((cur / total) * width))
    filled = max(0, min(width, filled))
    return "▰" * filled + "▱" * (width - filled) + f"  {int((cur/total)*100)}%"


async def _ad_mission_extra_callback(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    q = update.callback_query
    if not q:
        return
    try:
        await q.answer()
    except Exception:
        pass
    data = (q.data or "").split("|")
    if len(data) < 2:
        return
    action = data[1]
    uid = str(q.from_user.id)

    if action == "refresh_daily":
        try:
            await q.edit_message_text(
                _ms_daily_premium_text(uid),
                reply_markup=_ms_daily_premium_kb(uid),
            )
        except Exception:
            pass
        return

    if action == "claim_daily":
        u = _ms_user(uid)
        if not _ms_is_tier_complete(uid, "daily"):
            try:
                await q.answer("⛔ Mission မပြီးသေးပါ", show_alert=True)
            except Exception:
                pass
            return
        if u["daily"].get("claimed"):
            try:
                await q.answer("ℹ️ Reward ကို Claim ပြီးပါပြီ", show_alert=True)
            except Exception:
                pass
            return
        u["daily"]["claimed"] = True
        # bump weekly counter
        u["weekly"]["progress"]["complete_daily"] = \
            int(u["weekly"]["progress"].get("complete_daily", 0)) + 1
        _ms_save()
        try:
            await _ms_deliver_reward_cards(q, context, uid, "daily")
        except Exception:
            try:
                await context.bot.send_message(
                    chat_id=q.message.chat_id,
                    text="🎁 Daily Mission Reward delivered!"
                )
            except Exception:
                pass
        try:
            await context.bot.send_message(
                chat_id=q.message.chat_id,
                text=_ms_daily_premium_text(uid),
                reply_markup=_ms_daily_premium_kb(uid),
            )
        except Exception:
            pass
        return


