# ⚙️  Auto-start daily tier on first game command (so progress is tracked)
# ═══════════════════════════════════════════════════════════════════════
def _ad_ensure_daily_started(uid: str):
    _ms_check_reset(uid)
    u = _ms_user(uid)
    if not u.get("started_daily"):
        _ms_start_tier(uid, "daily")


def _ad_add_progress(uid: str, key: str, amount: int = 1):
    _ad_ensure_daily_started(uid)
    try:
        mission_progress_add(uid, key, amount)
    except Exception:
        pass


# ═══════════════════════════════════════════════════════════════════════
# ⚔️  /mbattle  —  Multi Battle (PvP card-power vs random AI opponent)
# ═══════════════════════════════════════════════════════════════════════
def _ad_user_card_power(uid: str) -> int:
    """Sum of rarity values of user's owned cards. Falls back to random."""
    try:
        udata = bot.data.get("users", {}).get(uid, {})
        cards = udata.get("cards", {}) or udata.get("collection", {}) or {}
        cards_all = bot.data.get("cards", {})
        power = 0
        count = 0
        for cid in cards:
            c = cards_all.get(str(cid)) or cards_all.get(cid)
            if not c:
                continue
            try:
                rar = int(c.get("rarity", 1))
            except Exception:
                rar = 1
            power += max(1, rar) * 5
            count += 1
        if power <= 0:
            power = _addon_random.randint(40, 80)
        return power
    except Exception:
        return _addon_random.randint(40, 80)


async def mbattle_cmd(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not update.message:
        return
    uid = str(user.id)
    if not _ad_check_spam(uid):
        await update.message.reply_text("⏳ Cooldown… please wait a moment.")
        return
    _ad_ensure_daily_started(uid)
    u = _ms_user(uid)
    cur = int(u["daily"]["progress"].get("multi_battle", 0))
    target = _AD_DAILY_TARGETS["multi_battle"]
    if cur >= target:
        await update.message.reply_text(
            f"⚔️ Multi Battle already complete ({cur}/{target}) ✅"
        )
        return

    p1 = _ad_user_card_power(uid)
    p2 = _addon_random.randint(30, 130)
    # 50/50-ish but skewed by player power
    win = p1 > p2 or (p1 == p2 and _addon_random.random() < 0.5)
    if win:
        _ad_add_progress(uid, "multi_battle", 1)
        new_cur = min(cur + 1, target)
        bar = _ad_progress_bar(new_cur, target)
        text = (
            "╔════════════════════╗\n"
            "    ⚔️  MULTI BATTLE  ⚔️\n"
            "╚════════════════════╝\n\n"
            f"🟢 Your Power : {p1}\n"
            f"🔴 Enemy Power: {p2}\n\n"
            "🏆  𝗩𝗜𝗖𝗧𝗢𝗥𝗬!\n\n"
            f"⚔️ Multi Battle  ({new_cur}/{target})\n"
            f"   {bar}"
        )
    else:
        text = (
            "╔════════════════════╗\n"
            "    ⚔️  MULTI BATTLE  ⚔️\n"
            "╚════════════════════╝\n\n"
            f"🟢 Your Power : {p1}\n"
            f"🔴 Enemy Power: {p2}\n\n"
            "💀  𝗗𝗘𝗙𝗘𝗔𝗧 — Progress unchanged.\n\n"
            f"⚔️ Multi Battle  ({cur}/{target})\n"
            f"   {_ad_progress_bar(cur, target)}"
        )
    kb = _AdKb([
        [_AdBtn("🔁 Battle Again", callback_data="adgame|mbattle"),
         _AdBtn("📋 Missions",     callback_data="adm|refresh_daily")],
    ])
    await update.message.reply_text(text, reply_markup=kb)


# ═══════════════════════════════════════════════════════════════════════
# 🥊  /afight  —  Alone Fight (User vs AI)
# ═══════════════════════════════════════════════════════════════════════
async def afight_cmd(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not update.message:
        return
    uid = str(user.id)
    if not _ad_check_spam(uid):
        await update.message.reply_text("⏳ Cooldown… please wait a moment.")
        return
    _ad_ensure_daily_started(uid)
    u = _ms_user(uid)
    cur = int(u["daily"]["progress"].get("alone_fight", 0))
    target = _AD_DAILY_TARGETS["alone_fight"]
    if cur >= target:
        await update.message.reply_text(
            f"🥊 Alone Fight already complete ({cur}/{target}) ✅"
        )
        return

    user_p = _ad_user_card_power(uid) + _addon_random.randint(-10, 20)
    ai_p   = _addon_random.randint(40, 140)
    win = user_p > ai_p
    if win:
        _ad_add_progress(uid, "alone_fight", 1)
        new_cur = min(cur + 1, target)
        bar = _ad_progress_bar(new_cur, target)
        text = (
            "╔════════════════════╗\n"
            "     🥊  ALONE FIGHT  🥊\n"
            "╚════════════════════╝\n\n"
            f"💪 Your Power : {user_p}\n"
            f"🤖 AI  Power  : {ai_p}\n\n"
            "🏆  𝗬𝗢𝗨 𝗪𝗜𝗡!\n\n"
            f"🥊 Alone Fight  ({new_cur}/{target})\n"
            f"   {bar}"
        )
    else:
        text = (
            "╔════════════════════╗\n"
            "     🥊  ALONE FIGHT  🥊\n"
            "╚════════════════════╝\n\n"
            f"💪 Your Power : {user_p}\n"
            f"🤖 AI  Power  : {ai_p}\n\n"
            "💀  𝗗𝗘𝗙𝗘𝗔𝗧 — try again, hero!\n\n"
            f"🥊 Alone Fight  ({cur}/{target})\n"
            f"   {_ad_progress_bar(cur, target)}"
        )
    kb = _AdKb([
        [_AdBtn("🔁 Fight Again", callback_data="adgame|afight"),
         _AdBtn("📋 Missions",    callback_data="adm|refresh_daily")],
    ])
    await update.message.reply_text(text, reply_markup=kb)


# ═══════════════════════════════════════════════════════════════════════
# ❌  /tictoe  —  Tic Tac Toe 3x3 (User vs Bot)
# ═══════════════════════════════════════════════════════════════════════
_TTT_LINES = [
    (0, 1, 2), (3, 4, 5), (6, 7, 8),     # rows
    (0, 3, 6), (1, 4, 7), (2, 5, 8),     # cols
    (0, 4, 8), (2, 4, 6),                # diagonals
]


def _ttt_check_winner(board):
    for a, b, c in _TTT_LINES:
        if board[a] != " " and board[a] == board[b] == board[c]:
            return board[a]
    if " " not in board:
        return "draw"
    return None


def _ttt_bot_move(board):
    # 1) Win if possible  2) Block player  3) Center  4) Corner  5) Random
    def find_move(player):
        for a, b, c in _TTT_LINES:
            line = [board[a], board[b], board[c]]
            if line.count(player) == 2 and line.count(" ") == 1:
                return [a, b, c][line.index(" ")]
        return None
    m = find_move("O")
    if m is not None: return m
    m = find_move("X")
    if m is not None: return m
    if board[4] == " ":
        return 4
    for i in (0, 2, 6, 8):
        if board[i] == " ":
            return i
    empties = [i for i, v in enumerate(board) if v == " "]
    return _addon_random.choice(empties) if empties else -1


def _ttt_render_kb(session_id: int, board: list, finished: bool) -> _AdKb:
    rows = []
    for r in range(3):
        row = []
        for c in range(3):
            i = r * 3 + c
            mark = board[i]
            label = mark if mark != " " else "·"
            cb = f"ttt|move|{session_id}|{i}" if (not finished and mark == " ") else "ttt|nop"
            row.append(_AdBtn(label, callback_data=cb))
        rows.append(row)
    if finished:
        rows.append([_AdBtn("🔁 Play Again", callback_data=f"ttt|new|{session_id}"),
                     _AdBtn("📋 Missions",   callback_data="adm|refresh_daily")])
    else:
        rows.append([_AdBtn("❌ Resign", callback_data=f"ttt|resign|{session_id}")])
    return _AdKb(rows)


def _ttt_text(uid: str, board: list, status: str) -> str:
    u = _ms_user(uid)
    cur = int(u["daily"]["progress"].get("tictactoe", 0))
    tgt = _AD_DAILY_TARGETS["tictactoe"]
    bar = _ad_progress_bar(cur, tgt)
    return (
        "╔════════════════════╗\n"
        "      ❌  TIC TAC TOE  ⭕\n"
        "╚════════════════════╝\n\n"
        f"{status}\n\n"
        f"❌ Tic Tac Toe  ({cur}/{tgt})\n"
        f"   {bar}"
    )


async def tictoe_cmd(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not update.message:
        return
    uid = str(user.id)
    if not _ad_check_spam(uid):
        await update.message.reply_text("⏳ Cooldown… please wait a moment.")
        return
    _ad_ensure_daily_started(uid)
    u = _ms_user(uid)
    cur = int(u["daily"]["progress"].get("tictactoe", 0))
    tgt = _AD_DAILY_TARGETS["tictactoe"]
    if cur >= tgt:
        await update.message.reply_text(f"❌ Tic Tac Toe already complete ({cur}/{tgt}) ✅")
        return

    session_id = update.message.chat_id
    _ADDON_TTT_SESSIONS[session_id] = {
        "uid": uid,
        "board": [" "] * 9,
        "finished": False,
    }
    s = _ADDON_TTT_SESSIONS[session_id]
    await update.message.reply_text(
        _ttt_text(uid, s["board"], "🎮 Your move (❌). Tap a cell."),
        reply_markup=_ttt_render_kb(session_id, s["board"], False),
    )


async def _ttt_callback(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    q = update.callback_query
    if not q:
        return
    try:
        await q.answer()
    except Exception:
        pass
    parts = (q.data or "").split("|")
    if len(parts) < 2:
        return
    action = parts[1]
    chat_id = q.message.chat_id

    if action == "nop":
        return

    session = _ADDON_TTT_SESSIONS.get(chat_id)

    if action == "new":
        uid = str(q.from_user.id)
        _ad_ensure_daily_started(uid)
        u = _ms_user(uid)
        cur = int(u["daily"]["progress"].get("tictactoe", 0))
        tgt = _AD_DAILY_TARGETS["tictactoe"]
        if cur >= tgt:
            try:
                await q.edit_message_text(f"❌ Tic Tac Toe already complete ({cur}/{tgt}) ✅")
            except Exception:
                pass
            return
        _ADDON_TTT_SESSIONS[chat_id] = {"uid": uid, "board": [" "] * 9, "finished": False}
        s = _ADDON_TTT_SESSIONS[chat_id]
        try:
            await q.edit_message_text(
                _ttt_text(uid, s["board"], "🎮 New game! Your move (❌)."),
                reply_markup=_ttt_render_kb(chat_id, s["board"], False),
            )
        except Exception:
            pass
        return

    if not session or session["finished"]:
        try:
            await q.answer("Game ended. Use /tictoe to start a new one.", show_alert=False)
        except Exception:
            pass
        return

    # Only the original player can interact
    if str(q.from_user.id) != session["uid"]:
        try:
            await q.answer("Not your game!", show_alert=False)
        except Exception:
            pass
        return

    if action == "resign":
        session["finished"] = True
        try:
            await q.edit_message_text(
                _ttt_text(session["uid"], session["board"], "🏳️ You resigned. No progress."),
                reply_markup=_ttt_render_kb(chat_id, session["board"], True),
            )
        except Exception:
            pass
        return

    if action == "move" and len(parts) >= 4:
        try:
            idx = int(parts[3])
        except Exception:
            return
        board = session["board"]
        if idx < 0 or idx > 8 or board[idx] != " ":
            return
        board[idx] = "X"
        winner = _ttt_check_winner(board)
        if winner is None:
            # bot moves
            bm = _ttt_bot_move(board)
            if 0 <= bm <= 8:
                board[bm] = "O"
            winner = _ttt_check_winner(board)

        if winner is None:
            status = "🎮 Your move (❌)."
            try:
                await q.edit_message_text(
                    _ttt_text(session["uid"], board, status),
                    reply_markup=_ttt_render_kb(chat_id, board, False),
                )
            except Exception:
                pass
            return

        # Game over
        session["finished"] = True
        if winner == "X":
            _ad_add_progress(session["uid"], "tictactoe", 1)
            status = "🏆 𝗬𝗢𝗨 𝗪𝗜𝗡! Progress +1"
        elif winner == "O":
            status = "💀 You lost. Draws/losses don't count."
        else:
            status = "🤝 Draw. Draws don't count."
        try:
            await q.edit_message_text(
                _ttt_text(session["uid"], board, status),
                reply_markup=_ttt_render_kb(chat_id, board, True),
            )
        except Exception:
            pass
        return


