# 💎  /diamond  —  Diamond Hunt (5 mystery boxes, some contain diamond)
# ═══════════════════════════════════════════════════════════════════════
def _diamond_new_round() -> dict:
    # 2-3 diamond boxes hidden among 5
    n_dia = _addon_random.choice([2, 3])
    positions = list(range(5))
    _addon_random.shuffle(positions)
    diamond_set = set(positions[:n_dia])
    return {"opened": set(), "diamonds": diamond_set, "ended": False}


def _diamond_kb(session_id: int, sess: dict) -> _AdKb:
    rows = []
    for r in range(0, 5, 5):  # one row of 5
        row = []
        for i in range(5):
            opened = i in sess["opened"]
            if opened:
                is_dia = i in sess["diamonds"]
                label = "💎" if is_dia else "💀"
                row.append(_AdBtn(label, callback_data="dia|nop"))
            else:
                row.append(_AdBtn(f"🎁 {i+1}", callback_data=f"dia|open|{session_id}|{i}"))
        rows.append(row)
    if sess["ended"]:
        rows.append([_AdBtn("🔁 Hunt Again", callback_data=f"dia|new|{session_id}"),
                     _AdBtn("📋 Missions", callback_data="adm|refresh_daily")])
    return _AdKb(rows)


def _diamond_text(uid: str, sess: dict, last_msg: str = "") -> str:
    u = _ms_user(uid)
    cur = int(u["daily"]["progress"].get("diamond_hunt", 0))
    tgt = _AD_DAILY_TARGETS["diamond_hunt"]
    return (
        "╔════════════════════╗\n"
        "     💎  DIAMOND HUNT  💎\n"
        "╚════════════════════╝\n\n"
        "Pick a Mystery Box. Find a 💎 to score a point.\n"
        f"{last_msg}\n"
        f"💎 Diamond Hunt  ({cur}/{tgt})\n"
        f"   {_ad_progress_bar(cur, tgt)}"
    )


async def diamond_cmd(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not update.message:
        return
    uid = str(user.id)
    if not _ad_check_spam(uid):
        await update.message.reply_text("⏳ Cooldown… please wait a moment.")
        return
    _ad_ensure_daily_started(uid)
    u = _ms_user(uid)
    cur = int(u["daily"]["progress"].get("diamond_hunt", 0))
    tgt = _AD_DAILY_TARGETS["diamond_hunt"]
    if cur >= tgt:
        await update.message.reply_text(f"💎 Diamond Hunt already complete ({cur}/{tgt}) ✅")
        return

    chat_id = update.message.chat_id
    sess = _diamond_new_round()
    sess["uid"] = uid
    _ADDON_DIAMOND_SESSIONS[chat_id] = sess
    await update.message.reply_text(
        _diamond_text(uid, sess, ""),
        reply_markup=_diamond_kb(chat_id, sess),
    )


async def _diamond_callback(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    q = update.callback_query
    if not q:
        return
    try:
        await q.answer()
    except Exception:
        pass
    parts = (q.data or "").split("|")
    if len(parts) < 2:
        return
    action = parts[1]
    chat_id = q.message.chat_id

    if action == "nop":
        return

    if action == "new":
        uid = str(q.from_user.id)
        _ad_ensure_daily_started(uid)
        u = _ms_user(uid)
        cur = int(u["daily"]["progress"].get("diamond_hunt", 0))
        tgt = _AD_DAILY_TARGETS["diamond_hunt"]
        if cur >= tgt:
            try:
                await q.edit_message_text(f"💎 Diamond Hunt already complete ({cur}/{tgt}) ✅")
            except Exception:
                pass
            return
        sess = _diamond_new_round()
        sess["uid"] = uid
        _ADDON_DIAMOND_SESSIONS[chat_id] = sess
        try:
            await q.edit_message_text(
                _diamond_text(uid, sess, ""),
                reply_markup=_diamond_kb(chat_id, sess),
            )
        except Exception:
            pass
        return

    sess = _ADDON_DIAMOND_SESSIONS.get(chat_id)
    if not sess or sess["ended"]:
        try:
            await q.answer("Round ended. Use /diamond to play again.", show_alert=False)
        except Exception:
            pass
        return

    if str(q.from_user.id) != sess.get("uid"):
        try:
            await q.answer("Not your game!", show_alert=False)
        except Exception:
            pass
        return

    if action == "open" and len(parts) >= 4:
        try:
            idx = int(parts[3])
        except Exception:
            return
        if idx in sess["opened"]:
            return
        sess["opened"].add(idx)
        is_dia = idx in sess["diamonds"]
        if is_dia:
            _ad_add_progress(sess["uid"], "diamond_hunt", 1)
            sess["ended"] = True
            msg = f"\n💎 𝗗𝗶𝗮𝗺𝗼𝗻𝗱 𝗙𝗼𝘂𝗻𝗱! Progress +1\n"
        else:
            sess["ended"] = True
            msg = f"\n💀 𝗘𝗺𝗽𝘁𝘆 𝗕𝗼𝘅. Try again next round.\n"
        try:
            await q.edit_message_text(
                _diamond_text(sess["uid"], sess, msg),
                reply_markup=_diamond_kb(chat_id, sess),
            )
        except Exception:
            pass
        return


