# 🔁  Inline "play again" buttons for games
# ═══════════════════════════════════════════════════════════════════════
async def _adgame_callback(update: _AdUpdate, context: _AdCtx.DEFAULT_TYPE):
    q = update.callback_query
    if not q:
        return
    try:
        await q.answer()
    except Exception:
        pass
    parts = (q.data or "").split("|")
    if len(parts) < 2:
        return
    game = parts[1]

    # Build a fake update message so we can re-use the cmd handlers
    fake_msg = q.message
    if not fake_msg:
        return

    class _F:
        message = fake_msg
        effective_user = q.from_user
    fake_update = _F()
    # Attach .message.reply_text alias since handlers call update.message.reply_text
    if game == "mbattle":
        await mbattle_cmd(fake_update, context)
    elif game == "afight":
        await afight_cmd(fake_update, context)


# ═══════════════════════════════════════════════════════════════════════
# 🛠  Registration  +  override original /start handler
# ═══════════════════════════════════════════════════════════════════════
def _ad_register(application):
    # Premium /start is now handled directly by the original `start` handler
    # registered in main() — no extra group=10 handler is needed (and adding
    # one would cause the welcome message to be sent twice).
    # (kept here intentionally as a no-op for backward compatibility)
    _ad_premium_start  # reference only, no extra handler registered
    # Owner commands
    application.add_handler(_AdCmd('setwcl',  setwcl_cmd))
    application.add_handler(_AdCmd('sethelp', sethelp_cmd))

    # Daily-mission game commands
    application.add_handler(_AdCmd('mbattle', mbattle_cmd))
    application.add_handler(_AdCmd('afight',  afight_cmd))
    application.add_handler(_AdCmd('tictoe',  tictoe_cmd))
    application.add_handler(_AdCmd('mtask',   mtask_cmd))
    application.add_handler(_AdCmd('diamond', diamond_cmd))

    # Callback handlers (specific patterns first)
    application.add_handler(_AdCbq(_ad_psui_callback,        pattern=r"^psui\|"))
    application.add_handler(_AdCbq(_ad_mission_extra_callback, pattern=r"^adm\|"))
    application.add_handler(_AdCbq(_ttt_callback,            pattern=r"^ttt\|"))
    application.add_handler(_AdCbq(_diamond_callback,        pattern=r"^dia\|"))
    application.add_handler(_AdCbq(_mtask_callback,          pattern=r"^mtask\|"))
    application.add_handler(_AdCbq(_adgame_callback,         pattern=r"^adgame\|"))

    try:
        logger.info("[premium-addon] ✅  Start UI + Daily Mission games registered")
    except Exception:
        pass


# Wrap main() once so our handlers get attached after everything else
def _ad_install_wrapper():
    g = globals()
    cur_main = g.get("main")
    if not callable(cur_main) or getattr(cur_main, "_ad_wrapped", False):
        return

    def wrapped_main(*a, **kw):
        from telegram.ext import Application as _AdApp
        orig_build = _AdApp.builder().__class__.build

        def patched_build(self, *aa, **kk):
            app_obj = orig_build(self, *aa, **kk)
            try:
                _ad_register(app_obj)
            except Exception as e:
                try:
                    logger.error(f"[premium-addon] register failed: {e}")
                except Exception:
                    pass
            _AdApp.builder().__class__.build = orig_build
            return app_obj

        _AdApp.builder().__class__.build = patched_build
        return cur_main(*a, **kw)

    wrapped_main._ad_wrapped = True
    g["main"] = wrapped_main


_ad_install_wrapper()

