import asyncio as _ov_asyncio
import time    as _ov_time
import logging as _ov_logging

from telegram import (
    Update                as _OvUpdate,
    InlineKeyboardButton  as _OvBtn,
    InlineKeyboardMarkup  as _OvKb,
)
from telegram.ext import (
    CommandHandler        as _OvCmd,
    CallbackQueryHandler  as _OvCbq,
    ContextTypes          as _OvCtx,
)

_ov_logger = _ov_logging.getLogger(__name__)


# ───────────────────────────────────────────────────────────────────────
# 1️⃣  PREMIUM /start UI  (Welcome Video/Photo + Caption + Inline Buttons)
# ───────────────────────────────────────────────────────────────────────
# The original `start` function has been upgraded to the Premium UI in
# place, and the add-on group=10 handler (_ad_premium_start) is now made
# a thin redirect to it so only ONE welcome message is sent per /start.
try:
    _ov_original_start = globals().get("start")
    if callable(_ov_original_start):
        async def _ad_premium_start(update, context):   # noqa: F811  (re-bind)
            try:
                return await _ov_original_start(update, context)
            except Exception as e:
                _ov_logger.error(f"[premium-start] redirect failed: {e}")
        globals()["_ad_premium_start"] = _ad_premium_start
except Exception as e:
    _ov_logger.error(f"[premium-start] bind failed: {e}")


# ───────────────────────────────────────────────────────────────────────
# 2️⃣  MISSION CLAIM REWARD  →  SYSTEM NOTICE UI  →  Inventory reveal
# ───────────────────────────────────────────────────────────────────────
# Behaviour:
#   • On Claim: silently add cards to inventory + store "pending reveal"
#     reward list per user.
#   • Show SYSTEM NOTICE (🎁 REWARD RECEIVED) with two inline buttons:
#         [📦 Inventory]   [📋 Missions]
#   • 📦 Inventory  → reveals latest reward (photo/video + caption).
#   • 📋 Missions  → re-opens Mission Center (uses existing missions_cmd
#                    flow, no rewards shown).
# ───────────────────────────────────────────────────────────────────────

# ❶ per-user "last reward bundle" cache (in-memory; survives within run).
_OV_LAST_REWARDS: dict = {}      # uid -> list[card_id]
_OV_LAST_TIER:    dict = {}      # uid -> tier name ("daily"/"weekly"/"monthly")


def _ov_rarity_display(card: dict) -> str:
    try:
        rk = str(card.get("rarity", "1"))
        info = RARITIES.get(rk, RARITIES.get("1", {"display": "💮 Common"}))
        return info.get("display", rk)
    except Exception:
        return "💮 Common"


def _ov_card_role(card: dict) -> str:
    for k in ("role", "Role", "anime", "Anime", "category"):
        v = card.get(k) if isinstance(card, dict) else None
        if v:
            return str(v)
    return "—"


async def _ov_silent_add_rewards(uid: str, tier: str) -> list:
    """
    Pick REWARD_CARDS_PER_CLAIM random cards, add to inventory silently.
    Returns the list of card ids that were added.
    """
    pool = REWARD_POOLS.get(tier, ["3", "4", "5"])
    bot.data.setdefault("users", {})
    bot.data["users"].setdefault(uid, [])

    added: list = []
    for _ in range(REWARD_CARDS_PER_CLAIM):
        try:
            cid = _ms_random_card_id(pool)
        except Exception:
            cid = None
        if not cid:
            continue
        if cid not in bot.data.get("cards", {}):
            continue
        bot.data["users"][uid].append(cid)
        added.append(cid)

    try:
        bot.save_data()
    except Exception:
        pass

    # higher-tier counter bump (collect_cards)
    try:
        mission_progress_add(uid, "collect_cards", len(added))
    except Exception:
        pass

    return added


