async def _ov_show_system_notice(query_or_update, context, uid: str, tier: str):
    """Replace the immediate card-spam with the SYSTEM NOTICE UI."""
    # silently add cards
    added = await _ov_silent_add_rewards(uid, tier)
    _OV_LAST_REWARDS[uid] = added
    _OV_LAST_TIER[uid]    = tier

    chat_id = None
    try:
        if hasattr(query_or_update, "message") and query_or_update.message:
            chat_id = query_or_update.message.chat_id
        elif hasattr(query_or_update, "effective_chat"):
            chat_id = query_or_update.effective_chat.id
    except Exception:
        pass
    if chat_id is None:
        return

    try:
        await context.bot.send_message(
            chat_id=chat_id,
            text=_ov_system_notice_text(),
            reply_markup=_ov_system_notice_kb(),
        )
    except Exception as e:
        _ov_logger.error(f"[override-claim] notice send failed: {e}")


