globals()["_ms_deliver_reward_cards"] = _ms_deliver_reward_cards


# ── Callback handler for the SYSTEM NOTICE buttons
async def _ov_reward_callback(update: _OvUpdate, context: _OvCtx.DEFAULT_TYPE):
    q = update.callback_query
    if not q:
        return
    try:
        await q.answer()
    except Exception:
        pass

    parts = (q.data or "").split("|")
    if len(parts) < 2:
        return
    action = parts[1]
    user = q.from_user
    uid = str(user.id)
    chat_id = q.message.chat_id if q.message else None
    if chat_id is None:
        return

    # ── 📦 INVENTORY — reveal latest reward (photo/video + caption)
    if action == "inv":
        cards_added = _OV_LAST_REWARDS.get(uid, [])
        tier_name   = _OV_LAST_TIER.get(uid, "daily")

        if not cards_added:
            try:
                await context.bot.send_message(
                    chat_id=chat_id,
                    text=(
                        "╔════════════════════╗\n"
                        "      📦 INVENTORY\n"
                        "╚════════════════════╝\n\n"
                        "ℹ️ No recent rewards to reveal.\n"
                        "Use /missions to view your missions."
                    ),
                )
            except Exception:
                pass
            return

        # Header
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=(
                    "╔════════════════════╗\n"
                    "      📦 INVENTORY\n"
                    "╚════════════════════╝\n\n"
                    f"🎁 Recent Rewards ({len(cards_added)})\n"
                    f"🏷  Tier: {tier_name.title()}\n\n"
                    "━━━━━━━━━━━━━━━━"
                ),
            )
        except Exception:
            pass

        # Reveal each card
        cards_all = bot.data.get("cards", {})
        for idx, cid in enumerate(cards_added, 1):
            card = cards_all.get(str(cid)) or cards_all.get(cid)
            if not card:
                continue
            cname  = card.get("name", "Unknown")
            rarity = _ov_rarity_display(card)
            role   = _ov_card_role(card)
            caption = (
                "╔════════════════════╗\n"
                "      📦 INVENTORY\n"
                "╚════════════════════╝\n\n"
                "🎁 Recent Reward\n\n"
                f"📛 Name: {cname}\n"
                f"⭐ Rarity: {rarity}\n"
                f"🎭 Role: {role}\n\n"
                "━━━━━━━━━━━━━━━━\n"
                f"({idx}/{len(cards_added)})"
            )
            try:
                if card.get("type") == "video" or card.get("video"):
                    vid = card.get("video") or card.get("video_url")
                    if vid:
                        if card.get("video_type") == "video":
                            await context.bot.send_video(
                                chat_id=chat_id, video=vid, caption=caption
                            )
                        else:
                            await context.bot.send_document(
                                chat_id=chat_id, document=vid, caption=caption
                            )
                    else:
                        await context.bot.send_message(chat_id=chat_id, text=caption)
                else:
                    img = card.get("image") or card.get("photo") or card.get("photo_url")
                    if img:
                        await context.bot.send_photo(
                            chat_id=chat_id, photo=img, caption=caption
                        )
                    else:
                        await context.bot.send_message(chat_id=chat_id, text=caption)
            except Exception as e:
                _ov_logger.warning(f"[override-claim] reveal failed: {e}")
                try:
                    await context.bot.send_message(chat_id=chat_id, text=caption)
                except Exception:
                    pass
            # tiny pacing so Telegram doesn't choke on 10 quick sends
            try:
                await _ov_asyncio.sleep(0.15)
            except Exception:
                pass
        return

    # ── 📋 MISSIONS — open mission menu only (no rewards shown)
    if action == "missions":
        try:
            _ms_check_reset(uid)
            _ms_user(uid)
            text = _ms_center_text(uid)
            await context.bot.send_message(
                chat_id=chat_id,
                text=text,
                reply_markup=_ms_center_kb(),
            )
        except Exception:
            try:
                await context.bot.send_message(
                    chat_id=chat_id,
                    text="📋 Use /missions to open the Mission Center.",
                )
            except Exception:
                pass
        return


# ───────────────────────────────────────────────────────────────────────
# 3️⃣  FAST ASYNC /broadcast  (batched, parallel, 10k–100k users)
# ───────────────────────────────────────────────────────────────────────
_OV_BC_BATCH_SIZE   = 25       # users per batch
_OV_BC_BATCH_DELAY  = 0.5      # seconds between batches (rate-limit safe)
_OV_BC_PROGRESS_EVERY = 5      # update progress message every N batches
_OV_BC_LOCK = _ov_asyncio.Lock()  # prevent overlapping broadcasts


async def _ov_send_one(bot_obj, chat_id, *, forward_from=None, forward_mid=None,
                       text=None) -> bool:
    """Send a single message; return True if success, False on any error."""
    try:
        if forward_from is not None and forward_mid is not None:
            await bot_obj.forward_message(
                chat_id=chat_id,
                from_chat_id=forward_from,
                message_id=forward_mid,
            )
        else:
            await bot_obj.send_message(chat_id=chat_id, text=text)
        return True
    except Exception:
        return False


async def _ov_broadcast_batch(bot_obj, ids: list, **kw) -> tuple:
    """Send a batch of messages in parallel. Returns (ok, fail)."""
    if not ids:
        return 0, 0
    tasks = [_ov_send_one(bot_obj, int(cid), **kw) for cid in ids]
    results = await _ov_asyncio.gather(*tasks, return_exceptions=True)
    ok = sum(1 for r in results if r is True)
    fail = len(results) - ok
    return ok, fail


def _ov_progress_text(label: str, done: int, total: int,
                      ok: int, fail: int) -> str:
    pct = (done / total * 100.0) if total else 100.0
    bar_w = 14
    filled = int(round((done / total) * bar_w)) if total else bar_w
    bar = "▰" * filled + "▱" * (bar_w - filled)
    return (
        f"📡  BROADCASTING ({label})\n"
        f"━━━━━━━━━━━━━━━━\n"
        f"{bar}  {pct:5.1f}%\n\n"
        f"📦 Sent:      {done:,} / {total:,}\n"
        f"✅ Success:   {ok:,}\n"
        f"❌ Failed:    {fail:,}\n"
        f"━━━━━━━━━━━━━━━━"
    )


async def _ov_broadcast_to_list(context, chat_ids: list, label: str,
                                progress_msg, *, forward_from=None,
                                forward_mid=None, text=None) -> tuple:
    """Broadcast to a list of chat IDs in async batches with progress updates."""
    total = len(chat_ids)
    if total == 0:
        return 0, 0

    ok_total = 0
    fail_total = 0
    done = 0
    batch_n = 0

    for i in range(0, total, _OV_BC_BATCH_SIZE):
        batch = chat_ids[i:i + _OV_BC_BATCH_SIZE]
        b_ok, b_fail = await _ov_broadcast_batch(
            context.bot, batch,
            forward_from=forward_from, forward_mid=forward_mid, text=text,
        )
        ok_total   += b_ok
        fail_total += b_fail
        done       += len(batch)
        batch_n    += 1

        # update progress
        if progress_msg and (batch_n % _OV_BC_PROGRESS_EVERY == 0 or done >= total):
            try:
                await progress_msg.edit_text(
                    _ov_progress_text(label, done, total, ok_total, fail_total)
                )
            except Exception:
                pass

        # rate-limit cooldown between batches
        if done < total:
            try:
                await _ov_asyncio.sleep(_OV_BC_BATCH_DELAY)
            except Exception:
                pass

    return ok_total, fail_total


async def broadcast_cmd(update: _OvUpdate, context: _OvCtx.DEFAULT_TYPE):   # noqa: F811
    """
    Fast async /broadcast — batched parallel sending with progress.

    Modes:
      /broadcast <message>            → plain text broadcast
      /broadcast  (reply to a msg)    → forwards that message
    """
    user = update.effective_user
    if not user:
        return
    # Admin / Owner / Sudo / Dev only
    try:
        if not (bot.is_owner(user.id) or bot.is_sudo(user.id) or bot.is_dev(user.id)):
            await update.message.reply_text("❌ Owner / Sudo / Dev only")
            return
    except Exception:
        await update.message.reply_text("❌ Admin only")
        return

    # Prevent overlapping broadcasts
    if _OV_BC_LOCK.locked():
        await update.message.reply_text(
            "⚠️ Another broadcast is already in progress. Please wait."
        )
        return

    # Build target lists from cache once (fast even for 100k users)
    groups = list((bot.data.get("group_counters") or {}).keys())
    users  = list((bot.data.get("users")          or {}).keys())

    if not groups and not users:
        await update.message.reply_text("❌ No groups/users found.")
        return

    # Determine mode
    reply_msg = update.message.reply_to_message if update.message else None
    text_arg  = " ".join(context.args) if context.args else ""

    forward_from = None
    forward_mid  = None
    bc_text      = None

    if reply_msg:
        forward_from = update.effective_chat.id
        forward_mid  = reply_msg.message_id
        mode_label   = "Forward"
    elif text_arg.strip():
        bc_text     = f"📢 Broadcast:\n\n{text_arg}"
        mode_label  = "Text"
    else:
        await update.message.reply_text(
            "📝 Usage:\n"
            "  /broadcast <message>\n"
            "  /broadcast  (reply to a message to forward it)"
        )
        return

    async with _OV_BC_LOCK:
        # Initial progress message
        progress_msg = None
        try:
            progress_msg = await update.message.reply_text(
                f"🚀 Starting broadcast…\n"
                f"━━━━━━━━━━━━━━━━\n"
                f"Mode:   {mode_label}\n"
                f"Groups: {len(groups):,}\n"
                f"Users:  {len(users):,}\n"
                f"Batch:  {_OV_BC_BATCH_SIZE} • Delay {_OV_BC_BATCH_DELAY}s\n"
                f"━━━━━━━━━━━━━━━━"
            )
        except Exception:
            progress_msg = None

        start_ts = _ov_time.time()

        # ── Groups
        g_ok, g_fail = await _ov_broadcast_to_list(
            context, groups, "Groups", progress_msg,
            forward_from=forward_from, forward_mid=forward_mid, text=bc_text,
        )

        # ── Users
        u_ok, u_fail = await _ov_broadcast_to_list(
            context, users, "Users", progress_msg,
            forward_from=forward_from, forward_mid=forward_mid, text=bc_text,
        )

        elapsed = _ov_time.time() - start_ts
        total_ok   = g_ok + u_ok
        total_fail = g_fail + u_fail
        total_all  = len(groups) + len(users)

        summary = (
            "╔════════════════════╗\n"
            "    ✅ BROADCAST DONE\n"
            "╚════════════════════╝\n\n"
            f"📊  Groups\n"
            f"   ✅ Success: {g_ok:,}\n"
            f"   ❌ Failed:  {g_fail:,}\n\n"
            f"👥  Users\n"
            f"   ✅ Success: {u_ok:,}\n"
            f"   ❌ Failed:  {u_fail:,}\n\n"
            "━━━━━━━━━━━━━━━━\n"
            f"📡 Total Sent:    {total_all:,}\n"
            f"✅ Success Rate:  "
            f"{(total_ok / total_all * 100.0) if total_all else 0:.1f}%\n"
            f"⏱  Elapsed:       {elapsed:.1f}s\n"
            f"⚡ Throughput:    "
            f"{(total_all / elapsed) if elapsed > 0 else 0:.1f} msg/s"
        )

        try:
            if progress_msg:
                await progress_msg.edit_text(summary)
            else:
                await update.message.reply_text(summary)
        except Exception:
            try:
                await update.message.reply_text(summary)
            except Exception:
                pass


# Re-bind globally so any prior reference uses the new fast implementation
globals()["broadcast_cmd"] = broadcast_cmd


# ───────────────────────────────────────────────────────────────────────
# 🛠  Register override callback handler (SYSTEM NOTICE buttons)
# ───────────────────────────────────────────────────────────────────────
def _ov_register(application):
    try:
        application.add_handler(
            _OvCbq(_ov_reward_callback, pattern=r"^ovrwd\|")
        )
        _ov_logger.info("[override] ✅ Reward-Notice + Fast-Broadcast installed")
    except Exception as e:
        _ov_logger.error(f"[override] register failed: {e}")


def _ov_install_wrapper():
    g = globals()
    cur_main = g.get("main")
    if not callable(cur_main) or getattr(cur_main, "_ov_wrapped", False):
        return

    def wrapped_main(*a, **kw):
        from telegram.ext import Application as _OvApp
        orig_build = _OvApp.builder().__class__.build

        def patched_build(self, *aa, **kk):
            app_obj = orig_build(self, *aa, **kk)
            try:
                _ov_register(app_obj)
            except Exception as e:
                _ov_logger.error(f"[override] register failed: {e}")
            _OvApp.builder().__class__.build = orig_build
            return app_obj

        _OvApp.builder().__class__.build = patched_build
        return cur_main(*a, **kw)

    wrapped_main._ov_wrapped = True
    g["main"] = wrapped_main


_ov_install_wrapper()

# ═══════════════════════════════════════════════════════════════════════
#  END OF FINAL OVERRIDE PATCH
