# ═══════════════════════════════════════════════════════════════════════
# 📁  settings.json  —  Premium Start Menu persistence mirror
# ═══════════════════════════════════════════════════════════════════════
# Spec requires a settings.json file with these keys:
#   { "welcome_media": "", "welcome_type": "", "help_link": "" }
# We mirror bot.settings into settings.json on every change AND load it on
# startup. This guarantees Restart-safe persistence even if bot_settings.json
# is missing or wiped.
import os       as _ps_os
import json     as _ps_json
import logging  as _ps_logging

_PS_LOG = _ps_logging.getLogger(__name__)
_PS_SETTINGS_FILE = "settings.json"
_PS_KEYS = ("welcome_media", "welcome_type", "help_link")


def _ps_read_file() -> dict:
    try:
        if _ps_os.path.exists(_PS_SETTINGS_FILE):
            with open(_PS_SETTINGS_FILE, "r", encoding="utf-8") as fh:
                d = _ps_json.load(fh) or {}
            return d if isinstance(d, dict) else {}
    except Exception as e:
        _PS_LOG.warning(f"[settings.json] read failed: {e}")
    return {}


def _ps_write_file(data: dict) -> None:
    try:
        # Only persist the 3 spec keys + keep any extras already in file
        payload = {k: "" for k in _PS_KEYS}
        payload.update({k: v for k, v in data.items() if k in _PS_KEYS})
        tmp = _PS_SETTINGS_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            _ps_json.dump(payload, fh, ensure_ascii=False, indent=2)
        _ps_os.replace(tmp, _PS_SETTINGS_FILE)
    except Exception as e:
        _PS_LOG.warning(f"[settings.json] write failed: {e}")


def _ps_sync_to_file() -> None:
    """Mirror current bot.settings -> settings.json"""
    try:
        snap = {k: bot.settings.get(k, "") for k in _PS_KEYS}
        _ps_write_file(snap)
    except Exception as e:
        _PS_LOG.warning(f"[settings.json] sync-to-file failed: {e}")


def _ps_load_from_file() -> None:
    """Load settings.json into bot.settings (file is source of truth on boot if bot.settings empty)."""
    try:
        on_disk = _ps_read_file()
        if not on_disk:
            # Nothing in settings.json yet — seed it from bot.settings
            _ps_sync_to_file()
            return
        changed = False
        for k in _PS_KEYS:
            v = on_disk.get(k, "")
            # Only populate from file when bot.settings has no value yet
            if v and not bot.settings.get(k):
                bot.settings[k] = v
                changed = True
        if changed:
            try:
                bot.save_settings()
            except Exception:
                pass
    except Exception as e:
        _PS_LOG.warning(f"[settings.json] load-from-file failed: {e}")


# Hook into the addon settings setter so every write also touches settings.json
try:
    _ps_original_settings_set = globals().get("_ad_settings_set")
    if callable(_ps_original_settings_set):
        def _ad_settings_set(key, value):   # noqa: F811
            try:
                _ps_original_settings_set(key, value)
            finally:
                if key in _PS_KEYS:
                    _ps_sync_to_file()
        globals()["_ad_settings_set"] = _ad_settings_set
except Exception as e:
    _PS_LOG.warning(f"[settings.json] hook install failed: {e}")


# Load on import so settings are restored before main() runs
try:
    _ps_load_from_file()
    _PS_LOG.info("[settings.json] ✅ Premium Start Menu settings loaded")
except Exception as e:
    _PS_LOG.warning(f"[settings.json] startup load failed: {e}")
# ═══════════════════════════════════════════════════════════════════════


# ═══════════════════════════════════════════════════════════════════════
# 🎴  PREMIUM /buy UPGRADE  +  /rmrole  +  /loan /reloan  +  /give 5000
# ───────────────────────────────────────────────────────────────────────
# This module is APPENDED to the original bot file. It does NOT delete
# or modify any existing code — it only:
#   • REGISTERS NEW HANDLERS that take priority (group=-3) over the old
#     /buy and /give command handlers (the old ones still exist as fallback
#     but the new ones reply first using ApplicationHandlerStop semantics
#     by NOT calling next handler).
#   • Adds new commands: /rmrole /loan /reloan
#   • Hooks into existing main() via the same Application.builder().build()
#     monkey-patch trick already used elsewhere in this file.
#
# ⚠️ Original file behaviour is preserved. If you remove this module,
#     the bot reverts to the previous behaviour automatically.
# ═══════════════════════════════════════════════════════════════════════

import json       as _u_json
import time       as _u_time
import random     as _u_random
import os         as _u_os
import logging    as _u_logging
from datetime import datetime as _u_dt, timedelta as _u_td

from telegram import (
    Update                as _UUpdate,
    InlineKeyboardButton  as _UBtn,
    InlineKeyboardMarkup  as _UKb,
)
from telegram.ext import (
    CommandHandler        as _UCmd,
    CallbackQueryHandler  as _UCbq,
    ContextTypes          as _UCtx,
    Application           as _UApp,
)

_U_LOG = _u_logging.getLogger("upgrade_module")
_U_LOG.setLevel(_u_logging.INFO)


# ═══════════════════════════════════════════════════════════════════════
# 🗄  PERSISTENT STORAGE  —  shop_data.json
#   {
#     "daily": { "<uid>": {"date": "YYYY-MM-DD", "count": 0} },
#     "stats": { "<card_id>": {"buys": 0, "skips": 0, "price": 0} },
#     "loans": { "<uid>": {"amount": 0, "ts": "...", "card_seized": false} }
#   }
# ═══════════════════════════════════════════════════════════════════════
_U_SHOP_FILE = "shop_data.json"
_U_SHOP_CACHE: dict = {"daily": {}, "stats": {}, "loans": {}}


def _u_shop_load():
    global _U_SHOP_CACHE
    try:
        if _u_os.path.exists(_U_SHOP_FILE):
            with open(_U_SHOP_FILE, "r", encoding="utf-8") as fh:
                d = _u_json.load(fh) or {}
            if isinstance(d, dict):
                _U_SHOP_CACHE = {
                    "daily": d.get("daily", {}) or {},
                    "stats": d.get("stats", {}) or {},
                    "loans": d.get("loans", {}) or {},
                }
    except Exception as e:
        _U_LOG.warning(f"[shop_data] load failed: {e}")


def _u_shop_save():
    try:
        tmp = _U_SHOP_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            _u_json.dump(_U_SHOP_CACHE, fh, ensure_ascii=False, indent=2)
        _u_os.replace(tmp, _U_SHOP_FILE)
    except Exception as e:
        _U_LOG.warning(f"[shop_data] save failed: {e}")


_u_shop_load()


# ═══════════════════════════════════════════════════════════════════════
# 📊  DAILY PURCHASE LIMIT  (15 cards / 24h, auto-reset)
# ═══════════════════════════════════════════════════════════════════════
_U_DAILY_LIMIT = 15


def _u_today_key() -> str:
    return _u_dt.now().strftime("%Y-%m-%d")


def _u_get_daily_count(uid: str) -> int:
    rec = _U_SHOP_CACHE["daily"].get(uid)
    if not rec:
        return 0
    if rec.get("date") != _u_today_key():
        # auto-reset
        _U_SHOP_CACHE["daily"][uid] = {"date": _u_today_key(), "count": 0}
        _u_shop_save()
        return 0
    return int(rec.get("count", 0))


def _u_inc_daily_count(uid: str) -> int:
    today = _u_today_key()
    rec = _U_SHOP_CACHE["daily"].get(uid)
    if not rec or rec.get("date") != today:
        rec = {"date": today, "count": 0}
    rec["count"] = int(rec.get("count", 0)) + 1
    _U_SHOP_CACHE["daily"][uid] = rec
    _u_shop_save()
    return rec["count"]


def _u_daily_remaining(uid: str) -> int:
    return max(0, _U_DAILY_LIMIT - _u_get_daily_count(uid))


def _u_seconds_to_reset() -> int:
    now = _u_dt.now()
    tomorrow = (now + _u_td(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    return int((tomorrow - now).total_seconds())


def _u_fmt_remaining_time() -> str:
    secs = _u_seconds_to_reset()
    h = secs // 3600
    m = (secs % 3600) // 60
    return f"{h}h {m}m"


# ═══════════════════════════════════════════════════════════════════════
# 💹  DYNAMIC PRICING  —  prices rise when bought, drift down when skipped
# ═══════════════════════════════════════════════════════════════════════
_U_PRICE_STEP_UP   = 0.10   # +10 % per purchase
_U_PRICE_STEP_DOWN = 0.02   # −2 % drift when shown but skipped
_U_PRICE_MAX_MULT  = 5.0    # cap at 5x base
_U_PRICE_MIN_MULT  = 0.40   # floor at 0.4x base


def _u_base_price_for_card(card: dict) -> int:
    """Base price comes from SHOP_PRICES[rarity]."""
    try:
        rarity = str(card.get("rarity", "1"))
        return int(SHOP_PRICES.get(rarity, {}).get("price", 1000))
    except Exception:
        return 1000


def _u_get_stats(card_id: str, card: dict) -> dict:
    s = _U_SHOP_CACHE["stats"].get(card_id)
    if not s:
        s = {"buys": 0, "skips": 0, "price": _u_base_price_for_card(card)}
        _U_SHOP_CACHE["stats"][card_id] = s
    return s


def _u_current_price(card_id: str, card: dict) -> int:
    s = _u_get_stats(card_id, card)
    price = int(s.get("price") or _u_base_price_for_card(card))
    return max(1, price)


def _u_apply_buy_price_up(card_id: str, card: dict):
    s = _u_get_stats(card_id, card)
    base = _u_base_price_for_card(card)
    new_price = int(s["price"] * (1.0 + _U_PRICE_STEP_UP))
    new_price = min(new_price, int(base * _U_PRICE_MAX_MULT))
    s["price"] = max(1, new_price)
    s["buys"] = int(s.get("buys", 0)) + 1
    _u_shop_save()


def _u_apply_skip_price_down(card_id: str, card: dict):
    s = _u_get_stats(card_id, card)
    base = _u_base_price_for_card(card)
    new_price = int(s["price"] * (1.0 - _U_PRICE_STEP_DOWN))
    new_price = max(new_price, int(base * _U_PRICE_MIN_MULT))
    s["price"] = max(1, new_price)
    s["skips"] = int(s.get("skips", 0)) + 1
    _u_shop_save()


# ═══════════════════════════════════════════════════════════════════════
# 🎴  PREMIUM /buy  UI
# ═══════════════════════════════════════════════════════════════════════
# Browse session in-memory: per-user current rarity & index
# Key: (chat_id, message_id)  ->  {"uid": "...", "rarity": "5", "cards": [ids], "idx": 0, "shown": set()}
_U_BROWSE: dict = {}


def _u_pool_for_rarity(rarity: str) -> list:
    """All non-hidden cards of given rarity, sorted by id for stable nav."""
    pool = []
    try:
        for cid, card in bot.data.get("cards", {}).items():
            if not card:
                continue
            if str(card.get("rarity")) != str(rarity):
                continue
            if card.get("hidden"):
                continue
            pool.append(cid)
    except Exception:
        pass
    # stable sort by numeric id when possible
    def _k(x):
        try: return (0, int(x))
        except: return (1, str(x))
    pool.sort(key=_k)
    return pool


def _u_build_card_caption(card: dict, card_id: str, price: int, balance: int,
                         remaining_today: int, total: int, idx: int) -> str:
    """Premium Product Card text."""
    try:
        rarity_key = str(card.get("rarity", "1"))
        rarity_info = RARITIES.get(rarity_key, RARITIES["1"])
        role_info = get_role_info(card)
    except Exception:
        rarity_info = {"display": "💮 Common"}
        role_info = {"display": "🎴 Normal"}

    name = card.get("name") or "Unknown"
    movie = card.get("movie") or "—"
    cid = card.get("id") or card_id
    desc = card.get("description") or movie

    lines = [
        "╔══ 🛒 𝗣𝗥𝗘𝗠𝗜𝗨𝗠 𝗦𝗛𝗢𝗣 ══╗",
        f"🎴 {name}",
        f"🆔 Card #: {cid}",
        f"⭐ {rarity_info['display']}",
        f"🎭 {role_info['display']}",
        f"🎬 {movie}",
        "─" * 22,
        f"💰 Required : {price:,} Coins",
        f"🪙 Balance  : {balance:,} Coins",
        "─" * 22,
        f"📦 Page {idx + 1} / {total}",
        f"📅 Today bought : {_U_DAILY_LIMIT - remaining_today}/{_U_DAILY_LIMIT}",
        f"📝 {desc}",
        "╚══════════════════╝",
    ]
    return "\n".join(lines)


def _u_build_browse_keyboard(card_id: str, idx: int, total: int, can_buy: bool) -> _UKb:
    rows = []
    # Nav row
    nav = []
    if total > 1:
        nav.append(_UBtn("◀️ Back",  callback_data=f"ushop|nav|prev|{card_id}"))
    if can_buy:
        nav.append(_UBtn("🛒 Buy",   callback_data=f"ushop|buy|{card_id}"))
    else:
        nav.append(_UBtn("💵 Buy",   callback_data=f"ushop|nobuy|{card_id}"))
    if total > 1:
        nav.append(_UBtn("▶️ Next",  callback_data=f"ushop|nav|next|{card_id}"))
    rows.append(nav)
    # Close
    rows.append([_UBtn("✖ Close", callback_data=f"ushop|close|{card_id}")])
    return _UKb(rows)


def _u_build_confirm_keyboard(card_id: str) -> _UKb:
    return _UKb([
        [_UBtn("✅ Confirm", callback_data=f"ushop|confirm|{card_id}"),
         _UBtn("❌ Cancel",  callback_data=f"ushop|cancel|{card_id}")],
    ])


async def _u_send_card_view(message_or_query, context, uid: str, rarity: str,
                            cards: list, idx: int, edit: bool):
    """Send or edit a card display. Stores browse state keyed by chat+message id."""
    if not cards:
        if hasattr(message_or_query, "edit_message_text"):
            await message_or_query.edit_message_text("❌ No cards available for this rarity.")
        else:
            await message_or_query.reply_text("❌ No cards available for this rarity.")
        return

    idx = max(0, min(idx, len(cards) - 1))
    card_id = cards[idx]
    card = bot.data["cards"].get(card_id) or {}

    # Init profile/balance
    init_user_if_not_exists(uid)
    profile = bot.data["user_profiles"][uid]
    balance = int(profile.get("coins", 0))
    price = _u_current_price(card_id, card)
    remaining_today = _u_daily_remaining(uid)
    can_buy = (balance >= price) and (remaining_today > 0)

    caption = _u_build_card_caption(card, card_id, price, balance,
                                    remaining_today, len(cards), idx)
    kb = _u_build_browse_keyboard(card_id, idx, len(cards), can_buy)

    # Determine media
    media_kind = "photo"
    media_ref = card.get("image")
    if card.get("type") == "video":
        media_kind = "video" if card.get("video_type") == "video" else "document"
        media_ref = card.get("video")

    sent_msg = None
    try:
        if edit and hasattr(message_or_query, "message") and message_or_query.message:
            # Try to edit caption (for media messages)
            try:
                await message_or_query.edit_message_caption(
                    caption=caption, reply_markup=kb
                )
                sent_msg = message_or_query.message
            except Exception:
                # Fallback: edit_text for plain text messages
                try:
                    await message_or_query.edit_message_text(
                        text=caption, reply_markup=kb
                    )
                    sent_msg = message_or_query.message
                except Exception as e:
                    _U_LOG.warning(f"[ushop] edit fail: {e}")
        else:
            target = message_or_query
            try:
                if media_kind == "photo" and media_ref:
                    sent_msg = await target.reply_photo(
                        photo=media_ref, caption=caption, reply_markup=kb
                    )
                elif media_kind == "video" and media_ref:
                    sent_msg = await target.reply_video(
                        video=media_ref, caption=caption, reply_markup=kb
                    )
                elif media_kind == "document" and media_ref:
                    sent_msg = await target.reply_document(
                        document=media_ref, caption=caption, reply_markup=kb
                    )
                else:
                    sent_msg = await target.reply_text(
                        text=caption, reply_markup=kb
                    )
            except Exception as e:
                _U_LOG.warning(f"[ushop] send media failed -> text fallback: {e}")
                sent_msg = await target.reply_text(text=caption, reply_markup=kb)

    except Exception as e:
        _U_LOG.warning(f"[ushop] send/edit error: {e}")

    # Save browse state
    if sent_msg is not None:
        key = f"{sent_msg.chat_id}:{sent_msg.message_id}"
        _U_BROWSE[key] = {
            "uid": uid,
            "rarity": str(rarity),
            "cards": cards,
            "idx": idx,
        }


# ═══════════════════════════════════════════════════════════════════════
# /buy  ENTRY POINT  (premium UI)
# ═══════════════════════════════════════════════════════════════════════
async def u_buy_cmd(update: _UUpdate, context: _UCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not update.message:
        return
    try:
        if bot.is_gbanned(user.id):
            await update.message.reply_text("❌ You are globally banned.")
            return
    except Exception:
        pass

    if not context.args:
        # Show shop summary
        try:
            await update.message.reply_text(
                "📝 Usage: `/buy <rarity_number>`\n"
                "💡 Example: `/buy 1`, `/buy 5`, `/buy 10`\n\n"
                "📋 Use /shop to see rarity numbers and prices.",
                parse_mode="Markdown",
            )
        except Exception:
            await update.message.reply_text(
                "Usage: /buy <rarity_number>\nExample: /buy 5"
            )
        return

    rarity = context.args[0].strip()
    if rarity not in SHOP_PRICES:
        await update.message.reply_text(
            "❌ Invalid rarity number.\n📋 Use /shop to see available rarities."
        )
        return

    # Block locked rarities
    try:
        locked = bot.settings.get("locked_rarities", []) or []
        if rarity in locked:
            info = RARITIES.get(rarity, RARITIES["1"])
            await update.message.reply_text(
                f"🔒 {info['display']} is currently locked.\n"
                f"❌ Cannot purchase locked rarity cards."
            )
            return
    except Exception:
        pass

    uid = str(user.id)
    cards = _u_pool_for_rarity(rarity)
    if not cards:
        info = RARITIES.get(rarity, RARITIES["1"])
        await update.message.reply_text(
            f"❌ {info['display']} card not available.\n"
            "🔄 Contact admin to add cards."
        )
        return

    await _u_send_card_view(update.message, context, uid, rarity, cards,
                            idx=0, edit=False)


# ═══════════════════════════════════════════════════════════════════════
# /buy  CALLBACK HANDLER  (nav + buy + confirm)
# ═══════════════════════════════════════════════════════════════════════
async def u_buy_callback(update: _UUpdate, context: _UCtx.DEFAULT_TYPE):
    query = update.callback_query
    if not query or not query.data:
        return

    try:
        await query.answer()
    except Exception:
        pass

    parts = query.data.split("|")
    if len(parts) < 2 or parts[0] != "ushop":
        return

    action = parts[1]
    msg = query.message
    if not msg:
        return
    key = f"{msg.chat_id}:{msg.message_id}"
    state = _U_BROWSE.get(key)
    if not state:
        try:
            await query.edit_message_caption(caption="⌛ Session expired. Please send /buy again.")
        except Exception:
            try:
                await query.edit_message_text("⌛ Session expired. Please send /buy again.")
            except Exception:
                pass
        return

    # Lock to original user
    uid = str(update.effective_user.id) if update.effective_user else None
    if uid != state["uid"]:
        try:
            await query.answer("❌ This shop session belongs to another user.", show_alert=True)
        except Exception:
            pass
        return

    cards = state["cards"]
    idx = state["idx"]
    rarity = state["rarity"]

    # ── NAV ──
    if action == "nav" and len(parts) >= 4:
        direction = parts[2]
        # Mark current card as "skipped" (drift price down a bit)
        try:
            cur_id = cards[idx]
            cur_card = bot.data["cards"].get(cur_id) or {}
            _u_apply_skip_price_down(cur_id, cur_card)
        except Exception:
            pass

        if direction == "prev":
            idx = (idx - 1) % len(cards)
        elif direction == "next":
            idx = (idx + 1) % len(cards)
        state["idx"] = idx
        await _u_send_card_view(query, context, uid, rarity, cards,
                                idx=idx, edit=True)
        return

    # ── BUY (open confirm panel) ──
    if action == "buy":
        # Check daily limit
        if _u_daily_remaining(uid) <= 0:
            reset = _u_fmt_remaining_time()
            try:
                await query.answer(
                    f"📅 Daily limit reached (15/15)\n⏳ Resets in {reset}",
                    show_alert=True,
                )
            except Exception:
                pass
            return

        card_id = cards[idx]
        card = bot.data["cards"].get(card_id) or {}
        init_user_if_not_exists(uid)
        balance = int(bot.data["user_profiles"][uid].get("coins", 0))
        price = _u_current_price(card_id, card)
        rarity_info = RARITIES.get(str(card.get("rarity", "1")), RARITIES["1"])

        if balance < price:
            need = price - balance
            text = (
                "❌ 𝗜𝗻𝘀𝘂𝗳𝗳𝗶𝗰𝗶𝗲𝗻𝘁 𝗖𝗼𝗶𝗻𝘀\n\n"
                f"💰 Required : {price:,}\n"
                f"🪙 Your Balance : {balance:,}\n"
                f"📉 Short : {need:,}\n\n"
                "💡 Earn coins: /daily • chat for XP • /interest"
            )
            try:
                await query.edit_message_caption(
                    caption=text,
                    reply_markup=_UKb([[_UBtn("◀️ Back to Shop",
                                              callback_data=f"ushop|back|{card_id}")]]),
                )
            except Exception:
                try:
                    await query.edit_message_text(
                        text=text,
                        reply_markup=_UKb([[_UBtn("◀️ Back to Shop",
                                                  callback_data=f"ushop|back|{card_id}")]]),
                    )
                except Exception:
                    pass
            return

        # Show confirm panel
        confirm_text = (
            "⚠️ 𝗖𝗼𝗻𝗳𝗶𝗿𝗺 𝗣𝘂𝗿𝗰𝗵𝗮𝘀𝗲?\n\n"
            f"🎴 {card.get('name', 'Unknown')} #{card.get('id', card_id)}\n"
            f"⭐ {rarity_info['display']}\n"
            f"💰 Cost : {price:,} Bot Coins\n\n"
            f"🪙 Current Balance : {balance:,}\n"
            f"📅 Daily Remaining : {_u_daily_remaining(uid)}/{_U_DAILY_LIMIT}"
        )
        try:
            await query.edit_message_caption(
                caption=confirm_text,
                reply_markup=_u_build_confirm_keyboard(card_id),
            )
        except Exception:
            try:
                await query.edit_message_text(
                    text=confirm_text,
                    reply_markup=_u_build_confirm_keyboard(card_id),
                )
            except Exception:
                pass
        return

    # ── CANCEL (back to browse) ──
    if action == "cancel" or action == "back":
        await _u_send_card_view(query, context, uid, rarity, cards,
                                idx=idx, edit=True)
        return

    # ── CONFIRM (do purchase) ──
    if action == "confirm":
        card_id = cards[idx]
        card = bot.data["cards"].get(card_id) or {}

        # Re-check daily limit (race-safe)
        if _u_daily_remaining(uid) <= 0:
            try:
                await query.answer(
                    f"📅 Daily limit reached. Resets in {_u_fmt_remaining_time()}",
                    show_alert=True,
                )
            except Exception:
                pass
            return

        init_user_if_not_exists(uid)
        profile = bot.data["user_profiles"][uid]
        price = _u_current_price(card_id, card)
        balance = int(profile.get("coins", 0))
        if balance < price:
            try:
                await query.answer("❌ Insufficient coins.", show_alert=True)
            except Exception:
                pass
            return

        # Deduct coins
        profile["coins"] = balance - price
        # Add to inventory
        bot.data.setdefault("users", {}).setdefault(uid, []).append(card_id)
        # Update card owner
        try:
            bot.data["cards"][card_id]["owner"] = int(uid)
            bot.data["cards"][card_id]["owner_name"] = (
                update.effective_user.first_name if update.effective_user else "?"
            )
        except Exception:
            pass

        # Stats
        _u_apply_buy_price_up(card_id, card)
        _u_inc_daily_count(uid)

        # Transaction log
        try:
            log = bot.data.setdefault("transactions", [])
            log.append({
                "type": "buy",
                "uid": uid,
                "card_id": card_id,
                "price": price,
                "ts": _u_dt.now().isoformat(),
            })
            # Trim to last 2000 entries
            if len(log) > 2000:
                del log[: len(log) - 2000]
        except Exception:
            pass

        try:
            bot.save_data()
        except Exception:
            pass

        rarity_info = RARITIES.get(str(card.get("rarity", "1")), RARITIES["1"])
        new_balance = profile["coins"]
        success_text = (
            "🎉 𝗣𝘂𝗿𝗰𝗵𝗮𝘀𝗲 𝗦𝘂𝗰𝗰𝗲𝘀𝘀𝗳𝘂𝗹!\n\n"
            f"🎴 {card.get('name', '?')} #{card.get('id', card_id)}\n"
            f"⭐ {rarity_info['display']}\n"
            f"💰 Paid : {price:,} Coins\n"
            f"🪙 Remaining : {new_balance:,} Coins\n\n"
            f"📅 Today : {_u_get_daily_count(uid)}/{_U_DAILY_LIMIT}"
        )
        try:
            await query.edit_message_caption(
                caption=success_text,
                reply_markup=_UKb([[_UBtn("🛒 Buy More",
                                          callback_data=f"ushop|back|{card_id}"),
                                    _UBtn("✖ Close",
                                          callback_data=f"ushop|close|{card_id}")]]),
            )
        except Exception:
            try:
                await query.edit_message_text(
                    text=success_text,
                    reply_markup=_UKb([[_UBtn("🛒 Buy More",
                                              callback_data=f"ushop|back|{card_id}"),
                                        _UBtn("✖ Close",
                                              callback_data=f"ushop|close|{card_id}")]]),
                )
            except Exception:
                pass
        return

    # ── CLOSE ──
    if action == "close":
        try:
            await query.edit_message_caption(caption="🛒 Shop closed.")
        except Exception:
            try:
                await query.edit_message_text("🛒 Shop closed.")
            except Exception:
                pass
        try:
            _U_BROWSE.pop(key, None)
        except Exception:
            pass
        return

    # ── NOBUY (info only) ──
    if action == "nobuy":
        if _u_daily_remaining(uid) <= 0:
            msg_txt = f"📅 Daily limit reached. Resets in {_u_fmt_remaining_time()}"
        else:
            msg_txt = "❌ Insufficient coins for this card."
        try:
            await query.answer(msg_txt, show_alert=True)
        except Exception:
            pass
        return


# ═══════════════════════════════════════════════════════════════════════
# 🛠  /rmrole <name>  —  Owner-only: remove a role from the system
# ═══════════════════════════════════════════════════════════════════════
async def u_rmrole_cmd(update: _UUpdate, context: _UCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not update.message:
        return
    try:
        is_owner = bot.is_real_owner(user.id) if hasattr(bot, "is_real_owner") else bot.is_owner(user.id)
    except Exception:
        is_owner = False
    if not is_owner:
        await update.message.reply_text("❌ Owner only")
        return

    if not context.args:
        await update.message.reply_text(
            "📝 Usage: `/rmrole <name>`\n"
            "ဥပမာ: `/rmrole ninja`",
            parse_mode="Markdown",
        )
        return

    raw = context.args[0].strip().lower().replace(" ", "").replace("-", "").replace("_", "")
    # Resolve via alias too
    key = raw if raw in ROLES else ROLE_ALIASES.get(raw)
    if not key or key not in ROLES:
        await update.message.reply_text(
            f"❌ Role `{raw}` not found.\nUse the role's exact name.",
            parse_mode="Markdown",
        )
        return

    # Protect 'normal' default
    if key == "normal":
        await update.message.reply_text("❌ Cannot remove the default `normal` role.",
                                        parse_mode="Markdown")
        return

    removed_info = ROLES.pop(key, None)
    # Clean aliases
    for ak, av in list(ROLE_ALIASES.items()):
        if av == key:
            try:
                del ROLE_ALIASES[ak]
            except Exception:
                pass

    # Persist: remove from custom_roles in settings if present
    try:
        cr = bot.settings.get("custom_roles", {}) or {}
        if key in cr:
            del cr[key]
            bot.settings["custom_roles"] = cr
            bot.save_settings()
    except Exception:
        pass

    # Reset cards that used this role back to 'normal'
    touched = 0
    try:
        for cid, c in bot.data.get("cards", {}).items():
            if not isinstance(c, dict):
                continue
            if str(c.get("role", "")).strip().lower() == key:
                c["role"] = "normal"
                touched += 1
        if touched:
            bot.save_data()
    except Exception:
        pass

    display = (removed_info or {}).get("display", key)
    await update.message.reply_text(
        f"✅ Role removed\n\n"
        f"🗑 {display}\n"
        f"🔑 key: `{key}`\n"
        f"🎴 Cards reset to Normal: {touched}",
        parse_mode="Markdown",
    )


# ═══════════════════════════════════════════════════════════════════════
# 🎁  /give upgrade: max 50  →  max 5000
#     New wrapper command takes priority. Falls back to original semantics.
# ═══════════════════════════════════════════════════════════════════════
_U_GIVE_MAX = 5000


async def u_give_cmd(update: _UUpdate, context: _UCtx.DEFAULT_TYPE):
    """Wrapper that mirrors the original /give but raises the per-call cap
    to _U_GIVE_MAX (5000). Preserves: reply mode, card-id mode, /give <id> <uid> mode.
    """
    if not update.effective_user or not update.message:
        return
    uid = update.effective_user.id
    try:
        if not bot.is_owner(uid):
            await update.message.reply_text("❌ Owner only")
            return
    except Exception:
        await update.message.reply_text("❌ Owner only")
        return

    if not context.args:
        await update.message.reply_text(
            "📝 Usage:\n"
            "• Reply + `/give <amount>`  (random cards, max 5000)\n"
            "• Reply + `/give card <card_id>` (specific card)\n"
            "• `/give <card_id> <user_id>` (specific card)",
            parse_mode="Markdown",
        )
        return

    args = [a.strip() for a in context.args if a.strip()]
    target_user = None
    target_id_str = None
    target_name = None

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        target_user = update.message.reply_to_message.from_user
        target_id_str = str(target_user.id)
        target_name = target_user.first_name
    elif len(args) >= 2 and args[-1].lstrip("-").isdigit():
        target_id_str = args[-1]
        target_name = target_id_str
        args = args[:-1]
    else:
        await update.message.reply_text(
            "❌ Target user မသိ!\n\n"
            "✅ Reply to user + `/give <amount>`\n"
            "or `/give card <card_id>`\n"
            "သို့မဟုတ် `/give <card_id> <user_id>`",
            parse_mode="Markdown",
        )
        return

    init_user_if_not_exists(target_id_str)
    bot.data["users"].setdefault(target_id_str, [])

    mode = None
    amount = 0
    card_id = None

    if len(args) >= 2 and args[0].lower() in ("card", "id"):
        mode = "specific"
        card_id = args[1]
    elif len(args) >= 2 and args[0].lower() in ("random", "rnd", "cards"):
        mode = "random"
        try:
            amount = int(args[1])
        except Exception:
            amount = 0
    else:
        if target_user is not None and len(args) == 1 and args[0].isdigit():
            mode = "random"
            amount = int(args[0])
        else:
            mode = "specific"
            card_id = args[0]

    if mode == "random":
        if amount <= 0:
            await update.message.reply_text("❌ Amount မှန်အောင်ရေးပါ။ ဥပမာ: reply + /give 5")
            return
        if amount > _U_GIVE_MAX:
            await update.message.reply_text(
                f"❌ Maximum {_U_GIVE_MAX:,} cards per command."
            )
            return

        pool = [cid for cid, c in bot.data.get("cards", {}).items() if c]
        if not pool:
            await update.message.reply_text("❌ Card database ထဲမှာ card မရှိသေးပါ")
            return

        given = []
        for _ in range(amount):
            cid = _u_random.choice(pool)
            bot.data["users"][target_id_str].append(cid)
            try:
                bot.data["cards"][cid]["owner"] = (
                    int(target_id_str) if str(target_id_str).lstrip("-").isdigit() else 0
                )
                bot.data["cards"][cid]["owner_name"] = target_name
            except Exception:
                pass
            given.append(cid)

        try:
            bot.save_data()
        except Exception:
            pass

        await update.message.reply_text(
            f"✅ **Random Cards Give လုပ်ပြီးပါပြီ!**\n\n"
            f"👤 To: **{target_name}** (`{target_id_str}`)\n"
            f"🎁 Amount: **{len(given):,}**\n"
            f"📦 Cap: {_U_GIVE_MAX:,}\n"
            f"💡 /harem ဖြင့်ကြည့်ပါ။",
            parse_mode="Markdown",
        )
        return

    # specific
    if not card_id:
        await update.message.reply_text(
            "❌ Card ID မရှိပါ။ /give card <card_id> သို့မဟုတ် /give <card_id> <user_id>"
        )
        return
    if card_id not in bot.data.get("cards", {}):
        await update.message.reply_text(f"❌ Card ID `{card_id}` မတွေ့ပါ", parse_mode="Markdown")
        return

    card = bot.data["cards"][card_id]
    bot.data["users"][target_id_str].append(card_id)
    try:
        bot.data["cards"][card_id]["owner"] = (
            int(target_id_str) if str(target_id_str).lstrip("-").isdigit() else 0
        )
        bot.data["cards"][card_id]["owner_name"] = target_name
    except Exception:
        pass
    try:
        bot.save_data()
    except Exception:
        pass

    rarity = card.get("rarity", "1")
    rarity_info = RARITIES.get(rarity, RARITIES["1"])
    await update.message.reply_text(
        f"✅ **Card Give လုပ်ပြီးပါပြီ!**\n\n"
        f"🎴 **{card.get('name', '?')}**\n"
        f"🎬 {card.get('movie', '?')}\n"
        f"🆔 ID: `{card.get('id', card_id)}`\n"
        f"⭐ {rarity_info['display']}\n"
        f"📥 Received: **{target_name}** (`{target_id_str}`)",
        parse_mode="Markdown",
    )


# ═══════════════════════════════════════════════════════════════════════
# 🏦  /loan <amount>   /reloan
#     Bank loan system. If user doesn't repay, a card equal to loan
#     value is seized when they next call /reloan with insufficient coins,
#     or on /sell etc. — for now, we provide explicit /reloan and a manual
#     /seizeloan helper for the owner.
# ═══════════════════════════════════════════════════════════════════════
_U_LOAN_MAX_PERCENT_OF_BANK = 1.0   # may loan up to 100 % of current bank
_U_LOAN_HARD_CAP = 10_000_000       # never loan more than 10 M per user


def _u_get_loan(uid: str) -> dict:
    return _U_SHOP_CACHE["loans"].get(uid) or {"amount": 0, "ts": None, "card_seized": False}


def _u_set_loan(uid: str, data: dict):
    _U_SHOP_CACHE["loans"][uid] = data
    _u_shop_save()


def _u_clear_loan(uid: str):
    try:
        _U_SHOP_CACHE["loans"].pop(uid, None)
        _u_shop_save()
    except Exception:
        pass


async def u_loan_cmd(update: _UUpdate, context: _UCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not update.message:
        return
    try:
        if bot.is_gbanned(user.id):
            await update.message.reply_text("❌ You are globally banned.")
            return
    except Exception:
        pass

    if not context.args:
        await update.message.reply_text(
            "📝 Usage: `/loan <amount>`\n"
            "🏦 Bank မှ coin ချေးယူရန်။\n"
            "💡 ပြန်မဆပ်ပါက အညီအမျှတန်ဖိုးရှိ card ကို သိမ်းမည်။\n"
            "💰 ပြန်ဆပ်ရန် `/reloan` သုံးပါ။",
            parse_mode="Markdown",
        )
        return

    try:
        amount = int(str(context.args[0]).replace(",", "").strip())
        if amount <= 0:
            raise ValueError
    except Exception:
        await update.message.reply_text("❌ Invalid amount")
        return

    uid = str(user.id)
    init_user_if_not_exists(uid)
    profile = bot.data["user_profiles"][uid]

    # Existing loan?
    cur_loan = _u_get_loan(uid)
    if int(cur_loan.get("amount", 0)) > 0:
        await update.message.reply_text(
            "❌ You already have an active loan.\n\n"
            f"💳 Outstanding : {int(cur_loan['amount']):,} Coins\n"
            f"💡 Repay first using `/reloan`",
            parse_mode="Markdown",
        )
        return

    # Cap
    if amount > _U_LOAN_HARD_CAP:
        await update.message.reply_text(
            f"❌ Maximum single loan is {_U_LOAN_HARD_CAP:,} Coins."
        )
        return

    # Deliver coins immediately
    profile["coins"] = int(profile.get("coins", 0)) + amount
    try:
        bot.save_data()
    except Exception:
        pass

    _u_set_loan(uid, {
        "amount": amount,
        "ts": _u_dt.now().isoformat(),
        "card_seized": False,
    })

    await update.message.reply_text(
        "🏦 𝗟𝗼𝗮𝗻 𝗔𝗽𝗽𝗿𝗼𝘃𝗲𝗱\n\n"
        f"💰 Borrowed : {amount:,} Coins\n"
        f"🪙 New Balance : {int(profile['coins']):,}\n"
        f"💳 Outstanding : {amount:,} Coins\n\n"
        "💡 Repay with /reloan\n"
        "⚠️ မဆပ်ပါက amount ပမာဏနဲ့ညီတဲ့ Card တစ်ကဒ်ကို သိမ်းပါမည်။"
    )


def _u_pick_card_to_seize(uid: str, debt: int) -> str | None:
    """Pick lowest-value card from user inventory whose value ≥ debt;
    if none, pick the most valuable card they own.
    Returns card_id or None.
    """
    inv = bot.data.get("users", {}).get(uid, []) or []
    if not inv:
        return None

    candidates = []
    for cid in inv:
        c = bot.data.get("cards", {}).get(cid)
        if not c:
            continue
        try:
            r = str(c.get("rarity", "1"))
            v = int(RARITIES.get(r, {}).get("value", 0)) * 100  # value*100 ≈ coin worth
        except Exception:
            v = 0
        candidates.append((v, cid))
    if not candidates:
        return None

    candidates.sort()
    # try cheapest card ≥ debt
    for v, cid in candidates:
        if v >= debt:
            return cid
    # else seize most valuable
    return candidates[-1][1]


async def u_reloan_cmd(update: _UUpdate, context: _UCtx.DEFAULT_TYPE):
    user = update.effective_user
    if not user or not update.message:
        return

    uid = str(user.id)
    init_user_if_not_exists(uid)
    profile = bot.data["user_profiles"][uid]

    cur_loan = _u_get_loan(uid)
    debt = int(cur_loan.get("amount", 0))
    if debt <= 0:
        await update.message.reply_text("✅ You have no outstanding loan.")
        return

    balance = int(profile.get("coins", 0))

    if balance >= debt:
        profile["coins"] = balance - debt
        try:
            bot.save_data()
        except Exception:
            pass
        _u_clear_loan(uid)
        await update.message.reply_text(
            "✅ 𝗟𝗼𝗮𝗻 𝗥𝗲𝗽𝗮𝗶𝗱\n\n"
            f"💸 Paid : {debt:,} Coins\n"
            f"🪙 Remaining : {int(profile['coins']):,}\n"
            f"💳 Outstanding : 0"
        )
        return

    # Cannot repay → seize a card
    cid = _u_pick_card_to_seize(uid, debt)
    if not cid:
        await update.message.reply_text(
            "❌ Insufficient coins and no card to seize.\n\n"
            f"💳 Debt : {debt:,}\n"
            f"🪙 Balance : {balance:,}\n"
            "💡 Earn more coins and try /reloan again."
        )
        return

    card = bot.data["cards"].get(cid) or {}
    rarity_info = RARITIES.get(str(card.get("rarity", "1")), RARITIES["1"])

    # Remove from inventory
    try:
        bot.data["users"][uid].remove(cid)
    except Exception:
        pass
    # Reset card owner
    try:
        bot.data["cards"][cid]["owner"] = 0
        bot.data["cards"][cid]["owner_name"] = None
    except Exception:
        pass
    try:
        bot.save_data()
    except Exception:
        pass

    _u_clear_loan(uid)

    await update.message.reply_text(
        "⚠️ 𝗖𝗮𝗿𝗱 𝗦𝗲𝗶𝘇𝗲𝗱 — 𝗟𝗼𝗮𝗻 𝗦𝗲𝘁𝘁𝗹𝗲𝗱\n\n"
        f"💳 Debt : {debt:,} Coins\n"
        f"🪙 Balance : {balance:,}\n\n"
        f"🗑 Seized: {card.get('name', '?')} #{card.get('id', cid)}\n"
        f"⭐ {rarity_info['display']}\n\n"
        "✅ Loan cleared."
    )


# ═══════════════════════════════════════════════════════════════════════
# 🧩  REGISTER  —  monkey-patch Application.builder().build()
# ═══════════════════════════════════════════════════════════════════════
def _u_register_handlers(application):
    # Group=-3 → runs BEFORE the original /buy and /give CommandHandlers
    try:
        application.add_handler(_UCmd("buy",     u_buy_cmd),     group=-3)
        application.add_handler(_UCmd("give",    u_give_cmd),    group=-3)
        application.add_handler(_UCmd("rmrole",  u_rmrole_cmd),  group=-3)
        application.add_handler(_UCmd("loan",    u_loan_cmd),    group=-3)
        application.add_handler(_UCmd("reloan",  u_reloan_cmd),  group=-3)
        application.add_handler(
            _UCbq(u_buy_callback, pattern=r"^ushop\|"),
            group=-3,
        )
        try:
            logger.info("[upgrade] ✅ Premium /buy + /rmrole + /loan/reloan + /give-5000 registered")
        except Exception:
            pass
    except Exception as e:
        try:
            logger.error(f"[upgrade] register failed: {e}")
        except Exception:
            pass


def _u_install_main_wrapper():
    g = globals()
    orig_main = g.get("main")
    if not callable(orig_main) or getattr(orig_main, "_u_wrapped", False):
        return

    def wrapped_main():
        from telegram.ext import Application as _UMS_App
        orig_build = _UMS_App.builder().__class__.build

        def patched_build(self, *a, **kw):
            app_obj = orig_build(self, *a, **kw)
            try:
                _u_register_handlers(app_obj)
            except Exception as e:
                try:
                    logger.error(f"[upgrade] register-in-build failed: {e}")
                except Exception:
                    pass
            _UMS_App.builder().__class__.build = orig_build
            return app_obj

        _UMS_App.builder().__class__.build = patched_build
        return orig_main()

    wrapped_main._u_wrapped = True
    g["main"] = wrapped_main


_u_install_main_wrapper()
# ═══════════════════════════════════════════════════════════════════════
#  END  PREMIUM /buy  UPGRADE  MODULE
# ═══════════════════════════════════════════════════════════════════════



# ═══════════════════════════════════════════════════════════════════════
# 🌍  GLOBAL TOP LEADERBOARD MODULE  —  /gtop  +  /settop
# ───────────────────────────────────────────────────────────────────────
#  • /gtop  →  Photo banner + Top 250 captures, 10 per page (max 25 pages)
#  • /settop →  Owner-only. Reply to a photo/video then /settop to use it
#               as the /gtop banner. Banner is persisted in bot.settings.
#  • Pagination uses edit_message_media() / edit_message_caption() — NO new
#    messages are sent on Next/Prev.
#  • [ 🧍 YOUR RANK ] button shows an alert with the caller's global rank
#    and total captures.
#  • This module does NOT modify any existing DB structure, capture-count
#    logic, callbacks or commands. It only ADDS new functionality.
# ═══════════════════════════════════════════════════════════════════════
from telegram import (
    Update as _GtUpdate,
    InlineKeyboardButton as _GtBtn,
    InlineKeyboardMarkup as _GtKb,
    InputMediaPhoto as _GtIMPhoto,
    InputMediaVideo as _GtIMVideo,
)
from telegram.ext import (
    CommandHandler as _GtCmd,
    CallbackQueryHandler as _GtCbq,
    ContextTypes as _GtCtx,
)

# Tunables ---------------------------------------------------------------
_GTOP_PAGE_SIZE   = 10        # users per page
_GTOP_MAX_USERS   = 250       # cap at 250 users -> 25 pages
_GTOP_MAX_PAGES   = _GTOP_MAX_USERS // _GTOP_PAGE_SIZE   # = 25

# Default anime banner used when owner hasn't run /settop yet.
# Falls back to a text-only message if Telegram refuses the URL.
_GTOP_DEFAULT_BANNER_URL = (
    "https://files.catbox.moe/8x4yxz.jpg"
)

# ───────────────────────────────────────────────────────────────────────
# Helper: get capture count for a user (same logic as existing /top)
# ───────────────────────────────────────────────────────────────────────
def _gtop_capture_count(uid: str) -> int:
    try:
        cards_list = bot.data.get("users", {}).get(uid, []) or []
        return len(cards_list)
    except Exception:
        return 0


# ───────────────────────────────────────────────────────────────────────
# Helper: resolve a friendly display name for a user_id (string)
# ───────────────────────────────────────────────────────────────────────
def _gtop_resolve_name(uid: str) -> str:
    try:
        nm = get_name(uid)
    except Exception:
        nm = None
    if nm and nm != "Unknown":
        return nm
    # Fallback: scan cards for owner_name
    try:
        for c in bot.data.get("cards", {}).values():
            if str(c.get("owner")) == str(uid):
                nm2 = c.get("owner_name")
                if nm2:
                    try:
                        USER_CACHE[uid] = nm2
                    except Exception:
                        pass
                    return nm2
    except Exception:
        pass
    return f"User{str(uid)[-4:]}"


# ───────────────────────────────────────────────────────────────────────
# Build the sorted leaderboard list (uid, name, count).
# Sorted by count desc, then uid asc for stable ordering.
# ───────────────────────────────────────────────────────────────────────
def _gtop_build_ranking() -> list:
    rows = []
    try:
        users_dict = bot.data.get("users", {}) or {}
    except Exception:
        users_dict = {}

    for uid, cards in users_dict.items():
        try:
            cnt = len(cards) if cards else 0
        except Exception:
            cnt = 0
        if cnt <= 0:
            continue
        rows.append((str(uid), cnt))

    rows.sort(key=lambda x: (-x[1], x[0]))
    rows = rows[:_GTOP_MAX_USERS]
    return [(uid, _gtop_resolve_name(uid), cnt) for uid, cnt in rows]


# ───────────────────────────────────────────────────────────────────────
# Find a user's global rank + capture count (1-indexed)
# Returns (rank or None, capture_count, total_ranked_users)
# ───────────────────────────────────────────────────────────────────────
def _gtop_user_rank(uid: str) -> tuple:
    ranking = _gtop_build_ranking()
    total = len(ranking)
    uid = str(uid)
    for i, (u, _n, c) in enumerate(ranking, start=1):
        if u == uid:
            return i, c, total
    # Not in ranked list -> still return their count for transparency
    return None, _gtop_capture_count(uid), total


# ───────────────────────────────────────────────────────────────────────
# Build caption text for a given page (0-indexed)
# ───────────────────────────────────────────────────────────────────────
def _gtop_build_caption(ranking: list, page: int) -> str:
    total = len(ranking)
    total_pages = max(1, (total + _GTOP_PAGE_SIZE - 1) // _GTOP_PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))

    start = page * _GTOP_PAGE_SIZE
    end   = min(start + _GTOP_PAGE_SIZE, total)
    slice_ = ranking[start:end]

    bar = "━━━━━━━━━━━━━━━━━━━━"
    lines = [bar, "", "🌍 𝗧𝗢𝗣 𝟭𝟬 𝗚𝗟𝗢𝗕𝗔𝗟 𝗖𝗔𝗣𝗧𝗨𝗥𝗘𝗦", ""]

    if not slice_:
        lines.append("ℹ️ No captures recorded yet.")
    else:
        for rank_i, (_uid, name, count) in enumerate(slice_, start=start + 1):
            # Escape name for HTML-safe display
            safe_name = _gtop_html_escape(name) if name else "Unknown"
            lines.append(f"{rank_i}. {safe_name} ⇒ {count:,}")

    lines.append("")
    lines.append(bar)
    return "\n".join(lines)


def _gtop_html_escape(text) -> str:
    try:
        s = str(text)
    except Exception:
        s = ""
    return (
        s.replace("&", "&amp;")
         .replace("<", "&lt;")
         .replace(">", "&gt;")
    )


# ───────────────────────────────────────────────────────────────────────
# Build inline keyboard for /gtop page
#   Row 1 : [ 🧍 YOUR RANK ]
#   Row 2 : [ ◀️ ]  [ page/total ]  [ ▶️ ]
# Disabled arrows on the edges use a no-op callback that simply answers
# the query without changing anything.
# ───────────────────────────────────────────────────────────────────────
def _gtop_build_keyboard(page: int, total_pages: int) -> _GtKb:
    total_pages = max(1, total_pages)
    page = max(0, min(page, total_pages - 1))

    prev_cb = f"gtop_p:{page-1}" if page > 0 else "gtop_noop"
    next_cb = f"gtop_p:{page+1}" if page < total_pages - 1 else "gtop_noop"

    prev_btn = _GtBtn("◀️", callback_data=prev_cb)
    page_btn = _GtBtn(f"{page+1}/{total_pages}", callback_data="gtop_noop")
    next_btn = _GtBtn("▶️", callback_data=next_cb)

    return _GtKb([
        [_GtBtn("🧍 YOUR RANK", callback_data="gtop_rank")],
        [prev_btn, page_btn, next_btn],
    ])


# ───────────────────────────────────────────────────────────────────────
# Banner storage helpers
# Stored as: bot.settings["gtop_banner"] = {"type": "photo"|"video",
#                                            "file_id": "..."}
# ───────────────────────────────────────────────────────────────────────
def _gtop_get_banner() -> dict | None:
    try:
        b = bot.settings.get("gtop_banner")
        if isinstance(b, dict) and b.get("file_id"):
            return b
    except Exception:
        pass
    return None


def _gtop_set_banner(file_id: str, kind: str) -> None:
    try:
        bot.settings["gtop_banner"] = {"type": kind, "file_id": file_id}
        bot.save_settings()
    except Exception as e:
        try:
            logger.warning(f"[gtop] save banner failed: {e}")
        except Exception:
            pass


# ───────────────────────────────────────────────────────────────────────
# Send the FIRST /gtop message (always a new photo/video message).
# Subsequent Next/Prev presses must EDIT the same message — never send.
# ───────────────────────────────────────────────────────────────────────
async def _gtop_send_initial(message, caption: str, kb: _GtKb):
    banner = _gtop_get_banner()
    try:
        if banner:
            if banner.get("type") == "video":
                return await message.reply_video(
                    video=banner["file_id"],
                    caption=caption,
                    reply_markup=kb,
                    parse_mode="HTML",
                )
            else:
                return await message.reply_photo(
                    photo=banner["file_id"],
                    caption=caption,
                    reply_markup=kb,
                    parse_mode="HTML",
                )
        # Default URL banner
        return await message.reply_photo(
            photo=_GTOP_DEFAULT_BANNER_URL,
            caption=caption,
            reply_markup=kb,
            parse_mode="HTML",
        )
    except Exception as e:
        try:
            logger.warning(f"[gtop] send banner failed, falling back to text: {e}")
        except Exception:
            pass
        # Text-only fallback (still satisfies the "no new message on edit" rule
        # because the very first message is allowed to be anything).
        return await message.reply_text(
            caption, reply_markup=kb, parse_mode="HTML"
        )


# ───────────────────────────────────────────────────────────────────────
# /gtop command — entry point
# ───────────────────────────────────────────────────────────────────────
async def gtop_cmd(update: _GtUpdate, context: _GtCtx.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    try:
        if bot.is_gbanned(update.effective_user.id):
            await update.message.reply_text("❌ You are globally banned.")
            return
    except Exception:
        pass

    ranking = _gtop_build_ranking()
    total = len(ranking)
    total_pages = max(1, (total + _GTOP_PAGE_SIZE - 1) // _GTOP_PAGE_SIZE)

    page = 0
    caption = _gtop_build_caption(ranking, page)
    kb = _gtop_build_keyboard(page, total_pages)

    await _gtop_send_initial(update.message, caption, kb)


# ───────────────────────────────────────────────────────────────────────
# Callback handler for /gtop pagination + YOUR RANK + no-op edges
# ───────────────────────────────────────────────────────────────────────
async def gtop_callback(update: _GtUpdate, context: _GtCtx.DEFAULT_TYPE):
    query = update.callback_query
    if not query or not query.data:
        return
    data = query.data
    uid_str = str(query.from_user.id) if query.from_user else ""

    # ── YOUR RANK alert ────────────────────────────────────────────────
    if data == "gtop_rank":
        rank, count, total = _gtop_user_rank(uid_str)
        if rank is None:
            if count > 0:
                txt = (
                    f"🏆 Your Global Rank: #—\n"
                    f"🎴 Total Captures: {count:,}\n\n"
                    f"ℹ️ Top {total} only — keep capturing to enter!"
                )
            else:
                txt = (
                    "🏆 Your Global Rank: #—\n"
                    "🎴 Total Captures: 0\n\n"
                    "ℹ️ Capture some cards to appear here!"
                )
        else:
            txt = (
                f"🏆 Your Global Rank: #{rank}\n"
                f"🎴 Total Captures: {count:,}"
            )
        try:
            await query.answer(txt, show_alert=True)
        except Exception:
            try:
                await query.answer()
            except Exception:
                pass
        return

    # ── Disabled edge arrows — silently acknowledge, do nothing ────────
    if data == "gtop_noop":
        try:
            await query.answer()
        except Exception:
            pass
        return

    # ── Page navigation ────────────────────────────────────────────────
    if not data.startswith("gtop_p:"):
        try:
            await query.answer()
        except Exception:
            pass
        return

    try:
        page = int(data.split(":", 1)[1])
    except Exception:
        page = 0

    ranking = _gtop_build_ranking()
    total_pages = max(1, (len(ranking) + _GTOP_PAGE_SIZE - 1) // _GTOP_PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))

    caption = _gtop_build_caption(ranking, page)
    kb = _gtop_build_keyboard(page, total_pages)

    # ALWAYS answer first to dismiss the loading spinner
    try:
        await query.answer()
    except Exception:
        pass

    msg = query.message
    if not msg:
        return

    banner = _gtop_get_banner()

    # ── Prefer editing the caption only (cheapest, no media reload) ────
    has_media = bool(getattr(msg, "photo", None)) or bool(getattr(msg, "video", None))

    try:
        if has_media:
            # Edit caption only — banner stays unchanged
            await query.edit_message_caption(
                caption=caption,
                reply_markup=kb,
                parse_mode="HTML",
            )
        else:
            # Original message had no media (text fallback path).
            # Per spec we must NOT send a new message — edit the text.
            await query.edit_message_text(
                text=caption,
                reply_markup=kb,
                parse_mode="HTML",
            )
        return
    except Exception as e_caption:
        # Caption edit failed — try edit_message_media as a stronger fallback,
        # which still does NOT send a new message.
        try:
            if banner and banner.get("type") == "video":
                await query.edit_message_media(
                    media=_GtIMVideo(
                        media=banner["file_id"],
                        caption=caption,
                        parse_mode="HTML",
                    ),
                    reply_markup=kb,
                )
            else:
                photo_src = banner["file_id"] if banner else _GTOP_DEFAULT_BANNER_URL
                await query.edit_message_media(
                    media=_GtIMPhoto(
                        media=photo_src,
                        caption=caption,
                        parse_mode="HTML",
                    ),
                    reply_markup=kb,
                )
            return
        except Exception as e_media:
            # Last resort: try plain reply_markup refresh
            try:
                await query.edit_message_reply_markup(reply_markup=kb)
            except Exception:
                try:
                    logger.warning(
                        f"[gtop] edit failed (caption={e_caption}, media={e_media})"
                    )
                except Exception:
                    pass


# ───────────────────────────────────────────────────────────────────────
# /settop  —  Owner-only.
#   Usage:  Reply to a photo/video then send /settop
# ───────────────────────────────────────────────────────────────────────
async def settop_cmd(update: _GtUpdate, context: _GtCtx.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    try:
        if not bot.is_owner(update.effective_user.id):
            await update.message.reply_text("❌ Owner only command")
            return
    except Exception:
        await update.message.reply_text("❌ Owner only command")
        return

    reply = update.message.reply_to_message
    if not reply:
        await update.message.reply_text(
            "📝 Usage:\n"
            "• Reply to a photo or video then send /settop\n\n"
            "ℹ️ ဒီ banner ကို /gtop leaderboard မှာ ပြသွားပါမယ်။"
        )
        return

    file_id = None
    kind = None

    # Photo
    if getattr(reply, "photo", None):
        try:
            file_id = reply.photo[-1].file_id  # largest size
            kind = "photo"
        except Exception:
            file_id = None

    # Video
    if not file_id and getattr(reply, "video", None):
        try:
            file_id = reply.video.file_id
            kind = "video"
        except Exception:
            file_id = None

    # Animation (GIF) — treat as video for Telegram replay
    if not file_id and getattr(reply, "animation", None):
        try:
            file_id = reply.animation.file_id
            kind = "video"
        except Exception:
            file_id = None

    # Document image / video fallback
    if not file_id and getattr(reply, "document", None):
        try:
            mime = (reply.document.mime_type or "").lower()
            if mime.startswith("image/"):
                file_id = reply.document.file_id
                kind = "photo"
            elif mime.startswith("video/"):
                file_id = reply.document.file_id
                kind = "video"
        except Exception:
            file_id = None

    if not file_id or not kind:
        await update.message.reply_text(
            "❌ Reply to a photo or video first, then send /settop"
        )
        return

    _gtop_set_banner(file_id, kind)
    await update.message.reply_text(
        f"✅ /gtop banner saved!\n"
        f"📦 Type: {kind}\n"
        f"💡 Test it with /gtop"
    )


# ───────────────────────────────────────────────────────────────────────
# Register handlers — done via the same main-wrapper pattern used by the
# premium /buy module so we don't touch the existing main() body.
# ───────────────────────────────────────────────────────────────────────
def _gtop_register_handlers(application):
    try:
        application.add_handler(_GtCmd("gtop",   gtop_cmd),   group=-2)
        application.add_handler(_GtCmd("settop", settop_cmd), group=-2)
        application.add_handler(
            _GtCbq(gtop_callback, pattern=r"^gtop_"),
            group=-2,
        )
        try:
            logger.info("[gtop] ✅ /gtop + /settop + callbacks registered")
        except Exception:
            pass
    except Exception as e:
        try:
            logger.error(f"[gtop] register failed: {e}")
        except Exception:
            pass


def _gtop_install_main_wrapper():
    g = globals()
    orig_main = g.get("main")
    if not callable(orig_main) or getattr(orig_main, "_gtop_wrapped", False):
        return

    def wrapped_main():
        from telegram.ext import Application as _GtApp
        orig_build = _GtApp.builder().__class__.build

        def patched_build(self, *a, **kw):
            app_obj = orig_build(self, *a, **kw)
            try:
                _gtop_register_handlers(app_obj)
            except Exception as e:
                try:
                    logger.error(f"[gtop] register-in-build failed: {e}")
                except Exception:
                    pass
            _GtApp.builder().__class__.build = orig_build
            return app_obj

        _GtApp.builder().__class__.build = patched_build
        return orig_main()

    wrapped_main._gtop_wrapped = True
    g["main"] = wrapped_main


_gtop_install_main_wrapper()
# ═══════════════════════════════════════════════════════════════════════
#  END  /gtop  +  /settop  MODULE
# ═══════════════════════════════════════════════════════════════════════





