import os as _fa_os
import json as _fa_json
import random as _fa_random
import asyncio as _fa_asyncio
import logging as _fa_logging
import html as _fa_html
from datetime import datetime as _fa_dt

from telegram import (
    Update as _FaUpdate,
    InlineKeyboardButton as _FaBtn,
    InlineKeyboardMarkup as _FaKb,
    InputMediaPhoto as _FaIMPhoto,
    InputMediaVideo as _FaIMVideo,
)
from telegram.ext import (
    CommandHandler as _FaCmd,
    CallbackQueryHandler as _FaCbq,
    MessageHandler as _FaMsg,
    ContextTypes as _FaCtx,
    filters as _fa_filters,
)

_FA_LOG = _fa_logging.getLogger("fun_actions_patch")
_FA_LOG.setLevel(_fa_logging.INFO)

# ═══════════════════════════════════════════════════════════════════════════════
# 1️⃣  STORAGE  ── fun_media.json   (action media file_ids)
#                  setb_config.json  (loan-card-receiver account)
# ═══════════════════════════════════════════════════════════════════════════════
_FA_MEDIA_FILE = "fun_media.json"
_FA_MEDIA_CACHE: dict = {}

_FA_SETB_FILE = "setb_config.json"
_FA_SETB_CACHE: dict = {"receiver_id": None, "receiver_name": None}

# Pending media-save sessions (owner is asked to send sticker/gif)
# key = owner_user_id (int) -> action_name (str)
_FA_PENDING_MEDIA: dict = {}


def _fa_media_load():
    global _FA_MEDIA_CACHE
    try:
        if _fa_os.path.exists(_FA_MEDIA_FILE):
            with open(_FA_MEDIA_FILE, "r", encoding="utf-8") as fh:
                _FA_MEDIA_CACHE = _fa_json.load(fh) or {}
        else:
            _FA_MEDIA_CACHE = {}
    except Exception as e:
        _FA_LOG.warning(f"[fun] media load failed: {e}")
        _FA_MEDIA_CACHE = {}


def _fa_media_save():
    try:
        with open(_FA_MEDIA_FILE, "w", encoding="utf-8") as fh:
            _fa_json.dump(_FA_MEDIA_CACHE, fh, indent=2, ensure_ascii=False)
    except Exception as e:
        _FA_LOG.warning(f"[fun] media save failed: {e}")


def _fa_setb_load():
    global _FA_SETB_CACHE
    try:
        if _fa_os.path.exists(_FA_SETB_FILE):
            with open(_FA_SETB_FILE, "r", encoding="utf-8") as fh:
                d = _fa_json.load(fh) or {}
            if isinstance(d, dict):
                _FA_SETB_CACHE = {
                    "receiver_id": d.get("receiver_id"),
                    "receiver_name": d.get("receiver_name"),
                }
    except Exception as e:
        _FA_LOG.warning(f"[fun] setb load failed: {e}")


def _fa_setb_save():
    try:
        with open(_FA_SETB_FILE, "w", encoding="utf-8") as fh:
            _fa_json.dump(_FA_SETB_CACHE, fh, indent=2, ensure_ascii=False)
    except Exception as e:
        _FA_LOG.warning(f"[fun] setb save failed: {e}")


_fa_media_load()
_fa_setb_load()


# ═══════════════════════════════════════════════════════════════════════════════
# 2️⃣  FUN ACTION COMMANDS  (kiss/hug/pat/poke/bite/cuddle/punch/kick/shoot/
#                            slap/bonk/dance/ship)
# ═══════════════════════════════════════════════════════════════════════════════
_FA_ACTIONS = {
    "kiss":   {"emoji": "💋", "verb": "kissed",   "label": "Kiss"},
    "hug":    {"emoji": "🤗", "verb": "hugged",   "label": "Hug"},
    "pat":    {"emoji": "🐾", "verb": "patted",   "label": "Pat"},
    "poke":   {"emoji": "👉", "verb": "poked",    "label": "Poke"},
    "bite":   {"emoji": "🦷", "verb": "bit",      "label": "Bite"},
    "cuddle": {"emoji": "🥰", "verb": "cuddled",  "label": "Cuddle"},
    "punch":  {"emoji": "👊", "verb": "punched",  "label": "Punch"},
    "kick":   {"emoji": "🦵", "verb": "kicked",   "label": "Kick"},
    "shoot":  {"emoji": "🔫", "verb": "shot",     "label": "Shoot"},
    "slap":   {"emoji": "👋", "verb": "slapped",  "label": "Slap"},
    "bonk":   {"emoji": "🔨", "verb": "bonked",   "label": "Bonk"},
    "dance":  {"emoji": "💃", "verb": "danced with", "label": "Dance"},
    "ship":   {"emoji": "💍", "verb": "ship",     "label": "Ship"},
}


def _fa_user_mention_html(user_id, name) -> str:
    """Build a clickable mention. Uses tg://user?id= so it works without username."""
    try:
        safe = _fa_html.escape(str(name) if name else f"User{str(user_id)[-4:]}")
    except Exception:
        safe = "User"
    return f'<a href="tg://user?id={int(user_id)}">{safe}</a>'


def _fa_resolve_user_name(user) -> str:
    try:
        if not user:
            return "User"
        name = user.full_name or user.first_name or user.username or f"User{str(user.id)[-4:]}"
        return name
    except Exception:
        return "User"


def _fa_ship_message(uid_a: int, name_a: str, uid_b: int, name_b: str) -> str:
    # Stable per-pair % so same couple gets same result
    seed = tuple(sorted([int(uid_a), int(uid_b)]))
    rng = _fa_random.Random(f"ship-{seed[0]}-{seed[1]}")
    pct = rng.randint(0, 100)
    if   pct >= 90: tag = "Perfect Couple 😍"
    elif pct >= 70: tag = "Soulmates 💖"
    elif pct >= 50: tag = "Good Match 💞"
    elif pct >= 30: tag = "Try Harder 🙂"
    else:           tag = "Just Friends 😅"

    a_m = _fa_user_mention_html(uid_a, name_a)
    b_m = _fa_user_mention_html(uid_b, name_b)
    return (
        "💍 <b>Ship Result</b>\n\n"
        f"{a_m} ❤️ {b_m}\n\n"
        f"Compatibility: <b>{pct}%</b>\n"
        f"{tag}"
    )


async def _fa_send_action_media(message, action: str):
    """Send the saved sticker/gif/photo/video for an action if any."""
    entry = _FA_MEDIA_CACHE.get(action)
    if not entry:
        return
    kind = entry.get("type")
    file_id = entry.get("file_id")
    if not kind or not file_id:
        return
    try:
        if kind == "sticker":
            await message.reply_sticker(sticker=file_id)
        elif kind == "animation":
            await message.reply_animation(animation=file_id)
        elif kind == "video":
            await message.reply_video(video=file_id)
        elif kind == "photo":
            await message.reply_photo(photo=file_id)
        elif kind == "document":
            await message.reply_document(document=file_id)
    except Exception as e:
        _FA_LOG.warning(f"[fun] send action media failed for {action}: {e}")


async def _fa_action_cmd(update: _FaUpdate, context: _FaCtx.DEFAULT_TYPE):
    """Generic handler used by every /kiss /hug /slap ... command."""
    if not update.effective_user or not update.message:
        return

    # Figure out which action from message text
    txt = (update.message.text or "").strip()
    action = ""
    if txt.startswith("/"):
        head = txt.split()[0]
        # strip "@botname"
        if "@" in head:
            head = head.split("@", 1)[0]
        action = head.lstrip("/").lower()
    if action not in _FA_ACTIONS:
        return

    actor = update.effective_user
    actor_name = _fa_resolve_user_name(actor)

    # /ship can work with two replies OR with reply+actor
    reply = update.message.reply_to_message
    target = reply.from_user if reply else None

    # /ship special handling
    if action == "ship":
        if not target:
            await update.message.reply_text(
                "💍 Reply to a user with /ship to see your love-match %!"
            )
            return
        if target.id == actor.id:
            await update.message.reply_text("😅 You can't ship yourself!")
            return
        text = _fa_ship_message(actor.id, actor_name,
                                target.id, _fa_resolve_user_name(target))
        await update.message.reply_text(text, parse_mode="HTML",
                                        disable_web_page_preview=True)
        await _fa_send_action_media(update.message, "ship")
        return

    # Normal action commands need a reply target
    if not target:
        await update.message.reply_text(
            f"{_FA_ACTIONS[action]['emoji']} Reply to a user with /{action} to use this command."
        )
        return

    # Self-action allowed but slightly different wording
    info = _FA_ACTIONS[action]
    actor_m = _fa_user_mention_html(actor.id, actor_name)
    target_m = _fa_user_mention_html(target.id, _fa_resolve_user_name(target))

    if target.id == actor.id:
        text = f"{info['emoji']} {actor_m} {info['verb']} themselves! 😂"
    else:
        text = f"{info['emoji']} {actor_m} {info['verb']} {target_m}!"

    try:
        await update.message.reply_text(text, parse_mode="HTML",
                                        disable_web_page_preview=True)
    except Exception:
        # Fallback without HTML
        await update.message.reply_text(
            f"{info['emoji']} {actor_name} {info['verb']} {_fa_resolve_user_name(target)}!"
        )

    await _fa_send_action_media(update.message, action)


# ═══════════════════════════════════════════════════════════════════════════════
# 3️⃣  /sets  — Owner-only inline keyboard to set media for each action
# ═══════════════════════════════════════════════════════════════════════════════
def _fa_is_owner(user_id) -> bool:
    try:
        return bool(bot.is_owner(user_id))
    except Exception:
        return False


def _fa_sets_keyboard() -> _FaKb:
    rows = []
    row = []
    for key, info in _FA_ACTIONS.items():
        row.append(_FaBtn(f"{info['emoji']} {info['label']}",
                          callback_data=f"faset|{key}"))
        if len(row) == 3:
            rows.append(row); row = []
    if row:
        rows.append(row)
    rows.append([_FaBtn("✖ Close", callback_data="faset|close")])
    return _FaKb(rows)


async def fa_sets_cmd(update: _FaUpdate, context: _FaCtx.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    if not _fa_is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only command")
        return
    await update.message.reply_text(
        "🎬 <b>Fun Action Media Setup</b>\n\n"
        "Tap a button below, then send a Sticker / GIF / Photo / Video to save it "
        "for that action.",
        parse_mode="HTML",
        reply_markup=_fa_sets_keyboard(),
    )


async def fa_sets_callback(update: _FaUpdate, context: _FaCtx.DEFAULT_TYPE):
    query = update.callback_query
    if not query or not query.data:
        return
    try:
        await query.answer()
    except Exception:
        pass

    if not query.from_user or not _fa_is_owner(query.from_user.id):
        try:
            await query.answer("❌ Owner only", show_alert=True)
        except Exception:
            pass
        return

    parts = query.data.split("|", 1)
    if len(parts) != 2 or parts[0] != "faset":
        return
    action = parts[1]

    if action == "close":
        try:
            await query.edit_message_text("✅ Setup closed.")
        except Exception:
            pass
        return

    if action not in _FA_ACTIONS:
        return

    _FA_PENDING_MEDIA[int(query.from_user.id)] = action
    label = _FA_ACTIONS[action]["label"]
    try:
        await query.edit_message_text(
            f"📤 Please <b>SEND a Sticker / GIF / Photo / Video</b> for /<code>{action}</code>\n\n"
            f"({label})\n\n"
            "❗ Send within this chat. Type /cancel to abort.",
            parse_mode="HTML",
        )
    except Exception:
        pass


async def fa_cancel_setup_cmd(update: _FaUpdate, context: _FaCtx.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    uid = int(update.effective_user.id)
    if uid in _FA_PENDING_MEDIA:
        _FA_PENDING_MEDIA.pop(uid, None)
        await update.message.reply_text("✅ Setup cancelled.")


async def fa_media_capture(update: _FaUpdate, context: _FaCtx.DEFAULT_TYPE):
    """Listens for owner's next media after pressing a /sets button."""
    msg = update.message
    if not msg or not update.effective_user:
        return
    uid = int(update.effective_user.id)
    action = _FA_PENDING_MEDIA.get(uid)
    if not action:
        return  # not in setup mode → ignore (other handlers see it normally)

    file_id = None
    kind = None
    if msg.sticker:
        file_id = msg.sticker.file_id; kind = "sticker"
    elif msg.animation:
        file_id = msg.animation.file_id; kind = "animation"
    elif msg.video:
        file_id = msg.video.file_id; kind = "video"
    elif msg.photo:
        file_id = msg.photo[-1].file_id; kind = "photo"
    elif msg.document:
        mime = (msg.document.mime_type or "").lower()
        if mime.startswith("image/gif") or mime.endswith("/gif"):
            file_id = msg.document.file_id; kind = "animation"
        elif mime.startswith("image/"):
            file_id = msg.document.file_id; kind = "photo"
        elif mime.startswith("video/"):
            file_id = msg.document.file_id; kind = "video"
        else:
            file_id = msg.document.file_id; kind = "document"

    if not file_id or not kind:
        await msg.reply_text(
            "❌ Please send a Sticker, GIF, Photo or Video.\n"
            "Type /cancel to abort."
        )
        return

    _FA_MEDIA_CACHE[action] = {"type": kind, "file_id": file_id}
    _fa_media_save()
    _FA_PENDING_MEDIA.pop(uid, None)

    await msg.reply_text(
        f"✅ /{action} media saved successfully\n"
        f"📦 Type: {kind}"
    )
    # Stop other handlers from processing this media as a normal message
    try:
        from telegram.ext import ApplicationHandlerStop
        raise ApplicationHandlerStop
    except ImportError:
        pass


# ═══════════════════════════════════════════════════════════════════════════════
# 4️⃣  /setb  — set the user account that receives seized loan cards
#               Usage: reply to a user with /setb  OR  /setb @username  OR  /setb <user_id>
# ═══════════════════════════════════════════════════════════════════════════════
def _fa_find_user_by_username(uname: str):
    """Try to resolve a @username to (user_id, display_name) from bot.data caches."""
    uname = (uname or "").lstrip("@").lower()
    if not uname:
        return None, None
    # Search USER_CACHE / name caches if available
    try:
        for uid, name in (globals().get("USER_CACHE") or {}).items():
            if name and uname in str(name).lower():
                return str(uid), name
    except Exception:
        pass
    # Search cards for owner_name match
    try:
        for c in (bot.data.get("cards", {}) or {}).values():
            nm = (c.get("owner_name") or "").lower()
            if nm and uname in nm:
                return str(c.get("owner")), c.get("owner_name")
    except Exception:
        pass
    return None, None


async def fa_setb_cmd(update: _FaUpdate, context: _FaCtx.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    if not _fa_is_owner(update.effective_user.id):
        await update.message.reply_text("❌ Owner only command")
        return

    target_id = None
    target_name = None

    reply = update.message.reply_to_message
    if reply and reply.from_user:
        target_id = str(reply.from_user.id)
        target_name = _fa_resolve_user_name(reply.from_user)
    elif context.args:
        arg = str(context.args[0]).strip()
        if arg.startswith("@"):
            tid, tname = _fa_find_user_by_username(arg)
            target_id = tid
            target_name = tname
        elif arg.isdigit():
            target_id = arg
            try:
                target_name = get_name(arg)
            except Exception:
                target_name = f"User{arg[-4:]}"
        else:
            # try as username without @
            tid, tname = _fa_find_user_by_username(arg)
            target_id = tid
            target_name = tname

    if not target_id:
        await update.message.reply_text(
            "📝 Usage:\n"
            "• Reply to a user then send /setb\n"
            "• /setb @username\n"
            "• /setb <user_id>\n\n"
            "ℹ️ ဒီအကောင့်က /loan ပြန်မဆပ်လို့ သိမ်းတဲ့ card တွေကို လက်ခံပါမယ်။"
        )
        return

    _FA_SETB_CACHE["receiver_id"] = str(target_id)
    _FA_SETB_CACHE["receiver_name"] = target_name or f"User{str(target_id)[-4:]}"
    _fa_setb_save()

    await update.message.reply_text(
        "✅ <b>Loan-Card Receiver Set</b>\n\n"
        f"👤 Receiver: {_fa_user_mention_html(target_id, _FA_SETB_CACHE['receiver_name'])}\n"
        f"🆔 User ID: <code>{target_id}</code>\n\n"
        "💡 မဆပ်တဲ့သူရဲ့ ကဒ်တွေက ဒီအကောင့်ဆီကိုသွားပါမယ်။",
        parse_mode="HTML",
        disable_web_page_preview=True,
    )


async def fa_getb_cmd(update: _FaUpdate, context: _FaCtx.DEFAULT_TYPE):
    if not update.message:
        return
    rid = _FA_SETB_CACHE.get("receiver_id")
    if not rid:
        await update.message.reply_text("ℹ️ No loan-card receiver set yet. Use /setb to configure.")
        return
    rname = _FA_SETB_CACHE.get("receiver_name") or "Unknown"
    await update.message.reply_text(
        f"🏦 Current loan-card receiver:\n"
        f"👤 {_fa_user_mention_html(rid, rname)}\n"
        f"🆔 <code>{rid}</code>",
        parse_mode="HTML",
        disable_web_page_preview=True,
    )


