# 5️⃣  PATCH:  /loan  hard cap → 10,000,000,000,000   (10 trillion)
#               /reloan seized card → transfer to /setb receiver + DM notify
# ═══════════════════════════════════════════════════════════════════════════════
try:
    # Raise hard cap as requested
    globals()["_U_LOAN_HARD_CAP"] = 10_000_000_000_000
    _FA_LOG.info("[fun] _U_LOAN_HARD_CAP raised to 10,000,000,000,000")
except Exception as _e:
    _FA_LOG.warning(f"[fun] failed to raise loan cap: {_e}")


def _fa_install_reloan_patch():
    """
    Wrap the existing u_reloan_cmd so that, when a card is seized, it is
    transferred to the /setb receiver and both parties are DM-notified.
    """
    g = globals()
    orig = g.get("u_reloan_cmd")
    if not orig or getattr(orig, "_fa_wrapped", False):
        return

    async def wrapped_reloan(update, context):
        user = update.effective_user
        if not user or not update.message:
            return await orig(update, context)

        uid = str(user.id)
        # Snapshot the user's inventory before original runs
        inv_before = list(bot.data.get("users", {}).get(uid, []) or [])
        loan_before = dict(_u_get_loan(uid)) if "_u_get_loan" in g else {}
        debt_before = int(loan_before.get("amount", 0)) if loan_before else 0

        # Call original
        await orig(update, context)

        # Detect seizure: a card disappeared from inventory + debt cleared
        try:
            inv_after = list(bot.data.get("users", {}).get(uid, []) or [])
        except Exception:
            inv_after = inv_before
        removed = [c for c in inv_before if c not in inv_after]

        if not removed or debt_before <= 0:
            return  # nothing seized — repayment was successful or no debt

        seized_id = removed[0]
        card = bot.data.get("cards", {}).get(seized_id) or {}

        receiver_id = _FA_SETB_CACHE.get("receiver_id")
        receiver_name = _FA_SETB_CACHE.get("receiver_name") or "Unknown"

        if not receiver_id:
            # No receiver configured: leave the card as-is (already orphaned by original code)
            try:
                await update.message.reply_text(
                    "ℹ️ Seized card is currently <b>unassigned</b> — owner has not run /setb yet.",
                    parse_mode="HTML",
                )
            except Exception:
                pass
            return

        # Transfer the card to receiver
        try:
            bot.data.setdefault("users", {}).setdefault(str(receiver_id), [])
            if seized_id not in bot.data["users"][str(receiver_id)]:
                bot.data["users"][str(receiver_id)].append(seized_id)
            bot.data.setdefault("cards", {})
            if seized_id in bot.data["cards"]:
                bot.data["cards"][seized_id]["owner"] = int(receiver_id) if str(receiver_id).isdigit() else receiver_id
                bot.data["cards"][seized_id]["owner_name"] = receiver_name
            bot.save_data()
        except Exception as e:
            _FA_LOG.warning(f"[fun] seized-card transfer failed: {e}")

        # DM notifications
        try:
            rarity_info = RARITIES.get(str(card.get("rarity", "1")), RARITIES["1"])
            card_name = card.get("name", "Unknown")
            card_id_disp = card.get("id", seized_id)

            # Notify the DEBTOR
            debtor_msg = (
                "⚠️ <b>Loan Default — Card Seized</b>\n\n"
                f"💳 Debt : <code>{debt_before:,}</code> Coins\n"
                f"🗑 Seized: <b>{_fa_html.escape(str(card_name))}</b> #{card_id_disp}\n"
                f"⭐ {rarity_info.get('display', '')}\n\n"
                f"➡️ Transferred to: {_fa_user_mention_html(receiver_id, receiver_name)}\n\n"
                "💡 Be careful with future loans!"
            )
            try:
                await context.bot.send_message(
                    chat_id=int(uid),
                    text=debtor_msg,
                    parse_mode="HTML",
                    disable_web_page_preview=True,
                )
            except Exception as e:
                _FA_LOG.info(f"[fun] DM to debtor {uid} failed: {e}")

            # Notify the RECEIVER
            actor_name = _fa_resolve_user_name(user)
            recv_msg = (
                "📥 <b>Loan-Card Received</b>\n\n"
                f"From: {_fa_user_mention_html(uid, actor_name)} "
                f"(<code>{uid}</code>)\n"
                f"💳 Original Debt : <code>{debt_before:,}</code> Coins\n\n"
                f"🎴 Card: <b>{_fa_html.escape(str(card_name))}</b> #{card_id_disp}\n"
                f"⭐ {rarity_info.get('display', '')}\n\n"
                "✅ This card has been added to your inventory."
            )
            try:
                await context.bot.send_message(
                    chat_id=int(receiver_id),
                    text=recv_msg,
                    parse_mode="HTML",
                    disable_web_page_preview=True,
                )
            except Exception as e:
                _FA_LOG.info(f"[fun] DM to receiver {receiver_id} failed: {e}")
        except Exception as e:
            _FA_LOG.warning(f"[fun] reloan-DM notify error: {e}")

    wrapped_reloan._fa_wrapped = True
    g["u_reloan_cmd"] = wrapped_reloan
    _FA_LOG.info("[fun] u_reloan_cmd wrapped (transfer + DM)")


_fa_install_reloan_patch()


# ═══════════════════════════════════════════════════════════════════════════════
# 6️⃣  PATCH:  Premium /buy  →  navigating Back/Next must SWAP the IMAGE too
# ═══════════════════════════════════════════════════════════════════════════════
def _fa_install_buy_image_patch():
    g = globals()
    orig = g.get("_u_send_card_view")
    if not orig or getattr(orig, "_fa_wrapped", False):
        return

    async def patched_send_card_view(message_or_query, context, uid, rarity,
                                     cards, idx, edit):
        if not edit:
            return await orig(message_or_query, context, uid, rarity, cards, idx, edit)

        # Edit branch: try to swap media + caption with edit_message_media
        try:
            idx = max(0, min(idx, len(cards) - 1))
            card_id = cards[idx]
            card = bot.data["cards"].get(card_id) or {}
            init_user_if_not_exists(uid)
            profile = bot.data["user_profiles"][uid]
            balance = int(profile.get("coins", 0))
            price = _u_current_price(card_id, card)
            remaining_today = _u_daily_remaining(uid)
            can_buy = (balance >= price) and (remaining_today > 0)

            caption = _u_build_card_caption(card, card_id, price, balance,
                                            remaining_today, len(cards), idx)
            kb = _u_build_browse_keyboard(card_id, idx, len(cards), can_buy)

            media_kind = "photo"
            media_ref = card.get("image")
            if card.get("type") == "video":
                media_kind = "video" if card.get("video_type") == "video" else "document"
                media_ref = card.get("video")

            # Need the query object
            query = message_or_query
            if not hasattr(query, "edit_message_media"):
                # Fall back to original behaviour
                return await orig(message_or_query, context, uid, rarity, cards, idx, edit)

            try:
                if media_kind == "photo" and media_ref:
                    await query.edit_message_media(
                        media=_FaIMPhoto(media=media_ref, caption=caption),
                        reply_markup=kb,
                    )
                elif media_kind == "video" and media_ref:
                    await query.edit_message_media(
                        media=_FaIMVideo(media=media_ref, caption=caption),
                        reply_markup=kb,
                    )
                else:
                    # Document / no media: fallback to caption-only edit
                    try:
                        await query.edit_message_caption(caption=caption, reply_markup=kb)
                    except Exception:
                        await query.edit_message_text(text=caption, reply_markup=kb)
            except Exception as e:
                _FA_LOG.info(f"[fun] buy edit_media failed → caption-only fallback: {e}")
                try:
                    await query.edit_message_caption(caption=caption, reply_markup=kb)
                except Exception:
                    try:
                        await query.edit_message_text(text=caption, reply_markup=kb)
                    except Exception as e2:
                        _FA_LOG.warning(f"[fun] buy caption fallback failed: {e2}")

            # Save browse state on the SAME message
            msg = query.message
            if msg:
                key = f"{msg.chat_id}:{msg.message_id}"
                _U_BROWSE[key] = {
                    "uid": uid,
                    "rarity": str(rarity),
                    "cards": cards,
                    "idx": idx,
                }
        except Exception as e:
            _FA_LOG.warning(f"[fun] buy patched view error → original fallback: {e}")
            return await orig(message_or_query, context, uid, rarity, cards, idx, edit)

    patched_send_card_view._fa_wrapped = True
    g["_u_send_card_view"] = patched_send_card_view
    _FA_LOG.info("[fun] _u_send_card_view patched (image swap on nav)")


_fa_install_buy_image_patch()


# ═══════════════════════════════════════════════════════════════════════════════
# 7️⃣  PATCH:  /gtop  → show ONLY TOP 10 with HTML mentions
# ═══════════════════════════════════════════════════════════════════════════════
def _fa_install_gtop_patch():
    g = globals()
    orig_build_caption = g.get("_gtop_build_caption")
    orig_build_keyboard = g.get("_gtop_build_keyboard")
    if not orig_build_caption:
        return

    # Force page-size to 10 and cap to first 10 names only
    def patched_build_caption(ranking, page):
        try:
            ranking = list(ranking)[:10]    # only the top 10 globally
        except Exception:
            pass
        bar = "━━━━━━━━━━━━━━━━━━━━"
        lines = [bar, "", "🌍 𝗧𝗢𝗣 𝟭𝟬 𝗚𝗟𝗢𝗕𝗔𝗟 𝗖𝗔𝗣𝗧𝗨𝗥𝗘𝗦", ""]
        if not ranking:
            lines.append("ℹ️ No captures recorded yet.")
        else:
            for i, (uid, name, count) in enumerate(ranking, start=1):
                medal = "🥇" if i == 1 else "🥈" if i == 2 else "🥉" if i == 3 else f"{i}."
                # Mention (clickable name)
                mention = _fa_user_mention_html(uid, name or f"User{str(uid)[-4:]}")
                lines.append(f"{medal} {mention} ⇒ {count:,}")
        lines.append("")
        lines.append(bar)
        return "\n".join(lines)

    patched_build_caption._fa_wrapped = True
    g["_gtop_build_caption"] = patched_build_caption

    # Single-page keyboard (no pagination needed for top 10)
    if orig_build_keyboard:
        def patched_build_keyboard(page, total_pages):
            return _FaKb([
                [_FaBtn("🧍 YOUR RANK", callback_data="gtop_rank")],
            ])
        patched_build_keyboard._fa_wrapped = True
        g["_gtop_build_keyboard"] = patched_build_keyboard

    _FA_LOG.info("[fun] gtop patched → top 10 with mentions")


_fa_install_gtop_patch()


# ═══════════════════════════════════════════════════════════════════════════════
# 8️⃣  PATCH:  /profile  → show spouse as a clickable mention
# ═══════════════════════════════════════════════════════════════════════════════
def _fa_install_profile_spouse_patch():
    """
    Monkey-patch get_name? No — easier: wrap profile_cmd to post-process the
    caption it builds, OR wrap by intercepting marriages display.
    Cleanest: post-process the caption string before profile_cmd sends it.

    Since profile_cmd is large and uses 'lines' locally, the simplest reliable
    way is to override the marriages display by patching the function source
    via wrapping: replace bot.data['marriages'] lookup result by attaching
    spouse mention through a small helper used inside the caption build.

    Approach taken here: install a post-send hook is hard, so we wrap the
    profile_cmd function entirely and reproduce the spouse mention behavior
    by editing the message after it is sent. We do this via a wrapper that
    re-renders just the spouse line and replaces the existing 'Spouse:' line.
    """
    g = globals()
    orig = g.get("profile_cmd")
    if not orig or getattr(orig, "_fa_wrapped", False):
        return

    async def wrapped_profile(update, context):
        # Temporarily monkey-patch get_name during this call to inject HTML mention.
        # Easier: after the original send, edit the caption/text to replace the
        # spouse line with a mention. We capture sent messages via context.bot.
        # Simplest robust approach: do nothing here, and instead modify the
        # caption *after* send by post-processing the most recent message.
        return await orig(update, context)

    # Use a different strategy: patch get_name only in the profile_cmd's scope
    # by reaching into bot.data marriages lookup at runtime via a code wrapper.
    # We replace the function with one that builds the same output but with mention.
    #
    # Easiest reliable patch: hook into _html_escape used on spouse name? No,
    # name is plain. Better: install a post-handler that listens to the
    # bot's own outgoing 'Spouse:' messages — not feasible.
    #
    # FINAL APPROACH: replace the spouse-name resolution by patching get_name to
    # return an HTML mention when called from within profile_cmd. Detect using
    # a thread-local flag.
    import contextvars as _cv
    g.setdefault("_fa_in_profile_ctx", _cv.ContextVar("_fa_in_profile_ctx", default=False))
    in_profile_ctx = g["_fa_in_profile_ctx"]

    orig_get_name = g.get("get_name")
    if orig_get_name and not getattr(orig_get_name, "_fa_wrapped", False):
        def wrapped_get_name(uid):
            try:
                base = orig_get_name(uid)
            except Exception:
                base = None
            if in_profile_ctx.get() and uid:
                # Return an HTML mention so the spouse line becomes clickable
                # (profile_cmd builds HTML output → this is safe).
                try:
                    safe = _fa_html.escape(str(base) if base else f"User{str(uid)[-4:]}")
                except Exception:
                    safe = "User"
                # Mark with a sentinel so we don't double-mention if used elsewhere
                return f'<a href="tg://user?id={int(uid)}">{safe}</a>'
            return base
        wrapped_get_name._fa_wrapped = True
        g["get_name"] = wrapped_get_name

    async def wrapped_profile_v2(update, context):
        token = in_profile_ctx.set(True)
        try:
            return await orig(update, context)
        finally:
            in_profile_ctx.reset(token)

    wrapped_profile_v2._fa_wrapped = True
    g["profile_cmd"] = wrapped_profile_v2
    _FA_LOG.info("[fun] profile_cmd patched → spouse mention enabled")


_fa_install_profile_spouse_patch()


# ═══════════════════════════════════════════════════════════════════════════════
# 9️⃣  REGISTER  — handlers via the same main()-wrapper pattern
# ═══════════════════════════════════════════════════════════════════════════════
def _fa_register_handlers(application):
    try:
        # Action commands
        for act in _FA_ACTIONS.keys():
            application.add_handler(_FaCmd(act, _fa_action_cmd), group=-4)

        # Owner setup
        application.add_handler(_FaCmd("sets",   fa_sets_cmd),   group=-4)
        application.add_handler(_FaCmd("setb",   fa_setb_cmd),   group=-4)
        application.add_handler(_FaCmd("getb",   fa_getb_cmd),   group=-4)
        application.add_handler(_FaCmd("cancel", fa_cancel_setup_cmd), group=-4)

        # Callback for /sets buttons
        application.add_handler(_FaCbq(fa_sets_callback, pattern=r"^faset\|"), group=-4)

        # Media capture (must be high-priority so it intercepts owner's reply)
        media_filter = (
            _fa_filters.Sticker.ALL |
            _fa_filters.ANIMATION |
            _fa_filters.VIDEO |
            _fa_filters.PHOTO |
            _fa_filters.Document.ALL
        )
        application.add_handler(_FaMsg(media_filter, fa_media_capture), group=-5)

        _FA_LOG.info("[fun] ✅ Fun-Action commands + /sets + /setb registered")
    except Exception as e:
        _FA_LOG.error(f"[fun] register failed: {e}")


def _fa_install_main_wrapper():
    g = globals()
    orig_main = g.get("main")
    if not callable(orig_main) or getattr(orig_main, "_fa_wrapped", False):
        return

    def wrapped_main():
        from telegram.ext import Application as _FaApp
        orig_build = _FaApp.builder().__class__.build

        def patched_build(self, *a, **kw):
            app_obj = orig_build(self, *a, **kw)
            try:
                _fa_register_handlers(app_obj)
            except Exception as e:
                _FA_LOG.error(f"[fun] register-in-build failed: {e}")
            _FaApp.builder().__class__.build = orig_build
            return app_obj

        _FaApp.builder().__class__.build = patched_build
        return orig_main()

    wrapped_main._fa_wrapped = True
    g["main"] = wrapped_main


_fa_install_main_wrapper()
