# ── Storage ───────────────────────────────────────────────────────────────
_GC_FILE = "guess_data.json"
_GC_CACHE: dict = {
    "stats": {},          # user_id -> {"total":0,"week":0,"month":0,
                          #             "week_key":"YYYY-WW","month_key":"YYYY-MM",
                          #             "kakera":0,"last_win":None}
    "settings": {
        "round_seconds": 30,
        "rarity_chance": {       # only used as fallback when many rarities are unlocked
            "1": 50.0,           # Common
            "3": 25.0,           # Rare
            "4": 12.0,           # Epic (treated as "Elite" tier in user spec)
            "5": 8.0,            # Legendary  (treated as "Epic" tier)
            "6": 4.0,            # Mythic     (treated as "Legendary")
            "7": 1.0,            # Divine     (treated as "Mythic")
        },
        # Kakera conversion table per rarity key (internal rarity ids)
        "kakera_per_rarity": {
            "1":  50,    # Common
            "2":  80,    # Uncommon
            "3":  150,   # Rare
            "4":  300,   # Elite (Epic)
            "5":  500,   # Epic (Legendary)
            "6":  750,   # Legendary (Mythic)
            "7":  1500,  # Mythic (Divine)
            "8":  2000,
            "9":  3000,
            "10": 4000,
            "11": 5000,
            "12": 7500,
            "13": 10000,
            "14": 15000,
            "15": 25000,
            "16": 50000,
        },
        # Daily streak rewards (Day1..Day7) — recycled after day 7
        "daily_streak": {
            "1": {"type": "coins", "amount": 500},
            "2": {"type": "coins", "amount": 800},
            "3": {"type": "card",  "rarity": None},   # random card from unlocked
            "4": {"type": "coins", "amount": 1500},
            "5": {"type": "coins", "amount": 2500},
            "6": {"type": "coins", "amount": 4000},
            "7": {"type": "card",  "rarity": "4"},    # Epic card (rarity id 4)
        },
    },
}

# Active sessions:  chat_id (int) -> session dict
_GC_SESSIONS: dict = {}
_GC_SESSION_LOCK = _gc_asyncio.Lock()


def _gc_load():
    global _GC_CACHE
    if _gc_os.path.exists(_GC_FILE):
        try:
            with open(_GC_FILE, "r", encoding="utf-8") as f:
                loaded = _gc_json.load(f)
                if isinstance(loaded, dict):
                    # merge — keep defaults for missing keys
                    if "stats" in loaded and isinstance(loaded["stats"], dict):
                        _GC_CACHE["stats"] = loaded["stats"]
                    if "settings" in loaded and isinstance(loaded["settings"], dict):
                        for k, v in loaded["settings"].items():
                            _GC_CACHE["settings"][k] = v
        except Exception as e:
            _GC_LOG.warning(f"[guess] load failed: {e}")


def _gc_save():
    try:
        tmp = _GC_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _gc_json.dump(_GC_CACHE, f, ensure_ascii=False, indent=2)
        _gc_os.replace(tmp, _GC_FILE)
    except Exception as e:
        _GC_LOG.warning(f"[guess] save failed: {e}")


_gc_load()


# ── Helpers ───────────────────────────────────────────────────────────────
def _gc_now() -> _gc_dt:
    return _gc_dt.now()


def _gc_week_key(dt: _gc_dt | None = None) -> str:
    dt = dt or _gc_now()
    iso_year, iso_week, _ = dt.isocalendar()
    return f"{iso_year}-W{iso_week:02d}"


def _gc_month_key(dt: _gc_dt | None = None) -> str:
    dt = dt or _gc_now()
    return f"{dt.year}-{dt.month:02d}"


def _gc_ensure_user_stats(uid: str) -> dict:
    s = _GC_CACHE["stats"].get(uid)
    if not isinstance(s, dict):
        s = {}
        _GC_CACHE["stats"][uid] = s
    s.setdefault("total", 0)
    s.setdefault("week", 0)
    s.setdefault("month", 0)
    s.setdefault("week_key", _gc_week_key())
    s.setdefault("month_key", _gc_month_key())
    s.setdefault("kakera", 0)
    s.setdefault("last_win", None)
    # reset week/month counters if period changed
    wk_now = _gc_week_key()
    mo_now = _gc_month_key()
    if s.get("week_key") != wk_now:
        s["week_key"] = wk_now
        s["week"] = 0
    if s.get("month_key") != mo_now:
        s["month_key"] = mo_now
        s["month"] = 0
    return s


def _gc_normalize(text: str) -> str:
    """Lowercase + strip punctuation/spaces for fuzzy compare."""
    if not text:
        return ""
    text = text.lower()
    # remove emojis & special chars, keep letters/digits/space
    text = _gc_re.sub(r"[^\w\s]", " ", text, flags=_gc_re.UNICODE)
    text = _gc_re.sub(r"\s+", " ", text).strip()
    return text


def _gc_name_tokens(name: str) -> list:
    norm = _gc_normalize(name)
    if not norm:
        return []
    parts = [p for p in norm.split(" ") if p]
    return parts


def _gc_name_matches(guess: str, target_name: str) -> bool:
    """
    Accept either:
      • exact full name (case-insensitive, punctuation-stripped)
      • any single token (first / middle / last name) length>=2
    """
    g = _gc_normalize(guess)
    if not g:
        return False
    t = _gc_normalize(target_name)
    if not t:
        return False
    if g == t:
        return True
    # token match
    tokens = [p for p in t.split(" ") if len(p) >= 2]
    if g in tokens:
        return True
    # also accept guess as multi-word subset (e.g. "yor forger" matches "yor forger 🔞")
    if len(g.split()) >= 2 and g in t:
        return True
    return False


def _gc_get_rarities_dict():
    """Resolve RARITIES from the main module's globals (works regardless of order)."""
    try:
        return globals().get("RARITIES", {}) or {}
    except Exception:
        return {}


def _gc_get_bot():
    return globals().get("bot")


def _gc_get_locked_rarities() -> set:
    b = _gc_get_bot()
    if not b:
        return set()
    try:
        return {str(r) for r in (b.settings.get("locked_rarities", []) or [])}
    except Exception:
        return set()


def _gc_all_cards_dict() -> dict:
    b = _gc_get_bot()
    if not b:
        return {}
    try:
        return b.data.get("cards", {}) or {}
    except Exception:
        return {}


def _gc_pick_question_card() -> dict | None:
    """Pick a random card (any rarity, NOT locked) for the question image."""
    cards = _gc_all_cards_dict()
    if not cards:
        return None
    locked = _gc_get_locked_rarities()
    pool = []
    for cid, c in cards.items():
        if not isinstance(c, dict):
            continue
        if str(c.get("rarity", "1")) in locked:
            continue
        if not c.get("name") or not c.get("movie"):
            continue
        if not (c.get("image") or c.get("video")):
            continue
        pool.append((cid, c))
    if not pool:
        return None
    cid, card = _gc_random.choice(pool)
    return {"id": cid, **card}


def _gc_pick_reward_rarity() -> str | None:
    """Pick a rarity from UNLOCKED rarities using configured weights."""
    locked = _gc_get_locked_rarities()
    rarities = _gc_get_rarities_dict()
    weights_cfg = _GC_CACHE["settings"].get("rarity_chance", {}) or {}

    # Candidate rarities (in DB & unlocked)
    candidates = []
    weights = []
    for rk in rarities.keys():
        if str(rk) in locked:
            continue
        w = float(weights_cfg.get(str(rk), 0.0))
        if w <= 0:
            continue
        candidates.append(str(rk))
        weights.append(w)

    if not candidates:
        # Fallback: equal weight across all unlocked rarities that have cards
        cards = _gc_all_cards_dict()
        rk_set = set()
        for c in cards.values():
            if not isinstance(c, dict):
                continue
            rk = str(c.get("rarity", "1"))
            if rk not in locked:
                rk_set.add(rk)
        if not rk_set:
            return None
        return _gc_random.choice(list(rk_set))

    # Weighted random
    total = sum(weights)
    pick = _gc_random.uniform(0, total)
    cum = 0.0
    for rk, w in zip(candidates, weights):
        cum += w
        if pick <= cum:
            return rk
    return candidates[-1]


def _gc_pick_reward_card_id(rarity_key: str) -> str | None:
    """Pick a random card_id of the given rarity."""
    cards = _gc_all_cards_dict()
    pool = [cid for cid, c in cards.items()
            if isinstance(c, dict) and str(c.get("rarity", "1")) == str(rarity_key)]
    if not pool:
        return None
    return _gc_random.choice(pool)


def _gc_user_owns(uid: str, card_id: str) -> bool:
    b = _gc_get_bot()
    if not b:
        return False
    try:
        return str(card_id) in (b.data.get("users", {}).get(uid, []) or [])
    except Exception:
        return False


def _gc_grant_card(uid: str, card_id: str):
    b = _gc_get_bot()
    if not b:
        return
    try:
        b.data.setdefault("users", {}).setdefault(uid, [])
        if str(card_id) not in b.data["users"][uid]:
            b.data["users"][uid].append(str(card_id))
        b.save_data()
    except Exception as e:
        _GC_LOG.warning(f"[guess] grant card failed: {e}")


def _gc_grant_kakera(uid: str, amount: int):
    b = _gc_get_bot()
    if not b:
        return
    try:
        init_fn = globals().get("init_user_if_not_exists")
        if callable(init_fn):
            init_fn(uid)
        prof = b.data.setdefault("user_profiles", {}).setdefault(uid, {})
        prof["kakera"] = int(prof.get("kakera", 0)) + int(amount)
        b.save_data()
    except Exception as e:
        _GC_LOG.warning(f"[guess] grant kakera failed: {e}")
    # mirror inside guess stats
    s = _gc_ensure_user_stats(uid)
    s["kakera"] = int(s.get("kakera", 0)) + int(amount)
    _gc_save()


def _gc_rarity_display(rk: str) -> str:
    rarities = _gc_get_rarities_dict()
    info = rarities.get(str(rk), {})
    return info.get("display") or info.get("name") or f"Rarity {rk}"


def _gc_rarity_emoji(rk: str) -> str:
    rarities = _gc_get_rarities_dict()
    info = rarities.get(str(rk), {})
    return info.get("emoji", "⭐")


def _gc_rarity_name(rk: str) -> str:
    rarities = _gc_get_rarities_dict()
    info = rarities.get(str(rk), {})
    return info.get("name", f"Rarity {rk}")


def _gc_kakera_for_rarity(rk: str) -> int:
    table = _GC_CACHE["settings"].get("kakera_per_rarity", {}) or {}
    return int(table.get(str(rk), 100))


# ── Session model ────────────────────────────────────────────────────────
def _gc_new_session(chat_id: int, mode: str = "normal") -> dict:
    return {
        "chat_id": chat_id,
        "mode": mode,                 # "normal" / "hint" / "blur" / "silhouette" / "progressive" / "event"
        "card": None,
        "message_id": None,
        "started_at": None,
        "deadline_at": None,
        "active": False,
        "loop": True,                 # keep running until /stopg
        "task": None,                 # asyncio.Task for timeout
        "round_no": 0,
    }


def _gc_is_group(update: _GcUpdate) -> bool:
    chat = update.effective_chat
    if not chat:
        return False
    return chat.type in (_GcChatType.GROUP, _GcChatType.SUPERGROUP)


# ── Question delivery ────────────────────────────────────────────────────
async def _gc_send_question(context: _GcCtx.DEFAULT_TYPE, chat_id: int, session: dict) -> bool:
    """Pick a random card and send the question image."""
    card = _gc_pick_question_card()
    if not card:
        try:
            await context.bot.send_message(
                chat_id,
                "❌ No cards available in database for guess game."
            )
        except Exception:
            pass
        return False

    session["card"] = card
    session["round_no"] = int(session.get("round_no", 0)) + 1
    session["started_at"] = _gc_now().isoformat()
    rs = int(_GC_CACHE["settings"].get("round_seconds", 30))
    session["deadline_at"] = (_gc_now() + _gc_td(seconds=rs)).isoformat()
    session["active"] = True

    caption = (
        f"{'🎯'} <b>Guess &amp; Catch</b>\n\n"
        f"{'❓'} ဒီ Character ရဲ့ နာမည်ကို အရင်ဆုံး မှန်အောင် ရိုက်ပါ။\n\n"
        f"{'⏳'} Time Limit : <b>{rs} Seconds</b>\n"
        f"{'🏆'} Reward : Random Coins သို့မဟုတ် Diamonds"
    )

    try:
        if card.get("image"):
            msg = await context.bot.send_photo(
                chat_id=chat_id,
                photo=card["image"],
                caption=caption,
                parse_mode="HTML",
            )
        elif card.get("video"):
            msg = await context.bot.send_video(
                chat_id=chat_id,
                video=card["video"],
                caption=caption,
                parse_mode="HTML",
            )
        else:
            msg = await context.bot.send_message(chat_id, caption, parse_mode="HTML")
        session["message_id"] = getattr(msg, "message_id", None)
        return True
    except Exception as e:
        _GC_LOG.warning(f"[guess] send question failed: {e}")
        try:
            await context.bot.send_message(chat_id, f"⚠️ Could not send card image: {e}")
        except Exception:
            pass
        return False


async def _gc_timeout_watcher(context: _GcCtx.DEFAULT_TYPE, chat_id: int):
    """Background task: when round time runs out, announce timeout & start next round (if loop)."""
    try:
        rs = int(_GC_CACHE["settings"].get("round_seconds", 30))
        await _gc_asyncio.sleep(rs + 0.5)
        async with _GC_SESSION_LOCK:
            sess = _GC_SESSIONS.get(chat_id)
            if not sess or not sess.get("active"):
                return
            # If round is no longer the same (someone answered, started new), skip
            card = sess.get("card")
            if not card:
                return
            sess["active"] = False

        # Announce timeout
        try:
            ch_name = card.get("name", "?")
            mv_name = card.get("movie", "?")
            await context.bot.send_message(
                chat_id,
                f"{'⌛'} <b>Time\'s up!</b>\n\n"
                f"👤 <b>{ch_name}</b>\n"
                f"{'📺'} {mv_name}\n\n"
                f"{'❌'} မည်သူမှ မဖြေနိုင်ပါ။",
                parse_mode="HTML"
            )
        except Exception:
            pass

        # Continue loop if not stopped
        async with _GC_SESSION_LOCK:
            sess = _GC_SESSIONS.get(chat_id)
            if not sess or not sess.get("loop"):
                # cleanup
                if sess:
                    sess["task"] = None
                if chat_id in _GC_SESSIONS:
                    _GC_SESSIONS.pop(chat_id, None)
                return

        # small delay before next round
        await _gc_asyncio.sleep(2)
        async with _GC_SESSION_LOCK:
            sess = _GC_SESSIONS.get(chat_id)
            if not sess or not sess.get("loop"):
                return
        ok = await _gc_send_question(context, chat_id, sess)
        if ok:
            sess["task"] = _gc_asyncio.create_task(_gc_timeout_watcher(context, chat_id))
        else:
            async with _GC_SESSION_LOCK:
                _GC_SESSIONS.pop(chat_id, None)

    except _gc_asyncio.CancelledError:
        pass
    except Exception as e:
        _GC_LOG.warning(f"[guess] timeout watcher error: {e}")


# ── Commands: /guess  /stopg  /grank ─────────────────────────────────────
async def _gc_guess_cmd(update: _GcUpdate, context: _GcCtx.DEFAULT_TYPE):
    if not _gc_is_group(update):
        try:
            await update.effective_message.reply_text(
                "❌ Group Only\n\n"
                "🎯 /guess command ကို Group Chat ထဲမှာသာ သုံးနိုင်ပါတယ်။"
            )
        except Exception:
            pass
        return

    chat_id = update.effective_chat.id

    async with _GC_SESSION_LOCK:
        existing = _GC_SESSIONS.get(chat_id)
        if existing and existing.get("active"):
            try:
                await update.effective_message.reply_text(
                    "⚠️ Guess Event က ဒီ Group ထဲ run နေပါသေးတယ်။\n"
                    "ရပ်ချင်ရင် /stopg သုံးပါ။"
                )
            except Exception:
                pass
            return
        sess = _gc_new_session(chat_id, mode="normal")
        sess["loop"] = True
        _GC_SESSIONS[chat_id] = sess

    ok = await _gc_send_question(context, chat_id, sess)
    if not ok:
        async with _GC_SESSION_LOCK:
            _GC_SESSIONS.pop(chat_id, None)
        return

    sess["task"] = _gc_asyncio.create_task(_gc_timeout_watcher(context, chat_id))


async def _gc_stopg_cmd(update: _GcUpdate, context: _GcCtx.DEFAULT_TYPE):
    if not _gc_is_group(update):
        try:
            await update.effective_message.reply_text("❌ Group Only command")
        except Exception:
            pass
        return

    chat_id = update.effective_chat.id

    async with _GC_SESSION_LOCK:
        sess = _GC_SESSIONS.pop(chat_id, None)

    if not sess:
        try:
            await update.effective_message.reply_text("ℹ️ Guess Event run နေတာ မရှိပါ။")
        except Exception:
            pass
        return

    # Cancel timer
    sess["loop"] = False
    sess["active"] = False
    t = sess.get("task")
    if t and not t.done():
        try:
            t.cancel()
        except Exception:
            pass

    try:
        await update.effective_message.reply_text(
            f"{'🛑'} <b>Guess Event</b> ကို ရပ်လိုက်ပါပြီ။\n"
            f"ပြန်စချင်ရင် <code>/guess</code> ပြန်ရိုက်ပါ။",
            parse_mode="HTML"
        )
    except Exception:
        pass


async def _gc_grank_cmd(update: _GcUpdate, context: _GcCtx.DEFAULT_TYPE):
    """Show Top 10 by total / weekly / monthly wins."""
    args = context.args or []
    mode = "total"
    if args:
        a = args[0].lower()
        if a in ("week", "weekly", "w"):
            mode = "week"
        elif a in ("month", "monthly", "m"):
            mode = "month"
        elif a in ("total", "all", "t"):
            mode = "total"

    # refresh period rollover by ensuring each user
    stats = _GC_CACHE.get("stats", {}) or {}
    rows = []
    for uid, s in stats.items():
        if not isinstance(s, dict):
            continue
        # period-roll
        wk_now = _gc_week_key()
        mo_now = _gc_month_key()
        if s.get("week_key") != wk_now:
            s["week_key"] = wk_now
            s["week"] = 0
        if s.get("month_key") != mo_now:
            s["month_key"] = mo_now
            s["month"] = 0
        rows.append((uid, s))

    if mode == "week":
        rows.sort(key=lambda x: int(x[1].get("week", 0)), reverse=True)
        title = "📅 Weekly Guess Top"
        key = "week"
    elif mode == "month":
        rows.sort(key=lambda x: int(x[1].get("month", 0)), reverse=True)
        title = "📆 Monthly Guess Top"
        key = "month"
    else:
        rows.sort(key=lambda x: int(x[1].get("total", 0)), reverse=True)
        title = "🏆 Total Guess Top"
        key = "total"

    rows = [r for r in rows if int(r[1].get(key, 0)) > 0][:10]

    if not rows:
        try:
            await update.effective_message.reply_text(
                f"{title}\n\nမည်သူမှ မှတ်တမ်းမရှိသေးပါ။"
            )
        except Exception:
            pass
        _gc_save()
        return

    get_name_fn = globals().get("get_name")
    lines = [f"<b>{title}</b>", ""]
    medal = ['🥇', "🥈", "🥉"]
    for i, (uid, s) in enumerate(rows, start=1):
        try:
            nm = get_name_fn(uid) if callable(get_name_fn) else uid
        except Exception:
            nm = uid
        if not nm:
            nm = f"User {uid}"
        pre = medal[i - 1] if i <= 3 else f" {i}."
        lines.append(f"{pre} <b>{nm}</b> — {int(s.get(key,0))} wins {'🏆'}")

    try:
        await update.effective_message.reply_text("\n".join(lines), parse_mode="HTML")
    except Exception:
        pass
    _gc_save()


# ── Answer interceptor (group-only, plain text) ──────────────────────────
async def _gc_answer_listener(update: _GcUpdate, context: _GcCtx.DEFAULT_TYPE):
    try:
        if not _gc_is_group(update):
            return
        msg = update.effective_message
        if not msg or not msg.text:
            return
        text = msg.text.strip()
        if not text or text.startswith("/"):
            return

        chat_id = update.effective_chat.id
        sess = _GC_SESSIONS.get(chat_id)
        if not sess or not sess.get("active"):
            return

        card = sess.get("card")
        if not card:
            return

        target_name = card.get("name", "")
        if not _gc_name_matches(text, target_name):
            return

        # ✅ Correct answer
        async with _GC_SESSION_LOCK:
            # Re-check (race)
            sess2 = _GC_SESSIONS.get(chat_id)
            if not sess2 or not sess2.get("active") or sess2.get("card", {}).get("id") != card.get("id"):
                return
            sess2["active"] = False
            t = sess2.get("task")
            if t and not t.done():
                try:
                    t.cancel()
                except Exception:
                    pass
            sess2["task"] = None

        winner = update.effective_user
        uid = str(winner.id) if winner else "0"
        winner_name = (
            (winner.first_name if winner else None)
            or (winner.username if winner else None)
            or f"User {uid}"
        )

    # Update name cache (so /grank looks pretty)
        upd_cache = globals().get("update_name_cache")
        if callable(upd_cache):
            try:
                upd_cache(winner)
            except Exception:
                pass

        # Update guess stats
        s = _gc_ensure_user_stats(uid)
        s["total"] = int(s.get("total", 0)) + 1
        s["week"]  = int(s.get("week", 0))  + 1
        s["month"] = int(s.get("month", 0)) + 1
        s["last_win"] = _gc_now().isoformat()

        # Reward — card ပေးခြင်း မရှိတော့ပါ → coins သို့မဟုတ် diamonds ကျပန်းပေးမည်
        reward_text = ""
        try:
            give_coins = random.random() < 0.6
            if give_coins:
                amount = random.randint(200, 1200)
                _b = globals().get("bot")
                _prof = None
                _init = globals().get("init_user_if_not_exists")
                if callable(_init):
                    try:
                        _init(uid)
                    except Exception:
                        pass
                if _b is not None and hasattr(_b, "data"):
                    _prof = _b.data.get("user_profiles", {}).get(uid)
                if isinstance(_prof, dict):
                    _prof["coins"] = int(_prof.get("coins", 0) or 0) + amount
                    _prof["total_earned"] = int(_prof.get("total_earned", 0) or 0) + amount
                    try:
                        _b.save_data()
                    except Exception:
                        pass
                reward_text = (
                    "\n🎁 <b>Reward</b>\n\n"
                    f"🪙 +<b>{amount:,}</b> Coins"
                )
            else:
                amount = random.randint(50, 300)
                _gc_grant_kakera(uid, amount)
                reward_text = (
                    "\n🎁 <b>Reward</b>\n\n"
                    f"💎 +<b>{amount}</b> Diamonds"
                )
        except Exception as _e:
            _GC_LOG.warning(f"[guess] reward grant failed: {_e}")
            reward_text = ""

        _gc_save()

        ch_name = card.get("name", "?")
        mv_name = card.get("movie", "?")
        body = (
            f"{'🎉'} <b>{winner_name}</b> guessed it! {'✅'}\n\n"
            f"👤 <b>{ch_name}</b>\n"
            f"{'📺'} {mv_name}\n"
            f"{reward_text}"
        )

        try:
            await msg.reply_text(body, parse_mode="HTML")
        except Exception:
            try:
                await context.bot.send_message(chat_id, body, parse_mode="HTML")
            except Exception:
                pass

        # Continue loop if not stopped
        if sess.get("loop"):
            await _gc_asyncio.sleep(2)
            async with _GC_SESSION_LOCK:
                sess3 = _GC_SESSIONS.get(chat_id)
                if not sess3 or not sess3.get("loop"):
                    return
            ok = await _gc_send_question(context, chat_id, sess3)
            if ok:
                sess3["task"] = _gc_asyncio.create_task(_gc_timeout_watcher(context, chat_id))
            else:
                async with _GC_SESSION_LOCK:
                    _GC_SESSIONS.pop(chat_id, None)

    except Exception as e:
        _GC_LOG.warning(f"[guess] answer listener error: {e}")


# ═══════════════════════════════════════════════════════════════════════════════
# 🎁  DAILY STREAK UPGRADE  — wraps the existing daily_cmd, no original code edit
# ═══════════════════════════════════════════════════════════════════════════════

def _gc_streak_reward_for_day(day: int) -> dict:
    """Day 1..7 — recycles every 7 days."""
    streak_cfg = _GC_CACHE["settings"].get("daily_streak", {}) or {}
    idx = ((day - 1) % 7) + 1
    return streak_cfg.get(str(idx), {"type": "coins", "amount": 500})


def _gc_install_daily_streak_patch():
    """Replace daily_cmd in globals() with a wrapped version that adds streak rewards."""
    g = globals()
    if g.get("_gc_daily_patched"):
        return
    orig_daily = g.get("daily_cmd")
    if not callable(orig_daily):
        return  # nothing to patch (shouldn't happen)

    DAILY_REWARD_DEFAULT = int(g.get("DAILY_REWARD", 500))

    async def daily_cmd_streak(update: _GcUpdate, context: _GcCtx.DEFAULT_TYPE):
        b = _gc_get_bot()
        if b is None:
            return await orig_daily(update, context)

        user = update.effective_user
        uid = str(user.id) if user else "0"

        # gban
        is_gbanned = getattr(b, "is_gbanned", None)
        if callable(is_gbanned):
            try:
                if is_gbanned(user.id):
                    await update.message.reply_text("❌ You are globally banned.")
                    return
            except Exception:
                pass

        init_fn = g.get("init_user_if_not_exists")
        if callable(init_fn):
            init_fn(uid)

        profile = b.data["user_profiles"][uid]
        now = _gc_now()

        # cooldown check
        last_daily = profile.get("last_daily")
        if last_daily:
            try:
                last_dt = _gc_dt.fromisoformat(last_daily)
            except Exception:
                last_dt = None
            if last_dt:
                elapsed = now - last_dt
                cooldown = _gc_td(hours=24)
                if elapsed < cooldown:
                    remaining = cooldown - elapsed
                    total_secs = int(remaining.total_seconds())
                    hours = total_secs // 3600
                    minutes = (total_secs % 3600) // 60
                    streak_now = int(profile.get("daily_streak", 0))
                    try:
                        await update.message.reply_text(
                            "⏳ Daily not ready yet!\n\n"
                            f"💤 Wait {hours}h {minutes}m\n"
                            f"🔥 Current Streak : {streak_now} day(s)\n"
                            f"🪙 Coins: {int(profile.get('coins', 0)):,}"
                        )
                    except Exception:
                        pass
                    return

                # streak continuation logic
                # within 48h since last claim → streak +1, else reset
                if elapsed <= _gc_td(hours=48):
                    profile["daily_streak"] = int(profile.get("daily_streak", 0)) + 1
                else:
                    profile["daily_streak"] = 1
        else:
            profile["daily_streak"] = 1

        streak_day = int(profile.get("daily_streak", 1))
        reward = _gc_streak_reward_for_day(streak_day)

        # bookkeeping common
        profile["daily_claimed_days"] = int(profile.get("daily_claimed_days", 0)) + 1
        profile["last_daily"] = now.isoformat()

        # Apply reward
        reward_lines = []
        reward_type = reward.get("type", "coins")
        if reward_type == "coins":
            amount = int(reward.get("amount", DAILY_REWARD_DEFAULT))
            profile["coins"] = int(profile.get("coins", 0)) + amount
            profile["total_earned"] = int(profile.get("total_earned", 0)) + amount
            reward_lines.append(f"🪙 +{amount:,} Coins")
        elif reward_type == "card":
            forced_rarity = reward.get("rarity")
            picked_rarity = None
            picked_card_id = None
            locked = _gc_get_locked_rarities()

            if forced_rarity is not None and str(forced_rarity) not in locked:
                picked_rarity = str(forced_rarity)
                picked_card_id = _gc_pick_reward_card_id(picked_rarity)

            if not picked_card_id:
                # fallback: any unlocked rarity (weighted)
                picked_rarity = _gc_pick_reward_rarity()
                if picked_rarity:
                    picked_card_id = _gc_pick_reward_card_id(picked_rarity)

            if picked_card_id:
                reward_card = _gc_all_cards_dict().get(str(picked_card_id), {}) or {}
                r_name = reward_card.get("name", f"Card {picked_card_id}")
                r_emoji = _gc_rarity_emojemoji(picked_rarity)
                r_rarity_name = _gc_rarity_name(picked_rarity)
                if _gc_user_owns(uid, picked_card_id):
                    kak = _gc_kakera_for_rarity(picked_rarity)
                    _gc_grant_kakera(uid, kak)
                    reward_lines.append(
                        f"{r_emoji} {r_name}\n🌟 {r_rarity_name}\n"
                        f"❗ Already Owned → 💎 +{kak} Kakera"
                    )
                else:
                    _gc_grant_card(uid, picked_card_id)
                    reward_lines.append(
                        f"{r_emoji} {r_name}\n🌟 {r_rarity_name}\n"
                        f"🆕 Added to Collection"
                    )
            else:
                # nothing to give → fallback coins
                fallback = DAILY_REWARD_DEFAULT
                profile["coins"] = int(profile.get("coins", 0)) + fallback
                profile["total_earned"] = int(profile.get("total_earned", 0)) + fallback
                reward_lines.append(f"🪙 +{fallback:,} Coins (no card available)")
        else:
            # unknown → coins fallback
            fallback = DAILY_REWARD_DEFAULT
            profile["coins"] = int(profile.get("coins", 0)) + fallback
            profile["total_earned"] = int(profile.get("total_earned", 0)) + fallback
            reward_lines.append(f"🪙 +{fallback:,} Coins")

        try:
            b.save_data()
        except Exception:
            pass

        # Next preview
        next_day = streak_day + 1
        next_reward = _gc_streak_reward_for_day(next_day)
        if next_reward.get("type") == "coins":
            next_preview = f"Day {((next_day - 1) % 7) + 1} → {int(next_reward.get('amount', 500)):,} coins"
        else:
            if next_reward.get("rarity"):
                next_preview = f"Day {((next_day - 1) % 7) + 1} → {_gc_rarity_name(next_reward['rarity'])} Card"
            else:
                next_preview = f"Day {((next_day - 1) % 7) + 1} → Random Card"

        try:
            await update.message.reply_text(
                "🎁 Daily Reward!\n\n"
                f"👤 {user.first_name if user else ''}\n"
                f"🔥 Streak : Day {streak_day}\n\n"
                + "\n".join(reward_lines) +
                f"\n\n💰 Balance: {int(profile.get('coins', 0)):,} coins\n\n"
                "📅 Streak Schedule\n"
                "Day 1 → 500 coins\n"
                "Day 2 → 800 coins\n"
                "Day 3 → Random Card\n"
                "Day 4 → 1,500 coins\n"
                "Day 5 → 2,500 coins\n"
                "Day 6 → 4,000 coins\n"
                "Day 7 → Epic Card\n\n"
                f"➡️ Next : {next_preview}\n"
                "⏰ Come back in 24 hours"
            )
        except Exception:
            pass

    daily_cmd_streak.__name__ = "daily_cmd"
    g["daily_cmd"] = daily_cmd_streak
    g["_gc_daily_patched"] = True
    _GC_LOG.info("[guess] ✅ daily_cmd wrapped with streak system")


# ═══════════════════════════════════════════════════════════════════════════════
# 🔌  REGISTER HANDLERS (via existing _fa_register_handlers wrapper hook)
# ═══════════════════════════════════════════════════════════════════════════════

def _gc_register_handlers(application):
    try:
        application.add_handler(_GcCmd("guess", _gc_guess_cmd), group=-3)
        application.add_handler(_GcCmd("stopg", _gc_stopg_cmd), group=-3)
        application.add_handler(_GcCmd("grank", _gc_grank_cmd), group=-3)

        # plain-text listener for group answers — low priority so other handlers fire first
        application.add_handler(
            _GcMsg(_gc_filters.TEXT & (~_gc_filters.COMMAND) & _gc_filters.ChatType.GROUPS,
                   _gc_answer_listener),
            group=5
        )
        _GC_LOG.info("[guess] ✅ /guess /stopg /grank + answer listener registered")
    except Exception as e:
        _GC_LOG.error(f"[guess] register failed: {e}")


def _gc_install_main_wrapper():
    """Hook into main() so handlers register when the Application is built.

    This wraps the (possibly already-wrapped) main() function and the Application
    builder.build() so that BOTH the original FA register AND our register run.
    """
    g = globals()
    orig_main = g.get("main")
    if not callable(orig_main) or getattr(orig_main, "_gc_wrapped", False):
        return

    def wrapped_main():
        # Make sure the daily streak patch is installed before any handler fires
        try:
            _gc_install_daily_streak_patch()
        except Exception as e:
            _GC_LOG.warning(f"[guess] daily patch install failed: {e}")

        from telegram.ext import Application as _GcApp
        orig_build = _GcApp.builder().__class__.build

        def patched_build(self, *a, **kw):
            app_obj = orig_build(self, *a, **kw)
            try:
                _gc_register_handlers(app_obj)
            except Exception as e:
                _GC_LOG.error(f"[guess] register-in-build failed: {e}")
            _GcApp.builder().__class__.build = orig_build
            return app_obj

        _GcApp.builder().__class__.build = patched_build
        return orig_main()

    wrapped_main._gc_wrapped = True
    # Preserve flags from prior wrapper if present
    if getattr(orig_main, "_fa_wrapped", False):
        wrapped_main._fa_wrapped = True
    g["main"] = wrapped_main


_gc_install_main_wrapper()
# Also patch daily immediately in case main() already executed in some embed scenarios
try:
    _gc_install_daily_streak_patch()
except Exception:
    pass

# ═══════════════════════════════════════════════════════════════════════════════
#  END  GUESS & CATCH  +  DAILY STREAK PATCH
# ═══════════════════════════════════════════════════════════════════════════════


# ════════════════════════════════════════════════════════════════════════════
#  PREMIUM UI PATCH MODULE  —  /see + Top 10 Owners + Bold Unicode Fonts
#  Appended at the end of the file to preserve original structure.
#  Adds:
#    • Bold Unicode font helper (𝐏𝐑𝐎𝐅𝐈𝐋𝐄 style)
#    • Username-first / Telegram-ID fallback (no "Hidden User / Anonymous")
#    • Premium /see caption format:
#         <Anime / Movie Name>
#         <ID>: <Character Name> [emoji]
#         (🎗 RARITY: <Name>)
#         <rarity badge line>
#    • Premium box / spacing layout for the Top 10 Owners section.
# ════════════════════════════════════════════════════════════════════════════

try:
    # ---------- Bold Unicode (Mathematical Bold) font ----------
    def _bold_unicode(text: str) -> str:
        """Convert ASCII letters/digits to Mathematical Bold Unicode codepoints.
        Used for premium header titles (PROFILE, INVENTORY, MISSIONS, ...).
        Non-ASCII / symbols are passed through unchanged.
        """
        out = []
        for ch in str(text or ""):
            o = ord(ch)
            if 0x41 <= o <= 0x5A:        # A-Z  →  𝐀-𝐙
                out.append(chr(0x1D400 + (o - 0x41)))
            elif 0x61 <= o <= 0x7A:      # a-z  →  𝐚-𝐳
                out.append(chr(0x1D41A + (o - 0x61)))
            elif 0x30 <= o <= 0x39:      # 0-9  →  𝟎-𝟗
                out.append(chr(0x1D7CE + (o - 0x30)))
            else:
                out.append(ch)
        return "".join(out)

    # Quick pre-built premium header titles (cached for speed)
    BOLD = {
        "PROFILE":      _bold_unicode("PROFILE"),
        "INVENTORY":    _bold_unicode("INVENTORY"),
        "MISSIONS":     _bold_unicode("MISSIONS"),
        "CLAIM REWARD": _bold_unicode("CLAIM REWARD"),
        "LEADERBOARD":  _bold_unicode("LEADERBOARD"),
        "SHOP":         _bold_unicode("SHOP"),
        "COLLECTION":   _bold_unicode("COLLECTION"),
        "HAREM":        _bold_unicode("HAREM"),
        "TRADE":        _bold_unicode("TRADE"),
        "CARD DETAILS": _bold_unicode("CARD DETAILS"),
        "TOP 10 OWNERS":_bold_unicode("TOP 10 OWNERS"),
        "RARITY":       _bold_unicode("RARITY"),
        "CAUGHT GLOBALLY": _bold_unicode("CAUGHT GLOBALLY"),
        "OWNERS":       _bold_unicode("OWNERS"),
        "TIMES":        _bold_unicode("TIMES"),
    }

    # Public helper so other future patches can reuse it
    globals()['bold_unicode'] = _bold_unicode
    globals()['BOLD'] = BOLD

    # ---------- Username-first display resolver ----------
    def _resolve_owner_display(uid_str: str, cached_name: str | None) -> str:
        """Return what to render for a card owner in the Top-10 list.

        Rules (per user spec):
          1. If we have a *real* Username / display name in cache → show it.
          2. Else → show the raw Telegram numeric ID (NEVER "Hidden User",
             "Anonymous" or "Unknown User").
        """
        bad = {"", "unknown", "unknown user", "hidden user",
               "anonymous", "none", "null"}
        name = (cached_name or "").strip()
        if name and name.lower() not in bad:
            return name
        # Fallback → raw Telegram ID
        return str(uid_str)

    globals()['resolve_owner_display'] = _resolve_owner_display

    # ---------- Rarity badge line (💠Sacred💠 etc.) ----------
    def _rarity_badge_line(rarity_info: dict) -> str:
        """Build the second rarity line, e.g. '💠Sacred💠'.

        Uses the rarity's own emoji + display name when available,
        falling back to a neutral diamond badge.
        """
        try:
            emoji = (rarity_info.get('emoji')
                     or rarity_info.get('icon')
                     or '💠')
            name  = (rarity_info.get('name')
                     or rarity_info.get('label')
                     or 'Sacred')
            # Use only the first emoji character to keep the line tight
            return f"{emoji}{name}{emoji}"
        except Exception:
            return "💠Sacred💠"

    globals()['rarity_badge_line'] = _rarity_badge_line

    # ---------- Premium /see implementation ----------
    async def _see_cmd_premium(update, context):
        """Premium /see command — new caption layout + premium Top-10 owners."""
        if not context.args:
            await update.message.reply_text("📝 /see <card_id>")
            return

        card_id = str(context.args[0]).strip()

        if card_id not in bot.data.get('cards', {}):
            await update.message.reply_text("❌ Card မရှိပါ")
            return

        card = bot.data['cards'][card_id]

        # ---- collect owners ----
        owners_info = []  # (uid_str, display_text, count)
        for uid_str, cards in bot.data.get('users', {}).items():
            if card_id in cards:
                count = cards.count(card_id)

                owner_name = get_name(uid_str)
                if owner_name == "Unknown":
                    # fallback: scan card metadata for a stored owner_name
                    for c in bot.data.get('cards', {}).values():
                        if str(c.get('owner')) == str(uid_str):
                            cand = c.get('owner_name', 'Unknown')
                            if cand and cand != 'Unknown':
                                owner_name = cand
                                USER_CACHE[str(uid_str)] = owner_name
                            break

                display = _resolve_owner_display(uid_str, owner_name)
                owners_info.append((str(uid_str), display, count, owner_name))

        # Sort by count desc (stable)
        owners_info.sort(key=lambda x: x[2], reverse=True)

        total_caught  = sum(c for _, _, c, _ in owners_info)
        unique_owners = len(owners_info)

        owners_show = owners_info[:10]

        rarity      = str(card.get('rarity', '1'))
        rarity_info = RARITIES.get(rarity, RARITIES['1'])
        role_info   = get_role_info(card)

        # ---- Build Top 10 Owners block (CLEAN /see redesign) ----
        char_name  = card.get('name', '') or ''
        anime_name = card.get('movie', '') or card.get('anime', '') or ''
        char_id    = card.get('id', card_id)

        caption_lines = [f"🎴 {char_id}  ─  {_md_escape(char_name)}", ""]
        if anime_name:
            caption_lines.append(f"🎬 {_md_escape(anime_name)}")
        caption_lines.append(f"{rarity_info['display']}  •  {role_info['display']}")
        caption_lines.append("")
        caption_lines.append(f"🌍 {total_caught} Caught   👥 {unique_owners} Owners")
        caption_lines.append("")

        if unique_owners == 0:
            caption_lines.append("🏆 TOP OWNERS")
            caption_lines.append("🕊 No owners yet — be the first!")
        else:
            caption_lines.append("🏆 TOP OWNERS")
            _medals = {1: "🥇", 2: "🥈", 3: "🥉"}
            for _idx, (uid_str, display, count, raw_name) in enumerate(owners_show, 1):
                _badge = _medals.get(_idx, f"{_idx}.")
                _bad = {"", "unknown", "unknown user", "hidden user",
                        "anonymous", "none", "null"}
                if (raw_name or "").strip().lower() not in _bad:
                    try:
                        _disp = f"[{_md_escape(display)}](tg://user?id={int(uid_str)})"
                    except Exception:
                        _disp = _md_escape(display)
                else:
                    _disp = _md_escape(str(uid_str))
                caption_lines.append(f"{_badge} {_disp} ×{count}")

        caption = "\n".join(caption_lines)

        try:
            if card.get('type') == 'video':
                if card.get('video_type') == 'video':
                    await update.message.reply_video(
                        video=card['video'], caption=caption, parse_mode='Markdown')
                else:
                    await update.message.reply_document(
                        document=card['video'], caption=caption, parse_mode='Markdown')
            else:
                await update.message.reply_photo(
                    photo=card['image'], caption=caption, parse_mode='Markdown')
        except Exception as e:
            try:
                logger.error(f"/see send failed: {e}")
            except Exception:
                pass
            await update.message.reply_text(caption, parse_mode='Markdown')

    globals()['_see_cmd_premium'] = _see_cmd_premium

    try:
        logger.info("[premium-ui] /see patched → username-first + premium layout")
    except Exception:
        pass

except Exception as _premium_patch_err:
    try:
        logger.error(f"[premium-ui] patch failed: {_premium_patch_err}")
    except Exception:
        print(f"[premium-ui] patch failed: {_premium_patch_err}")

