import html as _premium_html


# ─── Bold Unicode font converter (Mathematical Sans-Serif Bold) ───
# Telegram သာ rendering လုပ်နိုင်တဲ့ Unicode Bold characters
_BOLD_MAP = {}
def _build_bold_map():
    # Mathematical Sans-Serif Bold  A-Z (U+1D5D4 - U+1D5ED)
    for i, c in enumerate("ABCDEFGHIJKLMNOPQRSTUVWXYZ"):
        _BOLD_MAP[c] = chr(0x1D5D4 + i)
    # a-z (U+1D5EE - U+1D607)
    for i, c in enumerate("abcdefghijklmnopqrstuvwxyz"):
        _BOLD_MAP[c] = chr(0x1D5EE + i)
    # 0-9 (U+1D7EC - U+1D7F5)
    for i, c in enumerate("0123456789"):
        _BOLD_MAP[c] = chr(0x1D7EC + i)

_build_bold_map()


def _bold_unicode(text: str) -> str:
    """Convert ASCII letters/digits in text to Mathematical Sans-Serif Bold.
    Non-ASCII characters (Japanese, Burmese, etc.) are kept as-is.
    """
    if not text:
        return ""
    return "".join(_BOLD_MAP.get(ch, ch) for ch in str(text))


# ─── Symmetric double-emoji display helpers ───
def _premium_role_display(role_info: dict) -> str:
    """🎄 Christmas 🎄 style — same emoji on both sides."""
    if not isinstance(role_info, dict):
        return ""
    emoji = role_info.get('emoji', '🎴')
    name = role_info.get('name', 'Normal')
    return f"{emoji} {name} {emoji}"


def _premium_rarity_display(rarity_info: dict) -> str:
    """🔮 Legendary 🔮 style — same emoji on both sides."""
    if not isinstance(rarity_info, dict):
        return ""
    emoji = rarity_info.get('emoji', '💮')
    name = rarity_info.get('name', 'Common')
    return f"{emoji} {name} {emoji}"


# ─── HTML mention helper (cleaner than markdown for channel posts) ───
def _premium_mention_html(user_id, name) -> str:
    safe_name = _premium_html.escape(str(name or "User"))
    if user_id:
        try:
            uid = int(user_id)
            return f'<a href="tg://user?id={uid}">{safe_name}</a>'
        except Exception:
            pass
    return safe_name


