# ═══════════════════════════════════════════════════════════════════════
# 🔎 /wa  COMMAND  MODULE  —  Reply-to-media Card Finder by File ID
# ───────────────────────────────────────────────────────────────────────
# Feature: User replies to a card photo / video / document / forwarded
# message and runs "/wa".  The bot extracts the media file_id (and the
# stable file_unique_id) and looks it up in the in-memory cards DB
# (bot.data['cards']).  If found, it shows a cool premium-styled card
# summary; otherwise it shows a "Card Not Found" notice.
#
# Storage backend:
#   - This bot uses a JSON-based DB (bot.data) — NOT MongoDB.
#   - File IDs are ALREADY stored on each card via the existing upload
#     handlers as:  card['image']  (photo)  or  card['video']  (video /
#     document).  No schema migration is required.
#   - For extra robustness across file_id changes, this module ALSO
#     maintains an optional file_unique_id index — populated lazily on
#     first /wa call and on the fly when new cards are uploaded.
#
# Framework: python-telegram-bot v20+  (the same framework the rest of
# this file uses).  Note: although the user's brief mentions Pyrogram,
# the original bot is written in python-telegram-bot, so this module
# is implemented in PTB to remain drop-in compatible.
# ═══════════════════════════════════════════════════════════════════════
try:
    from telegram import Update as _WA_Update  # type: ignore
    from telegram.ext import (
        Application as _WA_App,
        CommandHandler as _WA_CmdH,
        ContextTypes as _WA_Ctx,
    )
except Exception:  # pragma: no cover - PTB is required by the host file
    _WA_Update = None  # type: ignore
    _WA_App = None  # type: ignore
    _WA_CmdH = None  # type: ignore
    _WA_Ctx = None  # type: ignore


# ── Channel join footer (matches the user's spec) ──
_WA_JOIN_HANDLE = "@officalzcko"

# ── Cache for fast lookup by file_unique_id (built lazily) ──
_WA_UNIQUE_INDEX: dict[str, str] = {}     # file_unique_id -> card_id
_WA_FILE_ID_INDEX: dict[str, str] = {}    # file_id        -> card_id
_WA_INDEX_BUILT = False


def _wa_safe_logger():
    try:
        return logger  # type: ignore[name-defined]
    except Exception:
        import logging as _lg
        return _lg.getLogger("wa_module")


def _wa_get_cards_db() -> dict:
    """Return the cards dictionary from the running bot, safely."""
    try:
        return bot.data.get('cards', {}) or {}  # type: ignore[name-defined]
    except Exception:
        return {}


def _wa_card_file_id(card: dict) -> str | None:
    """Return the primary file_id stored on a card (image or video)."""
    if not isinstance(card, dict):
        return None
    fid = card.get('image') or card.get('video')
    if fid:
        return str(fid)
    return None


def _wa_build_index(force: bool = False) -> None:
    """Build / refresh the file_id → card_id index from current DB."""
    global _WA_INDEX_BUILT
    if _WA_INDEX_BUILT and not force:
        return
    _WA_FILE_ID_INDEX.clear()
    _WA_UNIQUE_INDEX.clear()
    try:
        for cid, card in _wa_get_cards_db().items():
            if not isinstance(card, dict):
                continue
            fid = _wa_card_file_id(card)
            if fid:
                _WA_FILE_ID_INDEX[fid] = str(cid)
            # Optional unique_id (only present if recorded at upload time)
            uid = card.get('file_unique_id') or card.get('media_unique_id')
            if uid:
                _WA_UNIQUE_INDEX[str(uid)] = str(cid)
        _WA_INDEX_BUILT = True
    except Exception as e:
        _wa_safe_logger().error(f"[/wa] index build failed: {e}")


def _wa_extract_media_ids(message) -> tuple[str | None, str | None, str]:
    """Return (file_id, file_unique_id, media_kind) from a Telegram message.

    media_kind ∈ {'photo','video','animation','document','sticker',''}.
    Falls back across all common media types so forwarded messages work.
    """
    if message is None:
        return None, None, ''

    # Photo (take the largest size — Telegram lists them ascending)
    photos = getattr(message, 'photo', None)
    if photos:
        try:
            p = photos[-1]
            return str(getattr(p, 'file_id', '')), str(getattr(p, 'file_unique_id', '') or ''), 'photo'
        except Exception:
            pass

    # Video
    video = getattr(message, 'video', None)
    if video:
        return str(getattr(video, 'file_id', '')), str(getattr(video, 'file_unique_id', '') or ''), 'video'

    # Animation (GIF / mp4 animations — many video cards use this)
    animation = getattr(message, 'animation', None)
    if animation:
        return str(getattr(animation, 'file_id', '')), str(getattr(animation, 'file_unique_id', '') or ''), 'animation'

    # Document (video_type == 'document' cards land here)
    document = getattr(message, 'document', None)
    if document:
        return str(getattr(document, 'file_id', '')), str(getattr(document, 'file_unique_id', '') or ''), 'document'

    # Sticker (rare, but supported defensively)
    sticker = getattr(message, 'sticker', None)
    if sticker:
        return str(getattr(sticker, 'file_id', '')), str(getattr(sticker, 'file_unique_id', '') or ''), 'sticker'

    # Video note
    video_note = getattr(message, 'video_note', None)
    if video_note:
        return str(getattr(video_note, 'file_id', '')), str(getattr(video_note, 'file_unique_id', '') or ''), 'video_note'

    return None, None, ''


def _wa_lookup_card(file_id: str | None, file_unique_id: str | None) -> tuple[str | None, dict | None]:
    """Find a card by file_id (primary) then file_unique_id (fallback).

    Returns (card_id, card_dict) or (None, None).
    """
    cards_db = _wa_get_cards_db()
    if not cards_db:
        return None, None

    # Ensure cache is warm
    _wa_build_index(force=False)

    # 1) Fast path: file_id index
    if file_id and file_id in _WA_FILE_ID_INDEX:
        cid = _WA_FILE_ID_INDEX[file_id]
        card = cards_db.get(cid)
        if isinstance(card, dict):
            return str(cid), card

    # 2) Fast path: file_unique_id index
    if file_unique_id and file_unique_id in _WA_UNIQUE_INDEX:
        cid = _WA_UNIQUE_INDEX[file_unique_id]
        card = cards_db.get(cid)
        if isinstance(card, dict):
            return str(cid), card

    # 3) Slow path: linear scan (covers cards added since last index build)
    target_fid = str(file_id) if file_id else None
    target_uid = str(file_unique_id) if file_unique_id else None
    for cid, card in cards_db.items():
        if not isinstance(card, dict):
            continue
        cfid = _wa_card_file_id(card)
        if target_fid and cfid and cfid == target_fid:
            # Warm the cache for next time
            _WA_FILE_ID_INDEX[cfid] = str(cid)
            return str(cid), card
        cuid = card.get('file_unique_id') or card.get('media_unique_id')
        if target_uid and cuid and str(cuid) == target_uid:
            _WA_UNIQUE_INDEX[str(cuid)] = str(cid)
            return str(cid), card

    return None, None


def _wa_role_emoji(card: dict) -> str:
    """Return a short emoji tag for the card's role (e.g. [🧹]).
    Tries to reuse the existing helpers if available; otherwise stays safe.
    """
    try:
        info = get_role_info(card) or {}  # type: ignore[name-defined]
        emoji = info.get('emoji') or info.get('icon') or ''
        if emoji:
            return f"[{emoji}]"
    except Exception:
        pass
    # Fallback: try direct fields on the card
    e = card.get('role_emoji') or card.get('emoji')
    if e:
        return f"[{e}]"
    return ''


def _wa_first_hint_word(name: str) -> str:
    """Pick the first meaningful word from a card name for /ziceko hint."""
    if not name:
        return ''
    cleaned = []
    for ch in name:
        if ch.isalnum() or ch in (' ', '-', "'", '_'):
            cleaned.append(ch)
    base = ''.join(cleaned).strip()
    parts = base.split()
    return parts[0].lower() if parts else base.lower()


def _wa_format_found_caption(card_id: str, card: dict) -> str:
    """Build the cool UI message shown when a card is matched."""
    name = str(card.get('name', '') or 'Unknown').strip() or 'Unknown'
    role_tag = _wa_role_emoji(card)
    title = f"{name} {role_tag}".strip()

    hint_word = _wa_first_hint_word(name)
    full_name = f"{name} {role_tag}".strip()

    movie = str(card.get('movie', '') or '').strip()
    rarity = ''
    try:
        # Best-effort, reuse global RARITIES if present
        rkey = str(card.get('rarity', '') or '')
        rarity_info = RARITIES.get(rkey, {}) if 'RARITIES' in globals() else {}  # type: ignore[name-defined]
        rarity = rarity_info.get('display', '') if isinstance(rarity_info, dict) else ''
    except Exception:
        rarity = ''

    lines: list[str] = []
    lines.append(f"<b>NAME</b> : {title}")
    lines.append("━━━━━━━━━━━━━━━━━━")
    if hint_word:
        lines.append(f"🔹 <b>Hint</b> : <code>/ziceko {hint_word}</code>")
    lines.append(f"🔸 <b>Full</b> : <code>/ziceko {full_name}</code>")
    if movie:
        lines.append(f"🎞 <b>From</b> : {movie}")
    if rarity:
        lines.append(f"⭐ <b>Rarity</b> : {rarity}")
    lines.append(f"🆔 <b>Card ID</b> : <code>{card_id}</code>")
    lines.append("")
    lines.append(f"🔗 join - {_WA_JOIN_HANDLE}")
    return "\n".join(lines)


def _wa_format_not_found_caption(media_kind: str) -> str:
    kind = media_kind or 'media'
    return (
        "❌ <b>Card Not Found</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"This {kind} does not match any saved card in the database.\n"
        "• Make sure you replied to an original card upload.\n"
        "• Forwarded copies of the same media should also match.\n"
        "\n"
        f"🔗 join - {_WA_JOIN_HANDLE}"
    )


def _wa_format_usage_caption() -> str:
    return (
        "📌 <b>Usage</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "Reply to a card <b>photo</b>, <b>video</b>, <b>animation</b> or "
        "<b>document</b> with the command:\n"
        "<code>/wa</code>\n\n"
        "The bot will look up the media in the card database and show "
        "the matching card name.\n"
        "\n"
        f"🔗 join - {_WA_JOIN_HANDLE}"
    )


async def wa_cmd(update, context):  # type: ignore[no-redef]
    """/wa — reply-to-media → card lookup by file_id."""
    try:
        message = getattr(update, 'message', None)
        if message is None:
            return

        # Global bans / locks: reuse existing checks when available
        try:
            uid = update.effective_user.id if update.effective_user else 0
            if 'bot' in globals() and hasattr(bot, 'is_gbanned') and bot.is_gbanned(uid):  # type: ignore[name-defined]
                await message.reply_text("❌ You are globally banned.")
                return
        except Exception:
            pass

        reply = getattr(message, 'reply_to_message', None)
        if reply is None:
            await message.reply_text(
                _wa_format_usage_caption(),
                parse_mode='HTML',
            )
            return

        file_id, file_unique_id, media_kind = _wa_extract_media_ids(reply)
        if not file_id:
            await message.reply_text(
                "⚠️ <b>No media found</b> in the replied message.\n"
                "Reply to a photo / video / animation / document and try again.",
                parse_mode='HTML',
            )
            return

        card_id, card = _wa_lookup_card(file_id, file_unique_id)
        if not card:
            await message.reply_text(
                _wa_format_not_found_caption(media_kind),
                parse_mode='HTML',
            )
            return

        caption = _wa_format_found_caption(card_id, card)

        # Try to echo the same media back with the cool caption.
        # Falls back to plain text on any failure to stay robust.
        try:
            if card.get('image'):
                await message.reply_photo(
                    photo=card['image'], caption=caption, parse_mode='HTML'
                )
                return
            if card.get('video'):
                vtype = str(card.get('video_type', 'video') or 'video').lower()
                if vtype == 'document':
                    await message.reply_document(
                        document=card['video'], caption=caption, parse_mode='HTML'
                    )
                else:
                    await message.reply_video(
                        video=card['video'], caption=caption, parse_mode='HTML'
                    )
                return
        except Exception as media_err:
            _wa_safe_logger().warning(f"[/wa] media echo failed, falling back to text: {media_err}")

        await message.reply_text(caption, parse_mode='HTML')

    except Exception as e:
        _wa_safe_logger().error(f"[/wa] handler error: {e}")
        try:
            await update.message.reply_text(
                "⚠️ Something went wrong while processing /wa. Please try again.",
            )
        except Exception:
            pass


# ── Optional: hook into uploads so newly added cards get their
#    file_unique_id recorded automatically (best-effort, no-op on error).
def _wa_observe_new_card(card_id: str, card: dict, file_unique_id: str | None) -> None:
    try:
        if not isinstance(card, dict):
            return
        if file_unique_id and not card.get('file_unique_id'):
            card['file_unique_id'] = str(file_unique_id)
            try:
                bot.save_data()  # type: ignore[name-defined]
            except Exception:
                pass
        fid = _wa_card_file_id(card)
        if fid:
            _WA_FILE_ID_INDEX[fid] = str(card_id)
        if file_unique_id:
            _WA_UNIQUE_INDEX[str(file_unique_id)] = str(card_id)
    except Exception:
        pass


# ── Register the /wa handler via the same monkey-patch pattern the
#    other upgrade modules in this file already use. ──
def _wa_register_handlers(application) -> None:
    try:
        if _WA_CmdH is None:
            return
        application.add_handler(_WA_CmdH('wa', wa_cmd), group=-3)
        try:
            logger.info("[/wa] ✅ Reply-to-media card finder registered")  # type: ignore[name-defined]
        except Exception:
            pass
    except Exception as e:
        try:
            logger.error(f"[/wa] register failed: {e}")  # type: ignore[name-defined]
        except Exception:
            pass


def _wa_install_main_wrapper() -> None:
    g = globals()
    orig_main = g.get("main")
    if not callable(orig_main) or getattr(orig_main, "_wa_wrapped", False):
        return

    def wrapped_main():  # noqa: D401
        try:
            from telegram.ext import Application as _WAMS_App  # type: ignore
        except Exception:
            return orig_main()

        orig_build = _WAMS_App.builder().__class__.build

        def patched_build(self, *a, **kw):
            app_obj = orig_build(self, *a, **kw)
            try:
                _wa_register_handlers(app_obj)
            except Exception as e:
                try:
                    logger.error(f"[/wa] register-in-build failed: {e}")  # type: ignore[name-defined]
                except Exception:
                    pass
            _WAMS_App.builder().__class__.build = orig_build
            return app_obj

        _WAMS_App.builder().__class__.build = patched_build
        return orig_main()

    wrapped_main._wa_wrapped = True  # type: ignore[attr-defined]
    g["main"] = wrapped_main


_wa_install_main_wrapper()
# ═══════════════════════════════════════════════════════════════════════
#  END  /wa  COMMAND  MODULE
# ═══════════════════════════════════════════════════════════════════════


# ═══════════════════════════════════════════════════════════════════════
#  BLACK MARKET — IMMORTAL SHOP SYSTEM + /diamonds + /adddiamond + /wa fix
#  -----------------------------------------------------------------------
#  • Uses existing 💎 Diamonds (stored in user_profiles[uid]["kakera"])
#  • Sells ONLY Immortal (rarity '14') cards from the existing card DB
#  • Reuses existing inventory (bot.data["users"][uid] list of card_ids)
#  • Base price = 100,000,000,000,000  💎
#  • Each purchase of a card doubles that card's price (per-card counter)
#  • Same Bot UI / Callback style as the rest of the file
#  • Also installs a robust /wa register hook (post_init) — fixes the
#    "command not responding" issue caused by builder-class wrapping order.
# ═══════════════════════════════════════════════════════════════════════
try:
    from telegram.ext import (
        Application as _IM_App,
        CommandHandler as _IM_CmdH,
        CallbackQueryHandler as _IM_CbH,
        ContextTypes as _IM_Ctx,
    )
    from telegram import (
        InlineKeyboardButton as _IM_IKB,
        InlineKeyboardMarkup as _IM_IKM,
        Update as _IM_Update,
    )
except Exception:  # pragma: no cover
    _IM_App = None  # type: ignore
    _IM_CmdH = None  # type: ignore
    _IM_CbH = None  # type: ignore
    _IM_Ctx = None  # type: ignore
    _IM_IKB = None  # type: ignore
    _IM_IKM = None  # type: ignore
    _IM_Update = None  # type: ignore


# ── Constants ──────────────────────────────────────────────────────────
_IM_IMMORTAL_RARITY = "14"          # Immortal rarity key in RARITIES
_IM_BASE_PRICE = 100_000_000_000_000  # 100 Trillion 💎
_IM_JOIN_HANDLE = "@officalzcko"
_IM_PAGE_SIZE = 6                    # cards per page in /blackmarketshop


def _im_safe_logger():
    try:
        return logger  # type: ignore[name-defined]
    except Exception:
        import logging as _lg
        return _lg.getLogger("immortal_shop")


# ── Helpers: bot data accessors ────────────────────────────────────────
def _im_bot():
    try:
        return bot  # type: ignore[name-defined]
    except Exception:
        return None


def _im_init_user(uid: str) -> None:
    """Use existing init_user_if_not_exists if available, otherwise minimal init."""
    try:
        fn = globals().get("init_user_if_not_exists")
        if callable(fn):
            fn(str(uid))
            return
    except Exception:
        pass
    b = _im_bot()
    if not b:
        return
    b.data.setdefault("users", {}).setdefault(str(uid), [])
    b.data.setdefault("user_profiles", {}).setdefault(str(uid), {})


def _im_get_diamonds(uid: str) -> int:
    """Return the user's 💎 Diamond balance (kakera field)."""
    b = _im_bot()
    if not b:
        return 0
    _im_init_user(uid)
    try:
        prof = b.data.get("user_profiles", {}).get(str(uid), {}) or {}
        return int(prof.get("kakera", 0) or 0)
    except Exception:
        return 0


def _im_add_diamonds(uid: str, amount: int) -> int:
    """Add (or subtract) diamonds; returns new balance."""
    b = _im_bot()
    if not b:
        return 0
    _im_init_user(uid)
    prof = b.data.setdefault("user_profiles", {}).setdefault(str(uid), {})
    new_bal = int(prof.get("kakera", 0) or 0) + int(amount)
    if new_bal < 0:
        new_bal = 0
    prof["kakera"] = new_bal
    try:
        b.save_data()
    except Exception:
        pass
    return new_bal


def _im_get_purchase_counts() -> dict:
    """Per-card purchase counter store (in bot.data)."""
    b = _im_bot()
    if not b:
        return {}
    return b.data.setdefault("immortal_shop_counts", {})


def _im_card_price(card_id: str) -> int:
    """current_price = base_price * (2 ** purchase_count)."""
    counts = _im_get_purchase_counts()
    n = int(counts.get(str(card_id), 0) or 0)
    # Cap exponent to keep it sane (still astronomically high)
    if n > 60:
        n = 60
    return _IM_BASE_PRICE * (2 ** n)


def _im_inc_purchase_count(card_id: str) -> int:
    counts = _im_get_purchase_counts()
    n = int(counts.get(str(card_id), 0) or 0) + 1
    counts[str(card_id)] = n
    b = _im_bot()
    if b:
        try:
            b.save_data()
        except Exception:
            pass
    return n


def _im_all_immortal_cards() -> list[tuple[str, dict]]:
    """Return list of (card_id, card) for every Immortal-rarity card in DB."""
    b = _im_bot()
    if not b:
        return []
    out: list[tuple[str, dict]] = []
    for cid, c in (b.data.get("cards", {}) or {}).items():
        if isinstance(c, dict) and str(c.get("rarity", "")) == _IM_IMMORTAL_RARITY:
            out.append((str(cid), c))
    # Sort by numeric id when possible
    def _sort_key(item):
        try:
            return (0, int(item[0]))
        except Exception:
            return (1, item[0])
    out.sort(key=_sort_key)
    return out


def _im_resolve_user_arg(update, context) -> tuple[int | None, str | None]:
    """
    Resolve target user from:
      1) reply_to_message
      2) numeric id arg
      3) @username arg
    Returns (target_id, target_name).
    """
    msg = getattr(update, "message", None)

    # 1) Reply
    try:
        if msg and msg.reply_to_message and msg.reply_to_message.from_user:
            ru = msg.reply_to_message.from_user
            if ru and not ru.is_bot:
                return int(ru.id), (ru.first_name or ru.username or str(ru.id))
    except Exception:
        pass

    # 2/3) Arg
    if context and getattr(context, "args", None):
        arg = (context.args[0] or "").strip().lstrip("@")
        if arg.isdigit():
            try:
                tid = int(arg)
                try:
                    cache = USER_CACHE  # type: ignore[name-defined]
                    name = cache.get(str(tid)) or f"User {tid}"
                except Exception:
                    name = f"User {tid}"
                return tid, name
            except Exception:
                return None, None
        else:
            # username — best-effort via context.bot.get_chat
            try:
                import asyncio as _aio
                # cannot await here (sync helper). Return marker, caller will handle.
                return None, arg
            except Exception:
                return None, None
    return None, None


# ── Number formatting ──────────────────────────────────────────────────
def _im_fmt(n: int) -> str:
    try:
        return f"{int(n):,}"
    except Exception:
        return str(n)


def _im_short_price(n: int) -> str:
    """Compact form like 100T, 200T, 1.6Qa etc."""
    units = [
        (10**18, "Qi"),  # Quintillion
        (10**15, "Qa"),  # Quadrillion
        (10**12, "T"),   # Trillion
        (10**9,  "B"),
        (10**6,  "M"),
        (10**3,  "K"),
    ]
    for v, suf in units:
        if n >= v:
            q = n / v
            if q >= 100:
                return f"{q:.0f}{suf}"
            if q >= 10:
                return f"{q:.1f}{suf}"
            return f"{q:.2f}{suf}"
    return str(n)


def _im_rarity_display() -> str:
    try:
        info = RARITIES.get(_IM_IMMORTAL_RARITY, {})  # type: ignore[name-defined]
        return info.get("display", "🪞 Immortal")
    except Exception:
        return "🪞 Immortal"


# ── UI Builders ────────────────────────────────────────────────────────
def _im_build_shop_page(page: int) -> tuple[str, object]:
    """Build text + keyboard for a given shop page."""
    cards = _im_all_immortal_cards()
    total = len(cards)
    pages = max(1, (total + _IM_PAGE_SIZE - 1) // _IM_PAGE_SIZE)
    page = max(0, min(page, pages - 1))

    start = page * _IM_PAGE_SIZE
    end = start + _IM_PAGE_SIZE
    slice_ = cards[start:end]

    rdisp = _im_rarity_display()

    lines: list[str] = []
    lines.append("🏴‍☠️ <b>BLACK MARKET — IMMORTAL SHOP</b>")
    lines.append("━━━━━━━━━━━━━━━━━━━━━━━━")
    lines.append(f"⭐ Rarity : {rdisp}")
    lines.append(f"💎 Base   : <code>{_im_fmt(_IM_BASE_PRICE)}</code>")
    lines.append("📈 <i>Price doubles after every purchase</i>")
    lines.append("━━━━━━━━━━━━━━━━━━━━━━━━")

    if total == 0:
        lines.append("")
        lines.append("❌ No Immortal cards available in the database yet.")
        lines.append("")
        lines.append(f"🔗 join - {_IM_JOIN_HANDLE}")
        kb_rows: list[list[object]] = []
        kb_rows.append([_IM_IKB("🔄 Refresh", callback_data="im_shop:0")])
        return "\n".join(lines), _IM_IKM(kb_rows)

    for cid, card in slice_:
        name = str(card.get("name", "Unknown") or "Unknown").strip()
        movie = str(card.get("movie", "") or "").strip()
        price = _im_card_price(cid)
        counts = _im_get_purchase_counts()
        n_sold = int(counts.get(str(cid), 0) or 0)
        lines.append(
            f"🆔 <code>{cid}</code> • <b>{name}</b>"
        )
        if movie:
            lines.append(f"   🎬 {movie}")
        lines.append(
            f"   💎 <code>{_im_fmt(price)}</code>  "
            f"({_im_short_price(price)})  •  🛒 sold ×{n_sold}"
        )

    lines.append("━━━━━━━━━━━━━━━━━━━━━━━━")
    lines.append(f"📄 Page <b>{page+1}</b> / <b>{pages}</b>  •  Total : <b>{total}</b>")
    lines.append("📝 Buy : <code>/blackmarket &lt;card_id&gt;</code>")
    lines.append(f"🔗 join - {_IM_JOIN_HANDLE}")

    # Build keyboard: prev / page / next + per-card "Buy" buttons
    kb_rows: list[list[object]] = []
    buy_row: list[object] = []
    for cid, card in slice_:
        buy_row.append(_IM_IKB(f"💎 {cid}", callback_data=f"im_buy:{cid}"))
        if len(buy_row) == 3:
            kb_rows.append(buy_row)
            buy_row = []
    if buy_row:
        kb_rows.append(buy_row)

    nav: list[object] = []
    if pages > 1:
        prev_page = (page - 1) % pages
        next_page = (page + 1) % pages
        nav.append(_IM_IKB("◀️ Prev", callback_data=f"im_shop:{prev_page}"))
        nav.append(_IM_IKB(f"{page+1}/{pages}", callback_data=f"im_shop:{page}"))
        nav.append(_IM_IKB("Next ▶️", callback_data=f"im_shop:{next_page}"))
    else:
        nav.append(_IM_IKB("🔄 Refresh", callback_data=f"im_shop:{page}"))
    kb_rows.append(nav)

    return "\n".join(lines), _IM_IKM(kb_rows)


# ── /blackmarketshop ───────────────────────────────────────────────────
async def _im_blackmarketshop_cmd(update, context):
    msg = getattr(update, "message", None)
    if msg is None:
        return
    try:
        uid = update.effective_user.id if update.effective_user else 0
        b = _im_bot()
        if b and hasattr(b, "is_gbanned") and b.is_gbanned(uid):
            await msg.reply_text("❌ You are globally banned.")
            return
    except Exception:
        pass

    text, kb = _im_build_shop_page(0)
    try:
        await msg.reply_text(text, parse_mode="HTML", reply_markup=kb,
                             disable_web_page_preview=True)
    except Exception as e:
        _im_safe_logger().warning(f"[blackmarketshop] reply failed: {e}")
        try:
            await msg.reply_text(text, reply_markup=kb)
        except Exception:
            pass


# ── /blackmarket <card_id> ─────────────────────────────────────────────
async def _im_blackmarket_buy_cmd(update, context):
    msg = getattr(update, "message", None)
    user = getattr(update, "effective_user", None)
    if msg is None or user is None:
        return

    b = _im_bot()
    if b and hasattr(b, "is_gbanned") and b.is_gbanned(user.id):
        await msg.reply_text("❌ You are globally banned.")
        return

    if not getattr(context, "args", None):
        await msg.reply_text(
            "📝 <b>Usage</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "<code>/blackmarket &lt;card_id&gt;</code>\n\n"
            "📋 Browse : /blackmarketshop\n"
            "💎 Balance : /diamonds",
            parse_mode="HTML",
        )
        return

    card_id = str(context.args[0]).strip()
    await _im_perform_purchase(update, context, str(user.id), card_id, via_callback=False)


async def _im_perform_purchase(update, context, uid: str, card_id: str, via_callback: bool):
    """Core purchase logic; shared by /blackmarket and the inline Buy button."""
    msg = getattr(update, "message", None)
    cb = getattr(update, "callback_query", None)
    user = getattr(update, "effective_user", None)

    async def _reply(text: str, kb=None):
        try:
            if via_callback and cb is not None:
                await cb.answer()
                await cb.message.reply_text(text, parse_mode="HTML",
                                            reply_markup=kb,
                                            disable_web_page_preview=True)
            elif msg is not None:
                await msg.reply_text(text, parse_mode="HTML",
                                     reply_markup=kb,
                                     disable_web_page_preview=True)
        except Exception as e:
            _im_safe_logger().warning(f"[blackmarket] reply failed: {e}")

    b = _im_bot()
    if not b:
        await _reply("⚠️ Bot data not initialised.")
        return

    cards = b.data.get("cards", {}) or {}
    if str(card_id) not in cards:
        await _reply(
            f"❌ <b>Card not found</b>\n"
            f"━━━━━━━━━━━━━━━━━━\n"
            f"No card with ID <code>{card_id}</code> in the database.\n"
            f"📋 Browse : /blackmarketshop"
        )
        return

    card = cards[str(card_id)]
    if str(card.get("rarity", "")) != _IM_IMMORTAL_RARITY:
        await _reply(
            f"❌ <b>Not an Immortal card</b>\n"
            f"━━━━━━━━━━━━━━━━━━\n"
            f"The Black Market only sells {_im_rarity_display()} cards.\n"
            f"📋 Browse : /blackmarketshop"
        )
        return

    price = _im_card_price(card_id)
    bal = _im_get_diamonds(uid)

    if bal < price:
        short = price - bal
        await _reply(
            "❌ <b>Not enough Diamonds</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"💎 You have : <code>{_im_fmt(bal)}</code>\n"
            f"💵 Price    : <code>{_im_fmt(price)}</code>\n"
            f"📉 Short by : <code>{_im_fmt(short)}</code>\n\n"
            "💡 Earn diamonds via /guess in groups.\n"
            "📋 Browse : /blackmarketshop"
        )
        return

    # Deduct diamonds
    new_bal = _im_add_diamonds(uid, -price)

    # Add card to user inventory (existing structure: bot.data['users'][uid] = list of card_ids)
    b.data.setdefault("users", {}).setdefault(str(uid), [])
    b.data["users"][str(uid)].append(str(card_id))

    # Increment purchase count → price doubles next time
    n_sold = _im_inc_purchase_count(card_id)
    next_price = _im_card_price(card_id)

    try:
        b.save_data()
    except Exception:
        pass

    name = str(card.get("name", "Unknown") or "Unknown").strip()
    movie = str(card.get("movie", "") or "").strip()
    rdisp = _im_rarity_display()

    caption_lines = [
        "🎉 <b>BLACK MARKET PURCHASE</b>",
        "━━━━━━━━━━━━━━━━━━━━━━━━",
        f"🎴 <b>{name}</b>",
    ]
    if movie:
        caption_lines.append(f"🎬 {movie}")
    caption_lines += [
        f"🆔 <code>{card_id}</code>",
        f"⭐ {rdisp}",
        "━━━━━━━━━━━━━━━━━━━━━━━━",
        f"💎 -{_im_fmt(price)}",
        f"💰 Balance : <code>{_im_fmt(new_bal)}</code>",
        "━━━━━━━━━━━━━━━━━━━━━━━━",
        f"🛒 This card has been sold <b>×{n_sold}</b> total",
        f"📈 Next price : <code>{_im_fmt(next_price)}</code>",
        "",
        f"🔗 join - {_IM_JOIN_HANDLE}",
    ]
    caption = "\n".join(caption_lines)

    # Try to send the card media if available, else plain text
    try:
        target_msg = (cb.message if via_callback and cb else msg)
        if target_msg is None:
            return
        if card.get("image"):
            await target_msg.reply_photo(photo=card["image"], caption=caption,
                                         parse_mode="HTML")
            return
        if card.get("video"):
            vtype = str(card.get("video_type", "video") or "video").lower()
            if vtype == "document":
                await target_msg.reply_document(document=card["video"],
                                                caption=caption, parse_mode="HTML")
            else:
                await target_msg.reply_video(video=card["video"], caption=caption,
                                             parse_mode="HTML")
            return
    except Exception as e:
        _im_safe_logger().warning(f"[blackmarket] media reply failed, fallback to text: {e}")

    await _reply(caption)


# ── Shop callback (paging + buy button) ────────────────────────────────
async def _im_shop_cb(update, context):
    q = getattr(update, "callback_query", None)
    if q is None:
        return
    data = (q.data or "").strip()
    try:
        if data.startswith("im_shop:"):
            try:
                page = int(data.split(":", 1)[1])
            except Exception:
                page = 0
            text, kb = _im_build_shop_page(page)
            try:
                await q.answer()
            except Exception:
                pass
            try:
                await q.edit_message_text(text, parse_mode="HTML",
                                          reply_markup=kb,
                                          disable_web_page_preview=True)
            except Exception as e:
                # Probably "message is not modified" — silently ignore
                _im_safe_logger().debug(f"[blackmarketshop] edit failed: {e}")
            return

        if data.startswith("im_buy:"):
            card_id = data.split(":", 1)[1].strip()
            user = update.effective_user
            if not user:
                try:
                    await q.answer("⚠️ Cannot identify user", show_alert=True)
                except Exception:
                    pass
                return
            await _im_perform_purchase(update, context, str(user.id), card_id, via_callback=True)
            return
    except Exception as e:
        _im_safe_logger().error(f"[blackmarket] callback error: {e}")
        try:
            await q.answer("⚠️ Error", show_alert=False)
        except Exception:
            pass


# ── /diamonds ──────────────────────────────────────────────────────────
async def _im_diamonds_cmd(update, context):
    msg = getattr(update, "message", None)
    user = getattr(update, "effective_user", None)
    if msg is None or user is None:
        return
    b = _im_bot()
    if b and hasattr(b, "is_gbanned") and b.is_gbanned(user.id):
        await msg.reply_text("❌ You are globally banned.")
        return

    # If reply or arg → admin-style lookup of someone else's balance (anyone may check own)
    target_id = user.id
    target_name = user.first_name or user.username or str(user.id)

    try:
        if msg.reply_to_message and msg.reply_to_message.from_user \
                and not msg.reply_to_message.from_user.is_bot:
            ru = msg.reply_to_message.from_user
            target_id = ru.id
            target_name = ru.first_name or ru.username or str(ru.id)
        elif getattr(context, "args", None):
            arg = (context.args[0] or "").strip().lstrip("@")
            if arg.isdigit():
                target_id = int(arg)
                try:
                    cache = USER_CACHE  # type: ignore[name-defined]
                    target_name = cache.get(str(target_id)) or f"User {target_id}"
                except Exception:
                    target_name = f"User {target_id}"
            else:
                try:
                    chat = await context.bot.get_chat("@" + arg)
                    target_id = chat.id
                    target_name = chat.first_name or arg
                except Exception:
                    await msg.reply_text(
                        "❌ Username မတွေ့ပါ။ Reply or numeric id သုံးပါ။"
                    )
                    return
    except Exception:
        pass

    bal = _im_get_diamonds(str(target_id))
    text = (
        "💎 <b>DIAMOND BALANCE</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👤 {target_name}\n"
        f"🆔 <code>{target_id}</code>\n"
        f"💎 <code>{_im_fmt(bal)}</code>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "🛒 Spend at /blackmarketshop\n"
        "🎯 Earn via /guess\n"
        f"🔗 join - {_IM_JOIN_HANDLE}"
    )
    try:
        await msg.reply_text(text, parse_mode="HTML")
    except Exception:
        await msg.reply_text(text)


# ── /adddiamond  (Owner only) ──────────────────────────────────────────
async def _im_adddiamond_cmd(update, context):
    msg = getattr(update, "message", None)
    user = getattr(update, "effective_user", None)
    if msg is None or user is None:
        return
    b = _im_bot()
    if not b or not hasattr(b, "is_owner") or not b.is_owner(user.id):
        await msg.reply_text("❌ Owner only")
        return

    # Resolve target
    target_id = None
    target_name = None

    # 1) Reply
    try:
        if msg.reply_to_message and msg.reply_to_message.from_user \
                and not msg.reply_to_message.from_user.is_bot:
            ru = msg.reply_to_message.from_user
            target_id = ru.id
            target_name = ru.first_name or ru.username or str(ru.id)
    except Exception:
        pass

    args = list(getattr(context, "args", []) or [])
    amount: int | None = None

    if target_id is not None:
        # Reply mode: /adddiamond <amount>
        if args:
            try:
                amount = int(str(args[0]).replace(",", "").strip())
            except Exception:
                amount = None
    else:
        # Arg mode: /adddiamond <user|@username|reply> <amount>
        if args:
            first = args[0].strip().lstrip("@")
            if first.isdigit():
                try:
                    target_id = int(first)
                    try:
                        cache = USER_CACHE  # type: ignore[name-defined]
                        target_name = cache.get(str(target_id)) or f"User {target_id}"
                    except Exception:
                        target_name = f"User {target_id}"
                except Exception:
                    target_id = None
            else:
                # username lookup
                try:
                    chat = await context.bot.get_chat("@" + first)
                    target_id = chat.id
                    target_name = chat.first_name or first
                except Exception:
                    await msg.reply_text(
                        "❌ Username မတွေ့ပါ။ Reply or numeric id သုံးပါ။"
                    )
                    return
            if len(args) >= 2:
                try:
                    amount = int(str(args[1]).replace(",", "").strip())
                except Exception:
                    amount = None

    if target_id is None or amount is None:
        await msg.reply_text(
            "📝 <b>Usage</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "<code>/adddiamond &lt;reply&gt; &lt;amount&gt;</code>\n"
            "<code>/adddiamond @username &lt;amount&gt;</code>\n"
            "<code>/adddiamond &lt;user_id&gt; &lt;amount&gt;</code>\n"
            "💡 amount can be negative to subtract.",
            parse_mode="HTML",
        )
        return

    new_bal = _im_add_diamonds(str(target_id), int(amount))
    sign = "+" if amount >= 0 else ""
    await msg.reply_text(
        "✅ <b>Diamonds updated</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👤 {target_name}\n"
        f"🆔 <code>{target_id}</code>\n"
        f"💎 {sign}{_im_fmt(amount)}\n"
        f"💰 Balance : <code>{_im_fmt(new_bal)}</code>",
        parse_mode="HTML",
    )


# ───────────────────────────────────────────────────────────────────────
#  /wa  REGISTRATION FIX
#  ---------------------------------------------------------------------
#  The original module registered /wa via an ApplicationBuilder.build
#  monkey-patch.  That patch is fragile because multiple modules in this
#  file overwrite the same class-level attribute in different orders.
#  When the chain of wrapped main()s does not unwind cleanly, the /wa
#  handler never gets added and the command appears silent.
#
#  We add a SECOND, idempotent registration path via Application.post_init
#  which runs once the Application object is fully built — guaranteed to
#  execute regardless of wrapper ordering.
# ───────────────────────────────────────────────────────────────────────
def _im_install_post_init_hook() -> None:
    if _IM_App is None:
        return
    g = globals()

    # Prevent double-install
    if g.get("_IM_POST_INIT_INSTALLED"):
        return

    # Reuse the existing /wa handler function defined earlier in the file
    wa_handler_fn = g.get("wa_cmd")
    wa_register_fn = g.get("_wa_register_handlers")

    # Capture original ApplicationBuilder.build (current, after all other
    # modules have already wrapped it). We hook through Application instead.
    try:
        orig_app_init = _IM_App.__init__
    except Exception:
        return

    if getattr(orig_app_init, "_im_wrapped", False):
        return

    def patched_init(self, *args, **kwargs):  # type: ignore[no-redef]
        orig_app_init(self, *args, **kwargs)
        try:
            _im_register_all_handlers(self, wa_handler_fn, wa_register_fn)
        except Exception as e:
            _im_safe_logger().error(f"[immortal_shop] register-on-init failed: {e}")

    patched_init._im_wrapped = True  # type: ignore[attr-defined]
    try:
        _IM_App.__init__ = patched_init  # type: ignore[assignment]
        g["_IM_POST_INIT_INSTALLED"] = True
    except Exception as e:
        _im_safe_logger().error(f"[immortal_shop] App.__init__ patch failed: {e}")


# Module-level set of Application id()s that already had handlers added.
# Application uses __slots__, so we cannot set an attribute on the instance.
_IM_REGISTERED_APPS: set[int] = set()


def _im_register_all_handlers(application, wa_handler_fn, wa_register_fn) -> None:
    """Register Immortal Shop handlers + /wa (idempotent)."""
    if application is None:
        return

    # Idempotency marker — Application object uses __slots__,
    # so we track which Application ids we've already touched.
    try:
        _app_key = id(application)
    except Exception:
        _app_key = None
    if _app_key is not None and _app_key in _IM_REGISTERED_APPS:
        return
    if _app_key is not None:
        _IM_REGISTERED_APPS.add(_app_key)

    # ── /wa  (re-register defensively) ─────────────────────────────
    try:
        if callable(wa_register_fn):
            wa_register_fn(application)
        elif callable(wa_handler_fn) and _IM_CmdH is not None:
            application.add_handler(_IM_CmdH("wa", wa_handler_fn), group=-3)
            _im_safe_logger().info("[immortal_shop] /wa registered via fallback")
    except Exception as e:
        _im_safe_logger().warning(f"[immortal_shop] /wa register failed: {e}")

    # ── Immortal Shop commands & callback ──────────────────────────
    try:
        if _IM_CmdH is not None:
            application.add_handler(_IM_CmdH("blackmarketshop", _im_blackmarketshop_cmd), group=-3)
            application.add_handler(_IM_CmdH("blackmarket",     _im_blackmarket_buy_cmd), group=-3)
            application.add_handler(_IM_CmdH("diamonds",        _im_diamonds_cmd), group=-3)
            application.add_handler(_IM_CmdH("adddiamond",      _im_adddiamond_cmd), group=-3)
        if _IM_CbH is not None:
            application.add_handler(_IM_CbH(_im_shop_cb, pattern=r"^im_(shop|buy):"), group=-3)
        _im_safe_logger().info(
            "[immortal_shop] ✅ /blackmarketshop /blackmarket /diamonds /adddiamond + /wa hook installed"
        )
    except Exception as e:
        _im_safe_logger().error(f"[immortal_shop] register failed: {e}")


# ── Install (executed at import / file load time) ──────────────────────
try:
    _im_install_post_init_hook()
except Exception as _im_e:
    try:
        _im_safe_logger().error(f"[immortal_shop] install failed: {_im_e}")
    except Exception:
        pass

# ═══════════════════════════════════════════════════════════════════════
#  END  BLACK MARKET  /  IMMORTAL SHOP  MODULE
# ═══════════════════════════════════════════════════════════════════════


# ═══════════════════════════════════════════════════════════════════════
#  /wa  ENHANCEMENT PATCH  +  /setwa  +  /dpay
#  ---------------------------------------------------------------------
#  Goals (per upgrade brief):
#   ✅ Fix "Card Not Found" — /wa must match ANY card already in DB
#   ✅ Support Photo / Video / Animation / Document / Forwarded messages
#   ✅ Match by multiple keys:
#        • file_id           (Telegram's per-bot file id)
#        • file_unique_id    (stable across bots & restarts)
#        • media_hash        (sha1 of file_unique_id, defensive backup)
#        • caption / name    (fallback when media id changes)
#        • stored media refs (image / video on the card record itself)
#   ✅ Survive bot restarts (file_id may rotate — unique_id won't)
#   ✅ Auto-repair: scan whole card DB on startup & on first /wa call,
#      back-fill missing file_unique_id / media_hash without touching
#      any other card field.
#   ✅ Handle duplicate media — prefer the most-specific (unique_id) match
#   ✅ Keep the existing /wa response format EXACTLY as the brief shows
#   ✅ /wa restricted to a configurable group — set by owner via /setwa
#   ✅ /dpay  —  reply to a user with /dpay <amount> to share diamonds
#
#  Implementation notes:
#   • This module is appended at the END of the original file.  It does
#     NOT touch any other line of the original code, does NOT change the
#     existing JSON structure, and does NOT remove any existing command.
#   • The /wa handler implemented here REPLACES the previous wa_cmd by
#     re-registering at group=-4 (lower number = higher priority in PTB).
#   • The previous wa_cmd is still defined for safety; only the routing
#     is shadowed by the enhanced one at runtime.
# ═══════════════════════════════════════════════════════════════════════

import hashlib as _wax_hashlib
import re as _wax_re
import asyncio as _wax_asyncio
from typing import Any, Optional, List, Dict, Tuple

try:
    from telegram import Update as _WAX_Update  # type: ignore
    from telegram.ext import (
        CommandHandler as _WAX_CmdH,
        ContextTypes  as _WAX_Ctx,
        Application   as _WAX_App,
    )
except Exception:  # pragma: no cover
    _WAX_Update = None  # type: ignore
    _WAX_CmdH   = None  # type: ignore
    _WAX_Ctx    = None  # type: ignore
    _WAX_App    = None  # type: ignore


# ── Channel join footer (matches the user's spec output) ───────────────
_WAX_JOIN_HANDLE = "@officalzcko"


def _wax_log():
    try:
        return logger  # type: ignore[name-defined]
    except Exception:
        import logging
        return logging.getLogger("wa_patch")


def _wax_bot():
    try:
        return bot  # type: ignore[name-defined]
    except Exception:
        return None


# ───────────────────────────────────────────────────────────────────────
#  Settings helpers — used for the owner-defined /wa group
# ───────────────────────────────────────────────────────────────────────
def _wax_get_wa_groups():
    """Return the list of group chat_ids where /wa is allowed."""
    b = _wax_bot()
    if not b:
        return []
    try:
        raw = b.settings.get("wa_allowed_groups", []) or []
        out = []
        for x in raw:
            try:
                out.append(int(x))
            except Exception:
                continue
        return out
    except Exception:
        return []


def _wax_set_wa_group(chat_id, add=True):
    """Add (or remove) a group_id from the /wa allow-list. Persists."""
    b = _wax_bot()
    if not b:
        return []
    try:
        groups = _wax_get_wa_groups()
        cid = int(chat_id)
        if add:
            if cid not in groups:
                groups.append(cid)
        else:
            groups = [g for g in groups if g != cid]
        b.settings["wa_allowed_groups"] = groups
        b.save_settings()
        return groups
    except Exception as e:
        _wax_log().error(f"[wa_patch] set wa group failed: {e}")
        return _wax_get_wa_groups()


def _wax_is_real_owner(uid: int) -> bool:
    """True if uid is a hard-coded OWNER from OWNERS list."""
    try:
        return int(uid) in [int(x) for x in OWNERS]  # type: ignore[name-defined]
    except Exception:
        return False


# ───────────────────────────────────────────────────────────────────────
#  ENHANCED INDEX — multi-key lookup for /wa
# ───────────────────────────────────────────────────────────────────────
_WAX_INDEX_BUILT = False
_WAX_BY_FILE_ID    = {}
_WAX_BY_UNIQUE_ID  = {}
_WAX_BY_MEDIA_HASH = {}
_WAX_BY_NAME_NORM  = {}      # normalised name  -> card_id
_WAX_BY_NAME_FIRST = {}      # first word    -> [card_ids]


def _wax_norm_name(name: str) -> str:
    if not name:
        return ""
    s = str(name).lower()
    # Strip role-tag bracket suffix like " [🧹]" used in /wa format
    s = _wax_re.sub(r"\[[^\]]*\]", "", s)
    # Keep alnum + spaces, collapse whitespace
    s = _wax_re.sub(r"[^a-z0-9\u00C0-\uFFFF ]+", " ", s)
    s = _wax_re.sub(r"\s+", " ", s).strip()
    return s


def _wax_media_hash(unique_id):
    if not unique_id:
        return None
    try:
        return _wax_hashlib.sha1(str(unique_id).encode("utf-8")).hexdigest()
    except Exception:
        return None


def _wax_card_primary_fid(card):
    """Return the primary file_id on a card (image or video)."""
    if not isinstance(card, dict):
        return None
    fid = card.get("image") or card.get("video")
    return str(fid) if fid else None


def _wax_cards_db() -> dict:
    b = _wax_bot()
    if not b:
        return {}
    try:
        return b.data.get("cards", {}) or {}
    except Exception:
        return {}


def _wax_build_index(force: bool = False) -> None:
    """(Re)build the multi-key card index from the live JSON DB."""
    global _WAX_INDEX_BUILT
    if _WAX_INDEX_BUILT and not force:
        return
    _WAX_BY_FILE_ID.clear()
    _WAX_BY_UNIQUE_ID.clear()
    _WAX_BY_MEDIA_HASH.clear()
    _WAX_BY_NAME_NORM.clear()
    _WAX_BY_NAME_FIRST.clear()
    cards = _wax_cards_db()
    try:
        for cid, card in cards.items():
            if not isinstance(card, dict):
                continue
            scid = str(cid)
            fid = _wax_card_primary_fid(card)
            if fid:
                _WAX_BY_FILE_ID[fid] = scid
            uid = card.get("file_unique_id") or card.get("media_unique_id")
            if uid:
                _WAX_BY_UNIQUE_ID[str(uid)] = scid
                h = _wax_media_hash(str(uid))
                if h:
                    _WAX_BY_MEDIA_HASH[h] = scid
            # Some old cards may persist their own media_hash
            mh = card.get("media_hash")
            if mh:
                _WAX_BY_MEDIA_HASH[str(mh)] = scid
            name = card.get("name") or ""
            n = _wax_norm_name(name)
            if n:
                _WAX_BY_NAME_NORM[n] = scid
                first = n.split(" ", 1)[0] if n else ""
                if first:
                    _WAX_BY_NAME_FIRST.setdefault(first, []).append(scid)
        _WAX_INDEX_BUILT = True
        _wax_log().info(
            f"[wa_patch] index built: {len(_WAX_BY_FILE_ID)} file_id, "
            f"{len(_WAX_BY_UNIQUE_ID)} unique_id, {len(_WAX_BY_NAME_NORM)} names"
        )
    except Exception as e:
        _wax_log().error(f"[wa_patch] build_index error: {e}")


def _wax_remember(card_id, fid, uid):
    """Warm the cache after a successful match (also persists to card)."""
    try:
        if fid:
            _WAX_BY_FILE_ID[fid] = str(card_id)
        if uid:
            _WAX_BY_UNIQUE_ID[str(uid)] = str(card_id)
            h = _wax_media_hash(str(uid))
            if h:
                _WAX_BY_MEDIA_HASH[h] = str(card_id)
        # Back-fill the card record so future lookups are O(1)
        b = _wax_bot()
        if b is not None:
            card = b.data.get("cards", {}).get(str(card_id))
            if isinstance(card, dict):
                changed = False
                if uid and not card.get("file_unique_id"):
                    card["file_unique_id"] = str(uid)
                    changed = True
                if uid and not card.get("media_hash"):
                    mh = _wax_media_hash(str(uid))
                    if mh:
                        card["media_hash"] = mh
                        changed = True
                # If the card has no stored media yet (unusual), don't
                # overwrite — we only enrich, never replace.
                if changed:
                    try:
                        b.save_data()
                    except Exception:
                        pass
    except Exception:
        pass


# ───────────────────────────────────────────────────────────────────────
#  Media extraction — handles photo / video / animation / document /
#  sticker / video_note  AND  follows forward_origin where possible.
# ───────────────────────────────────────────────────────────────────────
def _wax_extract_media(message):
    """Return (file_id, file_unique_id, kind, caption_text)."""
    if message is None:
        return None, None, "", ""

    caption = (
        getattr(message, "caption", None)
        or getattr(message, "text", None)
        or ""
    ) or ""

    photos = getattr(message, "photo", None)
    if photos:
        try:
            p = photos[-1]
            return (
                str(getattr(p, "file_id", "") or ""),
                str(getattr(p, "file_unique_id", "") or ""),
                "photo",
                caption,
            )
        except Exception:
            pass

    for attr, kind in (
        ("video", "video"),
        ("animation", "animation"),
        ("document", "document"),
        ("sticker", "sticker"),
        ("video_note", "video_note"),
        ("audio", "audio"),
    ):
        m = getattr(message, attr, None)
        if m:
            return (
                str(getattr(m, "file_id", "") or ""),
                str(getattr(m, "file_unique_id", "") or ""),
                kind,
                caption,
            )

    return None, None, "", caption


# ───────────────────────────────────────────────────────────────────────
#  Look-up by the strongest available key (multi-step fallback)
# ───────────────────────────────────────────────────────────────────────
def _wax_lookup(file_id, unique_id, caption_text):
    cards = _wax_cards_db()
    if not cards:
        return None, None

    _wax_build_index(force=False)

    # 1) file_unique_id  (most reliable, stable across restarts)
    if unique_id and unique_id in _WAX_BY_UNIQUE_ID:
        cid = _WAX_BY_UNIQUE_ID[unique_id]
        c = cards.get(cid)
        if isinstance(c, dict):
            return cid, c

    # 2) media_hash  (sha1 of unique_id)
    if unique_id:
        h = _wax_media_hash(unique_id)
        if h and h in _WAX_BY_MEDIA_HASH:
            cid = _WAX_BY_MEDIA_HASH[h]
            c = cards.get(cid)
            if isinstance(c, dict):
                return cid, c

    # 3) file_id  (per-bot, may rotate after restart)
    if file_id and file_id in _WAX_BY_FILE_ID:
        cid = _WAX_BY_FILE_ID[file_id]
        c = cards.get(cid)
        if isinstance(c, dict):
            return cid, c

    # 4) Slow linear scan — covers cards added after last build
    target_fid = str(file_id) if file_id else None
    target_uid = str(unique_id) if unique_id else None
    for cid, card in cards.items():
        if not isinstance(card, dict):
            continue
        cuid = card.get("file_unique_id") or card.get("media_unique_id")
        if target_uid and cuid and str(cuid) == target_uid:
            _wax_remember(cid, target_fid, target_uid)
            return str(cid), card
        cfid = _wax_card_primary_fid(card)
        if target_fid and cfid and cfid == target_fid:
            _wax_remember(cid, target_fid, target_uid)
            return str(cid), card

    # 5) Caption-based fallback — parse "Name / Movie" from the replied
    #    message's caption.  Useful when the replied media is itself a
    #    /wa response or a forwarded uploader caption.
    if caption_text:
        nm = _wax_extract_name_from_caption(caption_text)
        if nm:
            n = _wax_norm_name(nm)
            if n and n in _WAX_BY_NAME_NORM:
                cid = _WAX_BY_NAME_NORM[n]
                c = cards.get(cid)
                if isinstance(c, dict):
                    _wax_remember(cid, target_fid, target_uid)
                    return cid, c
            # First-word fuzzy match (single-candidate only — avoid wrong duplicates)
            first = (n.split(" ", 1)[0] if n else "")
            if first and first in _WAX_BY_NAME_FIRST:
                candidates = _WAX_BY_NAME_FIRST[first]
                if len(candidates) == 1:
                    cid = candidates[0]
                    c = cards.get(cid)
                    if isinstance(c, dict):
                        _wax_remember(cid, target_fid, target_uid)
                        return cid, c

    return None, None


# ── Pull the "Name" out of a card caption (uploader OR /wa format) ─────
_WAX_NAME_RE = _wax_re.compile(
    r"(?:📛|🎴|NAME|Name|name)\s*[:：]\s*([^\n\r]+)",
    _wax_re.UNICODE,
)


def _wax_extract_name_from_caption(text):
    if not text:
        return None
    m = _WAX_NAME_RE.search(text)
    if m:
        raw = m.group(1).strip()
        # Drop trailing role tag " [🧹]" if any
        raw = _wax_re.sub(r"\s*\[[^\]]*\]\s*$", "", raw).strip()
        return raw or None
    return None


# ───────────────────────────────────────────────────────────────────────
#  Output formatting (unchanged from the brief)
# ───────────────────────────────────────────────────────────────────────
def _wax_role_tag(card: dict) -> str:
    try:
        info = get_role_info(card) or {}  # type: ignore[name-defined]
        e = info.get("emoji") or info.get("icon") or ""
        if e:
            return f"[{e}]"
    except Exception:
        pass
    e = card.get("role_emoji") or card.get("emoji")
    return f"[{e}]" if e else ""


def _wax_first_word(name: str) -> str:
    if not name:
        return ""
    cleaned = []
    for ch in name:
        if ch.isalnum() or ch in (" ", "-", "'", "_"):
            cleaned.append(ch)
    parts = "".join(cleaned).strip().split()
    return parts[0].lower() if parts else ""


def _wax_format_found(card_id: str, card: dict) -> str:
    """Output matches the brief sample EXACTLY."""
    name = str(card.get("name", "") or "Unknown").strip() or "Unknown"
    role_tag = _wax_role_tag(card)
    title = f"{name} {role_tag}".strip()
    hint  = _wax_first_word(name)
    full  = title  # "Shea Haulia [🧹]"
    lines = [
        f"NAME : {title}",
        "━━━━━━━━━━━━━━━━━━",
    ]
    if hint:
        lines.append(f"🔹 Hint : /ziceko {hint}")
    lines.append(f"🔸 Full : /ziceko {full}")
    lines.append("")
    lines.append(f"🔗 join - {_WAX_JOIN_HANDLE}")
    return "\n".join(lines)


def _wax_format_not_found(kind: str) -> str:
    return (
        "❌ Card Not Found\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"This {kind or 'media'} does not match any saved card.\n"
        "• Reply directly to a card photo / video / animation / document.\n"
        "• Forwarded copies are also supported.\n"
        "\n"
        f"🔗 join - {_WAX_JOIN_HANDLE}"
    )


def _wax_format_usage() -> str:
    return (
        "📌 Usage\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "Reply to a card photo / video / animation / document with:\n"
        "/wa\n"
        "\n"
        f"🔗 join - {_WAX_JOIN_HANDLE}"
    )


# ───────────────────────────────────────────────────────────────────────
#  Group-restriction enforcement for /wa
# ───────────────────────────────────────────────────────────────────────
def _wax_is_wa_allowed_here(chat):
    """True if /wa may be used in this chat.
    Owners (real OWNERS list) bypass the restriction everywhere.
    """
    try:
        if chat is None:
            return False, "Chat context unavailable."
        chat_type = getattr(chat, "type", "") or ""
        cid = int(getattr(chat, "id", 0) or 0)

        groups = _wax_get_wa_groups()
        if not groups:
            # No restriction configured — fall back to "groups only"
            if chat_type in ("group", "supergroup"):
                return True, ""
            return False, (
                "🚫 /wa is only available in groups.\n"
                "An owner can pin /wa to a specific group with:\n"
                "/setwa <group_id>"
            )

        if cid in groups:
            return True, ""

        return False, (
            "🚫 /wa is restricted to the bot's official group.\n"
            "Please join the configured group to use this command."
        )
    except Exception as e:
        _wax_log().warning(f"[wa_patch] allow-check failed: {e}")
        return False, "⚠️ Permission check failed."


# ───────────────────────────────────────────────────────────────────────
#  Auto-repair pass — runs once at startup, also on the first /wa call
# ───────────────────────────────────────────────────────────────────────
_WAX_AUTOREPAIR_DONE = False


def _wax_auto_repair_once() -> None:
    """Scan the whole card DB, back-fill media_hash where unique_id exists.
    Never overwrites existing data. Idempotent — safe to call repeatedly.
    """
    global _WAX_AUTOREPAIR_DONE
    if _WAX_AUTOREPAIR_DONE:
        return
    b = _wax_bot()
    if not b:
        return
    try:
        cards = b.data.get("cards", {}) or {}
        changed = 0
        for cid, card in cards.items():
            if not isinstance(card, dict):
                continue
            uid = card.get("file_unique_id") or card.get("media_unique_id")
            if uid and not card.get("media_hash"):
                h = _wax_media_hash(str(uid))
                if h:
                    card["media_hash"] = h
                    changed += 1
        if changed:
            try:
                b.save_data()
            except Exception:
                pass
            _wax_log().info(f"[wa_patch] auto-repair filled media_hash on {changed} cards")
        _WAX_AUTOREPAIR_DONE = True
        # Force rebuild now that the DB is enriched
        _wax_build_index(force=True)
    except Exception as e:
        _wax_log().warning(f"[wa_patch] auto-repair error: {e}")


# ───────────────────────────────────────────────────────────────────────
#  /wa  — ENHANCED handler
# ───────────────────────────────────────────────────────────────────────
async def _wax_wa_cmd(update, context):
    try:
        message = getattr(update, "message", None)
        if message is None:
            return

        # Global ban respect
        try:
            uid_check = update.effective_user.id if update.effective_user else 0
            b = _wax_bot()
            if b and hasattr(b, "is_gbanned") and b.is_gbanned(uid_check):
                await message.reply_text("❌ You are globally banned.")
                return
        except Exception:
            pass

        # Group restriction
        ok, why = _wax_is_wa_allowed_here(update.effective_chat)
        if not ok:
            # Owners always bypass
            try:
                uid_now = update.effective_user.id if update.effective_user else 0
            except Exception:
                uid_now = 0
            if not _wax_is_real_owner(uid_now):
                await message.reply_text(why)
                return

        # Ensure index + auto-repair done
        _wax_auto_repair_once()

        reply = getattr(message, "reply_to_message", None)
        if reply is None:
            await message.reply_text(_wax_format_usage())
            return

        fid, uid, kind, caption = _wax_extract_media(reply)

        # If the replied message itself has no media, try its caption
        # (e.g. user replied to a previous /wa text response).
        if not fid and not uid:
            if caption:
                # Try name-based caption match directly
                cid, card = _wax_lookup(None, None, caption)
                if card:
                    out = _wax_format_found(cid, card)
                    await _wax_send_match(message, card, out)
                    return
            await message.reply_text(
                "⚠️ No media found in the replied message.\n"
                "Reply to a photo / video / animation / document and try again."
            )
            return

        card_id, card = _wax_lookup(fid, uid, caption)
        if not card:
            await message.reply_text(_wax_format_not_found(kind))
            return

        out = _wax_format_found(card_id, card)
        await _wax_send_match(message, card, out)

    except Exception as e:
        _wax_log().error(f"[wa_patch] /wa handler error: {e}")
        try:
            await update.message.reply_text(
                "⚠️ Something went wrong while processing /wa. Please try again."
            )
        except Exception:
            pass


async def _wax_send_match(message, card: dict, caption: str) -> None:
    """Send the matched card back with its media (image / video / doc).
    Falls back to plain text on media failure.
    """
    try:
        if card.get("image"):
            await message.reply_photo(photo=card["image"], caption=caption)
            return
        if card.get("video"):
            vtype = str(card.get("video_type", "video") or "video").lower()
            if vtype == "document":
                await message.reply_document(document=card["video"], caption=caption)
            else:
                await message.reply_video(video=card["video"], caption=caption)
            return
    except Exception as e:
        _wax_log().warning(f"[wa_patch] media echo failed: {e}")
    try:
        await message.reply_text(caption)
    except Exception:
        pass


# ───────────────────────────────────────────────────────────────────────
#  /setwa <group_id>  — owner-only, configures the /wa group allow-list
#  Usage:
#     /setwa                → show current allowed groups
#     /setwa <gp_id>        → add group to allow-list
#     /setwa <gp_id> off    → remove group from allow-list
#     /setwa here           → add current chat (must be a group)
# ───────────────────────────────────────────────────────────────────────
async def _wax_setwa_cmd(update, context):
    try:
        message = getattr(update, "message", None)
        if message is None:
            return

        uid = update.effective_user.id if update.effective_user else 0
        if not _wax_is_real_owner(uid):
            await message.reply_text("🚫 Owner-only command.")
            return

        args = list(getattr(context, "args", []) or [])

        if not args:
            current = _wax_get_wa_groups()
            if not current:
                await message.reply_text(
                    "📌 /wa allow-list is empty.\n"
                    "Add a group with:\n"
                    "/setwa <group_id>\n"
                    "or run /setwa here inside a group."
                )
            else:
                txt = "\n".join(f"• <code>{g}</code>" for g in current)
                await message.reply_text(
                    "📌 <b>/wa allowed groups</b>\n"
                    "━━━━━━━━━━━━━━━━━━\n" + txt,
                    parse_mode="HTML",
                )
            return

        first = str(args[0]).strip().lower()
        second = str(args[1]).strip().lower() if len(args) > 1 else ""

        if first == "here":
            chat = update.effective_chat
            if not chat or getattr(chat, "type", "") not in ("group", "supergroup"):
                await message.reply_text("🚫 /setwa here only works inside a group.")
                return
            groups = _wax_set_wa_group(int(chat.id), add=True)
            await message.reply_text(
                "✅ This group is now allowed for /wa\n"
                f"🆔 <code>{chat.id}</code>\n"
                f"Total allowed: <b>{len(groups)}</b>",
                parse_mode="HTML",
            )
            return

        # parse numeric group id
        try:
            target = int(first)
        except Exception:
            await message.reply_text(
                "⚠️ Invalid usage.\n"
                "<b>/setwa &lt;group_id&gt;</b>\n"
                "<b>/setwa &lt;group_id&gt; off</b>\n"
                "<b>/setwa here</b>",
                parse_mode="HTML",
            )
            return

        if second in ("off", "remove", "del", "delete", "0", "false"):
            groups = _wax_set_wa_group(target, add=False)
            await message.reply_text(
                "🗑 Removed from /wa allow-list.\n"
                f"🆔 <code>{target}</code>\n"
                f"Total allowed: <b>{len(groups)}</b>",
                parse_mode="HTML",
            )
        else:
            groups = _wax_set_wa_group(target, add=True)
            await message.reply_text(
                "✅ Added to /wa allow-list.\n"
                f"🆔 <code>{target}</code>\n"
                f"Total allowed: <b>{len(groups)}</b>",
                parse_mode="HTML",
            )
    except Exception as e:
        _wax_log().error(f"[wa_patch] /setwa error: {e}")
        try:
            await update.message.reply_text("⚠️ /setwa failed. Please try again.")
        except Exception:
            pass


# ───────────────────────────────────────────────────────────────────────
#  /dpay  —  Reply to a user with /dpay <amount> to gift diamonds
#  Rules:
#     • Sender must reply to the recipient's message
#     • Recipient must not be a bot, and not == sender
#     • Amount must be a positive integer
#     • Sender's diamond (kakera) balance must be >= amount
#     • Atomic transfer; saves DB
# ───────────────────────────────────────────────────────────────────────
def _wax_get_diamonds(uid) -> int:
    b = _wax_bot()
    if not b:
        return 0
    try:
        prof = b.data.setdefault("user_profiles", {}).setdefault(str(uid), {})
        return int(prof.get("kakera", 0) or 0)
    except Exception:
        return 0


def _wax_set_diamonds(uid, value: int) -> int:
    b = _wax_bot()
    if not b:
        return 0
    try:
        prof = b.data.setdefault("user_profiles", {}).setdefault(str(uid), {})
        new_bal = max(0, int(value))
        prof["kakera"] = new_bal
        return new_bal
    except Exception:
        return 0


def _wax_parse_amount(text: str) -> Optional[int]:
    if text is None:
        return None
    s = str(text).strip().lower().replace(",", "").replace("_", "")
    if not s:
        return None
    mult = 1
    suffixes = {"k": 1_000, "m": 1_000_000, "b": 1_000_000_000, "t": 1_000_000_000_000}
    if s[-1] in suffixes:
        mult = suffixes[s[-1]]
        s = s[:-1]
    try:
        val = float(s)
    except Exception:
        return None
    val = int(val * mult)
    return val if val > 0 else None


def _wax_fmt_int(n: int) -> str:
    try:
        return f"{int(n):,}"
    except Exception:
        return str(n)


async def _wax_dpay_cmd(update, context):
    try:
        message = getattr(update, "message", None)
        if message is None:
            return

        sender = update.effective_user
        if sender is None:
            return

        # Global ban check
        try:
            b_check = _wax_bot()
            if b_check and hasattr(b_check, "is_gbanned") and b_check.is_gbanned(sender.id):
                await message.reply_text("❌ You are globally banned.")
                return
        except Exception:
            pass

        reply = getattr(message, "reply_to_message", None)
        if reply is None or reply.from_user is None:
            await message.reply_text(
                "📌 <b>Usage</b>\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "Reply to a user with:\n"
                "<code>/dpay &lt;amount&gt;</code>\n\n"
                "Example: <code>/dpay 1000</code>",
                parse_mode="HTML",
            )
            return

        recipient = reply.from_user

        if getattr(recipient, "is_bot", False):
            await message.reply_text("🚫 You cannot send diamonds to a bot.")
            return

        if int(recipient.id) == int(sender.id):
            await message.reply_text("🚫 You cannot send diamonds to yourself.")
            return

        args = list(getattr(context, "args", []) or [])
        if not args:
            await message.reply_text(
                "⚠️ Missing amount.\n"
                "<code>/dpay &lt;amount&gt;</code>",
                parse_mode="HTML",
            )
            return

        amount = _wax_parse_amount(args[0])
        if amount is None or amount <= 0:
            await message.reply_text("⚠️ Invalid amount. Use a positive integer.")
            return

        bal = _wax_get_diamonds(sender.id)
        if bal < amount:
            await message.reply_text(
                "💸 <b>Insufficient diamonds</b>\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"💎 You have : <code>{_wax_fmt_int(bal)}</code>\n"
                f"💎 Needed   : <code>{_wax_fmt_int(amount)}</code>",
                parse_mode="HTML",
            )
            return

        # Atomic transfer
        new_sender_bal    = _wax_set_diamonds(sender.id, bal - amount)
        new_recipient_bal = _wax_set_diamonds(
            recipient.id, _wax_get_diamonds(recipient.id) + amount
        )

        # Persist
        try:
            b_save = _wax_bot()
            if b_save:
                b_save.save_data()
        except Exception:
            pass

        sender_name    = (sender.first_name or "User") + (
            f" (@{sender.username})" if sender.username else ""
        )
        recipient_name = (recipient.first_name or "User") + (
            f" (@{recipient.username})" if recipient.username else ""
        )

        await message.reply_text(
            "💎 <b>Diamond Transfer Successful</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"👤 <b>From</b> : {sender_name}\n"
            f"👥 <b>To</b>   : {recipient_name}\n"
            f"💎 <b>Amount</b> : <code>{_wax_fmt_int(amount)}</code>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"📉 Your Balance      : <code>{_wax_fmt_int(new_sender_bal)}</code>\n"
            f"📈 Recipient Balance : <code>{_wax_fmt_int(new_recipient_bal)}</code>\n"
            "\n"
            f"🔗 join - {_WAX_JOIN_HANDLE}",
            parse_mode="HTML",
        )
    except Exception as e:
        _wax_log().error(f"[wa_patch] /dpay error: {e}")
        try:
            await update.message.reply_text("⚠️ /dpay failed. Please try again.")
        except Exception:
            pass


# ───────────────────────────────────────────────────────────────────────
#  Registration — runs after the host file has built its Application
# ───────────────────────────────────────────────────────────────────────
_WAX_REGISTERED_APPS = set()


def _wax_register(application) -> None:
    if application is None or _WAX_CmdH is None:
        return
    try:
        key = id(application)
    except Exception:
        key = None
    if key is not None and key in _WAX_REGISTERED_APPS:
        return
    if key is not None:
        _WAX_REGISTERED_APPS.add(key)

    try:
        # group=-4 so this /wa takes precedence over the older one at -3
        application.add_handler(_WAX_CmdH("wa",     _wax_wa_cmd),    group=-4)
        application.add_handler(_WAX_CmdH("setwa",  _wax_setwa_cmd), group=-4)
        application.add_handler(_WAX_CmdH("dpay",   _wax_dpay_cmd),  group=-4)
        _wax_log().info("[wa_patch] ✅ /wa  /setwa  /dpay  registered")
    except Exception as e:
        _wax_log().error(f"[wa_patch] register failed: {e}")

    # Initial auto-repair pass
    try:
        _wax_auto_repair_once()
    except Exception:
        pass


def _wax_install_post_init_hook() -> None:
    """Patch Application.__init__ to register our handlers after build."""
    if _WAX_App is None:
        return
    g = globals()
    if g.get("_WAX_POST_INIT_INSTALLED"):
        return
    try:
        orig_init = _WAX_App.__init__
    except Exception:
        return
    if getattr(orig_init, "_wax_wrapped", False):
        return

    def _patched_init(self, *a, **kw):
        orig_init(self, *a, **kw)
        try:
            _wax_register(self)
        except Exception as e:
            _wax_log().error(f"[wa_patch] register-on-init failed: {e}")

    _patched_init._wax_wrapped = True  # type: ignore[attr-defined]
    try:
        _WAX_App.__init__ = _patched_init  # type: ignore[assignment]
        g["_WAX_POST_INIT_INSTALLED"] = True
    except Exception as e:
        _wax_log().error(f"[wa_patch] App.__init__ patch failed: {e}")


try:
    _wax_install_post_init_hook()
except Exception as _wax_e:
    try:
        _wax_log().error(f"[wa_patch] install failed: {_wax_e}")
    except Exception:
        pass

# ═══════════════════════════════════════════════════════════════════════
#  END  /wa  ENHANCEMENT PATCH
# ═══════════════════════════════════════════════════════════════════════





# ═══════════════════════════════════════════════════════════════════════
#  📌 PATCH PACK — CMODE  +  /wa CLEANUP  +  /harem BUTTON OWNERSHIP
#  -----------------------------------------------------------------------
#  This block is APPEND-ONLY. It NEVER modifies any earlier code in
#  this file — original data, original handlers, original UI all remain
#  intact. Everything below is layered on top via monkey-patching.
#
#  Features added
#    1. /cmode  →  Per-user Collection Mode (Rarity filter) for
#                  /harem, /mywaifu, /collection.
#                  • Dynamic Rarity buttons pulled from RARITIES live.
#                  • 📦 Default (All) restores normal view.
#                  • Persisted in bot.data['cmode_users'].
#    2. /wa     →  Duplicate registrations disabled, only the
#                  group=-4 enhanced handler stays. Join Group button
#                  shown when user/chat is not in the allow-list.
#                  Membership check + exception handling.
#    3. /harem  →  Inline buttons usable ONLY by the user who issued
#                  /harem (button ownership guard).
# ═══════════════════════════════════════════════════════════════════════

import logging as _cmpx_logging
from collections import Counter as _CMPX_Counter, OrderedDict as _CMPX_OrderedDict

try:
    from telegram import (
        InlineKeyboardButton as _CMPX_IKB,
        InlineKeyboardMarkup as _CMPX_IKM,
        Update as _CMPX_Update,
    )
    from telegram.ext import (
        CommandHandler as _CMPX_CmdH,
        CallbackQueryHandler as _CMPX_CbH,
        ContextTypes as _CMPX_Ctx,
        Application as _CMPX_App,
    )
except Exception:  # pragma: no cover
    _CMPX_IKB = None
    _CMPX_IKM = None
    _CMPX_Update = None
    _CMPX_CmdH = None
    _CMPX_CbH = None
    _CMPX_Ctx = None
    _CMPX_App = None


def _cmpx_log():
    try:
        return logger  # type: ignore[name-defined]
    except Exception:
        return _cmpx_logging.getLogger("cmode_patch")


def _cmpx_bot():
    try:
        return bot  # type: ignore[name-defined]
    except Exception:
        return None


# ───────────────────────────────────────────────────────────────────────
#  CMODE — per-user collection-mode storage
# ───────────────────────────────────────────────────────────────────────
_CMPX_DATA_KEY = "cmode_users"


def _cmpx_get_user_mode(uid):
    """Return the rarity_key the user has selected, or None for default."""
    b = _cmpx_bot()
    if not b:
        return None
    try:
        store = b.data.setdefault(_CMPX_DATA_KEY, {})
        val = store.get(str(uid))
        if val in (None, "", "all", "ALL", "default", "Default"):
            return None
        return str(val)
    except Exception:
        return None


def _cmpx_set_user_mode(uid, rarity_key):
    """Persist user's mode selection. rarity_key=None → default (all)."""
    b = _cmpx_bot()
    if not b:
        return
    try:
        store = b.data.setdefault(_CMPX_DATA_KEY, {})
        if rarity_key is None:
            store.pop(str(uid), None)
        else:
            store[str(uid)] = str(rarity_key)
        try:
            b.save_data()
        except Exception as _e:
            _cmpx_log().warning(f"[cmode] save_data failed: {_e}")
    except Exception as e:
        _cmpx_log().error(f"[cmode] set_user_mode error: {e}")


def _cmpx_rarity_items():
    """Dynamically pull rarity items from RARITIES (and optional DB overrides).
    Returns list of (key, info_dict) sorted by numeric key when possible.
    """
    items = []
    try:
        R = RARITIES  # type: ignore[name-defined]
        if isinstance(R, dict):
            for k, v in R.items():
                if isinstance(v, dict):
                    items.append((str(k), v))
    except Exception:
        pass

    # Optional DB-level custom rarities (auto-extension)
    try:
        b = _cmpx_bot()
        if b:
            custom = (b.settings.get("custom_rarities") if hasattr(b, "settings") else None) or {}
            if isinstance(custom, dict):
                for k, v in custom.items():
                    if isinstance(v, dict) and str(k) not in {ik for ik, _ in items}:
                        items.append((str(k), v))
    except Exception:
        pass

    # Sort by integer if possible, else lexicographic
    def _key(kv):
        k = kv[0]
        try:
            return (0, int(k))
        except Exception:
            return (1, k)

    items.sort(key=_key)
    return items


def _cmpx_rarity_label(key, info):
    disp = info.get("display") or f"{info.get('emoji','')} {info.get('name', key)}".strip()
    return disp or f"Rarity {key}"


# ───────────────────────────────────────────────────────────────────────
#  /cmode  command + callback
# ───────────────────────────────────────────────────────────────────────
async def _cmpx_cmode_cmd(update, context):
    """Open the Collection Mode panel."""
    try:
        message = getattr(update, "message", None)
        if message is None:
            return
        user = update.effective_user
        if user is None:
            return

        current_key = _cmpx_get_user_mode(user.id)
        current_label = "📦 Default (All)"
        if current_key:
            try:
                info = RARITIES.get(current_key) if "RARITIES" in globals() else None  # type: ignore[name-defined]
            except Exception:
                info = None
            if info:
                current_label = _cmpx_rarity_label(current_key, info)

        text = (
            "🎴 <b>Collection Mode (CMODE)</b>\n"
            "━━━━━━━━━━━━━━━━━━━━━━\n"
            f"👤 User: <b>{getattr(user, 'first_name', '') or 'You'}</b>\n"
            f"🎯 Current Mode: <b>{current_label}</b>\n\n"
            "Select an option below:"
        )

        kb = [
            [_CMPX_IKB("🎯 Rarity", callback_data=f"cmode|r|{user.id}")],
            [_CMPX_IKB("📦 Default (All)", callback_data=f"cmode|d|{user.id}")],
            [_CMPX_IKB("❌ Cancel", callback_data=f"cmode|x|{user.id}")],
        ]
        await message.reply_text(text, reply_markup=_CMPX_IKM(kb), parse_mode="HTML")
    except Exception as e:
        _cmpx_log().error(f"[cmode] /cmode error: {e}")
        try:
            await update.message.reply_text("⚠️ Failed to open Collection Mode panel.")
        except Exception:
            pass


async def _cmpx_cmode_callback(update, context):
    """Handle all cmode|* button presses."""
    query = update.callback_query
    if query is None:
        return
    try:
        data = str(query.data or "")
        parts = data.split("|")
        if len(parts) < 2 or parts[0] != "cmode":
            await query.answer()
            return

        action = parts[1]
        owner_id = None
        if len(parts) >= 3 and parts[2].lstrip("-").isdigit():
            owner_id = int(parts[2])

        clicker_id = query.from_user.id if query.from_user else 0
        if owner_id is not None and owner_id != clicker_id:
            await query.answer("🚫 This panel is not for you.", show_alert=True)
            return

        # ── Action: open rarity sub-panel ──
        if action == "r":
            items = _cmpx_rarity_items()
            if not items:
                await query.answer("No rarities available.", show_alert=True)
                return

            buttons = []
            row = []
            for k, info in items:
                label = _cmpx_rarity_label(k, info)
                # truncate overly long labels for clean grid
                if len(label) > 18:
                    label = label[:17] + "…"
                row.append(_CMPX_IKB(label, callback_data=f"cmode|s|{clicker_id}|{k}"))
                if len(row) == 2:
                    buttons.append(row)
                    row = []
            if row:
                buttons.append(row)

            buttons.append([
                _CMPX_IKB("📦 Default (All)", callback_data=f"cmode|d|{clicker_id}"),
                _CMPX_IKB("⬅️ Back", callback_data=f"cmode|b|{clicker_id}"),
            ])
            buttons.append([_CMPX_IKB("❌ Cancel", callback_data=f"cmode|x|{clicker_id}")])

            await query.answer()
            try:
                await query.message.edit_text(
                    "🎯 <b>Select Rarity</b>\n"
                    "━━━━━━━━━━━━━━━━━━━━━━\n"
                    "Only cards of the chosen rarity will appear\n"
                    "in /harem, /mywaifu and /collection.",
                    reply_markup=_CMPX_IKM(buttons),
                    parse_mode="HTML",
                )
            except Exception:
                await query.message.reply_text(
                    "🎯 Select Rarity:",
                    reply_markup=_CMPX_IKM(buttons),
                )
            return

        # ── Action: back to root panel ──
        if action == "b":
            current_key = _cmpx_get_user_mode(clicker_id)
            current_label = "📦 Default (All)"
            if current_key:
                try:
                    info = RARITIES.get(current_key)  # type: ignore[name-defined]
                except Exception:
                    info = None
                if info:
                    current_label = _cmpx_rarity_label(current_key, info)
            text = (
                "🎴 <b>Collection Mode (CMODE)</b>\n"
                "━━━━━━━━━━━━━━━━━━━━━━\n"
                f"🎯 Current Mode: <b>{current_label}</b>\n\n"
                "Select an option below:"
            )
            kb = [
                [_CMPX_IKB("🎯 Rarity", callback_data=f"cmode|r|{clicker_id}")],
                [_CMPX_IKB("📦 Default (All)", callback_data=f"cmode|d|{clicker_id}")],
                [_CMPX_IKB("❌ Cancel", callback_data=f"cmode|x|{clicker_id}")],
            ]
            await query.answer()
            try:
                await query.message.edit_text(text, reply_markup=_CMPX_IKM(kb), parse_mode="HTML")
            except Exception:
                pass
            return

        # ── Action: set rarity ──
        if action == "s":
            if len(parts) < 4:
                await query.answer("⚠️ Bad selection.", show_alert=True)
                return
            rarity_key = parts[3]
            try:
                info = RARITIES.get(rarity_key)  # type: ignore[name-defined]
            except Exception:
                info = None
            if not info:
                await query.answer("⚠️ Unknown rarity.", show_alert=True)
                return
            _cmpx_set_user_mode(clicker_id, rarity_key)
            label = _cmpx_rarity_label(rarity_key, info)
            await query.answer(f"✅ Mode set: {label}", show_alert=False)
            try:
                await query.message.edit_text(
                    "🎴 <b>Collection Mode Updated</b>\n"
                    "━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"🎯 Now showing only: <b>{label}</b>\n\n"
                    "Use /harem to view filtered list.\n"
                    "Use /cmode again to change mode.",
                    parse_mode="HTML",
                )
            except Exception:
                pass
            return

        # ── Action: default (all) ──
        if action == "d":
            _cmpx_set_user_mode(clicker_id, None)
            await query.answer("✅ Filter cleared. Showing ALL cards.", show_alert=False)
            try:
                await query.message.edit_text(
                    "🎴 <b>Collection Mode</b>\n"
                    "━━━━━━━━━━━━━━━━━━━━━━\n"
                    "📦 Default (All) — filter cleared.\n"
                    "Your harem now shows every card.",
                    parse_mode="HTML",
                )
            except Exception:
                pass
            return

        # ── Action: cancel ──
        if action == "x":
            await query.answer("Cancelled.")
            try:
                await query.message.edit_text("❌ Collection Mode panel closed.")
            except Exception:
                pass
            return

        await query.answer()
    except Exception as e:
        _cmpx_log().error(f"[cmode] callback error: {e}")
        try:
            await query.answer("⚠️ Action failed.", show_alert=False)
        except Exception:
            pass


# ───────────────────────────────────────────────────────────────────────
#  Patch _build_harem_anime_text → apply CMODE filter (non-destructive)
# ───────────────────────────────────────────────────────────────────────
try:
    _CMPX_ORIG_BUILD_HAREM = _build_harem_anime_text  # type: ignore[name-defined]
except Exception:
    _CMPX_ORIG_BUILD_HAREM = None


def _cmpx_build_harem_anime_text(user, page: int):
    """Wrapper that applies CMODE filter (per-user rarity filter) on top of
    the ORIGINAL _build_harem_anime_text. Original logic untouched.
    """
    if _CMPX_ORIG_BUILD_HAREM is None:
        return None, None, 0

    b = _cmpx_bot()
    if not b:
        return _CMPX_ORIG_BUILD_HAREM(user, page)

    try:
        uid_str = str(user.id)
        mode = _cmpx_get_user_mode(user.id)
        if not mode:
            return _CMPX_ORIG_BUILD_HAREM(user, page)

        users_map = b.data.get("users", {}) or {}
        original_cards = list(users_map.get(uid_str, []) or [])
        if not original_cards:
            return _CMPX_ORIG_BUILD_HAREM(user, page)

        # Build a filtered list — only cards matching the selected rarity
        cards_db = b.data.get("cards", {}) or {}
        filtered = []
        for cid in original_cards:
            c = cards_db.get(str(cid))
            if not c:
                continue
            if str(c.get("rarity", "1")) == str(mode):
                filtered.append(cid)

        if not filtered:
            # No cards of this rarity → return informative empty payload
            try:
                info = RARITIES.get(str(mode), {})  # type: ignore[name-defined]
                label = _cmpx_rarity_label(str(mode), info)
            except Exception:
                label = f"Rarity {mode}"
            text = (
                f"🎴 USER HAREM\n"
                f"━━━━━━━━━━━━━━━━━━\n"
                f"🎯 Filter: {label}\n\n"
                f"😢 You don't own any cards of this rarity yet.\n"
                f"Use /cmode → 📦 Default (All) to clear the filter."
            )
            kb = [[_CMPX_IKB("📦 Show All", callback_data=f"cmode|d|{user.id}")]]
            return text, _CMPX_IKM(kb), 0

        # Temporarily swap the user's card list, call original, then restore
        users_map[uid_str] = filtered
        try:
            text, markup, max_page = _CMPX_ORIG_BUILD_HAREM(user, page)
        finally:
            users_map[uid_str] = original_cards

        # Prepend a filter banner so user knows CMODE is active
        if text:
            try:
                info = RARITIES.get(str(mode), {})  # type: ignore[name-defined]
                label = _cmpx_rarity_label(str(mode), info)
            except Exception:
                label = f"Rarity {mode}"
            banner = f"🎯 CMODE Filter: {label}\n"
            text = banner + text
        return text, markup, max_page
    except Exception as e:
        _cmpx_log().error(f"[cmode] build_harem wrap error: {e}")
        try:
            return _CMPX_ORIG_BUILD_HAREM(user, page)
        except Exception:
            return None, None, 0


try:
    if _CMPX_ORIG_BUILD_HAREM is not None:
        globals()["_build_harem_anime_text"] = _cmpx_build_harem_anime_text
        _cmpx_log().info("[cmode] _build_harem_anime_text wrapped ✅")
except Exception as _e:
    _cmpx_log().warning(f"[cmode] wrap _build_harem_anime_text failed: {_e}")


# ───────────────────────────────────────────────────────────────────────
#  /harem button ownership guard
#  Only the user who issued /harem may use its inline buttons.
# ───────────────────────────────────────────────────────────────────────
try:
    _CMPX_ORIG_HAREM_CB = harem_callback  # type: ignore[name-defined]
except Exception:
    _CMPX_ORIG_HAREM_CB = None


async def _cmpx_harem_callback(update, context):
    """Patched harem callback — checks button ownership before delegating."""
    if _CMPX_ORIG_HAREM_CB is None:
        return
    try:
        query = update.callback_query
        if query is None:
            return
        clicker = query.from_user
        msg = query.message

        # Determine the original harem owner via reply_to_message
        owner_id = None
        try:
            rtm = getattr(msg, "reply_to_message", None)
            if rtm and getattr(rtm, "from_user", None):
                owner_id = rtm.from_user.id
        except Exception:
            owner_id = None

        if owner_id is None:
            # Fallback: if we can't determine owner (e.g. very old message),
            # allow the click but log a warning.
            _cmpx_log().info("[harem-guard] owner unknown, allowing click.")
        elif clicker and clicker.id != owner_id:
            try:
                await query.answer(
                    "🚫 ဒီ Harem panel က မင်းအတွက် မဟုတ်ပါ — /harem ကိုကိုယ်တိုင် ပြန်သုံးပါ။",
                    show_alert=True,
                )
            except Exception:
                pass
            return

        await _CMPX_ORIG_HAREM_CB(update, context)
    except Exception as e:
        _cmpx_log().error(f"[harem-guard] callback error: {e}")
        try:
            await update.callback_query.answer("⚠️ Action failed.", show_alert=False)
        except Exception:
            pass


try:
    if _CMPX_ORIG_HAREM_CB is not None:
        globals()["harem_callback"] = _cmpx_harem_callback
        _cmpx_log().info("[harem-guard] harem_callback wrapped ✅")
except Exception as _e:
    _cmpx_log().warning(f"[harem-guard] wrap failed: {_e}")


# ───────────────────────────────────────────────────────────────────────
#  /wa cleanup — disable duplicate registrations
# ───────────────────────────────────────────────────────────────────────
# There were three places registering /wa:
#   • _wa_register_handlers  (group=-3, basic)
#   • immortal_shop fallback (group=-3, basic)
#   • _wax_register          (group=-4, ENHANCED — the one we keep)
#
# We neuter the first two so only the enhanced /wa stays. No code is
# deleted; we just replace them with no-op stubs.
try:
    def _cmpx_noop_register(*_a, **_kw):  # type: ignore[no-redef]
        return None

    if "_wa_register_handlers" in globals():
        globals()["_wa_register_handlers"] = _cmpx_noop_register
        _cmpx_log().info("[wa-dedupe] legacy _wa_register_handlers disabled ✅")
except Exception as _e:
    _cmpx_log().warning(f"[wa-dedupe] disable legacy failed: {_e}")


# ───────────────────────────────────────────────────────────────────────
#  /wa enhanced refusal — Join Group button when user is not in allow-list
# ───────────────────────────────────────────────────────────────────────
try:
    _CMPX_ORIG_WAX_WA = _wax_wa_cmd  # type: ignore[name-defined]
except Exception:
    _CMPX_ORIG_WAX_WA = None


async def _cmpx_build_join_buttons(context, group_ids):
    """Resolve group_ids → list of InlineKeyboardButton rows for joining.
    Public groups (with username) get a t.me link.
    Private groups are listed by id only (no button).
    """
    rows = []
    if not group_ids:
        return rows
    for gid in group_ids:
        try:
            chat = await context.bot.get_chat(int(gid))
            username = getattr(chat, "username", None)
            title = getattr(chat, "title", None) or f"Group {gid}"
            if username:
                rows.append([_CMPX_IKB(f"🔗 Join {title}", url=f"https://t.me/{username}")])
            else:
                # Private group → cannot share a join link, mention it instead.
                rows.append([_CMPX_IKB(f"👥 {title} (private)", callback_data="cmpx_noop")])
        except Exception as e:
            _cmpx_log().info(f"[wa-join] resolve {gid} failed: {e}")
    return rows


async def _cmpx_user_in_any_group(context, user_id, group_ids):
    """Check whether the user is a member of at least one allowed group.
    Errors per-group are tolerated — they don't crash the bot.
    """
    if not group_ids:
        return False
    for gid in group_ids:
        try:
            member = await context.bot.get_chat_member(int(gid), int(user_id))
            status = getattr(member, "status", "")
            if status in ("creator", "administrator", "member", "owner"):
                return True
            if status == "restricted":
                # restricted members are still in the group
                is_member = getattr(member, "is_member", False)
                if is_member:
                    return True
        except Exception as e:
            _cmpx_log().info(f"[wa-join] membership-check {gid} failed: {e}")
            continue
    return False


async def _cmpx_wax_wa_cmd(update, context):
    """Wrap the enhanced /wa command.
    Adds Join-Group buttons and per-user membership check on top of the
    existing chat-level allow-list logic.
    """
    if _CMPX_ORIG_WAX_WA is None:
        return
    try:
        message = getattr(update, "message", None)
        if message is None:
            return

        try:
            uid = update.effective_user.id if update.effective_user else 0
        except Exception:
            uid = 0

        # Owner bypass (mirrors original behaviour)
        try:
            is_owner = _wax_is_real_owner(uid)  # type: ignore[name-defined]
        except Exception:
            is_owner = False

        if not is_owner:
            try:
                groups = _wax_get_wa_groups()  # type: ignore[name-defined]
            except Exception:
                groups = []

            if groups:
                in_group = await _cmpx_user_in_any_group(context, uid, groups)
                if not in_group:
                    rows = await _cmpx_build_join_buttons(context, groups)
                    text = (
                        "❌ <b>WA Command ကို အသုံးပြုရန်</b>\n"
                        "━━━━━━━━━━━━━━━━━━\n"
                        "သတ်မှတ်ထားသော Group ကို အရင် Join လုပ်ရန် လိုအပ်ပါသည်။\n\n"
                        "🔗 အောက်က Button ကို နှိပ်ပြီး Join လုပ်ပါ။"
                    )
                    try:
                        await message.reply_text(
                            text,
                            reply_markup=_CMPX_IKM(rows) if rows else None,
                            parse_mode="HTML",
                        )
                    except Exception:
                        await message.reply_text(text)
                    return

        # Pass-through to original enhanced /wa
        await _CMPX_ORIG_WAX_WA(update, context)
    except Exception as e:
        _cmpx_log().error(f"[wa-join] /wa wrapper error: {e}")
        try:
            await _CMPX_ORIG_WAX_WA(update, context)
        except Exception:
            try:
                await update.message.reply_text(
                    "⚠️ /wa စစ်ဆေးနေစဉ် ပြသနာတစ်ခုဖြစ်ပေါ်ခဲ့ပါသည်။ နောက်ထပ်ပြန်ကြိုးစားပါ။"
                )
            except Exception:
                pass


try:
    if _CMPX_ORIG_WAX_WA is not None:
        globals()["_wax_wa_cmd"] = _cmpx_wax_wa_cmd
        _cmpx_log().info("[wa-join] _wax_wa_cmd wrapped ✅")
except Exception as _e:
    _cmpx_log().warning(f"[wa-join] wrap failed: {_e}")


# ───────────────────────────────────────────────────────────────────────
#  Register /cmode command + cmode callback (post-Application build hook)
# ───────────────────────────────────────────────────────────────────────
_CMPX_REGISTERED_APPS = set()


def _cmpx_register(application) -> None:
    if application is None or _CMPX_CmdH is None or _CMPX_CbH is None:
        return
    try:
        key = id(application)
    except Exception:
        key = None
    if key is not None and key in _CMPX_REGISTERED_APPS:
        return
    if key is not None:
        _CMPX_REGISTERED_APPS.add(key)

    try:
        application.add_handler(_CMPX_CmdH("cmode", _cmpx_cmode_cmd), group=-5)
        application.add_handler(_CMPX_CbH(_cmpx_cmode_callback, pattern=r"^cmode\|"), group=-5)
        _cmpx_log().info("[cmode] ✅ /cmode + callback registered")
    except Exception as e:
        _cmpx_log().error(f"[cmode] register failed: {e}")


def _cmpx_install_post_init_hook() -> None:
    """Patch Application.__init__ to register cmode handlers after build."""
    if _CMPX_App is None:
        return
    g = globals()
    if g.get("_CMPX_POST_INIT_INSTALLED"):
        return
    try:
        _orig_init = _CMPX_App.__init__

        def _patched_init(self, *a, **kw):
            _orig_init(self, *a, **kw)
            try:
                _cmpx_register(self)
            except Exception as e:
                _cmpx_log().error(f"[cmode] post-init register failed: {e}")

        _patched_init._cmpx_wrapped = True  # type: ignore[attr-defined]
        _CMPX_App.__init__ = _patched_init
        g["_CMPX_POST_INIT_INSTALLED"] = True
    except Exception as e:
        _cmpx_log().error(f"[cmode] App.__init__ patch failed: {e}")


try:
    _cmpx_install_post_init_hook()
except Exception as _cmpx_e:
    try:
        _cmpx_log().error(f"[cmode] install failed: {_cmpx_e}")
    except Exception:
        pass

# ═══════════════════════════════════════════════════════════════════════
#  END  PATCH PACK
