import asyncio as _AU_asyncio
import json as _AU_json
import logging as _AU_logging
import os as _AU_os
import time as _AU_time
import uuid as _AU_uuid
from datetime import datetime as _AU_dt, timedelta as _AU_td

try:
    from telegram import (
        Update as _AU_Update,
        InlineKeyboardButton as _AU_IKB,
        InlineKeyboardMarkup as _AU_IKM,
    )
    from telegram.ext import (
        Application as _AU_App,
        CommandHandler as _AU_CmdH,
        CallbackQueryHandler as _AU_CbH,
        ContextTypes as _AU_Ctx,
    )
    from telegram.error import TelegramError as _AU_TgErr
except Exception:  # pragma: no cover
    _AU_Update = None  # type: ignore
    _AU_IKB = None  # type: ignore
    _AU_IKM = None  # type: ignore
    _AU_App = None  # type: ignore
    _AU_CmdH = None  # type: ignore
    _AU_CbH = None  # type: ignore
    _AU_Ctx = None  # type: ignore
    _AU_TgErr = Exception  # type: ignore


def _au_log():
    try:
        return logger  # type: ignore[name-defined]
    except Exception:
        return _AU_logging.getLogger("auction_house")


def _au_bot():
    try:
        return bot  # type: ignore[name-defined]
    except Exception:
        return None


# ───────────────────────────────────────────────────────────────────────
#  Configuration & helpers
# ───────────────────────────────────────────────────────────────────────
_AU_DATA_KEY = "auctions"                # bot.data[_AU_DATA_KEY] = {auction_id: dict}
_AU_LOCK_KEY = "auction_locked_cards"     # bot.data[_AU_LOCK_KEY] = {card_id: auction_id}
_AU_DURATION_MAP = {                       # button choice → seconds
    "6h":  6 * 3600,
    "12h": 12 * 3600,
    "24h": 24 * 3600,
    "48h": 48 * 3600,
}
_AU_DEFAULT_MIN_INCREMENT = 10             # diamonds
_AU_TAX_PERCENT = 5                        # 5% tax to /setb receiver
_AU_TICKER_TASKS: dict = {}                # auction_id -> asyncio.Task
_AU_PENDING_AUCTIONS: dict = {}            # seller_uid -> draft (during duration prompt)
_AU_GROUP_CHAT_INDEX: dict = {}            # auction_id -> (chat_id, message_id) for live updates


def _au_now_ts() -> int:
    return int(_AU_time.time())


def _au_get_min_increment() -> int:
    """Admin can override min increment by setting bot.settings['auction_min_increment']."""
    b = _au_bot()
    if not b:
        return _AU_DEFAULT_MIN_INCREMENT
    try:
        v = int(b.settings.get("auction_min_increment", _AU_DEFAULT_MIN_INCREMENT) or _AU_DEFAULT_MIN_INCREMENT)
        return v if v >= 1 else _AU_DEFAULT_MIN_INCREMENT
    except Exception:
        return _AU_DEFAULT_MIN_INCREMENT


def _au_get_store() -> dict:
    b = _au_bot()
    if not b:
        return {}
    return b.data.setdefault(_AU_DATA_KEY, {})


def _au_get_lock_store() -> dict:
    b = _au_bot()
    if not b:
        return {}
    return b.data.setdefault(_AU_LOCK_KEY, {})


def _au_save():
    b = _au_bot()
    if not b:
        return
    try:
        b.save_data()
    except Exception as e:
        _au_log().warning(f"[auction] save_data failed: {e}")


def _au_fmt_int(n) -> str:
    try:
        return f"{int(n):,}"
    except Exception:
        return str(n)


def _au_fmt_time_left(remaining: int) -> str:
    if remaining < 0:
        remaining = 0
    h = remaining // 3600
    m = (remaining % 3600) // 60
    s = remaining % 60
    return f"{h:02d}:{m:02d}:{s:02d}"


def _au_html_escape(text) -> str:
    if text is None:
        return ""
    try:
        s = str(text)
    except Exception:
        return ""
    return (
        s.replace("&", "&amp;")
         .replace("<", "&lt;")
         .replace(">", "&gt;")
    )


def _au_html_mention(user_id, name) -> str:
    safe = _au_html_escape(name or str(user_id))
    return f'<a href="tg://user?id={int(user_id)}">{safe}</a>'


def _au_get_card(card_id):
    b = _au_bot()
    if not b:
        return None
    return b.data.get("cards", {}).get(str(card_id))


def _au_user_owns_card(uid: str, card_id: str) -> bool:
    b = _au_bot()
    if not b:
        return False
    cards = b.data.get("users", {}).get(str(uid), [])
    return str(card_id) in cards


def _au_remove_card_from_user(uid: str, card_id: str) -> bool:
    """Remove first occurrence of card_id from user's card list. Returns True if removed."""
    b = _au_bot()
    if not b:
        return False
    cards = b.data.get("users", {}).get(str(uid))
    if not cards or str(card_id) not in cards:
        return False
    try:
        cards = list(cards)
        cards.remove(str(card_id))
        b.data["users"][str(uid)] = cards
        return True
    except Exception as e:
        _au_log().error(f"[auction] remove_card_from_user error: {e}")
        return False


def _au_give_card_to_user(uid: str, card_id: str) -> None:
    b = _au_bot()
    if not b:
        return
    try:
        # initialise the user if helper exists
        try:
            init_user_if_not_exists(str(uid))  # type: ignore[name-defined]
        except Exception:
            pass
        users = b.data.setdefault("users", {})
        lst = users.setdefault(str(uid), [])
        lst.append(str(card_id))
        # update card ownership pointer too
        try:
            card = b.data.get("cards", {}).get(str(card_id))
            if isinstance(card, dict):
                card["owner"] = int(uid)
                # try to derive a name from user_profiles
                name = b.data.get("user_profiles", {}).get(str(uid), {}).get("name") \
                       or b.data.get("user_profiles", {}).get(str(uid), {}).get("first_name")
                if name:
                    card["owner_name"] = str(name)
        except Exception:
            pass
    except Exception as e:
        _au_log().error(f"[auction] give_card error: {e}")


def _au_get_diamonds(uid) -> int:
    """Re-uses the host bot's diamond storage (user_profiles[uid]['kakera'])."""
    b = _au_bot()
    if not b:
        return 0
    try:
        prof = b.data.setdefault("user_profiles", {}).setdefault(str(uid), {})
        return int(prof.get("kakera", 0) or 0)
    except Exception:
        return 0


def _au_set_diamonds(uid, value: int) -> int:
    b = _au_bot()
    if not b:
        return 0
    try:
        prof = b.data.setdefault("user_profiles", {}).setdefault(str(uid), {})
        new_bal = max(0, int(value))
        prof["kakera"] = new_bal
        return new_bal
    except Exception:
        return 0


def _au_add_diamonds(uid, delta: int) -> int:
    cur = _au_get_diamonds(uid)
    return _au_set_diamonds(uid, cur + int(delta))


def _au_get_tax_receiver():
    """Return (receiver_id, receiver_name) from the existing setb_config.json cache."""
    try:
        c = _FA_SETB_CACHE  # type: ignore[name-defined]
        rid = c.get("receiver_id")
        if rid:
            return int(rid), c.get("receiver_name") or "Tax Receiver"
    except Exception:
        pass
    return None, None


def _au_get_username(uid) -> str:
    b = _au_bot()
    if not b:
        return f"User-{uid}"
    try:
        prof = b.data.get("user_profiles", {}).get(str(uid), {}) or {}
        for k in ("name", "first_name", "username", "display_name"):
            v = prof.get(k)
            if v:
                return str(v)
    except Exception:
        pass
    return f"User-{uid}"


def _au_card_is_locked(card_id) -> bool:
    return str(card_id) in _au_get_lock_store()


def _au_lock_card(card_id, auction_id) -> None:
    _au_get_lock_store()[str(card_id)] = str(auction_id)


def _au_unlock_card(card_id) -> None:
    s = _au_get_lock_store()
    s.pop(str(card_id), None)


# ───────────────────────────────────────────────────────────────────────
#  AUCTION CORE — create / bid / buy-now / cancel / settle / expire
# ───────────────────────────────────────────────────────────────────────
_AU_STATUS_DRAFT     = "draft"      # waiting for duration choice
_AU_STATUS_ACTIVE    = "active"
_AU_STATUS_SOLD      = "sold"
_AU_STATUS_EXPIRED   = "expired"
_AU_STATUS_CANCELLED = "cancelled"


def _au_new_auction_id() -> str:
    return _AU_uuid.uuid4().hex[:10]


def _au_make_draft(seller_id: int, seller_name: str, card_id: str, start_price: int, buy_now) -> dict:
    return {
        "auction_id": _au_new_auction_id(),
        "seller_id": int(seller_id),
        "seller_name": str(seller_name),
        "card_id": str(card_id),
        "start_price": int(start_price),
        "current_bid": 0,
        "highest_bidder_id": None,
        "highest_bidder_name": None,
        "buy_now_price": int(buy_now) if buy_now else None,
        "start_time": None,
        "end_time": None,
        "duration_sec": None,
        "status": _AU_STATUS_DRAFT,
        "watchers": [],
        "bid_history": [],  # list of {uid, name, amount, ts}
        "winner_id": None,
        "winner_name": None,
        "final_price": None,
        "group_chat_id": None,
        "group_message_id": None,
        "near_end_notified": False,
    }


def _au_build_ui_text(a: dict, footer_msg: str = "") -> str:
    card = _au_get_card(a["card_id"]) or {}
    name = card.get("name", "Unknown")
    movie = card.get("movie", "")
    rarity_key = str(card.get("rarity", "1"))
    try:
        rarity_info = RARITIES.get(rarity_key, RARITIES["1"])  # type: ignore[name-defined]
        rarity_disp = rarity_info.get("display", "💮 Common")
    except Exception:
        rarity_disp = "💮 Common"

    if a["status"] == _AU_STATUS_ACTIVE:
        remaining = max(0, int(a["end_time"]) - _au_now_ts())
        timer = _au_fmt_time_left(remaining)
        status_line = f"⏰ <b>Time Left</b>     : <code>{timer}</code>"
    elif a["status"] == _AU_STATUS_SOLD:
        status_line = "🏆 <b>Status</b>        : <code>SOLD</code>"
    elif a["status"] == _AU_STATUS_EXPIRED:
        status_line = "⌛ <b>Status</b>        : <code>EXPIRED</code>"
    elif a["status"] == _AU_STATUS_CANCELLED:
        status_line = "🚫 <b>Status</b>        : <code>CANCELLED</code>"
    else:
        status_line = "📝 <b>Status</b>        : <code>DRAFT</code>"

    if a["highest_bidder_id"]:
        bidder_line = (
            f"👑 <b>Highest Bidder</b>: "
            f"{_au_html_mention(a['highest_bidder_id'], a['highest_bidder_name'])}"
        )
        bid_line = f"💎 <b>Current Bid</b>   : <code>{_au_fmt_int(a['current_bid'])}</code>"
    else:
        bidder_line = "👑 <b>Highest Bidder</b>: <i>None yet</i>"
        bid_line = "💎 <b>Current Bid</b>   : <code>—</code>"

    buy_now_line = ""
    if a.get("buy_now_price"):
        buy_now_line = f"⚡ <b>Buy Now</b>       : <code>{_au_fmt_int(a['buy_now_price'])}</code>\n"

    text = (
        "🏛️ <b>𝐃𝐈𝐀𝐌𝐎𝐍𝐃 𝐀𝐔𝐂𝐓𝐈𝐎𝐍 𝐇𝐎𝐔𝐒𝐄</b>\n"
        "━━━━━━━━━━━━━━━━━━━━━\n"
        f"🆔 <b>Card ID</b>       : <code>#{_au_html_escape(a['card_id'])}</code>\n"
        f"👤 <b>Character</b>     : <code>{_au_html_escape(name)}</code>\n"
        f"🎬 <b>Movie</b>         : <code>{_au_html_escape(movie)}</code>\n"
        f"⭐ <b>Rarity</b>        : {_au_html_escape(rarity_disp)}\n"
        "━━━━━━━━━━━━━━━━━━━━━\n"
        f"💎 <b>Starting Price</b>: <code>{_au_fmt_int(a['start_price'])}</code>\n"
        f"{bid_line}\n"
        f"{buy_now_line}"
        f"{bidder_line}\n"
        "━━━━━━━━━━━━━━━━━━━━━\n"
        f"🧾 <b>Auction ID</b>    : <code>{_au_html_escape(a['auction_id'])}</code>\n"
        f"💼 <b>Seller</b>        : {_au_html_mention(a['seller_id'], a['seller_name'])}\n"
        f"{status_line}"
    )
    if footer_msg:
        text += f"\n\n{footer_msg}"
    return text


def _au_build_keyboard(a: dict) -> "_AU_IKM":
    aid = a["auction_id"]
    if a["status"] != _AU_STATUS_ACTIVE:
        return _AU_IKM([[_AU_IKB("📜 View My Auctions", callback_data=f"au|noop|{aid}")]])
    row1 = [
        _AU_IKB("💎 Bid", callback_data=f"au|bid|{aid}"),
    ]
    if a.get("buy_now_price"):
        row1.append(_AU_IKB("⚡ Buy Now", callback_data=f"au|buynow|{aid}"))
    row1.append(_AU_IKB("⭐ Watch", callback_data=f"au|watch|{aid}"))
    row2 = [
        _AU_IKB("ℹ️ Refresh", callback_data=f"au|refresh|{aid}"),
        _AU_IKB("🚫 Cancel (Seller)", callback_data=f"au|cancel|{aid}"),
    ]
    return _AU_IKM([row1, row2])


def _au_duration_keyboard(card_id: str) -> "_AU_IKM":
    rows = [
        [
            _AU_IKB("⏱ 6 Hours",  callback_data=f"au|dur|{card_id}|6h"),
            _AU_IKB("⏱ 12 Hours", callback_data=f"au|dur|{card_id}|12h"),
        ],
        [
            _AU_IKB("⏱ 24 Hours", callback_data=f"au|dur|{card_id}|24h"),
            _AU_IKB("⏱ 48 Hours", callback_data=f"au|dur|{card_id}|48h"),
        ],
        [
            _AU_IKB("✖ Cancel", callback_data=f"au|durcancel|{card_id}"),
        ],
    ]
    return _AU_IKM(rows)


# ───────────────────────────────────────────────────────────────────────
#  /auction   <card_id>  <start_price>  [buy_now]
# ───────────────────────────────────────────────────────────────────────
async def _au_auction_cmd(update, context):
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user:
        return

    try:
        if bot.is_gbanned(user.id):  # type: ignore[name-defined]
            await msg.reply_text("❌ You are globally banned.")
            return
    except Exception:
        pass

    args = context.args or []
    if len(args) < 2:
        await msg.reply_text(
            "📝 <b>Usage</b>\n"
            "<code>/auction &lt;card_id&gt; &lt;start_price&gt; [buy_now]</code>\n\n"
            "<b>Examples</b>\n"
            "• <code>/auction 152 500</code>\n"
            "• <code>/auction 152 500 1500</code>",
            parse_mode="HTML"
        )
        return

    card_id = str(args[0]).strip()
    try:
        start_price = int(str(args[1]).strip().replace(",", ""))
    except Exception:
        await msg.reply_text("❌ Starting price ကို integer အဖြစ်ထည့်ပါ။")
        return

    buy_now = None
    if len(args) >= 3:
        try:
            buy_now = int(str(args[2]).strip().replace(",", ""))
        except Exception:
            await msg.reply_text("❌ Buy-Now price ကို integer အဖြစ်ထည့်ပါ။")
            return

    if start_price <= 0:
        await msg.reply_text("❌ Starting price က 0 ထက်ကြီးရမည်။")
        return
    if buy_now is not None and buy_now <= start_price:
        await msg.reply_text("❌ Buy-Now price က Starting price ထက် ပိုကြီးရမည်။")
        return

    # Card existence
    card = _au_get_card(card_id)
    if not card:
        await msg.reply_text(f"❌ Card ID <code>#{_au_html_escape(card_id)}</code> ကို database ထဲ မတွေ့ပါ။", parse_mode="HTML")
        return

    # Ownership
    if not _au_user_owns_card(str(user.id), card_id):
        await msg.reply_text("❌ ဒီ Card သည် သင်ပိုင်ဆိုင်မှု မဟုတ်ပါ။")
        return

    # Anti-double-listing
    if _au_card_is_locked(card_id):
        await msg.reply_text("⚠️ ဒီ Card သည် တခြား Auction တစ်ခုထဲမှာ Lock ထားနေပါသည်။")
        return

    seller_name = user.first_name or user.username or f"User-{user.id}"
    draft = _au_make_draft(user.id, seller_name, card_id, start_price, buy_now)
    _AU_PENDING_AUCTIONS[str(user.id)] = draft

    await msg.reply_text(
        "⏳ <b>Auction Duration ရွေးပါ</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"🆔 Card ID : <code>#{_au_html_escape(card_id)}</code>\n"
        f"💎 Start   : <code>{_au_fmt_int(start_price)}</code>\n"
        + (f"⚡ Buy Now : <code>{_au_fmt_int(buy_now)}</code>\n" if buy_now else "")
        + "━━━━━━━━━━━━━━━━━━\n"
        "အောက်က Button များမှ Duration ရွေးပါ။",
        parse_mode="HTML",
        reply_markup=_au_duration_keyboard(card_id),
    )


# ───────────────────────────────────────────────────────────────────────
#  Duration callback → ACTIVATE the auction
# ───────────────────────────────────────────────────────────────────────
async def _au_activate(query, duration_key: str):
    user = query.from_user
    draft = _AU_PENDING_AUCTIONS.get(str(user.id))
    if not draft:
        await query.edit_message_text("⚠️ Pending auction draft မတွေ့ပါ။ /auction ဖြင့် ပြန်စပါ။")
        return

    # Re-validate ownership & not locked
    if not _au_user_owns_card(str(user.id), draft["card_id"]):
        _AU_PENDING_AUCTIONS.pop(str(user.id), None)
        await query.edit_message_text("❌ ဒီ Card သည် သင်ပိုင်ဆိုင်မှု မဟုတ်တော့ပါ။")
        return
    if _au_card_is_locked(draft["card_id"]):
        _AU_PENDING_AUCTIONS.pop(str(user.id), None)
        await query.edit_message_text("⚠️ Card ကို Lock ဖြစ်နေပါပြီ။ ပြန်ကြိုးစားပါ။")
        return

    duration = _AU_DURATION_MAP.get(duration_key)
    if not duration:
        await query.edit_message_text("❌ Invalid duration.")
        return

    draft["start_time"]   = _au_now_ts()
    draft["end_time"]     = draft["start_time"] + duration
    draft["duration_sec"] = duration
    draft["status"]       = _AU_STATUS_ACTIVE
    try:
        draft["group_chat_id"] = query.message.chat_id
    except Exception:
        pass

    # Persist
    store = _au_get_store()
    store[draft["auction_id"]] = draft
    _au_lock_card(draft["card_id"], draft["auction_id"])
    _au_save()
    _AU_PENDING_AUCTIONS.pop(str(user.id), None)

    # Send the live auction message in this chat
    text = _au_build_ui_text(draft)
    kb   = _au_build_keyboard(draft)
    try:
        sent = await query.message.reply_text(text, parse_mode="HTML", reply_markup=kb)
        draft["group_message_id"] = sent.message_id
        _AU_GROUP_CHAT_INDEX[draft["auction_id"]] = (sent.chat_id, sent.message_id)
        _au_save()
    except Exception as e:
        _au_log().error(f"[auction] send active message failed: {e}")

    # Update the prompt
    try:
        await query.edit_message_text(
            f"✅ Auction Activated!\n🧾 ID: <code>{_au_html_escape(draft['auction_id'])}</code>\n"
            f"⏰ Duration: <b>{duration_key}</b>",
            parse_mode="HTML",
        )
    except Exception:
        pass

    # Schedule background expiry watcher
    _au_schedule_ticker(draft["auction_id"])


def _au_schedule_ticker(auction_id: str) -> None:
    """Launch an asyncio task that will settle the auction when time expires."""
    try:
        loop = _AU_asyncio.get_event_loop()
    except Exception:
        return
    if auction_id in _AU_TICKER_TASKS and not _AU_TICKER_TASKS[auction_id].done():
        return
    task = loop.create_task(_au_ticker_worker(auction_id))
    _AU_TICKER_TASKS[auction_id] = task


async def _au_ticker_worker(auction_id: str):
    """Background watcher: waits until end_time, then settles the auction.
    Also fires a 'near-end' notification 5 minutes before the end."""
    try:
        while True:
            store = _au_get_store()
            a = store.get(auction_id)
            if not a or a["status"] != _AU_STATUS_ACTIVE:
                return
            remaining = int(a["end_time"]) - _au_now_ts()
            if remaining <= 0:
                await _au_finalize_auction(auction_id)
                return
            # near-end notification (≤ 5 min remaining)
            if remaining <= 300 and not a.get("near_end_notified"):
                a["near_end_notified"] = True
                _au_save()
                await _au_notify_near_end(a)
            # sleep until next event boundary (max 60s)
            await _AU_asyncio.sleep(min(60, remaining))
    except _AU_asyncio.CancelledError:
        return
    except Exception as e:
        _au_log().error(f"[auction] ticker_worker {auction_id} error: {e}")


async def _au_notify_near_end(a: dict):
    """DM each watcher that the auction is about to end."""
    b = _au_bot()
    if not b:
        return
    try:
        application = getattr(b, "application", None) or globals().get("_AU_APP_REF")
        tg_bot = application.bot if application is not None else None
    except Exception:
        tg_bot = None
    if tg_bot is None:
        return

    card = _au_get_card(a["card_id"]) or {}
    msg = (
        "⏰ <b>Auction Ending Soon!</b>\n"
        f"🆔 Card: <code>#{_au_html_escape(a['card_id'])}</code> — "
        f"{_au_html_escape(card.get('name',''))}\n"
        f"💎 Current Bid: <code>{_au_fmt_int(a['current_bid'] or a['start_price'])}</code>\n"
        f"🧾 Auction ID: <code>{_au_html_escape(a['auction_id'])}</code>"
    )
    for uid in a.get("watchers", []):
        try:
            await tg_bot.send_message(int(uid), msg, parse_mode="HTML")
        except Exception:
            pass


# ───────────────────────────────────────────────────────────────────────
#  Callback dispatcher: au|<action>|<args...>
# ───────────────────────────────────────────────────────────────────────
async def _au_callback(update, context):
    q = update.callback_query
    if not q:
        return
    try:
        await q.answer()
    except Exception:
        pass

    data = (q.data or "").split("|")
    if len(data) < 2:
        return
    action = data[1]

    try:
        if action == "dur" and len(data) >= 4:
            # data[2] = card_id (informational), data[3] = duration_key
            await _au_activate(q, data[3])
            return
        if action == "durcancel":
            _AU_PENDING_AUCTIONS.pop(str(q.from_user.id), None)
            await q.edit_message_text("✖ Auction listing cancelled.")
            return
        if action == "noop":
            return

        auction_id = data[2] if len(data) >= 3 else None
        if not auction_id:
            return
        a = _au_get_store().get(auction_id)
        if not a:
            await q.edit_message_text("❌ Auction not found.")
            return

        if action == "refresh":
            await _au_safe_update_message(context.bot, a, footer="🔄 Refreshed.")
            return

        if action == "watch":
            uid = q.from_user.id
            if uid == a["seller_id"]:
                try:
                    await q.answer("မိမိ Auction ကို Watch မလုပ်နိုင်ပါ။", show_alert=True)
                except Exception:
                    pass
                return
            watchers = a.setdefault("watchers", [])
            if uid in watchers:
                watchers.remove(uid)
                _au_save()
                try:
                    await q.answer("⭐ Watch ဖျက်ပြီးပါပြီ။", show_alert=False)
                except Exception:
                    pass
            else:
                watchers.append(uid)
                _au_save()
                try:
                    await q.answer("⭐ Watching ✅", show_alert=False)
                except Exception:
                    pass
            return

        if action == "cancel":
            uid = q.from_user.id
            if uid != a["seller_id"]:
                try:
                    await q.answer("Seller သာ Cancel လုပ်နိုင်သည်။", show_alert=True)
                except Exception:
                    pass
                return
            if a["status"] != _AU_STATUS_ACTIVE:
                try:
                    await q.answer("Active auction သာ Cancel လုပ်နိုင်သည်။", show_alert=True)
                except Exception:
                    pass
                return
            if a["highest_bidder_id"]:
                try:
                    await q.answer("Bid တင်ပြီးပါက Cancel မရပါ။", show_alert=True)
                except Exception:
                    pass
                return
            a["status"] = _AU_STATUS_CANCELLED
            _au_unlock_card(a["card_id"])
            _au_save()
            await _au_safe_update_message(context.bot, a, footer="🚫 Cancelled by seller.")
            return

        if action == "bid":
            await _au_prompt_bid(context, q, a)
            return

        if action == "buynow":
            await _au_buy_now(context, q, a)
            return

    except Exception as e:
        _au_log().error(f"[auction] callback error: {e}")
        try:
            await q.answer("⚠️ ပြသနာဖြစ်နေသည်။", show_alert=True)
        except Exception:
            pass


# ── Bid flow ────────────────────────────────────────────────────────────
_AU_PENDING_BIDS: dict = {}  # (chat_id, user_id) -> auction_id


async def _au_prompt_bid(context, query, a):
    uid = query.from_user.id
    if uid == a["seller_id"]:
        try:
            await query.answer("မိမိ Auction ကို Bid မလုပ်နိုင်ပါ။", show_alert=True)
        except Exception:
            pass
        return
    if a["status"] != _AU_STATUS_ACTIVE:
        try:
            await query.answer("Auction က Active မဟုတ်တော့ပါ။", show_alert=True)
        except Exception:
            pass
        return

    min_inc = _au_get_min_increment()
    current = a["current_bid"] or a["start_price"]
    next_min = current + min_inc if a["highest_bidder_id"] else a["start_price"]

    _AU_PENDING_BIDS[(query.message.chat_id, uid)] = a["auction_id"]
    try:
        await query.message.reply_text(
            "💎 <b>Place your Bid</b>\n"
            "━━━━━━━━━━━━━━━━\n"
            f"🧾 Auction ID : <code>{_au_html_escape(a['auction_id'])}</code>\n"
            f"💎 Min Bid    : <code>{_au_fmt_int(next_min)}</code>\n"
            "━━━━━━━━━━━━━━━━\n"
            "👉 ဒီ message ကို reply လုပ်ပြီး bid amount တစ်ခုထဲ ပို့ပါ။\n"
            "ဥပမာ : <code>900</code>\n\n"
            "ဒါမှမဟုတ်  <code>/bid {aid} 900</code>".replace("{aid}", a["auction_id"]),
            parse_mode="HTML",
        )
    except Exception:
        pass


async def _au_bid_cmd(update, context):
    """/bid <auction_id> <amount>"""
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user:
        return
    args = context.args or []
    if len(args) < 2:
        await msg.reply_text(
            "📝 <b>Usage</b>\n<code>/bid &lt;auction_id&gt; &lt;amount&gt;</code>",
            parse_mode="HTML",
        )
        return
    try:
        amount = int(str(args[1]).strip().replace(",", ""))
    except Exception:
        await msg.reply_text("❌ Amount ကို integer အဖြစ်ထည့်ပါ။")
        return
    await _au_apply_bid(context, msg, user, args[0], amount)


async def _au_apply_bid(context, reply_target, user, auction_id, amount):
    a = _au_get_store().get(str(auction_id))
    if not a:
        await reply_target.reply_text("❌ Auction not found.")
        return
    if a["status"] != _AU_STATUS_ACTIVE:
        await reply_target.reply_text("❌ Auction က Active မဟုတ်ပါ။")
        return
    if user.id == a["seller_id"]:
        await reply_target.reply_text("❌ မိမိ Auction ကို Bid မလုပ်နိုင်ပါ။")
        return
    if amount <= 0:
        await reply_target.reply_text("❌ Amount မမှန်ပါ။")
        return

    min_inc = _au_get_min_increment()
    if not a["highest_bidder_id"]:
        if amount < a["start_price"]:
            await reply_target.reply_text(
                f"❌ Starting Price <code>{_au_fmt_int(a['start_price'])}</code> ထက် မနည်းရပါ။",
                parse_mode="HTML",
            )
            return
    else:
        min_needed = a["current_bid"] + min_inc
        if amount < min_needed:
            await reply_target.reply_text(
                f"❌ အနည်းဆုံး Bid : <code>{_au_fmt_int(min_needed)}</code>",
                parse_mode="HTML",
            )
            return

    # Funds check
    bal = _au_get_diamonds(user.id)
    if bal < amount:
        await reply_target.reply_text(
            f"❌ Diamond မလုံလောက်ပါ။ Balance : <code>{_au_fmt_int(bal)}</code>",
            parse_mode="HTML",
        )
        return

    # Buy-Now check
    if a.get("buy_now_price") and amount >= a["buy_now_price"]:
        await _au_finalize_buy_now(context, a, user.id, user.first_name or _au_get_username(user.id))
        return

    # Record bid
    bidder_name = user.first_name or user.username or _au_get_username(user.id)
    a["current_bid"] = int(amount)
    a["highest_bidder_id"] = int(user.id)
    a["highest_bidder_name"] = str(bidder_name)
    a.setdefault("bid_history", []).append({
        "uid": int(user.id),
        "name": str(bidder_name),
        "amount": int(amount),
        "ts": _au_now_ts(),
    })
    _au_save()

    # Live announcement
    try:
        chat_id, _ = _AU_GROUP_CHAT_INDEX.get(a["auction_id"], (a.get("group_chat_id"), a.get("group_message_id")))
        if chat_id:
            await context.bot.send_message(
                chat_id,
                f"🔥 {_au_html_mention(user.id, bidder_name)} bid "
                f"<b>{_au_fmt_int(amount)}</b> 💎  on Auction <code>{_au_html_escape(a['auction_id'])}</code>",
                parse_mode="HTML",
            )
    except Exception:
        pass

    await _au_safe_update_message(
        context.bot, a, footer=f"💎 New bid by {bidder_name}: <b>{_au_fmt_int(amount)}</b>"
    )


async def _au_text_bid_listener(update, context):
    """If user is in a pending-bid session and sends a number → treat as bid."""
    msg = getattr(update, "effective_message", None)
    user = getattr(update, "effective_user", None)
    if not msg or not user or not msg.text:
        return
    key = (msg.chat_id, user.id)
    aid = _AU_PENDING_BIDS.get(key)
    if not aid:
        return
    text = (msg.text or "").strip().replace(",", "")
    if not text.isdigit():
        return
    _AU_PENDING_BIDS.pop(key, None)
    try:
        amount = int(text)
    except Exception:
        return
    await _au_apply_bid(context, msg, user, aid, amount)


# ── Buy-Now ────────────────────────────────────────────────────────────
async def _au_buy_now(context, query, a):
    uid = query.from_user.id
    if uid == a["seller_id"]:
        try:
            await query.answer("မိမိ Auction ကို Buy-Now မလုပ်နိုင်ပါ။", show_alert=True)
        except Exception:
            pass
        return
    if not a.get("buy_now_price"):
        try:
            await query.answer("Buy-Now သတ်မှတ်မထားပါ။", show_alert=True)
        except Exception:
            pass
        return
    if a["status"] != _AU_STATUS_ACTIVE:
        try:
            await query.answer("Auction က Active မဟုတ်တော့ပါ။", show_alert=True)
        except Exception:
            pass
        return
    bal = _au_get_diamonds(uid)
    if bal < a["buy_now_price"]:
        try:
            await query.answer(f"💎 မလုံလောက်ပါ။ Balance {_au_fmt_int(bal)}", show_alert=True)
        except Exception:
            pass
        return
    name = query.from_user.first_name or _au_get_username(uid)
    await _au_finalize_buy_now(context, a, uid, name)


async def _au_finalize_buy_now(context, a, winner_id, winner_name):
    price = int(a["buy_now_price"])
    # Funds check at the moment of finalisation
    if _au_get_diamonds(winner_id) < price:
        return

    a["current_bid"] = price
    a["highest_bidder_id"] = int(winner_id)
    a["highest_bidder_name"] = str(winner_name)
    a.setdefault("bid_history", []).append({
        "uid": int(winner_id), "name": str(winner_name),
        "amount": price, "ts": _au_now_ts(), "buy_now": True,
    })
    _au_save()
    await _au_settle(context.bot, a, winner_id=winner_id, winner_name=winner_name, final_price=price, buy_now=True)


# ── Finalisation when timer expires ────────────────────────────────────
async def _au_finalize_auction(auction_id: str):
    """Called by the ticker when end_time has been reached."""
    store = _au_get_store()
    a = store.get(auction_id)
    if not a or a["status"] != _AU_STATUS_ACTIVE:
        return

    application = globals().get("_AU_APP_REF")
    tg_bot = application.bot if application is not None else None

    if not a["highest_bidder_id"]:
        # Expired with no bids
        a["status"] = _AU_STATUS_EXPIRED
        _au_unlock_card(a["card_id"])
        _au_save()
        if tg_bot:
            try:
                chat_id, _ = _AU_GROUP_CHAT_INDEX.get(auction_id, (a.get("group_chat_id"), None))
                if chat_id:
                    await tg_bot.send_message(
                        chat_id,
                        f"⌛ <b>Auction Expired</b>\n"
                        f"🆔 Card: <code>#{_au_html_escape(a['card_id'])}</code>\n"
                        f"🧾 ID: <code>{_au_html_escape(auction_id)}</code>\n"
                        f"❌ No bids received.",
                        parse_mode="HTML",
                    )
            except Exception:
                pass
            try:
                await _au_safe_update_message(tg_bot, a, footer="⌛ Expired — No bids.")
            except Exception:
                pass
        return

    await _au_settle(
        tg_bot, a,
        winner_id=a["highest_bidder_id"],
        winner_name=a["highest_bidder_name"],
        final_price=int(a["current_bid"]),
        buy_now=False,
    )


async def _au_settle(tg_bot, a, winner_id, winner_name, final_price, buy_now: bool):
    """Perform the atomic transfer: card→winner, diamonds→seller (minus 5% tax)."""
    if a["status"] not in (_AU_STATUS_ACTIVE,):
        return

    seller_id = int(a["seller_id"])
    seller_name = a.get("seller_name") or _au_get_username(seller_id)

    # 1) Final funds check
    if _au_get_diamonds(winner_id) < final_price:
        _au_log().warning(f"[auction] winner {winner_id} insufficient at settle for {a['auction_id']}")
        # downgrade the auction to expired so card unlocks
        a["status"] = _AU_STATUS_EXPIRED
        _au_unlock_card(a["card_id"])
        _au_save()
        return

    # 2) Atomic diamond movement
    _au_add_diamonds(winner_id, -final_price)
    tax = (final_price * _AU_TAX_PERCENT) // 100
    seller_share = final_price - tax
    _au_add_diamonds(seller_id, seller_share)

    tax_receiver_id, tax_receiver_name = _au_get_tax_receiver()
    if tax_receiver_id and tax > 0:
        _au_add_diamonds(tax_receiver_id, tax)

    # 3) Card transfer
    _au_remove_card_from_user(seller_id, a["card_id"])
    _au_give_card_to_user(winner_id, a["card_id"])
    _au_unlock_card(a["card_id"])

    # 4) Persist + status
    a["status"] = _AU_STATUS_SOLD
    a["winner_id"] = int(winner_id)
    a["winner_name"] = str(winner_name)
    a["final_price"] = int(final_price)
    a["final_tax"] = int(tax)
    a["finalised_at"] = _au_now_ts()
    _au_save()

    # 5) Notifications
    if tg_bot is None:
        return

    card = _au_get_card(a["card_id"]) or {}
    rarity_key = str(card.get("rarity", "1"))
    try:
        rarity_info = RARITIES.get(rarity_key, RARITIES["1"])  # type: ignore[name-defined]
        rarity_disp = rarity_info.get("display", "💮 Common")
    except Exception:
        rarity_disp = "💮 Common"

    # ── Group announcement ──
    group_chat_id, _ = _AU_GROUP_CHAT_INDEX.get(a["auction_id"], (a.get("group_chat_id"), None))
    if group_chat_id:
        try:
            announce = (
                "🏆 <b>𝐀𝐔𝐂𝐓𝐈𝐎𝐍 𝐒𝐎𝐋𝐃!</b>\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🆔 Card     : <code>#{_au_html_escape(a['card_id'])}</code> — "
                f"<b>{_au_html_escape(card.get('name',''))}</b>\n"
                f"⭐ Rarity   : {_au_html_escape(rarity_disp)}\n"
                f"👑 Winner   : {_au_html_mention(winner_id, winner_name)}\n"
                f"💎 Price    : <code>{_au_fmt_int(final_price)}</code>\n"
                f"💼 Seller   : {_au_html_mention(seller_id, seller_name)}\n"
                f"🧾 Tax (5%) : <code>{_au_fmt_int(tax)}</code>\n"
                + (f"⚡ <i>Sold via Buy-Now</i>\n" if buy_now else "")
                + "━━━━━━━━━━━━━━━━━━"
            )
            await tg_bot.send_message(group_chat_id, announce, parse_mode="HTML")
        except Exception:
            pass

    # ── Update original auction message ──
    try:
        await _au_safe_update_message(tg_bot, a, footer="🏆 Auction Settled.")
    except Exception:
        pass

    # ── DM seller / winner / watchers ──
    try:
        await tg_bot.send_message(
            seller_id,
            "💼 <b>Your Auction Sold!</b>\n"
            f"🆔 Card : <code>#{_au_html_escape(a['card_id'])}</code>\n"
            f"💎 Price : <code>{_au_fmt_int(final_price)}</code>\n"
            f"🧾 Tax  : <code>{_au_fmt_int(tax)}</code>\n"
            f"💰 You Received : <code>{_au_fmt_int(seller_share)}</code>",
            parse_mode="HTML",
        )
    except Exception:
        pass
    try:
        await tg_bot.send_message(
            winner_id,
            "🏆 <b>You Won the Auction!</b>\n"
            f"🆔 Card : <code>#{_au_html_escape(a['card_id'])}</code> — "
            f"<b>{_au_html_escape(card.get('name',''))}</b>\n"
            f"💎 Price : <code>{_au_fmt_int(final_price)}</code>",
            parse_mode="HTML",
        )
    except Exception:
        pass

    # ── DM the tax receiver (bot account configured via /setb) ──
    if tax_receiver_id and tax > 0:
        try:
            await tg_bot.send_message(
                tax_receiver_id,
                "🧾 <b>Auction Tax Collected</b>\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🆔 Auction : <code>{_au_html_escape(a['auction_id'])}</code>\n"
                f"💎 Tax (5%) : <code>{_au_fmt_int(tax)}</code>\n"
                f"💼 From Seller : {_au_html_mention(seller_id, seller_name)}\n"
                f"👑 Winner : {_au_html_mention(winner_id, winner_name)}",
                parse_mode="HTML",
            )
        except Exception:
            pass

    # Watchers
    for uid in a.get("watchers", []):
        try:
            await tg_bot.send_message(
                int(uid),
                f"🏁 Auction <code>{_au_html_escape(a['auction_id'])}</code> ended.\n"
                f"🏆 Winner: {_au_html_mention(winner_id, winner_name)}\n"
                f"💎 Price : <code>{_au_fmt_int(final_price)}</code>",
                parse_mode="HTML",
            )
        except Exception:
            pass


# ── Safe live-update of the original auction message ───────────────────
async def _au_safe_update_message(tg_bot, a, footer: str = ""):
    if tg_bot is None:
        return
    chat_id, msg_id = _AU_GROUP_CHAT_INDEX.get(
        a["auction_id"], (a.get("group_chat_id"), a.get("group_message_id"))
    )
    if not chat_id or not msg_id:
        return
    text = _au_build_ui_text(a, footer_msg=footer)
    kb = _au_build_keyboard(a)
    try:
        await tg_bot.edit_message_text(
            chat_id=chat_id, message_id=msg_id,
            text=text, parse_mode="HTML",
            reply_markup=kb,
        )
    except Exception:
        # ignore "message not modified" / not found errors
        pass


# ───────────────────────────────────────────────────────────────────────
#  /auctions  — list all active auctions
# ───────────────────────────────────────────────────────────────────────
async def _au_auctions_cmd(update, context):
    msg = update.effective_message
    store = _au_get_store()
    actives = [a for a in store.values() if a.get("status") == _AU_STATUS_ACTIVE]
    actives.sort(key=lambda x: x.get("end_time", 0))

    if not actives:
        await msg.reply_text(
            "🏛️ <b>𝐃𝐈𝐀𝐌𝐎𝐍𝐃 𝐀𝐔𝐂𝐓𝐈𝐎𝐍 𝐇𝐎𝐔𝐒𝐄</b>\n━━━━━━━━━━━━━━━━━\nℹ️ Active auction မရှိသေးပါ။",
            parse_mode="HTML",
        )
        return

    lines = [
        "🏛️ <b>𝐀𝐂𝐓𝐈𝐕𝐄 𝐀𝐔𝐂𝐓𝐈𝐎𝐍𝐒</b>",
        "━━━━━━━━━━━━━━━━━━━━━",
    ]
    for a in actives[:30]:
        card = _au_get_card(a["card_id"]) or {}
        remaining = max(0, int(a["end_time"]) - _au_now_ts())
        lines.append(
            f"🧾 <code>{_au_html_escape(a['auction_id'])}</code>  "
            f"🆔 <code>#{_au_html_escape(a['card_id'])}</code> "
            f"— <b>{_au_html_escape(card.get('name',''))}</b>\n"
            f"   💎 Current: <code>{_au_fmt_int(a['current_bid'] or a['start_price'])}</code>"
            + (f"  ⚡ BuyNow: <code>{_au_fmt_int(a['buy_now_price'])}</code>" if a.get('buy_now_price') else "")
            + f"  ⏰ <code>{_au_fmt_time_left(remaining)}</code>"
        )
    if len(actives) > 30:
        lines.append(f"\n… and {len(actives) - 30} more.")
    await msg.reply_text("\n".join(lines), parse_mode="HTML")


# ───────────────────────────────────────────────────────────────────────
#  /myauctions  — Selling / Sold / Expired views for the caller
# ───────────────────────────────────────────────────────────────────────
async def _au_myauctions_cmd(update, context):
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user:
        return
    uid = int(user.id)
    store = _au_get_store()
    mine = [a for a in store.values() if int(a.get("seller_id", 0)) == uid]
    if not mine:
        await msg.reply_text("ℹ️ သင်တင်ထားသော Auction တစ်ခုမှ မရှိသေးပါ။")
        return
    selling = [a for a in mine if a["status"] == _AU_STATUS_ACTIVE]
    sold    = [a for a in mine if a["status"] == _AU_STATUS_SOLD]
    expired = [a for a in mine if a["status"] in (_AU_STATUS_EXPIRED, _AU_STATUS_CANCELLED)]

    def _block(title, items, show_price_key):
        lines = [f"\n<b>{title}</b>", "━━━━━━━━━━━━━━━━━━"]
        if not items:
            lines.append("<i>— None —</i>")
            return lines
        for a in items[:15]:
            card = _au_get_card(a["card_id"]) or {}
            price = a.get(show_price_key) or a.get("current_bid") or a.get("start_price") or 0
            lines.append(
                f"🧾 <code>{_au_html_escape(a['auction_id'])}</code>  "
                f"🆔 <code>#{_au_html_escape(a['card_id'])}</code> "
                f"— <b>{_au_html_escape(card.get('name',''))}</b>  "
                f"💎 <code>{_au_fmt_int(price)}</code>"
            )
        return lines

    out = ["🗂 <b>𝐌𝐘  𝐀𝐔𝐂𝐓𝐈𝐎𝐍𝐒</b>"]
    out += _block("🟢 Selling", selling, "current_bid")
    out += _block("🏆 Sold",    sold,    "final_price")
    out += _block("⌛ Expired / Cancelled", expired, "current_bid")
    await msg.reply_text("\n".join(out), parse_mode="HTML")


# ───────────────────────────────────────────────────────────────────────
#  ANTI-SCAM:  block trade/sell/gift/delete on locked cards
# ───────────────────────────────────────────────────────────────────────
def _au_install_antiscam_guards():
    """Wrap existing trade/sell/gift/delete commands so that a card currently
    being auctioned cannot be moved or destroyed.

    The wrappers run BEFORE the original handler; if the request involves a
    locked card we reply with a notice and return early — the original handler
    is never reached. All other requests pass through untouched.
    """
    g = globals()

    def _ids_from_args(args):
        out = []
        for a in args or []:
            sa = str(a).strip()
            if sa.isdigit() or (sa.startswith("#") and sa[1:].isdigit()):
                out.append(sa.lstrip("#"))
        return out

    async def _au_blocked_reply(update, card_id, action_name):
        try:
            await update.message.reply_text(
                f"🔒 Card <code>#{_au_html_escape(card_id)}</code> သည် Auction ထဲမှာ Lock ဖြစ်နေပါသည်။\n"
                f"❌ <b>{action_name}</b> မလုပ်နိုင်ပါ။",
                parse_mode="HTML",
            )
        except Exception:
            pass

    # ── /trade wrapper ──
    orig_trade = g.get("trade_cmd")
    if callable(orig_trade) and not getattr(orig_trade, "_au_wrapped", False):
        async def _au_trade_wrap(update, context):
            try:
                args = context.args or []
                if len(args) >= 1 and _au_card_is_locked(args[0]):
                    await _au_blocked_reply(update, args[0], "Trade")
                    return
                if len(args) >= 2 and _au_card_is_locked(args[1]):
                    await _au_blocked_reply(update, args[1], "Trade")
                    return
            except Exception:
                pass
            await orig_trade(update, context)
        _au_trade_wrap._au_wrapped = True  # type: ignore[attr-defined]
        g["trade_cmd"] = _au_trade_wrap

    # ── /sell wrapper ──
    orig_sell = g.get("sell_cmd")
    if callable(orig_sell) and not getattr(orig_sell, "_au_wrapped", False):
        async def _au_sell_wrap(update, context):
            try:
                args = context.args or []
                if args and _au_card_is_locked(args[0]):
                    await _au_blocked_reply(update, args[0], "Sell")
                    return
            except Exception:
                pass
            await orig_sell(update, context)
        _au_sell_wrap._au_wrapped = True  # type: ignore[attr-defined]
        g["sell_cmd"] = _au_sell_wrap

    # ── /gift wrapper ──
    orig_gift = g.get("gift")
    if callable(orig_gift) and not getattr(orig_gift, "_au_wrapped", False):
        async def _au_gift_wrap(update, context):
            try:
                args = context.args or []
                if args and _au_card_is_locked(args[0]):
                    await _au_blocked_reply(update, args[0], "Gift")
                    return
            except Exception:
                pass
            await orig_gift(update, context)
        _au_gift_wrap._au_wrapped = True  # type: ignore[attr-defined]
        g["gift"] = _au_gift_wrap

    # ── /delete wrapper ──
    orig_del = g.get("delete_cmd")
    if callable(orig_del) and not getattr(orig_del, "_au_wrapped", False):
        async def _au_delete_wrap(update, context):
            try:
                args = context.args or []
                for tok in _ids_from_args(args):
                    if _au_card_is_locked(tok):
                        await _au_blocked_reply(update, tok, "Delete")
                        return
            except Exception:
                pass
            await orig_del(update, context)
        _au_delete_wrap._au_wrapped = True  # type: ignore[attr-defined]
        g["delete_cmd"] = _au_delete_wrap


# ───────────────────────────────────────────────────────────────────────
#  /wa  REMOVAL — replace with a no-op registered at the highest priority
# ───────────────────────────────────────────────────────────────────────
async def _au_wa_disabled_cmd(update, context):
    try:
        await update.message.reply_text(
            "ℹ️ <b>/wa command သည် ပိတ်ထားပြီးပါပြီ။</b>",
            parse_mode="HTML",
        )
    except Exception:
        pass
    # Stop further propagation so the older /wa handlers never run.
    try:
        from telegram.ext import ApplicationHandlerStop as _AU_Stop  # type: ignore
        raise _AU_Stop
    except _AU_Stop:
        raise
    except Exception:
        pass


# ───────────────────────────────────────────────────────────────────────
#  Restore ticker tasks for active auctions after a bot restart
# ───────────────────────────────────────────────────────────────────────
def _au_restore_active_auctions():
    store = _au_get_store()
    for aid, a in list(store.items()):
        if a.get("status") != _AU_STATUS_ACTIVE:
            continue
        # If end_time already passed, mark for immediate finalisation
        try:
            chat_id = a.get("group_chat_id")
            msg_id  = a.get("group_message_id")
            if chat_id and msg_id:
                _AU_GROUP_CHAT_INDEX[aid] = (chat_id, msg_id)
        except Exception:
            pass
        try:
            _au_schedule_ticker(aid)
        except Exception as e:
            _au_log().warning(f"[auction] restore ticker {aid} failed: {e}")


# ───────────────────────────────────────────────────────────────────────
#  Registration — post-init hook
# ───────────────────────────────────────────────────────────────────────
_AU_REGISTERED_APPS = set()
_AU_APP_REF = None


def _au_register(application) -> None:
    global _AU_APP_REF
    if application is None or _AU_CmdH is None:
        return
    try:
        key = id(application)
    except Exception:
        key = None
    if key is not None and key in _AU_REGISTERED_APPS:
        return
    if key is not None:
        _AU_REGISTERED_APPS.add(key)

    _AU_APP_REF = application

    try:
        # /wa kill-switch — earliest priority
        application.add_handler(_AU_CmdH("wa", _au_wa_disabled_cmd), group=-10)

        # Auction commands
        application.add_handler(_AU_CmdH("auction",     _au_auction_cmd),     group=-6)
        application.add_handler(_AU_CmdH("auctions",    _au_auctions_cmd),    group=-6)
        application.add_handler(_AU_CmdH("myauctions",  _au_myauctions_cmd),  group=-6)
        application.add_handler(_AU_CmdH("bid",         _au_bid_cmd),         group=-6)

        # Callback dispatcher
        application.add_handler(_AU_CbH(_au_callback, pattern=r"^au\|"), group=-6)

        # Free-text bid listener (only consumes if user is in a pending bid session)
        try:
            from telegram.ext import MessageHandler as _AU_MsgH, filters as _AU_filters
            application.add_handler(
                _AU_MsgH(_AU_filters.TEXT & ~_AU_filters.COMMAND, _au_text_bid_listener),
                group=-6,
            )
        except Exception:
            pass

        _au_log().info("[auction] ✅ Diamond Auction House commands registered")
    except Exception as e:
        _au_log().error(f"[auction] register failed: {e}")

    # install anti-scam guards (idempotent)
    try:
        _au_install_antiscam_guards()
    except Exception as e:
        _au_log().error(f"[auction] anti-scam install failed: {e}")

    # restore in-flight auctions after restart
    try:
        _au_restore_active_auctions()
    except Exception as e:
        _au_log().error(f"[auction] restore failed: {e}")


def _au_install_post_init_hook() -> None:
    if _AU_App is None:
        return
    g = globals()
    if g.get("_AU_POST_INIT_INSTALLED"):
        return
    try:
        _orig_init = _AU_App.__init__
    except Exception:
        return
    if getattr(_orig_init, "_au_wrapped", False):
        return

    def _patched_init(self, *a, **kw):
        _orig_init(self, *a, **kw)
        try:
            _au_register(self)
        except Exception as e:
            _au_log().error(f"[auction] post-init register failed: {e}")

    _patched_init._au_wrapped = True  # type: ignore[attr-defined]
    try:
        _AU_App.__init__ = _patched_init  # type: ignore[assignment]
        g["_AU_POST_INIT_INSTALLED"] = True
    except Exception as e:
        _au_log().error(f"[auction] App.__init__ patch failed: {e}")


try:
    _au_install_post_init_hook()
except Exception as _au_e:
    try:
        _au_log().error(f"[auction] install failed: {_au_e}")
    except Exception:
        pass

# ═══════════════════════════════════════════════════════════════════════════════
#  END  DIAMOND AUCTION HOUSE PATCH
# ═══════════════════════════════════════════════════════════════════════════════


# ═══════════════════════════════════════════════════════════════════════════════
# 💎  PREMIUM DIAMOND TOP-UP SYSTEM  —  APPEND-ONLY ADD-ON
# ───────────────────────────────────────────────────────────────────────────────
# Non-destructive add-on. Hooks into existing main() via the same
# Application.builder().build() monkey-patch pattern used by other modules.
#
# Features:
#   • /topup        — opens the Premium Diamond Top-Up Center
#   • /diamonds     — already provided by existing wallet module (reused here)
#   • Owner commands:  /setkpay, /setwave, /setton, /setstars, /setpay, /setrate
#   • Inline package picker (Starter / Premium / Elite / Immortal)
#   • Payment-method picker (Telegram Stars / TON / KPay / Wave)
#   • User flow:  Pick package → pick method → see account → "I've Paid"
#                 → upload screenshot → forwarded to owner group with
#                 Approve / Reject buttons
#   • Owner approval auto-credits diamonds to user via _im_add_diamonds()
#   • Persistent JSON config + request history (survives restarts)
# ═══════════════════════════════════════════════════════════════════════════════

