#  JSON  load / save
# ════════════════════════════════════════════════════════════════════════════
def _tp_load_config() -> dict:
    try:
        if _tp_os.path.exists(_TP_CONFIG_FILE):
            with open(_TP_CONFIG_FILE, "r", encoding="utf-8") as f:
                data = _tp_json.load(f)
                # Migrate / merge missing keys
                cfg = dict(_TP_DEFAULT_CONFIG)
                cfg.update(data or {})
                # Ensure 'accounts' subdict exists with all keys
                acc = dict(_TP_DEFAULT_CONFIG["accounts"])
                acc.update((cfg.get("accounts") or {}))
                cfg["accounts"] = acc
                return cfg
    except Exception as e:
        _tp_log.error(f"[topup] load config failed: {e}")
    return dict(_TP_DEFAULT_CONFIG)


def _tp_save_config(cfg: dict) -> None:
    try:
        tmp = _TP_CONFIG_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _tp_json.dump(cfg, f, ensure_ascii=False, indent=2)
        _tp_os.replace(tmp, _TP_CONFIG_FILE)
    except Exception as e:
        _tp_log.error(f"[topup] save config failed: {e}")


def _tp_load_requests() -> dict:
    try:
        if _tp_os.path.exists(_TP_REQUESTS_FILE):
            with open(_TP_REQUESTS_FILE, "r", encoding="utf-8") as f:
                return _tp_json.load(f) or {}
    except Exception as e:
        _tp_log.error(f"[topup] load requests failed: {e}")
    return {}


def _tp_save_requests(reqs: dict) -> None:
    try:
        tmp = _TP_REQUESTS_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _tp_json.dump(reqs, f, ensure_ascii=False, indent=2)
        _tp_os.replace(tmp, _TP_REQUESTS_FILE)
    except Exception as e:
        _tp_log.error(f"[topup] save requests failed: {e}")


def _tp_log_history(line: str) -> None:
    try:
        with open(_TP_HISTORY_LOG, "a", encoding="utf-8") as f:
            f.write(f"[{_tp_dt.utcnow().isoformat()}Z] {line}\n")
    except Exception:
        pass


# Live state
