def _tp_bot():
    try:
        return bot  # type: ignore[name-defined]
    except Exception:
        return None


def _tp_is_owner(user_id) -> bool:
    """Use the existing owner check from the host bot."""
    try:
        b = _tp_bot()
        if b and hasattr(b, "is_owner") and b.is_owner(user_id):
            return True
    except Exception:
        pass
    try:
        return int(user_id) in OWNERS  # type: ignore[name-defined]
    except Exception:
        return False


def _tp_get_package(pid: str):
    for p in _TP_PACKAGES:
        if p["id"] == pid:
            return p
    return None


def _tp_get_method(mid: str):
    for m in _TP_METHODS:
        if m["id"] == mid:
            return m
    return None


def _tp_fmt_int(n) -> str:
    try:
        return f"{int(n):,}"
    except Exception:
        return str(n)


def _tp_add_diamonds_safe(uid: str, amount: int) -> int:
    """Credit diamonds to a user. Reuses existing wallet helper if present."""
    try:
        fn = globals().get("_im_add_diamonds")
        if callable(fn):
            return int(fn(str(uid), int(amount)))
    except Exception as e:
        _tp_log.error(f"[topup] _im_add_diamonds failed: {e}")
    # Fallback: direct bot.data write
    b = _tp_bot()
    if not b:
        return 0
    try:
        prof = b.data.setdefault("user_profiles", {}).setdefault(str(uid), {})
        new_bal = int(prof.get("kakera", 0) or 0) + int(amount)
        if new_bal < 0:
            new_bal = 0
        prof["kakera"] = new_bal
        try:
            b.save_data()
        except Exception:
            pass
        return new_bal
    except Exception as e:
        _tp_log.error(f"[topup] fallback add diamonds failed: {e}")
        return 0


def _tp_get_diamonds_safe(uid: str) -> int:
    try:
        fn = globals().get("_im_get_diamonds")
        if callable(fn):
            return int(fn(str(uid)))
    except Exception:
        pass
    b = _tp_bot()
    if not b:
        return 0
    try:
        prof = b.data.get("user_profiles", {}).get(str(uid), {}) or {}
        return int(prof.get("kakera", 0) or 0)
    except Exception:
        return 0


