def _tp_get_star_rate() -> int:
    """Diamonds per 1 Star."""
    try:
        v = int(_TP_CONFIG.get("star_diamond_rate", 1) or 1)
        return v if v > 0 else 1
    except Exception:
        return 1


def _tp_get_ton_rate() -> int:
    """Diamonds per 1 TON."""
    try:
        v = int(_TP_CONFIG.get("ton_diamond_rate", 1000) or 1000)
        return v if v > 0 else 1000
    except Exception:
        return 1000


def _tp_calc_diamonds(method_id: str, amount: float) -> int:
    """Calculate diamonds for a given amount in Stars or TON."""
    try:
        if method_id == "stars":
            return int(round(float(amount) * _tp_get_star_rate()))
        if method_id == "ton":
            return int(round(float(amount) * _tp_get_ton_rate()))
    except Exception:
        pass
    return 0


