async def _tp_topup_status_cmd(update: _TpUpdate, context: _TpCtx.DEFAULT_TYPE):
    """/topupstatus — owner only, list recent requests."""
    if not await _tp_owner_only_guard(update):
        return
    msg = update.message
    items = list(_TP_REQUESTS.values())
    items.sort(key=lambda r: r.get("ts", 0), reverse=True)
    items = items[:15]
    if not items:
        await msg.reply_text("📜 No top-up requests yet.")
        return
    lines = ["📜 <b>Recent Top-Up Requests</b>", "━━━━━━━━━━━━━━━━━━"]
    for r in items:
        icon = {"pending": "⏳", "uploaded": "📤",
                "approved": "✅", "rejected": "❌"}.get(r.get("status"), "•")
        lines.append(
            f"{icon} <code>{r.get('request_id','?')[:8]}</code> "
            f"u:<code>{r.get('user_id','?')}</code> "
            f"{r.get('pkg_name','?')} • {_tp_fmt_int(r.get('diamonds',0))}💎 "
            f"• {r.get('method_name','?')} • {r.get('status','?').upper()}"
        )
    await msg.reply_text("\n".join(lines), parse_mode="HTML")


# ════════════════════════════════════════════════════════════════════════════
#  Handler registration
# ════════════════════════════════════════════════════════════════════════════
def _tp_register_handlers(app):
    try:
        # User commands
        app.add_handler(_TpCmd("topup",        _tp_topup_cmd))
        app.add_handler(_TpCmd("cancel_topup", _tp_cancel_cmd))

        # Owner commands
        app.add_handler(_TpCmd("setkpay",      _tp_set_kpay_cmd))
        app.add_handler(_TpCmd("setwave",      _tp_set_wave_cmd))
        app.add_handler(_TpCmd("setton",       _tp_set_ton_cmd))
        app.add_handler(_TpCmd("setstars",     _tp_set_stars_cmd))
        app.add_handler(_TpCmd("setpay",       _tp_set_pay_cmd))
        app.add_handler(_TpCmd("setrate",       _tp_set_rate_cmd))
        app.add_handler(_TpCmd("topupstatus",   _tp_topup_status_cmd))

        # ── Star / TON custom price-rate admin commands ────────────────
        app.add_handler(_TpCmd("setstarprice",  _tp_set_star_price_cmd))
        app.add_handler(_TpCmd("editstarprice", _tp_edit_star_price_cmd))
        app.add_handler(_TpCmd("settonprice",   _tp_set_ton_price_cmd))
        app.add_handler(_TpCmd("edittonprice",  _tp_edit_ton_price_cmd))
        app.add_handler(_TpCmd("prices",        _tp_show_prices_cmd))

        # Callback handler — only our prefix
        app.add_handler(_TpCbq(_tp_callback, pattern=r"^tp:"))

        # Photo handler — only triggers for users in pending-upload state.
        # Use a positive group so it runs AFTER any existing photo handlers
        # if they were already set up; PTB delivers to ALL groups so the
        # original screenshot/upload handlers are NOT broken.
        app.add_handler(
            _TpMsg(_tp_filters.PHOTO, _tp_photo_handler),
            group=50,
        )

        # ── Custom-amount text handler  —  high group so existing text
        #    handlers are NOT broken; only fires when user has pending
        #    amount-input state. ─────────────────────────────────────────
        app.add_handler(
            _TpMsg(_tp_filters.TEXT & ~_tp_filters.COMMAND, _tp_amount_text_handler),
            group=51,
        )

        _tp_log.info("[topup] handlers registered (custom-amount mode)")
    except Exception as e:
        _tp_log.error(f"[topup] register failed: {e}")


# ════════════════════════════════════════════════════════════════════════════
#  Hook into existing main() — same Application.builder().build() monkey-patch
#  pattern already used by mission / auction modules in this file.
# ════════════════════════════════════════════════════════════════════════════
def _tp_install_main_wrapper():
    g = globals()
    orig_main = g.get("main")
    if not callable(orig_main) or getattr(orig_main, "_tp_wrapped", False):
        return

    def wrapped_main():
        from telegram.ext import Application as _TP_App
        orig_build = _TP_App.builder().__class__.build

        def patched_build(self, *a, **kw):
            app_obj = orig_build(self, *a, **kw)
            try:
                _tp_register_handlers(app_obj)
            except Exception as e:
                try:
                    _tp_log.error(f"[topup] register hook failed: {e}")
                except Exception:
                    pass
            # Restore so this only fires for the first build()
            _TP_App.builder().__class__.build = orig_build
            return app_obj

        _TP_App.builder().__class__.build = patched_build
        return orig_main()

    wrapped_main._tp_wrapped = True
    g["main"] = wrapped_main


try:
    _tp_install_main_wrapper()
except Exception as _tp_e:
    try:
        _tp_log.error(f"[topup] install failed: {_tp_e}")
    except Exception:
        pass

