# ═══════════════════════════════════════════════════════════════════════════════
#  BLACK MARKET v2 — APPROVAL WORKFLOW + DIAMOND RICH LIST (SIDECAR / APPEND-ONLY)
#  -----------------------------------------------------------------------------
#  • Adds upload-time "Add to Black Market?" popup (✅ Add / ❌ Skip)
#  • Pending list → Owner Approval (✅ Approve / ❌ Reject)
#  • Owner shop controls: /blackadd /blackremove /blackprice /blackstock
#                         /blacklist /blackpending
#  • Limited Time + Discount support
#  • Purchase via /blackmarket <card_id> (overrides legacy when card is in new
#    Black Market; otherwise falls through to legacy immortal_shop handler)
#  • DB Channel: ❌ on pending, ❌ on reject, ✅ on approve only
#  • /topdiamond — Top 10 richest players  (Photo / Video / Text cover)
#  • /settopdiamondphoto /settopdiamondvideo /cleartopdiamondmedia
#
#  100 % append-only. Does NOT modify original code, JSON files, or handlers.
#  Stores data in bot.settings under 'black_market_v2' (new isolated namespace).
# ═══════════════════════════════════════════════════════════════════════════════

# (Note: __future__ annotations already enabled by the parent file)
import asyncio as _bm_asyncio
import logging as _bm_logging
import time as _bm_time
from datetime import datetime as _bm_dt, timedelta as _bm_td

try:
    from telegram import (
        Update as _BM_Update,
        InlineKeyboardButton as _BM_IKB,
        InlineKeyboardMarkup as _BM_IKM,
    )
    from telegram.ext import (
        CommandHandler as _BM_CmdH,
        CallbackQueryHandler as _BM_CbH,
        MessageHandler as _BM_MsgH,
        ContextTypes as _BM_Ctx,
        ApplicationHandlerStop as _BM_Stop,
        filters as _bm_filters,
    )
except Exception:  # pragma: no cover
    _BM_Update = None  # type: ignore
    _BM_IKB = None  # type: ignore
    _BM_IKM = None  # type: ignore
    _BM_CmdH = None  # type: ignore
    _BM_CbH = None  # type: ignore
    _BM_MsgH = None  # type: ignore
    _BM_Ctx = None  # type: ignore
    _BM_Stop = Exception  # type: ignore
    _bm_filters = None  # type: ignore


_bm_logger = _bm_logging.getLogger("blackmarket_v2")


# ─────────────────────────────────────────────────────────────────────────────
#  Storage helpers (uses bot.settings['black_market_v2']) — auto-persisted.
# ─────────────────────────────────────────────────────────────────────────────
def _bm_bot():
    try:
        return bot  # type: ignore[name-defined]
    except Exception:
        return None


def _bm_store():
    """Return the live storage dict (auto-created)."""
    b = _bm_bot()
    if not b:
        return {"approved": {}, "pending": {}, "topdiamond_media": None}
    store = b.settings.setdefault("black_market_v2", {})
    store.setdefault("approved", {})       # card_id -> {price, stock, limited_time_iso, discount, added_at}
    store.setdefault("pending", {})        # card_id -> {uploaded_by_id, uploaded_by_name, requested_at}
    store.setdefault("topdiamond_media", None)  # {type: 'photo'/'video', file_id: str}
    return store


def _bm_save():
    b = _bm_bot()
    if not b:
        return
    try:
        b.save_settings()
    except Exception as e:
        _bm_logger.warning(f"[bm] save_settings failed: {e}")


def _bm_is_owner(uid) -> bool:
    b = _bm_bot()
    if not b:
        return False
    try:
        return bool(b.is_owner(int(uid)))
    except Exception:
        return False


def _bm_card(card_id):
    b = _bm_bot()
    if not b:
        return None
    return (b.data.get("cards", {}) or {}).get(str(card_id))


def _bm_rarity_display(card: dict) -> str:
    try:
        r = str(card.get("rarity", "1"))
        rar = RARITIES.get(r, RARITIES.get("1", {"display": "💮 Common"}))  # type: ignore[name-defined]
        return rar.get("display", "💮 Common")
    except Exception:
        return "💮 Common"


def _bm_role_display(card: dict) -> str:
    try:
        rk = str(card.get("role", "normal")).lower()
        r = ROLES.get(rk, ROLES.get("normal", {"display": "🎴 Normal"}))  # type: ignore[name-defined]
        return r.get("display", "🎴 Normal")
    except Exception:
        return "🎴 Normal"


def _bm_fmt(n) -> str:
    try:
        return f"{int(n):,}"
    except Exception:
        return str(n)


def _bm_get_diamonds(uid) -> int:
    """Read the player's diamond balance — uses immortal_shop's getter
    so both systems share the SAME diamond wallet (kakera field)."""
    try:
        fn = globals().get("_im_get_diamonds")
        if callable(fn):
            return int(fn(str(uid)) or 0)
    except Exception:
        pass
    b = _bm_bot()
    if not b:
        return 0
    try:
        return int((b.data.get("user_profiles", {}).get(str(uid), {}) or {}).get("kakera", 0) or 0)
    except Exception:
        return 0


def _bm_add_diamonds(uid, amount: int) -> int:
    try:
        fn = globals().get("_im_add_diamonds")
        if callable(fn):
            return int(fn(str(uid), int(amount)) or 0)
    except Exception:
        pass
    b = _bm_bot()
    if not b:
        return 0
    prof = b.data.setdefault("user_profiles", {}).setdefault(str(uid), {})
    new_bal = max(0, int(prof.get("kakera", 0) or 0) + int(amount))
    prof["kakera"] = new_bal
    try:
        b.save_data()
    except Exception:
        pass
    return new_bal


def _bm_owner_id():
    """Return first owner id for notifications (falls back to None)."""
    try:
        owners = OWNERS  # type: ignore[name-defined]
        return owners[0] if owners else None
    except Exception:
        return None


def _bm_db_channel():
    b = _bm_bot()
    if not b:
        return None
    return b.settings.get("database_channel")


def _bm_now_iso() -> str:
    return _bm_dt.now().isoformat()


def _bm_parse_iso(s):
    if not s:
        return None
    try:
        return _bm_dt.fromisoformat(s)
    except Exception:
        return None


def _bm_is_expired(entry: dict) -> bool:
    lt = entry.get("limited_time_iso")
    if not lt:
        return False
    dt = _bm_parse_iso(lt)
    if not dt:
        return False
    return _bm_dt.now() >= dt


def _bm_effective_price(entry: dict) -> int:
    """Apply discount % to base price."""
    try:
        price = int(entry.get("price", 0) or 0)
        disc = int(entry.get("discount", 0) or 0)
        if disc <= 0:
            return max(0, price)
        return max(0, price - (price * disc // 100))
    except Exception:
        return int(entry.get("price", 0) or 0)


# ─────────────────────────────────────────────────────────────────────────────
#  Premium Dark Theme UI helpers
# ─────────────────────────────────────────────────────────────────────────────
_BM_DIV = "━━━━━━━━━━━━━━━━━━━━━━━━"


def _bm_html_escape(text) -> str:
    if text is None:
        return ""
    s = str(text)
    return (s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;"))


def _bm_caption_shop_entry(card: dict, entry: dict) -> str:
    cid = str(card.get("id", ""))
    name = _bm_html_escape(card.get("name", "Unknown"))
    movie = _bm_html_escape(card.get("movie", ""))
    rarity = _bm_html_escape(_bm_rarity_display(card))
    role = _bm_html_escape(_bm_role_display(card))
    base = int(entry.get("price", 0) or 0)
    eff = _bm_effective_price(entry)
    disc = int(entry.get("discount", 0) or 0)
    stock = int(entry.get("stock", 0) or 0)
    lt = entry.get("limited_time_iso")

    sold_out = (stock <= 0)
    expired = _bm_is_expired(entry)

    lines = [
        "🕶 <b>BLACK MARKET</b>",
        _BM_DIV,
        f"🆔 <code>{cid}</code>",
        f"📛 <b>{name}</b>",
    ]
    if movie:
        lines.append(f"🎬 {movie}")
    lines += [f"⭐ {rarity}", f"🎭 {role}", _BM_DIV]
    if disc > 0 and not sold_out:
        lines.append(f"💎 <s>{_bm_fmt(base)}</s>  →  <b>{_bm_fmt(eff)}</b>  (−{disc}%)")
    else:
        lines.append(f"💎 <b>{_bm_fmt(eff)}</b>")

    if sold_out:
        lines.append("📦 ❌ <b>SOLD OUT</b>")
    else:
        lines.append(f"📦 Stock : <b>{stock}</b>")

    if lt:
        dt = _bm_parse_iso(lt)
        if dt:
            if expired:
                lines.append("⏳ ❌ <b>EXPIRED</b>")
            else:
                remaining = dt - _bm_dt.now()
                hrs = int(remaining.total_seconds() // 3600)
                if hrs >= 24:
                    days = hrs // 24
                    lines.append(f"⏳ Limited : <b>{days}d</b> left")
                elif hrs >= 1:
                    lines.append(f"⏳ Limited : <b>{hrs}h</b> left")
                else:
                    mins = max(1, int(remaining.total_seconds() // 60))
                    lines.append(f"⏳ Limited : <b>{mins}m</b> left")

    lines += [_BM_DIV, f"🛒 Buy : <code>/blackmarket {cid}</code>"]
    return "\n".join(lines)


# ═════════════════════════════════════════════════════════════════════════════
#  STEP 1 — Upload popup hook (monkey-patches role callbacks).
#  Strategy: WRAP existing upload_role_callback / owner_role_callback so that
#    • After original finalization runs, we look up the newly-created card and
#      offer the uploader a "Add to Black Market?" prompt.
#    • If user picks "Add" → move card metadata into pending list. The card
#      itself is already in bot.data['cards'] (original DB), which we don't
#      touch. The DB channel auto-send done by the original handler is reversed
#      by NOT sending again — we cannot un-send. So instead, we install a
#      "pre-send" suppression: a per-upload context flag tells a tiny patch to
#      route the send through a temporary buffer that only flushes on Skip or
#      Approve.
#
#  Implementation: we intercept the role-callback BEFORE the original runs,
#  flip a "defer_db_channel" flag on the bot, run the original, then read the
#  flag back and conditionally re-send. To avoid touching bot.settings, we use
#  a thread-local-ish global queue keyed by uploader_id.
# ═════════════════════════════════════════════════════════════════════════════

_BM_DEFERRED_DB: dict = {}   # card_id -> {"send_fn": coro_factory}  (unused — see below)

# Simpler approach: we don't try to suppress the in-handler DB send.
# Instead, we directly REPLACE the original handlers with new versions that
# replicate their behavior MINUS the DB channel send. The DB send happens
# afterward (on Skip immediately, or on Approve later).
#
# We capture the ORIGINAL globals references LAZILY at first patch call so
# that any other sidecar wrapping of these functions still works.

_BM_ORIG_UPLOAD_ROLE_CB = None
_BM_ORIG_OWNER_ROLE_CB = None


def _bm_patch_role_callbacks():
    """Replace upload_role_callback & owner_role_callback with BM-aware versions."""
    global _BM_ORIG_UPLOAD_ROLE_CB, _BM_ORIG_OWNER_ROLE_CB
    g = globals()

    orig_upload = g.get("upload_role_callback")
    orig_owner = g.get("owner_role_callback")
    if not callable(orig_upload) or not callable(orig_owner):
        _bm_logger.warning("[bm] role callbacks not found — popup skipped")
        return

    # Avoid double-patching
    if getattr(orig_upload, "_bm_patched", False):
        return

    _BM_ORIG_UPLOAD_ROLE_CB = orig_upload
    _BM_ORIG_OWNER_ROLE_CB = orig_owner

    async def patched_upload_role_callback(update, context):
        """Photo upload: defer DB channel send, then ask popup."""
        b = _bm_bot()
        # Temporarily blank out database_channel so the original won't send.
        saved_dbc = None
        deferred = False
        if b:
            try:
                saved_dbc = b.settings.get("database_channel")
                b.settings["database_channel"] = None
                deferred = True
            except Exception:
                pass
        try:
            result = await _BM_ORIG_UPLOAD_ROLE_CB(update, context)  # type: ignore[misc]
        finally:
            if deferred and b:
                try:
                    b.settings["database_channel"] = saved_dbc
                except Exception:
                    pass

        # Find the just-created card (highest ID owned/uploaded by this user)
        try:
            user = update.callback_query.from_user
            card_id = _bm_find_latest_uploaded_card(user.id, want_photo=True)
            if card_id is not None:
                await _bm_send_upload_popup(update.callback_query, context, card_id, is_video=False)
        except Exception as e:
            _bm_logger.warning(f"[bm] popup (photo) failed: {e}")
            # Fallback: if popup failed, do the original DB send so behavior is preserved.
            try:
                await _bm_send_card_to_db(context.bot, card_id, action="upload-fallback")
            except Exception:
                pass

        return result

    async def patched_owner_role_callback(update, context):
        """Video upload: same logic."""
        b = _bm_bot()
        saved_dbc = None
        deferred = False
        if b:
            try:
                saved_dbc = b.settings.get("database_channel")
                b.settings["database_channel"] = None
                deferred = True
            except Exception:
                pass
        try:
            result = await _BM_ORIG_OWNER_ROLE_CB(update, context)  # type: ignore[misc]
        finally:
            if deferred and b:
                try:
                    b.settings["database_channel"] = saved_dbc
                except Exception:
                    pass

        try:
            user = update.callback_query.from_user
            card_id = _bm_find_latest_uploaded_card(user.id, want_photo=False)
            if card_id is not None:
                await _bm_send_upload_popup(update.callback_query, context, card_id, is_video=True)
        except Exception as e:
            _bm_logger.warning(f"[bm] popup (video) failed: {e}")
            try:
                await _bm_send_card_to_db(context.bot, card_id, action="upload-fallback")
            except Exception:
                pass

        return result

    patched_upload_role_callback._bm_patched = True  # type: ignore[attr-defined]
    patched_owner_role_callback._bm_patched = True  # type: ignore[attr-defined]

    g["upload_role_callback"] = patched_upload_role_callback
    g["owner_role_callback"] = patched_owner_role_callback
    _bm_logger.info("[bm] ✅ upload role callbacks patched (BM popup enabled)")


def _bm_find_latest_uploaded_card(user_id: int, want_photo: bool):
    """Find the most-recently-uploaded card by this user."""
    b = _bm_bot()
    if not b:
        return None
    cards = b.data.get("cards", {}) or {}
    best = None
    best_id = None
    for cid, c in cards.items():
        if int(c.get("uploaded_by_id", 0) or 0) != int(user_id):
            continue
        has_photo = bool(c.get("image"))
        has_video = bool(c.get("video"))
        if want_photo and not has_photo:
            continue
        if (not want_photo) and not has_video:
            continue
        try:
            d = _bm_parse_iso(c.get("date"))
        except Exception:
            d = None
        if best is None or (d and best and d > best):
            best = d
            best_id = cid
    return best_id


async def _bm_send_upload_popup(query, context, card_id, is_video: bool):
    """Show the 'Add to Black Market?' popup to the uploader."""
    card = _bm_card(card_id)
    if not card:
        return
    name = _bm_html_escape(card.get("name", "Unknown"))
    rarity = _bm_html_escape(_bm_rarity_display(card))
    text = (
        "🕶 <b>BLACK MARKET</b>\n"
        f"{_BM_DIV}\n"
        f"🆔 <code>{card_id}</code>\n"
        f"📛 <b>{name}</b>\n"
        f"⭐ {rarity}\n"
        f"{_BM_DIV}\n"
        "❓ <b>ဒီ Card ကို Black Market Shop ထဲ ထည့်မလား?</b>\n"
        "<i>Add to Black Market — Owner Approval လိုပါတယ်။</i>"
    )
    kb = _BM_IKM([
        [
            _BM_IKB("✅ Add to Black Market", callback_data=f"bm_up:add:{card_id}"),
            _BM_IKB("❌ Skip", callback_data=f"bm_up:skip:{card_id}"),
        ]
    ])
    try:
        await query.message.reply_text(text, parse_mode="HTML", reply_markup=kb)
    except Exception as e:
        _bm_logger.warning(f"[bm] popup reply failed: {e}")


async def _bm_send_card_to_db(bot_api, card_id, action: str = "approved",
                              uploaded_by_id=None, uploaded_by_name=None,
                              approved_by_name: str = "Owner"):
    """Send approved card (media + info) to the database channel."""
    dbc = _bm_db_channel()
    if not dbc or not card_id:
        return
    card = _bm_card(card_id)
    if not card:
        return

    name = _bm_html_escape(card.get("name", "Unknown"))
    movie = _bm_html_escape(card.get("movie", ""))
    rarity = _bm_html_escape(_bm_rarity_display(card))
    role = _bm_html_escape(_bm_role_display(card))

    # Uploader mention
    up_id = uploaded_by_id or card.get("uploaded_by_id")
    up_name = uploaded_by_name or card.get("uploaded_by", "Unknown")
    up_name_esc = _bm_html_escape(up_name)
    if up_id:
        uploader_mention = f'<a href="tg://user?id={int(up_id)}">{up_name_esc}</a>'
    else:
        uploader_mention = up_name_esc

    if action == "approved":
        header = "🕶 <b>BLACK MARKET APPROVED</b>"
        extra = "💎 <b>Black Market Exclusive</b>"
    elif action == "skip":
        header = "📥 <b>CARD UPLOADED</b>"
        extra = ""
    else:
        header = "📥 <b>CARD UPLOADED</b>"
        extra = ""

    lines = [
        header,
        _BM_DIV,
        f"🆔 <code>{card_id}</code>",
        f"📛 <b>{name}</b>",
    ]
    if movie:
        lines.append(f"🎬 {movie}")
    lines += [
        f"⭐ {rarity}",
        f"🎭 {role}",
    ]
    if extra:
        lines.append(extra)
    lines += [
        "",
        f"👤 Uploaded By : {uploader_mention}",
    ]
    if action == "approved":
        lines.append(f"👑 Approved By : {_bm_html_escape(approved_by_name)}")
    lines.append(_BM_DIV)
    caption = "\n".join(lines)

    try:
        if card.get("image"):
            await bot_api.send_photo(chat_id=dbc, photo=card["image"],
                                     caption=caption, parse_mode="HTML")
            return
        if card.get("video"):
            vtype = str(card.get("video_type", "video") or "video").lower()
            if vtype == "document":
                await bot_api.send_document(chat_id=dbc, document=card["video"],
                                            caption=caption, parse_mode="HTML")
            else:
                await bot_api.send_video(chat_id=dbc, video=card["video"],
                                         caption=caption, parse_mode="HTML")
            return
        await bot_api.send_message(chat_id=dbc, text=caption, parse_mode="HTML")
    except Exception as e:
        _bm_logger.error(f"[bm] DB channel send failed: {e}")


# ─────────────────────────────────────────────────────────────────────────────
#  Upload popup callback handler (bm_up:add / bm_up:skip)
# ─────────────────────────────────────────────────────────────────────────────
async def _bm_upload_choice_cb(update, context):
    query = update.callback_query
    if not query:
        return
    data = query.data or ""
    parts = data.split(":")
    if len(parts) < 3 or parts[0] != "bm_up":
        return
    action = parts[1]
    card_id = parts[2]

    user = query.from_user
    card = _bm_card(card_id)
    if not card:
        try:
            await query.answer("❌ Card not found", show_alert=True)
        except Exception:
            pass
        return

    # Only the uploader can answer
    try:
        up_id = int(card.get("uploaded_by_id", 0) or 0)
    except Exception:
        up_id = 0
    if up_id and int(user.id) != up_id and not _bm_is_owner(user.id):
        try:
            await query.answer("⚠️ Uploader only", show_alert=True)
        except Exception:
            pass
        return

    store = _bm_store()

    if action == "skip":
        # Original behavior: send to DB channel now.
        try:
            await _bm_send_card_to_db(context.bot, card_id, action="skip",
                                      uploaded_by_id=up_id, uploaded_by_name=user.first_name)
        except Exception as e:
            _bm_logger.warning(f"[bm] skip DB send failed: {e}")
        try:
            await query.answer("✅ Skipped")
            await query.edit_message_text(
                "❌ <b>Skipped</b>\n"
                f"{_BM_DIV}\n"
                f"Card <code>{card_id}</code> — ပုံမှန် Database ထဲသာ သိမ်းပါမယ်။",
                parse_mode="HTML",
            )
        except Exception:
            pass
        return

    if action == "add":
        # Add to PENDING list. Do NOT send to DB channel.
        if card_id in store["approved"]:
            try:
                await query.answer("⚠️ Already in Black Market", show_alert=True)
            except Exception:
                pass
            return
        store["pending"][str(card_id)] = {
            "uploaded_by_id": up_id,
            "uploaded_by_name": user.first_name,
            "requested_at": _bm_now_iso(),
        }
        _bm_save()

        try:
            await query.answer("✅ Pending approval")
            await query.edit_message_text(
                "🕶 <b>BLACK MARKET — PENDING</b>\n"
                f"{_BM_DIV}\n"
                f"🆔 <code>{card_id}</code>\n"
                f"📛 <b>{_bm_html_escape(card.get('name','Unknown'))}</b>\n"
                f"⭐ {_bm_html_escape(_bm_rarity_display(card))}\n"
                f"{_BM_DIV}\n"
                "⏳ Owner Approval ကို စောင့်ဆိုင်းနေပါတယ်...",
                parse_mode="HTML",
            )
        except Exception:
            pass

        # Notify owner
        try:
            await _bm_notify_owner_pending(context.bot, card_id,
                                           up_id, user.first_name)
        except Exception as e:
            _bm_logger.warning(f"[bm] owner notify failed: {e}")
        return


async def _bm_notify_owner_pending(bot_api, card_id, uploaded_by_id, uploaded_by_name):
    """Send approval request to first owner in DM (best effort)."""
    card = _bm_card(card_id)
    if not card:
        return
    own = _bm_owner_id()
    if not own:
        return

    name = _bm_html_escape(card.get("name", "Unknown"))
    rarity = _bm_html_escape(_bm_rarity_display(card))
    up_name_esc = _bm_html_escape(uploaded_by_name or "Unknown")
    if uploaded_by_id:
        uploader_mention = f'<a href="tg://user?id={int(uploaded_by_id)}">{up_name_esc}</a>'
    else:
        uploader_mention = up_name_esc

    text = (
        "🕶 <b>Black Market Request</b>\n"
        f"{_BM_DIV}\n"
        f"🆔 <code>{card_id}</code>\n"
        f"📛 <b>{name}</b>\n"
        f"⭐ {rarity}\n"
        f"👤 Uploaded By : {uploader_mention}\n"
        f"{_BM_DIV}"
    )
    kb = _BM_IKM([
        [
            _BM_IKB("✅ Approve", callback_data=f"bm_ap:ok:{card_id}"),
            _BM_IKB("❌ Reject", callback_data=f"bm_ap:no:{card_id}"),
        ]
    ])
    try:
        if card.get("image"):
            await bot_api.send_photo(chat_id=own, photo=card["image"],
                                     caption=text, parse_mode="HTML",
                                     reply_markup=kb)
            return
        if card.get("video"):
            vtype = str(card.get("video_type", "video") or "video").lower()
            if vtype == "document":
                await bot_api.send_document(chat_id=own, document=card["video"],
                                            caption=text, parse_mode="HTML",
                                            reply_markup=kb)
            else:
                await bot_api.send_video(chat_id=own, video=card["video"],
                                         caption=text, parse_mode="HTML",
                                         reply_markup=kb)
            return
        await bot_api.send_message(chat_id=own, text=text, parse_mode="HTML",
                                   reply_markup=kb)
    except Exception as e:
        _bm_logger.warning(f"[bm] owner DM failed (uid={own}): {e}")


# ─────────────────────────────────────────────────────────────────────────────
#  Owner approval callback handler  (bm_ap:ok / bm_ap:no)
# ─────────────────────────────────────────────────────────────────────────────
async def _bm_approval_cb(update, context):
    query = update.callback_query
    if not query:
        return
    data = query.data or ""
    parts = data.split(":")
    if len(parts) < 3 or parts[0] != "bm_ap":
        return
    action = parts[1]
    card_id = str(parts[2])

    if not _bm_is_owner(query.from_user.id):
        try:
            await query.answer("⚠️ Owner only", show_alert=True)
        except Exception:
            pass
        return

    store = _bm_store()
    pending = store["pending"]
    entry = pending.get(card_id)
    if not entry:
        try:
            await query.answer("⚠️ Not in pending list", show_alert=True)
        except Exception:
            pass
        return

    card = _bm_card(card_id)
    if not card:
        pending.pop(card_id, None)
        _bm_save()
        try:
            await query.answer("❌ Card missing", show_alert=True)
        except Exception:
            pass
        return

    if action == "no":
        # Reject — remove from pending. Do NOT send to DB channel.
        pending.pop(card_id, None)
        _bm_save()
        try:
            await query.answer("❌ Rejected")
            await query.edit_message_caption(
                caption=(
                    "❌ <b>BLACK MARKET — REJECTED</b>\n"
                    f"{_BM_DIV}\n"
                    f"🆔 <code>{card_id}</code>\n"
                    "Card သည် ပုံမှန် Card အဖြစ်သာ ကျန်ပါမည်။"
                ),
                parse_mode="HTML",
            )
        except Exception:
            try:
                await query.edit_message_text(
                    "❌ <b>BLACK MARKET — REJECTED</b>\n"
                    f"{_BM_DIV}\n"
                    f"🆔 <code>{card_id}</code>",
                    parse_mode="HTML",
                )
            except Exception:
                pass
        return

    if action == "ok":
        # Approve — add to approved list (default price/stock), send to DB, then live.
        if card_id in store["approved"]:
            try:
                await query.answer("Already approved", show_alert=False)
            except Exception:
                pass
            pending.pop(card_id, None)
            _bm_save()
            return

        # Default base price scales with rarity value
        try:
            r = str(card.get("rarity", "1"))
            rar_val = int(RARITIES.get(r, {}).get("value", 100))  # type: ignore[name-defined]
        except Exception:
            rar_val = 100
        default_price = max(1000, rar_val * 1000)  # diamonds

        store["approved"][card_id] = {
            "price": default_price,
            "stock": 1,
            "limited_time_iso": None,
            "discount": 0,
            "added_at": _bm_now_iso(),
            "approved_by": query.from_user.first_name or "Owner",
            "uploaded_by_id": entry.get("uploaded_by_id"),
            "uploaded_by_name": entry.get("uploaded_by_name"),
        }
        pending.pop(card_id, None)
        _bm_save()

        # ✅ DB Channel Auto Send (only on approve)
        try:
            await _bm_send_card_to_db(
                context.bot, card_id, action="approved",
                uploaded_by_id=entry.get("uploaded_by_id"),
                uploaded_by_name=entry.get("uploaded_by_name"),
                approved_by_name=query.from_user.first_name or "Owner",
            )
        except Exception as e:
            _bm_logger.warning(f"[bm] approve DB send failed: {e}")

        try:
            await query.answer("✅ Approved")
            await query.edit_message_caption(
                caption=(
                    "🕶 <b>BLACK MARKET — APPROVED</b>\n"
                    f"{_BM_DIV}\n"
                    f"🆔 <code>{card_id}</code>\n"
                    f"💎 Default Price : <b>{_bm_fmt(default_price)}</b>\n"
                    f"📦 Default Stock : <b>1</b>\n"
                    f"{_BM_DIV}\n"
                    f"Use <code>/blackprice {card_id} &lt;price&gt;</code> / "
                    f"<code>/blackstock {card_id} &lt;n&gt;</code> to tune."
                ),
                parse_mode="HTML",
            )
        except Exception:
            try:
                await query.edit_message_text(
                    f"🕶 <b>BLACK MARKET — APPROVED</b>\n"
                    f"{_BM_DIV}\n"
                    f"🆔 <code>{card_id}</code>",
                    parse_mode="HTML",
                )
            except Exception:
                pass

        # Notify uploader (best effort DM)
        try:
            up_id = entry.get("uploaded_by_id")
            if up_id:
                await context.bot.send_message(
                    chat_id=int(up_id),
                    text=(
                        "🕶 <b>BLACK MARKET — APPROVED</b>\n"
                        f"{_BM_DIV}\n"
                        f"🆔 <code>{card_id}</code>\n"
                        f"📛 {_bm_html_escape(card.get('name','Unknown'))}\n"
                        "သင်တင်ထားသော Card ကို Black Market ထဲ ဝင်ပါပြီ ✅"
                    ),
                    parse_mode="HTML",
                )
        except Exception:
            pass
        return


# ═════════════════════════════════════════════════════════════════════════════
#  STEP 3 — Owner Shop Control commands
# ═════════════════════════════════════════════════════════════════════════════
def _bm_require_owner(update) -> bool:
    try:
        uid = update.effective_user.id
    except Exception:
        return False
    return _bm_is_owner(uid)


def _bm_parse_int(arg, default=None):
    try:
        return int(str(arg).strip().replace(",", ""))
    except Exception:
        return default


def _bm_parse_duration(arg) -> int | None:
    """Parse '24h', '7d', '30m' → seconds."""
    if not arg:
        return None
    s = str(arg).strip().lower()
    try:
        if s.endswith("d"):
            return int(float(s[:-1]) * 86400)
        if s.endswith("h"):
            return int(float(s[:-1]) * 3600)
        if s.endswith("m"):
            return int(float(s[:-1]) * 60)
        if s.endswith("s"):
            return int(float(s[:-1]))
        return int(float(s))  # raw seconds
    except Exception:
        return None


# /blackadd <card_id> [price] [stock] [duration like 24h] [discount%]
async def _bm_cmd_blackadd(update, context):
    if not _bm_require_owner(update):
        await update.message.reply_text("❌ Owner only")
        return
    args = context.args or []
    if not args:
        await update.message.reply_text(
            "📝 <b>Usage</b>\n"
            f"{_BM_DIV}\n"
            "<code>/blackadd &lt;card_id&gt; [price] [stock] [duration: 24h/7d] [discount%]</code>",
            parse_mode="HTML",
        )
        return
    card_id = str(args[0]).strip()
    card = _bm_card(card_id)
    if not card:
        await update.message.reply_text(f"❌ Card <code>{card_id}</code> not found.", parse_mode="HTML")
        return
    price = _bm_parse_int(args[1] if len(args) > 1 else None, default=None)
    stock = _bm_parse_int(args[2] if len(args) > 2 else None, default=1)
    dur_s = _bm_parse_duration(args[3]) if len(args) > 3 else None
    disc = _bm_parse_int(args[4] if len(args) > 4 else None, default=0)
    if price is None:
        # Default by rarity
        try:
            r = str(card.get("rarity", "1"))
            rar_val = int(RARITIES.get(r, {}).get("value", 100))  # type: ignore[name-defined]
        except Exception:
            rar_val = 100
        price = max(1000, rar_val * 1000)

    store = _bm_store()
    lt_iso = None
    if dur_s and dur_s > 0:
        lt_iso = (_bm_dt.now() + _bm_td(seconds=dur_s)).isoformat()

    store["approved"][card_id] = {
        "price": int(price),
        "stock": int(stock or 0),
        "limited_time_iso": lt_iso,
        "discount": int(disc or 0),
        "added_at": _bm_now_iso(),
        "approved_by": update.effective_user.first_name or "Owner",
        "uploaded_by_id": card.get("uploaded_by_id"),
        "uploaded_by_name": card.get("uploaded_by"),
    }
    # Also clear from pending if it was there
    store["pending"].pop(card_id, None)
    _bm_save()

    # If DB channel set, send approved card now (per spec)
    try:
        await _bm_send_card_to_db(
            context.bot, card_id, action="approved",
            uploaded_by_id=card.get("uploaded_by_id"),
            uploaded_by_name=card.get("uploaded_by"),
            approved_by_name=update.effective_user.first_name or "Owner",
        )
    except Exception:
        pass

    await update.message.reply_text(
        _bm_caption_shop_entry(card, store["approved"][card_id]),
        parse_mode="HTML",
    )


# /blackremove <card_id>
async def _bm_cmd_blackremove(update, context):
    if not _bm_require_owner(update):
        await update.message.reply_text("❌ Owner only")
        return
    args = context.args or []
    if not args:
        await update.message.reply_text("📝 Usage: <code>/blackremove &lt;card_id&gt;</code>", parse_mode="HTML")
        return
    cid = str(args[0]).strip()
    store = _bm_store()
    if cid not in store["approved"]:
        await update.message.reply_text("❌ Not in Black Market.", parse_mode="HTML")
        return
    store["approved"].pop(cid, None)
    _bm_save()
    await update.message.reply_text(f"🗑 Removed <code>{cid}</code> from Black Market.", parse_mode="HTML")


