# /blacklist  — list all approved
async def _bm_cmd_blacklist(update, context):
    store = _bm_store()
    approved = store["approved"]
    if not approved:
        await update.message.reply_text(
            "🕶 <b>BLACK MARKET</b>\n"
            f"{_BM_DIV}\n"
            "📦 Empty — no approved cards yet.",
            parse_mode="HTML",
        )
        return
    # Paginated text list (10 per message to stay under telegram size limit)
    items = list(approved.items())
    page_size = 10
    pages = [items[i:i + page_size] for i in range(0, len(items), page_size)]
    for pi, page in enumerate(pages, 1):
        lines = [f"🕶 <b>BLACK MARKET</b>  (page {pi}/{len(pages)})", _BM_DIV]
        for cid, entry in page:
            card = _bm_card(cid)
            if not card:
                continue
            name = _bm_html_escape(card.get("name", "Unknown"))
            rarity = _bm_html_escape(_bm_rarity_display(card))
            eff = _bm_effective_price(entry)
            stock = int(entry.get("stock", 0) or 0)
            if stock <= 0:
                stock_s = "❌ SOLD OUT"
            else:
                stock_s = f"📦 {stock}"
            disc = int(entry.get("discount", 0) or 0)
            price_s = f"💎 {_bm_fmt(eff)}"
            if disc > 0:
                price_s += f"  (-{disc}%)"
            lines.append(f"🆔 <code>{cid}</code> · {rarity} · {name}\n   {price_s}  ·  {stock_s}")
        lines.append(_BM_DIV)
        lines.append("🛒 Buy: <code>/blackmarket &lt;id&gt;</code>")
        try:
            await update.message.reply_text("\n".join(lines), parse_mode="HTML")
        except Exception as e:
            _bm_logger.warning(f"[bm] blacklist send failed: {e}")


