# ═════════════════════════════════════════════════════════════════════════════
#  STEP 6 — Purchase via /blackmarket <card_id>   (NEW black_market only)
#
#  Registered at group=-5 (before the legacy immortal_shop handler at -3).
#  If card is in NEW black_market → handle here and raise ApplicationHandlerStop.
#  Else: let it fall through to legacy handler.
# ═════════════════════════════════════════════════════════════════════════════
async def _bm_cmd_blackmarket_buy(update, context):
    msg = getattr(update, "message", None)
    user = getattr(update, "effective_user", None)
    if msg is None or user is None:
        return

    args = context.args or []
    if not args:
        # No args → let legacy handler show its usage (don't stop).
        return

    cid = str(args[0]).strip()
    store = _bm_store()
    if cid not in store["approved"]:
        # Not ours — let legacy handler attempt it.
        return

    entry = store["approved"][cid]
    card = _bm_card(cid)
    if not card:
        await msg.reply_text("❌ Card not found in database.")
        raise _BM_Stop

    # Banned check
    b = _bm_bot()
    if b and hasattr(b, "is_gbanned") and b.is_gbanned(user.id):
        await msg.reply_text("❌ You are globally banned.")
        raise _BM_Stop

    # Expired?
    if _bm_is_expired(entry):
        await msg.reply_text(
            "⏳ <b>EXPIRED</b>\n"
            f"{_BM_DIV}\n"
            f"🆔 <code>{cid}</code>  Limited time ended.",
            parse_mode="HTML",
        )
        raise _BM_Stop

    # Stock?
    stock = int(entry.get("stock", 0) or 0)
    if stock <= 0:
        await msg.reply_text(
            "❌ <b>SOLD OUT</b>\n"
            f"{_BM_DIV}\n"
            f"🆔 <code>{cid}</code>",
            parse_mode="HTML",
        )
        raise _BM_Stop

    price = _bm_effective_price(entry)
    bal = _bm_get_diamonds(user.id)
    if bal < price:
        await msg.reply_text(
            "❌ <b>Not enough Diamonds</b>\n"
            f"{_BM_DIV}\n"
            f"💎 You have : <code>{_bm_fmt(bal)}</code>\n"
            f"💵 Price    : <code>{_bm_fmt(price)}</code>\n"
            f"📉 Short by : <code>{_bm_fmt(price - bal)}</code>",
            parse_mode="HTML",
        )
        raise _BM_Stop

    # Atomic-ish: deduct diamonds → transfer ownership → decrement stock
    new_bal = _bm_add_diamonds(user.id, -price)

    # Card ownership transfer (mirror legacy: append card_id to buyer inventory).
    try:
        if b:
            b.data.setdefault("users", {}).setdefault(str(user.id), [])
            b.data["users"][str(user.id)].append(str(cid))
            # Mark owner on the card (best effort — preserves existing schema fields)
            card["owner"] = str(user.id)
            card["owner_name"] = user.first_name or "Unknown"
            b.save_data()
    except Exception as e:
        _bm_logger.warning(f"[bm] inventory update failed: {e}")

    # Decrement stock; if zero → Sold Out (stays in shop, marked SOLD OUT).
    entry["stock"] = max(0, stock - 1)
    entry.setdefault("sold_total", 0)
    entry["sold_total"] = int(entry.get("sold_total", 0) or 0) + 1
    _bm_save()

    name = _bm_html_escape(card.get("name", "Unknown"))
    movie = _bm_html_escape(card.get("movie", ""))
    rarity = _bm_html_escape(_bm_rarity_display(card))
    role = _bm_html_escape(_bm_role_display(card))

    lines = [
        "🎉 <b>BLACK MARKET — PURCHASED</b>",
        _BM_DIV,
        f"🆔 <code>{cid}</code>",
        f"📛 <b>{name}</b>",
    ]
    if movie:
        lines.append(f"🎬 {movie}")
    lines += [
        f"⭐ {rarity}",
        f"🎭 {role}",
        _BM_DIV,
        f"💎 -{_bm_fmt(price)}",
        f"💰 Balance : <code>{_bm_fmt(new_bal)}</code>",
        f"📦 Stock left : <b>{entry['stock']}</b>"
        + ("  ❌ SOLD OUT" if entry["stock"] <= 0 else ""),
        _BM_DIV,
    ]
    caption = "\n".join(lines)

    try:
        if card.get("image"):
            await msg.reply_photo(photo=card["image"], caption=caption, parse_mode="HTML")
        elif card.get("video"):
            vtype = str(card.get("video_type", "video") or "video").lower()
            if vtype == "document":
                await msg.reply_document(document=card["video"], caption=caption, parse_mode="HTML")
            else:
                await msg.reply_video(video=card["video"], caption=caption, parse_mode="HTML")
        else:
            await msg.reply_text(caption, parse_mode="HTML")
    except Exception as e:
        _bm_logger.warning(f"[bm] purchase reply failed: {e}")
        try:
            await msg.reply_text(caption, parse_mode="HTML")
        except Exception:
            pass

    raise _BM_Stop


# ═════════════════════════════════════════════════════════════════════════════
#  STEP 9 — Diamond Rich List
# ═════════════════════════════════════════════════════════════════════════════
_BM_TOP_MEDALS = ["🥇 #1", "🥈 #2", "🥉 #3", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]


def _bm_collect_top_diamonds(limit: int = 10) -> list[tuple[str, str, int]]:
    """Return [(uid_str, display_name, diamonds), ...] sorted desc."""
    b = _bm_bot()
    if not b:
        return []
    profiles = b.data.get("user_profiles", {}) or {}
    suspended = b.settings.get("suspended_users", {}) or {}
    gbanned = b.settings.get("gbanned_users", {}) or {}

    rows = []
    for uid, prof in profiles.items():
        try:
            dia = int((prof or {}).get("kakera", 0) or 0)
        except Exception:
            dia = 0
        if dia <= 0:
            continue
        if str(uid) in suspended or str(uid) in gbanned:
            continue
        # Try to resolve a display name
        try:
            fn = globals().get("get_name")
            name = fn(uid) if callable(fn) else None
        except Exception:
            name = None
        if not name:
            name = (prof or {}).get("name") or f"User {uid}"
        rows.append((str(uid), str(name), dia))

    rows.sort(key=lambda x: -x[2])
    return rows[:limit]


def _bm_format_topdiamond_caption(rows) -> str:
    if not rows:
        return (
            "💎 <b>DIAMOND RICH LIST</b> 💎\n"
            f"{_BM_DIV}\n"
            "📦 No data yet."
        )
    lines = [
        "💎 <b>DIAMOND RICH LIST</b> 💎",
        "👑 <b>Top 10 Richest Players</b>",
        _BM_DIV,
    ]
    for idx, (uid, name, dia) in enumerate(rows):
        medal = _BM_TOP_MEDALS[idx] if idx < len(_BM_TOP_MEDALS) else f"#{idx+1}"
        nm = _bm_html_escape(name)
        try:
            mention = f'<a href="tg://user?id={int(uid)}">{nm}</a>'
        except Exception:
            mention = nm
        lines.append(f"{medal} {mention} — 💎 {_bm_fmt(dia)}")
    lines.append(_BM_DIV)
    return "\n".join(lines)


async def _bm_cmd_topdiamond(update, context):
    rows = _bm_collect_top_diamonds(10)
    caption = _bm_format_topdiamond_caption(rows)
    media = _bm_store().get("topdiamond_media")
    msg = update.message
    try:
        if media and isinstance(media, dict):
            mtype = (media.get("type") or "").lower()
            fid = media.get("file_id")
            if fid and mtype == "photo":
                await msg.reply_photo(photo=fid, caption=caption, parse_mode="HTML")
                return
            if fid and mtype == "video":
                await msg.reply_video(video=fid, caption=caption, parse_mode="HTML")
                return
        await msg.reply_text(caption, parse_mode="HTML")
    except Exception as e:
        _bm_logger.warning(f"[bm] topdiamond send failed: {e}")
        try:
            await msg.reply_text(caption, parse_mode="HTML")
        except Exception:
            pass


