# ═════════════════════════════════════════════════════════════════════════════
#  Handler installation (mirrors the immortal_shop pattern)
# ═════════════════════════════════════════════════════════════════════════════
_BM_REGISTERED_APPS: set[int] = set()


def _bm_register_handlers(application):
    if application is None:
        return
    try:
        key = id(application)
    except Exception:
        key = None
    if key is not None and key in _BM_REGISTERED_APPS:
        return
    if key is not None:
        _BM_REGISTERED_APPS.add(key)

    try:
        # New /blackmarket buyer at group=-5 → runs BEFORE legacy at group=-3.
        # On match it raises ApplicationHandlerStop; on no-match it returns
        # without stopping, so legacy handler still runs.
        application.add_handler(_BM_CmdH("blackmarket", _bm_cmd_blackmarket_buy), group=-5)

        # Owner shop control
        application.add_handler(_BM_CmdH("blackadd",       _bm_cmd_blackadd),       group=-3)
        application.add_handler(_BM_CmdH("blackremove",    _bm_cmd_blackremove),    group=-3)
        application.add_handler(_BM_CmdH("blackprice",     _bm_cmd_blackprice),     group=-3)
        application.add_handler(_BM_CmdH("blackstock",     _bm_cmd_blackstock),     group=-3)
        application.add_handler(_BM_CmdH("blacklimit",     _bm_cmd_blacklimit),     group=-3)
        application.add_handler(_BM_CmdH("blackdiscount",  _bm_cmd_blackdiscount),  group=-3)
        application.add_handler(_BM_CmdH("blacklist",      _bm_cmd_blacklist),      group=-3)
        application.add_handler(_BM_CmdH("blackpending",   _bm_cmd_blackpending),   group=-3)

        # Diamond rich list
        application.add_handler(_BM_CmdH("topdiamond",            _bm_cmd_topdiamond),            group=-3)
        application.add_handler(_BM_CmdH("settopdiamondphoto",    _bm_cmd_settopdiamondphoto),    group=-3)
        application.add_handler(_BM_CmdH("settopdiamondvideo",    _bm_cmd_settopdiamondvideo),    group=-3)
        application.add_handler(_BM_CmdH("cleartopdiamondmedia",  _bm_cmd_cleartopdiamondmedia),  group=-3)

        # Callbacks
        application.add_handler(_BM_CbH(_bm_upload_choice_cb,  pattern=r"^bm_up:(add|skip):"), group=-3)
        application.add_handler(_BM_CbH(_bm_approval_cb,       pattern=r"^bm_ap:(ok|no):"),    group=-3)

        _bm_logger.info("[bm] ✅ Black Market v2 handlers + /topdiamond registered")
    except Exception as e:
        _bm_logger.error(f"[bm] register failed: {e}")


def _bm_install_post_init_hook():
    """Mirror the immortal_shop strategy: wrap Application.__init__ so that
    handlers are auto-added when main() builds the Application."""
    try:
        from telegram.ext import Application as _BM_App
    except Exception:
        return
    orig_init = getattr(_BM_App, "__init__", None)
    if not callable(orig_init):
        return
    if getattr(orig_init, "_bm_wrapped", False):
        return

    def patched_init(self, *args, **kwargs):
        orig_init(self, *args, **kwargs)
        try:
            _bm_register_handlers(self)
        except Exception as e:
            _bm_logger.error(f"[bm] register-on-init failed: {e}")

    patched_init._bm_wrapped = True  # type: ignore[attr-defined]
    try:
        _BM_App.__init__ = patched_init  # type: ignore[assignment]
    except Exception as e:
        _bm_logger.error(f"[bm] App.__init__ patch failed: {e}")


# ─────────────────────────────────────────────────────────────────────────────
#  Bootstrap (executed at module load — i.e. when this sidecar is appended
#  to the main file and Python evaluates the module).
# ─────────────────────────────────────────────────────────────────────────────
try:
    _bm_patch_role_callbacks()
except Exception as _bm_e:
    _bm_logger.error(f"[bm] role-cb patch failed: {_bm_e}")

try:
    _bm_install_post_init_hook()
except Exception as _bm_e:
    _bm_logger.error(f"[bm] post-init install failed: {_bm_e}")

# ═══════════════════════════════════════════════════════════════════════════════
#  END  BLACK MARKET v2 + DIAMOND RICH LIST
# ═══════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════
#  📌 PATCH PACK — UNICODE FONT NORMALIZATION (/ziceko) + INLINE CMODE FILTER
# ═══════════════════════════════════════════════════════════════════════════════
#
#  Goals (non-destructive, no DB structure change):
#    1. /ziceko <name> → accept Telegram Unicode mathematical / stylized fonts
#       (𝗕𝗼𝗹𝗱, 𝐁𝐨𝐥𝐝, 𝙄𝙩𝙖𝙡𝙞𝙘, 𝑰𝒕𝒂𝒍𝒊𝒄, 𝓢𝓬𝓻𝓲𝓹𝓽, 𝔉𝔯𝔞𝔨𝔱𝔲𝔯, monospace, etc.)
#       by normalizing input to plain ASCII before whole-word matching.
#    2. /harem inline-view-cards button → respect the user's CMODE rarity choice
#       so only cards of the chosen rarity appear inline (when user views own).
#
#  Strategy:
#    • Wrap existing ziceko_cmd via monkey-patch + re-register handler at startup.
#    • Wrap inline_query: when query is the requester's own user-id (the harem
#      inline button payload), filter results by cmode rarity selection.
#    • Both wrappers fall back to the original behaviour on any error.
# ═══════════════════════════════════════════════════════════════════════════════

import logging as _ufp_logging
import re as _ufp_re
import unicodedata as _ufp_unicodedata

_ufp_log = _ufp_logging.getLogger("ufp_patch")


# ───────────────────────────────────────────────────────────────────────
#  Unicode font → ASCII normalizer
# ───────────────────────────────────────────────────────────────────────
def _ufp_unicode_to_ascii(text: str) -> str:
    """Convert Telegram-style Unicode font characters to plain ASCII.

    Handles Mathematical Alphanumeric Symbols (U+1D400..U+1D7FF) such as
    Bold, Italic, Bold-Italic, Script, Bold-Script, Fraktur, Bold-Fraktur,
    Double-struck, Sans-serif (regular/bold/italic/bold-italic), Monospace,
    plus the few letters Unicode placed outside that block
    (e.g. ℎ U+210E, ℬ U+212C, ℰ U+2130, ℱ U+2131, ℋ U+210B, ℐ U+2110,
    ℒ U+2112, ℳ U+2133, ℛ U+211B, ℯ U+212F, ℊ U+210A, ℴ U+2134,
    ℂ U+2102, ℍ U+210D, ℕ U+2115, ℙ U+2119, ℚ U+211A, ℝ U+211D, ℤ U+2124).
    Also handles fullwidth ASCII (U+FF01..U+FF5E) and circled / squared letters.
    Falls back to NFKD compatibility decomposition for everything else.
    """
    if not text:
        return ""

    out_chars = []
    for ch in text:
        cp = ord(ch)

        # Plain ASCII — keep as-is
        if cp < 128:
            out_chars.append(ch)
            continue

        mapped = _UFP_DIRECT_MAP.get(ch)
        if mapped is not None:
            out_chars.append(mapped)
            continue

        # Mathematical Alphanumeric Symbols block U+1D400..U+1D7FF
        if 0x1D400 <= cp <= 0x1D7FF:
            mapped = _ufp_math_alnum(cp)
            if mapped is not None:
                out_chars.append(mapped)
                continue

        # Fullwidth ASCII U+FF01..U+FF5E → ASCII
        if 0xFF01 <= cp <= 0xFF5E:
            out_chars.append(chr(cp - 0xFEE0))
            continue

        # Generic compatibility decomposition fallback
        try:
            decomposed = _ufp_unicodedata.normalize("NFKD", ch)
        except Exception:
            decomposed = ch
        added = False
        for d in decomposed:
            dcp = ord(d)
            if dcp < 128:
                out_chars.append(d)
                added = True
            elif 0x1D400 <= dcp <= 0x1D7FF:
                m2 = _ufp_math_alnum(dcp)
                if m2 is not None:
                    out_chars.append(m2)
                    added = True
        if not added:
            # Last resort: drop non-letter combining marks, keep letters via NFKC name lookup
            try:
                name = _ufp_unicodedata.name(ch, "")
            except Exception:
                name = ""
            # Examples: "MATHEMATICAL BOLD CAPITAL A", "LATIN SMALL LETTER A"
            m = _ufp_re.search(r"(?:CAPITAL|SMALL)\s+LETTER\s+([A-Z])", name)
            if m:
                letter = m.group(1)
                if "SMALL" in name:
                    out_chars.append(letter.lower())
                else:
                    out_chars.append(letter)
            else:
                # Keep original char if nothing else worked (spaces, punctuation, CJK, etc.)
                out_chars.append(ch)

    return "".join(out_chars)


def _ufp_math_alnum(cp: int):
    """Map a code point inside U+1D400..U+1D7FF to its ASCII counterpart."""
    # Letter ranges: each variant spans 26 uppercase + 26 lowercase = 52 chars,
    # but a handful of code points are "reserved" / holes that Unicode placed
    # elsewhere (e.g. italic h at U+210E). The arithmetic below relies on
    # the offset-from-base trick — works for every "complete" variant block.
    # Variants in order start at: 1D400, 1D434, 1D468, 1D49C, 1D4D0, 1D504,
    # 1D538, 1D56C, 1D5A0, 1D5D4, 1D608, 1D63C, 1D670  (each 52 long).
    # Digits start at 1D7CE and span 5 variants × 10 = 50 chars up to 1D7FF.

    # ---- Digits ----
    if 0x1D7CE <= cp <= 0x1D7FF:
        return str((cp - 0x1D7CE) % 10)

    # ---- Letters ----
    if 0x1D400 <= cp <= 0x1D6A3:  # main 13 letter variants (52 each)
        rel = cp - 0x1D400
        idx_in_variant = rel % 52
        if idx_in_variant < 26:
            return chr(ord("A") + idx_in_variant)
        else:
            return chr(ord("a") + (idx_in_variant - 26))
    # Greek / additional letters above 1D6A4 are unlikely for character names,
    # so we let the NFKD fallback handle them.
    return None


# Direct overrides for the "holes" Unicode left in the math block.
# Each entry maps a single stylized glyph → ASCII letter.
_UFP_DIRECT_MAP = {
    # Italic holes
    "\u210E": "h",  # ℎ Planck constant (italic small h)
    # Script holes
    "\u212C": "B", "\u2130": "E", "\u2131": "F", "\u210B": "H",
    "\u2110": "I", "\u2112": "L", "\u2133": "M", "\u211B": "R",
    "\u212F": "e", "\u210A": "g", "\u2134": "o",
    # Fraktur holes
    "\u212D": "C", "\u210C": "H", "\u2111": "I", "\u211C": "R", "\u2128": "Z",
    # Double-struck holes
    "\u2102": "C", "\u210D": "H", "\u2115": "N", "\u2119": "P",
    "\u211A": "Q", "\u211D": "R", "\u2124": "Z",
}


def _ufp_normalize_name(text: str) -> str:
    """Full pipeline: Unicode-font → ASCII → lowercase → collapse spaces."""
    if text is None:
        return ""
    s = _ufp_unicode_to_ascii(str(text))
    # Strip combining marks left after NFKD
    s = "".join(c for c in s if not _ufp_unicodedata.combining(c))
    # Lowercase + collapse internal whitespace
    s = _ufp_re.sub(r"\s+", " ", s).strip().lower()
    return s


# ───────────────────────────────────────────────────────────────────────
#  /ziceko — wrapped version with Unicode-font support
# ───────────────────────────────────────────────────────────────────────
async def _ufp_ziceko_cmd(update, context):
    """Drop-claim with Unicode-font tolerant name matching.

    Mirrors the original ziceko_cmd flow but normalizes both the user's
    typed name and the card's stored name via _ufp_normalize_name() so
    bold / italic / script / fraktur / monospace / etc. variants all
    resolve to the same plain-ASCII form before whole-word comparison.
    """
    try:
        # Lazy import of the globals the original function uses
        from telegram.ext import ContextTypes  # noqa: F401

        if update.effective_chat.type not in ['group', 'supergroup']:
            await update.message.reply_text("❌ Group မှာပဲသုံးပါ")
            return

        if not context.args:
            await update.message.reply_text("📝 /ziceko <name>")
            return

        group_id = str(update.effective_chat.id)

        if group_id not in bot.data['dropped_cards']:
            # DROP SNIPED: this group's drop may have just been claimed
            if await maybe_send_drop_sniped(update, group_id, ' '.join(context.args), normalizer=_ufp_normalize_name):
                return
            await update.message.reply_text("❌ Drop ကသူများကောက်သွားပြီဆက်စောင့်😾")
            return

        dropped = bot.data['dropped_cards'][group_id]
        card_id = dropped['card_id']
        card = bot.data['cards'].get(card_id)

        if not card:
            await update.message.reply_text("❌ Card data error")
            return

        # ── NEW: Unicode-font normalize both sides before matching ──
        raw_input = ' '.join(context.args)
        claimed_name = _ufp_normalize_name(raw_input)
        card_name = _ufp_normalize_name(card.get('name', ''))

        # Whole-word matching (preserved from original)
        card_words = _ufp_re.split(r'\s+', card_name.strip()) if card_name else []
        claimed_words = _ufp_re.split(r'\s+', claimed_name.strip()) if claimed_name else []

        word_match = False
        if claimed_words and card_words and len(claimed_words) <= len(card_words):
            for i in range(len(card_words) - len(claimed_words) + 1):
                if card_words[i:i + len(claimed_words)] == claimed_words:
                    word_match = True
                    break

        if not word_match:
            await update.message.reply_text("❌ နာမည်မှားပါတယ် (နာမည်တစ်ခုလုံးရေးပါ)")
            return

        user = update.effective_user
        user_id_str = str(user.id)

        if user_id_str not in bot.data['users']:
            bot.data['users'][user_id_str] = []

        # Race-condition guard: re-verify the drop is still active right before claiming
        if group_id not in bot.data['dropped_cards']:
            if await maybe_send_drop_sniped(update, group_id, ' '.join(context.args), normalizer=_ufp_normalize_name):
                return
            await update.message.reply_text("❌ Drop ကသူများကောက်သွားပြီဆက်စောင့်😾")
            return

        bot.data['users'][user_id_str].append(card_id)
        bot.data['cards'][card_id]['owner'] = user.id
        bot.data['cards'][card_id]['owner_name'] = user.first_name

        # Record last-claimed info BEFORE removing the active drop (DROP SNIPED)
        record_last_claim(group_id, card, user)
        del bot.data['dropped_cards'][group_id]

        # EVENT SYSTEM: Reward event coins (preserved)
        try:
            if is_event_active() and card_id in events["event_cards"]:
                profile = bot.data['user_profiles'][user_id_str]
                event = events["active_event"]
                currency = event.get("currency_emoji", "🎃")
                profile["event_coins"] = profile.get("event_coins", 0) + 10
                await update.message.reply_text(f"🎉 +10 {currency} Event Coins!")
        except Exception as _ev_e:
            _ufp_log.warning(f"[ufp] event reward skipped: {_ev_e}")

        bot.save_data()

        rarity = card.get('rarity', '1')
        rarity_info = RARITIES.get(rarity, RARITIES['1'])
        role_info = get_role_info(card)

        mention = f"[{user.first_name}](tg://user?id={user.id})"
        await update.message.reply_text(
            f"╔══════════════════════════╗\n"
            f"🏆⚡  𝗖𝗔𝗥𝗗  𝗖𝗟𝗔𝗜𝗠𝗘𝗗  ⚡🏆\n"
            f"┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
            f"👤 𝗣𝗹𝗮𝘆𝗲𝗿  : {mention}\n"
            f"🎴 𝗖𝗮𝗿𝗱    : {card['name']}\n"
            f"🎬 𝗠𝗼𝘃𝗶𝗲   : {card['movie']}\n"
            f"🆔 𝗜𝗗      : {card['id']}\n"
            f"⭐ 𝗥𝗮𝗿𝗶𝘁𝘆  : {rarity_info['display']}\n"
            f"🎭 𝗥𝗼𝗹𝗲    : {role_info['display']}\n"
            f"╚══════════════════════════╝",
            parse_mode="Markdown"
        )
    except Exception as e:
        _ufp_log.error(f"[ufp] ziceko_cmd error: {e}", exc_info=True)
        try:
            await update.message.reply_text("❌ Error လုပ်ဆောင်နေစဉ်ပြသနာဖြစ်နေပါသည်")
        except Exception:
            pass


# Replace the module-level function so any existing handler reference
# that resolves the name dynamically picks up the new behaviour, and
# also re-register a fresh handler at higher priority to be safe.
try:
    globals()["ziceko_cmd"] = _ufp_ziceko_cmd
    _ufp_log.info("[ufp] ziceko_cmd globally rebound ✅")
except Exception as _ufp_e:
    _ufp_log.error(f"[ufp] rebind ziceko_cmd failed: {_ufp_e}")


# ───────────────────────────────────────────────────────────────────────
#  Inline-query wrapper: CMODE rarity filter for own-harem inline view
# ───────────────────────────────────────────────────────────────────────
#  Behaviour:
#    • If the requester opens inline query with their OWN user-id as the
#      query (the "🔍 Inline View Cards" button in /harem does exactly this
#      via switch_inline_query_current_chat=str(user.id)), and the user has
#      a CMODE rarity selected, only cards of that rarity are returned.
#    • For other users' harems / generic name searches → behaviour unchanged.
#    • If the user's CMODE filter yields zero results, fall back to the
#      unfiltered list so the panel is not empty.
# ───────────────────────────────────────────────────────────────────────
def _ufp_get_cmode_rarity(uid):
    """Read the cmode store directly (mirrors _cmpx_get_user_mode)."""
    try:
        store = bot.data.get("cmode_users", {}) or {}
        val = store.get(str(uid))
        if val in (None, "", "all", "ALL", "default", "Default"):
            return None
        return str(val)
    except Exception:
        return None


try:
    _ufp_orig_inline_query = inline_query  # type: ignore[name-defined]
except NameError:
    _ufp_orig_inline_query = None


async def _ufp_inline_query(update, context):
    """Inline Harem with CMODE filtering + Telegram inline pagination.

    The /harem "Inline View Cards" button sends the user's own Telegram ID
    as the inline query.  Telegram only accepts up to 50 results per answer,
    so use InlineQuery.offset/next_offset to let the client load the next
    batch automatically while the user scrolls.
    """
    try:
        iq = update.inline_query
        if iq is None or _ufp_orig_inline_query is None:
            if _ufp_orig_inline_query is not None:
                return await _ufp_orig_inline_query(update, context)
            return

        query = (iq.query or "").strip()
        requester = update.effective_user
        if not requester or not query:
            return await _ufp_orig_inline_query(update, context)

        # Only intercept the own-harem inline query generated by /harem.
        if not (query.isdigit() and len(query) >= 4 and query == str(requester.id)):
            return await _ufp_orig_inline_query(update, context)

        # Telegram sends the current pagination cursor back as iq.offset.
        # Keep it numeric and clamp invalid values safely.
        try:
            offset = int((getattr(iq, "offset", "") or "0").strip() or "0")
        except Exception:
            offset = 0
        offset = max(0, offset)

        # IMPORTANT: Always handle the self-harem query here, even when
        # CMODE is not selected.  The original inline handler is blocked
        # for self-harem queries, so this wrapper must provide the ALL-cards
        # pagination path as well.
        rarity_key = _ufp_get_cmode_rarity(requester.id)
        user_cards = list(bot.data.get('users', {}).get(str(requester.id)) or [])

        if not user_cards:
            await iq.answer([], cache_time=1, is_personal=True, next_offset="")
            return

        # Apply CMODE only when a rarity is actually selected.
        # No CMODE = ALL owned cards.
        if rarity_key is not None:
            cards_db = bot.data.get('cards', {}) or {}
            filtered_cards = []
            for cid in user_cards:
                card = cards_db.get(str(cid))
                if not card:
                    continue
                if str(card.get('rarity', '1')) == str(rarity_key):
                    filtered_cards.append(cid)
            user_cards = filtered_cards

        total = len(user_cards)
        if offset >= total:
            await iq.answer([], cache_time=1, is_personal=True, next_offset="")
            return

        target_name = requester.first_name or "User"
        try:
            mention = _mention_md(requester.id, target_name)  # type: ignore[name-defined]
        except Exception:
            mention = target_name

        try:
            rarity_info = RARITIES.get(str(rarity_key), RARITIES['1']) if rarity_key is not None else {}
        except Exception:
            rarity_info = {"display": str(rarity_key or ""), "name": str(rarity_key or ""), "emoji": ""}

        def _cap(card):
            try:
                r = str(card.get('rarity', '1'))
                ri = RARITIES.get(r, RARITIES['1'])
                role_info = get_role_info(card)
                return (
                    f"OwO! Check out this character!\n"
                    f"👤 Player : {mention}\n"
                    f"🎬 Anime  : {_md_escape(card.get('movie',''))}\n"
                    f"🆔 ID     : {card.get('id','')}\n"
                    f"🌟 Name   : {_md_escape(card.get('name',''))}\n"
                    f"⚜ Rarity : {ri['display']}\n"
                    f"🎭 Role   : {role_info['display']}\n"
                    f"╰━━━━━━━━━━━━━━━━━━━━╯"
                )
            except Exception:
                return str(card.get('name', ''))

        # Telegram inline answers are limited to 50 results.
        # Walk the source list until we have 50 valid results, so a missing
        #/broken card entry never causes later cards to be skipped.
        results = []
        cards_db = bot.data.get('cards', {}) or {}
        scan_index = offset

        while scan_index < total and len(results) < 50:
            cid = user_cards[scan_index]
            card = cards_db.get(str(cid))
            scan_index += 1
            if not card:
                continue
            try:
                cap = _cap(card)
                if card.get('type') == 'video' and card.get('video'):
                    results.append(InlineQueryResultCachedVideo(
                        id=f"uh_v_{card.get('id','0')}_{offset}_{random.randint(1000,9999)}",
                        video_file_id=card['video'],
                        title=str(card.get('name', 'Video Card')),
                        description=(
                            f"{rarity_info.get('emoji','')} {rarity_info.get('name','')}"
                            if rarity_key is not None else "Your Harem"
                        ),
                        caption=cap,
                        parse_mode='Markdown',
                    ))
                elif card.get('image'):
                    results.append(InlineQueryResultCachedPhoto(
                        id=f"uh_p_{card.get('id','0')}_{offset}_{random.randint(1000,9999)}",
                        photo_file_id=card['image'],
                        title=str(card.get('name', 'Card')),
                        description=(
                            f"{rarity_info.get('emoji','')} {rarity_info.get('name','')}"
                            if rarity_key is not None else "Your Harem"
                        ),
                        caption=cap,
                        parse_mode='Markdown',
                    ))
            except Exception as _e:
                _ufp_log.warning(f"[ufp] build inline harem result failed: {_e}")
                continue

        # Telegram will request the next batch automatically while the user
        # scrolls the inline result list. The cursor is the actual source
        # position we reached, not blindly offset+50.
        next_offset = str(scan_index) if scan_index < total else ""

        try:
            await iq.answer(
                results,
                cache_time=1,
                is_personal=True,
                next_offset=next_offset,
            )
        except Exception as _e:
            _ufp_log.error(f"[ufp] inline harem iq.answer failed: {_e}")
            try:
                await iq.answer(results, cache_time=1, is_personal=True)
            except Exception:
                pass
    except Exception as e:
        _ufp_log.error(f"[ufp] _ufp_inline_query error: {e}", exc_info=True)
        if _ufp_orig_inline_query is not None:
            try:
                return await _ufp_orig_inline_query(update, context)
            except Exception:
                pass


# Rebind the module-level inline_query name so add_handler picks up the new one.
try:
    if _ufp_orig_inline_query is not None:
        globals()["inline_query"] = _ufp_inline_query
        _ufp_log.info("[ufp] inline_query globally rebound ✅")
except Exception as _ufp_e:
    _ufp_log.error(f"[ufp] rebind inline_query failed: {_ufp_e}")


# ───────────────────────────────────────────────────────────────────────
#  Post-init hook → re-register handlers with high priority (group=-10)
#  so the wrapped versions win even if the originals were registered
#  earlier with the original function references.
# ───────────────────────────────────────────────────────────────────────
def _ufp_register_handlers(application):
    try:
        from telegram.ext import CommandHandler as _UCH
        from telegram.ext import InlineQueryHandler as _UIQH

        application.add_handler(_UCH("ziceko", _ufp_ziceko_cmd), group=-10)
        application.add_handler(_UIQH(_ufp_inline_query), group=-10)
        _ufp_log.info("[ufp] handlers re-registered at group=-10 ✅")
    except Exception as e:
        _ufp_log.error(f"[ufp] register failed: {e}")


def _ufp_install_post_init_hook():
    """Mirror the immortal/black-market sidecar pattern: wrap Application.__init__
    so our handlers register automatically when main() builds the Application."""
    try:
        from telegram.ext import Application as _UFP_App
    except Exception:
        return
    orig_init = getattr(_UFP_App, "__init__", None)
    if not callable(orig_init):
        return
    if getattr(orig_init, "_ufp_wrapped", False):
        return

    def patched_init(self, *args, **kwargs):
        orig_init(self, *args, **kwargs)
        try:
            _ufp_register_handlers(self)
        except Exception as e:
            _ufp_log.error(f"[ufp] register-on-init failed: {e}")

    patched_init._ufp_wrapped = True  # type: ignore[attr-defined]
    try:
        _UFP_App.__init__ = patched_init  # type: ignore[assignment]
    except Exception as e:
        _ufp_log.error(f"[ufp] App.__init__ patch failed: {e}")


try:
    _ufp_install_post_init_hook()
except Exception as _ufp_e:
    _ufp_log.error(f"[ufp] post-init install failed: {_ufp_e}")


# ═══════════════════════════════════════════════════════════════════════════════
#  END  UNICODE FONT NORMALIZATION + INLINE CMODE FILTER PATCH
