import logging as _jl_logging
import json as _jl_json
import os as _jl_os
import html as _jl_html
from datetime import datetime as _jl_datetime

_jl_log = _jl_logging.getLogger("joinlog")
_JL_FILE = "joinlog_settings.json"


def _jl_load() -> dict:
    """Load join-log settings from disk (separate file so it survives restart)."""
    try:
        if _jl_os.path.exists(_JL_FILE):
            with open(_JL_FILE, "r", encoding="utf-8") as _f:
                _data = _jl_json.load(_f)
                if isinstance(_data, dict):
                    return _data
    except Exception as _e:
        _jl_log.error(f"[joinlog] load error: {_e}")
    return {}


def _jl_save(d: dict) -> None:
    try:
        with open(_JL_FILE, "w", encoding="utf-8") as _f:
            _jl_json.dump(d, _f, ensure_ascii=False, indent=2)
    except Exception as _e:
        _jl_log.error(f"[joinlog] save error: {_e}")


# In-memory store (also mirrored into bot.settings so /backupnow includes it)
_JL_STORE: dict = _jl_load()

# Also make sure the standalone joinlog_settings.json is included in the
# main backup zip (BACKUP_FILES is defined near the top of this file).
try:
    if isinstance(BACKUP_FILES, list) and _JL_FILE not in BACKUP_FILES:  # type: ignore[name-defined]
        BACKUP_FILES.append(_JL_FILE)  # type: ignore[name-defined]
except Exception:
    pass


def _jl_bot():
    try:
        return globals().get("bot")
    except Exception:
        return None


def _jl_sync_into_bot_settings():
    """Mirror join-log config into bot.settings so the existing backup/restore
    pipeline picks it up (everything inside bot.settings gets included)."""
    b = _jl_bot()
    if not b:
        return
    try:
        b.settings["joinlog"] = dict(_JL_STORE)
        try:
            b.save_settings()
        except Exception:
            pass
    except Exception as _e:
        _jl_log.warning(f"[joinlog] sync_into_bot_settings: {_e}")


def _jl_sync_from_bot_settings():
    """On startup / after restore, pull settings back from bot.settings if present."""
    b = _jl_bot()
    if not b:
        return
    try:
        cfg = (b.settings or {}).get("joinlog")
        if isinstance(cfg, dict) and cfg:
            _JL_STORE.clear()
            _JL_STORE.update(cfg)
            _jl_save(_JL_STORE)
    except Exception as _e:
        _jl_log.warning(f"[joinlog] sync_from_bot_settings: {_e}")


def _jl_is_owner(uid) -> bool:
    try:
        return int(uid) in OWNERS  # type: ignore[name-defined]
    except Exception:
        return False


def _jl_set_channel(chat_id: int) -> None:
    _JL_STORE["log_chat_id"] = int(chat_id)
    _jl_save(_JL_STORE)
    _jl_sync_into_bot_settings()


def _jl_refresh_from_settings_if_newer():
    """After a restorefull, bot.settings may carry a fresher 'joinlog' dict than
    our in-memory _JL_STORE. Re-sync the in-memory copy so the next getter call
    sees the restored values WITHOUT touching the existing restore code."""
    try:
        b = _jl_bot()
        if not b:
            return
        cfg = (b.settings or {}).get("joinlog")
        if not isinstance(cfg, dict):
            return
        # If bot.settings has a value we don't have in memory, adopt it.
        if cfg and cfg != _JL_STORE:
            _JL_STORE.clear()
            _JL_STORE.update(cfg)
            _jl_save(_JL_STORE)
    except Exception:
        pass


def _jl_get_channel():
    _jl_refresh_from_settings_if_newer()
    val = _JL_STORE.get("log_chat_id")
    try:
        return int(val) if val is not None else None
    except Exception:
        return None


def _jl_set_media(file_id: str, media_type: str) -> None:
    _JL_STORE["media_file_id"] = str(file_id)
    _JL_STORE["media_type"] = str(media_type)  # "photo" or "video"
    _jl_save(_JL_STORE)
    _jl_sync_into_bot_settings()


def _jl_clear_media() -> None:
    _JL_STORE.pop("media_file_id", None)
    _JL_STORE.pop("media_type", None)
    _jl_save(_JL_STORE)
    _jl_sync_into_bot_settings()


def _jl_get_media():
    _jl_refresh_from_settings_if_newer()
    fid = _JL_STORE.get("media_file_id")
    mtype = _JL_STORE.get("media_type")
    if fid and mtype in ("photo", "video"):
        return str(fid), str(mtype)
    return None, None


def _jl_escape(text) -> str:
    try:
        return _jl_html.escape(str(text or ""))
    except Exception:
        return str(text or "")


def _jl_build_added_caption(user, chat) -> str:
    """Build the pretty notification caption for an ADD event."""
    uname = ("@" + user.username) if getattr(user, "username", None) else "—"
    full_name = (getattr(user, "full_name", None)
                 or " ".join(filter(None, [getattr(user, "first_name", ""), getattr(user, "last_name", "")]))
                 or "Unknown")
    mention = f'<a href="tg://user?id={user.id}">{_jl_escape(full_name)}</a>'

    g_name = getattr(chat, "title", None) or "Unknown"
    g_id = chat.id
    g_user = ("@" + chat.username) if getattr(chat, "username", None) else "—"
    g_type = (getattr(chat, "type", "") or "").capitalize() or "Group"

    now_str = _jl_datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    caption = (
        "🤖 <b>New Group Added</b>\n\n"
        "👤 <b>Added By</b>\n"
        f"• Name : {_jl_escape(full_name)}\n"
        f"• User ID : <code>{user.id}</code>\n"
        f"• Username : {_jl_escape(uname)}\n"
        f"• Mention : {mention}\n\n"
        "👥 <b>Group Information</b>\n"
        f"• Group Name : {_jl_escape(g_name)}\n"
        f"• Group ID : <code>{g_id}</code>\n"
        f"• Username : {_jl_escape(g_user)}\n"
        f"• Type : {_jl_escape(g_type)}\n\n"
        f"🕒 <b>Added Time</b> : <code>{now_str}</code>\n\n"
        "✅ <i>Bot was added successfully.</i>"
    )
    return caption


def _jl_build_removed_caption(user, chat, status: str) -> str:
    uname = ("@" + user.username) if getattr(user, "username", None) else "—"
    full_name = (getattr(user, "full_name", None)
                 or " ".join(filter(None, [getattr(user, "first_name", ""), getattr(user, "last_name", "")]))
                 or "Unknown")
    mention = f'<a href="tg://user?id={user.id}">{_jl_escape(full_name)}</a>'

    g_name = getattr(chat, "title", None) or "Unknown"
    g_id = chat.id
    g_user = ("@" + chat.username) if getattr(chat, "username", None) else "—"
    g_type = (getattr(chat, "type", "") or "").capitalize() or "Group"

    now_str = _jl_datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    pretty_status = "Kicked 👢" if status == "kicked" else "Left 🚪"

    caption = (
        "⚠️ <b>Bot Removed From Group</b>\n\n"
        "👤 <b>Action By</b>\n"
        f"• Name : {_jl_escape(full_name)}\n"
        f"• User ID : <code>{user.id}</code>\n"
        f"• Username : {_jl_escape(uname)}\n"
        f"• Mention : {mention}\n\n"
        "👥 <b>Group Information</b>\n"
        f"• Group Name : {_jl_escape(g_name)}\n"
        f"• Group ID : <code>{g_id}</code>\n"
        f"• Username : {_jl_escape(g_user)}\n"
        f"• Type : {_jl_escape(g_type)}\n\n"
        f"🕒 <b>Time</b> : <code>{now_str}</code>\n"
        f"📛 <b>Status</b> : {pretty_status}"
    )
    return caption


async def _jl_send_notification(context, caption: str) -> None:
    """Send notification to the configured log channel with optional photo/video."""
    log_chat = _jl_get_channel()
    if not log_chat:
        _jl_log.info("[joinlog] no log channel configured — skipping notification")
        return

    file_id, media_type = _jl_get_media()
    try:
        if file_id and media_type == "photo":
            await context.bot.send_photo(
                chat_id=log_chat, photo=file_id,
                caption=caption, parse_mode="HTML"
            )
        elif file_id and media_type == "video":
            await context.bot.send_video(
                chat_id=log_chat, video=file_id,
                caption=caption, parse_mode="HTML"
            )
        else:
            await context.bot.send_message(
                chat_id=log_chat, text=caption,
                parse_mode="HTML", disable_web_page_preview=True
            )
    except Exception as _e:
        _jl_log.error(f"[joinlog] failed to send notification to {log_chat}: {_e}")
        # Fallback: try plain text in case media file_id is stale
        try:
            await context.bot.send_message(
                chat_id=log_chat, text=caption,
                parse_mode="HTML", disable_web_page_preview=True
            )
        except Exception as _e2:
            _jl_log.error(f"[joinlog] plain-text fallback also failed: {_e2}")


async def _jl_my_chat_member_handler(update, context):
    """Triggered when the bot's chat-membership status changes (ChatMemberUpdated)."""
    try:
        cmu = update.my_chat_member
        if cmu is None:
            return
        chat = cmu.chat
        # only react in groups / supergroups (skip channels & private chats)
        chat_type = getattr(chat, "type", "")
        if chat_type not in ("group", "supergroup"):
            return

        old_status = cmu.old_chat_member.status if cmu.old_chat_member else None
        new_status = cmu.new_chat_member.status if cmu.new_chat_member else None

        # actor who caused the membership change
        actor = cmu.from_user

        # ADDED  =  was not member -> now member/administrator
        added_states = ("member", "administrator")
        leaving_states = ("left", "kicked", "restricted")

        if (old_status in (None, "left", "kicked")) and (new_status in added_states):
            caption = _jl_build_added_caption(actor, chat)
            await _jl_send_notification(context, caption)
            return

        # REMOVED  =  was member/admin -> now left/kicked
        if (old_status in added_states) and (new_status in leaving_states):
            caption = _jl_build_removed_caption(actor, chat, new_status or "left")
            await _jl_send_notification(context, caption)
            return

    except Exception as _e:
        _jl_log.error(f"[joinlog] my_chat_member handler error: {_e}")


# ──────────────── Owner commands ────────────────

async def _jl_setjoinlog_cmd(update, context):
    """/setjoinlog <chat_id>   — Owner only"""
    try:
        msg = update.effective_message
        user = update.effective_user
        if not user or not _jl_is_owner(user.id):
            try:
                await msg.reply_text("❌ Owner only.")
            except Exception:
                pass
            return

        args = context.args or []
        if not args:
            cur = _jl_get_channel()
            cur_txt = f"<code>{cur}</code>" if cur else "—"
            await msg.reply_text(
                f"Usage: <code>/setjoinlog &lt;chat_id&gt;</code>\n"
                f"Current: {cur_txt}",
                parse_mode="HTML"
            )
            return

        raw = args[0].strip()
        try:
            chat_id = int(raw)
        except Exception:
            await msg.reply_text("❌ Invalid chat id. Example: <code>/setjoinlog -1001234567890</code>", parse_mode="HTML")
            return

        _jl_set_channel(chat_id)
        await msg.reply_text(
            f"✅ Join-log channel set to <code>{chat_id}</code>",
            parse_mode="HTML"
        )
    except Exception as _e:
        _jl_log.error(f"[joinlog] setjoinlog_cmd error: {_e}")


async def _jl_setjoinmedia_cmd(update, context):
    """/setjoinmedia (reply to photo or video)  — Owner only.
    The replied media is saved by file_id so it survives restart."""
    try:
        msg = update.effective_message
        user = update.effective_user
        if not user or not _jl_is_owner(user.id):
            try:
                await msg.reply_text("❌ Owner only.")
            except Exception:
                pass
            return

        reply = msg.reply_to_message if msg else None
        if not reply:
            await msg.reply_text(
                "📎 Reply to a <b>photo</b> or <b>video</b> with /setjoinmedia to use it on join notifications.",
                parse_mode="HTML"
            )
            return

        # photo (take highest-resolution thumb)
        if getattr(reply, "photo", None):
            fid = reply.photo[-1].file_id
            _jl_set_media(fid, "photo")
            await msg.reply_text("✅ Join-log photo saved.")
            return

        # video
        if getattr(reply, "video", None):
            fid = reply.video.file_id
            _jl_set_media(fid, "video")
            await msg.reply_text("✅ Join-log video saved.")
            return

        # animation / gif (treat as video)
        if getattr(reply, "animation", None):
            fid = reply.animation.file_id
            _jl_set_media(fid, "video")
            await msg.reply_text("✅ Join-log animation saved.")
            return

        await msg.reply_text("❌ The replied message must be a photo or video.")
    except Exception as _e:
        _jl_log.error(f"[joinlog] setjoinmedia_cmd error: {_e}")


async def _jl_clearjoinmedia_cmd(update, context):
    """/clearjoinmedia — remove the saved photo/video (owner only)."""
    try:
        msg = update.effective_message
        user = update.effective_user
        if not user or not _jl_is_owner(user.id):
            return
        _jl_clear_media()
        await msg.reply_text("🗑️ Join-log media cleared. Notifications will be sent as plain text.")
    except Exception as _e:
        _jl_log.error(f"[joinlog] clearjoinmedia_cmd error: {_e}")


async def _jl_joinlog_status_cmd(update, context):
    """/joinlogstatus — show current settings (owner only)."""
    try:
        msg = update.effective_message
        user = update.effective_user
        if not user or not _jl_is_owner(user.id):
            return
        ch = _jl_get_channel()
        fid, mtype = _jl_get_media()
        text = (
            "📋 <b>Join-Log Settings</b>\n\n"
            f"• Log channel : <code>{ch if ch else '—'}</code>\n"
            f"• Media type  : <code>{mtype or '—'}</code>\n"
            f"• Media file_id : <code>{(fid[:30] + '…') if fid else '—'}</code>"
        )
        await msg.reply_text(text, parse_mode="HTML")
    except Exception as _e:
        _jl_log.error(f"[joinlog] joinlogstatus_cmd error: {_e}")


def _jl_register_handlers(application) -> None:
    """Register all join-log handlers on the given Application."""
    try:
        from telegram.ext import (
            ChatMemberHandler as _JL_CMH,
            CommandHandler as _JL_CH,
        )

        # MY_CHAT_MEMBER : only this bot's own membership changes
        application.add_handler(
            _JL_CMH(_jl_my_chat_member_handler, _JL_CMH.MY_CHAT_MEMBER),
            group=-5
        )
        application.add_handler(_JL_CH("setjoinlog", _jl_setjoinlog_cmd))
        application.add_handler(_JL_CH("setjoinmedia", _jl_setjoinmedia_cmd))
        application.add_handler(_JL_CH("clearjoinmedia", _jl_clearjoinmedia_cmd))
        application.add_handler(_JL_CH("joinlogstatus", _jl_joinlog_status_cmd))

        # Restore from bot.settings after possible backup-restore
        try:
            _jl_sync_from_bot_settings()
        except Exception:
            pass

        _jl_log.info("[joinlog] handlers registered ✅")
    except Exception as _e:
        _jl_log.error(f"[joinlog] register failed: {_e}")


def _jl_install_post_init_hook() -> None:
    """Same pattern as other sidecars: patch Application.__init__ so our
    handlers are registered automatically without touching main()."""
    try:
        from telegram.ext import Application as _JL_App
    except Exception:
        return
    orig_init = getattr(_JL_App, "__init__", None)
    if not callable(orig_init):
        return
    if getattr(orig_init, "_jl_wrapped", False):
        return

    def patched_init(self, *args, **kwargs):
        orig_init(self, *args, **kwargs)
        try:
            _jl_register_handlers(self)
        except Exception as _e:
            _jl_log.error(f"[joinlog] register-on-init failed: {_e}")

    patched_init._jl_wrapped = True  # type: ignore[attr-defined]
    try:
        _JL_App.__init__ = patched_init  # type: ignore[assignment]
    except Exception as _e:
        _jl_log.error(f"[joinlog] App.__init__ patch failed: {_e}")


try:
    _jl_install_post_init_hook()
except Exception as _jl_e:
    _jl_log.error(f"[joinlog] post-init install failed: {_jl_e}")


# ═══════════════════════════════════════════════════════════════════════════════
#  END  JOIN LOG
