# ═══════════════════════════════════════════════════════════════════════════════
#  BEGIN  MINES GAME  (/mines)
#  Sidecar module — Diamond casino-style mines game with persistence.
#  Uses the same diamond wallet as the rest of the bot (user_profiles[uid]['kakera']).
#  Persists active games into bot.data so they survive restart and full restore.
# ═══════════════════════════════════════════════════════════════════════════════

import logging as _mn_logging
import random as _mn_random
from datetime import datetime as _mn_datetime

_mn_log = _mn_logging.getLogger("mines")

_MN_GRID_SIZE = 25         # 5×5 board
_MN_CARD_DROP_RATE = 0.005  # 0.5 %
_MN_JACKPOT_RATE = 0.001    # 0.1 %
_MN_JACKPOT_MULT = 50

# Per-mine-count multiplier curves (multipliers ASSUMED at 1..N safe picks)
# The values below match the spec for 3 mines; the 5/10 curves grow faster.
_MN_MULT_CURVES = {
    3:  [1.20, 1.50, 2.00, 3.00, 5.00, 7.00, 10.0, 14.0, 20.0, 30.0, 45.0, 65.0],
    5:  [1.35, 1.80, 2.50, 3.80, 6.00, 9.50, 15.0, 24.0, 40.0, 70.0, 120.0, 200.0],
    10: [1.80, 3.00, 5.50, 10.0, 18.0, 35.0, 70.0, 140.0, 280.0, 600.0, 1200.0, 2500.0],
}


def _mn_bot():
    try:
        return globals().get("bot")
    except Exception:
        return None


def _mn_get_diamonds(uid) -> int:
    fn = globals().get("_im_get_diamonds")
    if callable(fn):
        try:
            return int(fn(str(uid)) or 0)
        except Exception:
            pass
    b = _mn_bot()
    if not b:
        return 0
    try:
        return int((b.data.get("user_profiles", {}).get(str(uid), {}) or {}).get("kakera", 0) or 0)
    except Exception:
        return 0


def _mn_add_diamonds(uid, amount: int) -> int:
    fn = globals().get("_im_add_diamonds")
    if callable(fn):
        try:
            return int(fn(str(uid), int(amount)) or 0)
        except Exception:
            pass
    b = _mn_bot()
    if not b:
        return 0
    prof = b.data.setdefault("user_profiles", {}).setdefault(str(uid), {})
    new_bal = max(0, int(prof.get("kakera", 0) or 0) + int(amount))
    prof["kakera"] = new_bal
    try:
        b.save_data()
    except Exception:
        pass
    return new_bal


def _mn_fmt(n) -> int:
    try:
        return int(n)
    except Exception:
        return 0


def _mn_store() -> dict:
    """Persistent store inside bot.data['mines_games'] = { uid_str: game_dict }."""
    b = _mn_bot()
    if not b:
        return {}
    return b.data.setdefault("mines_games", {})


def _mn_save():
    b = _mn_bot()
    if not b:
        return
    try:
        b.save_data()
    except Exception as _e:
        _mn_log.error(f"[mines] save failed: {_e}")


def _mn_get_game(uid):
    return _mn_store().get(str(uid))


def _mn_set_game(uid, game: dict):
    _mn_store()[str(uid)] = game
    _mn_save()


def _mn_clear_game(uid):
    store = _mn_store()
    if str(uid) in store:
        del store[str(uid)]
        _mn_save()


def _mn_parse_amount(arg: str, balance: int) -> int | None:
    """Parse the bet amount (supports 'all')."""
    if arg is None:
        return None
    s = str(arg).strip().lower()
    if not s:
        return None
    if s in ("all", "max"):
        return int(balance)
    # strip commas / underscores
    s = s.replace(",", "").replace("_", "")
    try:
        v = int(float(s))
        if v <= 0:
            return None
        return v
    except Exception:
        return None


def _mn_pick_multiplier(num_mines: int, safe_opened: int) -> float:
    curve = _MN_MULT_CURVES.get(int(num_mines), _MN_MULT_CURVES[3])
    if safe_opened <= 0:
        return 1.0
    idx = min(safe_opened - 1, len(curve) - 1)
    return float(curve[idx])


def _mn_render_board(game: dict, reveal_all: bool = False) -> list:
    """Build the 5x5 inline keyboard from the current game state."""
    from telegram import InlineKeyboardButton as _MN_Btn, InlineKeyboardMarkup as _MN_KB

    opened = set(int(x) for x in game.get("opened", []))
    mines = set(int(x) for x in game.get("mines", []))
    hit_mine_idx = game.get("hit_mine")
    is_ended = bool(game.get("ended"))

    rows = []
    for r in range(5):
        row = []
        for c in range(5):
            idx = r * 5 + c
            if reveal_all or is_ended:
                if idx == hit_mine_idx:
                    label = "💥"
                elif idx in mines:
                    label = "💣"
                elif idx in opened:
                    label = "💎"
                else:
                    label = "⬜"
                # disable all tiles when game is over
                row.append(_MN_Btn(label, callback_data="mn_noop"))
            else:
                if idx in opened:
                    label = "💎"
                    row.append(_MN_Btn(label, callback_data="mn_noop"))
                else:
                    label = "⬜"
                    row.append(_MN_Btn(label, callback_data=f"mn_tile_{idx}"))
        rows.append(row)

    # bottom action row
    if not is_ended:
        safe_opened = len(opened)
        if safe_opened > 0:
            mult = _mn_pick_multiplier(int(game.get("mines_count", 3)), safe_opened)
            rows.append([
                _MN_Btn(f"?? Cashout (x{mult:g})", callback_data="mn_cashout"),
                _MN_Btn("🏳️ Forfeit", callback_data="mn_forfeit"),
            ])
        else:
            rows.append([_MN_Btn("🏳️ Forfeit", callback_data="mn_forfeit")])
    return rows


def _mn_render_status(game: dict, footer: str = "") -> str:
    bet = _mn_fmt(game.get("bet", 0))
    mines_count = int(game.get("mines_count", 3))
    safe_opened = len(game.get("opened", []))
    mult = _mn_pick_multiplier(mines_count, safe_opened)
    potential = int(bet * mult) if safe_opened > 0 else bet
    text = (
        "🎮 <b>MINES</b>\n"
        f"💎 Bet : <b>{bet:,}</b>\n"
        f"💣 Mines : <b>{mines_count}</b>\n"
        f"✅ Safe opened : <b>{safe_opened}</b>\n"
        f"📈 Multiplier : <b>x{mult:g}</b>\n"
        f"💰 Potential : <b>{potential:,}</b> 💎"
    )
    if footer:
        text += f"\n\n{footer}"
    return text


def _mn_render_setup(bet: int, footer: str = "") -> tuple:
    """Build the mines-count selection screen."""
    from telegram import InlineKeyboardButton as _MN_Btn, InlineKeyboardMarkup as _MN_KB

    text = (
        "🎮 <b>MINES</b>\n\n"
        f"💎 Bet : <b>{bet:,}</b>\n\n"
        "💣 Choose how many mines:"
    )
    if footer:
        text += f"\n\n{footer}"
    kb = _MN_KB([
        [
            _MN_Btn("💣 3 Mines",  callback_data=f"mn_setup_3_{bet}"),
            _MN_Btn("💣 5 Mines",  callback_data=f"mn_setup_5_{bet}"),
            _MN_Btn("💣 10 Mines", callback_data=f"mn_setup_10_{bet}"),
        ],
        [_MN_Btn("❌ Cancel", callback_data=f"mn_setup_cancel_{bet}")]
    ])
    return text, kb


def _mn_start_game(uid: int, bet: int, mines_count: int) -> dict:
    indices = list(range(_MN_GRID_SIZE))
    _mn_random.shuffle(indices)
    mines = indices[:mines_count]
    game = {
        "uid": int(uid),
        "bet": int(bet),
        "mines_count": int(mines_count),
        "mines": mines,
        "opened": [],
        "ended": False,
        "started_at": _mn_datetime.now().isoformat(),
        "hit_mine": None,
        "chat_id": None,
        "message_id": None,
    }
    _mn_set_game(uid, game)
    return game


def _mn_try_card_drop(uid: int) -> str | None:
    """0.5% chance to drop a random card to the user. Returns the card_id or None.
    Uses the same '_au_give_card_to_user' helper as the rest of the bot."""
    try:
        if _mn_random.random() >= _MN_CARD_DROP_RATE:
            return None
        b = _mn_bot()
        if not b:
            return None
        all_cards = b.data.get("cards", {}) or {}
        pool = [cid for cid, c in all_cards.items()
                if isinstance(c, dict) and c.get("drop_enabled", True)]
        if not pool:
            return None
        card_id = _mn_random.choice(pool)
        # Use the existing auction-module helper if available
        giver = globals().get("_au_give_card_to_user")
        if callable(giver):
            try:
                giver(str(uid), str(card_id))
            except Exception as _e:
                _mn_log.warning(f"[mines] _au_give_card_to_user failed: {_e}")
                return None
        else:
            # Fallback: manual append (mirrors the same data model)
            try:
                init_fn = globals().get("init_user_if_not_exists")
                if callable(init_fn):
                    init_fn(str(uid))
            except Exception:
                pass
            users = b.data.setdefault("users", {})
            lst = users.setdefault(str(uid), [])
            lst.append(str(card_id))
        try:
            _mn_save()
        except Exception:
            pass
        return str(card_id)
    except Exception as _e:
        _mn_log.error(f"[mines] card_drop error: {_e}")
        return None


# ────────────── Command & callbacks ──────────────

async def _mn_mines_cmd(update, context):
    """/mines <amount|all>   — start a new mines round (must end previous first)."""
    try:
        msg = update.effective_message
        user = update.effective_user
        if not msg or not user:
            return

        # Already-running game?
        existing = _mn_get_game(user.id)
        if existing and not existing.get("ended"):
            await msg.reply_text(
                "⚠️ You already have a mines game in progress.\n"
                "Open it or use 🏳️ Forfeit / 💰 Cashout first.",
            )
            return

        args = context.args or []
        if not args:
            await msg.reply_text(
                "Usage:\n"
                "<code>/mines 1000</code>\n"
                "<code>/mines 5000000</code>\n"
                "<code>/mines all</code>",
                parse_mode="HTML",
            )
            return

        balance = _mn_get_diamonds(user.id)
        bet = _mn_parse_amount(args[0], balance)
        if bet is None or bet <= 0:
            await msg.reply_text("❌ Invalid amount.")
            return
        if bet > balance:
            await msg.reply_text(
                f"❌ You only have <b>{balance:,}</b> 💎",
                parse_mode="HTML",
            )
            return

        # Show mines-count selection — bet is NOT deducted yet (deducted on confirm)
        text, kb = _mn_render_setup(bet)
        await msg.reply_text(text, parse_mode="HTML", reply_markup=kb)

    except Exception as _e:
        _mn_log.error(f"[mines] /mines error: {_e}")
        try:
            await update.effective_message.reply_text("❌ Error starting game.")
        except Exception:
            pass


async def _mn_callback(update, context):
    """All mines callbacks: mn_setup_*, mn_tile_*, mn_cashout, mn_forfeit, mn_noop."""
    try:
        query = update.callback_query
        if not query:
            return
        user = query.from_user
        data = query.data or ""

        if data == "mn_noop":
            try:
                await query.answer()
            except Exception:
                pass
            return

        # ──────────── SETUP ────────────
        if data.startswith("mn_setup_"):
            parts = data.split("_")
            # mn_setup_cancel_<bet>   OR   mn_setup_<N>_<bet>
            if parts[2] == "cancel":
                await query.answer("Cancelled.")
                try:
                    await query.edit_message_text("❌ Mines game cancelled.")
                except Exception:
                    pass
                return

            try:
                mines_count = int(parts[2])
                bet = int(parts[3])
            except Exception:
                await query.answer("Bad data.", show_alert=True)
                return
            if mines_count not in (3, 5, 10):
                await query.answer("Invalid mines count.", show_alert=True)
                return

            # Check balance again and deduct
            balance = _mn_get_diamonds(user.id)
            if bet > balance:
                await query.answer("Not enough diamonds.", show_alert=True)
                try:
                    await query.edit_message_text("❌ Not enough diamonds.")
                except Exception:
                    pass
                return

            # already running?
            existing = _mn_get_game(user.id)
            if existing and not existing.get("ended"):
                await query.answer("You already have an active game.", show_alert=True)
                return

            # Deduct bet up-front (refund only on cashout)
            _mn_add_diamonds(user.id, -bet)

            game = _mn_start_game(user.id, bet, mines_count)
            # store chat & message for later edits
            game["chat_id"] = query.message.chat_id
            game["message_id"] = query.message.message_id
            _mn_set_game(user.id, game)

            from telegram import InlineKeyboardMarkup as _MN_KB
            text = _mn_render_status(game)
            kb = _MN_KB(_mn_render_board(game))
            try:
                await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
            except Exception as _e:
                _mn_log.warning(f"[mines] edit on setup failed: {_e}")
            try:
                await query.answer("Good luck! 🍀")
            except Exception:
                pass
            return

        # All other actions need an active game
        game = _mn_get_game(user.id)
        if not game or game.get("ended"):
            try:
                await query.answer("No active mines game.", show_alert=True)
            except Exception:
                pass
            return

        # Only the player who started it can act
        if int(game.get("uid", 0)) != int(user.id):
            try:
                await query.answer("This isn't your game.", show_alert=True)
            except Exception:
                pass
            return

        # ──────────── FORFEIT ────────────
        if data == "mn_forfeit":
            game["ended"] = True
            _mn_set_game(user.id, game)
            try:
                from telegram import InlineKeyboardMarkup as _MN_KB
                text = _mn_render_status(game, "🏳️ <b>Forfeited.</b> Bet lost.")
                kb = _MN_KB(_mn_render_board(game, reveal_all=True))
                await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
            except Exception:
                pass
            _mn_clear_game(user.id)
            try:
                await query.answer("Forfeited.")
            except Exception:
                pass
            return

        # ──────────── CASHOUT ────────────
        if data == "mn_cashout":
            safe_opened = len(game.get("opened", []))
            if safe_opened <= 0:
                try:
                    await query.answer("Open at least one tile first.", show_alert=True)
                except Exception:
                    pass
                return
            bet = int(game.get("bet", 0))
            mines_count = int(game.get("mines_count", 3))
            mult = _mn_pick_multiplier(mines_count, safe_opened)
            reward = int(bet * mult)

            new_bal = _mn_add_diamonds(user.id, reward)
            game["ended"] = True
            _mn_set_game(user.id, game)

            try:
                from telegram import InlineKeyboardMarkup as _MN_KB
                footer = (
                    f"💰 <b>CASHOUT!</b>\n"
                    f"Multiplier : <b>x{mult:g}</b>\n"
                    f"Reward : <b>+{reward:,}</b> 💎\n"
                    f"Balance : <b>{new_bal:,}</b> 💎"
                )
                text = _mn_render_status(game, footer)
                kb = _MN_KB(_mn_render_board(game, reveal_all=True))
                await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
            except Exception:
                pass
            _mn_clear_game(user.id)
            try:
                await query.answer(f"+{reward:,} 💎")
            except Exception:
                pass
            return

        # ──────────── TILE OPEN ────────────
        if data.startswith("mn_tile_"):
            try:
                idx = int(data.split("_")[-1])
            except Exception:
                try:
                    await query.answer("Bad tile.", show_alert=True)
                except Exception:
                    pass
                return
            if idx < 0 or idx >= _MN_GRID_SIZE:
                try:
                    await query.answer("Bad tile.", show_alert=True)
                except Exception:
                    pass
                return

            opened = list(game.get("opened", []))
            mines = list(game.get("mines", []))
            if idx in opened:
                try:
                    await query.answer("Already opened.", show_alert=True)
                except Exception:
                    pass
                return

            # 0.1% Jackpot — instantly cash out at bet * 50, ends the game
            if _mn_random.random() < _MN_JACKPOT_RATE:
                bet = int(game.get("bet", 0))
                reward = int(bet * _MN_JACKPOT_MULT)
                new_bal = _mn_add_diamonds(user.id, reward)
                opened.append(int(idx))
                # if this tile was a mine, force it to safe for visual
                if idx in mines:
                    mines.remove(idx)
                game["opened"] = opened
                game["mines"] = mines
                game["ended"] = True
                _mn_set_game(user.id, game)
                try:
                    from telegram import InlineKeyboardMarkup as _MN_KB
                    footer = (
                        "🌟 <b>JACKPOT!</b>\n"
                        f"Multiplier : <b>x{_MN_JACKPOT_MULT}</b>\n"
                        f"Reward : <b>+{reward:,}</b> 💎\n"
                        f"Balance : <b>{new_bal:,}</b> 💎"
                    )
                    text = _mn_render_status(game, footer)
                    kb = _MN_KB(_mn_render_board(game, reveal_all=True))
                    await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
                except Exception:
                    pass
                _mn_clear_game(user.id)
                try:
                    await query.answer(f"🌟 JACKPOT +{reward:,} 💎", show_alert=True)
                except Exception:
                    pass
                return

            # Mine hit?
            if idx in mines:
                game["opened"] = opened  # keep previous opens
                game["hit_mine"] = int(idx)
                game["ended"] = True
                _mn_set_game(user.id, game)
                try:
                    from telegram import InlineKeyboardMarkup as _MN_KB
                    bet = int(game.get("bet", 0))
                    footer = (
                        "💥 <b>BOOM!</b>\n"
                        f"You hit a mine and lost <b>{bet:,}</b> 💎"
                    )
                    text = _mn_render_status(game, footer)
                    kb = _MN_KB(_mn_render_board(game, reveal_all=True))
                    await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
                except Exception:
                    pass
                _mn_clear_game(user.id)
                try:
                    await query.answer("💥 BOOM!", show_alert=True)
                except Exception:
                    pass
                return

            # Safe tile
            opened.append(int(idx))
            game["opened"] = opened
            _mn_set_game(user.id, game)

            # 0.5% card drop
            drop_msg = ""
            try:
                dropped_id = _mn_try_card_drop(user.id)
                if dropped_id:
                    b = _mn_bot()
                    card = (b.data.get("cards", {}) if b else {}).get(str(dropped_id), {}) if b else {}
                    cname = (card.get("name") if isinstance(card, dict) else None) or f"#{dropped_id}"
                    drop_msg = f"\n🎴 <b>Card Drop!</b> You got: <b>{_jl_escape(cname)}</b>"
            except Exception as _e:
                _mn_log.warning(f"[mines] drop check failed: {_e}")

            try:
                from telegram import InlineKeyboardMarkup as _MN_KB
                safe_opened = len(opened)
                mult = _mn_pick_multiplier(int(game.get("mines_count", 3)), safe_opened)
                bet = int(game.get("bet", 0))
                potential = int(bet * mult)
                footer = (
                    f"✅ Safe! (x{mult:g})\n"
                    f"💰 Cash-out value : <b>{potential:,}</b> 💎"
                    f"{drop_msg}"
                )
                text = _mn_render_status(game, footer)
                kb = _MN_KB(_mn_render_board(game))
                await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
            except Exception as _e:
                _mn_log.warning(f"[mines] tile-open edit failed: {_e}")
            try:
                await query.answer("✅ Safe")
            except Exception:
                pass
            return

        # unknown
        try:
            await query.answer()
        except Exception:
            pass

    except Exception as _e:
        _mn_log.error(f"[mines] callback error: {_e}")
        try:
            await update.callback_query.answer("Error.", show_alert=True)
        except Exception:
            pass


def _mn_register_handlers(application) -> None:
    try:
        from telegram.ext import (
            CommandHandler as _MN_CH,
            CallbackQueryHandler as _MN_CBH,
        )
        application.add_handler(_MN_CH("mines", _mn_mines_cmd))
        application.add_handler(_MN_CBH(_mn_callback, pattern=r"^mn_"))
        _mn_log.info("[mines] handlers registered ✅")
    except Exception as _e:
        _mn_log.error(f"[mines] register failed: {_e}")


def _mn_install_post_init_hook() -> None:
    try:
        from telegram.ext import Application as _MN_App
    except Exception:
        return
    orig_init = getattr(_MN_App, "__init__", None)
    if not callable(orig_init):
        return
    if getattr(orig_init, "_mn_wrapped", False):
        return

    def patched_init(self, *args, **kwargs):
        orig_init(self, *args, **kwargs)
        try:
            _mn_register_handlers(self)
        except Exception as _e:
            _mn_log.error(f"[mines] register-on-init failed: {_e}")

    patched_init._mn_wrapped = True  # type: ignore[attr-defined]
    try:
        _MN_App.__init__ = patched_init  # type: ignore[assignment]
    except Exception as _e:
        _mn_log.error(f"[mines] App.__init__ patch failed: {_e}")


try:
    _mn_install_post_init_hook()
except Exception as _mn_e:
    _mn_log.error(f"[mines] post-init install failed: {_mn_e}")


