# ─── 10. Backup / Restore — the fields are just card-dict keys, so they are
#          automatically included by the existing JSON dump. We only guarantee
#          they exist when loading old backups.
try:
    _orig_load_data = bot.load_data  # type: ignore[name-defined]

    def _ook_load_data_patched(self=None):
        d = _orig_load_data()
        try:
            if isinstance(d, dict):
                seen_uuid = set()
                for cid, c in d.get("cards", {}).items():
                    if _ook_is_ook_card(c):
                        # Guarantee the required fields even after old-format restore
                        c.setdefault("transferable", False)
                        c.setdefault("exclusive_type", "one_of_a_kind")
                        c.setdefault("bound", True)
                        c.setdefault("owner_name", c.get("card_owner_name", "?"))
                        c.setdefault("card_owner_name", c.get("owner_name", "?"))
                        if c.get("card_owner_id") is None and c.get("owner") is not None:
                            c["card_owner_id"] = c["owner"]
                        if not c.get("unique_uuid") or c.get("unique_uuid") in seen_uuid:
                            # Regenerate unique
                            while True:
                                u = _ook_uuid.uuid4().hex
                                if u not in seen_uuid:
                                    break
                            c["unique_uuid"] = u
                        seen_uuid.add(c["unique_uuid"])
        except Exception as _e:
            _ook_log.error(f"[ook] restore-pass repair failed: {_e}")
        return d

    import types as _ook_types2
    bot.load_data = _ook_types2.MethodType(_ook_load_data_patched, bot)  # type: ignore[name-defined]
    _ook_log.info("[ook] load_data hooked for backup/restore integrity")
except Exception as _e:
    _ook_log.error(f"[ook] load_data hook failed: {_e}")


# ─── 11. Drop / Claim / Roll pool protection ─────────────────────────────────
#
#     The rate table `DEFAULT_RARITY_RATES` maps rarity keys "1"..."16" to
#     weights. Since 'ook' is NEVER inserted there, our new rarity is already
#     excluded from every random draw. We additionally guard `_weighted_choice`
#     and `_choose_card_id_by_rates` — belt-and-braces — so that even if a
#     future config accidentally adds it, no OOK card can be picked.
try:
    _orig_choose_card_id_by_rates = _choose_card_id_by_rates  # type: ignore[name-defined]

    def _ook_choose_card_id_by_rates(locked_rarities):
        # Reuse original but if it ever returns an OOK card id, redraw.
        for _ in range(5):
            cid = _orig_choose_card_id_by_rates(locked_rarities)
            if cid is None:
                return None
            c = _ook_get_card_by_id(cid)
            if not c or not _ook_is_ook_card(c):
                return cid
        return None

    globals()["_choose_card_id_by_rates"] = _ook_choose_card_id_by_rates
    _ook_log.info("[ook] drop-pool guard installed")
except Exception as _e:
    _ook_log.error(f"[ook] drop-pool guard failed: {_e}")


# ─── 12. /mines button owner enforcement ─────────────────────────────────────
#
#     Wrap `_mn_callback` so the setup buttons and every subsequent button
#     accept clicks only from the user who invoked /mines. Because the game
#     dict already stores `uid` from the moment a mines-count is picked, the
#     original callback rejects other users after setup — we only need to
#     also protect the setup screen itself.
try:
    _orig_mn_callback = _mn_callback  # type: ignore[name-defined]

    async def _ook_mn_callback(update, context):
        try:
            query = update.callback_query
            if query is not None:
                data = query.data or ""
                # Setup callbacks: `mn_setup_<N>_<bet>` or `mn_setup_cancel_<bet>`
                # The setup message was sent as a REPLY to the user's /mines
                # command → its `reply_to_message.from_user.id` is the invoker.
                if data.startswith("mn_setup_"):
                    invoker_id = None
                    try:
                        rtm = query.message.reply_to_message
                        if rtm and rtm.from_user:
                            invoker_id = int(rtm.from_user.id)
                    except Exception:
                        invoker_id = None
                    if invoker_id is not None and int(query.from_user.id) != invoker_id:
                        try:
                            await query.answer(
                                "❌ ဒီ Mines Game ကို စတင်သူသာ နှိပ်နိုင်ပါသည်။",
                                show_alert=True,
                            )
                        except Exception:
                            pass
                        return
        except Exception as _e:
            _ook_log.error(f"[ook] mines-guard pre error: {_e}")
        return await _orig_mn_callback(update, context)

    globals()["_mn_callback"] = _ook_mn_callback
    _ook_log.info("[ook] /mines button-owner guard installed")
except Exception as _e:
    _ook_log.error(f"[ook] mines-guard failed: {_e}")


# ─── 13. Post-init hook — register /createook, /setowner, /ookcards ──────────
def _ook_register_handlers(application):
    try:
        from telegram.ext import CommandHandler as _OokCH
        # Guard against double registration
        try:
            _existing = getattr(application, "_ook_registered", False)
            if _existing:
                return
        except Exception:
            pass

        # Remove any duplicate registrations of same command names to keep
        # command tables clean (per project maintenance habits).
        try:
            handlers_map = application.handlers
            for _grp, _list in list(handlers_map.items()):
                new_list = []
                for h in _list:
                    try:
                        cmds = set(getattr(h, "commands", set()) or set())
                    except Exception:
                        cmds = set()
                    if cmds & {"createook", "setowner", "ookcards"}:
                        continue  # drop older duplicates
                    new_list.append(h)
                handlers_map[_grp] = new_list
        except Exception as _e:
            _ook_log.warning(f"[ook] cleanup old handlers failed: {_e}")

        application.add_handler(_OokCH("createook", _ook_createook_cmd))
        application.add_handler(_OokCH("setowner",  _ook_setowner_cmd))
        application.add_handler(_OokCH("ookcards",  _ook_list_cmd))
        try:
            application._ook_registered = True  # type: ignore[attr-defined]
        except Exception:
            pass
        _ook_log.info(
            "[ook] handlers registered: /createook /setowner /ookcards"
        )
    except Exception as _e:
        _ook_log.error(f"[ook] register handlers failed: {_e}")


def _ook_install_post_init_hook():
    """Monkey-patch Application.__init__ so handlers install on every build."""
    try:
        from telegram.ext import Application as _OokApp
        orig_init = _OokApp.__init__
        if getattr(orig_init, "_ook_wrapped", False):
            return

        def patched_init(self, *args, **kwargs):
            orig_init(self, *args, **kwargs)
            try:
                _ook_register_handlers(self)
            except Exception as _e:
                _ook_log.error(f"[ook] register-on-init failed: {_e}")

        patched_init._ook_wrapped = True  # type: ignore[attr-defined]
        _OokApp.__init__ = patched_init  # type: ignore[assignment]
    except Exception as _e:
        _ook_log.error(f"[ook] post-init install failed: {_e}")


try:
    _ook_install_post_init_hook()
except Exception as _e:
    _ook_log.error(f"[ook] post-init install error: {_e}")


