# ═══════════════════════════════════════════════════════════════════════════════
#  BEGIN  MINES CASHOUT + AUTO-CASHOUT + UPLOAD FIX ADDON  (non-destructive)
#  Adds:
#    • /cashout    → immediate cashout for any active /mines game (all users)
#    • auto-cashout when a /mines game has been idle for 60s
#    • /upload  &  /uploadvd re-registration guard (ensures they run reliably)
#  This module is APPEND-ONLY.  It does not modify or replace any existing
#  function, handler, or data structure.  All names are prefixed `_mnx_`
#  to avoid clashes with the original bot code.
# ═══════════════════════════════════════════════════════════════════════════════

import asyncio as _mnx_asyncio
import logging as _mnx_logging
import time as _mnx_time
from datetime import datetime as _mnx_datetime

_mnx_log = _mnx_logging.getLogger("mines_addon")

# Idle window (seconds) before a mines game is auto-cashed out
_MNX_IDLE_SECONDS = 60
# How often the watcher polls all active games
_MNX_POLL_SECONDS = 5


# ─── Helper: touch `last_action_at` on every tile-open / setup ─────────────
def _mnx_touch(uid) -> None:
    """Mark the given user's mines game as 'just acted on now'."""
    try:
        store_fn = globals().get("_mn_store")
        save_fn = globals().get("_mn_save")
        if not callable(store_fn):
            return
        store = store_fn() or {}
        g = store.get(str(uid))
        if not g or g.get("ended"):
            return
        g["last_action_at"] = _mnx_time.time()
        if callable(save_fn):
            try:
                save_fn()
            except Exception:
                pass
    except Exception as _e:
        _mnx_log.warning(f"[mnx] touch failed: {_e}")


# ─── Wrap _mn_callback so every user action updates the idle timer ─────────
try:
    _mnx_orig_mn_callback = globals().get("_mn_callback")
    if callable(_mnx_orig_mn_callback):

        async def _mnx_wrapped_mn_callback(update, context):
            try:
                q = update.callback_query
                if q and q.from_user:
                    # Touch BEFORE processing so the timer reflects the newest action
                    _mnx_touch(q.from_user.id)
            except Exception:
                pass
            return await _mnx_orig_mn_callback(update, context)

        globals()["_mn_callback"] = _mnx_wrapped_mn_callback
        _mnx_log.info("[mnx] _mn_callback wrapped with idle-timer touch ✅")
except Exception as _e:
    _mnx_log.error(f"[mnx] wrap _mn_callback failed: {_e}")


# ─── Helper: perform a cashout for a given user (shared by /cashout cmd
#     and by the auto-cashout watcher) ─────────────────────────────────────
async def _mnx_perform_cashout(uid: int, *, reason: str = "manual",
                               notify_send=None):
    """Execute a cashout on the currently active game for `uid`.

    Returns a dict:
      {'ok': True, 'reward': int, 'balance': int, 'mult': float, 'bet': int,
       'chat_id': int|None, 'message_id': int|None}
    Or:
      {'ok': False, 'reason': str}
    """
    try:
        get_game = globals().get("_mn_get_game")
        set_game = globals().get("_mn_set_game")
        clear_game = globals().get("_mn_clear_game")
        add_dia = globals().get("_mn_add_diamonds")
        pick_mult = globals().get("_mn_pick_multiplier")
        render_status = globals().get("_mn_render_status")
        render_board = globals().get("_mn_render_board")

        if not callable(get_game) or not callable(add_dia) or not callable(pick_mult):
            return {"ok": False, "reason": "mines module missing"}

        game = get_game(uid)
        if not game or game.get("ended"):
            return {"ok": False, "reason": "no_active_game"}

        safe_opened = len(game.get("opened", []) or [])
        if safe_opened <= 0:
            return {"ok": False, "reason": "no_safe_open"}

        bet = int(game.get("bet", 0) or 0)
        mines_count = int(game.get("mines_count", 3) or 3)
        mult = float(pick_mult(mines_count, safe_opened))
        reward = int(bet * mult)

        new_bal = int(add_dia(uid, reward) or 0)
        game["ended"] = True
        try:
            set_game(uid, game)
        except Exception:
            pass

        chat_id = game.get("chat_id")
        message_id = game.get("message_id")

        # Try to edit the original game message so it visually finishes
        try:
            from telegram import InlineKeyboardMarkup as _MNX_KB
            if callable(render_status) and callable(render_board) and notify_send is not None:
                label = ("💰 <b>CASHOUT!</b>"
                         if reason == "manual"
                         else "⏱ <b>AUTO-CASHOUT</b>  (1 min idle)")
                footer = (
                    f"{label}\n"
                    f"Multiplier : <b>x{mult:g}</b>\n"
                    f"Reward : <b>+{reward:,}</b> 💎\n"
                    f"Balance : <b>{new_bal:,}</b> 💎"
                )
                text = render_status(game, footer)
                kb = _MNX_KB(render_board(game, reveal_all=True))
                if chat_id and message_id:
                    try:
                        await notify_send.edit_message_text(
                            chat_id=chat_id,
                            message_id=message_id,
                            text=text,
                            parse_mode="HTML",
                            reply_markup=kb,
                        )
                    except Exception as _e:
                        _mnx_log.warning(f"[mnx] edit game msg failed: {_e}")
        except Exception as _e:
            _mnx_log.warning(f"[mnx] render on cashout failed: {_e}")

        try:
            if callable(clear_game):
                clear_game(uid)
        except Exception:
            pass

        return {
            "ok": True, "reward": reward, "balance": new_bal,
            "mult": mult, "bet": bet, "chat_id": chat_id, "message_id": message_id,
        }
    except Exception as _e:
        _mnx_log.error(f"[mnx] perform_cashout error: {_e}")
        return {"ok": False, "reason": f"error: {_e}"}


# ─── /cashout command  (works for every user, no admin restriction) ────────
async def _mnx_cashout_cmd(update, context):
    """
    /cashout — cash out the caller's active /mines game immediately.
    Works for ALL users (not admin-only).  Also works as a button via the
    existing 💰 Cashout inline button — this command is a redundant path.
    """
    try:
        msg = update.effective_message
        user = update.effective_user
        if not msg or not user:
            return

        # Only the user's OWN active game
        result = await _mnx_perform_cashout(
            user.id, reason="manual", notify_send=context.bot
        )

        if result.get("ok"):
            reward = int(result.get("reward", 0))
            new_bal = int(result.get("balance", 0))
            mult = float(result.get("mult", 1.0))
            await msg.reply_text(
                f"💰 <b>CASHOUT!</b>\n"
                f"Multiplier : <b>x{mult:g}</b>\n"
                f"Reward : <b>+{reward:,}</b> 💎\n"
                f"Balance : <b>{new_bal:,}</b> 💎",
                parse_mode="HTML",
            )
        else:
            r = result.get("reason", "")
            if r == "no_active_game":
                await msg.reply_text("ℹ️ You don't have an active /mines game.")
            elif r == "no_safe_open":
                await msg.reply_text(
                    "⚠️ Open at least one 💎 safe tile first before cashing out."
                )
            else:
                await msg.reply_text("❌ Cashout failed. Try the 💰 button instead.")
    except Exception as _e:
        _mnx_log.error(f"[mnx] /cashout cmd error: {_e}")
        try:
            await update.effective_message.reply_text("❌ Cashout error.")
        except Exception:
            pass


# ─── Background watcher — auto-cashout after 60s idle ──────────────────────
async def _mnx_auto_cashout_watcher(application):
    """Poll all active mines games; auto-cashout those idle > _MNX_IDLE_SECONDS.

    An "action" is: setup (bet confirmed / game start), tile-open, or a wrap
    of _mn_callback (all callback presses touch the timer).  Cashout only
    fires if at least one safe tile has been opened; otherwise we simply
    keep the game alive (nothing to cash out).  Games with zero safe opens
    that idle out are left alone — the user still has to press a tile or
    forfeit; auto-cashout only rewards *progress*.
    """
    _mnx_log.info("[mnx] auto-cashout watcher started ✅")
    while True:
        try:
            await _mnx_asyncio.sleep(_MNX_POLL_SECONDS)

            store_fn = globals().get("_mn_store")
            if not callable(store_fn):
                continue
            store = store_fn() or {}
            if not store:
                continue

            now = _mnx_time.time()

            # Snapshot keys — the store may mutate during iteration
            for uid_str in list(store.keys()):
                try:
                    g = store.get(uid_str)
                    if not isinstance(g, dict):
                        continue
                    if g.get("ended"):
                        continue

                    # If last_action_at not set yet, initialize to 'started_at' or now
                    last = g.get("last_action_at")
                    if not last:
                        # Try to derive from started_at ISO
                        try:
                            iso = g.get("started_at")
                            if iso:
                                dt = _mnx_datetime.fromisoformat(iso)
                                last = dt.timestamp()
                        except Exception:
                            last = None
                    if not last:
                        # Initialize now so we start the clock cleanly
                        g["last_action_at"] = now
                        continue

                    if (now - float(last)) < _MNX_IDLE_SECONDS:
                        continue

                    # Auto-cashout only if user has opened at least one safe tile
                    if len(g.get("opened", []) or []) <= 0:
                        # No progress to cash out — refresh the timer so we
                        # don't hot-loop, but do not touch the game state.
                        continue

                    uid_int = int(g.get("uid") or int(uid_str))
                    result = await _mnx_perform_cashout(
                        uid_int, reason="auto", notify_send=application.bot
                    )
                    if result.get("ok"):
                        reward = int(result.get("reward", 0))
                        new_bal = int(result.get("balance", 0))
                        mult = float(result.get("mult", 1.0))
                        chat_id = result.get("chat_id")
                        try:
                            if chat_id:
                                await application.bot.send_message(
                                    chat_id=chat_id,
                                    text=(
                                        f"⏱ <b>AUTO-CASHOUT</b> — 1 မိနစ်ဖြင့် လှုပ်ရှားမှုမရှိပါ\n"
                                        f"💰 Multiplier : <b>x{mult:g}</b>\n"
                                        f"💎 Reward : <b>+{reward:,}</b>\n"
                                        f"💎 Balance : <b>{new_bal:,}</b>"
                                    ),
                                    parse_mode="HTML",
                                    reply_to_message_id=result.get("message_id"),
                                    allow_sending_without_reply=True,
                                )
                        except Exception as _e:
                            _mnx_log.warning(f"[mnx] auto notice send failed: {_e}")
                except Exception as _e:
                    _mnx_log.warning(f"[mnx] watcher inner err on {uid_str}: {_e}")
                    continue
        except _mnx_asyncio.CancelledError:
            _mnx_log.info("[mnx] auto-cashout watcher cancelled")
            return
        except Exception as _e:
            _mnx_log.error(f"[mnx] watcher outer err: {_e}")
            # Keep looping — never let this task die


# ─── Register /cashout + start watcher via Application.__init__ patch ──────
# Track apps that already have addon installed (Application uses __slots__)
_MNX_APP_REGISTRY = set()


def _mnx_is_registered(application) -> bool:
    try:
        return id(application) in _MNX_APP_REGISTRY
    except Exception:
        return False


def _mnx_mark_registered(application) -> None:
    try:
        _MNX_APP_REGISTRY.add(id(application))
    except Exception:
        pass


def _mnx_register_on_app(application):
    try:
        if _mnx_is_registered(application):
            return

        from telegram.ext import CommandHandler as _MNX_CH

        # /cashout — available to ALL users
        application.add_handler(_MNX_CH("cashout", _mnx_cashout_cmd))

        # Kick off the auto-cashout background task once the app is running,
        # and make sure /upload + /uploadvd are still installed at that point.
        async def _mnx_post_init(app):
            try:
                # Ensure upload/uploadvd are present AFTER main() has finished
                # adding its own handlers — this is the reliable moment.
                try:
                    _mnx_ensure_upload_handlers(app)
                except Exception as _e:
                    _mnx_log.warning(f"[mnx] ensure_upload_handlers err: {_e}")

                # Start (or re-start) the auto-cashout watcher exactly once
                task = getattr(app, "_mnx_task_ref", None)
                if task and not task.done():
                    return
                new_task = _mnx_asyncio.create_task(
                    _mnx_auto_cashout_watcher(app)
                )
                try:
                    app._mnx_task_ref = new_task  # type: ignore[attr-defined]
                except Exception:
                    # Application uses __slots__ on some versions — store
                    # the task in the module registry instead.
                    _MNX_APP_REGISTRY.add((id(app), "task", new_task))
                _mnx_log.info("[mnx] watcher task scheduled")
            except Exception as _e:
                _mnx_log.error(f"[mnx] post_init schedule failed: {_e}")

        # Chain onto any existing post_init handler if the API allows it
        try:
            existing = application.post_init
        except Exception:
            existing = None

        async def _mnx_chained_post_init(app):
            try:
                if callable(existing):
                    try:
                        await existing(app)
                    except Exception as _e:
                        _mnx_log.warning(f"[mnx] prior post_init err: {_e}")
            except Exception:
                pass
            await _mnx_post_init(app)

        installed_post_init = False
        try:
            application.post_init = _mnx_chained_post_init  # type: ignore[assignment]
            installed_post_init = True
        except Exception:
            pass

        # Fallback path: if post_init is read-only (PTB slots), hook into
        # run_polling / run_webhook instead so we still get a chance to
        # start the watcher and re-verify upload handlers.
        if not installed_post_init:
            try:
                for _mname in ("run_polling", "run_webhook"):
                    _orig = getattr(application, _mname, None)
                    if not callable(_orig):
                        continue

                    def _wrap(orig_fn, mname):
                        def _mnx_runner(*a, **k):
                            # Schedule a one-shot job through the JobQueue
                            # once the event loop is running.
                            try:
                                jq = application.job_queue
                                if jq is not None:
                                    async def _mnx_kickoff(ctx):
                                        await _mnx_post_init(application)
                                    jq.run_once(_mnx_kickoff, when=1)
                            except Exception as _e:
                                _mnx_log.warning(f"[mnx] jobqueue kickoff err: {_e}")
                            return orig_fn(*a, **k)
                        return _mnx_runner

                    try:
                        setattr(application, _mname, _wrap(_orig, _mname))
                    except Exception:
                        pass
            except Exception as _e:
                _mnx_log.warning(f"[mnx] fallback hook err: {_e}")

        _mnx_mark_registered(application)
        _mnx_log.info("[mnx] /cashout registered ✅")

    except Exception as _e:
        _mnx_log.error(f"[mnx] register on app failed: {_e}")


# ─── Upload / Uploadvd resilience — re-register if missing ─────────────────
def _mnx_ensure_upload_handlers(application):
    """
    Make sure /upload and /uploadvd ConversationHandlers are still installed.
    If the original main() failed to attach them (or something else stripped
    them from the handler table), rebuild and add them here.  Idempotent —
    safe to run multiple times.
    """
    try:
        from telegram.ext import (
            ConversationHandler as _MNX_Conv,
            CommandHandler as _MNX_CH,
            MessageHandler as _MNX_MH,
            CallbackQueryHandler as _MNX_CBH,
            filters as _mnx_filters,
        )

        # Check whether /upload and /uploadvd are currently registered
        has_upload = False
        has_uploadvd = False
        try:
            for _grp, _list in (application.handlers or {}).items():
                for h in _list:
                    try:
                        # ConversationHandler exposes entry_points
                        entries = getattr(h, "entry_points", None) or []
                        for ep in entries:
                            cmds = set(getattr(ep, "commands", set()) or set())
                            if "upload" in cmds:
                                has_upload = True
                            if "uploadvd" in cmds:
                                has_uploadvd = True
                        # Plain CommandHandler
                        cmds = set(getattr(h, "commands", set()) or set())
                        if "upload" in cmds:
                            has_upload = True
                        if "uploadvd" in cmds:
                            has_uploadvd = True
                    except Exception:
                        continue
        except Exception:
            pass

        # Pull the existing functions from the original bot
        upload_start = globals().get("upload_start")
        upload_image = globals().get("upload_image")
        upload_name = globals().get("upload_name")
        upload_movie = globals().get("upload_movie")
        upload_rarity_callback = globals().get("upload_rarity_callback")
        upload_role_callback = globals().get("upload_role_callback")
        owner_start = globals().get("owner_start")
        owner_video = globals().get("owner_video")
        owner_name = globals().get("owner_name")
        owner_movie = globals().get("owner_movie")
        owner_role_callback = globals().get("owner_role_callback")
        owner_cancel = globals().get("owner_cancel")

        UPLOAD_IMAGE = globals().get("UPLOAD_IMAGE")
        UPLOAD_NAME = globals().get("UPLOAD_NAME")
        UPLOAD_MOVIE = globals().get("UPLOAD_MOVIE")
        UPLOAD_RARITY = globals().get("UPLOAD_RARITY")
        UPLOAD_ROLE = globals().get("UPLOAD_ROLE")
        OWNER_VIDEO = globals().get("OWNER_VIDEO")
        OWNER_NAME = globals().get("OWNER_NAME")
        OWNER_MOVIE = globals().get("OWNER_MOVIE")
        OWNER_ROLE = globals().get("OWNER_ROLE")

        if not has_upload and callable(upload_start) and UPLOAD_IMAGE is not None:
            try:
                conv = _MNX_Conv(
                    entry_points=[_MNX_CH("upload", upload_start)],
                    states={
                        UPLOAD_IMAGE: [_MNX_MH(_mnx_filters.PHOTO, upload_image)],
                        UPLOAD_NAME: [_MNX_MH(_mnx_filters.TEXT & ~_mnx_filters.COMMAND, upload_name)],
                        UPLOAD_MOVIE: [_MNX_MH(_mnx_filters.TEXT & ~_mnx_filters.COMMAND, upload_movie)],
                        UPLOAD_RARITY: [_MNX_CBH(upload_rarity_callback, pattern='^rarity_')],
                        UPLOAD_ROLE: [_MNX_CBH(upload_role_callback, pattern='^uprole_')],
                    },
                    fallbacks=[_MNX_CH("cancel", owner_cancel)] if callable(owner_cancel) else [],
                    name="mnx_upload_conv",
                    persistent=False,
                )
                application.add_handler(conv)
                _mnx_log.info("[mnx] /upload re-registered ✅")
            except Exception as _e:
                _mnx_log.error(f"[mnx] re-register /upload failed: {_e}")

        if not has_uploadvd and callable(owner_start) and OWNER_VIDEO is not None:
            try:
                conv = _MNX_Conv(
                    entry_points=[_MNX_CH("uploadvd", owner_start)],
                    states={
                        OWNER_VIDEO: [_MNX_MH(_mnx_filters.VIDEO | _mnx_filters.Document.ALL, owner_video)],
                        OWNER_NAME: [_MNX_MH(_mnx_filters.TEXT & ~_mnx_filters.COMMAND, owner_name)],
                        OWNER_MOVIE: [_MNX_MH(_mnx_filters.TEXT & ~_mnx_filters.COMMAND, owner_movie)],
                        OWNER_ROLE: [_MNX_CBH(owner_role_callback, pattern='^vrole_')],
                    },
                    fallbacks=[_MNX_CH("cancel", owner_cancel)] if callable(owner_cancel) else [],
                    name="mnx_uploadvd_conv",
                    persistent=False,
                )
                application.add_handler(conv)
                _mnx_log.info("[mnx] /uploadvd re-registered ✅")
            except Exception as _e:
                _mnx_log.error(f"[mnx] re-register /uploadvd failed: {_e}")

    except Exception as _e:
        _mnx_log.error(f"[mnx] ensure_upload_handlers failed: {_e}")


# ─── Install onto Application.__init__ (same pattern as the ook module) ────
def _mnx_install_app_hook():
    try:
        from telegram.ext import Application as _MnxApp
        orig_init = _MnxApp.__init__
        if getattr(orig_init, "_mnx_wrapped", False):
            return

        def patched_init(self, *args, **kwargs):
            orig_init(self, *args, **kwargs)
            try:
                _mnx_register_on_app(self)
            except Exception as _e:
                _mnx_log.error(f"[mnx] register-on-init failed: {_e}")

        patched_init._mnx_wrapped = True  # type: ignore[attr-defined]
        _MnxApp.__init__ = patched_init  # type: ignore[assignment]
        _mnx_log.info("[mnx] Application.__init__ hook installed ✅")
    except Exception as _e:
        _mnx_log.error(f"[mnx] install_app_hook failed: {_e}")


try:
    _mnx_install_app_hook()
except Exception as _mnx_e:
    _mnx_log.error(f"[mnx] top-level install failed: {_mnx_e}")


# ═══════════════════════════════════════════════════════════════════════════════
#  END  MINES CASHOUT + AUTO-CASHOUT + UPLOAD FIX ADDON
