# ═══════════════════════════════════════════════════════════════════════════════
#  ADMIN ECONOMY & SHOP CONTROL ADDON
#  ---------------------------------------------------------------------------
#  Adds three OWNER/ADMIN-only commands (sidecar module — original file
#  untouched; only appended once at the end, right before `if __name__ ==
#  '__main__'`).  All new state is stored inside the existing
#  gold_data / bot.data / bot.settings JSON files so BACKUP_FILES continues
#  to protect it automatically.
#
#   1. /deldiamond   →  Subtract a PERCENTAGE of a user's 💎 Diamonds
#      Usage:
#         /deldiamond <percent>                 (reply to the user)
#         /deldiamond <user_id> <percent>
#         /deldiamond @username  <percent>
#
#   2. /delgold      →  Subtract a PERCENTAGE of a user's 🪙 Gold
#      Usage: same as /deldiamond
#
#   3. /closeshop    →  Close a whole Rarity so it CANNOT be bought
#         • Locks it inside `bot.settings['locked_rarities']`
#         • /buy   already respects that list — will refuse
#         • /blackmarketshop  and  /blackmarket <id>  will ALSO refuse when
#           Immortal (rarity 14) is closed  (patched here)
#      Usage:
#         /closeshop  <rarity_number|rarity_name>
#         /closeshop  list          (see currently closed rarities)
#         /closeshop  open <r>      (re-open a rarity)
#
#  Note:  These three commands are OWNER-ONLY by default (per the user's
#         brief:  "မူရင်း file မပျက်စေပဲ owner နဲ့ admin တွေပဲ သုံးလို့ရမယ်").
#         Real admins added to `bot.settings['admins']` are also allowed.
# ═══════════════════════════════════════════════════════════════════════════════

import logging as _sc_logging

try:
    from telegram import Update as _SC_Update  # type: ignore
    from telegram.ext import (
        CommandHandler as _SC_CmdH,
        ContextTypes    as _SC_Ctx,
        Application     as _SC_App,
    )
except Exception:  # pragma: no cover
    _SC_Update = None  # type: ignore
    _SC_CmdH   = None  # type: ignore
    _SC_Ctx    = None  # type: ignore
    _SC_App    = None  # type: ignore


def _sc_log():
    try:
        return logger  # type: ignore[name-defined]
    except Exception:
        return _sc_logging.getLogger("admin_econ_shop")


def _sc_bot():
    try:
        return bot  # type: ignore[name-defined]
    except Exception:
        return None


# ── Permission helper ──────────────────────────────────────────────────────
def _sc_is_permitted(user_id) -> bool:
    """Owner OR real admin (excluding sudo/dev unless they're also admins)."""
    b = _sc_bot()
    if not b:
        return False
    try:
        if hasattr(b, "is_owner") and b.is_owner(user_id):
            return True
    except Exception:
        pass
    try:
        admins = b.settings.get("admins", []) or []
        return int(user_id) in [int(x) for x in admins]
    except Exception:
        return False


# ── Argument helpers ───────────────────────────────────────────────────────
def _sc_parse_percent(raw) -> float | None:
    """Accept things like  50, 50%, 12.5, 12.5%.  Clamp to (0, 100]."""
    if raw is None:
        return None
    s = str(raw).strip().rstrip("%").replace(",", "").strip()
    if not s:
        return None
    try:
        p = float(s)
    except Exception:
        return None
    if p <= 0 or p > 100:
        return None
    return p


async def _sc_resolve_target(update, context):
    """
    Resolve target user for /deldiamond and /delgold.
    Returns (target_id:int|None, target_name:str|None, remaining_args:list).
    Supports:
      • Reply to user
      • Numeric telegram id
      • @username
    """
    msg = getattr(update, "message", None)
    args = list(getattr(context, "args", []) or [])

    # 1) Reply mode
    try:
        if msg and msg.reply_to_message and msg.reply_to_message.from_user \
                and not msg.reply_to_message.from_user.is_bot:
            ru = msg.reply_to_message.from_user
            name = ru.first_name or ru.username or str(ru.id)
            return int(ru.id), name, args
    except Exception:
        pass

    # 2/3) argument-based
    if not args:
        return None, None, args

    first = str(args[0]).strip().lstrip("@")
    remaining = args[1:]

    if first.isdigit():
        try:
            tid = int(first)
            try:
                cache = USER_CACHE  # type: ignore[name-defined]
                name = cache.get(str(tid)) or f"User {tid}"
            except Exception:
                name = f"User {tid}"
            return tid, name, remaining
        except Exception:
            return None, None, remaining

    # Try @username via Telegram API
    try:
        chat = await context.bot.get_chat("@" + first)
        return int(chat.id), (chat.first_name or first), remaining
    except Exception:
        return None, None, remaining


def _sc_fmt(n) -> str:
    try:
        return f"{int(n):,}"
    except Exception:
        return str(n)


# ═══════════════════════════════════════════════════════════════════════════
#  /deldiamond   —  subtract PERCENT of user's diamonds (kakera)
# ═══════════════════════════════════════════════════════════════════════════
async def _sc_deldiamond_cmd(update, context):
    msg = getattr(update, "message", None)
    user = getattr(update, "effective_user", None)
    if msg is None or user is None:
        return

    if not _sc_is_permitted(user.id):
        try:
            await msg.reply_text("❌ Owner/Admin only.")
        except Exception:
            pass
        return

    target_id, target_name, remaining = await _sc_resolve_target(update, context)
    if target_id is None:
        await msg.reply_text(
            "📝 <b>Usage</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "<code>/deldiamond &lt;percent&gt;</code>   (reply)\n"
            "<code>/deldiamond &lt;user_id&gt; &lt;percent&gt;</code>\n"
            "<code>/deldiamond @username &lt;percent&gt;</code>\n"
            "💡 percent must be between 1 and 100.",
            parse_mode="HTML",
        )
        return

    # In reply mode, percent is args[0]; in arg-mode it's remaining[0].
    percent_raw = None
    try:
        args = list(getattr(context, "args", []) or [])
        # Reply mode → all args are percent-related; use args[0]
        if msg.reply_to_message and msg.reply_to_message.from_user \
                and not msg.reply_to_message.from_user.is_bot:
            percent_raw = args[0] if args else None
        else:
            percent_raw = remaining[0] if remaining else None
    except Exception:
        percent_raw = None

    percent = _sc_parse_percent(percent_raw)
    if percent is None:
        await msg.reply_text(
            "❌ Invalid percent.\n"
            "📝 Example: <code>/deldiamond 50</code>  (removes 50%)",
            parse_mode="HTML",
        )
        return

    b = _sc_bot()
    if not b:
        await msg.reply_text("⚠️ Bot data not initialised.")
        return

    # Ensure user structure exists
    try:
        fn = globals().get("_im_init_user") or globals().get("init_user_if_not_exists")
        if callable(fn):
            fn(str(target_id))
    except Exception:
        pass

    prof = b.data.setdefault("user_profiles", {}).setdefault(str(target_id), {})
    old_bal = int(prof.get("kakera", 0) or 0)

    if old_bal <= 0:
        await msg.reply_text(
            "❌ Target user has no diamonds to deduct.\n"
            f"👤 <code>{target_id}</code>",
            parse_mode="HTML",
        )
        return

    deduct = int(old_bal * (percent / 100.0))
    if deduct < 1:
        deduct = 1  # remove at least 1 so the action is not a no-op
    if deduct > old_bal:
        deduct = old_bal

    new_bal = old_bal - deduct
    prof["kakera"] = new_bal
    try:
        b.save_data()
    except Exception:
        pass

    _sc_log().info(
        f"[deldiamond] admin={user.id} target={target_id} "
        f"pct={percent} deducted={deduct} old={old_bal} new={new_bal}"
    )

    await msg.reply_text(
        "✅ <b>Diamonds deducted</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👤 {target_name}\n"
        f"🆔 <code>{target_id}</code>\n"
        f"📉 -{percent:g}%  →  -<code>{_sc_fmt(deduct)}</code> 💎\n"
        f"💰 Before : <code>{_sc_fmt(old_bal)}</code>\n"
        f"💰 After  : <code>{_sc_fmt(new_bal)}</code>",
        parse_mode="HTML",
    )


# ═══════════════════════════════════════════════════════════════════════════
#  /delgold   —  subtract PERCENT of user's gold
# ═══════════════════════════════════════════════════════════════════════════
async def _sc_delgold_cmd(update, context):
    msg = getattr(update, "message", None)
    user = getattr(update, "effective_user", None)
    if msg is None or user is None:
        return

    if not _sc_is_permitted(user.id):
        try:
            await msg.reply_text("❌ Owner/Admin only.")
        except Exception:
            pass
        return

    target_id, target_name, remaining = await _sc_resolve_target(update, context)
    if target_id is None:
        await msg.reply_text(
            "📝 <b>Usage</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "<code>/delgold &lt;percent&gt;</code>   (reply)\n"
            "<code>/delgold &lt;user_id&gt; &lt;percent&gt;</code>\n"
            "<code>/delgold @username &lt;percent&gt;</code>\n"
            "💡 percent must be between 1 and 100.",
            parse_mode="HTML",
        )
        return

    percent_raw = None
    try:
        args = list(getattr(context, "args", []) or [])
        if msg.reply_to_message and msg.reply_to_message.from_user \
                and not msg.reply_to_message.from_user.is_bot:
            percent_raw = args[0] if args else None
        else:
            percent_raw = remaining[0] if remaining else None
    except Exception:
        percent_raw = None

    percent = _sc_parse_percent(percent_raw)
    if percent is None:
        await msg.reply_text(
            "❌ Invalid percent.\n"
            "📝 Example: <code>/delgold 25</code>",
            parse_mode="HTML",
        )
        return

    # gold_data is a top-level dict in the original file
    try:
        gd = gold_data  # type: ignore[name-defined]
    except Exception:
        gd = None
    if gd is None:
        await msg.reply_text("⚠️ Gold system not available.")
        return

    # Ensure key exists
    try:
        _ensure_fn = globals().get("_ensure_gold")
        if callable(_ensure_fn):
            _ensure_fn(str(target_id))
        else:
            gd.setdefault(str(target_id), 0)
    except Exception:
        gd.setdefault(str(target_id), 0)

    old_bal = int(gd.get(str(target_id), 0) or 0)
    if old_bal <= 0:
        await msg.reply_text(
            "❌ Target user has no gold to deduct.\n"
            f"👤 <code>{target_id}</code>",
            parse_mode="HTML",
        )
        return

    deduct = int(old_bal * (percent / 100.0))
    if deduct < 1:
        deduct = 1
    if deduct > old_bal:
        deduct = old_bal

    new_bal = old_bal - deduct
    gd[str(target_id)] = new_bal

    try:
        save_fn = globals().get("save_gold")
        if callable(save_fn):
            save_fn()
    except Exception:
        pass

    _sc_log().info(
        f"[delgold] admin={user.id} target={target_id} "
        f"pct={percent} deducted={deduct} old={old_bal} new={new_bal}"
    )

    await msg.reply_text(
        "✅ <b>Gold deducted</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👤 {target_name}\n"
        f"🆔 <code>{target_id}</code>\n"
        f"📉 -{percent:g}%  →  -<code>{_sc_fmt(deduct)}</code> 🪙\n"
        f"💰 Before : <code>{_sc_fmt(old_bal)}</code>\n"
        f"💰 After  : <code>{_sc_fmt(new_bal)}</code>",
        parse_mode="HTML",
    )


# ═══════════════════════════════════════════════════════════════════════════
#  /closeshop   —  lock a whole Rarity so it cannot be bought
# ═══════════════════════════════════════════════════════════════════════════
def _sc_resolve_rarity_arg(arg) -> str | None:
    """Accept rarity number ('3') OR name ('Rare', 'immortal', ...).
    Returns the string key ('1'..'16') or None."""
    if arg is None:
        return None
    s = str(arg).strip().lower()
    if not s:
        return None
    try:
        rarities = RARITIES  # type: ignore[name-defined]
    except Exception:
        return None

    # Direct numeric key
    if s in rarities:
        return s
    # Numeric that starts with 0?
    if s.isdigit():
        s2 = str(int(s))
        if s2 in rarities:
            return s2

    # Match by name (case-insensitive), ignore spaces/underscores
    def _norm(x):
        return "".join(ch for ch in str(x).lower() if ch.isalnum())

    target = _norm(s)
    for k, info in rarities.items():
        if _norm(info.get("name", "")) == target:
            return str(k)
        if _norm(info.get("display", "")) == target:
            return str(k)
    return None


def _sc_rarity_display(key: str) -> str:
    try:
        info = RARITIES.get(key, {})  # type: ignore[name-defined]
        return info.get("display", f"Rarity {key}")
    except Exception:
        return f"Rarity {key}"


async def _sc_closeshop_cmd(update, context):
    msg = getattr(update, "message", None)
    user = getattr(update, "effective_user", None)
    if msg is None or user is None:
        return

    if not _sc_is_permitted(user.id):
        try:
            await msg.reply_text("❌ Owner/Admin only.")
        except Exception:
            pass
        return

    b = _sc_bot()
    if not b:
        await msg.reply_text("⚠️ Bot data not initialised.")
        return

    args = list(getattr(context, "args", []) or [])
    # /closeshop uses a BUY-ONLY blocklist so drops / guessing / fusion /
    # anything else still works normally on that rarity. The legacy
    # 'locked_rarities' drop-blocklist is still applied for /lockrd logic.
    locked = b.settings.setdefault("buy_blocked_rarities", [])
    # Backward-compat migration for users upgrading from the older version
    # that conflated shop-close with drop-lock:
    legacy = b.settings.get("locked_rarities") or []
    if legacy and not locked:
        # The old setting blocked drops too; honour that for any entry
        # already in 'locked_rarities' so existing operators don't have a
        # surprise unlock.
        try:
            locked.extend([str(r) for r in legacy if str(r) not in locked])
        except Exception:
            pass

    # No args → show usage AND current status
    if not args:
        if locked:
            lines = ["🔒 <b>Currently closed rarities</b>",
                     "━━━━━━━━━━━━━━━━━━"]
            for r in locked:
                lines.append(f"• <code>{r}</code>  {_sc_rarity_display(str(r))}")
            lines.append("")
        else:
            lines = ["✅ No rarities are currently closed.", ""]
        lines += [
            "📝 <b>Usage</b>",
            "━━━━━━━━━━━━━━━━━━",
            "<code>/closeshop &lt;rarity_number|name&gt;</code>",
            "<code>/closeshop open &lt;rarity&gt;</code>   — re-open",
            "<code>/closeshop list</code>                — show closed",
            "",
            "🧾 Closing a rarity blocks it from",
            "   • /buy   (normal shop)",
            "   • /blackmarket & /blackmarketshop  (Immortal only)",
        ]
        await msg.reply_text("\n".join(lines), parse_mode="HTML")
        return

    sub = str(args[0]).strip().lower()

    # /closeshop list
    if sub in ("list", "ls", "show", "status"):
        if not locked:
            await msg.reply_text("✅ No rarities are currently closed.")
            return
        lines = ["🔒 <b>Currently closed rarities</b>",
                 "━━━━━━━━━━━━━━━━━━"]
        for r in locked:
            lines.append(f"• <code>{r}</code>  {_sc_rarity_display(str(r))}")
        await msg.reply_text("\n".join(lines), parse_mode="HTML")
        return

    # /closeshop open <rarity>
    if sub in ("open", "unlock", "reopen"):
        if len(args) < 2:
            await msg.reply_text(
                "📝 <code>/closeshop open &lt;rarity_number|name&gt;</code>",
                parse_mode="HTML",
            )
            return
        rk = _sc_resolve_rarity_arg(args[1])
        if not rk:
            await msg.reply_text(f"❌ Unknown rarity: <code>{args[1]}</code>", parse_mode="HTML")
            return
        if rk in locked:
            locked.remove(rk)
            try:
                b.save_settings()
            except Exception:
                pass
            _sc_log().info(f"[closeshop] admin={user.id} REOPENED rarity={rk}")
            await msg.reply_text(
                f"🔓 <b>Reopened</b>\n"
                f"━━━━━━━━━━━━━━━━━━\n"
                f"{_sc_rarity_display(rk)}  (id <code>{rk}</code>) can now be purchased again.",
                parse_mode="HTML",
            )
        else:
            await msg.reply_text(
                f"✅ {_sc_rarity_display(rk)} is not closed — nothing to do.",
                parse_mode="HTML",
            )
        return

    # /closeshop <rarity_number|name>
    rk = _sc_resolve_rarity_arg(args[0])
    if not rk:
        await msg.reply_text(
            f"❌ Unknown rarity: <code>{args[0]}</code>\n"
            "💡 Use the rarity number (1-16) or its name (e.g. Immortal).",
            parse_mode="HTML",
        )
        return

    if rk in locked:
        await msg.reply_text(
            f"ℹ️ {_sc_rarity_display(rk)} is already closed.\n"
            f"🔓 Re-open with <code>/closeshop open {rk}</code>",
            parse_mode="HTML",
        )
        return

    locked.append(rk)
    try:
        b.save_settings()
    except Exception:
        pass
    _sc_log().info(f"[closeshop] admin={user.id} CLOSED rarity={rk}")

    extra = ""
    if rk == "14":
        extra = "\n🏴‍☠️ The Black Market (/blackmarketshop) will also refuse this rarity."

    await msg.reply_text(
        f"🔒 <b>Rarity closed</b>\n"
        f"━━━━━━━━━━━━━━━━━━\n"
        f"{_sc_rarity_display(rk)}  (id <code>{rk}</code>)\n"
        f"❌ Cannot be bought via <code>/buy</code>.{extra}\n"
        f"🔓 Re-open with <code>/closeshop open {rk}</code>",
        parse_mode="HTML",
    )


# ═══════════════════════════════════════════════════════════════════════════
#  Black-market patch — make it respect /closeshop for Immortal cards
#  ---------------------------------------------------------------------
#  We wrap the existing coroutine `_im_perform_purchase` (defined earlier
#  in this file).  When rarity '14' is in locked_rarities, purchase is
#  blocked at both the /blackmarket <id> path and the inline Buy button.
#  We ALSO gate `/blackmarketshop` itself so that closed shop shows a
#  clear notice.
# ═══════════════════════════════════════════════════════════════════════════
def _sc_is_rarity_closed(rk: str) -> bool:
    """A rarity is considered 'closed' if EITHER:
       • it's in the legacy 'locked_rarities' list (set via /lockrd —
         blocks BOTH buys and drops), or
       • it's in 'buy_blocked_rarities' (set via /closeshop — blocks
         buys only, drops still work normally).
    """
    b = _sc_bot()
    if not b:
        return False
    try:
        legacy = b.settings.get("locked_rarities", []) or []
        buy_only = b.settings.get("buy_blocked_rarities", []) or []
        all_closed = [str(x) for x in legacy] + [str(x) for x in buy_only]
        return str(rk) in all_closed
    except Exception:
        return False


def _sc_patch_blackmarket_once():
    """Idempotent wrapper around _im_perform_purchase and _im_blackmarketshop_cmd."""
    g = globals()
    if g.get("_SC_BM_PATCHED"):
        return

    orig_purchase = g.get("_im_perform_purchase")
    if callable(orig_purchase):
        async def _wrapped_perform_purchase(update, context, uid, card_id, via_callback):
            # Refuse when Immortal rarity has been closed by owner/admin
            if _sc_is_rarity_closed("14"):
                msg = getattr(update, "message", None)
                cb = getattr(update, "callback_query", None)
                text = (
                    "🔒 <b>Black Market is closed</b>\n"
                    "━━━━━━━━━━━━━━━━━━━━\n"
                    "🪞 Immortal purchases have been disabled by admin.\n"
                    "⏳ Try again later."
                )
                try:
                    if via_callback and cb is not None:
                        await cb.answer("Black Market closed", show_alert=True)
                        try:
                            await cb.message.reply_text(text, parse_mode="HTML")
                        except Exception:
                            pass
                    elif msg is not None:
                        await msg.reply_text(text, parse_mode="HTML")
                except Exception:
                    pass
                return
            return await orig_purchase(update, context, uid, card_id, via_callback)

        g["_im_perform_purchase"] = _wrapped_perform_purchase

    orig_shop = g.get("_im_blackmarketshop_cmd")
    if callable(orig_shop):
        async def _wrapped_blackmarketshop(update, context):
            if _sc_is_rarity_closed("14"):
                msg = getattr(update, "message", None)
                if msg is not None:
                    try:
                        await msg.reply_text(
                            "🔒 <b>Black Market is closed</b>\n"
                            "━━━━━━━━━━━━━━━━━━━━\n"
                            "🪞 Immortal shop has been disabled by admin.\n"
                            "⏳ Please try again later.",
                            parse_mode="HTML",
                        )
                    except Exception:
                        pass
                return
            return await orig_shop(update, context)

        g["_im_blackmarketshop_cmd"] = _wrapped_blackmarketshop

    g["_SC_BM_PATCHED"] = True
    _sc_log().info("[admin_econ_shop] black-market /closeshop gate installed ✅")


# ═══════════════════════════════════════════════════════════════════════════
#  Handler registration — same idempotent Application.__init__ pattern the
#  rest of this file uses.
# ═══════════════════════════════════════════════════════════════════════════
_SC_REGISTERED_APPS: set[int] = set()


def _sc_register_handlers(application) -> None:
    if application is None or _SC_CmdH is None:
        return
    try:
        _app_key = id(application)
    except Exception:
        _app_key = None
    if _app_key is not None and _app_key in _SC_REGISTERED_APPS:
        return
    if _app_key is not None:
        _SC_REGISTERED_APPS.add(_app_key)

    try:
        application.add_handler(_SC_CmdH("deldiamond", _sc_deldiamond_cmd), group=-3)
        application.add_handler(_SC_CmdH("delgold",    _sc_delgold_cmd),    group=-3)
        application.add_handler(_SC_CmdH("closeshop",  _sc_closeshop_cmd),  group=-3)
        _sc_log().info(
            "[admin_econ_shop] ✅ /deldiamond /delgold /closeshop registered"
        )
    except Exception as e:
        _sc_log().error(f"[admin_econ_shop] register failed: {e}")

    # Patch black-market once handlers are wired in.
    try:
        _sc_patch_blackmarket_once()
    except Exception as e:
        _sc_log().error(f"[admin_econ_shop] blackmarket patch failed: {e}")


def _sc_install_app_hook():
    if _SC_App is None:
        return
    g = globals()
    if g.get("_SC_APP_HOOK_INSTALLED"):
        return
    try:
        orig_init = _SC_App.__init__
    except Exception:
        return
    if getattr(orig_init, "_sc_wrapped", False):
        return

    def patched_init(self, *args, **kwargs):
        orig_init(self, *args, **kwargs)
        try:
            _sc_register_handlers(self)
        except Exception as _e:
            _sc_log().error(f"[admin_econ_shop] register-on-init failed: {_e}")

    patched_init._sc_wrapped = True  # type: ignore[attr-defined]
    try:
        _SC_App.__init__ = patched_init  # type: ignore[assignment]
        g["_SC_APP_HOOK_INSTALLED"] = True
        _sc_log().info("[admin_econ_shop] Application.__init__ hook installed ✅")
    except Exception as e:
        _sc_log().error(f"[admin_econ_shop] App.__init__ patch failed: {e}")


try:
    _sc_install_app_hook()
except Exception as _sc_e:
    try:
        _sc_log().error(f"[admin_econ_shop] top-level install failed: {_sc_e}")
    except Exception:
        pass

# ═══════════════════════════════════════════════════════════════════════════════
#  END  ADMIN ECONOMY & SHOP CONTROL ADDON
