# ════════════════════════════════════════════════════════════════════════════
#  RARITY-PATCH: /rarity command + /uploadvd rewrite + /see alpha-id support
#  • Inserts immediately before the entry point. Reads RARITIES / ROLES
#    from this file's globals. Hooks Application.__init__ so the handlers
#    are installed automatically when the bot boots.
#  • No existing command, function, or data structure was modified.
# ════════════════════════════════════════════════════════════════════════════

"""Patch: Add /rarity command and /uploadvd character step.

Inserted as an end-of-file module so it latches onto the existing bot
Data (bot.data['cards'], RARITIES, ROLES, styles). No existing handlers
are touched — the new handlers are registered in a guarded post_install()
that runs after main() has installed the application.
"""

import logging
from datetime import datetime

from telegram import (
    InlineKeyboardButton,
    InlineKeyboardMarkup,
    Update,
)
from telegram.ext import (
    CommandHandler,
    ConversationHandler,
    MessageHandler,
    CallbackQueryHandler,
    ContextTypes,
    filters,
)

logger = logging.getLogger(__name__)


# ============================================================================
#                      /rarity  COMMAND  (NEW)
# ============================================================================
# Goals:
#   • All emojis / names / ordering come from the existing RARITIES dict
#     (so adding rarity '17' automatically works without touching this code).
#   • Only counts the MAIN card database (bot.data['cards']) — never user
#     inventories.
#   • Live update: every new card added to bot.data['cards'] shows up
#     immediately because we query the dict every invocation.
#   • Highest → lowest order. Premium 3D-style banner.
# ============================================================================

# Conversation states for the rewritten /uploadvd flow
UPLOADVD_MEDIA, UPLOADVD_MOVIE, UPLOADVD_CHAR, UPLOADVD_RARITY, UPLOADVD_ROLE = range(510, 515)


def _rarity_emoji(rarity_key: str) -> str:
    info = RARITIES.get(str(rarity_key), {})
    return info.get('emoji') or '🎴'


def _rarity_name(rarity_key: str) -> str:
    info = RARITIES.get(str(rarity_key), {})
    return info.get('name') or f"Rarity {rarity_key}"


def _rarity_display(rarity_key: str) -> str:
    info = RARITIES.get(str(rarity_key), {})
    return info.get('display') or _rarity_emoji(rarity_key) + " " + _rarity_name(rarity_key)


async def rarity_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/rarity — Show how many cards exist in main DB per rarity (highest→lowest)."""
    cards = bot.data.get('cards', {}) if hasattr(bot, 'data') else {}
    counts: dict[str, int] = {}
    for cid, c in cards.items():
        if not c:
            continue
        r = str(c.get('rarity', '1'))
        counts[r] = counts.get(r, 0) + 1

    # Order by numeric rarity asc, then display highest→lowest
    present_keys = sorted(counts.keys(), key=lambda x: int(x) if str(x).isdigit() else 0)
    present_keys.reverse()

    lines = []
    lines.append("╔══════════════════════════╗")
    lines.append("        📊 RARITY STATISTICS")
    lines.append("╚══════════════════════════╝")
    lines.append("")

    if not present_keys:
        lines.append("❌ Database ထဲမှာ card မရှိသေးပါ။")
    else:
        for rk in present_keys:
            emoji = _rarity_emoji(rk)
            name = _rarity_name(rk)
            cnt = counts[rk]
            lines.append(f"{emoji} {name}")
            lines.append(f"  └ 🎴 Cards: {cnt}")
            lines.append("")

    total = sum(counts.values())
    lines.append("━━━━━━━━━━━━━━━━━━━")
    lines.append(f"📈 Total Cards: {total}")

    text = "\n".join(lines)
    try:
        await update.message.reply_text(text, parse_mode=None)
    except Exception as e:
        logger.error(f"/rarity send failed: {e}")
        try:
            await update.message.reply_text(text)
        except Exception:
            pass


# ============================================================================
#          /uploadvd  REWORK  (MEDIA → MOVIE → CHARACTER → RARITY → ROLE)
# ============================================================================
# New behavior:
#   1. Admin/Owner sends /uploadvd
#   2. Bot asks for photo or video
#   3. Bot asks for MOVIE — previous movie names are shown as inline buttons.
#      Tapping a button = re-use. No match = enter new movie as free text.
#   4. Bot asks for CHARACTER — previous character names for the chosen
#      movie are shown as inline buttons. Tapping = re-use. No match = new.
#   5. Rarity chosen via inline keyboard (built from RARITIES dict).
#   6. Role chosen via inline keyboard (built from ROLES dict, with skip).
#   7. Card is saved to bot.data['cards'] and broadcast to database channel.
# ============================================================================

def _uploadvd_get_existing_movies() -> list[str]:
    """Return distinct movie names currently in the card DB (newest first)."""
    cards = bot.data.get('cards', {}) if hasattr(bot, 'data') else {}
    seen: dict[str, None] = {}
    out: list[str] = []
    for cid in reversed(list(cards.keys())):
        c = cards.get(cid)
        if not c:
            continue
        m = (c.get('movie') or '').strip()
        if not m:
            continue
        if m.lower() in seen:
            continue
        seen[m.lower()] = None
        out.append(m)
        if len(out) >= 30:
            break
    return out


def _uploadvd_get_existing_characters(movie: str) -> list[str]:
    """Return distinct character names for given movie (newest first)."""
    cards = bot.data.get('cards', {}) if hasattr(bot, 'data') else {}
    seen: dict[str, None] = {}
    out: list[str] = []
    low_movie = (movie or '').strip().lower()
    for cid in reversed(list(cards.keys())):
        c = cards.get(cid)
        if not c:
            continue
        if (c.get('movie') or '').strip().lower() != low_movie:
            continue
        n = (c.get('name') or '').strip()
        if not n:
            continue
        if n.lower() in seen:
            continue
        seen[n.lower()] = None
        out.append(n)
        if len(out) >= 30:
            break
    return out


def _uploadvd_movie_keyboard(movies: list[str], page: int = 0):
    """Build paginated inline keyboard with up to 8 movies per page + 'New'."""
    if not movies:
        return None
    per_page = 8
    start = page * per_page
    chunk = movies[start:start + per_page]
    rows = []
    for m in chunk:
        # Truncate to fit button text
        label = m if len(m) <= 28 else (m[:25] + "…")
        rows.append([InlineKeyboardButton(f"🎬 {label}", callback_data=f"uvd_movie_sel|{start + chunk.index(m)}")])
    # Pagination row
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton("⬅️ Prev", callback_data=f"uvd_movie_page|{page - 1}"))
    if start + per_page < len(movies):
        nav.append(InlineKeyboardButton("➡️ Next", callback_data=f"uvd_movie_page|{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton("➕ Movie အသစ်ရိုက်ထည့်မည်", callback_data="uvd_movie_new")])
    return InlineKeyboardMarkup(rows), page, len(movies)


async def uploadvd_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/uploadvd entry — media first."""
    if not bot.is_admin(update.effective_user.id):
        await update.message.reply_text("❌ Admin/Sudo only")
        return ConversationHandler.END
    context.user_data.pop('uploadvd', None)
    await update.message.reply_text(
        "🎞 /uploadvd — Premium Upload\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "📸/🎥 အရင်ဆုံး Photo သို့မဟုတ် Video ပို့ပါ။"
    )
    return UPLOADVD_MEDIA


async def uploadvd_receive_media(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Step 1: receive photo or video."""
    sess = context.user_data.setdefault('uploadvd', {})

    if update.message.photo:
        sess['media_kind'] = 'photo'
        sess['file_id'] = update.message.photo[-1].file_id
    elif update.message.video:
        sess['media_kind'] = 'video'
        sess['file_id'] = update.message.video.file_id
        sess['video_type'] = 'video'
    elif update.message.document:
        # Accept documents as a fallback (e.g. GIFs sent as files)
        sess['media_kind'] = 'video'
        sess['file_id'] = update.message.document.file_id
        sess['video_type'] = 'document'
    else:
        await update.message.reply_text("❌ Photo သို့မဟုတ် Video ပို့ပါ။")
        return UPLOADVD_MEDIA

    sess['movies'] = _uploadvd_get_existing_movies()
    sess['movies_page'] = 0

    kb = _uploadvd_movie_keyboard(sess['movies'], sess['movies_page'])
    if kb:
        markup, page, total = kb
        await update.message.reply_text(
            f"🎬 Movie ရွေးပါ (page {page + 1}/{((total - 1) // 8) + 1}) — "
            f"မရှိရင် 'Movie အသစ်' ကိုနှိပ်ပြီး ရိုက်ထည့်ပါ:",
            reply_markup=markup,
        )
    else:
        await update.message.reply_text("🎬 Movie နာမည် ရိုက်ထည့်ပါ:")
    return UPLOADVD_MOVIE


async def uploadvd_movie_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Movie chosen from existing list → skip free-text input."""
    query = update.callback_query
    await query.answer()
    sess = context.user_data.setdefault('uploadvd', {})
    data = query.data or ''

    if data.startswith('uvd_movie_page|'):
        try:
            new_page = int(data.split('|', 1)[1])
        except Exception:
            new_page = 0
        sess['movies_page'] = new_page
        kb = _uploadvd_movie_keyboard(sess.get('movies', []), new_page)
        if kb:
            markup, page, total = kb
            try:
                await query.edit_message_reply_markup(markup)
            except Exception:
                pass
        return UPLOADVD_MOVIE

    if data == 'uvd_movie_new':
        try:
            await query.edit_message_text("🎬 Movie နာမည် ရိုက်ထည့်ပါ:")
        except Exception:
            pass
        return UPLOADVD_MOVIE

    if data.startswith('uvd_movie_sel|'):
        try:
            idx = int(data.split('|', 1)[1])
        except Exception:
            idx = 0
        movies = sess.get('movies', [])
        if 0 <= idx < len(movies):
            sess['movie'] = movies[idx]
            try:
                await query.edit_message_text(f"✅ Movie: {movies[idx]}")
            except Exception:
                pass
            return await _ask_character(query.message, context)

    return UPLOADVD_MOVIE


async def uploadvd_receive_movie(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Free-text movie entered."""
    sess = context.user_data.setdefault('uploadvd', {})
    sess['movie'] = update.message.text.strip()
    return await _ask_character(update.message, context)


async def _ask_character(target_msg, context):
    sess = context.user_data.setdefault('uploadvd', {})
    movie = sess.get('movie', '')
    chars = _uploadvd_get_existing_characters(movie)
    sess['chars'] = chars
    sess['chars_page'] = 0

    if not chars:
        await target_msg.reply_text("📝 Character နာမည် ရိုက်ထည့်ပါ:")
        return UPLOADVD_CHAR

    kb = _uploadvd_chars_keyboard(chars, 0)
    if kb:
        markup = kb
        await target_msg.reply_text(
            f"📝 Character ရွေးပါ — မရှိရင် 'Character အသစ်' ကိုနှိပ်ပြီး ရိုက်ထည့်ပါ:",
            reply_markup=markup,
        )
    else:
        await target_msg.reply_text("📝 Character နာမည် ရိုက်ထည့်ပါ:")
    return UPLOADVD_CHAR


def _uploadvd_chars_keyboard(chars: list[str], page: int = 0):
    """Build paginated inline keyboard with up to 8 chars per page + 'New'."""
    if not chars:
        return None
    per_page = 8
    start = page * per_page
    chunk = chars[start:start + per_page]
    rows = []
    for i, n in enumerate(chunk):
        label = n if len(n) <= 26 else (n[:23] + "…")
        rows.append([InlineKeyboardButton(f"📛 {label}", callback_data=f"uvd_char_sel|{start + i}")])

    nav = []
    total = len(chars)
    if page > 0:
        nav.append(InlineKeyboardButton("⬅️ Prev", callback_data=f"uvd_char_page|{page - 1}"))
    if start + per_page < total:
        nav.append(InlineKeyboardButton("➡️ Next", callback_data=f"uvd_char_page|{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton("➕ Character အသစ်ရိုက်ထည့်မည်", callback_data="uvd_char_new")])
    return InlineKeyboardMarkup(rows)


async def uploadvd_char_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Character chosen from existing list → ask for rarity."""
    query = update.callback_query
    await query.answer()
    sess = context.user_data.setdefault('uploadvd', {})
    data = query.data or ''

    if data.startswith('uvd_char_page|'):
        try:
            new_page = int(data.split('|', 1)[1])
        except Exception:
            new_page = 0
        sess['chars_page'] = new_page
        kb = _uploadvd_chars_keyboard(sess.get('chars', []), new_page)
        if kb:
            try:
                await query.edit_message_reply_markup(kb)
            except Exception:
                await query.message.reply_text("📝 Character ရွေးပါ:", reply_markup=kb)
        return UPLOADVD_CHAR

    if data == 'uvd_char_new':
        try:
            await query.edit_message_text("📝 Character နာမည် ရိုက်ထည့်ပါ:")
        except Exception:
            pass
        return UPLOADVD_CHAR

    if data.startswith('uvd_char_sel|'):
        try:
            idx = int(data.split('|', 1)[1])
        except Exception:
            idx = 0
        chars = sess.get('chars', [])
        if 0 <= idx < len(chars):
            sess['char'] = chars[idx]
            try:
                await query.edit_message_text(f"✅ Character: {chars[idx]}")
            except Exception:
                pass
            return await _ask_rarity(query.message, context)

    return UPLOADVD_CHAR


async def uploadvd_receive_char(update: Update, context: ContextTypes.DEFAULT_TYPE):
    sess = context.user_data.setdefault('uploadvd', {})
    sess['char'] = update.message.text.strip()
    return await _ask_rarity(update.message, context)


async def _ask_rarity(target_msg, context):
    """Show rarity keyboard. Built dynamically from RARITIES dict so new
    rarities get picked up automatically without touching this code."""
    keys = sorted(RARITIES.keys(), key=lambda x: int(x) if str(x).isdigit() else 0)
    rows = []
    row = []
    for rk in keys:
        row.append(InlineKeyboardButton(_rarity_display(rk), callback_data=f"uvd_rarity_{rk}"))
        if len(row) == 2:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    await target_msg.reply_text(
        "⭐ Rarity ရွေးပါ:",
        reply_markup=InlineKeyboardMarkup(rows),
    )
    return UPLOADVD_RARITY


async def uploadvd_rarity_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    sess = context.user_data.setdefault('uploadvd', {})
    data = query.data or ''
    if not data.startswith('uvd_rarity_'):
        return UPLOADVD_RARITY
    rk = data[len('uvd_rarity_'):]
    if rk not in RARITIES:
        try:
            await query.edit_message_text("❌ Rarity မမှန်ပါ။ ထပ်ရွေးပါ:")
        except Exception:
            pass
        return await _ask_rarity(query.message, context)
    sess['rarity'] = rk
    try:
        await query.edit_message_text(f"✅ Rarity: {_rarity_display(rk)}")
    except Exception:
        pass
    return await _ask_role(query.message, context)


async def _ask_role(target_msg, context):
    keys = list(ROLES.keys())
    rows = []
    row = []
    for k in keys:
        role_info = ROLES[k]
        row.append(InlineKeyboardButton(role_info.get('display', k), callback_data=f"uvd_role_{k}"))
        if len(row) == 2:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    rows.append([InlineKeyboardButton("⏭ Skip (Normal)", callback_data="uvd_role_normal")])
    await target_msg.reply_text(
        "🎭 Role ရွေးပါ (Skip နှိပ်ရင် Normal):",
        reply_markup=InlineKeyboardMarkup(rows),
    )
    return UPLOADVD_ROLE


async def uploadvd_role_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Finalize: build the card and broadcast to database channel."""
    query = update.callback_query
    await query.answer()
    sess = context.user_data.setdefault('uploadvd', {})
    data = query.data or ''
    role_key = data[len('uvd_role_'):] if data.startswith('uvd_role_') else 'normal'
    if role_key not in ROLES:
        role_key = 'normal'
    sess['role'] = role_key

    user = query.from_user
    card_id = bot.data.get('next_id', 1)
    try:
        card_id = int(card_id)
    except Exception:
        card_id = 1

    card_data = {
        'id': card_id,
        'name': sess.get('char', 'Unknown'),
        'movie': sess.get('movie', 'Unknown'),
        'owner': None,
        'owner_name': 'Available',
        'uploaded_by': user.first_name if user else 'Admin',
        'uploaded_by_id': user.id if user else None,
        'date': datetime.now().isoformat(),
        'rarity': sess.get('rarity', '1'),
        'role': role_key,
    }

    mk = sess.get('media_kind', 'photo')
    if mk == 'photo':
        card_data['image'] = sess.get('file_id')
    else:
        card_data['video'] = sess.get('file_id')
        card_data['video_type'] = sess.get('video_type', 'video')
        card_data['type'] = 'video'

    bot.data['cards'][str(card_id)] = card_data
    bot.data['next_id'] = card_id + 1
    try:
        bot.save_data()
    except Exception as e:
        logger.error(f"/uploadvd save_data failed: {e}")

    rarity_info = RARITIES.get(card_data['rarity'], RARITIES['1'])
    role_info = ROLES[role_key]

    # ── Premium Chat Caption ──
    chat_caption_lines = [
        "╔══════════════════════════╗",
        "    ✅ Upload Successful",
        "╚══════════════════════════╝",
        f"🆔 ID : {card_id}",
        f"📛 {_md_escape(card_data['name'])}",
        f"🎬 {_md_escape(card_data['movie'])}",
        f"⭐ {_md_escape(rarity_info.get('display', ''))}",
        f"🎭 {_md_escape(role_info.get('display', ''))}",
        f"📤 {_mention_md(user.id, user.first_name) if user else 'Admin'}",
    ]
    chat_caption = "\n".join(chat_caption_lines)

    try:
        await query.edit_message_text("✅ Role selected — card uploaded!")
    except Exception:
        pass

    try:
        if mk == 'photo':
            await query.message.reply_photo(
                photo=card_data['image'],
                caption=chat_caption,
                parse_mode='Markdown',
            )
        else:
            if card_data.get('video_type') == 'document':
                await query.message.reply_document(
                    document=card_data['video'],
                    caption=chat_caption,
                    parse_mode='Markdown',
                )
            else:
                await query.message.reply_video(
                    video=card_data['video'],
                    caption=chat_caption,
                    parse_mode='Markdown',
                )
    except Exception as e:
        logger.error(f"/uploadvd reply_media failed: {e}")

    # ── Send to database channel (/setdbchannel) if configured ──
    db_channel = None
    try:
        db_channel = bot.settings.get('database_channel')
    except Exception:
        db_channel = None

    if db_channel:
        try:
            db_caption_lines = [
                "╔══════════════════════════╗",
                "    📥 NEW CARD IN DB",
                "╚══════════════════════════╝",
                f"🆔 ID : {card_id}",
                f"📛 {_md_escape(card_data['name'])}",
                f"🎬 {_md_escape(card_data['movie'])}",
                f"⭐ {_md_escape(rarity_info.get('display', ''))}",
                f"🎭 {_md_escape(role_info.get('display', ''))}",
                f"📤 {_mention_md(user.id, user.first_name) if user else 'Admin'}",
            ]
            db_caption = "\n".join(db_caption_lines)

            if mk == 'photo':
                await query.bot.send_photo(
                    chat_id=db_channel,
                    photo=card_data['image'],
                    caption=db_caption,
                    parse_mode='Markdown',
                )
            else:
                if card_data.get('video_type') == 'document':
                    await query.bot.send_document(
                        chat_id=db_channel,
                        document=card_data['video'],
                        caption=db_caption,
                        parse_mode='Markdown',
                    )
                else:
                    await query.bot.send_video(
                        chat_id=db_channel,
                        video=card_data['video'],
                        caption=db_caption,
                        parse_mode='Markdown',
                    )
        except Exception as e:
            logger.error(f"/uploadvd db-channel send failed: {e}")

    # Clear session
    context.user_data.pop('uploadvd', None)
    return ConversationHandler.END


async def uploadvd_cancel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    context.user_data.pop('uploadvd', None)
    await update.message.reply_text("❌ Upload ဖျက်ပြီးပါပြီ။")
    return ConversationHandler.END


# ============================================================================
#            /see  ENHANCEMENT  —  supports alphanumeric IDs
# ============================================================================
# Behavior:
#   - /see <int>     → still works (the original numeric ID)
#   - /see <key>     → exact key match (preserves existing functionality)
#   - /see <text>    → fallback: search by case-insensitive prefix on
#                      card keys (e.g. /see A will find first key starting
#                      with 'A'). Useful for "One-of-a-Kind" cards whose
#                      IDs are labeled A, B, C, ... by the admin.
# ============================================================================

async def see_cmd_alpha(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Enhanced /see that also handles alphanumeric IDs."""
    if not context.args:
        await update.message.reply_text("📝 /see <card_id>")
        return

    raw = str(context.args[0]).strip()
    cards = bot.data.get('cards', {}) if hasattr(bot, 'data') else {}

    # ─── Singularity letter-alias lookup ───
    # /see A  (or B/C/...) → resolve to the matching singular card id
    # before falling through to numeric / substring matching.
    try:
        alias_target = _resolve_see_alias(raw)
    except Exception:
        alias_target = None
    if alias_target and alias_target in cards:
        target_id = alias_target
    elif raw in cards:
        # Exact match wins
        target_id = raw
    else:
        # Try case-insensitive prefix match on keys
        low = raw.lower()
        matches = [k for k in cards.keys() if str(k).lower().startswith(low)]
        if not matches:
            # Try a broader substring match as last resort
            matches = [k for k in cards.keys() if low in str(k).lower()]
        if not matches:
            await update.message.reply_text(f"❌ Card '{raw}' မတွေ့ပါ")
            return
        # Pick the newest (highest id when integer, else first by date)
        def _sort_key(k):
            try:
                return (0, int(k), '')
            except Exception:
                c = cards.get(k) or {}
                return (1, 0, c.get('date', ''))
        matches.sort(key=_sort_key, reverse=True)
        target_id = matches[0]

    # Pass through to original /see handler by simulating context.args
    saved_args = list(context.args)
    try:
        context.args = [target_id]
        # Prefer the legacy simple implementation so we don't depend on
        # the premium patch globals (those exist at runtime but only when
        # the patch hooked cleanly).
        await _see_cmd_legacy(update, context)
    except Exception as e:
        logger.error(f"/see alpha dispatch failed: {e}")
        # Re-show the user's original input rather than silently swallowing
        try:
            context.args = saved_args
            await _see_cmd_legacy(update, context)
        except Exception:
            await update.message.reply_text(f"❌ /see failed for '{raw}'")
    finally:
        context.args = saved_args


# ============================================================================
#                     POST-INSTALL HANDLER REGISTRATION
# ============================================================================
# We hook Application.__init__ so that whatever existing installation
# code does (the bot has multiple wrapper layers), our handlers get
# appended once. This mirrors the pattern already used elsewhere in the
# file for mnx / ov / sc / u / _ad handlers — no behavior changed for
# ANY other command.
# ============================================================================

_PATCH_INSTALLED = False


def _patch_install_handlers(application):
    """Register our new handlers on the given PTB application."""
    global _PATCH_INSTALLED
    if _PATCH_INSTALLED:
        return False
    try:
        # /rarity simple command
        application.add_handler(CommandHandler('rarity', rarity_cmd))
    except Exception as e:
        logger.error(f"[rarity-patch] /rarity handler install failed: {e}")
        return False

    try:
        # /uploadvd — fully rewritten stepwise ConversationHandler
        # We use 'photo' / 'video' / 'document' filters but also accept
        # any message at the last steps (after media is already captured).
        uploadvd_conv = ConversationHandler(
            entry_points=[CommandHandler('uploadvd', uploadvd_start)],
            states={
                UPLOADVD_MEDIA: [
                    MessageHandler(
                        filters.PHOTO | filters.VIDEO | filters.Document.ALL,
                        uploadvd_receive_media,
                    ),
                ],
                UPLOADVD_MOVIE: [
                    CallbackQueryHandler(uploadvd_movie_callback, pattern=r'^uvd_movie_'),
                    MessageHandler(filters.TEXT & ~filters.COMMAND, uploadvd_receive_movie),
                ],
                UPLOADVD_CHAR: [
                    CallbackQueryHandler(uploadvd_char_callback, pattern=r'^uvd_char_'),
                    MessageHandler(filters.TEXT & ~filters.COMMAND, uploadvd_receive_char),
                ],
                UPLOADVD_RARITY: [
                    CallbackQueryHandler(uploadvd_rarity_callback, pattern=r'^uvd_rarity_'),
                ],
                UPLOADVD_ROLE: [
                    CallbackQueryHandler(uploadvd_role_callback, pattern=r'^uvd_role_'),
                ],
            },
            fallbacks=[CommandHandler('cancel', uploadvd_cancel)],
            allow_reentry=True,
            name='patched_uploadvd_conv',
        )
        # Inject state enum attrs so the bot's other systems that read
        # OWNER_VIDEO etc. still work — we leave the originals untouched.
        try:
            globals()['UPLOADVD_MEDIA_STATE'] = UPLOADVD_MEDIA
            globals()['UPLOADVD_MOVIE_STATE'] = UPLOADVD_MOVIE
            globals()['UPLOADVD_CHAR_STATE'] = UPLOADVD_CHAR
            globals()['UPLOADVD_RARITY_STATE'] = UPLOADVD_RARITY
            globals()['UPLOADVD_ROLE_STATE'] = UPLOADVD_ROLE
        except Exception:
            pass
        application.add_handler(uploadvd_conv)
    except Exception as e:
        logger.error(f"[rarity-patch] /uploadvd install failed: {e}")
        return False

    try:
        # /see upgrade: alphanumeric-friendly override. We register a new
        # CommandHandler for 'see' that overrides the original — but
        # fallbacks to _see_cmd_legacy on exact match (so all existing
        # behavior is preserved).
        application.add_handler(CommandHandler('see', see_cmd_alpha))
    except Exception as e:
        # If a later patch installed /see, this error is harmless.
        logger.warning(f"[rarity-patch] /see install note: {e}")

    _PATCH_INSTALLED = True
    try:
        logger.info("[rarity-patch] /rarity + /uploadvd + /see installed ✅")
    except Exception:
        pass
    return True


def _patch_install_app_hook():
    """Hook into Application.__init__ so we install when the bot boots."""
    import telegram.ext as _te
    _App = _te.Application
    if getattr(_App.__init__, "_rarity_patch_wrapped", False):
        return
    _orig_init = _App.__init__

    def _patched_init(self, *args, **kwargs):
        _orig_init(self, *args, **kwargs)
        try:
            _patch_install_handlers(self)
        except Exception as e:
            logger.error(f"[rarity-patch] hook-install failed: {e}")

    _patched_init._rarity_patch_wrapped = True
    _App.__init__ = _patched_init


try:
    _patch_install_app_hook()
except Exception as _e:
    try:
        logger.error(f"[rarity-patch] top-level install failed: {_e}")
    except Exception:
        print(f"[rarity-patch] top-level install failed: {_e}")

# ═══════════════════════════════════════════════════════════════════════════
#  ██  USER REQUEST PATCH MODULE  (appended — do not modify prior code)
#  ─────────────────────────────────────────────────────────────────────────
#  Requested changes (preserved in this single append-only block):
#    1. /guess       → sudo / admin / dev only can start
#    2. /closeshop   → rarities in buy_blocked_rarities cannot be bought
#                      (covers /buy, /blackmarket, /blackmarketshop, etc.)
#    3. /see         → 🎖 One-of-a-Kind cards get a dedicated luxury UI
#    4. /lockmine /unlockmine → owner/sudo can freeze the /mines game
#    5. /wa           → completely removed from code (silent no-op)
#    6. /global3dnotice → completely removed from code (silent no-op)
#  Diamond system + all other commands are untouched.
# ═══════════════════════════════════════════════════════════════════════════

import logging as _up_logging
import asyncio as _up_asyncio

_up_log = _up_logging.getLogger("user_patch")

try:
    from telegram.ext import (
        CommandHandler as _UP_CmdH,
        CallbackQueryHandler as _UP_CbH,
        MessageHandler as _UP_MsgH,
        ApplicationHandlerStop as _UP_Stop,
        filters as _UP_filters,
        Application as _UP_App,
    )
    from telegram import Update as _UP_Update
except Exception as _e:
    _up_log.error(f"[user_patch] telegram import failed: {_e}")
    _UP_CmdH = None
    _UP_App = None
    _UP_Stop = Exception


# ═══════════════════════════════════════════════════════════════════════════
#  1. /wa  and  /global3dnotice  — SILENT REMOVAL
#     Requirement: "code မှ ဖျက်ထုတ်" — commands must not respond at all,
#     and must not trigger any further handler downstream.
# ═══════════════════════════════════════════════════════════════════════════
async def _up_dead_wa(update, context):
    """/wa is removed from the bot. Silently swallow the command."""
    try:
        # Do NOT reply — the command should behave as if it does not exist.
        raise _UP_Stop
    except _UP_Stop:
        raise
    except Exception:
        pass


async def _up_dead_global3dnotice(update, context):
    """/global3dnotice is removed from the bot. Silently swallow."""
    try:
        raise _UP_Stop
    except _UP_Stop:
        raise
    except Exception:
        pass


# ═══════════════════════════════════════════════════════════════════════════
#  2. /guess — restrict to sudo / admin / dev only
#     We wrap the existing _gc_guess_cmd (do not modify original) with a
#     permission gate registered at higher priority (group=-99).
# ═══════════════════════════════════════════════════════════════════════════
def _up_is_privileged(uid) -> bool:
    """Return True if uid is owner / sudo / admin / dev."""
    try:
        b = globals().get("bot")
        if b is None:
            return False
        u = int(uid)
        checks = [
            ("is_owner",  lambda: b.is_owner(u)),
            ("is_sudo",   lambda: b.is_sudo(u)),
            ("is_dev",    lambda: b.is_dev(u)),
            ("is_admin",  lambda: b.is_admin(u)),
        ]
        for _name, fn in checks:
            try:
                if fn():
                    return True
            except Exception:
                continue
        # Extra safety net: OWNERS constant
        try:
            OWNERS = globals().get("OWNERS", [])
            if u in OWNERS:
                return True
        except Exception:
            pass
    except Exception:
        pass
    return False


async def _up_guess_gate(update, context):
    """Priority gate for /guess — blocks non-privileged users, then defers."""
    try:
        user = update.effective_user
        if not user:
            return
        if _up_is_privileged(user.id):
            # Allow the original /guess handler to run
            return
        # Block: friendly reply + stop propagation so the game never starts
        try:
            await update.effective_message.reply_text(
                "🚫 <b>Permission Denied</b>\n\n"
                "🎯 /guess command ကို <b>Sudo / Admin / Dev</b> "
                "အသုံးပြုသူများသာ စတင်နိုင်ပါသည်။",
                parse_mode="HTML",
            )
        except Exception:
            try:
                await update.effective_message.reply_text(
                    "?? /guess ကို Sudo/Admin/Dev သာ စတင်နိုင်သည်။"
                )
            except Exception:
                pass
        raise _UP_Stop
    except _UP_Stop:
        raise
    except Exception as _e:
        _up_log.warning(f"[user_patch] guess gate error: {_e}")


# ═══════════════════════════════════════════════════════════════════════════
#  3. /closeshop enforcement — block BUY for closed rarities everywhere.
#     Original /closeshop writes to bot.settings['buy_blocked_rarities'].
#     u_buy_cmd only checks 'locked_rarities' → users could still buy
#     closed rarities. We install a priority gate that intercepts /buy
#     and /blackmarket* commands and blocks them when the target rarity
#     is in buy_blocked_rarities.
# ═══════════════════════════════════════════════════════════════════════════
def _up_get_blocked_rarities():
    try:
        b = globals().get("bot")
        if b is None:
            return set()
        raw = b.settings.get("buy_blocked_rarities", []) or []
        return set(str(r).strip() for r in raw if str(r).strip())
    except Exception:
        return set()


def _up_get_rarity_display(rk):
    try:
        RARITIES = globals().get("RARITIES", {})
        info = RARITIES.get(str(rk), {})
        return info.get("display", f"Rarity {rk}")
    except Exception:
        return f"Rarity {rk}"


async def _up_buy_gate(update, context):
    """Intercept /buy <rarity_number> — block if rarity closed."""
    try:
        msg = update.effective_message
        if not msg:
            return
        args = list(getattr(context, "args", []) or [])
        if not args:
            return  # Let the original handler show usage.
        rk = str(args[0]).strip()
        blocked = _up_get_blocked_rarities()
        if rk in blocked:
            disp = _up_get_rarity_display(rk)
            try:
                await msg.reply_text(
                    f"🔒 <b>Shop Closed</b>\n\n"
                    f"❌ {disp} rarity အား ဝယ်ယူ၍မရပါ။\n"
                    f"ℹ️ Owner/Admin မှ /closeshop ဖြင့် ပိတ်ထားပါသည်။",
                    parse_mode="HTML",
                )
            except Exception:
                try:
                    await msg.reply_text(
                        f"🔒 {disp} is currently closed for purchase."
                    )
                except Exception:
                    pass
            raise _UP_Stop
    except _UP_Stop:
        raise
    except Exception as _e:
        _up_log.warning(f"[user_patch] buy gate error: {_e}")


async def _up_blackmarket_gate(update, context):
    """Intercept /blackmarket <card_id> — block if card rarity closed."""
    try:
        msg = update.effective_message
        if not msg:
            return
        args = list(getattr(context, "args", []) or [])
        if not args:
            return
        card_id = str(args[0]).strip()
        b = globals().get("bot")
        if b is None:
            return
        cards = b.data.get("cards", {}) or {}
        card = cards.get(card_id) or cards.get(card_id.upper()) or cards.get(card_id.lower())
        if not card:
            return  # Let the original handler show "not found".
        rk = str(card.get("rarity", "1")).strip()
        blocked = _up_get_blocked_rarities()
        if rk in blocked:
            disp = _up_get_rarity_display(rk)
            try:
                await msg.reply_text(
                    f"🔒 <b>Blackmarket Closed</b>\n\n"
                    f"❌ ဤ card ၏ rarity ({disp}) ကို "
                    f"Owner/Admin မှ ပိတ်ထားပါသည်။\n"
                    f"ℹ️ Command : /closeshop",
                    parse_mode="HTML",
                )
            except Exception:
                try:
                    await msg.reply_text(
                        f"🔒 {disp} rarity is closed for purchase."
                    )
                except Exception:
                    pass
            raise _UP_Stop
    except _UP_Stop:
        raise
    except Exception as _e:
        _up_log.warning(f"[user_patch] blackmarket gate error: {_e}")


# ═══════════════════════════════════════════════════════════════════════════
#  4. /lockmine and /unlockmine — freeze / unfreeze the /mines game
#     Uses bot.settings['mines_locked'] boolean. When True, /mines is
#     blocked for ALL users (owner/sudo can still lock/unlock).
# ═══════════════════════════════════════════════════════════════════════════
def _up_is_mines_locked() -> bool:
    try:
        b = globals().get("bot")
        if b is None:
            return False
        return bool(b.settings.get("mines_locked", False))
    except Exception:
        return False


def _up_set_mines_locked(flag: bool) -> None:
    try:
        b = globals().get("bot")
        if b is None:
            return
        b.settings["mines_locked"] = bool(flag)
        try:
            b.save_settings()
        except Exception:
            try:
                b.save_data()
            except Exception:
                pass
    except Exception as _e:
        _up_log.warning(f"[user_patch] set mines_locked failed: {_e}")


def _up_is_mine_admin(uid) -> bool:
    """Only owner / sudo can toggle mines lock."""
    try:
        b = globals().get("bot")
        if b is None:
            return False
        u = int(uid)
        for fn_name in ("is_owner", "is_sudo", "is_dev"):
            try:
                fn = getattr(b, fn_name, None)
                if callable(fn) and fn(u):
                    return True
            except Exception:
                continue
        OWNERS = globals().get("OWNERS", [])
        if u in OWNERS:
            return True
    except Exception:
        pass
    return False


async def _up_lockmine_cmd(update, context):
    """/lockmine — owner/sudo only, freeze /mines for all users."""
    try:
        user = update.effective_user
        msg = update.effective_message
        if not user or not msg:
            return
        if not _up_is_mine_admin(user.id):
            try:
                await msg.reply_text(
                    "🚫 <b>Permission Denied</b>\n\n"
                    "ℹ️ Owner / Sudo များသာ သုံးနိုင်ပါသည်။",
                    parse_mode="HTML",
                )
            except Exception:
                pass
            return
        _up_set_mines_locked(True)
        try:
            await msg.reply_text(
                "🔒 <b>MINES LOCKED</b>\n\n"
                "💣 /mines command ကို user အားလုံးအတွက် ပိတ်ထားပါပြီ။\n"
                "🔓 ပြန်ဖွင့်ရန် : <code>/unlockmine</code>",
                parse_mode="HTML",
            )
        except Exception:
            try:
                await msg.reply_text("🔒 Mines locked for all users.")
            except Exception:
                pass
    except Exception as _e:
        _up_log.error(f"[user_patch] /lockmine error: {_e}")


async def _up_unlockmine_cmd(update, context):
    """/unlockmine — owner/sudo only, re-enable /mines."""
    try:
        user = update.effective_user
        msg = update.effective_message
        if not user or not msg:
            return
        if not _up_is_mine_admin(user.id):
            try:
                await msg.reply_text(
                    "🚫 <b>Permission Denied</b>\n\n"
                    "ℹ️ Owner / Sudo များသာ သုံးနိုင်ပါသည်။",
                    parse_mode="HTML",
                )
            except Exception:
                pass
            return
        _up_set_mines_locked(False)
        try:
            await msg.reply_text(
                "🔓 <b>MINES UNLOCKED</b>\n\n"
                "💣 /mines command ကို user အားလုံးအတွက် ပြန်ဖွင့်ပေးလိုက်ပါပြီ။",
                parse_mode="HTML",
            )
        except Exception:
            try:
                await msg.reply_text("🔓 Mines unlocked for all users.")
            except Exception:
                pass
    except Exception as _e:
        _up_log.error(f"[user_patch] /unlockmine error: {_e}")


async def _up_mines_gate(update, context):
    """Priority gate that blocks /mines when mines_locked=True."""
    try:
        user = update.effective_user
        msg = update.effective_message
        if not user or not msg:
            return
        # Owner/sudo bypass the lock so they can test.
        if _up_is_mine_admin(user.id):
            return
        if _up_is_mines_locked():
            try:
                await msg.reply_text(
                    "🔒 <b>Mines Locked</b>\n\n"
                    "💣 /mines game ကို ယာယီ ပိတ်ထားပါသည်။\n"
                    "🙏 နောက်မှ ပြန်ကြိုးစားပါ။",
                    parse_mode="HTML",
                )
            except Exception:
                try:
                    await msg.reply_text("🔒 Mines is currently locked.")
                except Exception:
                    pass
            raise _UP_Stop
    except _UP_Stop:
        raise
    except Exception as _e:
        _up_log.warning(f"[user_patch] mines gate error: {_e}")


# ═══════════════════════════════════════════════════════════════════════════
#  5. /see  → 🎖 One-of-a-Kind Character UI Design override
#     Wraps the existing see_cmd. When the resolved card is singular, we
#     render a luxurious 🎖 One-of-a-Kind layout ourselves and stop the
#     original handler. Non-singular cards fall through to the original
#     see_cmd untouched.
# ═══════════════════════════════════════════════════════════════════════════
def _up_md_escape(s):
    try:
        _fn = globals().get("_md_escape")
        if callable(_fn):
            return _fn(s)
    except Exception:
        pass
    if s is None:
        return ""
    s = str(s)
    for ch in ("\\", "_", "*", "[", "]", "(", ")", "~", "`", ">",
               "#", "+", "-", "=", "|", "{", "}", ".", "!"):
        s = s.replace(ch, "\\" + ch)
    return s


def _up_is_singular(card):
    try:
        fn = globals().get("is_singular_card")
        if callable(fn):
            return bool(fn(card))
    except Exception:
        pass
    try:
        if card.get("one_of_a_kind") is True:
            return True
        if str(card.get("exclusive_type", "")).lower() == "one_of_a_kind":
            return True
    except Exception:
        pass
    return False


def _up_resolve_see_alias(raw):
    try:
        fn = globals().get("_resolve_see_alias")
        if callable(fn):
            return fn(raw)
    except Exception:
        pass
    # Fallback: treat raw as literal id
    try:
        b = globals().get("bot")
        cards = b.data.get("cards", {})
        if str(raw) in cards:
            return str(raw)
        if str(raw).upper() in cards:
            return str(raw).upper()
    except Exception:
        pass
    return None


def _up_get_name(uid_str):
    try:
        fn = globals().get("get_name")
        if callable(fn):
            return fn(uid_str)
    except Exception:
        pass
    return "Unknown"


def _up_build_ook_caption(card, card_id):
    """Build luxurious 🎖 One-of-a-Kind caption (HTML-safe plain text)."""
    try:
        RARITIES = globals().get("RARITIES", {})
        rk = str(card.get("rarity", "7"))
        rinfo = RARITIES.get(rk, RARITIES.get("7", {"display": "Divine", "emoji": "⚜"}))
        rarity_display = rinfo.get("display") or rinfo.get("name") or "Divine"

        # Serial suffix (single letter A/B/C…)
        suffix = str(card.get("serial_suffix") or "").strip()
        if not suffix:
            try:
                _rsfn = globals().get("_resolve_singular_suffix")
                if callable(_rsfn):
                    suffix = str(_rsfn(card_id) or "A")
            except Exception:
                suffix = "A"
        if not suffix:
            suffix = "A"
        serial = f"{card.get('id', card_id)} {suffix}"

        char_name = card.get("name") or "-"
        movie = card.get("movie") or card.get("anime") or "-"

        # Owner block
        b = globals().get("bot")
        owners = []
        if b is not None:
            for uid_str, ucards in b.data.get("users", {}).items():
                if card_id in ucards:
                    owners.append((str(uid_str), ucards.count(card_id)))

        if not owners:
            owner_block = (
                "🔒 <i>Void · Awaiting Claim</i>\n"
                "👑 No Owner Yet\n"
                "🌎 Only One Will Ever Exist"
            )
        else:
            uid_str, cnt = owners[0]
            name = _up_get_name(uid_str)
            if not name or str(name).lower() in ("unknown", "", "none", "null"):
                owner_block = (
                    "👑 Sole Owner · <i>Hidden</i>\n"
                    "🌎 Only One Exists"
                )
            else:
                # Use HTML-safe escaping
                safe_name = (str(name)
                             .replace("&", "&amp;")
                             .replace("<", "&lt;")
                             .replace(">", "&gt;"))
                try:
                    uid_int = int(uid_str)
                    mention = f'<a href="tg://user?id={uid_int}">{safe_name}</a>'
                except Exception:
                    mention = safe_name
                owner_block = (
                    f"👑 Sole Owner · {mention}\n"
                    f"🌎 Only One Exists"
                )

        # HTML-safe character fields
        def _h(x):
            return (str(x)
                    .replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;"))

        caption = (
            "╔═══════════════════╗\n"
            "   🎖 <b>ONE-OF-A-KIND</b>\n"
            "╚═══════════════════╝\n"
            "\n"
            "✦ <b>Character Profile</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"🆔 <code>{_h(serial)}</code>\n"
            f"🎭 <b>{_h(char_name)}</b>\n"
            f"🎬 {_h(movie)}\n"
            f"💎 {_h(rarity_display)}\n"
            f"🎖 <i>One-of-a-Kind</i>\n"
            "\n"
            "✦ <b>Prestige Status</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"{owner_block}\n"
            "\n"
            "🜲 <i>A singular relic — no copy, no duplicate.</i>"
        )
        return caption
    except Exception as _e:
        _up_log.warning(f"[user_patch] ook caption build failed: {_e}")
        return f"🎖 One-of-a-Kind\n{card.get('name','')}\n{card.get('movie','')}"


async def _up_see_ook_gate(update, context):
    """Priority /see gate — render One-of-a-Kind UI ourselves for singular cards."""
    try:
        msg = update.effective_message
        if not msg:
            return
        args = list(getattr(context, "args", []) or [])
        if not args:
            return  # Let original handler show usage
        raw = str(args[0]).strip()
        cid = _up_resolve_see_alias(raw)
        if not cid:
            return  # Let original handler produce "not found"
        b = globals().get("bot")
        if b is None:
            return
        card = b.data.get("cards", {}).get(cid)
        if not card:
            return
        if not _up_is_singular(card):
            return  # Non-singular → fall through to original see_cmd

        caption = _up_build_ook_caption(card, cid)
        try:
            if card.get("type") == "video":
                if card.get("video_type") == "video":
                    await msg.reply_video(
                        video=card["video"], caption=caption, parse_mode="HTML"
                    )
                else:
                    await msg.reply_document(
                        document=card["video"], caption=caption, parse_mode="HTML"
                    )
            elif card.get("image"):
                await msg.reply_photo(
                    photo=card["image"], caption=caption, parse_mode="HTML"
                )
            else:
                await msg.reply_text(caption, parse_mode="HTML")
        except Exception as _e:
            _up_log.warning(f"[user_patch] ook send failed: {_e}")
            try:
                await msg.reply_text(caption, parse_mode="HTML")
            except Exception:
                pass
        raise _UP_Stop
    except _UP_Stop:
        raise
    except Exception as _e:
        _up_log.warning(f"[user_patch] see-ook gate error: {_e}")


# ═══════════════════════════════════════════════════════════════════════════
#  Registration — hook into Application.__init__ (append-only style,
#  mirrors the existing rarity-patch installation pattern in this file).
# ═══════════════════════════════════════════════════════════════════════════
_UP_REGISTERED_APPS = set()


def _up_register(application) -> None:
    if application is None or _UP_CmdH is None:
        return
    try:
        key = id(application)
    except Exception:
        key = None
    if key is not None and key in _UP_REGISTERED_APPS:
        return
    if key is not None:
        _UP_REGISTERED_APPS.add(key)

    try:
        # ── /wa and /global3dnotice — silent kill-switches (top priority) ──
        application.add_handler(_UP_CmdH("wa", _up_dead_wa), group=-99)
        application.add_handler(
            _UP_CmdH("global3dnotice", _up_dead_global3dnotice), group=-99
        )

        # ── /guess — sudo/admin/dev only (runs BEFORE _gc_guess_cmd) ──
        application.add_handler(_UP_CmdH("guess", _up_guess_gate), group=-99)

        # ── /buy and /blackmarket — enforce buy_blocked_rarities ──
        application.add_handler(_UP_CmdH("buy", _up_buy_gate), group=-99)
        application.add_handler(
            _UP_CmdH("blackmarket", _up_blackmarket_gate), group=-99
        )

        # ── /mines — enforce mines_locked ──
        application.add_handler(_UP_CmdH("mines", _up_mines_gate), group=-99)

        # ── /lockmine  /unlockmine ──
        application.add_handler(_UP_CmdH("lockmine",   _up_lockmine_cmd),   group=-98)
        application.add_handler(_UP_CmdH("unlockmine", _up_unlockmine_cmd), group=-98)

        # ── /see — One-of-a-Kind UI override ──
        application.add_handler(_UP_CmdH("see", _up_see_ook_gate), group=-99)

        _up_log.info("[user_patch] ✅ All requested handlers installed")
    except Exception as _e:
        _up_log.error(f"[user_patch] register failed: {_e}")


def _up_install_app_hook():
    if _UP_App is None:
        return
    orig_init = getattr(_UP_App, "__init__", None)
    if not callable(orig_init):
        return
    if getattr(orig_init, "_up_wrapped", False):
        return

    def _patched_init(self, *args, **kwargs):
        orig_init(self, *args, **kwargs)
        try:
            _up_register(self)
        except Exception as _e:
            _up_log.error(f"[user_patch] hook register failed: {_e}")

    _patched_init._up_wrapped = True  # type: ignore[attr-defined]
    _UP_App.__init__ = _patched_init


try:
    _up_install_app_hook()
    _up_log.info("[user_patch] init hook installed")
except Exception as _e:
    try:
        _up_log.error(f"[user_patch] top-level install failed: {_e}")
    except Exception:
        print(f"[user_patch] top-level install failed: {_e}")

