# ── (B) /top : Top 10 groups with most card drops, mentioned ───────────────
#   Data source: bot.data['group_drop_counters']  (already tracked by
#                                                   the original drop system)
#   Group title source: bot.data['group_titles']  (populated on every
#                                                   message we see; falls
#                                                   back to chat.title from
#                                                   effective_chat if
#                                                   available).

def _fp_get_group_titles() -> dict:
    try:
        b = globals().get("bot")
        if b is None or not hasattr(b, "data"):
            return {}
        b.data.setdefault("group_titles", {})
        return b.data["group_titles"]
    except Exception:
        return {}


def _fp_set_group_title(gid, title, username=None):
    try:
        b = globals().get("bot")
        if b is None or not hasattr(b, "data"):
            return
        b.data.setdefault("group_titles", {})
        entry = b.data["group_titles"].get(str(gid), {})
        if not isinstance(entry, dict):
            entry = {"title": str(entry)}
        if title:
            entry["title"] = str(title)
        if username:
            entry["username"] = str(username)
        b.data["group_titles"][str(gid)] = entry
    except Exception as _e:
        try:
            _fp_log.warning(f"[final_patch] set_group_title failed: {_e}")
        except Exception:
            pass


async def _fp_track_group_title(update, context):
    """Silently learn group titles/usernames from ambient traffic.
    Never blocks propagation."""
    try:
        chat = getattr(update, "effective_chat", None)
        if not chat:
            return
        if getattr(chat, "type", None) not in ("group", "supergroup"):
            return
        _fp_set_group_title(
            chat.id,
            getattr(chat, "title", None),
            getattr(chat, "username", None),
        )
    except Exception:
        # Absolutely never crash the handler pipeline
        return


def _fp_group_mention(gid: str) -> str:
    """Return an HTML mention/link for a group id.
    Rules:
      - If group has a public @username → clickable link https://t.me/<u>
      - Else → plain <b>title</b> (Telegram cannot mention private groups)
    Everything is HTML-escaped.
    """
    titles = _fp_get_group_titles()
    info = titles.get(str(gid), {}) if isinstance(titles, dict) else {}
    if not isinstance(info, dict):
        info = {"title": str(info)}

    title = info.get("title") or f"Group {gid}"
    username = info.get("username")
    safe_title = _fp_html.escape(str(title))

    if username:
        safe_user = _fp_html.escape(str(username))
        return f'<a href="https://t.me/{safe_user}">{safe_title}</a>'
    return f"<b>{safe_title}</b>"


async def _fp_top_cmd(update, context):
    """Override /top → Top 10 groups by total card drops (with mentions)."""
    try:
        b = globals().get("bot")
        if b is None or not hasattr(b, "data"):
            try:
                await update.effective_message.reply_text("⚠️ Bot data unavailable.")
            except Exception:
                pass
            raise _FP_Stop

        # Learn this chat's title too, opportunistically
        try:
            await _fp_track_group_title(update, context)
        except Exception:
            pass

        counters = {}
        try:
            raw = b.data.get("group_drop_counters", {}) or {}
            if isinstance(raw, dict):
                for gid, cnt in raw.items():
                    try:
                        counters[str(gid)] = int(cnt or 0)
                    except Exception:
                        continue
        except Exception as _e:
            _fp_log.warning(f"[final_patch] read counters failed: {_e}")
            counters = {}

        if not counters:
            try:
                await update.effective_message.reply_text(
                    "📊 <b>Top Groups</b>\n\n"
                    "❌ ကဒ်ကျခဲ့တဲ့ group data မရှိသေးပါ။",
                    parse_mode="HTML",
                )
            except Exception:
                try:
                    await update.effective_message.reply_text(
                        "No group drop data yet."
                    )
                except Exception:
                    pass
            raise _FP_Stop

        # Sort by drop count desc, take top 10
        ranked = sorted(counters.items(), key=lambda kv: kv[1], reverse=True)
        ranked = [(g, c) for g, c in ranked if c > 0][:10]

        if not ranked:
            try:
                await update.effective_message.reply_text(
                    "📊 <b>Top Groups</b>\n\n"
                    "❌ ကဒ်ကျခဲ့တဲ့ group မရှိသေးပါ။",
                    parse_mode="HTML",
                )
            except Exception:
                pass
            raise _FP_Stop

        medals = {1: "🥇", 2: "🥈", 3: "🥉"}
        lines = []
        lines.append("╔══════════════════════╗")
        lines.append("  🏆  TOP 10 GROUPS  🏆  ")
        lines.append("╚══════════════════════╝")
        lines.append("")
        for i, (gid, cnt) in enumerate(ranked, start=1):
            medal = medals.get(i, f"{i}\u2024")
            mention = _fp_group_mention(gid)
            lines.append(f"{medal} {mention}")
            lines.append(f"   🎴 {cnt} drops")
            lines.append("")
        lines.append("━━━━━━━━━━━━━━━━━━━━━━━")
        lines.append(f"📊 Total groups tracked: {len(counters)}")

        text = "\n".join(lines)

        try:
            await update.effective_message.reply_text(
                text,
                parse_mode="HTML",
                disable_web_page_preview=True,
            )
        except Exception as _e:
            _fp_log.warning(f"[final_patch] top send failed: {_e}")
            # Plain-text fallback so users never see nothing
            try:
                plain = "\n".join(
                    line.replace("<b>", "").replace("</b>", "") for line in lines
                )
                await update.effective_message.reply_text(plain)
            except Exception:
                pass

        # Stop propagation so the ORIGINAL /top (players) does NOT also fire
        raise _FP_Stop

    except _FP_Stop:
        raise
    except Exception as _e:
        try:
            _fp_log.error(f"[final_patch] /top handler error: {_e}")
        except Exception:
            pass
        try:
            await update.effective_message.reply_text(
                "⚠️ /top command မှာ error တစ်ခုတက်နေပါတယ်။"
            )
        except Exception:
            pass
        raise _FP_Stop


# ── Handler registration hook (multi-app safe) ─────────────────────────────
_FP_REGISTERED_APPS = set()

def _fp_register(application):
    if _FP_CmdH is None or application is None:
        return
    try:
        key = id(application)
    except Exception:
        key = None
    if key is not None and key in _FP_REGISTERED_APPS:
        return
    if key is not None:
        _FP_REGISTERED_APPS.add(key)

    try:
        # /top override — runs BEFORE the original /top (group=-3 in orig <
        # -100 here). Since original registers /top at default group (0),
        # -100 guarantees ours wins and stops propagation.
        application.add_handler(_FP_CmdH("top", _fp_top_cmd), group=-100)

        # Ambient title tracker — passive, never blocks.
        try:
            application.add_handler(
                _FP_MsgH(_FP_filters.ChatType.GROUPS, _fp_track_group_title),
                group=100,
            )
        except Exception as _e:
            _fp_log.warning(f"[final_patch] title tracker install failed: {_e}")

        _fp_log.info("[final_patch] ✅ /top override + title tracker registered")
    except Exception as _e:
        _fp_log.error(f"[final_patch] register failed: {_e}")


def _fp_install_app_hook():
    if _FP_App is None:
        return
    orig_init = _FP_App.__init__
    if getattr(orig_init, "_fp_wrapped", False):
        return

    def _patched_init(self, *args, **kwargs):
        orig_init(self, *args, **kwargs)
        try:
            _fp_register(self)
        except Exception as _e:
            _fp_log.error(f"[final_patch] hook register failed: {_e}")

    _patched_init._fp_wrapped = True  # type: ignore[attr-defined]
    _FP_App.__init__ = _patched_init


try:
    _fp_install_app_hook()
    _fp_log.info("[final_patch] init hook installed")
except Exception as _fp_e:
    try:
        _fp_log.error(f"[final_patch] top-level install failed: {_fp_e}")
    except Exception:
        print(f"[final_patch] top-level install failed: {_fp_e}")

# ═══════════════════════════════════════════════════════════════════════════
#  END FINAL OVERRIDE PATCH
