# ── Patch the "restart" hint text so users see /wguess instead of /guess ──
try:
    _orig_gc_guess_cmd = globals().get("_gc_guess_cmd")
    if callable(_orig_gc_guess_cmd):
        # Wrap _gc_stopg_cmd's reply text is inside its function body — leave it,
        # but override _gc_stopg_cmd's user-visible restart hint via wrapping.
        _orig_gc_stopg_cmd = globals().get("_gc_stopg_cmd")
        if callable(_orig_gc_stopg_cmd):
            async def _wg_stopg_cmd_wrapped(update, context):
                # Temporarily patch reply_text on the message object to rewrite the hint
                msg = update.effective_message
                if msg is not None and hasattr(msg, "reply_text"):
                    _orig_reply = msg.reply_text

                    async def _reply_patched(text, *a, **kw):
                        try:
                            if isinstance(text, str) and "/guess" in text and "/wguess" not in text:
                                text = text.replace("<code>/guess</code>", "<code>/wguess</code>")
                                text = text.replace("/guess", "/wguess")
                        except Exception:
                            pass
                        return await _orig_reply(text, *a, **kw)

                    try:
                        msg.reply_text = _reply_patched  # type: ignore[attr-defined]
                    except Exception:
                        pass
                    try:
                        return await _orig_gc_stopg_cmd(update, context)
                    finally:
                        try:
                            msg.reply_text = _orig_reply  # type: ignore[attr-defined]
                        except Exception:
                            pass
                else:
                    return await _orig_gc_stopg_cmd(update, context)

            globals()["_gc_stopg_cmd"] = _wg_stopg_cmd_wrapped
            _WG_LOG.info("[wguess_topgp] /stopg restart-hint patched to /wguess")
except Exception as _wg_hint_e:
    _WG_LOG.warning(f"[wguess_topgp] hint patch failed: {_wg_hint_e}")


# ═══════════════════════════════════════════════════════════════════════════
#  END USER REQUESTED PATCH
# ═══════════════════════════════════════════════════════════════════════════


# ═══════════════════════════════════════════════════════════════════════════
#  ALDv2 ADD-ON PATCH  —  (additive only: no original line above is modified)
#  ─────────────────────────────────────────────────────────────────────────
#  ဤ patch သည် မူရင်း file ကို မပျက်စေဘဲ အောက်ပါအချက်များကို ထည့်သွင်းပေးပါသည် —
#    1. /delald        — owner / sudo / dev သာ အသုံးပြုနိုင်ပြီး user အားလုံး၏
#                        diamond (kakera) အားလုံးကို ဖျက်ပစ်သည်။
#    2. Claim double-message fix — /ziceko (`/delald` မဟုတ်) claim တစ်ခါလုပ်လျှင်
#                        စာ ၂ ကြောင်း ပြန်နေသည့် ပြဿနာကို ဖြေရှင်းသည်
#                        (duplicate handler + duplicate-update guard)။
#    3. /language      — owner only သာ ပြောင်းနိုင်ပြီး ရွေးထားသော language သည်
#                        user / group အားလုံးတွင် global ဖြစ်သည်။
#    4. /font          — owner only ၊ font ၂၆ မျိုး button ပြပြီး ရွေးထားသော
#                        font သည် user / group အားလုံးတွင် global ဖြစ်သည်။
#  ═══════════════════════════════════════════════════════════════════════════
try:
    import re as _aldv2_re
    import time as _aldv2_time
    import logging as _aldv2_logging

    _aldv2_log = _aldv2_logging.getLogger("aldv2")

    # ───────────────────────────────────────────────────────────────────────
    #  A) 26 FONT STYLES
    # ───────────────────────────────────────────────────────────────────────
    _ALD_UP = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    _ALD_LOW = "abcdefghijklmnopqrstuvwxyz"
    _ALD_DIG = "0123456789"

    def _ald_seq(start, n):
        return "".join(chr(start + i) for i in range(n))

    def _ald_seq_ov(start, overrides):
        return "".join(chr(overrides.get(i, start + i)) for i in range(26))

    def _ald_mk(up_str, low_str, dig_str, mark=None):
        m = {}
        for c, g in zip(_ALD_UP, up_str):
            m[c] = (g + mark) if mark else g
        for c, g in zip(_ALD_LOW, low_str):
            m[c] = (g + mark) if mark else g
        for c, g in zip(_ALD_DIG, dig_str):
            m[c] = (g + mark) if mark else g
        return m

    def _ald_dict_up(d_low, d_up, d_dig=None):
        m = {}
        for c, v in d_up.items():
            m[str(c).upper()] = v
        for c, v in d_low.items():
            m[str(c).lower()] = v
        if d_dig:
            for c, v in d_dig.items():
                m[str(c)] = v
        return m

    # small caps (a-z / A-Z)
    _ALD_SMALLCAPS = {
        "a": "ᴀ", "b": "ʙ", "c": "ᴄ", "d": "ᴅ", "e": "ᴇ", "f": "ꜰ", "g": "ɢ",
        "h": "ʜ", "i": "ɪ", "j": "ᴊ", "k": "ᴋ", "l": "ʟ", "m": "ᴍ", "n": "ɴ",
        "o": "ᴏ", "p": "ᴘ", "q": "ǫ", "r": "ʀ", "s": "ꜱ", "t": "ᴛ", "u": "ᴜ",
        "v": "ᴠ", "w": "ᴡ", "x": "x", "y": "ʏ", "z": "ᴢ",
    }

    # superscript
    _ALD_SUP_LOW = {
        "a": "ᵃ", "b": "ᵇ", "c": "ᶜ", "d": "ᵈ", "e": "ᵉ", "f": "ᶠ", "g": "ᵍ",
        "h": "ʰ", "i": "ⁱ", "j": "ʲ", "k": "ᵏ", "l": "ˡ", "m": "ᵐ", "n": "ⁿ",
        "o": "ᵒ", "p": "ᵖ", "q": "q", "r": "ʳ", "s": "ˢ", "t": "ᵗ", "u": "ᵘ",
        "v": "ᵛ", "w": "ʷ", "x": "ˣ", "y": "ʸ", "z": "ᶻ",
    }
    _ALD_SUP_UP = {
        "a": "ᴬ", "b": "ᴮ", "c": "ᶜ", "d": "ᴰ", "e": "ᴱ", "f": "ᶠ", "g": "ᴳ",
        "h": "ᴴ", "i": "ᴵ", "j": "ᴶ", "k": "ᴷ", "l": "ᴸ", "m": "ᴹ", "n": "ᴺ",
        "o": "ᴼ", "p": "ᴾ", "q": "Q", "r": "ᴿ", "s": "ˢ", "t": "ᵀ", "u": "ᵁ",
        "v": "ⱽ", "w": "ᵂ", "x": "ˣ", "y": "ʸ", "z": "ᶻ",
    }
    _ALD_SUP_DIG = {
        "0": "⁰", "1": "¹", "2": "²", "3": "³", "4": "⁴",
        "5": "⁵", "6": "⁶", "7": "⁷", "8": "⁸", "9": "⁹",
    }

    # subscript
    _ALD_SUB_LOW = {
        "a": "ₐ", "b": "b", "c": "c", "d": "d", "e": "ₑ", "f": "f", "g": "g",
        "h": "ₕ", "i": "ᵢ", "j": "ⱼ", "k": "ₖ", "l": "ₗ", "m": "ₘ", "n": "ₙ",
        "o": "ₒ", "p": "ₚ", "q": "q", "r": "ᵣ", "s": "ₛ", "t": "ₜ", "u": "ᵤ",
        "v": "ᵥ", "w": "w", "x": "ₓ", "y": "y", "z": "z",
    }
    _ALD_SUB_DIG = {
        "0": "₀", "1": "₁", "2": "₂", "3": "₃", "4": "₄",
        "5": "₅", "6": "₆", "7": "₇", "8": "₈", "9": "₉",
    }

    _ALDV2_STYLES = [
        ("Off / Normal", None),
        ("Bold", _ald_mk(_ald_seq(0x1D400, 26), _ald_seq(0x1D41A, 26), _ald_seq(0x1D7CE, 10))),
        ("Italic", _ald_mk(_ald_seq(0x1D434, 26), _ald_seq(0x1D44E, 26), _ald_seq(0x1D7CE, 10))),
        ("Bold Italic", _ald_mk(_ald_seq(0x1D468, 26), _ald_seq(0x1D482, 26), _ald_seq(0x1D7CE, 10))),
        ("Sans", _ald_mk(_ald_seq(0x1D5A0, 26), _ald_seq(0x1D5BA, 26), _ald_seq(0x1D7E2, 10))),
        ("Sans Bold", _ald_mk(_ald_seq(0x1D5D4, 26), _ald_seq(0x1D5EE, 26), _ald_seq(0x1D7EC, 10))),
        ("Sans Italic", _ald_mk(_ald_seq(0x1D608, 26), _ald_seq(0x1D622, 26), _ald_seq(0x1D7E2, 10))),
        ("Sans Bold Italic", _ald_mk(_ald_seq(0x1D63C, 26), _ald_seq(0x1D656, 26), _ald_seq(0x1D7EC, 10))),
        ("Script", _ald_mk(
            _ald_seq_ov(0x1D49C, {1: 0x212C, 4: 0x2130, 5: 0x2131, 7: 0x210B,
                                  8: 0x2110, 11: 0x2112, 12: 0x2133, 17: 0x211B}),
            _ald_seq_ov(0x1D4B6, {4: 0x212F, 6: 0x210A, 14: 0x2134}),
            _ald_seq(0x1D7CE, 10))),
        ("Script Bold", _ald_mk(_ald_seq(0x1D4D0, 26), _ald_seq(0x1D4EA, 26), _ald_seq(0x1D7CE, 10))),
        ("Fraktur", _ald_mk(
            _ald_seq_ov(0x1D504, {2: 0x212D, 7: 0x210C, 8: 0x2111, 17: 0x211C, 25: 0x2128}),
            _ald_seq(0x1D51E, 26), _ald_seq(0x1D7CE, 10))),
        ("Fraktur Bold", _ald_mk(_ald_seq(0x1D56C, 26), _ald_seq(0x1D586, 26), _ald_seq(0x1D7CE, 10))),
        ("Double-Struck", _ald_mk(
            _ald_seq_ov(0x1D538, {2: 0x2102, 7: 0x210D, 13: 0x2115, 15: 0x2119,
                                  16: 0x211A, 17: 0x211D, 25: 0x2124}),
            _ald_seq(0x1D552, 26), _ald_seq(0x1D7D8, 10))),
        ("Monospace", _ald_mk(_ald_seq(0x1D670, 26), _ald_seq(0x1D68A, 26), _ald_seq(0x1D7F6, 10))),
        ("Fullwidth", _ald_mk(_ald_seq(0xFF21, 26), _ald_seq(0xFF41, 26), _ald_seq(0xFF10, 10))),
        ("Small Caps", _ald_dict_up(_ALD_SMALLCAPS, _ALD_SMALLCAPS,
                                     {d: d for d in _ALD_DIG})),
        ("Superscript", _ald_dict_up(_ALD_SUP_LOW, _ALD_SUP_UP, _ALD_SUP_DIG)),
        ("Subscript", _ald_dict_up(_ALD_SUB_LOW, _ALD_SUB_LOW, _ALD_SUB_DIG)),
        ("Circled", _ald_mk(_ald_seq(0x24B6, 26), _ald_seq(0x24D0, 26), "\u24EA" + _ald_seq(0x2460, 9))),
        ("Parenthesized", _ald_mk(_ald_seq(0x249C, 26), _ald_seq(0x249C, 26), _ALD_DIG)),
        ("Underline", _ald_mk(_ALD_UP, _ALD_LOW, _ALD_DIG, mark="\u0332")),
        ("Double Underline", _ald_mk(_ALD_UP, _ALD_LOW, _ALD_DIG, mark="\u0333")),
        ("Strike", _ald_mk(_ALD_UP, _ALD_LOW, _ALD_DIG, mark="\u0336")),
        ("Slash", _ald_mk(_ALD_UP, _ALD_LOW, _ALD_DIG, mark="\u0338")),
        ("Overline", _ald_mk(_ALD_UP, _ALD_LOW, _ALD_DIG, mark="\u0305")),
        ("Tilde", _ald_mk(_ALD_UP, _ALD_LOW, _ALD_DIG, mark="\u0334")),
    ]
    # 26 styles total (index 0 = off, 1..25 = stylised)
    _ALDV2_FONT_COUNT = len(_ALDV2_STYLES)

    # HTML tags / entities / code blocks / URLs are NEVER re-styled, so
    # parse_mode=HTML|Markdown အလုပ်လုပ်နေမှုကို မထိခိုက်စေပါ။
    _ALDV2_PROTECT = _aldv2_re.compile(
        r"(?is)(<pre>.*?</pre>|<code>.*?</code>|<[^<>\n]{1,300}>"
        r"|https?://\S+|tg://\S+|&(?:[A-Za-z]{1,10}|#\d{1,7});)"
    )

    def _aldv2_apply_font(text):
        """Apply the owner-selected GLOBAL font to outgoing text (ASCII only)."""
        try:
            if not isinstance(text, str) or not text:
                return text
            idx = int(bot.settings.get("global_font", 0) or 0)
            if idx <= 0 or idx >= _ALDV2_FONT_COUNT:
                return text
            mapper = _ALDV2_STYLES[idx][1]
            if not mapper:
                return text
            out = []
            for part in _ALDV2_PROTECT.split(text):
                if not part:
                    continue
                if _ALDV2_PROTECT.fullmatch(part):
                    out.append(part)
                else:
                    out.append("".join(mapper.get(ch, ch) for ch in part))
            return "".join(out)
        except Exception:
            return text

    def _aldv2_preview(mapper, sample="Abc1"):
        try:
            if not mapper:
                return sample
            return "".join(mapper.get(c, c) for c in sample)
        except Exception:
            return sample

    # ── wire the font into EVERY outgoing text/caption (after translation) ──
    _aldv2_orig_translate_for_chat = globals().get("_translate_text_for_chat")

    if callable(_aldv2_orig_translate_for_chat) and not getattr(
            _aldv2_orig_translate_for_chat, "_aldv2_wrapped", False):
        async def _aldv2_translate_for_chat(text, chat_id):
            try:
                res = await _aldv2_orig_translate_for_chat(text, chat_id)
            except Exception:
                res = text
            return _aldv2_apply_font(res)

        _aldv2_translate_for_chat._aldv2_wrapped = True  # type: ignore[attr-defined]
        globals()["_translate_text_for_chat"] = _aldv2_translate_for_chat

    # ───────────────────────────────────────────────────────────────────────
    #  B) GLOBAL LANGUAGE  (owner picks once → applies to all users/groups)
    # ───────────────────────────────────────────────────────────────────────
    _aldv2_orig_safe_lang = globals().get("_safe_chat_language")
    _aldv2_orig_set_lang = globals().get("_set_chat_language")

    def _aldv2_safe_chat_language(chat_id=None):
        try:
            g = bot.settings.get("global_language")
            if g:
                norm = globals().get("_normalize_lang_code")
                return norm(g) if callable(norm) else str(g)
        except Exception:
            pass
        try:
            if callable(_aldv2_orig_safe_lang):
                return _aldv2_orig_safe_lang(chat_id)
        except Exception:
            pass
        return globals().get("DEFAULT_BOT_LANGUAGE", "my")

    def _aldv2_set_chat_language(chat_id, user_id, lang_code):
        chosen = lang_code
        try:
            if callable(_aldv2_orig_set_lang):
                chosen = _aldv2_orig_set_lang(chat_id, user_id, lang_code)
        except Exception as e:
            _aldv2_log.warning(f"[aldv2] set language failed: {e}")
        try:
            bot.settings["global_language"] = chosen
            bot.save_settings()
        except Exception as e:
            _aldv2_log.warning(f"[aldv2] save global language failed: {e}")
        return chosen

    globals()["_safe_chat_language"] = _aldv2_safe_chat_language
    globals()["_set_chat_language"] = _aldv2_set_chat_language

    # ───────────────────────────────────────────────────────────────────────
    #  C) PERMISSION HELPERS
    # ───────────────────────────────────────────────────────────────────────
    def _aldv2_is_owner(uid):
        try:
            return uid is not None and bool(bot.is_owner(int(uid)))
        except Exception:
            return False

    def _aldv2_is_staff(uid):
        """owner / sudo / dev  (as requested for /delald)"""
        try:
            u = int(uid)
            return bool(bot.is_owner(u) or bot.is_sudo(u) or bot.is_dev(u))
        except Exception:
            return False

    async def _aldv2_deny(update, text, alert=False):
        try:
            msg = getattr(update, "effective_message", None)
            q = getattr(update, "callback_query", None)
            if q is not None:
                await q.answer(text[:190], show_alert=alert)
                return
            if msg is not None:
                await msg.reply_text(text)
        except Exception:
            pass

    # ───────────────────────────────────────────────────────────────────────
    #  D) /font  — owner only, 26 style buttons, GLOBAL
    # ───────────────────────────────────────────────────────────────────────
    def _aldv2_font_keyboard(current=0):
        rows, row = [], []
        for i, (name, mapper) in enumerate(_ALDV2_STYLES):
            mark = "✅ " if i == int(current or 0) else ""
            label = f"{mark}{i}. {name} {_aldv2_preview(mapper)}".strip()
            row.append(InlineKeyboardButton(label[:60], callback_data=f"font_set_{i}"))
            if len(row) == 2:
                rows.append(row)
                row = []
        if row:
            rows.append(row)
        return InlineKeyboardMarkup(rows)

    def _aldv2_font_menu_text(current=0):
        idx = int(current or 0)
        name = _ALDV2_STYLES[idx][0] if 0 <= idx < _ALDV2_FONT_COUNT else _ALDV2_STYLES[0][0]
        return (
            "🔤 Bot Font Menu (GLOBAL)\n"
            "━━━━━━━━━━━━━━━━━━━━━━━━\n"
            f"လက်ရှိ Font : {name}   (index {idx} / {_ALDV2_FONT_COUNT - 1})\n"
            "အောက်က button ကိုနှိပ်ပြီး font ကို ရွေးပါ။\n"
            "Owner ရွေးထားသော font သည် user / group အားလုံးတွင် တစ်ပြေးညီ ပြောင်းလဲပါမည်။\n"
            "• 0 = Off (မူရင်း font)\n"
            "• 1 ~ 25 = stylised font 25 မျိုး"
        )

    async def _aldv2_font_cmd(update, context):
        try:
            uid = getattr(getattr(update, "effective_user", None), "id", None)
            if not _aldv2_is_owner(uid):
                await _aldv2_deny(update, "❌ Owner only — /font ကို owner သာ သုံးနိုင်ပါသည်။")
                return
            current = int(bot.settings.get("global_font", 0) or 0)
            await update.effective_message.reply_text(
                _aldv2_font_menu_text(current),
                reply_markup=_aldv2_font_keyboard(current),
            )
        except Exception as e:
            _aldv2_log.error(f"[aldv2] /font error: {e}")

    async def _aldv2_font_callback(update, context):
        try:
            q = getattr(update, "callback_query", None)
            if q is None:
                return
            uid = getattr(q.from_user, "id", None)
            if not _aldv2_is_owner(uid):
                await q.answer("❌ Owner only", show_alert=True)
                return
            data = q.data or ""
            try:
                idx = int(data.replace("font_set_", "", 1))
            except Exception:
                await q.answer("❌ Invalid font")
                return
            if idx < 0 or idx >= _ALDV2_FONT_COUNT:
                await q.answer("❌ Invalid font")
                return
            await q.answer(f"✅ Font : {_ALDV2_STYLES[idx][0]}")
            try:
                bot.settings["global_font"] = idx
                bot.save_settings()
            except Exception as e:
                _aldv2_log.warning(f"[aldv2] save global font failed: {e}")
            txt = _aldv2_font_menu_text(idx)
            try:
                await q.edit_message_text(txt, reply_markup=_aldv2_font_keyboard(idx))
            except Exception:
                try:
                    await q.message.reply_text(txt, reply_markup=_aldv2_font_keyboard(idx))
                except Exception:
                    pass
        except Exception as e:
            _aldv2_log.error(f"[aldv2] font callback error: {e}")

    # ───────────────────────────────────────────────────────────────────────
    #  E) /language — OWNER ONLY  (global switch)
    # ───────────────────────────────────────────────────────────────────────
    _aldv2_orig_language_cmd = globals().get("language_cmd")
    _aldv2_orig_language_cb = globals().get("language_callback")

    async def _aldv2_language_cmd(update, context):
        try:
            uid = getattr(getattr(update, "effective_user", None), "id", None)
            if not _aldv2_is_owner(uid):
                await _aldv2_deny(update, "❌ Owner only — /language ကို owner သာ ပြောင်းနိုင်ပါသည်။")
                return
            if callable(_aldv2_orig_language_cmd):
                await _aldv2_orig_language_cmd(update, context)
        except Exception as e:
            _aldv2_log.error(f"[aldv2] /language error: {e}")

    async def _aldv2_language_callback(update, context):
        try:
            q = getattr(update, "callback_query", None)
            if q is None:
                return
            uid = getattr(q.from_user, "id", None)
            if not _aldv2_is_owner(uid):
                await q.answer("❌ Owner only", show_alert=True)
                return
            if callable(_aldv2_orig_language_cb):
                await _aldv2_orig_language_cb(update, context)
        except Exception as e:
            _aldv2_log.error(f"[aldv2] language callback error: {e}")

    # ───────────────────────────────────────────────────────────────────────
    #  F) /delald — owner / sudo / dev  → wipe EVERY user's diamonds
    # ───────────────────────────────────────────────────────────────────────
    def _aldv2_wipe_diamonds():
        users, total = 0, 0
        try:
            profiles = bot.data.get("user_profiles", {}) or {}
            for uid, prof in list(profiles.items()):
                if not isinstance(prof, dict):
                    continue
                try:
                    val = int(prof.get("kakera", 0) or 0)
                except Exception:
                    val = 0
                if val > 0:
                    users += 1
                    total += val
                if "kakera" in prof or val:
                    prof["kakera"] = 0
        except Exception as e:
            _aldv2_log.error(f"[aldv2] wipe profiles error: {e}")

        # guess-game mirror store (same wallet, mirrored copy)
        try:
            cache = globals().get("_GC_CACHE")
            if isinstance(cache, dict):
                for _uid, st in (cache.get("stats", {}) or {}).items():
                    if isinstance(st, dict) and "kakera" in st:
                        st["kakera"] = 0
                saver = globals().get("_gc_save")
                if callable(saver):
                    saver()
        except Exception as e:
            _aldv2_log.warning(f"[aldv2] wipe guess stats error: {e}")

        try:
            bot.save_data()
        except Exception as e:
            _aldv2_log.error(f"[aldv2] save after wipe error: {e}")
        return users, total

    async def _aldv2_delald_cmd(update, context):
        try:
            uid = getattr(getattr(update, "effective_user", None), "id", None)
            if not _aldv2_is_staff(uid):
                await _aldv2_deny(
                    update,
                    "❌ Owner / Sudo / Dev only — /delald ကို owner, sudo, dev သာ သုံးနိုင်ပါသည်။",
                )
                return
            users, total = _aldv2_wipe_diamonds()
            await update.effective_message.reply_text(
                "💎 <b>ALL DIAMONDS WIPED</b>\n"
                "━━━━━━━━━━━━━━━━━━━━━━━━\n"
                f"👥 Users affected : <b>{users}</b>\n"
                f"💎 Diamonds removed : <b>{int(total):,}</b>\n"
                "✅ User အားလုံး၏ diamond balance ကို 0 သို့ ပြောင်းပြီးပါပြီ။\n"
                "ℹ️ /diamonds ဖြင့် စစ်ဆေးနိုင်ပါသည်။",
                parse_mode="HTML",
            )
        except Exception as e:
            _aldv2_log.error(f"[aldv2] /delald error: {e}")
            try:
                await update.effective_message.reply_text("⚠️ /delald အလုပ်လုပ်ရာတွင် error ဖြစ်ခဲ့သည်။")
            except Exception:
                pass

    # ───────────────────────────────────────────────────────────────────────
    #  G) CLAIM DOUBLE-MESSAGE FIX  (one /ziceko → exactly one reply)
    # ───────────────────────────────────────────────────────────────────────
    _aldv2_claim_impl = globals().get("_ufp_ziceko_cmd") or globals().get("ziceko_cmd")
    _ALDV2_CLAIM_SEEN = {}

    async def _aldv2_ziceko_claim(update, context):
        """Guarded claim: the same Telegram message can never be handled twice."""
        try:
            key = None
            try:
                key = (int(update.effective_chat.id), int(update.message.message_id))
            except Exception:
                key = None
            if key is not None:
                now = _aldv2_time.time()
                if len(_ALDV2_CLAIM_SEEN) > 500:
                    for k in [k for k, t in _ALDV2_CLAIM_SEEN.items() if now - t > 180]:
                        _ALDV2_CLAIM_SEEN.pop(k, None)
                if now - _ALDV2_CLAIM_SEEN.get(key, 0) < 120:
                    _aldv2_log.info("[aldv2] duplicate claim invocation suppressed")
                    return
                _ALDV2_CLAIM_SEEN[key] = now
            if callable(_aldv2_claim_impl):
                return await _aldv2_claim_impl(update, context)
        except Exception as e:
            _aldv2_log.error(f"[aldv2] claim wrapper error: {e}")
            try:
                await update.effective_message.reply_text("⚠️ Claim လုပ်ရာတွင် error ဖြစ်ခဲ့သည်။")
            except Exception:
                pass

    # ───────────────────────────────────────────────────────────────────────
    #  H) HANDLER HOOKS
    #     • retarget existing handlers (ziceko / language / lang-callback)
    #     • de-duplicate the double-registered /ziceko handler
    #     • register the brand new /font + /delald commands
    # ───────────────────────────────────────────────────────────────────────
    try:
        from telegram.ext import Application as _ALDV2_App
        from telegram.ext import CommandHandler as _ALDV2_CmdH
        from telegram.ext import CallbackQueryHandler as _ALDV2_CbH
        _ALDV2_TG_OK = True
    except Exception as _aldv2_tg_e:  # pragma: no cover
        _ALDV2_TG_OK = False
        _aldv2_log.error(f"[aldv2] telegram import failed: {_aldv2_tg_e}")

    _ALDV2_SEEN_CMDS = {}
    _ALDV2_REGISTERED_APPS = set()

    def _aldv2_retarget(app, handler):
        """Swap callbacks of existing handlers with our guarded versions."""
        names = set()
        try:
            cmds = getattr(handler, "commands", None)
            if cmds:
                if isinstance(cmds, (set, frozenset, list, tuple)):
                    names = {str(c).lower().lstrip("/") for c in cmds}
                else:
                    names = {str(cmds).lower().lstrip("/")}
        except Exception:
            names = set()

        if "delald" in names:
            handler.callback = _aldv2_delald_cmd
            return handler
        if "font" in names:
            handler.callback = _aldv2_font_cmd
            return handler
        if "language" in names:
            handler.callback = _aldv2_language_cmd
            return handler
        if "ziceko" in names:
            key = id(app)
            seen = _ALDV2_SEEN_CMDS.setdefault(key, set())
            if "ziceko" in seen:
                _aldv2_log.info("[aldv2] duplicate /ziceko handler not added (double-message fix)")
                return None
            seen.add("ziceko")
            handler.callback = _aldv2_ziceko_claim
            return handler

        pat = getattr(handler, "pattern", None)
        if pat is not None:
            try:
                pstr = getattr(pat, "pattern", None) or str(pat)
            except Exception:
                pstr = ""
            if "lang_set_" in pstr:
                handler.callback = _aldv2_language_callback
            elif "font_set_" in pstr:
                handler.callback = _aldv2_font_callback
        return handler

    def _aldv2_register_new(app):
        try:
            app.add_handler(_ALDV2_CmdH("font", _aldv2_font_cmd), group=-95)
            app.add_handler(_ALDV2_CmdH("delald", _aldv2_delald_cmd), group=-95)
            app.add_handler(_ALDV2_CbH(_aldv2_font_callback, pattern=r"^font_set_"), group=-95)
            _aldv2_log.info("[aldv2] ✅ /font (26 fonts) + /delald registered")
        except Exception as e:
            _aldv2_log.error(f"[aldv2] register new commands failed: {e}")

    if _ALDV2_TG_OK:
        _aldv2_orig_add_handler = _ALDV2_App.add_handler

        if not getattr(_aldv2_orig_add_handler, "_aldv2_wrapped", False):
            def _aldv2_add_handler(self, handler, *args, **kwargs):
                try:
                    handler = _aldv2_retarget(self, handler)
                    if handler is None:
                        return None
                except Exception as e:
                    _aldv2_log.warning(f"[aldv2] retarget failed: {e}")
                return _aldv2_orig_add_handler(self, handler, *args, **kwargs)

            _aldv2_add_handler._aldv2_wrapped = True  # type: ignore[attr-defined]
            _ALDV2_App.add_handler = _aldv2_add_handler

        _aldv2_orig_app_init = _ALDV2_App.__init__

        if not getattr(_aldv2_orig_app_init, "_aldv2_wrapped", False):
            def _aldv2_patched_init(self, *a, **kw):
                _aldv2_orig_app_init(self, *a, **kw)
                try:
                    key = id(self)
                    if key not in _ALDV2_REGISTERED_APPS:
                        _ALDV2_REGISTERED_APPS.add(key)
                        _aldv2_register_new(self)
                except Exception as e:
                    _aldv2_log.error(f"[aldv2] init-hook register failed: {e}")

            _aldv2_patched_init._aldv2_wrapped = True  # type: ignore[attr-defined]
            _ALDV2_App.__init__ = _aldv2_patched_init

    # ───────────────────────────────────────────────────────────────────────
    #  I) self-check (never fatal)
    # ───────────────────────────────────────────────────────────────────────
    try:
        _bad = [n for n, m in _ALDV2_STYLES[1:]
                if not m or len(m) < 62 or len(set(m.values())) != len(m.values()) - 36]
        _aldv2_log.info(
            f"[aldv2] font styles: {_ALDV2_FONT_COUNT} (off + {_ALDV2_FONT_COUNT - 1} styles); "
            f"questionable maps: {_bad}"
        )
        _aldv2_log.info("[aldv2] ✅ /delald + claim fix + owner-only /language + /font installed")
    except Exception as _aldv2_e:
        print(f"[aldv2] self-check note: {_aldv2_e}")

except Exception as _aldv2_top_e:  # pragma: no cover
    try:
        print(f"[aldv2] top-level install failed: {_aldv2_top_e}")
    except Exception:
        pass



# ==================== DROP SNIPED — STARTUP CLEANUP ====================
# After a (re)start: clear persisted active drops so a stale drop can never
# be claimed, and reset the in-memory last-claimed cache.
try:
    if hasattr(bot, 'data') and isinstance(bot.data, dict):
        if bot.data.get('dropped_cards'):
            bot.data['dropped_cards'] = {}
            try:
                bot.save_data()
            except Exception:
                pass
    _last_claimed_drops.clear()
    print("[drop-sniped] startup cleanup done ✅")
except Exception as _sniped_boot_e:
    print(f"[drop-sniped] startup cleanup note: {_sniped_boot_e}")



# ═══════════════════════════════════════════════════════════════════════════
# 🎨 ZICEKO CHARACTER FRAME SYSTEM
# /see + /fav media gets the user's equipped frame (photo cards only).
# No equipped frame => original media is sent unchanged.
# Frames are manually sold for real money by the owner; owner grants them.
# ═══════════════════════════════════════════════════════════════════════════

_ZF_LOG = logging.getLogger("ziceko_frame_system")
_ZF_DIR = os.path.join(os.path.dirname(DATA_FILE) or ".", "frames")  # legacy only; new frames use Telegram file_id
_ZF_DATA_KEY = "character_frames"
_ZF_USER_KEY = "user_frames"
_ZF_EQUIPPED_KEY = "equipped_frame"
_ZF_REGISTERED_APPS = set()
_ZF_PENDING = {}


def _zf_ensure_data():
    try:
        bot.data.setdefault(_ZF_DATA_KEY, {})
        bot.data.setdefault(_ZF_USER_KEY, {})
        bot.data.setdefault(_ZF_EQUIPPED_KEY, {})
        # Frames are stored by Telegram file_id, so they survive bot/server
        # restarts and are included automatically in JSON backup/restore.
        # Legacy local-path frames are still readable for backward compatibility.
    except Exception as e:
        _ZF_LOG.warning("frame data init failed: %s", e)


def _zf_is_owner(uid):
    try:
        return bool(bot.is_real_owner(int(uid)))
    except Exception:
        try:
            return int(uid) in OWNERS
        except Exception:
            return False


def _zf_user_frames(uid):
    _zf_ensure_data()
    store = bot.data[_ZF_USER_KEY]
    value = store.setdefault(str(uid), [])
    if not isinstance(value, list):
        value = []
        store[str(uid)] = value
    return value


def _zf_equipped(uid):
    _zf_ensure_data()
    fid = bot.data[_ZF_EQUIPPED_KEY].get(str(uid))
    return str(fid) if fid else None


def _zf_frame(fid):
    _zf_ensure_data()
    item = bot.data[_ZF_DATA_KEY].get(str(fid))
    return item if isinstance(item, dict) else None


def _zf_safe_filename(fid):
    return re.sub(r"[^A-Za-z0-9_.-]+", "_", str(fid))


async def _zf_download_source(source, bot_api):
    """Return BytesIO for a Telegram file_id, URL, or local frame path."""
    if not source:
        return None
    try:
        out = io.BytesIO()
        source = str(source)
        if source.startswith("http://") or source.startswith("https://"):
            raw = await asyncio.to_thread(lambda: urlopen(Request(source, headers={"User-Agent": "Mozilla/5.0"}), timeout=15).read())
            out.write(raw)
            out.seek(0)
            return out
        if os.path.isfile(source):
            with open(source, "rb") as f:
                out.write(f.read())
            out.seek(0)
            return out
        # Telegram file_id
        tg_file = await bot_api.get_file(source)
        await tg_file.download_to_memory(out)
        out.seek(0)
        return out
    except Exception as e:
        _ZF_LOG.warning("frame/media download failed: %s", e)
        return None


async def _zf_apply_frame(photo_source, frame_id, bot_api):
    """Overlay a transparent PNG frame over a card photo.
    Returns BytesIO or None. Failure never blocks the original card image.
    """
    if not photo_source or not frame_id:
        return None
    frame = _zf_frame(frame_id)
    if not frame:
        return None
    try:
        from PIL import Image
    except Exception as e:
        _ZF_LOG.warning("Pillow is not installed; frame skipped: %s", e)
        return None

    media_buf = await _zf_download_source(photo_source, bot_api)
    frame_source = frame.get("file_id") or frame.get("image") or frame.get("path")
    frame_buf = None
    if frame.get("b64"):
        # Built-in frames ship inside the code as base64 PNG artwork.
        try:
            frame_buf = io.BytesIO(base64.b64decode(frame["b64"]))
            frame_buf.seek(0)
        except Exception as _b64_err:
            _ZF_LOG.warning("frame base64 decode failed: %s", _b64_err)
            frame_buf = None
    if frame_buf is None:
        frame_buf = await _zf_download_source(frame_source, bot_api)
    if not media_buf or not frame_buf:
        return None

    try:
        media = Image.open(media_buf).convert("RGBA")
        overlay = Image.open(frame_buf).convert("RGBA")
        overlay = overlay.resize(media.size, Image.Resampling.LANCZOS)

        # Frame files are border artwork.  Some Telegram-uploaded frame PNGs
        # contain a black/solid center instead of real transparency.  Remove
        # only the connected dark center area so the CHARACTER PHOTO remains
        # fully visible underneath the frame.  The gold/colored border and
        # decorations stay untouched.
        try:
            # Work on a COPY first. Only swap it in when the cleanup removed
            # a sane amount of pixels — this prevents a dark-bordered frame
            # from getting its artwork eaten by the flood fill, while wider
            # thresholds make sure a solid black center is fully removed.
            w, h = overlay.size
            cleaned = overlay.copy()
            px = cleaned.load()
            seeds = []
            for sx, sy in ((w // 2, h // 2), (w // 2, h // 3), (w // 3, h // 2),
                           (2 * w // 3, h // 2), (w // 2, 2 * h // 3)):
                if 0 <= sx < w and 0 <= sy < h:
                    r, g, b, a = px[sx, sy]
                    if a > 0 and max(r, g, b) < 110:
                        seeds.append((sx, sy))
            if seeds:
                from collections import deque
                q = deque(seeds)
                seen = set(seeds)
                cleared = 0
                while q:
                    x, y = q.popleft()
                    r, g, b, a = px[x, y]
                    if a > 0 and max(r, g, b) < 135:
                        px[x, y] = (r, g, b, 0)
                        cleared += 1
                        for nx, ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in seen:
                                nr, ng, nb, na = px[nx, ny]
                                if na > 0 and max(nr, ng, nb) < 135:
                                    seen.add((nx, ny))
                                    q.append((nx, ny))
                if 0 < cleared <= int(w * h * 0.65):
                    overlay = cleaned
                elif cleared > int(w * h * 0.65):
                    _ZF_LOG.warning(
                        "frame cleanup would clear %.1f%% of the image — skipped to protect frame art",
                        100.0 * cleared / float(w * h))
        except Exception as _frame_transparency_error:
            _ZF_LOG.warning("frame center transparency cleanup failed: %s", _frame_transparency_error)

        media.alpha_composite(overlay)
        out = io.BytesIO()
        out.name = "ziceko_framed.png"
        media.save(out, format="PNG", optimize=True)
        out.seek(0)
        return out
    except Exception as e:
        _ZF_LOG.warning("frame compositing failed: %s", e)
        return None


async def _zf_send_photo_or_original(message, photo_source, caption, user_id, bot_api, parse_mode="Markdown"):
    """Send framed photo when equipped; otherwise send the exact original photo."""
    fid = _zf_equipped(user_id)
    framed = await _zf_apply_frame(photo_source, fid, bot_api) if fid else None
    try:
        if framed:
            await message.reply_photo(photo=framed, caption=caption, parse_mode=parse_mode)
            return True
        await message.reply_photo(photo=photo_source, caption=caption, parse_mode=parse_mode)
        return True
    except Exception as e:
        _ZF_LOG.warning("framed/original photo send failed: %s", e)
        try:
            if framed:
                framed.seek(0)
                await message.reply_photo(photo=framed, caption=caption, parse_mode=parse_mode)
                return True
        except Exception:
            pass
        return False


