_ZF_BUILTIN_FRAMES = {
    "azure_dragon": {
        "name": "🐉 Azure Dragon Frame",
        "tier": "Legendary",
        "rarity": "Legendary",
        "theme": "မိုးပြာရောင် နဂါး Frame",
        "description": "မိုးပြာရောင် နဂါး Border • Lightning Effect • Blue Crystal Gems • Premium Legendary Frame",
        "price_mmk": 0,
    },
}


def _zf_register_builtin_frames():
    """Create/refresh every built-in frame inside bot.data (idempotent)."""
    try:
        _zf_ensure_data()
        store = bot.data[_ZF_DATA_KEY]
        changed = False
        for fid, meta in _ZF_BUILTIN_FRAMES.items():
            entry = store.get(fid)
            if not isinstance(entry, dict):
                entry = {}
            for key, value in meta.items():
                entry.setdefault(key, value)
            entry.setdefault("builtin", True)
            entry.setdefault("created_at", datetime.now().isoformat())
            if fid == "azure_dragon":
                entry["b64"] = _ZF_AZURE_DRAGON_B64
            if store.get(fid) != entry:
                store[fid] = entry
                changed = True
        if changed:
            bot.save_data()
            _ZF_LOG.info("[frame] built-in frames ready: %s",
                         ", ".join(sorted(_ZF_BUILTIN_FRAMES)))
    except Exception as e:
        _ZF_LOG.warning("built-in frame registration failed: %s", e)


async def _zf_get_card_image(photo_source, user_id, bot_api):
    """Return the framed card image (BytesIO) when the viewer has a frame.

    Returns None when no frame is equipped or compositing fails, so the
    caller can always fall back to the untouched original character image.
    """
    try:
        frame_id = _zf_equipped(user_id)
    except Exception:
        return None
    if not frame_id or not photo_source:
        return None
    return await _zf_apply_frame(photo_source, frame_id, bot_api)


async def _zf_see_router(update, context):
    """Priority /see handler — actually draws the equipped frame on the card.

    Only photo cards are composited (video cards keep their original media),
    and only when the viewer has a frame equipped.  In every other case this
    handler stays completely silent, so the normal /see implementation keeps
    working exactly as before.
    """
    try:
        msg = update.effective_message
        user = update.effective_user
        args = list(getattr(context, "args", []) or [])
        if not msg or not user or not args:
            return
        raw = str(args[0]).strip()
        try:
            card_id = _resolve_see_alias(raw)
        except Exception:
            card_id = None
        if not card_id:
            return
        card = bot.data.get('cards', {}).get(str(card_id))
        if not card:
            return
        if is_singular_card(card):
            return                          # One-of-a-Kind UI is handled elsewhere
        if str(card.get('type') or '') == 'video':
            return                          # video cards are sent unchanged
        image = card.get('image')
        if not image:
            return
        uid = str(user.id)
        if not _zf_equipped(uid):
            return                          # no frame → normal /see
        framed = await _zf_get_card_image(image, uid, context.bot)
        if not framed:
            return                          # compositing failed → normal /see
        try:
            caption = _zf_see_caption(card, str(card_id), user.id)
        except Exception:
            caption = None
        try:
            await msg.reply_photo(
                photo=framed,
                caption=caption,
                parse_mode='HTML',
                reply_markup=_zf_see_keyboard(str(card_id), user.id),
            )
        except Exception as e:
            _ZF_LOG.warning("framed /see send failed: %s", e)
            return
        raise ApplicationHandlerStop
    except ApplicationHandlerStop:
        raise
    except Exception as e:
        _ZF_LOG.warning("frame /see router error: %s", e)


async def _zf_frameinfo_cmd(update, context):
    """Show details of one frame."""
    _zf_ensure_data()
    if not context.args:
        await update.effective_message.reply_text("Usage: /frameinfo <frame_id>")
        return
    fid = str(context.args[0]).strip()
    item = _zf_frame(fid)
    if not item:
        await update.effective_message.reply_text("❌ Frame မတွေ့ပါ။ /frames နဲ့ ID စစ်ပါ။")
        return
    uid = str(update.effective_user.id)
    owned_now = fid in [str(x) for x in _zf_user_frames(uid)]
    lines = [
        "╭━━━〔 🖼 FRAME INFO 〕━━━╮",
        f"🆔 <code>{_html_escape(fid)}</code>",
        f"🏷 <b>{_html_escape(str(item.get('name') or fid))}</b>",
        f"✨ {_html_escape(str(item.get('rarity') or item.get('tier') or 'Legendary'))}",
        f"💰 {int(item.get('price_mmk') or 0):,} MMK",
    ]
    if item.get('theme'):
        lines.append(f"🎨 {_html_escape(str(item.get('theme')))}")
    if item.get('description'):
        lines.append(f"📝 {_html_escape(str(item.get('description')))}")
    lines += [
        "╰━━━━━━━━━━━━━━━━━━━━╯",
        "",
        f"👤 ပိုင်ဆိုင်မှု  : {'✅ ပိုင်ပြီး' if owned_now else '🔒 မပိုင်သေးပါ'}",
        f"⚡ တပ်ဆင်မှု    : {'🟢 Equipped' if _zf_equipped(uid) == fid else '⚪ Not equipped'}",
        "",
        "💡 /equipframe <id> နဲ့ တပ်နိုင်ပါတယ်။",
    ]
    await update.effective_message.reply_text("\n".join(lines), parse_mode="HTML")


async def _zf_equipframe_cmd(update, context):
    """Equip one of the user's own frames."""
    _zf_ensure_data()
    uid = str(update.effective_user.id)
    if not context.args:
        await update.effective_message.reply_text("Usage: /equipframe <frame_id>")
        return
    fid = str(context.args[0]).strip()
    item = _zf_frame(fid)
    if not item:
        await update.effective_message.reply_text("❌ Frame မတွေ့ပါ။ /frames နဲ့ ID စစ်ပါ။")
        return
    if fid not in [str(x) for x in _zf_user_frames(uid)]:
        await update.effective_message.reply_text(
            "❌ ဒီ Frame ကို မပိုင်သေးပါ။\n/myframes မှာ စစ်ပါ။")
        return
    bot.data[_ZF_EQUIPPED_KEY][uid] = fid
    bot.save_data()
    await update.effective_message.reply_text(
        f"✅ <b>Frame Equipped!</b>\n"
        f"🖼 {_html_escape(str(item.get('name') or fid))}\n\n"
        f"အခု /see · /fav · /harem · /profile အားလုံးမှာ Frame တပ်ပြီး ပေါ်ပါမယ်။",
        parse_mode="HTML")


async def _zf_removeframe_cmd(update, context):
    """Remove the equipped frame (user self-service)."""
    _zf_ensure_data()
    uid = str(update.effective_user.id)
    if not _zf_equipped(uid):
        await update.effective_message.reply_text(
            "⚪ Frame မတပ်ထားသေးပါ။ /myframes မှာ ရွေးနိုင်ပါတယ်။")
        return
    bot.data[_ZF_EQUIPPED_KEY].pop(uid, None)
    bot.save_data()
    await update.effective_message.reply_text(
        "✅ Frame ဖြုတ်ပြီးပါပြီ။\n/see မှာ Original Card Image ပြန်ပေါ်ပါမယ်။")


async def _zf_fav_router(update, context):
    """Priority /fav handler.

    Bare /fav   → framed favorite preview.
    /fav <id>   → the normal confirmation flow runs, then handling STOPS so the
                  regular /fav handler cannot run a second time (that duplicate
                  run was what made the Favorite UI appear twice).
    """
    if context.args:
        # Debounce: if this user already has an unanswered Favorite-Confirm
        # in this chat (sent within the last 15s), do NOT send a second one —
        # that duplicate send was what made the /fav UI appear twice.
        _msg = update.effective_message
        _usr = update.effective_user
        if _msg is not None and _usr is not None:
            try:
                _now = time.time()
                for _mid, _p in list(PENDING_FAVS.items()):
                    if (_p.get('user_id') == _usr.id
                            and _p.get('chat_id') == _msg.chat_id
                            and _now - float(_p.get('created_at') or 0) < 15):
                        await _msg.reply_text(
                            "⏳ Favorite Confirm တစ်ခု ဖွင့်ထားပြီးသားပါ။\n"
                            "အပေါ်က message မှာ ✅ Yes / ❌ No အရင်နှိပ်ပါ။")
                        raise ApplicationHandlerStop
            except ApplicationHandlerStop:
                raise
            except Exception as _deb_e:
                _ZF_LOG.warning("fav debounce check failed: %s", _deb_e)
        try:
            await fav_cmd(update, context)
        except Exception as e:
            _ZF_LOG.warning("delegated /fav failed: %s", e)
        raise ApplicationHandlerStop
    user = update.effective_user
    msg = update.effective_message
    if not user or not msg:
        return
    uid = str(user.id)
    fav_id = _get_user_fav_id(uid)
    if not fav_id:
        await msg.reply_text("💖 Favorite မသတ်မှတ်ထားသေးပါ။\n\n/fav <card_id> နဲ့ သတ်မှတ်နိုင်ပါတယ်။")
        raise ApplicationHandlerStop
    owned = bot.data.get('users', {}).get(uid, [])
    if str(fav_id) not in [str(x) for x in owned]:
        _set_user_fav_id(uid, None)
        bot.save_data()
        await msg.reply_text("⚠️ Favorite card ကို မပိုင်တော့လို့ auto-remove လုပ်လိုက်ပါတယ်။")
        raise ApplicationHandlerStop
    entry = _get_user_fav_entry(uid) or {}
    card = bot.data.get('cards', {}).get(str(fav_id), {})
    image = entry.get('image') or card.get('image')
    caption = (
        f"╭━━━〔 💖 FAVORITE CARD 〕━━━╮\n"
        f"👤 Player : {_mention_md(user.id, user.first_name)}\n"
        f"🎬 Anime  : {_md_escape(card.get('movie',''))}\n"
        f"🆔 ID     : {card.get('id', fav_id)}\n"
        f"🌟 Name   : {_md_escape(card.get('name',''))}\n"
        f"⚜ Rarity : {RARITIES.get(str(card.get('rarity','1')), RARITIES['1'])['display']}\n"
        f"🎭 Role   : {get_role_info(card)['display']}\n"
        f"╰━━━━━━━━━━━━━━━━━━━━╯"
    )
    if image:
        ok = await _zf_send_photo_or_original(msg, image, caption, user.id, context.bot, 'HTML')
        if not ok:
            await msg.reply_text(caption, parse_mode='HTML')
    elif entry.get('video') or card.get('video'):
        video = entry.get('video') or card.get('video')
        vtype = entry.get('video_type') or card.get('video_type')
        if vtype == 'video':
            await msg.reply_video(video=video, caption=caption, parse_mode='Markdown')
        else:
            await msg.reply_document(document=video, caption=caption, parse_mode='Markdown')
    else:
        await msg.reply_text(caption, parse_mode='Markdown')
    raise ApplicationHandlerStop


def _zf_register(application, force=False):
    """Register EVERY Frame command + callback DIRECTLY on the Application.

    Root cause of "/frames does nothing": the old code relied on
    ``Application.__init__`` being monkey-patched by ``_zf_install_hook()``.
    That hook was installed at import time, but the Application is only built
    inside ``main()`` -> ``Application.builder().build()`` (a classmethod that
    bypasses ``__init__`` in python-telegram-bot v20+), and several other
    modules in this file wrap ``Application.__init__`` / ``add_handler`` too.
    When any wrapper short-circuits, the patch never fires, so the Frame
    handlers were simply never added.  The old body also wrapped the whole
    registration in ``except Exception: pass``-style logging, so the failure
    was invisible.  We now call this explicitly from main() and surface the
    FULL traceback.
    """
    if application is None:
        _ZF_LOG.error("[FRAME] _zf_register() called with application=None")
        return
    if getattr(application, "_zf_handlers_installed", False) and not force:
        _ZF_LOG.info("[FRAME] Frame handlers already installed — skip")
        return

    _ZF_LOG.info("[FRAME] Registering Frame handlers")

    _specs = [
        ("see",           _zf_see_router,      -200),
        ("fav",           _zf_fav_router,      -200),
        ("frames",        _zf_frames_cmd,      -199),
        ("myframes",      _zf_myframes_cmd,    -199),
        ("addframe",      _zf_addframe_cmd,    -199),
        ("giveframe",     _zf_giveframe_cmd,   -199),
        ("takeframe",     _zf_takeframe_cmd,   -199),
        ("setframeprice", _zf_setprice_cmd,    -199),
        ("frameinfo",     _zf_frameinfo_cmd,   -199),
        ("equipframe",    _zf_equipframe_cmd,  -199),
        ("removeframe",   _zf_removeframe_cmd, -199),
    ]

    installed = []
    try:
        for name, callback, grp in _specs:
            application.add_handler(CommandHandler(name, callback), group=grp)
            installed.append(name)
            _ZF_LOG.info("[FRAME] Registered /%s", name)

        application.add_handler(
            CallbackQueryHandler(_zf_callback, pattern=r"^zframe\|"), group=-200)
        _ZF_LOG.info("[FRAME] Registered callback ^zframe" + chr(92) + "|")

        application.add_handler(
            CallbackQueryHandler(_zf_see_callback, pattern=r"^zsee\|"), group=-200)
        _ZF_LOG.info("[FRAME] Registered callback ^zsee" + chr(92) + "|")
    except Exception:
        try:
            import traceback as _zfb_tb
            _detail = _zfb_tb.format_exc()
        except Exception:
            _detail = "(traceback unavailable)"
        _ZF_LOG.error(
            "[FRAME] REGISTRATION FAILED after installing %s:\n%s",
            installed or "nothing", _detail)
        return

    application._zf_handlers_installed = True
    _ZF_REGISTERED_APPS.add(id(application))
    _ZF_LOG.info("[FRAME] Frame registration complete (%d commands + 2 callbacks)",
                 len(installed))


def _zf_install_hook():
    try:
        app_cls = Application
        orig = app_cls.__init__
        if getattr(orig, '_ziceko_frame_wrapped', False):
            return
        def _patched(self, *args, **kwargs):
            orig(self, *args, **kwargs)
            try:
                _zf_register(self)
            except Exception as e:
                _ZF_LOG.error("[frame] init registration failed: %s", e)
        _patched._ziceko_frame_wrapped = True
        app_cls.__init__ = _patched
    except Exception as e:
        _ZF_LOG.error("[frame] hook install failed: %s", e)


# NOTE: the Application.__init__ monkey-patch hook is NO LONGER installed.
# Frame handlers are registered explicitly from main() right after build().
try:
    _ZF_LOG.info("[FRAME] Initializing Frame System")
    _zf_ensure_data()
    _zf_register_builtin_frames()
    _ZF_LOG.info("[FRAME] Built-in frames ready")
except Exception as _zf_boot_e:
    _ZF_LOG.error("[FRAME] startup init failed: %s", _zf_boot_e, exc_info=True)


if __name__ == '__main__':
    main()
